INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'en', 'rNxC16mlO60', '{"videoId":"rNxC16mlO60","youtubeId":"rNxC16mlO60","title":"The Secrets and Science of Mental Toughness | Joe Risser MD, MPH | TEDxSanDiego","channel":"TEDx Talks","categoryId":"science","difficulty":"beginner","duration":524,"thumbnail":"https://i.ytimg.com/vi/rNxC16mlO60/sddefault.jpg","speechRateWpm":105,"addedAt":"2026-02-16","segmentCount":99,"vocabularyCount":0,"grammarPatternCount":15,"descriptionKo":"정신적 강인함의 비밀 — 스포츠 의학 전문의가 알려주는 멘탈 관리법"}'::jsonb, '{"videoId":"rNxC16mlO60","segments":[{"index":0,"start":0.0,"end":8.1,"textEn":"Reviewer. peree de","words":[{"word":"Reviewer","start":0.0,"end":0.94},{"word":".peree","start":0.94,"end":7.62},{"word":"de","start":7.62,"end":8.1}],"textKo":"리뷰어. 페레 데","listenDifficulty":1},{"index":1,"start":21.1,"end":24.74,"textEn":"You''re about to hold a plank. Just 60 seconds.","words":[{"word":"You''re","start":21.1,"end":21.82},{"word":"about","start":21.82,"end":22.2},{"word":"to","start":22.2,"end":22.4},{"word":"hold","start":22.4,"end":22.58},{"word":"a","start":22.58,"end":22.72},{"word":"plank.","start":22.72,"end":23.08},{"word":"Just","start":23.4,"end":23.9},{"word":"60","start":23.9,"end":24.32},{"word":"seconds.","start":24.32,"end":24.74}],"textKo":"플랭크를 유지할 준비가 되셨어요. 60초만에요","listenDifficulty":3},{"index":2,"start":25.12,"end":28.3,"textEn":"You know it''s coming, that tension in your core,","words":[{"word":"You","start":25.12,"end":25.64},{"word":"know","start":25.64,"end":25.88},{"word":"it''s","start":25.88,"end":26.18},{"word":"coming,","start":26.18,"end":26.54},{"word":"that","start":26.8,"end":27.2},{"word":"tension","start":27.2,"end":27.6},{"word":"in","start":27.6,"end":27.8},{"word":"your","start":27.8,"end":27.94},{"word":"core,","start":27.94,"end":28.3}],"textKo":"그 감각이 올 거예요, 몸 중심의 긴장감,","listenDifficulty":3},{"index":3,"start":28.3,"end":32.22,"textEn":"The burn in your arms, the mental countdown ticking away.","words":[{"word":"the","start":28.3,"end":28.94},{"word":"burn","start":28.94,"end":29.26},{"word":"in","start":29.26,"end":29.44},{"word":"your","start":29.44,"end":29.6},{"word":"arms,","start":29.6,"end":30.08},{"word":"the","start":30.3,"end":30.68},{"word":"mental","start":30.68,"end":30.92},{"word":"countdown","start":30.92,"end":31.44},{"word":"ticking","start":31.44,"end":31.84},{"word":"away.","start":31.84,"end":32.22}],"textKo":"팔의 피로감, 정신적인 카운트다운이 흐르고 있어요.","listenDifficulty":2},{"index":4,"start":32.5,"end":35.36,"textEn":"You''re already thinking, I can''t do this.","words":[{"word":"You''re","start":32.5,"end":33.06},{"word":"already","start":33.06,"end":33.3},{"word":"thinking,","start":33.3,"end":33.72},{"word":"I","start":34.0,"end":34.44},{"word":"can''t","start":34.44,"end":34.8},{"word":"do","start":34.8,"end":35.0},{"word":"this.","start":35.0,"end":35.36}],"textKo":"이미 생각하고 계세요, 나는 이걸 못 하겠어요.","listenDifficulty":2},{"index":5,"start":35.54,"end":37.7,"textEn":"I''m going to collapse at 30 seconds.","words":[{"word":"I''m","start":35.54,"end":36.1},{"word":"going","start":36.1,"end":36.18},{"word":"to","start":36.18,"end":36.28},{"word":"collapse","start":36.28,"end":36.74},{"word":"at","start":36.74,"end":36.98},{"word":"30","start":36.98,"end":37.22},{"word":"seconds.","start":37.22,"end":37.7}],"textKo":"30초만에 쓰러질 거예요.","listenDifficulty":3},{"index":6,"start":38.64,"end":41.2,"textEn":"Now, imagine you push through that feeling.","words":[{"word":"Now,","start":38.64,"end":39.28},{"word":"imagine","start":39.46,"end":39.88},{"word":"you","start":39.88,"end":40.08},{"word":"push","start":40.08,"end":40.42},{"word":"through","start":40.42,"end":40.6},{"word":"that","start":40.6,"end":40.8},{"word":"feeling.","start":40.8,"end":41.2}],"textKo":"지금, 그 감각을 이겨내는 걸 상상해보세요.","listenDifficulty":3},{"index":7,"start":41.44,"end":44.22,"textEn":"You hold on. Maybe your body starts shaking.","words":[{"word":"You","start":41.44,"end":41.86},{"word":"hold","start":41.86,"end":42.16},{"word":"on.","start":42.16,"end":42.48},{"word":"Maybe","start":42.7,"end":43.08},{"word":"your","start":43.08,"end":43.24},{"word":"body","start":43.24,"end":43.5},{"word":"starts","start":43.5,"end":43.74},{"word":"shaking.","start":43.74,"end":44.22}],"textKo":"지금 유지하세요. 몸이 흔들리기 시작할 수도 있어요.","listenDifficulty":3},{"index":8,"start":44.56,"end":46.7,"textEn":"Your mind is screaming for you to stop.","words":[{"word":"Your","start":44.56,"end":44.84},{"word":"mind","start":44.84,"end":45.1},{"word":"is","start":45.1,"end":45.28},{"word":"screaming","start":45.28,"end":45.88},{"word":"for","start":45.88,"end":46.14},{"word":"you","start":46.14,"end":46.24},{"word":"to","start":46.24,"end":46.36},{"word":"stop.","start":46.36,"end":46.7}],"textKo":"마음이 울부짖고 있어요, 지금 멈추라고.","listenDifficulty":3},{"index":9,"start":47.06,"end":50.08,"textEn":"You tell yourself, just one more second,","words":[{"word":"You","start":47.06,"end":47.44},{"word":"tell","start":47.44,"end":47.7},{"word":"yourself,","start":47.7,"end":48.2},{"word":"just","start":48.8,"end":49.0},{"word":"one","start":49.0,"end":49.42},{"word":"more","start":49.42,"end":49.64},{"word":"second,","start":49.64,"end":50.08}],"textKo":"자신에게 말해보세요, 하나 더.","listenDifficulty":2},{"index":10,"start":50.3,"end":54.88,"textEn":"And you make it to 60. You''re feeling pretty proud of yourself.","words":[{"word":"and","start":50.3,"end":50.94},{"word":"you","start":50.94,"end":51.1},{"word":"make","start":51.1,"end":51.44},{"word":"it","start":51.44,"end":51.58},{"word":"to","start":51.58,"end":51.74},{"word":"60.","start":51.74,"end":52.1},{"word":"You''re","start":52.5,"end":53.1},{"word":"feeling","start":53.1,"end":53.42},{"word":"pretty","start":53.42,"end":53.76},{"word":"proud","start":53.76,"end":54.26},{"word":"of","start":54.26,"end":54.46},{"word":"yourself.","start":54.46,"end":54.88}],"textKo":"60초까지 성공하셨죠? 자신감을 느끼고 계시죠.","listenDifficulty":2},{"index":11,"start":63.1,"end":66.58,"textEn":"But then, you don''t stop at 60 seconds.","words":[{"word":"But","start":63.1,"end":63.82},{"word":"then,","start":63.82,"end":64.22},{"word":"you","start":64.54,"end":65.06},{"word":"don''t","start":65.06,"end":65.28},{"word":"stop","start":65.28,"end":65.56},{"word":"at","start":65.56,"end":65.7},{"word":"60","start":65.7,"end":66.06},{"word":"seconds.","start":66.06,"end":66.58}],"textKo":"하지만 그 다음엔 60초만에 멈추지 않죠.","listenDifficulty":2},{"index":12,"start":66.78,"end":72.4,"textEn":"You don''t stop at five minutes. You keep going for an hour, for two hours,","words":[{"word":"You","start":66.78,"end":67.08},{"word":"don''t","start":67.08,"end":67.28},{"word":"stop","start":67.28,"end":67.52},{"word":"at","start":67.52,"end":67.68},{"word":"five","start":67.68,"end":67.9},{"word":"minutes.","start":67.9,"end":68.26},{"word":"You","start":68.42,"end":68.6},{"word":"keep","start":68.6,"end":68.82},{"word":"going","start":68.82,"end":69.2},{"word":"for","start":69.2,"end":69.9},{"word":"an","start":69.9,"end":70.14},{"word":"hour,","start":70.14,"end":70.6},{"word":"for","start":71.1,"end":71.46},{"word":"two","start":71.46,"end":71.78},{"word":"hours,","start":71.78,"end":72.4}],"textKo":"5분만에 멈추지 않고, 1시간, 2시간을 계속 진행합니다.","listenDifficulty":3},{"index":13,"start":72.6,"end":75.82,"textEn":"And then 10 hours.","words":[{"word":"and","start":72.6,"end":73.42},{"word":"then","start":73.42,"end":73.78},{"word":"10","start":73.78,"end":74.92},{"word":"hours.","start":74.92,"end":75.82}],"textKo":"그리고 10시간이 지나면.","listenDifficulty":1},{"index":14,"start":76.72,"end":81.0,"textEn":"Yep, 10 hours, 10 minutes, and 10 seconds.","words":[{"word":"Yep,","start":76.72,"end":77.18},{"word":"10","start":77.68,"end":77.8},{"word":"hours,","start":77.8,"end":78.2},{"word":"10","start":78.58,"end":79.02},{"word":"minutes,","start":79.02,"end":79.44},{"word":"and","start":79.84,"end":80.22},{"word":"10","start":80.22,"end":80.48},{"word":"seconds.","start":80.48,"end":81.0}],"textKo":"정말로 10시간, 10분, 10초가 지나면.","listenDifficulty":1},{"index":15,"start":81.0,"end":85.98,"textEn":"That''s exactly what George Hood did when he set the world record","words":[{"word":"That''s","start":81.0,"end":82.06},{"word":"exactly","start":82.06,"end":82.54},{"word":"what","start":82.54,"end":82.84},{"word":"George","start":82.84,"end":83.16},{"word":"Hood","start":83.16,"end":83.54},{"word":"did","start":83.54,"end":83.84},{"word":"when","start":83.84,"end":84.58},{"word":"he","start":84.58,"end":84.78},{"word":"set","start":84.78,"end":85.02},{"word":"the","start":85.02,"end":85.2},{"word":"world","start":85.2,"end":85.46},{"word":"record","start":85.46,"end":85.98}],"textKo":"그가 세계 기록을 세울 때 그게 바로 했던 일입니다.","listenDifficulty":2},{"index":16,"start":85.98,"end":88.72,"textEn":"For the longest plank in history,","words":[{"word":"for","start":85.98,"end":86.78},{"word":"the","start":86.78,"end":86.94},{"word":"longest","start":86.94,"end":87.34},{"word":"plank","start":87.34,"end":87.76},{"word":"in","start":87.76,"end":88.18},{"word":"history,","start":88.18,"end":88.72}],"textKo":"역사상 가장 긴 플랭크 기록을","listenDifficulty":2},{"index":17,"start":89.88,"end":93.0,"textEn":"A feat that most people would not believe possible.","words":[{"word":"a","start":89.88,"end":90.56},{"word":"feat","start":90.56,"end":90.76},{"word":"that","start":90.76,"end":90.98},{"word":"most","start":90.98,"end":91.28},{"word":"people","start":91.28,"end":91.6},{"word":"would","start":91.6,"end":92.04},{"word":"not","start":92.04,"end":92.18},{"word":"believe","start":92.18,"end":92.46},{"word":"possible.","start":92.46,"end":93.0}],"textKo":"대부분의 사람들이 믿기 어려운 기록입니다.","listenDifficulty":3},{"index":18,"start":94.54,"end":96.9,"textEn":"I met George eight years ago,","words":[{"word":"I","start":94.54,"end":95.22},{"word":"met","start":95.22,"end":95.46},{"word":"George","start":95.46,"end":95.84},{"word":"eight","start":95.84,"end":96.28},{"word":"years","start":96.28,"end":96.56},{"word":"ago,","start":96.56,"end":96.9}],"textKo":"8년 전에 조지와 만났습니다.","listenDifficulty":2},{"index":19,"start":97.12,"end":100.24,"textEn":"When he set the record, at that time, five hours.","words":[{"word":"when","start":97.12,"end":97.58},{"word":"he","start":97.58,"end":97.74},{"word":"set","start":97.74,"end":97.96},{"word":"the","start":97.96,"end":98.1},{"word":"record,","start":98.1,"end":98.46},{"word":"at","start":98.66,"end":99.16},{"word":"that","start":99.16,"end":99.34},{"word":"time,","start":99.34,"end":99.58},{"word":"five","start":99.58,"end":99.86},{"word":"hours.","start":99.86,"end":100.24}],"textKo":"그 당시에는 5시간이었죠.","listenDifficulty":3},{"index":20,"start":100.6,"end":106.98,"textEn":"And I''ll tell you this, he just looked like the definition of mental toughness.","words":[{"word":"And","start":100.6,"end":101.04},{"word":"I''ll","start":101.04,"end":101.18},{"word":"tell","start":101.18,"end":101.3},{"word":"you","start":101.3,"end":101.46},{"word":"this,","start":101.46,"end":101.86},{"word":"he","start":102.14,"end":102.8},{"word":"just","start":102.8,"end":103.2},{"word":"looked","start":103.2,"end":103.92},{"word":"like","start":103.92,"end":104.36},{"word":"the","start":104.36,"end":104.54},{"word":"definition","start":104.54,"end":105.22},{"word":"of","start":105.22,"end":106.1},{"word":"mental","start":106.1,"end":106.34},{"word":"toughness.","start":106.34,"end":106.98}],"textKo":"말씀드리자면, 그는 단순히 정신력의 정의처럼 보였어요.","listenDifficulty":2},{"index":21,"start":106.98,"end":110.4,"textEn":"The focus in his eyes was razor sharp,","words":[{"word":"The","start":106.98,"end":107.86},{"word":"focus","start":107.86,"end":108.28},{"word":"in","start":108.28,"end":108.5},{"word":"his","start":108.5,"end":108.66},{"word":"eyes","start":108.66,"end":109.02},{"word":"was","start":109.02,"end":109.44},{"word":"razor","start":109.44,"end":109.96},{"word":"sharp,","start":109.96,"end":110.4}],"textKo":"눈빛은 날카로운데요,","listenDifficulty":2},{"index":22,"start":110.6,"end":112.62,"textEn":"And he was drenched in sweat.","words":[{"word":"and","start":110.6,"end":111.04},{"word":"he","start":111.04,"end":111.22},{"word":"was","start":111.22,"end":111.46},{"word":"drenched","start":111.46,"end":112.0},{"word":"in","start":112.0,"end":112.22},{"word":"sweat.","start":112.22,"end":112.62}],"textKo":"그는 땀을 흘리고 있었습니다.","listenDifficulty":3},{"index":23,"start":112.9,"end":117.92,"textEn":"He was hurting. You could see it in his face, feel it in his body.","words":[{"word":"He","start":112.9,"end":113.26},{"word":"was","start":113.26,"end":113.52},{"word":"hurting.","start":113.52,"end":113.88},{"word":"You","start":114.3,"end":114.74},{"word":"could","start":114.74,"end":114.96},{"word":"see","start":114.96,"end":115.22},{"word":"it","start":115.22,"end":115.36},{"word":"in","start":115.36,"end":115.46},{"word":"his","start":115.46,"end":115.64},{"word":"face,","start":115.64,"end":116.12},{"word":"feel","start":116.34,"end":117.04},{"word":"it","start":117.04,"end":117.2},{"word":"in","start":117.2,"end":117.3},{"word":"his","start":117.3,"end":117.5},{"word":"body.","start":117.5,"end":117.92}],"textKo":"그는 아팠어요. 얼굴에서 보이고, 몸에서 느껴졌습니다.","listenDifficulty":3},{"index":24,"start":118.48,"end":123.28,"textEn":"But he didn''t stop. Later, I asked him,","words":[{"word":"But","start":118.48,"end":119.18},{"word":"he","start":119.18,"end":119.38},{"word":"didn''t","start":119.38,"end":119.86},{"word":"stop.","start":119.86,"end":120.44},{"word":"Later,","start":121.7,"end":122.3},{"word":"I","start":122.48,"end":122.68},{"word":"asked","start":122.68,"end":123.02},{"word":"him,","start":123.02,"end":123.28}],"textKo":"하지만 멈추지 않았어요. 이후로 제가 그에게 물었죠,","listenDifficulty":1},{"index":25,"start":123.64,"end":127.96,"textEn":"George, how do you do it? His answer surprised me.","words":[{"word":"George,","start":123.64,"end":124.16},{"word":"how","start":124.46,"end":124.92},{"word":"do","start":124.92,"end":125.06},{"word":"you","start":125.06,"end":125.14},{"word":"do","start":125.14,"end":125.3},{"word":"it?","start":125.3,"end":125.54},{"word":"His","start":126.16,"end":126.86},{"word":"answer","start":126.86,"end":127.18},{"word":"surprised","start":127.18,"end":127.68},{"word":"me.","start":127.68,"end":127.96}],"textKo":"조지, 어떻게 그런가요? 그의 대답은 나를 놀라게 했어요.","listenDifficulty":2},{"index":26,"start":128.42,"end":130.94,"textEn":"The plank is 90% mental.","words":[{"word":"The","start":128.42,"end":128.96},{"word":"plank","start":128.96,"end":129.32},{"word":"is","start":129.32,"end":129.76},{"word":"90","start":129.76,"end":130.2},{"word":"%","start":130.2,"end":130.54},{"word":"mental.","start":130.54,"end":130.94}],"textKo":"플랭크는 90% 정신적입니다.","listenDifficulty":3},{"index":27,"start":131.68,"end":134.3,"textEn":"George told me he kept his mind busy,","words":[{"word":"George","start":131.68,"end":132.26},{"word":"told","start":132.26,"end":132.58},{"word":"me","start":132.58,"end":132.82},{"word":"he","start":132.82,"end":133.14},{"word":"kept","start":133.14,"end":133.4},{"word":"his","start":133.4,"end":133.62},{"word":"mind","start":133.62,"end":133.88},{"word":"busy,","start":133.88,"end":134.3}],"textKo":"그는 두뇌를 바쁘게 했어요,","listenDifficulty":3},{"index":28,"start":134.3,"end":139.0,"textEn":"Distracting himself by focusing on the conversations in the room,","words":[{"word":"distracting","start":134.3,"end":135.46},{"word":"himself","start":135.46,"end":135.88},{"word":"by","start":135.88,"end":136.26},{"word":"focusing","start":136.26,"end":136.84},{"word":"on","start":136.84,"end":137.6},{"word":"the","start":137.6,"end":137.72},{"word":"conversations","start":137.72,"end":138.34},{"word":"in","start":138.34,"end":138.6},{"word":"the","start":138.6,"end":138.68},{"word":"room,","start":138.68,"end":139.0}],"textKo":"방안의 대화에 집중하면서 자신을 방해했어요,","listenDifficulty":2},{"index":29,"start":139.28,"end":142.02,"textEn":"Drawing energy from the people around him.","words":[{"word":"drawing","start":139.28,"end":139.84},{"word":"energy","start":139.84,"end":140.46},{"word":"from","start":140.46,"end":140.9},{"word":"the","start":140.9,"end":141.04},{"word":"people","start":141.04,"end":141.34},{"word":"around","start":141.34,"end":141.64},{"word":"him.","start":141.64,"end":142.02}],"textKo":"주변의 사람들로부터 에너지를 뽑아내는 거죠.","listenDifficulty":2},{"index":30,"start":142.42,"end":145.46,"textEn":"But there was something deeper happening here.","words":[{"word":"But","start":142.42,"end":143.0},{"word":"there","start":143.0,"end":143.16},{"word":"was","start":143.16,"end":143.36},{"word":"something","start":143.36,"end":143.8},{"word":"deeper","start":143.8,"end":144.36},{"word":"happening","start":144.36,"end":145.06},{"word":"here.","start":145.06,"end":145.46}],"textKo":"하지만 여기서는 더 깊은 일이 일어나고 있었어요.","listenDifficulty":2},{"index":31,"start":146.06,"end":149.88,"textEn":"We often think of grit as that mental toughness","words":[{"word":"We","start":146.06,"end":146.86},{"word":"often","start":146.86,"end":147.2},{"word":"think","start":147.2,"end":147.5},{"word":"of","start":147.5,"end":147.68},{"word":"grit","start":147.68,"end":148.12},{"word":"as","start":148.12,"end":148.68},{"word":"that","start":148.68,"end":148.92},{"word":"mental","start":148.92,"end":149.26},{"word":"toughness","start":149.26,"end":149.88}],"textKo":"우리는 성실함을 그런 정신적 강함으로 생각해요","listenDifficulty":2},{"index":32,"start":149.88,"end":152.94,"textEn":"That helps people achieve extraordinary things,","words":[{"word":"that","start":149.88,"end":150.6},{"word":"helps","start":150.6,"end":150.96},{"word":"people","start":150.96,"end":151.3},{"word":"achieve","start":151.3,"end":151.68},{"word":"extraordinary","start":151.68,"end":152.32},{"word":"things,","start":152.32,"end":152.94}],"textKo":"이런 정신적 강함은 사람들을 놀라운 성취로 이끕니다","listenDifficulty":1},{"index":33,"start":153.2,"end":156.76,"textEn":"Like ultramarathoners finishing races with broken bones.","words":[{"word":"like","start":153.2,"end":153.68},{"word":"ultramarathoners","start":153.68,"end":154.7},{"word":"finishing","start":154.7,"end":155.02},{"word":"races","start":155.02,"end":155.52},{"word":"with","start":155.52,"end":155.88},{"word":"broken","start":155.88,"end":156.22},{"word":"bones.","start":156.22,"end":156.76}],"textKo":"예를 들어, 골절된 골격을 가지고도 경기를 마치는 초거리 달리기 선수들처럼","listenDifficulty":1},{"index":34,"start":157.1,"end":161.8,"textEn":"But here''s the twist. Grit isn''t just about willpower.","words":[{"word":"But","start":157.1,"end":157.74},{"word":"here''s","start":157.74,"end":158.18},{"word":"the","start":158.18,"end":158.34},{"word":"twist.","start":158.34,"end":158.74},{"word":"Grit","start":159.12,"end":159.92},{"word":"isn''t","start":159.92,"end":160.48},{"word":"just","start":160.48,"end":160.8},{"word":"about","start":160.8,"end":161.16},{"word":"willpower.","start":161.16,"end":161.8}],"textKo":"하지만 여기서 놀라운 점이 있어요. 성실함은 단순히 의지력에만 기반하지 않아요","listenDifficulty":1},{"index":35,"start":161.8,"end":164.58,"textEn":"It''s rooted in biology.","words":[{"word":"It''s","start":161.8,"end":162.96},{"word":"rooted","start":162.96,"end":163.44},{"word":"in","start":163.44,"end":163.98},{"word":"biology.","start":163.98,"end":164.58}],"textKo":"생물학적 기반이 있어요","listenDifficulty":1},{"index":36,"start":165.04,"end":169.3,"textEn":"And the most powerful indicator to date is a protein","words":[{"word":"And","start":165.04,"end":165.96},{"word":"the","start":165.96,"end":166.12},{"word":"most","start":166.12,"end":166.42},{"word":"powerful","start":166.42,"end":166.92},{"word":"indicator","start":166.92,"end":167.5},{"word":"to","start":167.5,"end":167.78},{"word":"date","start":167.78,"end":168.1},{"word":"is","start":168.1,"end":168.7},{"word":"a","start":168.7,"end":168.86},{"word":"protein","start":168.86,"end":169.3}],"textKo":"현재까지 가장 강력한 지표는 단백질인데요","listenDifficulty":3},{"index":37,"start":169.3,"end":171.8,"textEn":"That we''re just starting to understand,","words":[{"word":"that","start":169.3,"end":170.2},{"word":"we''re","start":170.2,"end":170.36},{"word":"just","start":170.36,"end":170.54},{"word":"starting","start":170.54,"end":170.96},{"word":"to","start":170.96,"end":171.16},{"word":"understand,","start":171.16,"end":171.8}],"textKo":"우리가 이제야 조금씩 이해하기 시작한","listenDifficulty":2},{"index":38,"start":172.12,"end":177.04,"textEn":"Called brain-derived neurotrophic factor, or BDNF.","words":[{"word":"called","start":172.12,"end":172.8},{"word":"brain","start":172.8,"end":173.28},{"word":"-derived","start":173.28,"end":174.06},{"word":"neurotrophic","start":174.06,"end":174.98},{"word":"factor,","start":174.98,"end":175.44},{"word":"or","start":175.66,"end":176.12},{"word":"BDNF.","start":176.12,"end":177.04}],"textKo":"브레인-파생 신경성장인자(BDNF)라고 불려요","listenDifficulty":1},{"index":39,"start":177.96,"end":182.34,"textEn":"Think of BDNF as fertilizer for your brain,","words":[{"word":"Think","start":177.96,"end":178.88},{"word":"of","start":178.88,"end":179.04},{"word":"BDNF","start":179.04,"end":179.72},{"word":"as","start":179.72,"end":180.34},{"word":"fertilizer","start":180.34,"end":181.36},{"word":"for","start":181.36,"end":181.8},{"word":"your","start":181.8,"end":181.96},{"word":"brain,","start":181.96,"end":182.34}],"textKo":"BDNF를 뇌의 비료로 생각해보세요,","listenDifficulty":1},{"index":40,"start":182.7,"end":187.24,"textEn":"A protein that helps neurons, the cells in your brain, grow,","words":[{"word":"a","start":182.7,"end":183.44},{"word":"protein","start":183.44,"end":183.88},{"word":"that","start":183.88,"end":184.14},{"word":"helps","start":184.14,"end":184.52},{"word":"neurons,","start":184.52,"end":185.16},{"word":"the","start":185.16,"end":185.62},{"word":"cells","start":185.62,"end":185.86},{"word":"in","start":185.86,"end":186.06},{"word":"your","start":186.06,"end":186.18},{"word":"brain,","start":186.18,"end":186.52},{"word":"grow,","start":186.66,"end":187.24}],"textKo":"두뇌의 세포인 뉴런이 자랄 수 있도록 도와주는 단백질입니다.","listenDifficulty":2},{"index":41,"start":187.24,"end":190.88,"textEn":"Grow, stay healthy, and communicate more effectively.","words":[{"word":"grow,","start":187.24,"end":187.36},{"word":"stay","start":187.96,"end":188.32},{"word":"healthy,","start":188.32,"end":188.8},{"word":"and","start":189.0,"end":189.38},{"word":"communicate","start":189.38,"end":190.06},{"word":"more","start":190.06,"end":190.38},{"word":"effectively.","start":190.38,"end":190.88}],"textKo":"자라며, 건강하게 유지하고, 더 효과적으로 소통할 수 있도록 도와줍니다.","listenDifficulty":1},{"index":42,"start":191.28,"end":197.18,"textEn":"This protein is crucial for things like memory and mental resilience.","words":[{"word":"This","start":191.28,"end":192.08},{"word":"protein","start":192.08,"end":192.56},{"word":"is","start":192.56,"end":193.04},{"word":"crucial","start":193.04,"end":193.6},{"word":"for","start":193.6,"end":194.16},{"word":"things","start":194.16,"end":194.5},{"word":"like","start":194.5,"end":194.78},{"word":"memory","start":194.78,"end":195.22},{"word":"and","start":195.22,"end":196.1},{"word":"mental","start":196.1,"end":196.58},{"word":"resilience.","start":196.58,"end":197.18}],"textKo":"기억력과 정신적 회복력과 같은 것들에 필수적인 단백질입니다.","listenDifficulty":1},{"index":43,"start":197.76,"end":204.7,"textEn":"Many things increase BDNF, including sunshine, blueberries, and antidepressants.","words":[{"word":"Many","start":197.76,"end":198.46},{"word":"things","start":198.46,"end":198.86},{"word":"increase","start":198.86,"end":199.7},{"word":"BDNF,","start":199.7,"end":200.34},{"word":"including","start":200.44,"end":200.8},{"word":"sunshine,","start":200.8,"end":201.68},{"word":"blueberries,","start":202.0,"end":203.36},{"word":"and","start":203.56,"end":203.62},{"word":"antidepressants.","start":203.62,"end":204.7}],"textKo":"자외선, 블루베리, 항우울제 등 많은 것들이 BDNF를 증가시킵니다.","listenDifficulty":1},{"index":44,"start":206.0,"end":208.98,"textEn":"Exercise increases BDNF the most.","words":[{"word":"Exercise","start":206.0,"end":206.96},{"word":"increases","start":206.96,"end":207.72},{"word":"BDNF","start":207.72,"end":208.44},{"word":"the","start":208.44,"end":208.58},{"word":"most.","start":208.58,"end":208.98}],"textKo":"운동은 BDNF를 가장 많이 증가시킵니다.","listenDifficulty":1},{"index":45,"start":208.98,"end":213.24,"textEn":"And the plank, yes, that simple yoga pose,","words":[{"word":"And","start":208.98,"end":210.36},{"word":"the","start":210.36,"end":210.5},{"word":"plank,","start":210.5,"end":210.84},{"word":"yes,","start":211.12,"end":211.5},{"word":"that","start":211.64,"end":211.86},{"word":"simple","start":211.86,"end":212.48},{"word":"yoga","start":212.48,"end":212.78},{"word":"pose,","start":212.78,"end":213.24}],"textKo":"플랭크, 네, 그 간단한 요가 자세,","listenDifficulty":1},{"index":46,"start":213.66,"end":219.6,"textEn":"Just might be one of the best exercises for building mental toughness.","words":[{"word":"just","start":213.66,"end":214.52},{"word":"might","start":214.52,"end":214.86},{"word":"be","start":214.86,"end":215.24},{"word":"one","start":215.24,"end":215.74},{"word":"of","start":215.74,"end":215.88},{"word":"the","start":215.88,"end":216.04},{"word":"best","start":216.04,"end":216.38},{"word":"exercises","start":216.38,"end":217.2},{"word":"for","start":217.2,"end":217.98},{"word":"building","start":217.98,"end":218.46},{"word":"mental","start":218.46,"end":219.04},{"word":"toughness.","start":219.04,"end":219.6}],"textKo":"정신적 근력을 키우는 데 최고의 운동 중 하나일 수도 있습니다.","listenDifficulty":2},{"index":47,"start":220.66,"end":226.5,"textEn":"I''m a clinical professor and diplomat in the Department of Preventive Medicine at UCSD.","words":[{"word":"I''m","start":220.66,"end":221.46},{"word":"a","start":221.46,"end":221.54},{"word":"clinical","start":221.54,"end":221.78},{"word":"professor","start":221.78,"end":222.42},{"word":"and","start":222.42,"end":222.84},{"word":"diplomat","start":222.84,"end":223.4},{"word":"in","start":223.4,"end":223.78},{"word":"the","start":223.78,"end":223.88},{"word":"Department","start":223.88,"end":224.22},{"word":"of","start":224.22,"end":224.44},{"word":"Preventive","start":224.44,"end":225.0},{"word":"Medicine","start":225.0,"end":225.4},{"word":"at","start":225.4,"end":225.84},{"word":"UCSD.","start":225.84,"end":226.5}],"textKo":"저는 캘리포니아 대학교 샌디에이고 캠퍼스 예방의학과 임상 교수이자 전문의입니다.","listenDifficulty":3},{"index":48,"start":226.5,"end":231.0,"textEn":"I''ve been doing clinical research for over 40 years.","words":[{"word":"I''ve","start":226.5,"end":227.72},{"word":"been","start":227.72,"end":227.82},{"word":"doing","start":227.82,"end":228.02},{"word":"clinical","start":228.02,"end":228.42},{"word":"research","start":228.42,"end":228.9},{"word":"for","start":228.9,"end":229.34},{"word":"over","start":229.34,"end":230.32},{"word":"40","start":230.32,"end":230.64},{"word":"years.","start":230.64,"end":231.0}],"textKo":"40년 이상 임상 연구를 해왔습니다.","listenDifficulty":1},{"index":49,"start":231.92,"end":238.38,"textEn":"In the clinic, many of the patients I care for are so-called medically destitute.","words":[{"word":"In","start":231.92,"end":232.64},{"word":"the","start":232.64,"end":232.76},{"word":"clinic,","start":232.76,"end":233.1},{"word":"many","start":233.4,"end":233.78},{"word":"of","start":233.78,"end":233.92},{"word":"the","start":233.92,"end":234.06},{"word":"patients","start":234.06,"end":234.42},{"word":"I","start":234.42,"end":234.7},{"word":"care","start":234.7,"end":234.96},{"word":"for","start":234.96,"end":235.26},{"word":"are","start":235.26,"end":235.86},{"word":"so","start":235.86,"end":236.14},{"word":"-called","start":236.14,"end":236.54},{"word":"medically","start":236.54,"end":237.34},{"word":"destitute.","start":237.34,"end":238.38}],"textKo":"클리닉에서 제가 돌보는 환자들 중 많은 사람들이 의료적으로 가난한 사람들입니다.","listenDifficulty":2},{"index":50,"start":238.84,"end":242.22,"textEn":"Some had a heart attack or stroke in their 40s.","words":[{"word":"Some","start":238.84,"end":239.56},{"word":"had","start":239.56,"end":239.8},{"word":"a","start":239.8,"end":239.9},{"word":"heart","start":239.9,"end":240.06},{"word":"attack","start":240.06,"end":240.36},{"word":"or","start":240.36,"end":240.54},{"word":"stroke","start":240.54,"end":240.92},{"word":"in","start":240.92,"end":241.24},{"word":"their","start":241.24,"end":241.42},{"word":"40s.","start":241.42,"end":242.22}],"textKo":"40대에 심근경색이나 뇌졸중을 겪은 사람도 있다.","listenDifficulty":3},{"index":51,"start":242.72,"end":249.02,"textEn":"Some experienced a horrific accident in their 20s, rendering them unemployable,","words":[{"word":"Some","start":242.72,"end":243.44},{"word":"experienced","start":243.44,"end":244.16},{"word":"a","start":244.16,"end":244.44},{"word":"horrific","start":244.44,"end":244.94},{"word":"accident","start":244.94,"end":245.48},{"word":"in","start":245.48,"end":245.82},{"word":"their","start":245.82,"end":245.98},{"word":"20s,","start":245.98,"end":247.0},{"word":"rendering","start":247.0,"end":247.66},{"word":"them","start":247.66,"end":248.0},{"word":"unemployable,","start":248.0,"end":249.02}],"textKo":"20대에 악몽 같은 사고를 겪어 고용 불가능하게 만들었다,","listenDifficulty":1},{"index":52,"start":249.02,"end":254.32,"textEn":"Stripping them of everything, and leaving them with chronic pain or disability,","words":[{"word":"stripping","start":249.02,"end":249.96},{"word":"them","start":249.96,"end":250.14},{"word":"of","start":250.14,"end":250.36},{"word":"everything,","start":250.36,"end":250.9},{"word":"and","start":251.32,"end":251.84},{"word":"leaving","start":251.84,"end":252.12},{"word":"them","start":252.12,"end":252.32},{"word":"with","start":252.32,"end":252.5},{"word":"chronic","start":252.5,"end":252.84},{"word":"pain","start":252.84,"end":253.3},{"word":"or","start":253.3,"end":253.6},{"word":"disability,","start":253.6,"end":254.32}],"textKo":"모든 것을 뺏어가고 지속적인 통증이나 장애를 남겨두었다,","listenDifficulty":2},{"index":53,"start":254.74,"end":257.04,"textEn":"And a heavy dose of despair.","words":[{"word":"and","start":254.74,"end":255.32},{"word":"a","start":255.32,"end":255.46},{"word":"heavy","start":255.46,"end":255.86},{"word":"dose","start":255.86,"end":256.34},{"word":"of","start":256.34,"end":256.58},{"word":"despair.","start":256.58,"end":257.04}],"textKo":"심한 절망을 남겨두었다.","listenDifficulty":2},{"index":54,"start":258.14,"end":264.48,"textEn":"In no way am I suggesting something as basic as a plank can fix these conditions.","words":[{"word":"In","start":258.14,"end":258.9},{"word":"no","start":258.9,"end":259.14},{"word":"way","start":259.14,"end":259.5},{"word":"am","start":259.5,"end":259.88},{"word":"I","start":259.88,"end":260.0},{"word":"suggesting","start":260.0,"end":260.58},{"word":"something","start":260.58,"end":261.02},{"word":"as","start":261.02,"end":261.28},{"word":"basic","start":261.28,"end":261.62},{"word":"as","start":261.62,"end":261.88},{"word":"a","start":261.88,"end":262.0},{"word":"plank","start":262.0,"end":262.3},{"word":"can","start":262.3,"end":262.82},{"word":"fix","start":262.82,"end":263.38},{"word":"these","start":263.38,"end":263.86},{"word":"conditions.","start":263.86,"end":264.48}],"textKo":"플랭크 같은 기본 운동이 이 상태를 해결할 수 있다고 말하고 있는 것이 절대 아니다.","listenDifficulty":2},{"index":55,"start":265.1,"end":270.68,"textEn":"But more research is warranted to learn the potential benefits.","words":[{"word":"But","start":265.1,"end":265.86},{"word":"more","start":265.86,"end":266.16},{"word":"research","start":266.16,"end":266.66},{"word":"is","start":266.66,"end":266.9},{"word":"warranted","start":266.9,"end":267.62},{"word":"to","start":267.62,"end":268.58},{"word":"learn","start":268.58,"end":268.9},{"word":"the","start":268.9,"end":269.44},{"word":"potential","start":269.44,"end":270.06},{"word":"benefits.","start":270.06,"end":270.68}],"textKo":"잠재적 이점을 배우기 위해 더 많은 연구가 필요하다.","listenDifficulty":2},{"index":56,"start":272.16,"end":276.44,"textEn":"What makes the concept of grit and BDNF so compelling to me","words":[{"word":"What","start":272.16,"end":272.92},{"word":"makes","start":272.92,"end":273.24},{"word":"the","start":273.24,"end":273.42},{"word":"concept","start":273.42,"end":273.88},{"word":"of","start":273.88,"end":274.2},{"word":"grit","start":274.2,"end":274.46},{"word":"and","start":274.46,"end":274.76},{"word":"BDNF","start":274.76,"end":275.26},{"word":"so","start":275.26,"end":275.48},{"word":"compelling","start":275.48,"end":275.98},{"word":"to","start":275.98,"end":276.2},{"word":"me","start":276.2,"end":276.44}],"textKo":"그릿과 BDNF라는 개념이 나에게 왜 매력적인지","listenDifficulty":3},{"index":57,"start":276.44,"end":282.36,"textEn":"Are real-life examples of individuals enduring these devastating conditions.","words":[{"word":"are","start":276.44,"end":277.12},{"word":"real","start":277.12,"end":277.5},{"word":"-life","start":277.5,"end":277.76},{"word":"examples","start":277.76,"end":278.44},{"word":"of","start":278.44,"end":279.0},{"word":"individuals","start":279.0,"end":279.64},{"word":"enduring","start":279.64,"end":280.18},{"word":"these","start":280.18,"end":281.02},{"word":"devastating","start":281.02,"end":281.68},{"word":"conditions.","start":281.68,"end":282.36}],"textKo":"실제로 이러한 심각한 상태를 겪고 있는 개인들의 사례","listenDifficulty":1},{"index":58,"start":283.36,"end":288.48,"textEn":"Researchers and clinicians still have a lot of questions about grit and the plank.","words":[{"word":"Researchers","start":283.36,"end":284.28},{"word":"and","start":284.28,"end":284.58},{"word":"clinicians","start":284.58,"end":285.02},{"word":"still","start":285.02,"end":285.44},{"word":"have","start":285.44,"end":285.7},{"word":"a","start":285.7,"end":285.84},{"word":"lot","start":285.84,"end":286.02},{"word":"of","start":286.02,"end":286.16},{"word":"questions","start":286.16,"end":286.62},{"word":"about","start":286.62,"end":287.18},{"word":"grit","start":287.18,"end":287.86},{"word":"and","start":287.86,"end":288.12},{"word":"the","start":288.12,"end":288.24},{"word":"plank.","start":288.24,"end":288.48}],"textKo":"그릿과 플랭크에 대해 연구자들과 의료진들이 여전히 많은 질문을 가지고 있다.","listenDifficulty":3},{"index":59,"start":288.96,"end":292.92,"textEn":"No one has ever studied BDNF during a plank.","words":[{"word":"No","start":288.96,"end":289.62},{"word":"one","start":289.62,"end":289.8},{"word":"has","start":289.8,"end":290.14},{"word":"ever","start":290.14,"end":290.64},{"word":"studied","start":290.64,"end":291.42},{"word":"BDNF","start":291.42,"end":292.18},{"word":"during","start":292.18,"end":292.42},{"word":"a","start":292.42,"end":292.58},{"word":"plank.","start":292.58,"end":292.92}],"textKo":"누구도 플랭크 중에 BDNF를 연구해 본 적이 없다.","listenDifficulty":2},{"index":60,"start":293.38,"end":297.08,"textEn":"Yet. What we know is this.","words":[{"word":"Yet.","start":293.38,"end":294.08},{"word":"What","start":295.24,"end":296.16},{"word":"we","start":296.16,"end":296.3},{"word":"know","start":296.3,"end":296.52},{"word":"is","start":296.52,"end":296.72},{"word":"this.","start":296.72,"end":297.08}],"textKo":"그런데. 우리가 알고 있는 것은 이것입니다.","listenDifficulty":1},{"index":61,"start":297.42,"end":301.46,"textEn":"The most effective exercises for raising BDNF levels","words":[{"word":"The","start":297.42,"end":297.82},{"word":"most","start":297.82,"end":298.08},{"word":"effective","start":298.08,"end":298.56},{"word":"exercises","start":298.56,"end":299.34},{"word":"for","start":299.34,"end":299.98},{"word":"raising","start":299.98,"end":300.4},{"word":"BDNF","start":300.4,"end":301.08},{"word":"levels","start":301.08,"end":301.46}],"textKo":"BDNF 수치를 높이는 가장 효과적인 운동은","listenDifficulty":1},{"index":62,"start":301.46,"end":304.5,"textEn":"Are those requiring mental effort.","words":[{"word":"are","start":301.46,"end":302.16},{"word":"those","start":302.16,"end":302.38},{"word":"requiring","start":302.38,"end":303.0},{"word":"mental","start":303.0,"end":303.88},{"word":"effort.","start":303.88,"end":304.5}],"textKo":"심리적 노력이 필요한 운동들입니다.","listenDifficulty":1},{"index":63,"start":304.5,"end":309.92,"textEn":"If you''ve ever done a plank, you know how quickly mental fortitude is required.","words":[{"word":"If","start":304.5,"end":305.46},{"word":"you''ve","start":305.46,"end":305.66},{"word":"ever","start":305.66,"end":305.8},{"word":"done","start":305.8,"end":306.02},{"word":"a","start":306.02,"end":306.18},{"word":"plank,","start":306.18,"end":306.44},{"word":"you","start":306.78,"end":307.02},{"word":"know","start":307.02,"end":307.16},{"word":"how","start":307.16,"end":307.4},{"word":"quickly","start":307.4,"end":307.98},{"word":"mental","start":307.98,"end":308.66},{"word":"fortitude","start":308.66,"end":309.22},{"word":"is","start":309.22,"end":309.44},{"word":"required.","start":309.44,"end":309.92}],"textKo":"플랭크를 해본 적이 있다면, 정신적인 힘이 얼마나 빠르게 필요할지를 알겠죠.","listenDifficulty":2},{"index":64,"start":310.72,"end":313.38,"textEn":"That, along with what we''ve learned from George,","words":[{"word":"That,","start":310.72,"end":311.32},{"word":"along","start":311.52,"end":311.86},{"word":"with","start":311.86,"end":312.1},{"word":"what","start":312.1,"end":312.3},{"word":"we''ve","start":312.3,"end":312.58},{"word":"learned","start":312.58,"end":312.78},{"word":"from","start":312.78,"end":312.98},{"word":"George,","start":312.98,"end":313.38}],"textKo":"그와 함께 조지가 알려준 내용을 고려하면,","listenDifficulty":3},{"index":65,"start":313.9,"end":317.74,"textEn":"Leads us to believe the plank may be one of the most efficient","words":[{"word":"leads","start":313.9,"end":314.22},{"word":"us","start":314.22,"end":314.4},{"word":"to","start":314.4,"end":314.56},{"word":"believe","start":314.56,"end":314.88},{"word":"the","start":314.88,"end":315.08},{"word":"plank","start":315.08,"end":315.44},{"word":"may","start":315.44,"end":316.36},{"word":"be","start":316.36,"end":316.5},{"word":"one","start":316.5,"end":316.66},{"word":"of","start":316.66,"end":316.78},{"word":"the","start":316.78,"end":316.88},{"word":"most","start":316.88,"end":317.1},{"word":"efficient","start":317.1,"end":317.74}],"textKo":"우리가 플랭크가 가장 효율적이면서도 효과적인 방법 중 하나일 수 있다는 것을 믿게 합니다.","listenDifficulty":3},{"index":66,"start":318.5,"end":322.08,"textEn":"And effective ways of increasing BDNF.","words":[{"word":"and","start":318.31,"end":318.66},{"word":"effective","start":318.66,"end":319.16},{"word":"ways","start":319.16,"end":319.64},{"word":"of","start":319.64,"end":320.38},{"word":"increasing","start":320.38,"end":321.0},{"word":"BDNF.","start":321.0,"end":322.08}],"textKo":"BDNF를 증가시키는 방법 중 하나일 수 있다는 것을 믿게 합니다.","listenDifficulty":1},{"index":67,"start":322.84,"end":326.88,"textEn":"You see, grit is not just for planks.","words":[{"word":"You","start":322.84,"end":323.34},{"word":"see,","start":323.34,"end":323.64},{"word":"grit","start":324.66,"end":325.06},{"word":"is","start":325.06,"end":325.52},{"word":"not","start":325.52,"end":325.82},{"word":"just","start":325.82,"end":326.18},{"word":"for","start":326.18,"end":326.42},{"word":"planks.","start":326.42,"end":326.88}],"textKo":"아, 그렇습니다. 정신력은 플랭크에만 사용되는 것이 아닙니다.","listenDifficulty":1},{"index":68,"start":327.4,"end":330.58,"textEn":"And BDNF is not just a theory.","words":[{"word":"And","start":327.4,"end":328.02},{"word":"BDNF","start":328.02,"end":328.86},{"word":"is","start":328.86,"end":329.26},{"word":"not","start":329.26,"end":329.6},{"word":"just","start":329.6,"end":330.04},{"word":"a","start":330.04,"end":330.22},{"word":"theory.","start":330.22,"end":330.58}],"textKo":"그리고 BDNF는 단순히 이론에 그치지 않습니다.","listenDifficulty":2},{"index":69,"start":330.58,"end":333.1,"textEn":"It''s backed by science.","words":[{"word":"It''s","start":330.58,"end":331.72},{"word":"backed","start":331.72,"end":332.22},{"word":"by","start":332.22,"end":332.52},{"word":"science.","start":332.52,"end":333.1}],"textKo":"과학적으로 입증되었습니다.","listenDifficulty":1},{"index":70,"start":333.86,"end":339.44,"textEn":"A 2005 article in the aptly named journal Hippocampus","words":[{"word":"A","start":333.86,"end":334.9},{"word":"2005","start":334.9,"end":335.7},{"word":"article","start":335.7,"end":336.42},{"word":"in","start":336.42,"end":337.02},{"word":"the","start":337.02,"end":33