INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'en', 'iuYlGRnC7J8', '{"videoId":"iuYlGRnC7J8","youtubeId":"iuYlGRnC7J8","title":"A Plan Is Not a Strategy","channel":"Harvard Business Review","categoryId":"business","difficulty":"intermediate","duration":571,"thumbnail":"https://i.ytimg.com/vi/iuYlGRnC7J8/maxresdefault.jpg","speechRateWpm":155,"addedAt":"2026-02-16","segmentCount":86,"vocabularyCount":20,"grammarPatternCount":10,"descriptionKo":"계획은 전략이 아니다 — 진짜 전략적 사고란 무엇인가"}'::jsonb, '{"videoId":"iuYlGRnC7J8","segments":[{"index":0,"start":0.0,"end":4.7,"textEn":"This thing called planning has been around for a long, long time.","words":[{"word":"This","start":0.0,"end":0.24},{"word":"thing","start":0.24,"end":0.54},{"word":"called","start":0.54,"end":0.8},{"word":"planning","start":0.8,"end":1.38},{"word":"has","start":1.38,"end":1.66},{"word":"been","start":1.66,"end":1.86},{"word":"around","start":1.86,"end":2.52},{"word":"for","start":2.52,"end":2.96},{"word":"a","start":2.96,"end":3.84},{"word":"long,","start":3.84,"end":4.04},{"word":"long","start":4.14,"end":4.26},{"word":"time.","start":4.26,"end":4.7}],"textKo":"","listenDifficulty":2},{"index":1,"start":5.0,"end":9.0,"textEn":"People would plan out the activities they''re going to engage in.","words":[{"word":"People","start":5.0,"end":5.4},{"word":"would","start":5.4,"end":5.64},{"word":"plan","start":5.64,"end":6.14},{"word":"out","start":6.14,"end":6.4},{"word":"the","start":6.4,"end":6.58},{"word":"activities","start":6.58,"end":7.06},{"word":"they''re","start":7.06,"end":7.42},{"word":"going","start":7.42,"end":7.96},{"word":"to","start":7.96,"end":8.12},{"word":"engage","start":8.12,"end":8.6},{"word":"in.","start":8.6,"end":9.0}],"textKo":"사람들은 자기가 할 활동들을 계획하곤 했어.","listenDifficulty":3},{"index":2,"start":9.16,"end":12.48,"textEn":"More recently, there''s been a discipline called strategy.","words":[{"word":"More","start":9.16,"end":9.6},{"word":"recently,","start":9.6,"end":10.06},{"word":"there''s","start":10.34,"end":11.18},{"word":"been","start":11.18,"end":11.28},{"word":"a","start":11.28,"end":11.4},{"word":"discipline","start":11.4,"end":11.7},{"word":"called","start":11.7,"end":12.04},{"word":"strategy.","start":12.04,"end":12.48}],"textKo":"더 최근에는 전략이라는 학문이 생겼어.","listenDifficulty":1},{"index":3,"start":12.82,"end":16.8,"textEn":"People have put those two things together to call something strategic planning.","words":[{"word":"People","start":12.82,"end":13.1},{"word":"have","start":13.1,"end":13.28},{"word":"put","start":13.28,"end":13.5},{"word":"those","start":13.5,"end":13.74},{"word":"two","start":13.74,"end":13.9},{"word":"things","start":13.9,"end":14.14},{"word":"together","start":14.14,"end":14.48},{"word":"to","start":14.48,"end":14.76},{"word":"call","start":14.76,"end":15.02},{"word":"something","start":15.02,"end":15.44},{"word":"strategic","start":15.44,"end":15.9},{"word":"planning.","start":15.9,"end":16.8}],"textKo":"사람들은 이 두 가지를 합쳐서 전략적 계획이라고 부르기 시작했어.","listenDifficulty":2},{"index":4,"start":17.38,"end":23.68,"textEn":"Unfortunately, those things are not the same, strategy and planning.","words":[{"word":"Unfortunately,","start":17.38,"end":17.98},{"word":"those","start":18.4,"end":19.3},{"word":"things","start":19.3,"end":19.82},{"word":"are","start":19.82,"end":20.58},{"word":"not","start":20.58,"end":21.34},{"word":"the","start":21.34,"end":21.58},{"word":"same,","start":21.58,"end":22.08},{"word":"strategy","start":22.38,"end":23.02},{"word":"and","start":23.02,"end":23.36},{"word":"planning.","start":23.36,"end":23.68}],"textKo":"안타깝게도, 전략과 계획은 같은 게 아니야.","listenDifficulty":1},{"index":5,"start":23.88,"end":26.78,"textEn":"So just putting them together and calling it strategic planning doesn''t help.","words":[{"word":"So","start":23.88,"end":23.92},{"word":"just","start":23.92,"end":24.08},{"word":"putting","start":24.08,"end":24.36},{"word":"them","start":24.36,"end":24.5},{"word":"together","start":24.5,"end":24.76},{"word":"and","start":24.76,"end":24.92},{"word":"calling","start":24.92,"end":25.22},{"word":"it","start":25.22,"end":25.42},{"word":"strategic","start":25.42,"end":25.8},{"word":"planning","start":25.8,"end":26.2},{"word":"doesn''t","start":26.2,"end":26.56},{"word":"help.","start":26.56,"end":26.78}],"textKo":"그래서 그냥 둘을 합쳐서 전략적 계획이라고 부르는 건 도움이 안 돼.","listenDifficulty":3},{"index":6,"start":26.78,"end":33.48,"textEn":"What most strategic planning is in the world of business has nothing to do with strategy.","words":[{"word":"What","start":26.78,"end":27.18},{"word":"most","start":27.18,"end":27.64},{"word":"strategic","start":27.64,"end":28.2},{"word":"planning","start":28.2,"end":28.62},{"word":"is","start":28.62,"end":29.42},{"word":"in","start":29.42,"end":29.82},{"word":"the","start":29.82,"end":29.98},{"word":"world","start":29.98,"end":30.2},{"word":"of","start":30.2,"end":30.64},{"word":"business","start":30.64,"end":31.06},{"word":"has","start":31.06,"end":32.24},{"word":"nothing","start":32.24,"end":32.56},{"word":"to","start":32.56,"end":32.7},{"word":"do","start":32.7,"end":32.82},{"word":"with","start":32.82,"end":33.0},{"word":"strategy.","start":33.0,"end":33.48}],"textKo":"비즈니스 세계에서 대부분의 전략적 계획은 전략과 아무 관련이 없어.","listenDifficulty":2},{"index":7,"start":33.7,"end":41.1,"textEn":"It''s got the word, but it''s not. It''s a set of activities that the company says it''s going to do.","words":[{"word":"It''s","start":33.7,"end":33.98},{"word":"got","start":33.98,"end":34.08},{"word":"the","start":34.08,"end":34.18},{"word":"word,","start":34.18,"end":34.48},{"word":"but","start":34.68,"end":35.24},{"word":"it''s","start":35.24,"end":35.38},{"word":"not.","start":35.38,"end":35.56},{"word":"It''s","start":36.0,"end":36.58},{"word":"a","start":36.58,"end":36.72},{"word":"set","start":36.72,"end":37.08},{"word":"of","start":37.08,"end":37.36},{"word":"activities","start":37.36,"end":37.92},{"word":"that","start":37.92,"end":39.18},{"word":"the","start":39.18,"end":39.42},{"word":"company","start":39.42,"end":39.7},{"word":"says","start":39.7,"end":40.22},{"word":"it''s","start":40.22,"end":40.56},{"word":"going","start":40.56,"end":40.72},{"word":"to","start":40.72,"end":40.86},{"word":"do.","start":40.86,"end":41.1}],"textKo":"이름에 그 단어가 들어가 있지만 전략이 아니야. 회사가 하겠다고 말하는 활동 목록일 뿐이야.","listenDifficulty":3},{"index":8,"start":41.24,"end":43.68,"textEn":"We''re going to improve customer experience.","words":[{"word":"We''re","start":41.24,"end":41.56},{"word":"going","start":41.56,"end":41.66},{"word":"to","start":41.66,"end":41.76},{"word":"improve","start":41.76,"end":42.2},{"word":"customer","start":42.2,"end":42.8},{"word":"experience.","start":42.8,"end":43.68}],"textKo":"고객 경험을 개선할 거야.","listenDifficulty":2},{"index":9,"start":43.68,"end":51.96,"textEn":"We''re going to open this new plant. We''re going to start a new talent development program, a whole list of them, and they all sound good.","words":[{"word":"We''re","start":43.68,"end":44.1},{"word":"going","start":44.1,"end":44.24},{"word":"to","start":44.24,"end":44.4},{"word":"open","start":44.4,"end":44.72},{"word":"this","start":44.72,"end":45.02},{"word":"new","start":45.02,"end":45.22},{"word":"plant.","start":45.22,"end":45.62},{"word":"We''re","start":45.62,"end":46.08},{"word":"going","start":46.08,"end":46.3},{"word":"to","start":46.3,"end":46.54},{"word":"start","start":46.54,"end":46.98},{"word":"a","start":46.98,"end":47.3},{"word":"new","start":47.3,"end":47.54},{"word":"talent","start":47.54,"end":47.92},{"word":"development","start":47.92,"end":48.38},{"word":"program,","start":48.38,"end":48.92},{"word":"a","start":49.1,"end":49.22},{"word":"whole","start":49.22,"end":49.46},{"word":"list","start":49.46,"end":49.96},{"word":"of","start":49.96,"end":50.1},{"word":"them,","start":50.1,"end":50.22},{"word":"and","start":50.3,"end":50.34},{"word":"they","start":50.34,"end":50.44},{"word":"all","start":50.44,"end":51.18},{"word":"sound","start":51.18,"end":51.56},{"word":"good.","start":51.56,"end":51.96}],"textKo":"새 공장을 열 거야. 새로운 인재 개발 프로그램을 시작할 거야. 이런 목록이 쭉 있는 거지, 다 좋아 보여.","listenDifficulty":2},{"index":10,"start":51.96,"end":59.32,"textEn":"But the results of all of those are not going to make the company happy because they didn''t have a strategy.","words":[{"word":"But","start":51.96,"end":52.5},{"word":"the","start":52.5,"end":52.9},{"word":"results","start":52.9,"end":53.52},{"word":"of","start":53.52,"end":54.32},{"word":"all","start":54.32,"end":54.46},{"word":"of","start":54.46,"end":54.56},{"word":"those","start":54.56,"end":54.8},{"word":"are","start":54.8,"end":55.24},{"word":"not","start":55.24,"end":55.52},{"word":"going","start":55.52,"end":55.72},{"word":"to","start":55.72,"end":55.8},{"word":"make","start":55.8,"end":56.08},{"word":"the","start":56.08,"end":56.52},{"word":"company","start":56.52,"end":56.8},{"word":"happy","start":56.8,"end":57.14},{"word":"because","start":57.14,"end":57.52},{"word":"they","start":57.52,"end":58.16},{"word":"didn''t","start":58.16,"end":58.42},{"word":"have","start":58.42,"end":58.58},{"word":"a","start":58.58,"end":58.78},{"word":"strategy.","start":58.78,"end":59.32}],"textKo":"하지만 그 결과가 회사를 만족시키지 못할 거야. 전략이 없었으니까.","listenDifficulty":2},{"index":11,"start":62.22,"end":73.22,"textEn":"So what''s a strategy? A strategy is an integrative set of choices that positions you on a playing field of your choice in a way that you win.","words":[{"word":"So","start":62.22,"end":62.9},{"word":"what''s","start":62.9,"end":63.32},{"word":"a","start":63.32,"end":63.46},{"word":"strategy?","start":63.46,"end":63.96},{"word":"A","start":64.3,"end":64.88},{"word":"strategy","start":64.88,"end":65.32},{"word":"is","start":65.32,"end":65.72},{"word":"an","start":65.72,"end":65.92},{"word":"integrative","start":65.92,"end":66.8},{"word":"set","start":66.8,"end":67.38},{"word":"of","start":67.38,"end":67.7},{"word":"choices","start":67.7,"end":68.16},{"word":"that","start":68.16,"end":68.98},{"word":"positions","start":68.98,"end":69.4},{"word":"you","start":69.4,"end":69.82},{"word":"on","start":69.82,"end":70.58},{"word":"a","start":70.58,"end":70.68},{"word":"playing","start":70.68,"end":70.94},{"word":"field","start":70.94,"end":71.2},{"word":"of","start":71.2,"end":71.36},{"word":"your","start":71.36,"end":71.48},{"word":"choice","start":71.48,"end":71.88},{"word":"in","start":71.88,"end":72.2},{"word":"a","start":72.2,"end":72.32},{"word":"way","start":72.32,"end":72.48},{"word":"that","start":72.48,"end":72.68},{"word":"you","start":72.68,"end":72.86},{"word":"win.","start":72.86,"end":73.22}],"textKo":"그러면 전략이 뭐야? 전략은 네가 선택한 경쟁의 장에서 이길 수 있도록 포지셔닝하는 통합적인 선택의 집합이야.","listenDifficulty":3},{"index":12,"start":73.44,"end":76.3,"textEn":"So there''s a theory. Strategy has a theory.","words":[{"word":"So","start":73.44,"end":73.82},{"word":"there''s","start":73.82,"end":74.1},{"word":"a","start":74.1,"end":74.24},{"word":"theory.","start":74.24,"end":74.74},{"word":"Strategy","start":75.0,"end":75.5},{"word":"has","start":75.5,"end":75.8},{"word":"a","start":75.8,"end":75.96},{"word":"theory.","start":75.96,"end":76.3}],"textKo":"그래서 이론이 있어. 전략에는 이론이 있어.","listenDifficulty":2},{"index":13,"start":77.02,"end":81.16,"textEn":"Here''s why we should be on this playing field, not this other one.","words":[{"word":"Here''s","start":77.02,"end":77.58},{"word":"why","start":77.58,"end":78.12},{"word":"we","start":78.12,"end":78.68},{"word":"should","start":78.68,"end":78.8},{"word":"be","start":78.8,"end":78.94},{"word":"on","start":78.94,"end":79.16},{"word":"this","start":79.16,"end":79.46},{"word":"playing","start":79.46,"end":79.74},{"word":"field,","start":79.74,"end":80.08},{"word":"not","start":80.24,"end":80.42},{"word":"this","start":80.42,"end":80.64},{"word":"other","start":80.64,"end":80.86},{"word":"one.","start":80.86,"end":81.16}],"textKo":"우리가 왜 다른 곳이 아닌 이 경쟁의 장에 있어야 하는지에 대한 이론이야.","listenDifficulty":2},{"index":14,"start":81.36,"end":90.42,"textEn":"And here''s how on that playing field we''re going to be better than anybody else at serving the customers on that playing field.","words":[{"word":"And","start":81.36,"end":81.86},{"word":"here''s","start":81.86,"end":82.52},{"word":"how","start":82.52,"end":83.04},{"word":"on","start":83.04,"end":84.28},{"word":"that","start":84.28,"end":84.5},{"word":"playing","start":84.5,"end":84.76},{"word":"field","start":84.76,"end":85.04},{"word":"we''re","start":85.04,"end":85.3},{"word":"going","start":85.3,"end":85.32},{"word":"to","start":85.32,"end":85.38},{"word":"be","start":85.38,"end":85.5},{"word":"better","start":85.5,"end":85.86},{"word":"than","start":85.86,"end":86.42},{"word":"anybody","start":86.42,"end":86.8},{"word":"else","start":86.8,"end":87.18},{"word":"at","start":87.18,"end":87.46},{"word":"serving","start":87.46,"end":87.86},{"word":"the","start":87.86,"end":88.28},{"word":"customers","start":88.28,"end":88.76},{"word":"on","start":88.76,"end":89.5},{"word":"that","start":89.5,"end":89.74},{"word":"playing","start":89.74,"end":90.06},{"word":"field.","start":90.06,"end":90.42}],"textKo":"그리고 그 경쟁의 장에서 어떻게 다른 누구보다 더 잘 고객을 만족시킬 수 있는지에 대한 거야.","listenDifficulty":2},{"index":15,"start":90.9,"end":92.94,"textEn":"That theory has to be coherent.","words":[{"word":"That","start":90.9,"end":91.46},{"word":"theory","start":91.46,"end":91.74},{"word":"has","start":91.74,"end":92.0},{"word":"to","start":92.0,"end":92.14},{"word":"be","start":92.14,"end":92.3},{"word":"coherent.","start":92.3,"end":92.94}],"textKo":"그 이론은 일관성이 있어야 해.","listenDifficulty":3},{"index":16,"start":93.22,"end":99.58,"textEn":"It has to be doable. You have to be able to translate that into actions for it to be a great strategy.","words":[{"word":"It","start":93.22,"end":93.64},{"word":"has","start":93.64,"end":93.8},{"word":"to","start":93.8,"end":93.94},{"word":"be","start":93.94,"end":94.16},{"word":"doable.","start":94.16,"end":94.82},{"word":"You","start":95.16,"end":95.46},{"word":"have","start":95.46,"end":95.6},{"word":"to","start":95.6,"end":95.7},{"word":"be","start":95.7,"end":95.8},{"word":"able","start":95.8,"end":95.94},{"word":"to","start":95.94,"end":96.08},{"word":"translate","start":96.08,"end":96.54},{"word":"that","start":96.54,"end":96.82},{"word":"into","start":96.82,"end":97.04},{"word":"actions","start":97.04,"end":97.52},{"word":"for","start":97.52,"end":98.2},{"word":"it","start":98.2,"end":98.32},{"word":"to","start":98.32,"end":98.4},{"word":"be","start":98.4,"end":98.52},{"word":"a","start":98.52,"end":98.66},{"word":"great","start":98.66,"end":98.92},{"word":"strategy.","start":98.92,"end":99.58}],"textKo":"실행 가능해야 하고. 훌륭한 전략이 되려면 그걸 행동으로 옮길 수 있어야 해.","listenDifficulty":3},{"index":17,"start":101.24,"end":103.96,"textEn":"Planning does not have to have any such coherence.","words":[{"word":"Planning","start":101.24,"end":101.72},{"word":"does","start":101.72,"end":102.2},{"word":"not","start":102.2,"end":102.38},{"word":"have","start":102.38,"end":102.56},{"word":"to","start":102.56,"end":102.66},{"word":"have","start":102.66,"end":102.8},{"word":"any","start":102.8,"end":103.04},{"word":"such","start":103.04,"end":103.3},{"word":"coherence.","start":103.3,"end":103.96}],"textKo":"계획은 그런 일관성이 전혀 필요 없어.","listenDifficulty":3},{"index":18,"start":104.22,"end":108.5,"textEn":"And it typically is what people in manufacturing want, the few things.","words":[{"word":"And","start":104.22,"end":104.7},{"word":"it","start":104.7,"end":104.82},{"word":"typically","start":104.82,"end":105.1},{"word":"is","start":105.1,"end":105.6},{"word":"what","start":105.6,"end":106.58},{"word":"people","start":106.58,"end":106.88},{"word":"in","start":106.88,"end":107.04},{"word":"manufacturing","start":107.04,"end":107.58},{"word":"want,","start":107.58,"end":107.92},{"word":"the","start":108.04,"end":108.12},{"word":"few","start":108.12,"end":108.28},{"word":"things.","start":108.28,"end":108.5}],"textKo":"보통은 제조 부서 사람들이 원하는 몇 가지가 있는 거야.","listenDifficulty":2},{"index":19,"start":108.6,"end":113.72,"textEn":"They want to build a new plant, and the marketing people want to launch a new brand, and the talent people want to hire more people.","words":[{"word":"They","start":108.6,"end":108.62},{"word":"want","start":108.62,"end":108.76},{"word":"to","start":108.76,"end":108.82},{"word":"build","start":108.82,"end":108.94},{"word":"a","start":108.94,"end":109.06},{"word":"new","start":109.06,"end":109.14},{"word":"plant,","start":109.14,"end":109.54},{"word":"and","start":109.68,"end":109.84},{"word":"the","start":109.84,"end":109.9},{"word":"marketing","start":109.9,"end":110.14},{"word":"people","start":110.14,"end":110.38},{"word":"want","start":110.38,"end":110.52},{"word":"to","start":110.52,"end":110.62},{"word":"launch","start":110.62,"end":110.8},{"word":"a","start":110.8,"end":110.88},{"word":"new","start":110.88,"end":110.98},{"word":"brand,","start":110.98,"end":111.36},{"word":"and","start":111.44,"end":111.7},{"word":"the","start":111.7,"end":111.8},{"word":"talent","start":111.8,"end":112.08},{"word":"people","start":112.08,"end":112.36},{"word":"want","start":112.36,"end":112.6},{"word":"to","start":112.6,"end":112.7},{"word":"hire","start":112.7,"end":113.12},{"word":"more","start":113.12,"end":113.32},{"word":"people.","start":113.32,"end":113.72}],"textKo":"새 공장을 짓고 싶고, 마케팅 부서는 새 브랜드를 출시하고 싶고, 인재 부서는 더 많은 사람을 뽑고 싶고.","listenDifficulty":3},{"index":20,"start":114.34,"end":128.92,"textEn":"There tends to be a list that has no internal coherence to it and no specification of a way that that is going to accomplish collectively some goal for the company.","words":[{"word":"There","start":114.34,"end":114.82},{"word":"tends","start":114.82,"end":115.08},{"word":"to","start":115.08,"end":115.24},{"word":"be","start":115.24,"end":115.38},{"word":"a","start":115.38,"end":115.62},{"word":"list","start":115.62,"end":115.98},{"word":"that","start":115.98,"end":116.68},{"word":"has","start":116.68,"end":116.98},{"word":"no","start":116.98,"end":117.36},{"word":"internal","start":117.36,"end":118.16},{"word":"coherence","start":118.16,"end":119.14},{"word":"to","start":119.14,"end":119.38},{"word":"it","start":119.38,"end":119.64},{"word":"and","start":119.64,"end":120.32},{"word":"no","start":120.32,"end":121.06},{"word":"specification","start":121.06,"end":122.44},{"word":"of","start":122.44,"end":123.28},{"word":"a","start":123.28,"end":123.58},{"word":"way","start":123.58,"end":124.02},{"word":"that","start":124.02,"end":124.62},{"word":"that","start":124.62,"end":124.78},{"word":"is","start":124.78,"end":125.02},{"word":"going","start":125.02,"end":125.2},{"word":"to","start":125.2,"end":125.38},{"word":"accomplish","start":125.38,"end":125.94},{"word":"collectively","start":125.94,"end":126.74},{"word":"some","start":126.74,"end":127.8},{"word":"goal","start":127.8,"end":128.14},{"word":"for","start":128.14,"end":128.48},{"word":"the","start":128.48,"end":128.6},{"word":"company.","start":128.6,"end":128.92}],"textKo":"내부적으로 일관성이 없고, 회사의 어떤 목표를 집합적으로 달성할 방법도 명시되어 있지 않은 목록이 되기 쉬워.","listenDifficulty":2},{"index":21,"start":130.94,"end":138.36,"textEn":"Planning is quite comforting. Plans typically have to do with the resources you''re going to spend.","words":[{"word":"Planning","start":130.94,"end":131.56},{"word":"is","start":131.56,"end":131.8},{"word":"quite","start":131.8,"end":132.08},{"word":"comforting.","start":132.08,"end":132.86},{"word":"Plans","start":133.3,"end":133.92},{"word":"typically","start":133.92,"end":134.62},{"word":"have","start":134.62,"end":135.02},{"word":"to","start":135.02,"end":135.18},{"word":"do","start":135.18,"end":135.44},{"word":"with","start":135.44,"end":135.88},{"word":"the","start":135.88,"end":136.68},{"word":"resources","start":136.68,"end":137.54},{"word":"you''re","start":137.54,"end":137.84},{"word":"going","start":137.84,"end":137.92},{"word":"to","start":137.92,"end":138.02},{"word":"spend.","start":138.02,"end":138.36}],"textKo":"계획은 꽤 편안해. 계획은 보통 쓸 자원에 관한 거야.","listenDifficulty":2},{"index":22,"start":138.86,"end":141.06,"textEn":"So we''re going to build a plant.","words":[{"word":"So","start":138.86,"end":139.32},{"word":"we''re","start":139.32,"end":139.6},{"word":"going","start":139.6,"end":139.76},{"word":"to","start":139.76,"end":139.94},{"word":"build","start":139.94,"end":140.38},{"word":"a","start":140.38,"end":140.7},{"word":"plant.","start":140.7,"end":141.06}],"textKo":"그래서 공장을 짓겠다는 거야.","listenDifficulty":2},{"index":23,"start":141.24,"end":145.18,"textEn":"We''re going to hire some people. We''re going to launch a new product.","words":[{"word":"We''re","start":141.24,"end":141.4},{"word":"going","start":141.4,"end":141.54},{"word":"to","start":141.54,"end":141.7},{"word":"hire","start":141.7,"end":142.16},{"word":"some","start":142.16,"end":142.54},{"word":"people.","start":142.54,"end":143.0},{"word":"We''re","start":143.2,"end":143.6},{"word":"going","start":143.6,"end":143.68},{"word":"to","start":143.68,"end":143.8},{"word":"launch","start":143.8,"end":144.22},{"word":"a","start":144.22,"end":144.46},{"word":"new","start":144.46,"end":144.7},{"word":"product.","start":144.7,"end":145.18}],"textKo":"사람을 뽑겠다. 새 제품을 출시하겠다.","listenDifficulty":3},{"index":24,"start":145.46,"end":150.02,"textEn":"Those are all things that are on the cost side of businesses.","words":[{"word":"Those","start":145.46,"end":145.88},{"word":"are","start":145.88,"end":146.08},{"word":"all","start":146.08,"end":146.32},{"word":"things","start":146.32,"end":146.68},{"word":"that","start":146.68,"end":146.94},{"word":"are","start":146.94,"end":147.08},{"word":"on","start":147.08,"end":147.26},{"word":"the","start":147.26,"end":147.48},{"word":"cost","start":147.48,"end":148.08},{"word":"side","start":148.08,"end":148.5},{"word":"of","start":148.5,"end":149.4},{"word":"businesses.","start":149.4,"end":150.02}],"textKo":"이것들은 전부 사업의 비용 측면에 있는 것들이야.","listenDifficulty":2},{"index":25,"start":150.28,"end":152.36,"textEn":"Who controls your costs?","words":[{"word":"Who","start":150.28,"end":150.56},{"word":"controls","start":150.56,"end":151.16},{"word":"your","start":151.16,"end":151.84},{"word":"costs?","start":151.84,"end":152.36}],"textKo":"비용은 누가 통제해?","listenDifficulty":2},{"index":26,"start":152.54,"end":154.62,"textEn":"Who''s the customer of your costs?","words":[{"word":"Who''s","start":152.54,"end":152.9},{"word":"the","start":152.9,"end":153.08},{"word":"customer","start":153.08,"end":153.66},{"word":"of","start":153.66,"end":153.94},{"word":"your","start":153.94,"end":154.1},{"word":"costs?","start":154.1,"end":154.62}],"textKo":"비용의 고객은 누구야?","listenDifficulty":2},{"index":27,"start":154.96,"end":163.72,"textEn":"The answer is you are. You decide how many square feet to lease, how many raw materials to buy, how many people to hire.","words":[{"word":"The","start":154.96,"end":155.54},{"word":"answer","start":155.54,"end":155.74},{"word":"is","start":155.74,"end":155.96},{"word":"you","start":155.96,"end":156.16},{"word":"are.","start":156.16,"end":156.44},{"word":"You","start":156.44,"end":157.38},{"word":"decide","start":157.38,"end":157.76},{"word":"how","start":157.76,"end":157.98},{"word":"many","start":157.98,"end":158.18},{"word":"square","start":158.18,"end":158.62},{"word":"feet","start":158.62,"end":158.92},{"word":"to","start":158.92,"end":159.06},{"word":"lease,","start":159.06,"end":159.38},{"word":"how","start":159.66,"end":159.7},{"word":"many","start":159.7,"end":160.02},{"word":"raw","start":160.02,"end":161.58},{"word":"materials","start":161.58,"end":162.06},{"word":"to","start":162.06,"end":162.26},{"word":"buy,","start":162.26,"end":162.54},{"word":"how","start":162.7,"end":162.76},{"word":"many","start":162.76,"end":162.9},{"word":"people","start":162.9,"end":163.24},{"word":"to","start":163.24,"end":163.38},{"word":"hire.","start":163.38,"end":163.72}],"textKo":"답은 바로 너야. 사무실을 얼마나 빌릴지, 원자재를 얼마나 살지, 사람을 얼마나 뽑을지 네가 결정해.","listenDifficulty":2},{"index":28,"start":164.0,"end":166.3,"textEn":"Those are more comfortable because you control them.","words":[{"word":"Those","start":164.0,"end":164.36},{"word":"are","start":164.36,"end":164.52},{"word":"more","start":164.52,"end":164.66},{"word":"comfortable","start":164.66,"end":165.06},{"word":"because","start":165.06,"end":165.4},{"word":"you","start":165.4,"end":165.64},{"word":"control","start":165.64,"end":166.0},{"word":"them.","start":166.0,"end":166.3}],"textKo":"그래서 더 편해. 네가 통제할 수 있으니까.","listenDifficulty":3},{"index":29,"start":167.12,"end":174.82,"textEn":"A strategy, on the other hand, specifies an outcome, a competitive outcome that you wish to achieve,","words":[{"word":"A","start":167.12,"end":167.56},{"word":"strategy,","start":167.56,"end":168.26},{"word":"on","start":168.26,"end":169.16},{"word":"the","start":169.16,"end":169.28},{"word":"other","start":169.28,"end":169.46},{"word":"hand,","start":169.46,"end":169.84},{"word":"specifies","start":170.3,"end":171.1},{"word":"an","start":171.1,"end":171.52},{"word":"outcome,","start":171.52,"end":172.12},{"word":"a","start":172.32,"end":172.44},{"word":"competitive","start":172.44,"end":172.96},{"word":"outcome","start":172.96,"end":173.52},{"word":"that","start":173.52,"end":173.76},{"word":"you","start":173.76,"end":173.94},{"word":"wish","start":173.94,"end":174.18},{"word":"to","start":174.18,"end":174.36},{"word":"achieve,","start":174.36,"end":174.82}],"textKo":"반면에 전략은 결과를, 네가 달성하고 싶은 경쟁적 결과를 명시해.","listenDifficulty":3},{"index":30,"start":174.82,"end":187.92,"textEn":"Which involves customers wanting your product or service enough that they will buy enough of it to make the profitability that you''d like to make.","words":[{"word":"which","start":174.82,"end":175.86},{"word":"involves","start":175.86,"end":176.52},{"word":"customers","start":176.52,"end":177.62},{"word":"wanting","start":177.62,"end":178.84},{"word":"your","start":178.84,"end":179.12},{"word":"product","start":179.12,"end":179.56},{"word":"or","start":179.56,"end":179.8},{"word":"service","start":179.8,"end":180.34},{"word":"enough","start":180.34,"end":181.46},{"word":"that","start":181.46,"end":181.72},{"word":"they","start":181.72,"end":181.9},{"word":"will","start":181.9,"end":182.26},{"word":"buy","start":182.26,"end":183.02},{"word":"enough","start":183.02,"end":183.42},{"word":"of","start":183.42,"end":183.58},{"word":"it","start":183.58,"end":183.76},{"word":"to","start":183.76,"end":184.74},{"word":"make","start":184.74,"end":185.0},{"word":"the","start":185.0,"end":185.26},{"word":"profitability","start":185.26,"end":185.8},{"word":"that","start":185.8,"end":186.72},{"word":"you''d","start":186.72,"end":186.98},{"word":"like","start":186.98,"end":187.12},{"word":"to","start":187.12,"end":187.28},{"word":"make.","start":187.28,"end":187.92}],"textKo":"고객이 네 제품이나 서비스를 충분히 원해서 네가 원하는 수익을 낼 만큼 충분히 구매하는 것을 포함해.","listenDifficulty":3},{"index":31,"start":188.14,"end":193.46,"textEn":"The tricky thing about that is that you don''t control them.","words":[{"word":"The","start":188.14,"end":188.68},{"word":"tricky","start":188.68,"end":189.08},{"word":"thing","start":189.08,"end":189.46},{"word":"about","start":189.46,"end":189.7},{"word":"that","start":189.7,"end":190.14},{"word":"is","start":190.14,"end":191.1},{"word":"that","start":191.1,"end":191.46},{"word":"you","start":191.46,"end":192.56},{"word":"don''t","start":192.56,"end":192.82},{"word":"control","start":192.82,"end":193.16},{"word":"them.","start":193.16,"end":193.46}],"textKo":"까다로운 건 그들을 통제할 수 없다는 거야.","listenDifficulty":1},{"index":32,"start":193.46,"end":197.18,"textEn":"You might wish you could, but you can''t.","words":[{"word":"You","start":193.46,"end":194.66},{"word":"might","start":194.66,"end":194.88},{"word":"wish","start":194.88,"end":195.28},{"word":"you","start":195.28,"end":195.46},{"word":"could,","start":195.46,"end":195.78},{"word":"but","start":196.0,"end":196.54},{"word":"you","start":196.54,"end":196.72},{"word":"can''t.","start":196.72,"end":197.18}],"textKo":"통제하고 싶겠지만, 못해.","listenDifficulty":1},{"index":33,"start":197.36,"end":201.74,"textEn":"They decide, not you. That''s a harder trick.","words":[{"word":"They","start":197.36,"end":197.94},{"word":"decide,","start":197.94,"end":198.48},{"word":"not","start":198.64,"end":198.76},{"word":"you.","start":198.76,"end":199.08},{"word":"That''s","start":200.24,"end":200.88},{"word":"a","start":200.88,"end":200.98},{"word":"harder","start":200.98,"end":201.32},{"word":"trick.","start":201.32,"end":201.74}],"textKo":"그들이 결정하지, 네가 아니야. 더 어려운 일이지.","listenDifficulty":1},{"index":34,"start":201.74,"end":208.32,"textEn":"So that means putting yourself out and saying, here''s what we believe will happen.","words":[{"word":"So","start":201.74,"end":202.5},{"word":"that","start":202.5,"end":203.24},{"word":"means","start":203.24,"end":203.7},{"word":"putting","start":203.7,"end":204.52},{"word":"yourself","start":204.52,"end":204.86},{"word":"out","start":204.86,"end":205.26},{"word":"and","start":205.26,"end":205.44},{"word":"saying,","start":205.44,"end":205.8},{"word":"here''s","start":206.0,"end":206.78},{"word":"what","start":206.78,"end":206.94},{"word":"we","start":206.94,"end":207.12},{"word":"believe","start":207.12,"end":207.54},{"word":"will","start":207.54,"end":207.94},{"word":"happen.","start":207.94,"end":208.32}],"textKo":"그래서 나서서 이렇게 말해야 해. 이런 일이 일어날 거라고 우리는 믿어.","listenDifficulty":1},{"index":35,"start":208.98,"end":211.6,"textEn":"We can''t prove it in advance.","words":[{"word":"We","start":208.98,"end":209.62},{"word":"can''t","start":209.62,"end":210.04},{"word":"prove","start":210.04,"end":210.96},{"word":"it","start":210.96,"end":211.1},{"word":"in","start":211.1,"end":211.22},{"word":"advance.","start":211.22,"end":211.6}],"textKo":"미리 증명할 수 없어.","listenDifficulty":1},{"index":36,"start":211.96,"end":218.06,"textEn":"We can''t guarantee it. But this is what we want to have happen and that we believe will happen.","words":[{"word":"We","start":211.96,"end":212.56},{"word":"can''t","start":212.56,"end":212.86},{"word":"guarantee","start":212.86,"end":213.3},{"word":"it.","start":213.3,"end":213.7},{"word":"But","start":213.88,"end":214.46},{"word":"this","start":214.46,"end":214.68},{"word":"is","start":214.68,"end":214.8},{"word":"what","start":214.8,"end":214.96},{"word":"we","start":214.96,"end":215.14},{"word":"want","start":215.14,"end":215.44},{"word":"to","start":215.44,"end":215.56},{"word":"have","start":215.56,"end":215.7},{"word":"happen","start":215.7,"end":216.02},{"word":"and","start":216.02,"end":216.3},{"word":"that","start":216.3,"end":216.74},{"word":"we","start":216.74,"end":216.94},{"word":"believe","start":216.94,"end":217.4},{"word":"will","start":217.4,"end":217.72},{"word":"happen.","start":217.72,"end":218.06}],"textKo":"보장할 수 없어. 하지만 이것이 우리가 바라고 또 일어날 거라고 믿는 거야.","listenDifficulty":3},{"index":37,"start":218.9,"end":221.22,"textEn":"It''s much easier to say, I''ll build a factory.","words":[{"word":"It''s","start":218.9,"end":219.54},{"word":"much","start":219.54,"end":219.76},{"word":"easier","start":219.76,"end":220.12},{"word":"to","start":220.12,"end":220.24},{"word":"say,","start":220.24,"end":220.38},{"word":"I''ll","start":220.52,"end":220.58},{"word":"build","start":220.58,"end":220.76},{"word":"a","start":220.76,"end":220.86},{"word":"factory.","start":220.86,"end":221.22}],"textKo":"공장을 짓겠다고 말하는 게 훨씬 쉽지.","listenDifficulty":3},{"index":38,"start":221.28,"end":223.54,"textEn":"I will hire more people, etc.","words":[{"word":"I","start":221.28,"end":221.92},{"word":"will","start":221.92,"end":222.2},{"word":"hire","start":222.2,"end":222.68},{"word":"more","start":222.68,"end":222.88},{"word":"people,","start":222.88,"end":223.24},{"word":"etc.","start":223.34,"end":223.54}],"textKo":"사람을 더 뽑겠다, 등등.","listenDifficulty":2},{"index":39,"start":223.88,"end":232.14,"textEn":"Then I will have customers end up liking our offering more than those of competitors.","words":[{"word":"Then","start":223.88,"end":224.04},{"word":"I","start":224.04,"end":224.92},{"word":"will","start":224.92,"end":225.3},{"word":"have","start":225.3,"end":225.96},{"word":"customers","start":225.96,"end":226.94},{"word":"end","start":226.94,"end":227.72},{"word":"up","start":227.72,"end":227.96},{"word":"liking","start":227.96,"end":228.48},{"word":"our","start":228.48,"end":229.14},{"word":"offering","start":229.14,"end":229.68},{"word":"more","start":229.68,"end":230.48},{"word":"than","start":230.48,"end":231.2},{"word":"those","start":231.2,"end":231.42},{"word":"of","start":231.42,"end":231.62},{"word":"competitors.","start":231.62,"end":232.14}],"textKo":"고객이 경쟁사보다 우리 제품을 더 좋아하게 만들겠다고 말하는 것보다 말이야.","listenDifficulty":1},{"index":40,"start":232.62,"end":243.06,"textEn":"The tricky thing about planning is that while you''re planning, chances are at least one competitor is figuring out how to win.","words":[{"word":"The","start":232.62,"end":233.26},{"word":"tricky","start":233.26,"end":233.64},{"word":"thing","start":233.64,"end":233.9},{"word":"about","start":233.9,"end":234.16},{"word":"planning","start":234.16,"end":234.64},{"word":"is","start":234.64,"end":235.76},{"word":"that","start":235.76,"end":235.94},{"word":"while","start":235.94,"end":236.22},{"word":"you''re","start":236.22,"end":236.66},{"word":"planning,","start":236.66,"end":237.16},{"word":"chances","start":237.46,"end":238.78},{"word":"are","start":238.78,"end":239.0},{"word":"at","start":239.0,"end":239.14},{"word":"least","start":239.14,"end":239.3},{"word":"one","start":239.3,"end":239.82},{"word":"competitor","start":239.82,"end":240.38},{"word":"is","start":240.38,"end":242.0},{"word":"figuring","start":242.0,"end":242.28},{"word":"out","start":242.28,"end":242.5},{"word":"how","start":242.5,"end":242.62},{"word":"to","start":242.62,"end":242.76},{"word":"win.","start":242.76,"end":243.06}],"textKo":"계획의 까다로운 점은, 네가 계획하는 동안 적어도 경쟁사 하나는 이기는 방법을 찾고 있다는 거야.","listenDifficulty":1},{"index":41,"start":245.28,"end":259.16,"textEn":"When U. S. air carriers were busily planning, you know, what routes to fly and da-da-da, there was this little company in Texas called Southwest that had a strategy for winning.","words":[{"word":"When","start":245.28,"end":245.9},{"word":"U","start":245.9,"end":246.52},{"word":".S.","start":246.52,"end":246.78},{"word":"air","start":247.42,"end":247.56},{"word":"carriers","start":247.56,"end":248.04},{"word":"were","start":248.04,"end":248.26},{"word":"busily","start":248.26,"end":248.62},{"word":"planning,","start":248.62,"end":249.2},{"word":"you","start":249.56,"end":250.36},{"word":"know,","start":250.36,"end":250.46},{"word":"what","start":250.62,"end":250.74},{"word":"routes","start":250.74,"end":251.08},{"word":"to","start":251.08,"end":251.26},{"word":"fly","start":251.26,"end":251.58},{"word":"and","start":251.58,"end":251.94},{"word":"da","start":251.94,"end":252.12},{"word":"-da","start":252.12,"end":252.24},{"word":"-da,","start":252.24,"end":252.42},{"word":"there","start":252.66,"end":253.56},{"word":"was","start":253.56,"end":253.7},{"word":"this","start":253.7,"end":253.86},{"word":"little","start":253.86,"end":254.1},{"word":"company","start":254.1,"end":254.5},{"word":"in","start":254.5,"end":255.2},{"word":"Texas","start":255.2,"end":255.52},{"word":"called","start":255.52,"end":255.88},{"word":"Southwest","start":255.88,"end":256.28},{"word":"that","start":256.28,"end":257.4},{"word":"had","start":257.4,"end":257.68},{"word":"a","start":257.68,"end":257.94},{"word":"strategy","start":257.94,"end":258.48},{"word":"for","start":258.48,"end":258.86},{"word":"winning.","start":258.86,"end":259.16}],"textKo":"미국 항공사들이 어떤 노선을 운항할지 열심히 계획하고 있을 때, 텍사스에 사우스웨스트라는 작은 회사가 이기기 위한 전략을 세우고 있었어.","listenDifficulty":1},{"index":42,"start":260.24,"end":265.1,"textEn":"And, you know, at first that looked largely irrelevant because it was tiny.","words":[{"word":"And,","start":260.24,"end":260.86},{"word":"you","start":261.04,"end":261.48},{"word":"know,","start":261.48,"end":261.52},{"word":"at","start":261.58,"end":261.68},{"word":"first","start":261.68,"end":261.96},{"word":"that","start":261.96,"end":262.82},{"word":"looked","start":262.82,"end":263.26},{"word":"largely","start":263.26,"end":263.8},{"word":"irrelevant","start":263.8,"end":264.2},{"word":"because","start":264.2,"end":264.5},{"word":"it","start":264.5,"end":264.68},{"word":"was","start":264.68,"end":264.8},{"word":"tiny.","start":264.8,"end":265.1}],"textKo":"처음에는 너무 작아서 별로 중요하지 않아 보였어.","listenDifficulty":2},{"index":43,"start":265.36,"end":269.22,"textEn":"What Southwest Airlines was aiming for was an outcome.","words":[{"word":"What","start":265.36,"end":265.72},{"word":"Southwest","start":265.72,"end":266.44},{"word":"Airlines","start":266.44,"end":266.76},{"word":"was","start":266.76,"end":267.2},{"word":"aiming","start":267.2,"end":268.0},{"word":"for","start":268.0,"end":268.3},{"word":"was","start":268.3,"end":268.5},{"word":"an","start":268.5,"end":268.66},{"word":"outcome.","start":268.66,"end":269.22}],"textKo":"사우스웨스트 항공이 노리고 있던 건 결과였어.","listenDifficulty":1},{"index":44,"start":270.02,"end":275.36,"textEn":"What they wanted to be is a substitute for Greyhound.","words":[{"word":"What","start":270.02,"end":270.76},{"word":"they","start":270.76,"end":271.16},{"word":"wanted","start":271.16,"end":271.42},{"word":"to","start":271.42,"end":271.58},{"word":"be","start":271.58,"end":271.78},{"word":"is","start":271.78,"end":272.12},{"word":"a","start":272.12,"end":272.38},{"word":"substitute","start":272.38,"end":273.48},{"word":"for","start":273.48,"end":274.14},{"word":"Greyhound.","start":274.14,"end":275.36}],"textKo":"그들이 되고 싶었던 건 그레이하운드 버스의 대체재였어.","listenDifficulty":2},{"index":45,"start":276.26,"end":285.32,"textEn":"A way more convenient way to get around at a price that wasn''t extraordinarily much greater than a Greyhound bus.","words":[{"word":"A",