INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'en', 'P6FORpg0KVo', '{"videoId":"P6FORpg0KVo","youtubeId":"P6FORpg0KVo","title":"How to Make Learning as Addictive as Social Media | Duolingo''s Luis Von Ahn | TED","channel":"TED","categoryId":"tech","difficulty":"advanced","duration":774,"thumbnail":"https://i.ytimg.com/vi_webp/P6FORpg0KVo/maxresdefault.webp","speechRateWpm":160,"addedAt":"2026-02-16","segmentCount":234,"vocabularyCount":20,"grammarPatternCount":10,"descriptionKo":"듀오링고가 학습을 SNS만큼 중독적으로 만든 비결"}'::jsonb, '{"videoId":"P6FORpg0KVo","segments":[{"index":0,"start":5.36,"end":9.1,"textEn":"So, I''m from Guatemala. This is a public service announcement.","words":[{"word":"So,","start":5.36,"end":5.72},{"word":"I''m","start":5.72,"end":6.08},{"word":"from","start":6.08,"end":6.22},{"word":"Guatemala.","start":6.22,"end":6.68},{"word":"This","start":7.4,"end":7.76},{"word":"is","start":7.76,"end":7.86},{"word":"a","start":7.86,"end":7.98},{"word":"public","start":7.98,"end":8.34},{"word":"service","start":8.34,"end":8.66},{"word":"announcement.","start":8.66,"end":9.1}],"textKo":"","listenDifficulty":1},{"index":1,"start":9.24,"end":15.62,"textEn":"That is where Guatemala is. Also, that is not where they keep the prisoners.","words":[{"word":"That","start":9.24,"end":9.3},{"word":"is","start":9.3,"end":9.42},{"word":"where","start":9.42,"end":9.54},{"word":"Guatemala","start":9.54,"end":9.88},{"word":"is.","start":9.88,"end":10.2},{"word":"Also,","start":13.64,"end":14.0},{"word":"that","start":14.18,"end":14.48},{"word":"is","start":14.48,"end":14.58},{"word":"not","start":14.58,"end":14.72},{"word":"where","start":14.72,"end":14.86},{"word":"they","start":14.86,"end":14.96},{"word":"keep","start":14.96,"end":15.12},{"word":"the","start":15.12,"end":15.24},{"word":"prisoners.","start":15.24,"end":15.62}],"textKo":"과테말라가 여기 있어요. 아, 그리고 죄수들을 가두는 곳은 아니에요.","listenDifficulty":1},{"index":2,"start":15.8,"end":18.62,"textEn":"That is called Guantanamo. Not the same place.","words":[{"word":"That","start":15.8,"end":15.94},{"word":"is","start":15.94,"end":16.04},{"word":"called","start":16.04,"end":16.2},{"word":"Guantanamo.","start":16.2,"end":16.82},{"word":"Not","start":17.68,"end":18.04},{"word":"the","start":18.04,"end":18.16},{"word":"same","start":18.16,"end":18.3},{"word":"place.","start":18.3,"end":18.62}],"textKo":"그건 관타나모라고 해요. 같은 곳이 아니에요.","listenDifficulty":1},{"index":3,"start":19.96,"end":24.44,"textEn":"So Guatemala is right below Mexico. And for the Americans in the audience,","words":[{"word":"So","start":19.96,"end":20.32},{"word":"Guatemala","start":20.32,"end":20.68},{"word":"is","start":20.68,"end":20.84},{"word":"right","start":20.84,"end":20.96},{"word":"below","start":20.96,"end":21.14},{"word":"Mexico.","start":21.14,"end":21.58},{"word":"And","start":22.2,"end":22.56},{"word":"for","start":22.56,"end":22.86},{"word":"the","start":22.86,"end":23.12},{"word":"Americans","start":23.12,"end":23.84},{"word":"in","start":23.84,"end":24.04},{"word":"the","start":24.04,"end":24.14},{"word":"audience,","start":24.14,"end":24.44}],"textKo":"과테말라는 멕시코 바로 아래에 있어요. 그리고 미국인 관객분들을 위해서,","listenDifficulty":1},{"index":4,"start":24.56,"end":26.64,"textEn":"And let this sink in because it really applies in most ways,","words":[{"word":"and","start":24.56,"end":24.64},{"word":"let","start":24.64,"end":24.78},{"word":"this","start":24.78,"end":24.92},{"word":"sink","start":24.92,"end":25.14},{"word":"in","start":25.14,"end":25.3},{"word":"because","start":25.3,"end":25.48},{"word":"it","start":25.48,"end":25.68},{"word":"really","start":25.68,"end":25.88},{"word":"applies","start":25.88,"end":26.16},{"word":"in","start":26.16,"end":26.3},{"word":"most","start":26.3,"end":26.46},{"word":"ways,","start":26.46,"end":26.64}],"textKo":"이걸 좀 새겨두세요, 거의 모든 면에서 해당되니까요,","listenDifficulty":4},{"index":5,"start":26.72,"end":30.52,"textEn":"For the Americans in the audience, you can think of it as Mexico''s Mexico.","words":[{"word":"for","start":26.72,"end":26.8},{"word":"the","start":26.8,"end":26.9},{"word":"Americans","start":26.9,"end":27.3},{"word":"in","start":27.3,"end":27.46},{"word":"the","start":27.46,"end":27.54},{"word":"audience,","start":27.54,"end":27.8},{"word":"you","start":27.8,"end":28.36},{"word":"can","start":28.36,"end":28.48},{"word":"think","start":28.48,"end":28.68},{"word":"of","start":28.68,"end":28.78},{"word":"it","start":28.78,"end":28.88},{"word":"as","start":28.88,"end":29.02},{"word":"Mexico''s","start":29.02,"end":30.04},{"word":"Mexico.","start":30.04,"end":30.52}],"textKo":"미국인 관객분들, 과테말라를 멕시코의 멕시코라고 생각하면 돼요.","listenDifficulty":3},{"index":6,"start":33.14,"end":36.7,"textEn":"Just like the U. S. doesn''t want illegal immigration from Mexico,","words":[{"word":"Just","start":33.14,"end":33.62},{"word":"like","start":33.62,"end":33.82},{"word":"the","start":33.82,"end":33.96},{"word":"U","start":33.96,"end":34.14},{"word":".S.","start":34.14,"end":34.3},{"word":"doesn''t","start":34.46,"end":34.66},{"word":"want","start":34.66,"end":34.92},{"word":"illegal","start":34.92,"end":35.66},{"word":"immigration","start":35.66,"end":36.1},{"word":"from","start":36.1,"end":36.36},{"word":"Mexico,","start":36.36,"end":36.7}],"textKo":"미국이 멕시코로부터의 불법 이민을 원하지 않는 것처럼,","listenDifficulty":3},{"index":7,"start":36.92,"end":41.02,"textEn":"Mexico doesn''t want illegal immigration from Guatemala. It''s a smaller country.","words":[{"word":"Mexico","start":36.92,"end":37.22},{"word":"doesn''t","start":37.22,"end":37.54},{"word":"want","start":37.54,"end":37.64},{"word":"illegal","start":37.64,"end":37.86},{"word":"immigration","start":37.86,"end":38.24},{"word":"from","start":38.24,"end":38.46},{"word":"Guatemala.","start":38.46,"end":38.78},{"word":"It''s","start":39.7,"end":40.18},{"word":"a","start":40.18,"end":40.26},{"word":"smaller","start":40.26,"end":40.62},{"word":"country.","start":40.62,"end":41.02}],"textKo":"멕시코도 과테말라로부터의 불법 이민을 원하지 않아요. 더 작은 나라예요.","listenDifficulty":1},{"index":8,"start":41.38,"end":45.1,"textEn":"It''s a poorer country. And, well, what can I tell you?","words":[{"word":"It''s","start":41.38,"end":41.84},{"word":"a","start":41.84,"end":41.92},{"word":"poorer","start":41.92,"end":42.2},{"word":"country.","start":42.2,"end":42.6},{"word":"And,","start":43.22,"end":43.7},{"word":"well,","start":44.0,"end":44.24},{"word":"what","start":44.34,"end":44.54},{"word":"can","start":44.54,"end":44.66},{"word":"I","start":44.66,"end":44.74},{"word":"tell","start":44.74,"end":44.94},{"word":"you?","start":44.94,"end":45.1}],"textKo":"더 가난한 나라이기도 하고요. 뭐, 어떻게 말해야 할까요?","listenDifficulty":1},{"index":9,"start":45.54,"end":53.4,"textEn":"It has much better Mexican food. Guatemala is a very poor country.","words":[{"word":"It","start":45.54,"end":46.02},{"word":"has","start":46.02,"end":46.14},{"word":"much","start":46.14,"end":46.32},{"word":"better","start":46.32,"end":46.52},{"word":"Mexican","start":46.52,"end":46.84},{"word":"food.","start":46.84,"end":47.14},{"word":"Guatemala","start":51.72,"end":52.2},{"word":"is","start":52.2,"end":52.44},{"word":"a","start":52.44,"end":52.86},{"word":"very","start":52.86,"end":52.98},{"word":"poor","start":52.98,"end":53.14},{"word":"country.","start":53.14,"end":53.4}],"textKo":"멕시코 음식이 훨씬 맛있어요. 과테말라는 정말 가난한 나라예요.","listenDifficulty":1},{"index":10,"start":53.58,"end":55.84,"textEn":"And a lot of people talk about education","words":[{"word":"And","start":53.58,"end":54.0},{"word":"a","start":54.0,"end":54.26},{"word":"lot","start":54.26,"end":54.34},{"word":"of","start":54.34,"end":54.44},{"word":"people","start":54.44,"end":54.66},{"word":"talk","start":54.66,"end":54.9},{"word":"about","start":54.9,"end":55.16},{"word":"education","start":55.16,"end":55.84}],"textKo":"그리고 많은 사람들이 교육에 대해 이야기해요.","listenDifficulty":3},{"index":11,"start":55.84,"end":58.46,"textEn":"As something that brings equality to different social classes.","words":[{"word":"as","start":55.84,"end":56.22},{"word":"something","start":56.22,"end":56.44},{"word":"that","start":56.44,"end":56.58},{"word":"brings","start":56.58,"end":56.82},{"word":"equality","start":56.82,"end":57.36},{"word":"to","start":57.36,"end":57.54},{"word":"different","start":57.54,"end":57.76},{"word":"social","start":57.76,"end":58.04},{"word":"classes.","start":58.04,"end":58.46}],"textKo":"다른 사회 계층 간에 평등을 가져다주는 것으로요.","listenDifficulty":2},{"index":12,"start":58.68,"end":61.64,"textEn":"But I always saw it as the opposite, as something that brings inequality.","words":[{"word":"But","start":58.68,"end":59.02},{"word":"I","start":59.02,"end":59.12},{"word":"always","start":59.12,"end":59.28},{"word":"saw","start":59.28,"end":59.42},{"word":"it","start":59.42,"end":59.48},{"word":"as","start":59.48,"end":59.58},{"word":"the","start":59.58,"end":59.68},{"word":"opposite,","start":59.68,"end":59.94},{"word":"as","start":60.46,"end":60.54},{"word":"something","start":60.54,"end":60.68},{"word":"that","start":60.68,"end":60.8},{"word":"brings","start":60.8,"end":61.06},{"word":"inequality.","start":61.06,"end":61.64}],"textKo":"하지만 저는 항상 반대라고 봤어요, 불평등을 만드는 것으로요.","listenDifficulty":3},{"index":13,"start":62.18,"end":64.92,"textEn":"Because what happens in practice is that people who have a lot of money","words":[{"word":"Because","start":62.18,"end":62.58},{"word":"what","start":62.58,"end":62.74},{"word":"happens","start":62.74,"end":63.04},{"word":"in","start":63.04,"end":63.18},{"word":"practice","start":63.18,"end":63.52},{"word":"is","start":63.52,"end":63.8},{"word":"that","start":63.8,"end":63.9},{"word":"people","start":63.9,"end":64.1},{"word":"who","start":64.1,"end":64.24},{"word":"have","start":64.24,"end":64.4},{"word":"a","start":64.4,"end":64.5},{"word":"lot","start":64.5,"end":64.6},{"word":"of","start":64.6,"end":64.7},{"word":"money","start":64.7,"end":64.92}],"textKo":"왜냐하면 실제로 일어나는 일은, 돈이 많은 사람들은","listenDifficulty":3},{"index":14,"start":64.92,"end":67.28,"textEn":"Can buy themselves a really good education","words":[{"word":"can","start":64.92,"end":65.66},{"word":"buy","start":65.66,"end":65.84},{"word":"themselves","start":65.84,"end":66.14},{"word":"a","start":66.14,"end":66.4},{"word":"really","start":66.4,"end":66.66},{"word":"good","start":66.66,"end":66.84},{"word":"education","start":66.84,"end":67.28}],"textKo":"정말 좋은 교육을 살 수 있고","listenDifficulty":1},{"index":15,"start":67.28,"end":70.78,"textEn":"And therefore continue having a lot of money, whereas people who don''t have very much money","words":[{"word":"and","start":67.28,"end":67.6},{"word":"therefore","start":67.6,"end":67.78},{"word":"continue","start":67.78,"end":68.1},{"word":"having","start":68.1,"end":68.3},{"word":"a","start":68.3,"end":68.46},{"word":"lot","start":68.46,"end":68.54},{"word":"of","start":68.54,"end":68.62},{"word":"money,","start":68.62,"end":68.8},{"word":"whereas","start":69.34,"end":69.56},{"word":"people","start":69.56,"end":69.78},{"word":"who","start":69.78,"end":69.9},{"word":"don''t","start":69.9,"end":70.04},{"word":"have","start":70.04,"end":70.14},{"word":"very","start":70.14,"end":70.3},{"word":"much","start":70.3,"end":70.5},{"word":"money","start":70.5,"end":70.78}],"textKo":"그래서 계속 많은 돈을 벌 수 있는 반면, 돈이 별로 없는 사람들은","listenDifficulty":3},{"index":16,"start":71.38,"end":73.94,"textEn":"Barely learn how to read and write and therefore never make a lot of money.","words":[{"word":"barely","start":71.38,"end":71.78},{"word":"learn","start":71.78,"end":72.0},{"word":"how","start":72.0,"end":72.1},{"word":"to","start":72.1,"end":72.2},{"word":"read","start":72.2,"end":72.32},{"word":"and","start":72.32,"end":72.44},{"word":"write","start":72.44,"end":72.64},{"word":"and","start":72.64,"end":72.98},{"word":"therefore","start":72.98,"end":73.16},{"word":"never","start":73.16,"end":73.36},{"word":"make","start":73.36,"end":73.54},{"word":"a","start":73.54,"end":73.66},{"word":"lot","start":73.66,"end":73.72},{"word":"of","start":73.72,"end":73.8},{"word":"money.","start":73.8,"end":73.94}],"textKo":"겨우 읽고 쓰는 법만 배우고 그래서 절대 많은 돈을 벌지 못해요.","listenDifficulty":3},{"index":17,"start":74.02,"end":76.18,"textEn":"And this is especially true in poor countries.","words":[{"word":"And","start":74.02,"end":74.06},{"word":"this","start":74.06,"end":74.16},{"word":"is","start":74.16,"end":74.28},{"word":"especially","start":74.28,"end":74.72},{"word":"true","start":74.72,"end":75.1},{"word":"in","start":75.1,"end":75.66},{"word":"poor","start":75.66,"end":75.86},{"word":"countries.","start":75.86,"end":76.18}],"textKo":"그리고 이건 가난한 나라에서 특히 심해요.","listenDifficulty":2},{"index":18,"start":77.34,"end":80.78,"textEn":"Now, I was fortunate that I received a rich person''s education,","words":[{"word":"Now,","start":77.34,"end":77.74},{"word":"I","start":77.74,"end":78.14},{"word":"was","start":78.14,"end":78.28},{"word":"fortunate","start":78.28,"end":78.66},{"word":"that","start":78.66,"end":78.88},{"word":"I","start":78.88,"end":78.96},{"word":"received","start":78.96,"end":79.44},{"word":"a","start":79.44,"end":79.7},{"word":"rich","start":79.7,"end":79.9},{"word":"person''s","start":79.9,"end":80.32},{"word":"education,","start":80.32,"end":80.78}],"textKo":"저는 운 좋게도 부자들이 받는 수준의 교육을 받았는데,","listenDifficulty":1},{"index":19,"start":81.32,"end":84.62,"textEn":"Even though I didn''t grow up rich. And it''s because I''m an only child.","words":[{"word":"even","start":81.32,"end":81.72},{"word":"though","start":81.72,"end":81.92},{"word":"I","start":81.92,"end":82.12},{"word":"didn''t","start":82.12,"end":82.3},{"word":"grow","start":82.3,"end":82.46},{"word":"up","start":82.46,"end":82.58},{"word":"rich.","start":82.58,"end":82.82},{"word":"And","start":83.24,"end":83.64},{"word":"it''s","start":83.64,"end":83.76},{"word":"because","start":83.76,"end":83.9},{"word":"I''m","start":83.9,"end":84.08},{"word":"an","start":84.08,"end":84.14},{"word":"only","start":84.14,"end":84.34},{"word":"child.","start":84.34,"end":84.62}],"textKo":"부자집에서 자란 건 아니에요. 제가 외동이거든요.","listenDifficulty":2},{"index":20,"start":85.24,"end":89.38,"textEn":"And my mother, who was a single mother, spent all of her resources on my education.","words":[{"word":"And","start":85.24,"end":85.64},{"word":"my","start":85.64,"end":86.02},{"word":"mother,","start":86.02,"end":86.3},{"word":"who","start":86.4,"end":86.5},{"word":"was","start":86.5,"end":86.62},{"word":"a","start":86.62,"end":86.7},{"word":"single","start":86.7,"end":86.92},{"word":"mother,","start":86.92,"end":87.2},{"word":"spent","start":87.4,"end":87.58},{"word":"all","start":87.58,"end":88.0},{"word":"of","start":88.0,"end":88.14},{"word":"her","start":88.14,"end":88.24},{"word":"resources","start":88.24,"end":88.62},{"word":"on","start":88.62,"end":88.86},{"word":"my","start":88.86,"end":89.0},{"word":"education.","start":89.0,"end":89.38}],"textKo":"그리고 싱글맘이었던 어머니가 모든 자원을 제 교육에 쏟아부으셨어요.","listenDifficulty":2},{"index":21,"start":90.82,"end":93.26,"textEn":"And this allowed me to come to college to the U. S.","words":[{"word":"And","start":90.82,"end":91.22},{"word":"this","start":91.22,"end":91.62},{"word":"allowed","start":91.62,"end":91.82},{"word":"me","start":91.82,"end":91.94},{"word":"to","start":91.94,"end":92.02},{"word":"come","start":92.02,"end":92.16},{"word":"to","start":92.16,"end":92.28},{"word":"college","start":92.28,"end":92.58},{"word":"to","start":92.58,"end":92.74},{"word":"the","start":92.74,"end":92.86},{"word":"U","start":92.86,"end":93.04},{"word":".S.","start":93.04,"end":93.26}],"textKo":"덕분에 미국 대학에 올 수 있었고","listenDifficulty":3},{"index":22,"start":93.36,"end":95.48,"textEn":"And eventually get a Ph. D. in computer science.","words":[{"word":"and","start":93.36,"end":93.7},{"word":"eventually","start":93.7,"end":94.02},{"word":"get","start":94.02,"end":94.2},{"word":"a","start":94.2,"end":94.32},{"word":"Ph","start":94.32,"end":94.6},{"word":".D.","start":94.6,"end":94.74},{"word":"in","start":94.76,"end":94.88},{"word":"computer","start":94.88,"end":95.12},{"word":"science.","start":95.12,"end":95.48}],"textKo":"결국 컴퓨터 과학 박사 학위를 받을 수 있었어요.","listenDifficulty":2},{"index":23,"start":97.04,"end":100.84,"textEn":"Now, because of all of this, about 10 years ago,","words":[{"word":"Now,","start":97.04,"end":97.44},{"word":"because","start":97.44,"end":97.84},{"word":"of","start":97.84,"end":98.0},{"word":"all","start":98.0,"end":98.2},{"word":"of","start":98.2,"end":98.32},{"word":"this,","start":98.32,"end":98.58},{"word":"about","start":99.78,"end":100.18},{"word":"10","start":100.18,"end":100.38},{"word":"years","start":100.38,"end":100.62},{"word":"ago,","start":100.62,"end":100.84}],"textKo":"이 모든 경험 때문에, 약 10년 전에","listenDifficulty":1},{"index":24,"start":101.02,"end":105.24,"textEn":"I decided I wanted to do something that would give equal access to education to everyone.","words":[{"word":"I","start":101.02,"end":101.26},{"word":"decided","start":101.26,"end":101.58},{"word":"I","start":101.58,"end":101.76},{"word":"wanted","start":101.76,"end":101.92},{"word":"to","start":101.92,"end":102.06},{"word":"do","start":102.06,"end":102.18},{"word":"something","start":102.18,"end":102.52},{"word":"that","start":102.52,"end":102.72},{"word":"would","start":102.72,"end":102.84},{"word":"give","start":102.84,"end":103.02},{"word":"equal","start":103.02,"end":103.44},{"word":"access","start":103.44,"end":103.78},{"word":"to","start":103.78,"end":104.0},{"word":"education","start":104.0,"end":104.42},{"word":"to","start":104.42,"end":104.9},{"word":"everyone.","start":104.9,"end":105.24}],"textKo":"모두에게 교육에 대한 평등한 접근을 제공하는 일을 하고 싶다고 결심했어요.","listenDifficulty":3},{"index":25,"start":105.82,"end":108.2,"textEn":"Oh, by the way, this is what I want to talk to you about today,","words":[{"word":"Oh,","start":105.82,"end":106.22},{"word":"by","start":106.22,"end":106.34},{"word":"the","start":106.34,"end":106.4},{"word":"way,","start":106.4,"end":106.5},{"word":"this","start":106.82,"end":107.02},{"word":"is","start":107.02,"end":107.1},{"word":"what","start":107.1,"end":107.2},{"word":"I","start":107.2,"end":107.28},{"word":"want","start":107.28,"end":107.36},{"word":"to","start":107.36,"end":107.44},{"word":"talk","start":107.44,"end":107.58},{"word":"to","start":107.58,"end":107.7},{"word":"you","start":107.7,"end":107.76},{"word":"about","start":107.76,"end":107.94},{"word":"today,","start":107.94,"end":108.2}],"textKo":"아, 참고로 이게 오늘 여러분에게 하고 싶은 이야기예요,","listenDifficulty":3},{"index":26,"start":108.2,"end":110.22,"textEn":"Giving equal access to education to everyone.","words":[{"word":"giving","start":108.2,"end":108.7},{"word":"equal","start":108.7,"end":109.08},{"word":"access","start":109.08,"end":109.28},{"word":"to","start":109.28,"end":109.46},{"word":"education","start":109.46,"end":109.82},{"word":"to","start":109.82,"end":109.98},{"word":"everyone.","start":109.98,"end":110.22}],"textKo":"모두에게 교육에 대한 평등한 접근을 주는 것이요.","listenDifficulty":2},{"index":27,"start":111.08,"end":113.98,"textEn":"At the time, I was a professor of computer science","words":[{"word":"At","start":111.08,"end":111.52},{"word":"the","start":111.52,"end":111.64},{"word":"time,","start":111.64,"end":111.88},{"word":"I","start":112.1,"end":112.7},{"word":"was","start":112.7,"end":112.84},{"word":"a","start":112.84,"end":112.94},{"word":"professor","start":112.94,"end":113.2},{"word":"of","start":113.2,"end":113.36},{"word":"computer","start":113.36,"end":113.64},{"word":"science","start":113.64,"end":113.98}],"textKo":"당시 저는 카네기 멜론 대학교에서 컴퓨터 과학 교수였고,","listenDifficulty":2},{"index":28,"start":113.98,"end":118.04,"textEn":"At Carnegie Mellon University, and I decided to work on this","words":[{"word":"at","start":113.98,"end":114.14},{"word":"Carnegie","start":114.14,"end":114.38},{"word":"Mellon","start":114.38,"end":114.66},{"word":"University,","start":114.66,"end":115.04},{"word":"and","start":116.06,"end":116.5},{"word":"I","start":116.5,"end":116.94},{"word":"decided","start":116.94,"end":117.28},{"word":"to","start":117.28,"end":117.46},{"word":"work","start":117.46,"end":117.66},{"word":"on","start":117.66,"end":117.8},{"word":"this","start":117.8,"end":118.04}],"textKo":"제 박사 과정 학생 세베린과 함께 이 일을 하기로 했어요.","listenDifficulty":1},{"index":29,"start":118.04,"end":122.16,"textEn":"With my Ph. D. student, Severin. The way my brain works,","words":[{"word":"with","start":118.04,"end":118.44},{"word":"my","start":118.44,"end":118.72},{"word":"Ph","start":118.72,"end":119.02},{"word":".D.","start":119.02,"end":119.2},{"word":"student,","start":119.3,"end":119.5},{"word":"Severin.","start":119.64,"end":119.9},{"word":"The","start":120.84,"end":121.28},{"word":"way","start":121.28,"end":121.38},{"word":"my","start":121.38,"end":121.52},{"word":"brain","start":121.52,"end":121.78},{"word":"works,","start":121.78,"end":122.16}],"textKo":"제 사고 방식으로는, 교육 전체는 너무 광범위한 문제예요.","listenDifficulty":1},{"index":30,"start":122.38,"end":124.8,"textEn":"All of education, is just too general of a problem.","words":[{"word":"all","start":122.38,"end":122.58},{"word":"of","start":122.58,"end":122.68},{"word":"education,","start":122.68,"end":123.06},{"word":"is","start":123.24,"end":123.46},{"word":"just","start":123.46,"end":123.74},{"word":"too","start":123.74,"end":124.02},{"word":"general","start":124.02,"end":124.3},{"word":"of","start":124.3,"end":124.46},{"word":"a","start":124.46,"end":124.54},{"word":"problem.","start":124.54,"end":124.8}],"textKo":"그래서 한 가지를 가르치는 것부터 시작하자고 결정했어요.","listenDifficulty":2},{"index":31,"start":125.32,"end":128.14,"textEn":"So I decided, let''s start by teaching one thing.","words":[{"word":"So","start":125.32,"end":125.76},{"word":"I","start":125.76,"end":125.88},{"word":"decided,","start":125.88,"end":126.22},{"word":"let''s","start":126.52,"end":126.9},{"word":"start","start":126.9,"end":127.08},{"word":"by","start":127.08,"end":127.24},{"word":"teaching","start":127.24,"end":127.5},{"word":"one","start":127.5,"end":127.84},{"word":"thing.","start":127.84,"end":128.14}],"textKo":"그다음 생각하기 시작했어요, 그럼 뭘 먼저 가르칠까?","listenDifficulty":1},{"index":32,"start":128.7,"end":131.02,"textEn":"And then I started thinking, OK, well, what should we teach first?","words":[{"word":"And","start":128.7,"end":129.12},{"word":"then","start":129.12,"end":129.2},{"word":"I","start":129.2,"end":129.3},{"word":"started","start":129.3,"end":129.48},{"word":"thinking,","start":129.48,"end":129.7},{"word":"OK,","start":129.88,"end":129.98},{"word":"well,","start":130.04,"end":130.14},{"word":"what","start":130.2,"end":130.3},{"word":"should","start":130.3,"end":130.44},{"word":"we","start":130.44,"end":130.54},{"word":"teach","start":130.54,"end":130.74},{"word":"first?","start":130.74,"end":131.02}],"textKo":"수학을 가르칠까? 우리 둘 다 수학을 정말 좋아하거든요.","listenDifficulty":3},{"index":33,"start":131.54,"end":133.76,"textEn":"Should we teach math? I mean, we both love math.","words":[{"word":"Should","start":131.54,"end":131.76},{"word":"we","start":131.76,"end":131.88},{"word":"teach","start":131.88,"end":132.0},{"word":"math?","start":132.0,"end":132.4},{"word":"I","start":132.62,"end":132.78},{"word":"mean,","start":132.78,"end":132.84},{"word":"we","start":132.92,"end":133.02},{"word":"both","start":133.02,"end":133.2},{"word":"love","start":133.2,"end":133.42},{"word":"math.","start":133.42,"end":133.76}],"textKo":"저와 공동 창업자 둘 다 수학을 좋아해요. 그런데 수학을 하기로 하지는 않았어요.","listenDifficulty":2},{"index":34,"start":133.98,"end":139.6,"textEn":"Me and my co-founder, we both love math. And, you know, we didn''t decide to do math.","words":[{"word":"Me","start":133.98,"end":134.36},{"word":"and","start":134.36,"end":134.46},{"word":"my","start":134.46,"end":134.58},{"word":"co","start":134.58,"end":134.74},{"word":"-founder,","start":134.74,"end":134.98},{"word":"we","start":135.06,"end":135.14},{"word":"both","start":135.14,"end":135.32},{"word":"love","start":135.32,"end":135.48},{"word":"math.","start":135.48,"end":135.76},{"word":"And,","start":136.2,"end":136.6},{"word":"you","start":136.82,"end":137.06},{"word":"know,","start":137.06,"end":137.08},{"word":"we","start":137.18,"end":137.34},{"word":"didn''t","start":137.34,"end":138.84},{"word":"decide","start":138.84,"end":139.08},{"word":"to","start":139.08,"end":139.22},{"word":"do","start":139.22,"end":139.32},{"word":"math.","start":139.32,"end":139.6}],"textKo":"그러다 생각했어요, 컴퓨터 과학을 가르쳐야 할까.","listenDifficulty":1},{"index":35,"start":139.86,"end":142.04,"textEn":"Then we started thinking, well, maybe we should teach computer science.","words":[{"word":"Then","start":139.86,"end":140.14},{"word":"we","start":140.14,"end":140.36},{"word":"started","start":140.36,"end":140.54},{"word":"thinking,","start":140.54,"end":140.72},{"word":"well,","start":140.78,"end":140.86},{"word":"maybe","start":140.88,"end":141.04},{"word":"we","start":141.04,"end":141.14},{"word":"should","start":141.14,"end":141.22},{"word":"teach","start":141.22,"end":141.4},{"word":"computer","start":141.4,"end":141.66},{"word":"science.","start":141.66,"end":142.04}],"textKo":"하지만 결국, 북미 사람들에게는 놀라울 수 있겠지만,","listenDifficulty":3},{"index":36,"start":142.74,"end":146.46,"textEn":"But eventually, and this may be surprising to people in North America,","words":[{"word":"But","start":142.74,"end":143.14},{"word":"eventually,","start":143.14,"end":143.54},{"word":"and","start":144.34,"end":144.74},{"word":"this","start":144.74,"end":144.88},{"word":"may","start":144.88,"end":145.06},{"word":"be","start":145.06,"end":145.14},{"word":"surprising","start":145.14,"end":145.56},{"word":"to","start":145.56,"end":145.72},{"word":"people","start":145.72,"end":145.9},{"word":"in","start":145.9,"end":146.02},{"word":"North","start":146.02,"end":146.16},{"word":"America,","start":146.16,"end":146.46}],"textKo":"결국 시작하기에 가장 좋은 과목은","listenDifficulty":1},{"index":37,"start":146.64,"end":149.14,"textEn":"Eventually we decided that the best subject to start with","words":[{"word":"eventually","start":146.64,"end":147.06},{"word":"we","start":147.06,"end":147.26},{"word":"decided","start":147.26,"end":147.62},{"word":"that","start":147.62,"end":147.86},{"word":"the","start":147.86,"end":148.08},{"word":"best","start":148.08,"end":148.28},{"word":"subject","start":148.28,"end":148.56},{"word":"to","start":148.56,"end":148.74},{"word":"start","start":148.74,"end":148.94},{"word":"with","start":148.94,"end":149.14}],"textKo":"외국어를 가르치는 것이라고 결정했어요. 이유를 말씀드릴게요.","listenDifficulty":2},{"index":38,"start":149.14,"end":153.22,"textEn":"Was teaching foreign languages. And let me tell you why.","words":[{"word":"was","start":149.14,"end":149.86},{"word":"teaching","start":149.86,"end":150.08},{"word":"foreign","start":150.08,"end":150.4},{"word":"languages.","start":150.4,"end":150.82},{"word":"And","start":151.66,"end":152.06},{"word":"let","start":152.06,"end":152.18},{"word":"me","start":152.18,"end":152.26},{"word":"tell","start":152.26,"end":152.42},{"word":"you","start":152.42,"end":152.62},{"word":"why.","start":152.62,"end":153.22}],"textKo":"여러 가지 이유가 있어요. 하나는 엄청나게 많은 대상이 있다는 거예요.","listenDifficulty":1},{"index":39,"start":153.38,"end":157.58,"textEn":"There''s a number of reasons. One of them is that there''s a huge audience for it.","words":[{"word":"There''s","start":153.38,"end":153.56},{"word":"a","start":153.56,"end":153.64},{"word":"number","start":153.64,"end":153.82},{"word":"of","start":153.82,"end":153.96},{"word":"reasons.","start":153.96,"end":154.22},{"word":"One","start":155.06,"end":155.46},{"word":"of","start":155.46,"end":155.56},{"word":"them","start":155.56,"end":155.7},{"word":"is","start":155.7,"end":156.08},{"word":"that","start":156.08,"end":156.24},{"word":"there''s","start":156.24,"end":156.5},{"word":"a","start":156.5,"end":156.58},{"word":"huge","start":156.58,"end":156.84},{"word":"audience","start":156.84,"end":157.14},{"word":"for","start":157.14,"end":157.46},{"word":"it.","start":157.46,"end":157.58}],"textKo":"전 세계에서 약 20억 명의 사람들이 외국어를 배우고 있어요,","listenDifficulty":2},{"index":40,"start":157.74,"end":160.42,"textEn":"There''s about two billion people in the world learning a foreign language,","words":[{"word":"There''s","start":157.74,"end":157.92},{"word":"about","start":157.92,"end":158.46},{"word":"two","start":158.46,"end":158.72},{"word":"billion","start":158.72,"end":159.02},{"word":"people","start":159.02,"end":159.26},{"word":"in","start":159.26,"end":159.38},{"word":"the","start":159.38,"end":159.44},{"word":"world","start":159.44,"end":159.58},{"word":"learning","start":159.58,"end":159.82},{"word":"a","start":159.82,"end":159.92},{"word":"foreign","start":159.92,"end":160.1},{"word":"language,","start":160.1,"end":160.42}],"textKo":"학교 안에서도 밖에서도요. 참고로 이 사람들 대부분은","listenDifficulty":2},{"index":41,"start":160.7,"end":164.22,"textEn":"Both in school and outside of schools. Most of these people, by the way,","words":[{"word":"both","start":160.7,"end":161.18},{"word":"in","start":161.18,"end":161.4},{"word":"school","start":161.4,"end":161.72},{"word":"and","start":161.72,"end":161.94},{"word":"outside","start":161.94,"end":162.22},{"word":"of","start":162.22,"end":162.4},{"word":"schools.","start":162.4,"end":162.66},{"word":"Most","start":163.06,"end":163.46},{"word":"of","start":163.46,"end":163.54},{"word":"these","start":163.54,"end":163.68},{"word":"people,","start":163.68,"end":163.9},{"word":"by","start":163.98,"end":164.08},{"word":"the","start":164.08,"end":164.12},{"word":"way,","start":164.12,"end":164.22}],"textKo":"영어를 배우고 있어요. 약 80%가 영어를 배우고 있어요.","listenDifficulty":2},{"index":42,"start":164.22,"end":166.98,"textEn":"Are learning English. About 80% of them are learning English.","words":[{"word":"are","start":164.22,"end":164.46},{"word":"learning","start":164.46,"end":164.68},{"word":"English.","start":164.68,"end":165.04},{"word":"About","start":165.32,"end":165.52},{"word":"80","start":165.52,"end":165.74},{"word":"%","start":165.74,"end":165.98},{"word":"of","start":165.98,"end":166.14},{"word":"them","start":166.14,"end":166.26},{"word":"are","start":166.26,"end":166.48},{"word":"learning","start":166.48,"end":166.68},{"word":"English.","start":166.68,"end":166.98}],"textKo":"이 이상한 지도에서, 초록색으로 표시된 나라들은","listenDifficulty":2},{"index":43,"start":167.14,"end":169.42,"textEn":"In this weird map right here, all the countries in green","words":[{"word":"In","start":167.14,"end":167.32},{"word":"this","start":167.32,"end":167.44},{"word":"weird","start":167.44,"end":167.72},{"word":"map","start":167.72,"end":168.0},{"word":"right","start":168.0,"end":168.12},{"word":"here,","start":168.12,"end":168.3},{"word":"all","start":168.4,"end":168.48},{"word":"the","start":168.48,"end":168.6},{"word":"countries","start":168.6,"end":168.88},{"word":"in","start":168.88,"end":169.1},{"word":"green","start":169.1,"end":169.42}],"textKo":"주로 영어를 배우고 있는 나라들이에요.","listenDifficulty":3},{"index":44,"start":169.42,"end":172.86,"textEn":"Are countries in which people are predominantly learning English.","words":[{"word":"are","start":169.42,"end":170.24},{"word":"countries","start":170.24,"end":170.58},{"word":"in","start":170.58,"end":170.82},{"word":"which","start":170.82,"end":170.98},{"word":"people","start":170.98,"end":171.4},{"word":"are","start":171.4,"end":171.54},{"word":"predominantly","start":171.54,"end":171.98},{"word":"learning","start":171.98,"end":172.42},{"word":"English.","start":172.42,"end":172.86}],"textKo":"그 이유는 영어가 정말로 여러분의 삶을 바꿀 수 있기 때문이에요.","listenDifficulty":1},{"index":45,"start":173.12,"end":176.8,"textEn":"And the reason for that is because English can truly transform your life.","words":[{"word":"And","start":173.12,"end":173.56},{"word":"the","start":173.56,"end":173.68},{"word":"reason","start":173.68,"end":173.92},{"word":"for","start":173.92,"end":174.12},{"word":"that","start":174.12,"end":174.32},{"word":"is","start":174.32,"end":174.74},{"word":"because","start":174.74,"end":175.02},{"word":"English","start":175.02,"end":175.7},{"word":"can","start":175.7,"end":175.88},{"word":"truly","start":175.88,"end":176.06},{"word":"transform","start":176.06,"end":176.38},{"word":"your","start":176.38,"end":176.58},{"word":"life.","start":176.58,"end":176.8}],"textKo":"세계 대부분의 나라에서 영어 지식은 소득 잠재력을 크게 높일 수 있어요.","listenDifficulty":2},{"index":46,"start":177.08,"end":181.0,"textEn":"In most countries in the world, knowledge of English can significantly increase your income potential.","words":[{"word":"In","start":177.08,"end":177.3},{"word":"most","start":177.3,"end":177.54},{"word":"countries","start":177.54,"end":177.84},{"word":"in","start":177.84,"end":177.98},{"word":"the","start":177.98,"end":178.06},{"word":"world,","start":178.06,"end":178.26},{"word":"knowledge","start":178.36,"end":178.6},{"word":"of","start":178.6,"end":178.76},{"word":"English","start":178.76,"end":178.98},{"word":"can","start":178.98,"end":179.24},{"word":"significantly","start":179.24,"end":179.86},{"word":"increase","start":179.86,"end":180.28},{"word":"your","start":180.28,"end":180.46},{"word":"income","start":180.46,"end":180.62},{"word":"potential.","start":180.62,"end":181.0}],"textKo":"이것도 우리가 외국어로 시작하기로 한 또 다른 이유예요,","listenDifficulty":2},{"index":47,"start":182.14,"end":184.96,"textEn":"So this is another reason why we decided to start with foreign languages,","words":[{"word":"So","start":182.14,"end":182.58},{"word":"this","start":182.58,"end":182.92},{"word":"is","start":182.92,"end":183.02},{"word":"another","start":183.02,"end":183.3},{"word":"reason","start":183.3,"end":183.56},{"word":"why","start":183.56,"end":183.74},{"word":"we","start":183.74,"end":183.86},{"word":"decided","start":183.86,"end":184.12},{"word":"to","start":184.12,"end":184.26},{"word":"start","start":184.26,"end":184.38},{"word":"with","start":184.38,"end":184.5},{"word":"foreign","start":184.5,"end":184.7},{"word":"languages,","start":184.7,"end":184.96}],"textKo":"다른 언어를 배우면, 특히 영어를 배우면","listenDifficulty":3},{"index":48,"start":185.0,"end":187.04,"textEn":"And it''s because you can directly make more money","words":[{"word":"and","start":185.0,"end":185.14},{"word":"it''s","start":185.14,"end":185.24},{"word":"because","start":185.24,"end":185.4},{"word":"you","start":185.4,"end":185.54},{"word":"can","start":185.54,"end":185.66},{"word":"directly","start":185.66,"end":186.14},{"word":"make","start":186.14,"end":186.44},{"word":"more","start":186.44,"end":186.74},{"word":"money","start":186.74,"end":187.04}],"textKo":"직접적으로 더 많은 돈을 벌 수 있기 때문이에요.","listenDifficulty":2},{"index":49,"start":187.04,"end":189.54,"textEn":"If you learn another language, in particular, English.","words":[{"word":"if","start":187.04,"end":187.6},{"word":"you","start":187.6,"end":187.68},{"word":"learn","start":187.68,"end":187.94},{"word":"another","start":187.94,"end":188.4},{"word":"language,","start":188.4,"end":188.66},{"word":"in","start":188.72,"end":188.8},{"word":"particular,","start":188.8,"end":189.12},{"word":"English.","start":189.14,"end":189.54}],"textKo":"이건 다른 많은 과목과는 꽤 달라요. 예를 들어 수학을 보면,","listenDifficulty":1},{"index":50,"start":189.92,"end":192.78,"textEn":"And see, this is pretty different than many other subjects. For example, take math.","words":[{"word":"And","start":189.92,"end":190.06},{"word":"see,","start":190.06,"end":190.22},{"word":"this","start":190.42,"end":190.72},{"word":"is","start":190.72,"end":190.8},{"word":"pretty","start":190.8,"end":190.94},{"word":"different","start":190.94,"end":191.16},{"word":"than","start":191.16,"end":191.3},{"word":"many","start":191.3,"end":191.46},{"word":"other","start":191.46,"end":191.62},{"word":"subjects.","start":191.62,"end":191.9},{"word":"For","start":192.02,"end":192.12},{"word":"example,","start":192.12,"end":192.28},{"word":"take","start":192.38,"end":192.5},{"word":"math.","start":192.5,"end":192.78}],"textKo":"수학의 경우, 수학 지식 자체만으로는 소득 잠재력이 높아지지 않아요,","listenDifficulty":3},{"index":51,"start":193.24,"end":197.08,"textEn":"In the case of math, just knowledge of math does not increase your income potential,","words":[{"word":"In","start":193.24,"end":193.6},{"word":"the","start":193.6,"end":193.66},{"word":"case","start":193.66,"end":193.72},{"word":"of","start":193.72,"end":193.84},{"word":"math,","start":193.84,"end":194.0},{"word":"just","start":194.12,"end":194.24},{"word":"knowledge","start":194.24,"end":194.5},{"word":"of","start":194.5,"end":194.68},{"word":"math","start":194.68,"end":195.0},{"word":"does","start":195.0,"end":195.32},{"word":"not","start":195.32,"end":195.56},{"word":"increase","start":195.56,"end":196.3},{"word":"your","start":196.3,"end":196.5},{"word":"income","start":196.5,"end":196.66},{"word":"potential,","start":196.66,"end":197.08}],"textKo":"왜냐하면 보통 수학을 배운 다음 물리학을 배우고,","listenDifficulty":2},{"index":52,"start":197.3,"end":200.46,"textEn":"Because usually you have to learn math to then learn physics,","words":[{"word":"because","start":197.3,"end":197.78},{"word":"usually","start":197.78,"end":198.28},{"word":"you","start":198.28,"end":198.44},{"word":"have","start":198.44,"end":198.56},{"word":"to","start":198.56,"end":198.66},{"word":"learn","start":198.66,"end":198.82},{"word":"math","start":198.82,"end":199.16},{"word":"to","start":199.16,"end":199.7},{"word":"then","start":199.7,"end":199.86},{"word":"learn","start":199.86,"end":200.06},{"word":"physics,","start":200.06,"end":200.46}],"textKo":"그다음 토목 공학자가 되어야 하거든요. 그렇게 해야 더 많은 돈을 벌어요.","listenDifficulty":2},{"index":53,"start":200.74,"end":202.96,"textEn":"To then become a civil engineer. Like, that''s how you make more money.","words":[{"word":"to","start":200.74,"end":200.96},{"word":"then","start":200.96,"end":201.08},{"word":"become","start":201.08,"end":201.3},{"word":"a","start":201.3,"end":201.44},{"word":"civil","start":201.44,"end":201.62},{"word":"engineer.","start":201.62,"end":201.94},{"word":"Like,","start":202.08,"end":202.16},{"word":"that''s","start":202.2,"end":202.32},{"word":"how","start":202.32,"end":202.4},{"word":"you","start":202.4,"end":202.5},{"word":"make","start":202.5,"end":202.62},{"word":"more","start":202.62,"end":202.76},{"word":"money.","start":202.76,"end":202.96}],"textKo":"반면에 언어의 경우, 웨이터였다가","listenDifficulty":3},{"index":54,"start":203.24,"end":205.96,"textEn":"Whereas with languages, if you were a waiter","words":[{"word":"Whereas","start":203.24,"end":203.6},{"word":"with","start":203.6,"end":204.6},{"word":"languages,","start":204.6,"end":204.92},{"word":"if","start":205.16,"end":205.32},{"word":"you","start":205.32,"end":205.42},{"word":"were","start":205.42,"end":205.54},{"word":"a","start":205.54,"end":205.7},{"word":"waiter","start":205.7,"end":205.96}],"textKo":"영어를 배우면 호텔 웨이터가 될 수 있고","listenDifficulty":1},{"index":55,"start":206.5,"end":208.98,"textEn":"And you learned English, now you can be a waiter at a hotel","words":[{"word":"and","start":206.5,"end":206.86},{"word":"you","start":206.86,"end":206.96},{"word":"learned","start":206.96,"end":207.12},{"word":"English,","start":207.12,"end":207.52},{"word":"now","start":207.76,"end":207.92},{"word":"you","start":207.92,"end":208.0},{"word":"can","start":208.0,"end":208.08},{"word":"be","start":208.08,"end":208.18},{"word":"a","start":208.18,"end":208.26},{"word":"waiter","start":208.26,"end":208.44},{"word":"at","start":208.44,"end":208.58},{"word":"a","start":208.58,"end":208.64},{"word":"hotel","start":208.64,"end":208.98}],"textKo":"더 많은 돈을 벌 수 있어요. 그래서 우리는 결정했어요,","listenDifficulty":3},{"index":56,"start":208.98,"end":212.02,"textEn":"And make more money. So we decided,","words":[{"word":"and","start":208.98,"end":209.46},{"word":"make","start":209.46,"end":209.6},{"word":"more","start":209.6,"end":209.74},{"word":"money.","start":209.74,"end":209.94},{"word":"So","start":211.0,"end":211.36},{"word":"we","start":211.36,"end":211.72},{"word":"decided,","start":211.72,"end":212.02}],"textKo":"언어 교육부터 시작하자고요. 그리고 우리는 스스로를 설득했어요,","listenDifficulty":1},{"index":57,"start":212.26,"end":215.88,"textEn":"Well, let''s get started by teaching languages. Now, we also convinced ourselves","words":[{"word":"well,","start":212.26,"end":212.36},{"word":"let''s","start":212.42,"end":212.56},{"word":"get","start":212.56,"end":212.66},{"word":"started","start":212.66,"end":212.84},{"word":"by","start":212.84,"end":212.96},{"word":"teaching","start":212.96,"end":213.18},{"word":"languages.","start":213.18,"end":213.52},{"word":"Now,","start":214.16,"end":214.36},{"word":"we","start":214.5,"end":214.88},{"word":"also","start":214.88,"end":215.06},{"word":"convinced","start":215.06,"end":215.5},{"word":"ourselves","start":215.5,"end":215.88}],"textKo":"정말로 많은 사람들에게 도달할 수 있는 유일한 방법은","listenDifficulty":1},{"index":58,"start":215.88,"end":220.04,"textEn":"That the only way to really reach a lot of people","words":[{"word":"that","start":215.88,"end":216.76},{"word":"the","start":216.76,"end":217.52},{"word":"only","start":217.52,"end":217.74},{"word":"way","start":217.74,"end":217.94},{"word":"to","start":217.94,"end":218.28},{"word":"really","start":218.28,"end":218.88},{"word":"reach","start":218.88,"end":219.2},{"word":"a","start":219.2,"end":219.42},{"word":"lot","start":219.42,"end":219.62},{"word":"of","start":219.62,"end":219.76},{"word":"people","start":219.76,"end":220.04}],"textKo":"휴대폰을 사용하는 거라고요,","listenDifficulty":1},{"index":59,"start":220.04,"end":222.36,"textEn":"Was by using a mobile phone,","words":[{"word":"was","start":220.04,"end":220.84},{"word":"by","start":220.84,"end":221.48},{"word":"using","start":221.48,"end":221.68},{"word":"a","start":221.68,"end":221.84},{"word":"mobile","start":221.84,"end":222.06},{"word":"phone,","start":222.06,"end":222.36}],"textKo":"특히 스마트폰이요. 전 세계에 학교를 짓는 건","listenDifficulty":1},{"index":60,"start":222.52,"end":225.74,"textEn":"Or a smartphone in particular. See, building schools all over the world","words":[{"word":"or","start":222.52,"end":222.58},{"word":"a","start":222.58,"end":222.86},{"word":"smartphone","start":222.86,"end":223.12},{"word":"in","start":223.12,"end":223.32},{"word":"particular.","start":223.32,"end":223.68},{"word":"See,","start":224.34,"end":224.5},{"word":"building","start":224.6,"end":224.82},{"word":"schools","start":224.82,"end":225.12},{"word":"all","start":225.12,"end":225.32},{"word":"over","start":225.32,"end":225.44},{"word":"the","start":225.44,"end":225.52},{"word":"world","start":225.52,"end":225.74}],"textKo":"너무 비싸요. 반면에","listenDifficulty":2},{"index":61,"start":225.74,"end":228.44,"textEn":"Is simply too expensive. On the other hand,","words":[{"word":"is","start":225.74,"end":226.0},{"word":"simply","start":226.0,"end":226.16},{"word":"too","start":226.16,"end":226.3},{"word":"expensive.","start":226.3,"end":226.7},{"word":"On","start":227.52,"end":227.96},{"word":"the","start":227.96,"end":228.06},{"word":"other","start":228.06,"end":228.2},{"word":"hand,","start":228.2,"end":228.44}],"textKo":"세계 인구의 대부분은 이미 스마트폰을 가지고 있고,","listenDifficulty":1},{"index":62,"start":228.96,"end":231.46,"textEn":"Most of the world''s population already has access to a smartphone,","words":[{"word":"most","start":228.96,"end":229.4},{"word":"of","start":229.4,"end":229.5},{"word":"the","start":229.5,"end":229.58},{"word":"world''s","start":229.58,"end":229.78},{"word":"population","start":229.78,"end":230.14},{"word":"already","start":230.14,"end":230.42},{"word":"has","start":230.42,"end":230.64},{"word":"access","start":230.64,"end":230.86},{"word":"to","start":230.86,"end":231.02},{"word":"a","start":231.02,"end":231.1},{"word":"smartphone,","start":231.1,"end":231.46}],"textKo":"그 비율은 앞으로 더 늘어날 거예요.","listenDifficulty":3},{"index":63,"start":231.62,"end":233.68,"textEn":"And the trend is that that fraction is only going to increase.","words":[{"word":"and","start":231.62,"end":231.78},{"word":"the","start":231.78,"end":231.92},{"word":"trend","start":231.92,"end":232.08},{"word":"is","start":232.08,"end":232.24},{"word":"that","start":232.24,"end":232.36},{"word":"that","start":232.36,"end":232.48},{"word":"fraction","start":232.48,"end":232.74},{"word":"is","start":232.74,"end":232.88},{"word":"only","start":232.88,"end":233.04},{"word":"going","start":233.04,"end":233.2},{"word":"to","start":233.2,"end":233.34},{"word":"increase.","start":233.34,"end":233.68}],"textKo":"그래서 당시 우리는 외국어를 배울 수 있는 방법을 만들기로 했어요,","listenDifficulty":3},{"index":64,"start":234.9,"end":239.56,"textEn":"So we decided at the time that we would make a way to learn foreign languages","words":[{"word":"So","start":234.9,"end":235.34},{"word":"we","start":235.34,"end":235.78},{"word":"decided","start":235.78,"end":236.12},{"word":"at","start":236.12,"end":236.28},{"word":"the","start":236.28,"end":236.4},{"word":"time","start":236.4,"end":236.62},{"word":"that","start":236.62,"end":236.9},{"word":"we","start":236.9,"end":237.08},{"word":"would","start":237.08,"end":237.26},{"word":"make","start":237.26,"end":237.94},{"word":"a","start":237.94,"end":238.16},{"word":"way","start":238.16,"end":238.44},{"word":"to","start":238.44,"end":238.66},{"word":"learn","start":238.66,"end":238.84},{"word":"foreign","start":238.84,"end":239.18},{"word":"languages","start":239.18,"end":239.56}],"textKo":"모두가 접근 가능한 휴대폰으로요.","listenDifficulty":3},{"index":65,"start":239.56,"end":242.1,"textEn":"On a mobile phone that was accessible to everyone.","words":[{"word":"on","start":239.56,"end":239.92},{"word":"a","start":239.92,"end":240.02},{"word":"mobile","start":240.02,"end":240.2},{"word":"phone","start":240.2,"end":240.5},{"word":"that","start":240.5,"end":240.86},{"word":"was","start":240.86,"end":241.0},{"word":"accessible","start":241.0,"end":241.44},{"word":"to","start":241.44,"end":241.66},{"word":"everyone.","start":241.66,"end":242.1}],"textKo":"그리고 이름을 듀오링고라고 지었어요.","listenDifficulty":2},{"index":66,"start":242.1,"end":244.14,"textEn":"And then we called it Duolingo.","words":[{"word":"And","start":242.1,"end":242.74},{"word":"then","start":242.74,"end":242.9},{"word":"we","start":242.9,"end":243.34},{"word":"called","start":243.34,"end":243.54},{"word":"it","start":243.54,"end":243.66},{"word":"Duolingo.","start":243.66,"end":244.14}],"textKo":"감사합니다. 정말로 모두에게 접근 가능하려면,","listenDifficulty":1},{"index":67,"start":244.78,"end":252.4,"textEn":"Thank you. Now, in order to truly be accessible to everyone,","words":[{"word":"Thank","start":244.78,"end":245.18},{"word":"you.","start":245.18,"end":245.3},{"word":"Now,","start":249.52,"end":249.92},{"word":"in","start":249.92,"end":250.32},{"word":"order","start":250.32,"end":250.52},{"word":"to","start":250.52,"end":250.72},{"word":"truly","start":250.72,"end":251.36},{"word":"be","start":251.36,"end":251.52},{"word":"accessible","start":251.52,"end":251.88},{"word":"to","start":251.88,"end":252.1},{"word":"everyone,","start":252.1,"end":252.4}],"textKo":"부자든 가난한 사람이든, 듀오링고는 프리미엄 모델을 사용해요.","listenDifficulty":2},{"index":68,"start":252.48,"end":255.06,"textEn":"Rich and poor, Duolingo uses a freemium model","words":[{"word":"rich","start":252.48,"end":252.6},{"word":"and","start":252.6,"end":252.72},{"word":"poor,","start":252.72,"end":252.98},{"word":"Duolingo","start":253.14,"end":253.52},{"word":"uses","start":253.52,"end":253.84},{"word":"a","start":253.84,"end":254.22},{"word":"freemium","start":254.22,"end":254.72},{"word":"model","start":254.72,"end":255.06}],"textKo":"자체적으로 운영하기 위해서요. 그게 무슨 뜻이냐면","listenDifficulty":1},{"index":69,"start":255.06,"end":257.54,"textEn":"To support itself. What that means is that","words":[{"word":"to","start":255.06,"end":255.5},{"word":"support","start":255.5,"end":255.78},{"word":"itself.","start":255.78,"end":256.06},{"word":"What","start":256.42,"end":256.82},{"word":"that","start":256.82,"end":256.94},{"word":"means","start":256.94,"end":257.14},{"word":"is","start":257.14,"end":257.34},{"word":"that","start":257.34,"end":257.54}],"textKo":"돈을 내지 않고도 원하는 만큼 배울 수 있지만,","listenDifficulty":1},{"index":70,"start":257.98,"end":261.24,"textEn":"You can learn as much as you want without ever having to pay,","words":[{"word":"you","start":257.98,"end":258.38},{"word":"can","start":258.38,"end":258.48},{"word":"learn","start":258.48,"end":258.62},{"word":"as","start":258.62,"end":258.84},{"word":"much","start":258.84,"end":259.18},{"word":"as","start":259.18,"end":259.34},{"word":"you","start":259.34,"end":259.46},{"word":"want","start":259.46,"end":259.78},{"word":"without","start":259.78,"end":260.32},{"word":"ever","start":260.32,"end":260.58},{"word":"having","start":260.58,"end":260.8},{"word":"to","start":260.8,"end":260.98},{"word":"pay,","start":260.98,"end":261.24}],"textKo":"돈을 내지 않으면 수업 끝에 광고를 봐야 할 수도 있어요.","listenDifficulty":3},{"index":71,"start":262.12,"end":264.24,"textEn":"But if you don''t pay, you may have to see an ad","words":[{"word":"but","start":262.12,"end":262.52},{"word":"if","start":262.52,"end":262.72},{"word":"you","start":262.72,"end":262.82},{"word":"don''t","start":262.82,"end":262.98},{"word":"pay,","start":262.98,"end":263.2},{"word":"you","start":263.32,"end":263.42},{"word":"may","start":263.42,"end":263.52},{"word":"have","start":263.52,"end":263.64},{"word":"to","start":263.64,"end":263.74},{"word":"see","start":263.74,"end":263.86},{"word":"an","start":263.86,"end":264.02},{"word":"ad","start":264.02,"end":264.24}],"textKo":"광고가 싫으면,","listenDifficulty":3},{"index":72,"start":264.24,"end":266.82,"textEn":"At the end of a lesson. Now, if you don''t like ads,","words":[{"word":"at","start":264.24,"end":264.36},{"word":"the","start":264.36,"end":264.44},{"word":"end","start":264.44,"end":264.52},{"word":"of","start":264.52,"end":264.62},{"word":"a","start":264.62,"end":264.7},{"word":"lesson.","start":264.7,"end":264.94},{"word":"Now,","start":265.56,"end":265.96},{"word":"if","start":266.04,"end":266.06},{"word":"you","start":266.06,"end":266.14},{"word":"don''t","start":266.14,"end":266.34},{"word":"like","start":266.34,"end":266.5},{"word":"ads,","start":266.5,"end":266.82}],"textKo":"구독료를 내서 광고를 끌 수도 있어요.","listenDifficulty":3},{"index":73,"start":266.94,"end":268.96,"textEn":"You can also pay to subscribe to turn off the ads.","words":[{"word":"you","start":266.94,"end":267.04},{"word":"can","start":267.04,"end":267.14},{"word":"also","start":267.14,"end":267.26},{"word":"pay","start":267.26,"end":267.54},{"word":"to","start":267.54,"end":267.72},{"word":"subscribe","start":267.72,"end":268.1},{"word":"to","start":268.1,"end":268.28},{"word":"turn","start":268.28,"end":268.44},{"word":"off","start":268.44,"end":268.56},{"word":"the","start":268.56,"end":268.68},{"word":"ads.","start":268.68,"end":268.96}],"textKo":"그런데 듀오링고 수익의 대부분은","listenDifficulty":3},{"index":74,"start":269.94,"end":272.24,"textEn":"And it turns out that the vast majority","words":[{"word":"And","start":269.94,"end":270.34},{"word":"it","start":270.34,"end":270.72},{"word":"turns","start":270.72,"end":270.9},{"word":"out","start":270.9,"end":271.2},{"word":"that","start":271.2,"end":271.56},{"word":"the","start":271.56,"end":271.68},{"word":"vast","start":271.68,"end":271.92},{"word":"majority","start":271.92,"end":272.24}],"textKo":"광고를 끄기 위해 구독료를 내는 사람들에게서 나와요.","listenDifficulty":2},{"index":75,"start":272.24,"end":275.06,"textEn":"Of the revenue for Duolingo comes from people who pay to subscribe","words":[{"word":"of","start":272.24,"end":272.36},{"word":"the","start":272.36,"end":272.46},{"word":"revenue","start":272.46,"end":272.72},{"word":"for","start":272.72,"end":272.94},{"word":"Duolingo","start":272.94,"end":273.34},{"word":"comes","start":273.34,"end":273.7},{"word":"from","start":273.7,"end":273.86},{"word":"people","start":273.86,"end":274.1},{"word":"who","start":274.1,"end":274.28},{"word":"pay","start":274.28,"end":274.56},{"word":"to","start":274.56,"end":274.72},{"word":"subscribe","start":274.72,"end":275.06}],"textKo":"광고를 끄기 위해 구독료를 내는 사람들은 누구냐면요, 보통은","listenDifficulty":2},{"index":76,"start":275.06,"end":279.32,"textEn":"To turn off the ads. Now, who are these people","words":[{"word":"to","start":275.06,"end":275.2},{"word":"turn","start":275.2,"end":275.34},{"word":"off","start":275.34,"end":275.44},{"word":"the","start":275.44,"end":275.56},{"word":"ads.","start":275.56,"end":275.8},{"word":"Now,","start":278.08,"end":278.52},{"word":"who","start":278.62,"end":278.76},{"word":"are","start":278.76,"end":278.86},{"word":"these","start":278.86,"end":279.04},{"word":"people","start":279.04,"end":279.32}],"textKo":"미국이나 캐나다 같은 부유한 나라의 여유 있는 사람들이에요.","listenDifficulty":1},{"index":77,"start":279.32,"end":282.84,"textEn":"Who pay to subscribe to turn off the ads? Well, they''re usually people,","words":[{"word":"who","start":279.32,"end":279.46},{"word":"pay","start":279.46,"end":279.64},{"word":"to","start":279.64,"end":279.78},{"word":"subscribe","start":279.78,"end":280.06},{"word":"to","start":280.06,"end":280.2},{"word":"turn","start":280.2,"end":280.34},{"word":"off","start":280.34,"end":280.44},{"word":"the","start":280.44,"end":280.54},{"word":"ads?","start":280.54,"end":280.82},{"word":"Well,","start":281.34,"end":281.74},{"word":"they''re","start":281.92,"end":282.08},{"word":"usually","start":282.08,"end":282.48},{"word":"people,","start":282.48,"end":282.84}],"textKo":"구독료를 내지 않는 사람들은 누구냐면요.","listenDifficulty":2},{"index":78,"start":283.42,"end":285.9,"textEn":"Well-off people, in rich countries","words":[{"word":"well","start":283.42,"end":283.86},{"word":"-off","start":283.86,"end":284.08},{"word":"people,","start":284.08,"end":284.4},{"word":"in","start":284.6,"end":285.18},{"word":"rich","start":285.18,"end":285.56},{"word":"countries","start":285.56,"end":285.9}],"textKo":"보통 브라질이나 베트남 같은 가난한 나라에서 와요,","listenDifficulty":1},{"index":79,"start":285.9,"end":288.8,"textEn":"Like the US and Canada, who are the people who don''t pay to subscribe.","words":[{"word":"like","start":285.9,"end":286.1},{"word":"the","start":286.1,"end":286.24},{"word":"US","start":286.24,"end":286.44},{"word":"and","start":286.44,"end":286.6},{"word":"Canada,","start":286.6,"end":286.94},{"word":"who","start":287.12,"end":287.54},{"word":"are","start":287.54,"end":287.64},{"word":"the","start":287.64,"end":287.72},{"word":"people","start":287.72,"end":287.86},{"word":"who","start":287.86,"end":287.98},{"word":"don''t","start":287.98,"end":288.2},{"word":"pay","start":288.2,"end":288.36},{"word":"to","start":288.36,"end":288.52},{"word":"subscribe.","start":288.52,"end":288.8}],"textKo":"아니면 과테말라요. 제가 이 모델에서 좋아하는 건","listenDifficulty":3},{"index":80,"start":288.98,"end":292.36,"textEn":"They usually come from poorer countries like Brazil or Vietnam","words":[{"word":"They","start":288.98,"end":288.98},{"word":"usually","start":288.98,"end":289.24},{"word":"come","start":289.24,"end":289.5},{"word":"from","start":289.5,"end":289.76},{"word":"poorer","start":289.76,"end":290.24},{"word":"countries","start":290.24,"end":290.7},{"word":"like","start":290.7,"end":291.16},{"word":"Brazil","start":291.16,"end":291.88},{"word":"or","start":291.88,"end":292.06},{"word":"Vietnam","start":292.06,"end":292.36}],"textKo":"이것이 부의 재분배의 작은 형태라는 거예요.","listenDifficulty":2},{"index":81,"start":292.36,"end":295.3,"textEn":"Or Guatemala. So what I like about this model","words":[{"word":"or","start":292.36,"end":292.62},{"word":"Guatemala.","start":292.62,"end":292.94},{"word":"So","start":293.7,"end":294.14},{"word":"what","start":294.14,"end":294.24},{"word":"I","start":294.24,"end":294.34},{"word":"like","start":294.34,"end":294.62},{"word":"about","start":294.62,"end":294.78},{"word":"this","start":294.78,"end":295.0},{"word":"model","start":295.0,"end":295.3}],"textKo":"기본적으로 부자들이 모든 사람의 교육비를","listenDifficulty":1},{"index":82,"start":295.3,"end":297.76,"textEn":"Is that it is a small form of wealth redistribution","words":[{"word":"is","start":295.3,"end":295.52},{"word":"that","start":295.52,"end":295.64},{"word":"it","start":295.64,"end":295.72},{"word":"is","start":295.72,"end":295.88},{"word":"a","start":295.88,"end":296.04},{"word":"small","start":296.04,"end":296.44},{"word":"form","start":296.44,"end":296.8},{"word":"of","start":296.8,"end":296.96},{"word":"wealth","start":296.96,"end":297.16},{"word":"redistribution","start":297.16,"end":297.76}],"textKo":"내게 하는 거니까요. 마음에 들어요. 네.","listenDifficulty":2},{"index":83,"start":297.76,"end":300.16,"textEn":"Because we''re basically getting the rich people to pay for the education","words":[{"word":"because","start":297.76,"end":298.1},{"word":"we''re","start":298.1,"end":298.32},{"word":"basically","start":298.32,"end":298.62},{"word":"getting","start":298.62,"end":298.84},{"word":"the","start":298.84,"end":299.0},{"word":"rich","start":299.0,"end":299.1},{"word":"people","start":299.1,"end":299.34},{"word":"to","start":299.34,"end":299.52},{"word":"pay","start":299.52,"end":299.62},{"word":"for","start":299.62,"end":299.72},{"word":"the","start":299.72,"end":299.84},{"word":"education","start":299.84,"end":300.16}],"textKo":"좋죠. 스마트폰으로 많은 사람들에게 도달할 수 있고","listenDifficulty":3},{"index":84,"start":300.16,"end":303.26,"textEn":"Of everyone. So I like that. Yes.","words":[{"word":"of","start":300.16,"end":300.9},{"word":"everyone.","start":300.9,"end":301.18},{"word":"So","start":301.44,"end":301.7},{"word":"I","start":301.7,"end":301.78},{"word":"like","start":301.78,"end":301.92},{"word":"that.","start":301.92,"end":302.12},{"word":"Yes.","start":302.86,"end":303.26}],"textKo":"부자들이 전체 비용을 내게 할 수도 있어요.","listenDifficulty":1},{"index":85,"start":306.54,"end":309.06,"textEn":"It''s great. So with smartphones, we can reach a lot of people","words":[{"word":"It''s","start":306.54,"end":306.94},{"word":"great.","start":306.94,"end":307.1},{"word":"So","start":307.24,"end":307.34},{"word":"with","start":307.34,"end":307.48},{"word":"smartphones,","start":307.48,"end":307.82},{"word":"we","start":308.02,"end":308.2},{"word":"can","start":308.2,"end":308.34},{"word":"reach","start":308.34,"end":308.6},{"word":"a","start":308.6,"end":308.74},{"word":"lot","start":308.74,"end":308.78},{"word":"of","start":308.78,"end":308.86},{"word":"people","start":308.86,"end":309.06}],"textKo":"아주 좋아요. 하지만 스마트폰으로 교육을 전달하려고 하면,","listenDifficulty":3},{"index":86,"start":309.06,"end":311.4,"textEn":"And we can even get the rich people to pay for the whole thing.","words":[{"word":"and","start":309.06,"end":309.4},{"word":"we","start":309.4,"end":309.66},{"word":"can","start":309.66,"end":309.78},{"word":"even","start":309.78,"end":309.88},{"word":"get","start":309.88,"end":310.04},{"word":"the","start":310.04,"end":310.18},{"word":"rich","start":310.18,"end":310.4},{"word":"people","start":310.4,"end":310.62},{"word":"to","start":310.62,"end":310.76},{"word":"pay","start":310.76,"end":310.88},{"word":"for","start":310.88,"end":310.98},{"word":"the","start":310.98,"end":311.08},{"word":"whole","start":311.08,"end":311.2},{"word":"thing.","start":311.2,"end":311.4}],"textKo":"엄청나게 큰 문제에 부딪혀요. 그건 바로 스마트폰에는","listenDifficulty":5},{"index":87,"start":311.58,"end":314.58,"textEn":"This is great. However, if you''re trying","words":[{"word":"This","start":311.58,"end":311.82},{"word":"is","start":311.82,"end":311.9},{"word":"great.","start":311.9,"end":312.08},{"word":"However,","start":312.82,"end":313.22},{"word":"if","start":313.84,"end":314.24},{"word":"you''re","start":314.24,"end":314.38},{"word":"trying","start":314.38,"end":314.58}],"textKo":"인류가 만든 것 중 가장 중독적인","listenDifficulty":1},{"index":88,"start":314.58,"end":316.6,"textEn":"To deliver education with a smartphone, you run into","words":[{"word":"to","start":314.58,"end":314.7},{"word":"deliver","start":314.7,"end":315.04},{"word":"education","start":315.04,"end":315.5},{"word":"with","start":315.5,"end":315.7},{"word":"a","start":315.7,"end":315.8},{"word":"smartphone,","start":315.8,"end":316.14},{"word":"you","start":316.3,"end":316.32},{"word":"run","start":316.32,"end":316.46},{"word":"into","start":3