INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'en', 'JhHMJCUmq28', '{"videoId":"JhHMJCUmq28","youtubeId":"JhHMJCUmq28","title":"Quantum Computers Explained – Limits of Human Technology","channel":"Kurzgesagt – In a Nutshell","categoryId":"tech","difficulty":"advanced","duration":437,"thumbnail":"https://i.ytimg.com/vi_webp/JhHMJCUmq28/maxresdefault.webp","speechRateWpm":155,"addedAt":"2026-02-16","segmentCount":73,"vocabularyCount":20,"grammarPatternCount":10,"descriptionKo":"양자 컴퓨터란 무엇인가 — 인간 기술의 한계를 넘어서"}'::jsonb, '{"videoId":"JhHMJCUmq28","segments":[{"index":0,"start":0.0,"end":6.04,"textEn":"For most of our history, human technology consisted of our brains, fire and sharp sticks.","words":[{"word":"For","start":0.0,"end":0.44},{"word":"most","start":0.44,"end":0.72},{"word":"of","start":0.72,"end":0.88},{"word":"our","start":0.88,"end":1.04},{"word":"history,","start":1.04,"end":1.4},{"word":"human","start":1.72,"end":1.9},{"word":"technology","start":1.9,"end":2.48},{"word":"consisted","start":2.48,"end":3.08},{"word":"of","start":3.08,"end":3.4},{"word":"our","start":3.4,"end":3.6},{"word":"brains,","start":3.6,"end":4.04},{"word":"fire","start":4.24,"end":4.82},{"word":"and","start":4.82,"end":5.34},{"word":"sharp","start":5.34,"end":5.66},{"word":"sticks.","start":5.66,"end":6.04}],"textKo":"","listenDifficulty":1},{"index":1,"start":6.4,"end":12.6,"textEn":"While fire and sharp sticks became power plants and nuclear weapons, the biggest upgrade has happened to our brains.","words":[{"word":"While","start":6.4,"end":7.0},{"word":"fire","start":7.0,"end":7.38},{"word":"and","start":7.38,"end":7.54},{"word":"sharp","start":7.54,"end":7.8},{"word":"sticks","start":7.8,"end":8.1},{"word":"became","start":8.1,"end":8.4},{"word":"power","start":8.4,"end":8.84},{"word":"plants","start":8.84,"end":9.2},{"word":"and","start":9.2,"end":9.36},{"word":"nuclear","start":9.36,"end":9.68},{"word":"weapons,","start":9.68,"end":10.08},{"word":"the","start":10.28,"end":10.56},{"word":"biggest","start":10.56,"end":10.84},{"word":"upgrade","start":10.84,"end":11.26},{"word":"has","start":11.26,"end":11.5},{"word":"happened","start":11.5,"end":11.82},{"word":"to","start":11.82,"end":12.0},{"word":"our","start":12.0,"end":12.18},{"word":"brains.","start":12.18,"end":12.6}],"textKo":"불과 날카로운 막대기가 발전소와 핵무기가 되는 동안, 가장 큰 업그레이드는 우리의 뇌에서 일어났어.","listenDifficulty":2},{"index":2,"start":13.1,"end":21.76,"textEn":"Since the 1960s, the power of our brain machines has kept growing exponentially, allowing computers to get smaller and more powerful at the same time.","words":[{"word":"Since","start":13.1,"end":13.52},{"word":"the","start":13.52,"end":13.66},{"word":"1960s,","start":13.66,"end":14.5},{"word":"the","start":14.72,"end":14.86},{"word":"power","start":14.86,"end":15.12},{"word":"of","start":15.12,"end":15.28},{"word":"our","start":15.28,"end":15.42},{"word":"brain","start":15.42,"end":15.7},{"word":"machines","start":15.7,"end":16.12},{"word":"has","start":16.12,"end":16.32},{"word":"kept","start":16.32,"end":16.54},{"word":"growing","start":16.54,"end":16.84},{"word":"exponentially,","start":16.84,"end":17.54},{"word":"allowing","start":17.92,"end":18.3},{"word":"computers","start":18.3,"end":18.8},{"word":"to","start":18.8,"end":19.0},{"word":"get","start":19.0,"end":19.16},{"word":"smaller","start":19.16,"end":19.58},{"word":"and","start":19.58,"end":19.9},{"word":"more","start":19.9,"end":20.16},{"word":"powerful","start":20.16,"end":20.66},{"word":"at","start":20.66,"end":20.98},{"word":"the","start":20.98,"end":21.14},{"word":"same","start":21.14,"end":21.38},{"word":"time.","start":21.38,"end":21.76}],"textKo":"1960년대 이후, 우리 뇌 기계의 성능은 기하급수적으로 계속 성장해왔고, 컴퓨터는 동시에 더 작고 더 강력해질 수 있었어.","listenDifficulty":3},{"index":3,"start":22.14,"end":25.44,"textEn":"But this process is about to meet its physical limits.","words":[{"word":"But","start":22.14,"end":22.74},{"word":"this","start":22.74,"end":23.0},{"word":"process","start":23.0,"end":23.46},{"word":"is","start":23.46,"end":23.78},{"word":"about","start":23.78,"end":24.04},{"word":"to","start":24.04,"end":24.24},{"word":"meet","start":24.24,"end":24.42},{"word":"its","start":24.42,"end":24.66},{"word":"physical","start":24.66,"end":25.0},{"word":"limits.","start":25.0,"end":25.44}],"textKo":"하지만 이 과정은 곧 물리적 한계에 도달하려 하고 있어.","listenDifficulty":2},{"index":4,"start":25.8,"end":28.64,"textEn":"Computer parts are approaching the size of an atom.","words":[{"word":"Computer","start":25.8,"end":26.4},{"word":"parts","start":26.4,"end":26.72},{"word":"are","start":26.72,"end":27.0},{"word":"approaching","start":27.0,"end":27.46},{"word":"the","start":27.46,"end":27.68},{"word":"size","start":27.68,"end":27.98},{"word":"of","start":27.98,"end":28.18},{"word":"an","start":28.18,"end":28.32},{"word":"atom.","start":28.32,"end":28.64}],"textKo":"컴퓨터 부품이 원자 크기에 접근하고 있어.","listenDifficulty":2},{"index":5,"start":28.64,"end":32.68,"textEn":"To understand why this is a problem, we have to clear up some basics.","words":[{"word":"To","start":28.64,"end":29.56},{"word":"understand","start":29.56,"end":30.0},{"word":"why","start":30.0,"end":30.26},{"word":"this","start":30.26,"end":30.44},{"word":"is","start":30.44,"end":30.56},{"word":"a","start":30.56,"end":30.68},{"word":"problem,","start":30.68,"end":30.96},{"word":"we","start":31.42,"end":31.44},{"word":"have","start":31.44,"end":31.58},{"word":"to","start":31.58,"end":31.68},{"word":"clear","start":31.68,"end":31.86},{"word":"up","start":31.86,"end":32.06},{"word":"some","start":32.06,"end":32.24},{"word":"basics.","start":32.24,"end":32.68}],"textKo":"이게 왜 문제인지 이해하려면, 몇 가지 기본적인 것들을 정리해야 해.","listenDifficulty":3},{"index":6,"start":39.24,"end":48.34,"textEn":"A computer is made up of very simple components doing very simple things, representing data, the means of processing it and control mechanisms.","words":[{"word":"A","start":39.24,"end":39.92},{"word":"computer","start":39.92,"end":40.38},{"word":"is","start":40.38,"end":40.72},{"word":"made","start":40.72,"end":40.9},{"word":"up","start":40.9,"end":41.08},{"word":"of","start":41.08,"end":41.22},{"word":"very","start":41.22,"end":41.46},{"word":"simple","start":41.46,"end":41.8},{"word":"components","start":41.8,"end":42.36},{"word":"doing","start":42.36,"end":42.84},{"word":"very","start":42.84,"end":43.18},{"word":"simple","start":43.18,"end":43.52},{"word":"things,","start":43.52,"end":43.94},{"word":"representing","start":44.16,"end":44.8},{"word":"data,","start":44.8,"end":45.28},{"word":"the","start":45.48,"end":45.78},{"word":"means","start":45.78,"end":46.0},{"word":"of","start":46.0,"end":46.2},{"word":"processing","start":46.2,"end":46.68},{"word":"it","start":46.68,"end":46.9},{"word":"and","start":46.9,"end":47.36},{"word":"control","start":47.36,"end":47.8},{"word":"mechanisms.","start":47.8,"end":48.34}],"textKo":"컴퓨터는 아주 단순한 일을 하는 아주 단순한 부품들로 이루어져 있어. 데이터를 표현하고, 처리 수단과 제어 장치로 구성돼.","listenDifficulty":3},{"index":7,"start":48.88,"end":53.72,"textEn":"Computer chips contain modules, which contain logic gates, which contain transistors.","words":[{"word":"Computer","start":48.88,"end":49.56},{"word":"chips","start":49.56,"end":49.8},{"word":"contain","start":49.8,"end":50.14},{"word":"modules,","start":50.14,"end":50.68},{"word":"which","start":50.86,"end":51.16},{"word":"contain","start":51.16,"end":51.5},{"word":"logic","start":51.5,"end":51.88},{"word":"gates,","start":51.88,"end":52.2},{"word":"which","start":52.54,"end":52.64},{"word":"contain","start":52.64,"end":53.06},{"word":"transistors.","start":53.06,"end":53.72}],"textKo":"컴퓨터 칩에는 모듈이 들어 있고, 모듈에는 논리 게이트가, 논리 게이트에는 트랜지스터가 들어 있어.","listenDifficulty":1},{"index":8,"start":53.72,"end":63.22,"textEn":"A transistor is the simplest form of a data processor in computers, basically a switch that can either block or open the way for information coming through.","words":[{"word":"A","start":53.72,"end":54.72},{"word":"transistor","start":54.72,"end":55.18},{"word":"is","start":55.18,"end":55.82},{"word":"the","start":55.82,"end":55.96},{"word":"simplest","start":55.96,"end":56.3},{"word":"form","start":56.3,"end":56.64},{"word":"of","start":56.64,"end":56.78},{"word":"a","start":56.78,"end":56.88},{"word":"data","start":56.88,"end":57.08},{"word":"processor","start":57.08,"end":57.56},{"word":"in","start":57.56,"end":57.86},{"word":"computers,","start":57.86,"end":58.36},{"word":"basically","start":58.64,"end":59.1},{"word":"a","start":59.1,"end":59.4},{"word":"switch","start":59.4,"end":59.76},{"word":"that","start":59.76,"end":60.0},{"word":"can","start":60.0,"end":60.14},{"word":"either","start":60.14,"end":60.38},{"word":"block","start":60.38,"end":60.76},{"word":"or","start":60.76,"end":61.24},{"word":"open","start":61.24,"end":61.6},{"word":"the","start":61.6,"end":61.76},{"word":"way","start":61.76,"end":61.88},{"word":"for","start":61.88,"end":62.08},{"word":"information","start":62.08,"end":62.6},{"word":"coming","start":62.6,"end":62.94},{"word":"through.","start":62.94,"end":63.22}],"textKo":"트랜지스터는 컴퓨터에서 가장 단순한 형태의 데이터 처리 장치야. 기본적으로 들어오는 정보의 통로를 막거나 열 수 있는 스위치지.","listenDifficulty":2},{"index":9,"start":63.68,"end":68.46,"textEn":"This information is made up of bits, which can be set to either zero or one.","words":[{"word":"This","start":63.68,"end":64.28},{"word":"information","start":64.28,"end":64.68},{"word":"is","start":64.68,"end":65.0},{"word":"made","start":65.0,"end":65.18},{"word":"up","start":65.18,"end":65.36},{"word":"of","start":65.36,"end":65.54},{"word":"bits,","start":65.54,"end":65.98},{"word":"which","start":66.1,"end":66.42},{"word":"can","start":66.42,"end":66.54},{"word":"be","start":66.54,"end":66.66},{"word":"set","start":66.66,"end":66.9},{"word":"to","start":66.9,"end":67.08},{"word":"either","start":67.08,"end":67.42},{"word":"zero","start":67.42,"end":67.8},{"word":"or","start":67.8,"end":68.16},{"word":"one.","start":68.16,"end":68.46}],"textKo":"이 정보는 비트로 이루어져 있는데, 0 또는 1로 설정할 수 있어.","listenDifficulty":4},{"index":10,"start":69.14,"end":72.92,"textEn":"Combinations of several bits are used to represent more complex information.","words":[{"word":"Combinations","start":69.14,"end":69.74},{"word":"of","start":69.74,"end":70.04},{"word":"several","start":70.04,"end":70.34},{"word":"bits","start":70.34,"end":70.6},{"word":"are","start":70.6,"end":70.84},{"word":"used","start":70.84,"end":71.1},{"word":"to","start":71.1,"end":71.26},{"word":"represent","start":71.26,"end":71.64},{"word":"more","start":71.64,"end":71.94},{"word":"complex","start":71.94,"end":72.34},{"word":"information.","start":72.34,"end":72.92}],"textKo":"여러 비트의 조합으로 더 복잡한 정보를 표현해.","listenDifficulty":2},{"index":11,"start":72.92,"end":77.88,"textEn":"Transistors are combined to create logic gates, which still do very simple stuff.","words":[{"word":"Transistors","start":72.92,"end":74.16},{"word":"are","start":74.16,"end":74.36},{"word":"combined","start":74.36,"end":74.82},{"word":"to","start":74.82,"end":75.06},{"word":"create","start":75.06,"end":75.42},{"word":"logic","start":75.42,"end":75.78},{"word":"gates,","start":75.78,"end":76.08},{"word":"which","start":76.22,"end":76.6},{"word":"still","start":76.6,"end":76.8},{"word":"do","start":76.8,"end":76.96},{"word":"very","start":76.96,"end":77.22},{"word":"simple","start":77.22,"end":77.56},{"word":"stuff.","start":77.56,"end":77.88}],"textKo":"트랜지스터들이 결합되어 논리 게이트를 만드는데, 이것도 여전히 아주 단순한 일을 해.","listenDifficulty":1},{"index":12,"start":78.38,"end":84.82,"textEn":"For example, an AND gate sends an output of one if all of its inputs are one, and an output of zero otherwise.","words":[{"word":"For","start":78.38,"end":78.44},{"word":"example,","start":78.44,"end":78.8},{"word":"an","start":79.22,"end":79.32},{"word":"AND","start":79.32,"end":79.68},{"word":"gate","start":79.68,"end":80.0},{"word":"sends","start":80.0,"end":80.44},{"word":"an","start":80.44,"end":80.58},{"word":"output","start":80.58,"end":80.92},{"word":"of","start":80.92,"end":81.14},{"word":"one","start":81.14,"end":81.36},{"word":"if","start":81.36,"end":81.56},{"word":"all","start":81.56,"end":81.76},{"word":"of","start":81.76,"end":81.88},{"word":"its","start":81.88,"end":82.0},{"word":"inputs","start":82.0,"end":82.34},{"word":"are","start":82.34,"end":82.56},{"word":"one,","start":82.56,"end":82.8},{"word":"and","start":82.94,"end":83.38},{"word":"an","start":83.38,"end":83.48},{"word":"output","start":83.48,"end":83.84},{"word":"of","start":83.84,"end":84.04},{"word":"zero","start":84.04,"end":84.36},{"word":"otherwise.","start":84.36,"end":84.82}],"textKo":"예를 들어, AND 게이트는 모든 입력이 1이면 1을 출력하고, 그 외에는 0을 출력해.","listenDifficulty":3},{"index":13,"start":85.68,"end":90.84,"textEn":"Combinations of logic gates finally form meaningful modules, say for adding two numbers.","words":[{"word":"Combinations","start":85.68,"end":86.3},{"word":"of","start":86.3,"end":86.56},{"word":"logic","start":86.56,"end":86.82},{"word":"gates","start":86.82,"end":87.1},{"word":"finally","start":87.1,"end":87.72},{"word":"form","start":87.72,"end":88.1},{"word":"meaningful","start":88.1,"end":88.54},{"word":"modules,","start":88.54,"end":89.06},{"word":"say","start":89.24,"end":89.62},{"word":"for","start":89.62,"end":89.9},{"word":"adding","start":89.9,"end":90.18},{"word":"two","start":90.18,"end":90.46},{"word":"numbers.","start":90.46,"end":90.84}],"textKo":"논리 게이트의 조합이 마침내 의미 있는 모듈을 형성해. 예를 들어 두 숫자를 더하는 모듈 같은 거지.","listenDifficulty":1},{"index":14,"start":90.84,"end":96.8,"textEn":"Once you can add, you can also multiply, and once you can multiply, you can basically do anything.","words":[{"word":"Once","start":90.84,"end":91.72},{"word":"you","start":91.72,"end":91.9},{"word":"can","start":91.9,"end":92.04},{"word":"add,","start":92.04,"end":92.3},{"word":"you","start":92.48,"end":92.68},{"word":"can","start":92.68,"end":92.8},{"word":"also","start":92.8,"end":93.0},{"word":"multiply,","start":93.0,"end":93.48},{"word":"and","start":93.74,"end":94.12},{"word":"once","start":94.12,"end":94.36},{"word":"you","start":94.36,"end":94.52},{"word":"can","start":94.52,"end":94.66},{"word":"multiply,","start":94.66,"end":95.04},{"word":"you","start":95.36,"end":95.56},{"word":"can","start":95.56,"end":95.7},{"word":"basically","start":95.7,"end":96.1},{"word":"do","start":96.1,"end":96.38},{"word":"anything.","start":96.38,"end":96.8}],"textKo":"덧셈을 할 수 있으면 곱셈도 할 수 있고, 곱셈을 할 수 있으면 기본적으로 뭐든지 할 수 있어.","listenDifficulty":2},{"index":15,"start":97.44,"end":105.9,"textEn":"Since all basic operations are literally simpler than first grade math, you can imagine a computer as a group of seven-year-olds answering really basic math questions.","words":[{"word":"Since","start":97.44,"end":97.82},{"word":"all","start":97.82,"end":98.04},{"word":"basic","start":98.04,"end":98.42},{"word":"operations","start":98.42,"end":98.88},{"word":"are","start":98.88,"end":99.2},{"word":"literally","start":99.2,"end":99.52},{"word":"simpler","start":99.52,"end":99.94},{"word":"than","start":99.94,"end":100.16},{"word":"first","start":100.16,"end":100.42},{"word":"grade","start":100.42,"end":100.64},{"word":"math,","start":100.64,"end":100.92},{"word":"you","start":101.12,"end":101.42},{"word":"can","start":101.42,"end":101.52},{"word":"imagine","start":101.52,"end":101.82},{"word":"a","start":101.82,"end":101.98},{"word":"computer","start":101.98,"end":102.34},{"word":"as","start":102.34,"end":102.66},{"word":"a","start":102.66,"end":102.76},{"word":"group","start":102.76,"end":102.92},{"word":"of","start":102.92,"end":103.12},{"word":"seven","start":103.12,"end":103.44},{"word":"-year","start":103.44,"end":103.62},{"word":"-olds","start":103.62,"end":103.84},{"word":"answering","start":103.84,"end":104.48},{"word":"really","start":104.48,"end":104.8},{"word":"basic","start":104.8,"end":105.18},{"word":"math","start":105.18,"end":105.44},{"word":"questions.","start":105.44,"end":105.9}],"textKo":"모든 기본 연산이 말 그대로 1학년 수학보다 쉬우니까, 컴퓨터를 정말 기초적인 수학 문제에 답하는 7살짜리 아이들의 그룹이라고 상상해 봐.","listenDifficulty":2},{"index":16,"start":105.9,"end":110.68,"textEn":"A large enough bunch of them could compute anything from astrophysics to zelda.","words":[{"word":"A","start":105.9,"end":106.78},{"word":"large","start":106.78,"end":107.02},{"word":"enough","start":107.02,"end":107.22},{"word":"bunch","start":107.22,"end":107.48},{"word":"of","start":107.48,"end":107.62},{"word":"them","start":107.62,"end":107.78},{"word":"could","start":107.78,"end":107.98},{"word":"compute","start":107.98,"end":108.34},{"word":"anything","start":108.34,"end":108.7},{"word":"from","start":108.7,"end":109.06},{"word":"astrophysics","start":109.06,"end":109.82},{"word":"to","start":109.82,"end":110.24},{"word":"zelda.","start":110.24,"end":110.68}],"textKo":"충분히 많은 수의 아이들이 있으면 천체물리학부터 젤다까지 뭐든지 계산할 수 있어.","listenDifficulty":1},{"index":17,"start":111.04,"end":115.96,"textEn":"However, with parts getting tinier and tinier, quantum physics are making things tricky.","words":[{"word":"However,","start":111.04,"end":111.66},{"word":"with","start":111.92,"end":112.0},{"word":"parts","start":112.0,"end":112.3},{"word":"getting","start":112.3,"end":112.56},{"word":"tinier","start":112.56,"end":113.02},{"word":"and","start":113.02,"end":113.24},{"word":"tinier,","start":113.24,"end":113.66},{"word":"quantum","start":114.02,"end":114.32},{"word":"physics","start":114.32,"end":114.68},{"word":"are","start":114.68,"end":114.98},{"word":"making","start":114.98,"end":115.26},{"word":"things","start":115.26,"end":115.62},{"word":"tricky.","start":115.62,"end":115.96}],"textKo":"하지만 부품이 점점 더 작아지면서, 양자물리학이 일을 까다롭게 만들고 있어.","listenDifficulty":1},{"index":18,"start":116.44,"end":119.74,"textEn":"In a nutshell, a transistor is just an electric switch.","words":[{"word":"In","start":116.44,"end":116.86},{"word":"a","start":116.86,"end":116.96},{"word":"nutshell,","start":116.96,"end":117.3},{"word":"a","start":117.62,"end":117.8},{"word":"transistor","start":117.8,"end":118.16},{"word":"is","start":118.16,"end":118.54},{"word":"just","start":118.54,"end":118.8},{"word":"an","start":118.8,"end":119.02},{"word":"electric","start":119.02,"end":119.36},{"word":"switch.","start":119.36,"end":119.74}],"textKo":"간단히 말하면, 트랜지스터는 그냥 전기 스위치야.","listenDifficulty":2},{"index":19,"start":120.24,"end":127.7,"textEn":"Electricity is electrons moving from one place to another, so a switch is a passage that can block electrons from moving in one direction.","words":[{"word":"Electricity","start":120.24,"end":120.86},{"word":"is","start":120.86,"end":121.12},{"word":"electrons","start":121.12,"end":121.54},{"word":"moving","start":121.54,"end":121.9},{"word":"from","start":121.9,"end":122.1},{"word":"one","start":122.1,"end":122.32},{"word":"place","start":122.32,"end":122.58},{"word":"to","start":122.58,"end":122.74},{"word":"another,","start":122.74,"end":123.02},{"word":"so","start":123.24,"end":123.62},{"word":"a","start":123.62,"end":123.84},{"word":"switch","start":123.84,"end":124.22},{"word":"is","start":124.22,"end":124.7},{"word":"a","start":124.7,"end":124.82},{"word":"passage","start":124.82,"end":125.18},{"word":"that","start":125.18,"end":125.4},{"word":"can","start":125.4,"end":125.56},{"word":"block","start":125.56,"end":125.8},{"word":"electrons","start":125.8,"end":126.26},{"word":"from","start":126.26,"end":126.5},{"word":"moving","start":126.5,"end":126.84},{"word":"in","start":126.84,"end":127.02},{"word":"one","start":127.02,"end":127.22},{"word":"direction.","start":127.22,"end":127.7}],"textKo":"전기는 전자가 한 곳에서 다른 곳으로 이동하는 거니까, 스위치는 전자가 한 방향으로 이동하는 것을 막을 수 있는 통로야.","listenDifficulty":2},{"index":20,"start":127.7,"end":138.46,"textEn":"Today, a typical scale for transistors is 40 nanometers, which is about eight times less than the HIV virus'' diameter and 500 times smaller than a red blood cell''s.","words":[{"word":"Today,","start":127.7,"end":128.72},{"word":"a","start":128.96,"end":129.06},{"word":"typical","start":129.06,"end":129.4},{"word":"scale","start":129.4,"end":129.72},{"word":"for","start":129.72,"end":129.94},{"word":"transistors","start":129.94,"end":130.46},{"word":"is","start":130.46,"end":130.72},{"word":"40","start":130.72,"end":131.14},{"word":"nanometers,","start":131.14,"end":131.64},{"word":"which","start":131.96,"end":132.38},{"word":"is","start":132.38,"end":132.5},{"word":"about","start":132.5,"end":132.74},{"word":"eight","start":132.74,"end":133.0},{"word":"times","start":133.0,"end":133.34},{"word":"less","start":133.34,"end":133.56},{"word":"than","start":133.56,"end":133.8},{"word":"the","start":133.8,"end":133.92},{"word":"HIV","start":133.92,"end":134.34},{"word":"virus''","start":134.34,"end":134.88},{"word":"diameter","start":135.06,"end":135.46},{"word":"and","start":135.46,"end":136.04},{"word":"500","start":136.04,"end":136.54},{"word":"times","start":136.54,"end":136.88},{"word":"smaller","start":136.88,"end":137.26},{"word":"than","start":137.26,"end":137.44},{"word":"a","start":137.44,"end":137.56},{"word":"red","start":137.56,"end":137.76},{"word":"blood","start":137.76,"end":137.98},{"word":"cell''s.","start":137.98,"end":138.46}],"textKo":"오늘날 트랜지스터의 일반적인 크기는 40나노미터인데, 이건 HIV 바이러스 지름의 약 8분의 1이고 적혈구보다 500배 작아.","listenDifficulty":2},{"index":21,"start":138.86,"end":148.16,"textEn":"As transistors are shrinking to the size of only a few atoms, electrons may just transfer themselves to the other side of a blocked passage via a process called quantum tunneling.","words":[{"word":"As","start":138.86,"end":139.3},{"word":"transistors","start":139.3,"end":139.86},{"word":"are","start":139.86,"end":140.12},{"word":"shrinking","start":140.12,"end":140.46},{"word":"to","start":140.46,"end":140.68},{"word":"the","start":140.68,"end":140.8},{"word":"size","start":140.8,"end":141.06},{"word":"of","start":141.06,"end":141.24},{"word":"only","start":141.24,"end":141.54},{"word":"a","start":141.54,"end":141.7},{"word":"few","start":141.7,"end":141.84},{"word":"atoms,","start":141.84,"end":142.16},{"word":"electrons","start":142.56,"end":143.04},{"word":"may","start":143.04,"end":143.28},{"word":"just","start":143.28,"end":143.5},{"word":"transfer","start":143.5,"end":143.9},{"word":"themselves","start":143.9,"end":144.22},{"word":"to","start":144.22,"end":144.52},{"word":"the","start":144.52,"end":144.64},{"word":"other","start":144.64,"end":144.84},{"word":"side","start":144.84,"end":145.12},{"word":"of","start":145.12,"end":145.26},{"word":"a","start":145.26,"end":145.34},{"word":"blocked","start":145.34,"end":145.54},{"word":"passage","start":145.54,"end":145.92},{"word":"via","start":145.92,"end":146.44},{"word":"a","start":146.44,"end":146.62},{"word":"process","start":146.62,"end":146.96},{"word":"called","start":146.96,"end":147.26},{"word":"quantum","start":147.26,"end":147.7},{"word":"tunneling.","start":147.7,"end":148.16}],"textKo":"트랜지스터가 겨우 몇 개의 원자 크기로 줄어들면서, 전자가 양자 터널링이라는 과정을 통해 막힌 통로의 반대편으로 스스로 이동할 수도 있어.","listenDifficulty":3},{"index":22,"start":148.46,"end":156.44,"textEn":"In the quantum realm, physics works quite differently from the predictable ways we''re used to, and traditional computers just stop making sense.","words":[{"word":"In","start":148.46,"end":148.94},{"word":"the","start":148.94,"end":149.06},{"word":"quantum","start":149.06,"end":149.36},{"word":"realm,","start":149.36,"end":149.68},{"word":"physics","start":149.84,"end":150.3},{"word":"works","start":150.3,"end":150.68},{"word":"quite","start":150.68,"end":150.98},{"word":"differently","start":150.98,"end":151.42},{"word":"from","start":151.42,"end":151.7},{"word":"the","start":151.7,"end":151.84},{"word":"predictable","start":151.84,"end":152.28},{"word":"ways","start":152.28,"end":152.62},{"word":"we''re","start":152.62,"end":152.86},{"word":"used","start":152.86,"end":153.06},{"word":"to,","start":153.06,"end":153.24},{"word":"and","start":153.36,"end":153.8},{"word":"traditional","start":153.8,"end":154.22},{"word":"computers","start":154.22,"end":154.74},{"word":"just","start":154.74,"end":155.28},{"word":"stop","start":155.28,"end":155.6},{"word":"making","start":155.6,"end":155.98},{"word":"sense.","start":155.98,"end":156.44}],"textKo":"양자 세계에서 물리학은 우리가 익숙한 예측 가능한 방식과 꽤 다르게 작동하고, 기존 컴퓨터는 의미가 없어져.","listenDifficulty":3},{"index":23,"start":156.44,"end":161.0,"textEn":"We are approaching a real physical barrier for our technological progress.","words":[{"word":"We","start":156.44,"end":157.3},{"word":"are","start":157.3,"end":157.5},{"word":"approaching","start":157.5,"end":157.92},{"word":"a","start":157.92,"end":158.2},{"word":"real","start":158.2,"end":158.5},{"word":"physical","start":158.5,"end":158.88},{"word":"barrier","start":158.88,"end":159.32},{"word":"for","start":159.32,"end":159.62},{"word":"our","start":159.62,"end":159.8},{"word":"technological","start":159.8,"end":160.36},{"word":"progress.","start":160.36,"end":161.0}],"textKo":"우리는 기술 발전의 실질적인 물리적 장벽에 다가가고 있어.","listenDifficulty":1},{"index":24,"start":161.32,"end":169.02,"textEn":"To solve this problem, scientists are trying to use these unusual quantum properties to their advantage by building quantum computers.","words":[{"word":"To","start":161.32,"end":161.94},{"word":"solve","start":161.94,"end":162.3},{"word":"this","start":162.3,"end":162.52},{"word":"problem,","start":162.52,"end":162.86},{"word":"scientists","start":163.22,"end":163.6},{"word":"are","start":163.6,"end":163.84},{"word":"trying","start":163.84,"end":164.04},{"word":"to","start":164.04,"end":164.2},{"word":"use","start":164.2,"end":164.44},{"word":"these","start":164.44,"end":164.68},{"word":"unusual","start":164.68,"end":165.28},{"word":"quantum","start":165.28,"end":165.62},{"word":"properties","start":165.62,"end":166.08},{"word":"to","start":166.08,"end":166.28},{"word":"their","start":166.28,"end":166.48},{"word":"advantage","start":166.48,"end":166.94},{"word":"by","start":166.94,"end":167.54},{"word":"building","start":167.54,"end":168.0},{"word":"quantum","start":168.0,"end":168.44},{"word":"computers.","start":168.44,"end":169.02}],"textKo":"이 문제를 해결하기 위해, 과학자들은 이러한 특이한 양자 특성을 양자 컴퓨터를 만들어 유리하게 활용하려고 하고 있어.","listenDifficulty":1},{"index":25,"start":169.44,"end":173.02,"textEn":"In normal computers, bits are the smallest units of information.","words":[{"word":"In","start":169.44,"end":169.98},{"word":"normal","start":169.98,"end":170.28},{"word":"computers,","start":170.28,"end":170.78},{"word":"bits","start":170.78,"end":171.24},{"word":"are","start":171.24,"end":171.52},{"word":"the","start":171.52,"end":171.64},{"word":"smallest","start":171.64,"end":171.94},{"word":"units","start":171.94,"end":172.32},{"word":"of","start":172.32,"end":172.54},{"word":"information.","start":172.54,"end":173.02}],"textKo":"일반 컴퓨터에서는 비트가 가장 작은 정보 단위야.","listenDifficulty":1},{"index":26,"start":173.54,"end":177.72,"textEn":"Quantum computers use qubits, which can also be set to one of two values.","words":[{"word":"Quantum","start":173.54,"end":174.0},{"word":"computers","start":174.0,"end":174.48},{"word":"use","start":174.48,"end":174.84},{"word":"qubits,","start":174.84,"end":175.36},{"word":"which","start":175.46,"end":175.8},{"word":"can","start":175.8,"end":175.92},{"word":"also","start":175.92,"end":176.16},{"word":"be","start":176.16,"end":176.36},{"word":"set","start":176.36,"end":176.58},{"word":"to","start":176.58,"end":176.76},{"word":"one","start":176.76,"end":176.92},{"word":"of","start":176.92,"end":177.06},{"word":"two","start":177.06,"end":177.26},{"word":"values.","start":177.26,"end":177.72}],"textKo":"양자 컴퓨터는 큐비트를 사용하는데, 이것도 두 가지 값 중 하나로 설정할 수 있어.","listenDifficulty":3},{"index":27,"start":178.16,"end":184.02,"textEn":"A qubit can be any two-level quantum system, such as a spin in a magnetic field or a single photon.","words":[{"word":"A","start":178.16,"end":178.44},{"word":"qubit","start":178.44,"end":178.76},{"word":"can","start":178.76,"end":178.96},{"word":"be","start":178.96,"end":179.1},{"word":"any","start":179.1,"end":179.32},{"word":"two","start":179.32,"end":179.56},{"word":"-level","start":179.56,"end":179.82},{"word":"quantum","start":179.82,"end":180.16},{"word":"system,","start":180.16,"end":180.6},{"word":"such","start":180.88,"end":181.12},{"word":"as","start":181.12,"end":181.28},{"word":"a","start":181.28,"end":181.42},{"word":"spin","start":181.42,"end":181.74},{"word":"in","start":181.74,"end":181.92},{"word":"a","start":181.92,"end":182.04},{"word":"magnetic","start":182.04,"end":182.4},{"word":"field","start":182.4,"end":182.8},{"word":"or","start":182.8,"end":183.18},{"word":"a","start":183.18,"end":183.32},{"word":"single","start":183.32,"end":183.6},{"word":"photon.","start":183.6,"end":184.02}],"textKo":"큐비트는 자기장 속의 스핀이나 단일 광자처럼 어떤 두 단계 양자 시스템이든 될 수 있어.","listenDifficulty":3},{"index":28,"start":184.02,"end":190.36,"textEn":"Zero and one are this system''s possible states, like the photon''s horizontal or vertical polarization.","words":[{"word":"Zero","start":184.02,"end":185.0},{"word":"and","start":185.0,"end":185.36},{"word":"one","start":185.36,"end":185.64},{"word":"are","start":185.64,"end":186.04},{"word":"this","start":186.04,"end":186.22},{"word":"system''s","start":186.22,"end":186.72},{"word":"possible","start":186.72,"end":187.08},{"word":"states,","start":187.08,"end":187.42},{"word":"like","start":187.7,"end":187.98},{"word":"the","start":187.98,"end":188.14},{"word":"photon''s","start":188.14,"end":188.6},{"word":"horizontal","start":188.6,"end":189.1},{"word":"or","start":189.1,"end":189.38},{"word":"vertical","start":189.38,"end":189.82},{"word":"polarization.","start":189.82,"end":190.36}],"textKo":"0과 1은 이 시스템의 가능한 상태야. 광자의 수평 또는 수직 편광처럼 말이야.","listenDifficulty":2},{"index":29,"start":190.94,"end":197.6,"textEn":"In the quantum world, the qubit doesn''t have to be in just one of those, it can be in any proportions of both states at once.","words":[{"word":"In","start":190.94,"end":191.44},{"word":"the","start":191.44,"end":191.56},{"word":"quantum","start":191.56,"end":191.84},{"word":"world,","start":191.84,"end":192.18},{"word":"the","start":192.4,"end":192.48},{"word":"qubit","start":192.48,"end":192.84},{"word":"doesn''t","start":192.84,"end":193.14},{"word":"have","start":193.14,"end":193.28},{"word":"to","start":193.28,"end":193.4},{"word":"be","start":193.4,"end":193.52},{"word":"in","start":193.52,"end":193.7},{"word":"just","start":193.7,"end":193.88},{"word":"one","start":193.88,"end":194.12},{"word":"of","start":194.12,"end":194.24},{"word":"those,","start":194.24,"end":194.5},{"word":"it","start":194.68,"end":194.96},{"word":"can","start":194.96,"end":195.08},{"word":"be","start":195.08,"end":195.24},{"word":"in","start":195.24,"end":195.38},{"word":"any","start":195.38,"end":195.6},{"word":"proportions","start":195.6,"end":196.12},{"word":"of","start":196.12,"end":196.46},{"word":"both","start":196.46,"end":196.72},{"word":"states","start":196.72,"end":197.04},{"word":"at","start":197.04,"end":197.26},{"word":"once.","start":197.26,"end":197.6}],"textKo":"양자 세계에서 큐비트는 그중 하나의 상태에만 있을 필요가 없어. 두 상태의 어떤 비율로든 동시에 존재할 수 있지.","listenDifficulty":4},{"index":30,"start":197.9,"end":208.42,"textEn":"This is called superposition. But as soon as you test its value, say by sending the photon through a filter, it has to decide to be either vertically or horizontally polarized.","words":[{"word":"This","start":197.9,"end":198.3},{"word":"is","start":198.3,"end":198.56},{"word":"called","start":198.56,"end":198.88},{"word":"superposition.","start":198.88,"end":199.16},{"word":"But","start":200.1,"end":200.66},{"word":"as","start":200.66,"end":200.88},{"word":"soon","start":200.88,"end":201.02},{"word":"as","start":201.02,"end":201.18},{"word":"you","start":201.18,"end":201.28},{"word":"test","start":201.28,"end":201.62},{"word":"its","start":201.62,"end":201.82},{"word":"value,","start":201.82,"end":202.16},{"word":"say","start":202.34,"end":202.66},{"word":"by","start":202.66,"end":202.88},{"word":"sending","start":202.88,"end":203.22},{"word":"the","start":203.22,"end":203.4},{"word":"photon","start":203.4,"end":203.7},{"word":"through","start":203.7,"end":203.92},{"word":"a","start":203.92,"end":204.02},{"word":"filter,","start":204.02,"end":204.3},{"word":"it","start":204.64,"end":204.86},{"word":"has","start":204.86,"end":205.04},{"word":"to","start":205.04,"end":205.24},{"word":"decide","start":205.24,"end":205.66},{"word":"to","start":205.66,"end":206.02},{"word":"be","start":206.02,"end":206.14},{"word":"either","start":206.14,"end":206.44},{"word":"vertically","start":206.44,"end":206.9},{"word":"or","start":206.9,"end":207.28},{"word":"horizontally","start":207.28,"end":207.9},{"word":"polarized.","start":207.9,"end":208.42}],"textKo":"이걸 중첩이라고 해. 하지만 값을 테스트하는 순간, 예를 들어 광자를 필터에 통과시키면, 수직 편광이든 수평 편광이든 하나로 결정해야 해.","listenDifficulty":3},{"index":31,"start":209.06,"end":216.84,"textEn":"So, as long as it''s unobserved, the qubit is in a superposition of probabilities for zero and one, and you can''t predict which it will be.","words":[{"word":"So,","start":209.06,"end":209.58},{"word":"as","start":209.84,"end":209.92},{"word":"long","start":209.92,"end":210.08},{"word":"as","start":210.08,"end":210.26},{"word":"it''s","start":210.26,"end":210.44},{"word":"unobserved,","start":210.44,"end":211.04},{"word":"the","start":211.36,"end":211.44},{"word":"qubit","start":211.44,"end":211.82},{"word":"is","start":211.82,"end":212.04},{"word":"in","start":212.04,"end":212.16},{"word":"a","start":212.16,"end":212.28},{"word":"superposition","start":212.28,"end":212.94},{"word":"of","start":212.94,"end":213.16},{"word":"probabilities","start":213.16,"end":213.64},{"word":"for","start":213.64,"end":213.98},{"word":"zero","start":213.98,"end":214.3},{"word":"and","start":214.3,"end":214.6},{"word":"one,","start":214.6,"end":214.82},{"word":"and","start":214.98,"end":215.36},{"word":"you","start":215.36,"end":215.5},{"word":"can''t","start":215.5,"end":215.74},{"word":"predict","start":215.74,"end":216.02},{"word":"which","start":216.02,"end":216.28},{"word":"it","start":216.28,"end":216.44},{"word":"will","start":216.44,"end":216.58},{"word":"be.","start":216.58,"end":216.84}],"textKo":"그래서 관측되지 않는 한, 큐비트는 0과 1에 대한 확률의 중첩 상태에 있고, 어느 쪽이 될지 예측할 수 없어.","listenDifficulty":3},{"index":32,"start":217.28,"end":221.7,"textEn":"But the instant you measure it, it collapses into one of the definite states.","words":[{"word":"But","start":217.28,"end":217.8},{"word":"the","start":217.8,"end":217.98},{"word":"instant","start":217.98,"end":218.38},{"word":"you","start":218.38,"end":218.64},{"word":"measure","start":218.64,"end":218.94},{"word":"it,","start":218.94,"end":219.12},{"word":"it","start":219.22,"end":219.5},{"word":"collapses","start":219.5,"end":220.0},{"word":"into","start":220.0,"end":220.48},{"word":"one","start":220.48,"end":220.66},{"word":"of","start":220.66,"end":220.76},{"word":"the","start":220.76,"end":220.88},{"word":"definite","start":220.88,"end":221.24},{"word":"states.","start":221.24,"end":221.7}],"textKo":"하지만 측정하는 순간, 확정된 상태 중 하나로 붕괴해.","listenDifficulty":3},{"index":33,"start":222.68,"end":230.08,"textEn":"Superposition is a game-changer. Four classical bits can be in one of two to the power of four different configurations at a time.","words":[{"word":"Superposition","start":222.68,"end":223.2},{"word":"is","start":223.2,"end":223.66},{"word":"a","start":223.66,"end":223.8},{"word":"game","start":223.8,"end":224.04},{"word":"-changer.","start":224.04,"end":224.44},{"word":"Four","start":224.44,"end":225.56},{"word":"classical","start":225.56,"end":226.04},{"word":"bits","start":226.04,"end":226.4},{"word":"can","start":226.4,"end":226.62},{"word":"be","start":226.62,"end":226.78},{"word":"in","start":226.78,"end":226.94},{"word":"one","start":226.94,"end":227.08},{"word":"of","start":227.08,"end":227.24},{"word":"two","start":227.24,"end":227.44},{"word":"to","start":227.44,"end":227.6},{"word":"the","start":227.6,"end":227.72},{"word":"power","start":227.72,"end":227.94},{"word":"of","start":227.94,"end":228.14},{"word":"four","start":228.14,"end":228.34},{"word":"different","start":228.34,"end":228.68},{"word":"configurations","start":228.68,"end":229.34},{"word":"at","start":229.34,"end":229.7},{"word":"a","start":229.7,"end":229.8},{"word":"time.","start":229.8,"end":230.08}],"textKo":"중첩은 게임 체인저야. 4개의 고전적 비트는 한 번에 2의 4승 가지 다른 구성 중 하나에만 있을 수 있어.","listenDifficulty":3},{"index":34,"start":230.28,"end":234.3,"textEn":"That''s sixteen possible combinations, out of which you can use just one.","words":[{"word":"That''s","start":230.28,"end":230.82},{"word":"sixteen","start":230.82,"end":231.24},{"word":"possible","start":231.24,"end":231.76},{"word":"combinations,","start":231.76,"end":232.32},{"word":"out","start":232.48,"end":232.88},{"word":"of","start":232.88,"end":232.98},{"word":"which","start":232.98,"end":233.16},{"word":"you","start":233.16,"end":233.3},{"word":"can","start":233.3,"end":233.44},{"word":"use","start":233.44,"end":233.68},{"word":"just","start":233.68,"end":233.96},{"word":"one.","start":233.96,"end":234.3}],"textKo":"16가지 가능한 조합 중에서 딱 하나만 사용할 수 있어.","listenDifficulty":2},{"index":35,"start":235.0,"end":240.18,"textEn":"Four qubits in superposition, however, can be in all of those sixteen combinations at once.","words":[{"word":"Four","start":235.0,"end":235.3},{"word":"qubits","start":235.3,"end":235.68},{"word":"in","start":235.68,"end":235.94},{"word":"superposition,","start":235.94,"end":236.62},{"word":"however,","start":236.74,"end":236.92},{"word":"can","start":237.3,"end":237.48},{"word":"be","start":237.48,"end":237.64},{"word":"in","start":237.64,"end":237.78},{"word":"all","start":237.78,"end":238.02},{"word":"of","start":238.02,"end":238.16},{"word":"those","start":238.16,"end":238.42},{"word":"sixteen","start":238.42,"end":238.76},{"word":"combinations","start":238.76,"end":239.38},{"word":"at","start":239.38,"end":239.8},{"word":"once.","start":239.8,"end":240.18}],"textKo":"하지만 중첩 상태의 4개 큐비트는 그 16가지 조합 모두에 동시에 있을 수 있어.","listenDifficulty":2},{"index":36,"start":240.68,"end":243.9,"textEn":"This number grows exponentially with each extra qubit.","words":[{"word":"This","start":240.68,"end":241.24},{"word":"number","start":241.24,"end":241.54},{"word":"grows","start":241.54,"end":241.84},{"word":"exponentially","start":241.84,"end":242.42},{"word":"with","start":242.42,"end":242.74},{"word":"each","start":242.74,"end":243.06},{"word":"extra","start":243.06,"end":243.48},{"word":"qubit.","start":243.48,"end":243.9}],"textKo":"이 숫자는 큐비트가 하나 추가될 때마다 기하급수적으로 늘어나.","listenDifficulty":1},{"index":37,"start":244.5,"end":247.94,"textEn":"Twenty of them can already store a million values in parallel.","words":[{"word":"Twenty","start":244.5,"end":244.84},{"word":"of","start":244.84,"end":245.08},{"word":"them","start":245.08,"end":245.22},{"word":"can","start":245.22,"end":245.4},{"word":"already","start":245.4,"end":245.72},{"word":"store","start":245.72,"end":246.04},{"word":"a","start":246.04,"end":246.28},{"word":"million","start":246.28,"end":246.68},{"word":"values","start":246.68,"end":247.24},{"word":"in","start":247.24,"end":247.52},{"word":"parallel.","start":247.52,"end":247.94}],"textKo":"20개만 있어도 이미 백만 개의 값을 동시에 저장할 수 있어.","listenDifficulty":3},{"index":38,"start":247.94,"end":259.94,"textEn":"A really weird and unintuitive property qubits can have is entanglement, a close connection that makes each of the qubits react to a change in the other''s state instantaneously, no matter how far they are apart.","words":[{"word":"A","start":247.94,"end":248.92},{"word":"really","start":248.92,"end":249.14},{"word":"weird","start":249.14,"end":249.48},{"word":"and","start":249.48,"end":249.78},{"word":"unintuitive","start":249.78,"end":250.42},{"word":"property","start":250.42,"end":250.78},{"word":"qubits","start":250.78,"end":251.16},{"word":"can","start":251.16,"end":251.32},{"word":"have","start":251.32,"end":251.56},{"word":"is","start":251.56,"end":252.0},{"word":"entanglement,","start":252.0,"end":252.78},{"word":"a","start":252.96,"end":253.28},{"word":"close","start":253.28,"end":253.56},{"word":"connection","start":253.56,"end":253.94},{"word":"that","start":253.94,"end":254.2},{"word":"makes","start":254.2,"end":254.42},{"word":"each","start":254.42,"end":254.68},{"word":"of","start":254.68,"end":254.86},{"word":"the","start":254.86,"end":254.96},{"word":"qubits","start":254.96,"end":255.28},{"word":"react","start":255.28,"end":255.62},{"word":"to","start":255.62,"end":255.78},{"word":"a","start":255.78,"end":255.88},{"word":"change","start":255.88,"end":256.12},{"word":"in","start":256.12,"end":256.3},{"word":"the","start":256.3,"end":256.4},{"word":"other''s","start":256.4,"end":256.8},{"word":"state","start":256.8,"end":256.96},{"word":"instantaneously,","start":256.96,"end":257.9},{"word":"no","start":258.16,"end":258.46},{"word":"matter","start":258.46,"end":258.66},{"word":"how","start":258.66,"end":258.92},{"word":"far","start":258.92,"end":259.2},{"word":"they","start":259.2,"end":259.38},{"word":"are","start":259.38,"end":259.54},{"word":"apart.","start":259.54,"end":259.94}],"textKo":"큐비트가 가질 수 있는 정말 이상하고 직관에 반하는 특성은 얽힘인데, 이건 아무리 멀리 떨어져 있어도 한 큐비트의 상태 변화에 다른 큐비트가 즉각적으로 반응하게 하는 긴밀한 연결이야.","listenDifficulty":3},{"index":39,"start":260.3,"end":267.38,"textEn":"This means that when measuring just one entangled qubit, you can directly deduce properties of its partners without having to look.","words":[{"word":"This","start":260.3,"end":260.9},{"word":"means","start":260.9,"end":261.12},{"word":"that","start":261.12,"end":261.34},{"word":"when","start":261.34,"end":261.48},{"word":"measuring","start":261.48,"end":261.86},{"word":"just","start":261.86,"end":262.18},{"word":"one","start":262.18,"end":262.44},{"word":"entangled","start":262.44,"end":262.92},{"word":"qubit,","start":262.92,"end":263.34},{"word":"you","start":263.5,"end":263.78},{"word":"can","start":263.78,"end":263.92},{"word":"directly","start":263.92,"end":264.4},{"word":"deduce","start":264.4,"end":264.82},{"word":"properties","start":264.82,"end":265.22},{"word":"of","start":265.22,"end":265.48},{"word":"its","start":265.48,"end":265.62},{"word":"partners","start":265.62,"end":266.06},{"word":"without","start":266.06,"end":266.5},{"word":"having","start":266.5,"end":266.9},{"word":"to","start":266.9,"end":267.08},{"word":"look.","start":267.08,"end":267.38}],"textKo":"이건 얽힌 큐비트 하나만 측정해도, 볼 필요 없이 상대 큐비트의 특성을 직접 추론할 수 있다는 뜻이야.","listenDifficulty":3},{"index":40,"start":267.86,"end":270.6,"textEn":"Qubit manipulation is a mind-bender as well.","words":[{"word":"Qubit","start":267.86,"end":268.46},{"word":"manipulation","start":268.46,"end":268.9},{"word":"is","start":268.9,"end":269.38},{"word":"a","start":269.38,"end":269.5},{"word":"mind","start":269.5,"end":269.82},{"word":"-bender","start":269.82,"end":270.14},{"word":"as","start":270.14,"end":270.36},{"word":"well.","start":270.36,"end":270.6}],"textKo":"큐비트 조작도 정신이 아찔해.","listenDifficulty":2},{"index":41,"start":270.98,"end":276.14,"textEn":"A normal logic gate gets a simple set of inputs and produces one definite output.","words":[{"word":"A","start":270.98,"end":271.34},{"word":"normal","start":271.34,"end":271.76},{"word":"logic","start":271.76,"end":272.12},{"word":"gate","start":272.12,"end":272.36},{"word":"gets","start":272.36,"end":272.8},{"word":"a","start":272.8,"end":273.0},{"word":"simple","start":273.0,"end":273.34},{"word":"set","start":273.34,"end":273.54},{"word":"of","start":273.54,"end":273.66},{"word":"inputs","start":273.66,"end":274.06},{"word":"and","start":274.06,"end":274.48},{"word":"produces","start":274.48,"end":274.86},{"word":"one","start":274.86,"end":275.24},{"word":"definite","start":275.24,"end":275.62},{"word":"output.","start":275.62,"end":276.14}],"textKo":"일반 논리 게이트는 단순한 입력 세트를 받아서 하나의 확정된 출력을 생성해.","listenDifficulty":2},{"index":42,"start":276.14,"end":284.66,"textEn":"A quantum gate manipulates an input of superpositions, rotates probabilities, and produces another superposition as its output.","words":[{"word":"A","start":276.14,"end":276.9},{"word":"quantum","start":276.9,"end":277.32},{"word":"gate","start":277.32,"end":277.68},{"word":"manipulates","start":277.68,"end":278.48},{"word":"an","start":278.48,"end":278.62},{"word":"input","start":278.62,"end":278.94},{"word":"of","start":278.94,"end":279.12},{"word":"superpositions,","start":279.12,"end":279.82},{"word":"rotates","start":280.16,"end":280.78},{"word":"probabilities,","start":280.78,"end":281.36},{"word":"and","start":281.56,"end":282.0},{"word":"produces","start":282.0,"end":282.46},{"word":"another","start":282.46,"end":283.02},{"word":"superposition","start":283.02,"end":283.78},{"word":"as","start":283.78,"end":284.12},{"word":"its","start":284.12,"end":284.26},{"word":"output.","start":284.26,"end":284.66}],"textKo":"양자 게이트는 중첩 입력을 조작하고, 확률을 회전시키고, 다른 중첩을 출력으로 생성해.","listenDifficulty":1},{"index":43,"start":285.04,"end":291.32,"textEn":"So a quantum computer sets up some qubits, applies quantum gates to entangle them and manipulate probabilities,","words":[{"word":"So","start":285.04,"end":285.68},{"word":"a","start":285.68,"end":285.86},{"word":"quantum","start":285.86,"end":286.22},{"word":"computer","start":286.22,"end":286.72},{"word":"sets","start":286.72,"end":287.06},{"word":"up","start":287.06,"end":287.28},{"word":"some","start":287.28,"end":287.46},{"word":"qubits,","start":287.46,"end":287.88},{"word":"applies","start":288.18,"end":288.56},{"word":"quantum","start":288.56,"end":288.92},{"word":"gates","start":288.92,"end":289.22},{"word":"to","start":289.22,"end":289.38},{"word":"entangle","start":289.38,"end":289.8},{"word":"them","start":289.8,"end":289.96},{"word":"and","start":289.96,"end":290.22},{"word":"manipulate","start":290.22,"end":290.66},{"word":"probabilities,","start":290.66,"end":291.32}],"textKo":"그래서 양자 컴퓨터는 큐비트를 설정하고, 양자 게이트를 적용해서 큐비트들을 얽히게 하고 확률을 조작해.","listenDifficulty":1},{"index":44,"start":291.52,"end":297.34,"textEn":"And finally measures the outcome, collapsing superpositions to an actual sequence of zeros and ones.","words":[{"word":"and","start":291.52,"end":291.88},{"word":"finally","start":291.88,"end":292.26},{"word":"measures","start":292.26,"end":292.64},{"word":"the","start":292.64,"end":292.78},{"word":"outcome,","start":292.78,"end":293.2},{"word":"collapsing","start":293.56,"end":294.1},{"word":"superpositions","start":294.1,"end":294.94},{"word":"to","start":294.94,"end":295.32},{"word":"an","start":295.32,"end":295.44},{"word":"actual","start":295.44,"end":295.78},{"word":"sequence","start":295.78,"end":296.16},{"word":"of","start":296.16,"end":296.44},{"word":"zeros","start":296.44,"end":296.72},{"word":"and","start":296.72,"end":297.04},{"word":"ones.","start":297.04,"end":297.34}],"textKo":"그리고 마지막으로 결과를 측정해서, 중첩을 0과 1의 실제 시퀀스로 붕괴시켜.","listenDifficulty":1},{"index":45,"start":297.72,"end":304.06,"textEn":"What this means is that you get the entire lot of calculations that are possible with your setup all done at the same time.","words":[{"word":"What","start":297.72,"end":298.34},{"word":"this","start":298.34,"end":298.54},{"word":"means","start":298.54,"end":298.84},{"word":"is","start":298.84,"end":299.06},{"word":"that","start":299.06,"end":299.18},{"word":"you","start":299.18,"end":299.3},{"word":"get","start":299.3,"end":299.46},{"word":"the","start":299.46,"end":299.6},{"word":"entire","start":299.6,"end":300.02},{"word":"lot","start":300.02,"end":300.26},{"word":"of","start":300.26,"end":300.4},{"word":"calculations","start":300.4,"end":300.9},{"word":"that","start":300.9,"end":301.22},{"word":"are","start":301.22,"end":301.34},{"word":"possible","start":301.34,"end":301.7},{"word":"with","start":301.7,"end":301.96},{"word":"your","start":301.96,"end":302.14},{"word":"setup","start":302.14,"end":302.46},{"word":"all","start":302.46,"end":302.78},{"word":"done","start":302.78,"end":303.04},{"word":"at","start":303.04,"end":303.32},{"word":"the","start":303.32,"end":303.46},{"word":"same","start":303.46,"end":303.7},{"word":"time.","start":303.7,"end":304.06}],"textKo":"이게 의미하는 건, 설정으로 가능한 모든 계산을 동시에 처리한다는 거야.","listenDifficulty":3},{"index":46,"start":304.68,"end":311.6,"textEn":"Ultimately, you can only measure one of the results, and it will only probably be the one you want, so you may have to double-check and try again.","words":[{"word":"Ultimately,","start":304.68,"end":305.2},{"word":"you","start":305.46,"end":305.48},{"word":"can","start":305.48,"end":305.62},{"word":"only","start":305.62,"end":305.9},{"word":"measure","start":305.9,"end":306.2},{"word":"one","start":306.2,"end":306.42},{"word":"of","start":306.42,"end":306.52},{"word":"the","start":306.52,"end":306.6},{"word":"results,","start":306.6,"end":306.94},{"word":"and","start":307.06,"end":307.42},{"word":"it","start":307.42,"end":307.54},{"word":"will","start":307.54,"end":307.68},{"word":"only","start":307.68,"end":308.04},{"word":"probably","start":308.04,"end":308.38},{"word":"be","start":308.38,"end":308.66},{"word":"the","start":308.66,"end":308.8},{"word":"one","start":308.8,"end":308.94},{"word":"you","start":308.94,"end":309.1},{"word":"want,","start":309.1,"end":309.36},{"word":"so","start":309.54,"end":309.8},{"word":"you","start":309.8,"end":309.94},{"word":"may","start":309.94,"end":310.08},{"word":"have","start":310.08,"end":310.28},{"word":"to","start":310.28,"end":310.4},{"word":"double","start":310.4,"end":310.66},{"word":"-check","start":310.66,"end":310.86},{"word":"and","start":310.86,"end":311.04},{"word":"try","start":311.04,"end":311.22},{"word":"again.","start":311.22,"end":311.6}],"textKo":"결국 결과 중 하나만 측정할 수 있고, 그것도 원하는 결과일 확률이 있을 뿐이라서, 다시 확인하고 재시도해야 할 수도 있어.","listenDifficulty":3},{"index":47,"start":312.54,"end":320.24,"textEn":"But by cleverly exploiting superposition and entanglement, this can be exponentially more efficient than would ever be possible on a normal computer.","words":[{"word":"But","start":312.54,"end":313.06},{"word":"by","start":313.06,"end":313.36},{"word":"cleverly","start":313.36,"end":313.78},{"word":"exploiting","start":313.78,"end":314.34},{"word":"superposition","start":314.34,"end":315.0},{"word":"and","start":315.0,"end":315.28},{"word":"entanglement,","start":315.28,"end":315.82},{"word":"this","start":315.98,"end":316.3},{"word":"can","start":316.3,"end":316.42},{"word":"be","start":316.42,"end":316.56},{"word":"exponentially","start":316.56,"end":317.16},{"word":"more","start":317.16,"end":317.52},{"word":"efficient","start":317.52,"end":317.92},{"word":"than","start":317.92,"end":318.32},{"word":"would","start":318.32,"end":318.46},{"word":"ever","start":318.46,"end":318.68},{"word":"be","start":318.68,"end":318.82},{"word":"possible","start":318.82,"end":319.16},{"word":"on","start":319.16,"end":319.44},{"word":"a","start":319.44,"end":319.56},{"word":"normal","start":319.56,"end":319.8},{"word":"computer.","start":319.8,"end":320.24}],"textKo":"하지만 중첩과 얽힘을 영리하게 활용하면, 일반 컴퓨터에서는 절대 불가능한 수준으로 기하급수적으로 더 효율적일 수 있어.","listenDifficulty":2},{"index":48,"start":321.42,"end":328.02,"textEn":"So while quantum computers will probably not replace our home computers, in some areas they are vastly superior.","words":[{"word":"So","start":321.42,"end":322.02},{"word":"while","start":322.02,"end":322.38},{"word":"quantum","start":322.38,"end":322.74},{"word":"computers","start":322.74,"end":323.24},{"word":"will","start":323.24,"end":323.42},{"word":"probably","start":323.42,"end":323.76},{"word":"not","start":323.76,"end":324.0},{"word":"replace","start":324.0,"end":324.38},{"word":"our","start":324.38,"end":324.7},{"word":"home","start":324.7,"end":324.96},{"word":"computers,","start":324.96,"end":325.42},{"word":"in","start":325.6,"end":325.92},{"word":"some","start":325.92,"end":326.12},{"word":"areas","start":326.12,"end":326.48},{"word":"they","start":326.48,"end":326.8},{"word":"are","start":326.8,"end":327.0},{"word":"vastly","start":327.0,"end":327.46},{"word":"superior.","start":327.46,"end":328.02}],"textKo":"그래서 양자 컴퓨터가 아마 가정용 컴퓨터를 대체하지는 않겠지만, 일부 영역에서는 압도적으로 뛰어나.","listenDifficulty":3},{"index":49,"start":328.86,"end":335.44,"textEn":"One of them is database searching. To find something in a database, a normal computer may have to test every single one of its entries.","words":[{"word":"One","start":328.86,"end":328.98},{"word":"of","start":328.98,"end":329.08},{"word":"them","start":329.08,"end":329.2},{"word":"is","start":329.2,"end":329.44},{"word":"database","start":329.44,"end":329.78},{"word":"searching.","start":329.78,"end":330.32},{"word":"To","start":330.68,"end":331.04},{"word":"find","start":331.04,"end":331.28},{"word":"something","start":331.28,"end":331.6},{"word":"in","start":331.6,"end":331.76},{"word":"a","start":331.76,"end":331.8},{"word":"database,","start":331.8,"end":332.18},{"word":"a","start":332.46,"end":332.64},{"word":"normal","start":332.64,"end":332.9},{"word":"computer","start":332.9,"end":333.3},{"word":"may","start":333.3,"end":333.5},{"word":"have","start":333.5,"end":333.68},{"word":"to","start":333.68,"end":333.8},{"word":"test","start":333.8,"end":334.04},{"word":"every","start":334.04,"end":334.36},{"word":"single","start":334.36,"end":334.66},{"word":"one","start":334.66,"end":334.88},{"word":"of","start":334.88,"end":334.98},{"word":"its","start":334.98,"end":335.12},{"word":"entries.","start":335.12,"end":335.44}],"textKo":"그중 하나가 데이터베이스 검색이야. 데이터베이스에서 뭔가를 찾으려면, 일반 컴퓨터는 모든 항목을 하나하나 테스트해야 할 수도 있어.","listenDifficulty":3},{"index":50,"start":336.04,"end":341.82,"textEn":"Quantum algorithms need only the square root of that time, which for large databases is a huge difference.","words":[{"word":"Quantum","start":336.04,"end":336.36},{"word":"algorithms","start":336.36,"end":336.92},{"word":"need","start":336.92,"end":337.4},{"word":"only","start":337.4,"end":337.72},{"word":"the","start":337.72,"end":337.88},{"word":"square","start":337.88,"end":338.14},{"word":"root","start":338.14,"end":338.42},{"word":"of","start":338.42,"end":338.54},{"word":"that","start":338.54,"end":338.7},{"word":"time,","start":338.7,"end":339.0},{"word":"which","start":339.22,"end":339.52},{"word":"for","start":339.52,"end":339.64},{"word":"large","start":339.64,"end":339.94},{"word":"databases","start":339.94,"end":340.44},{"word":"is","start":340.44,"end":340.92},{"word":"a","start":340.92,"end":341.04},{"word":"huge","start":341.04,"end":341.36},{"word":"difference.","start":341.36,"end":341.82}],"textKo":"양자 알고리즘은 그 시간의 제곱근만 필요한데, 큰 데이터베이스에서는 엄청난 차이야.","listenDifficulty":3},{"index":51,"start":341.82,"end":346.46,"textEn":"The most famous use of quantum computers is ruining IT security.","words":[{"word":"The","start":341.82,"end":342.92},{"word":"most","start":342.92,"end":343.12},{"word":"famous","start":343.12,"end":343.42},{"word":"use","start":343.42,"end":343.68},{"word":"of","start":343.68,"end":343.86},{"word":"quantum","start":343.86,"end":344.1},{"word":"computers","start":344.1,"end":344.64},{"word":"is","start":344.64,"end":345.12},{"word":"ruining","start":345.12,"end":345.46},{"word":"IT","start":345.46,"end":345.88},{"word":"security.","start":345.88,"end":346.46}],"textKo":"양자 컴퓨터의 가장 유명한 용도는 IT 보안을 무너뜨리는 거야.","listenDifficulty":2},{"index":52,"start":347.04,"end":352.18,"textEn":"Right now, your browsing, email and banking data is being kept secure by an encryption system","words":[{"word":"Right","start":347.04,"end":347.56},{"word":"now,","start":347.56,"end":347.78},{"word":"your","start":347.98,"end":348.08},{"word":"browsing,","start":348.08,"end":348.48},{"word":"email","start":348.64,"end":348.9},{"word":"and","start":348.9,"end":349.1},{"word":"banking","start":349.1,"end":349.4},{"word":"data","start":349.4,"end":349.74},{"word":"is","start":349.74,"end":350.2},{"word":"being","start":350.2,"end":350.42},{"word":"kept","start":350.42,"end":350.7},{"word":"secure","start":350.7,"end":351.06},{"word":"by","start":351.06,"end":351.28},{"word":"an","start":351.28,"end":351.42},{"word":"encryption","start":351.42,"end":351.74},{"word":"system","start":351.74,"end":352.18}],"textKo":"지금 당장 너의 웹 브라우징, 이메일, 은행 데이터는 암호화 시스템으로 안전하게 보호되고 있어.","listenDifficulty":3},{"index":53,"start":352.18,"end":356.46,"textEn":"In which you give everyone a public key to encode messages only you can decode.","words":[{"word":"in","start":352.18,"end":352.4},{"word":"which","start":352.4,"end":352.6},{"word":"you","start":352.6,"end":352.74},{"word":"give","start":352.74,"end":352.94},{"word":"everyone","start":352.94,"end":353.32},{"word":"a","start":353.32,"end":353.48},{"word":"public","start":353.48,"end":353.72},{"word":"key","start":353.72,"end":353.98},{"word":"to","start":353.98,"end":354.16},{"word":"encode","start":354.16,"end":354.58},{"word":"messages","start":354.58,"end":355.0},{"word":"only","start":355.0,"end":355.42},{"word":"you","start":355.42,"end":355.7},{"word":"can","start":355.7,"end":355.94},{"word":"decode.","start":355.94,"end":356.46}],"textKo":"모든 사람에게 공개 키를 줘서 너만 해독할 수 있는 메시지를 암호화하게 하는 방식이지.","listenDifficulty":3},{"index":54,"start":356.76,"end":362.0,"textEn":"The problem is that this public key can actually be used to calculate your secret private key.","words":[{"word":"The","start":356.76,"end":357.24},{"word":"problem","start":357.24,"end":357.54},{"word":"is","start":357.54,"end":357.74},{"word":"that","start":357.74,"end":357.88},{"word":"this","start":357.88,"end":358.08},{"word":"public","start":358.08,"end":358.42},{"word":"key","start":358.42,"end":358.72},{"word":"can","start":358.72,"end":359.08},{"word":"actually","start":359.08,"end":359.44},{"word":"be","start":359.44,"end":359.64},{"word":"used","start":359.64,"end":359.94},{"word":"to","start":359.94,"end":360.12},{"word":"calculate","start":360.12,"end":360.56},{"word":"your","start":360.56,"end":360.88},{"word":"secret","start":360.88,"end":361.28},{"word":"private","start":361.28,"end":361.7},{"word":"key.","start":361.7,"end":362.0}],"textKo":"문제는 이 공개 키로 실제로 너의 비밀 개인 키를 계산할 수 있다는 거야.","listenDifficulty":2},{"index":55,"start":362.42,"end":367.56,"textEn":"Luckily, doing the necessary math on any normal computer would literally take years of trial and error.","words":[{"word":"Luckily,","start":362.42,"end":362.98},{"word":"doing","start":363.14,"end":363.54},{"word":"the","start":363.54,"end":363.7},{"word":"necessary","start":363.7,"end":364.12},{"word":"math","start":364.12,"end":364.4},{"word":"on","start":364.4,"end":364.58},{"word":"any","start":364.58,"end":364.8},{"word":"normal","start":364.8,"end":365.06},{"word":"computer","start":365.06,"end":365.48},{"word":"would","start":365.48,"end":365.9},{"word":"literally","start":365.9,"end":366.18},{"word":"take","start":366.18,"end":366.46},{"word":"years","start":366.46,"end":366.78},{"word":"of","start":366.78,"end":366.98},{"word":"trial","start":366.98,"end":367.22},{"word":"and","start":367.22,"end":367.38},{"word":"error.","start":367.38,"end":367.56}],"textKo":"다행히, 일반 컴퓨터로 필요한 수학을 하면 말 그대로 몇 년이나 시행착오가 걸려.","listenDifficulty":2},{"index":56,"start":367.56,"end":371.86,"textEn":"But a quantum computer with exponential speed-up could do it in a breeze.","words":[{"word":"But","start":367.56,"end":368.36},{"word":"a","start":368.36,"end":368.54},{"word":"quantum","start":368.54,"end":368.88},{"word":"computer","start":368.88,"end":369.34},{"word":"with","start":369.34,"end":369.58},{"word":"exponential","start":369.58,"end":370.08},{"word":"speed","start":370.08,"end":370.48},{"word":"-up","start":370.48,"end":370.64},{"word":"could","start":370.64,"end":371.04},{"word":"do","start":371.04,"end":371.22},{"word":"it","start":371.22,"end":371.36},{"word":"in","start":371.36,"end":371.48},{"word":"a","start":371.48,"end":371.54},{"word":"breeze.","start":371.54,"end":371.86}],"textKo":"하지만 기하급수적 속도 향상을 가진 양자 컴퓨터라면 순식간에 할 수 있어.","listenDifficulty":3},{"index":57,"start":372.4,"end":375.12,"textEn":"Another really exciting new use is simulations.","words":[{"word":"Another","start":372.4,"end":372.98},{"word":"really","start":372.98,"end":373.24},{"word":"exciting","start":373.24,"end":373.66},{"word":"new","start":373.66,"end":373.9},{"word":"use","start":373.9,"end":374.16},{"word":"is","start":374.16,"end":374.42},{"word":"simulations.","start":374.42,"end":375.12}],"textKo":"또 다른 정말 흥미로운 용도는 시뮬레이션이야.","listenDifficulty":2},{"index":58,"start":375.78,"end":378.8,"textEn":"Simulations of the quantum world are very intense on resources,","words":[{"word":"Simulations","start":375.78,"end":376.44},{"word":"of","start":376.44,"end":376.7},{"word":"the","start":376.7,"end":376.78},{"word":"quantum","start":376.78,"end":376.98},{"word":"world","start":376.98,"end":377.26},{"word":"are","start":377.26,"end":377.5},{"word":"very","start":377.5,"end":377.76},{"word":"intense","start":377.76,"end":378.14},{"word":"on","start":378.14,"end":378.38},{"word":"resources,","start":378.38,"end":378.8}],"textKo":"양자 세계의 시뮬레이션은 자원을 매우 많이 소모하고,","listenDifficulty":2},{"index":59,"start":379.02,"end":383.78,"textEn":"And even for bigger structures such as molecules, they often lack accuracy.","words":[{"word":"and","start":379.02,"end":379.42},{"word":"even","start":379.42,"end":379.74},{"word":"for","start":379.74,"end":380.08},{"word":"bigger","start":380.08,"end":380.5},{"word":"structures","start":380.5,"end":381.08},{"word":"such","start":381.08,"end":381.42},{"word":"as","start":381.42,"end":381.62},{"word":"molecules,","start":381.62,"end":382.04},{"word":"they","start":382.48,"end":382.58},{"word":"often","start":382.58,"end":382.9},{"word":"lack","start":382.9,"end":383.2},{"word":"accuracy.","start":383.2,"end":383.78}],"textKo":"분자 같은 더 큰 구조에서도 정확도가 부족한 경우가 많아.","listenDifficulty":2},{"index":60,"start":384.14,"end":388.2,"textEn":"So why not simulate quantum physics with actual quantum physics?","words":[{"word":"So","start":384.14,"end":384.8},{"word":"why","start":384.8,"end":385.06},{"word":"not","start":385.06,"end":385.26},{"word":"simulate","start":385.26,"end":385.68},{"word":"quantum","start":385.68,"end":386.1},{"word":"physics","start":386.1,"end":386.44},{"word":"with","start":386.44,"end":386.92},{"word":"actual","start":386.92,"end":387.36},{"word":"quantum","start":387.36,"end":387.76},{"word":"physics?","start":387.76,"end":388.2}],"textKo":"그러면 실제 양자 물리학으로 양자 물리학을 시뮬레이션하면 어떨까?","listenDifficulty":1},{"index":61,"start":388.82,"end":393.74,"textEn":"Quantum simulations could provide new insights on proteins that might revolutionize medicine.","words":[{"word":"Quantum","start":388.82,"end":389.42},{"word":"simulations","start":389.42,"end":389.98},{"word":"could","start":389.98,"end":390.26},{"word":"provide","start":390.26,"end":390.62},{"word":"new","start":390.62,"end":390.84},{"word":"insights","start":390.84,"end":391.26},{"word":"on","start":391.26,"end":391.48},{"word":"proteins","start":391.48,"end":391.9},{"word":"that","start":391.9,"end":392.32},{"word":"might","start":392.32,"end":392.52},{"word":"revolutionize","start":392.52,"end":393.36},{"word":"medicine.","start":393.36,"end":393.74}],"textKo":"양자 시뮬레이션은 의학을 혁명적으로 변화시킬 수 있는 단백질에 대한 새로운 통찰을 제공할 수 있어.","listenDifficulty":2},{"index":62,"start":394.3,"end":398.38,"textEn":"Right now, we don''t know if quantum computers will be just a very specialized tool,","words":[{"word":"Right","start":394.3,"end":394.78},{"word":"now,","start":394.78,"end":395.0},{"word":"we","start":395.22,"end":395.26},{"word":"don''t","start":395.26,"end":395.5},{"word":"know","start":395.5,"end":395.68},{"word":"if","start":395.68,"end":395.84},{"word":"quantum","start":395.84,"end":396.12},{"word":"computers","start":396.12,"end":396.62},{"word":"will","start":396.62,"end":396.8},{"word":"be","start":396.8,"end":396.9},{"word":"just","start":396.9,"end":397.1},{"word":"a","start":397.1,"end":397.28},{"word":"very","start":397.28,"end":397.44},{"word":"specialized","start":397.44,"end":397.88},{"word":"tool,","start":397.88,"end":398.38}],"textKo":"지금으로서는, 양자 컴퓨터가 그저 매우 전문적인 도구가 될지,","listenDifficulty":3},{"index":63,"start":398.54,"end":400.62,"textEn":"Or a big revolution for humanity.","words":[{"word":"or","start":398.54,"end":398.94},{"word":"a","start":398.94,"end":399.06},{"word":"big","start":399.06,"end":399.26},{"word":"revolution","start":399.26,"end":399.84},{"word":"for","start":399.84,"end":400.2},{"word":"humanity.","start":400.2,"end":400.62}],"textKo":"아니면 인류에게 큰 혁명이 될지 모르겠어.","listenDifficulty":1},{"index":64,"start":400.9,"end":405.92,"textEn":"We have no idea where the limits of technology are, and there''s only one way to find out.","words":[{"word":"We","start":400.9,"end":401.36},{"word":"have","start":401.36,"end":401.6},{"word":"no","start":401.6,"end":401.82},{"word":"idea","start":401.82,"end":402.22},{"word":"where","start":402.22,"end":402.5},{"word":"the","start":402.5,"end":402.6},{"word":"limits","start":402.6,"end":402.84},{"word":"of","start":402.84,"end":403.0},{"word":"technology","start":403.0,"end":403.44},{"word":"are,","start":403.44,"end":403.74},{"word":"and","start":403.86,"end":404.14},{"word":"there''s","start":404.14,"end":404.4},{"word":"only","start":404.4,"end":404.62},{"word":"one","start":404.62,"end":404.92},{"word":"way","start":404.92,"end":405.16},{"word":"to","start":405.16,"end":405.36},{"word":"find","start":405.36,"end":405.62},{"word":"out.","start":405.62,"end":405.92}],"textKo":"기술의 한계가 어디인지 알 수 없고, 알아내는 방법은 하나뿐이야.","listenDifficulty":3},{"index":65,"start":407.42,"end":410.58,"textEn":"This video is supported by the Australian Academy of Science,","words":[{"word":"This","start":407.42,"end":407.9},{"word":"video","start":407.9,"end":408.14},{"word":"is","start":408.14,"end":408.46},{"word":"supported","start":408.46,"end":408.84},{"word":"by","start":408.84,"end":409.08},{"word":"the","start":409.08,"end":409.22},{"word":"Australian","start":409.22,"end":409.64},{"word":"Academy","start":409.64,"end":410.02},{"word":"of","start":410.02,"end":410.26},{"word":"Science,","start":410.26,"end":410.58}],"textKo":"이 영상은 호주 과학 아카데미의 지원을 받았어.","listenDifficulty":2},{"index":66,"start":410.76,"end":413.54,"textEn":"Which promotes and supports excellence in science.","words":[{"word":"which","start":410.76,"end":411.04},{"word":"promotes","start":411.04,"end":411.44},{"word":"and","start":411.44,"end":411.74},{"word":"supports","start":411.74,"end":412.26},{"word":"excellence","start":412.26,"end":412.88},{"word":"in","start":412.88,"end":413.18},{"word":"science.","start":413.18,"end":413.54}],"textKo":"과학의 우수성을 촉진하고 지원하는 곳이야.","listenDifficulty":1},{"index":67,"start":414.18,"end":418.46,"textEn":"Learn more about this topic and others like it at nova. org. au.","words":[{"word":"Learn","start":414.18,"end":414.62},{"word":"more","start":414.62,"end":414.84},{"word":"about","start":414.84,"end":415.08},{"word":"this","start":415.08,"end":415.34},{"word":"topic","start":415.34,"end":415.62},{"word":"and","start":415.62,"end":415.84},{"word":"others","start":415.84,"end":416.14},{"word":"like","start":416.14,"end":416.4},{"word":"it","start":416.4,"end":416.58},{"word":"at","start":416.58,"end":417.08},{"word":"nova","start":417.08,"end":417.4},{"word":".org","start":417.4,"end":417.86},{"word":".au.","start":417.86,"end":418.46}],"textKo":"이 주제와 비슷한 주제에 대해 nova.org.au에서 더 알아봐.","listenDifficulty":2},{"index":68,"start":418.66,"end":421.8,"textEn":"It was a blast to work with them, so go check out their site.","words":[{"word":"It","start":418.66,"end":419.02},{"word":"was","start":419.02,"end":419.14},{"word":"a","start":419.14,"end":419.22},{"word":"blast","start":419.22,"end":419.44},{"word":"to","start":419.44,"end":419.64},{"word":"work","start":419.64,"end":419.8},{"word":"with","start":419.8,"end":419.96},{"word":"them,","start":419.96,"end":420.1},{"word":"so","start":420.28,"end":420.66},{"word":"go","start":420.66,"end":420.9},{"word":"check","start":420.9,"end":421.12},{"word":"out","start":421.12,"end":421.3},{"word":"their","start":421.3,"end":421.5},{"word":"site.","start":421.5,"end":421.8}],"textKo":"같이 작업하는 게 정말 즐거웠으니까 사이트를 확인해 봐.","listenDifficulty":3},{"index":69,"start":421.8,"end":426.04,"textEn":"Our videos are also made possible by your support on patreon. com.","words":[{"word":"Our","start":421.8,"end":422.6},{"word":"videos","start":422.6,"end":422.92},{"word":"are","start":422.92,"end":423.12},{"word":"also","start":423.12,"end":423.34},{"word":"made","start":423.34,"end":423.58},{"word":"possible","start":423.58,"end":423.94},{"word":"by","start":423.94,"end":424.2},{"word":"your","start":424.2,"end":424.4},{"word":"support","start":424.4,"end":424.74},{"word":"on","start":424.74,"end":425.02},{"word":"patreon","start":425.02,"end":425.38},{"word":".com.","start":425.38,"end":426.04}],"textKo":"우리 영상은 patreon.com에서의 여러분의 후원으로도 만들어져.","listenDifficulty":1},{"index":70,"start":426.3,"end":432.32,"textEn":"If you want to support us and become part of the Kotz-Gasacht Bird Army, check out our Patreon page.","words":[{"word":"If","start":426.3,"end":426.86},{"word":"you","start":426.86,"end":427.08},{"word":"want","start":427.08,"end":427.3},{"word":"to","start":427.3,"end":427.44},{"word":"support","start":427.44,"end":427.72},{"word":"us","start":427.72,"end":428.04},{"word":"and","start":428.04,"end":428.32},{"word":"become","start":428.32,"end":428.64},{"word":"part","start":428.64,"end":429.12},{"word":"of","start":429.12,"end":429.3},{"word":"the","start":429.3,"end":429.42},{"word":"Kotz","start":429.42,"end":429.72},{"word":"-Gasacht","start":429.72,"end":430.1},{"word":"Bird","start":430.1,"end":430.36},{"word":"Army,","start":430.36,"end":430.68},{"word":"check","start":430.88,"end":431.16},{"word":"out","start":431.16,"end":431.36},{"word":"our","start":431.36,"end":431.54},{"word":"Patreon","start":431.54,"end":431.88},{"word":"page.","start":431.88,"end":432.32}],"textKo":"우리를 지원하고 쿠르츠게작트 새 군단의 일원이 되고 싶으면, 패트리온 페이지를 확인해 봐.","listenDifficulty":2},{"index":71,"start":432.32,"end":435.92,"textEn":"Our apology is operated by our apology.","words":[{"word":"Our","start":432.32,"end":434.82},{"word":"apology","start":434.82,"end":434.88},{"word":"is","start":434.88,"end":435.92},{"word":"operated","start":435.92,"end":435.92},{"word":"by","start":435.92,"end":435.92},{"word":"our","start":435.92,"end":435.92},{"word":"apology.","start":435.92,"end":435.92}],"textKo":"","listenDifficulty":1},{"index":72,"start":435.92,"end":436.62,"textEn":"Our apology is operated by our apology.","words":[{"word":"Our","start":435.92,"end":436.62},{"word":"apology","start":436.62,"end":436.62},{"word":"is","start":436.62,"end":436.62},{"word":"operated","start":436.62,"end":436.62},{"word":"by","start":436.62,"end":436.62},{"word":"our","start":436.62,"end":436.62},{"word":"apology.","start":436.62,"end":436.62}],"textKo":"","listenDifficulty":3}]}'::jsonb, '[{"word":"exponentially","definition":"at a rate that becomes increasingly rapid in proportion to the growing total","meaningKo":"기하급수적으로","etymology":"Latin ''exponere'' meaning ''to put out, explain'' via mathematical ''exponent''","rootBreakdown":{"prefix":"ex-","root":"pon (put, place)","suffix":"-entially"},"relatedWords":["exponent","exponential","exponentiation"],"isEssential":true,"partOfSpeech":"adverb","phonetic":"/ˌɛkspəˈnɛnʃəli/","contextSentence":"The power of our brain machines has kept growing exponentially.","segmentIndex":2},{"word":"transistor","definition":"a semiconductor device used to amplify or switch electronic signals and electrical power","meaningKo":"트랜지스터 (전자 신호를 증폭하거나 전환하는 반도체 소자)","etymology":"Blend of ''transfer'' + ''resistor'' — transfers current across a resistor","rootBreakdown":{"prefix":"trans-","root":"fer/resist (carry/oppose)","suffix":"-or"},"relatedWords":["transfer","resistor","semiconductor"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/trænˈzɪstər/","contextSentence":"A transistor is the simplest form of a data processor in computers.","segmentIndex":8},{"word":"quantum","definition":"relating to the branch of physics dealing with the behavior of matter and energy at the smallest scales","meaningKo":"양자의, 양자역학에 관한","etymology":"Latin ''quantum'' meaning ''how much, how great''","rootBreakdown":{"prefix":null,"root":"quant (how much)","suffix":"-um"},"relatedWords":["quantity","quantify","quantize"],"isEssential":true,"partOfSpeech":"adjective","phonetic":"/ˈkwɒntəm/","contextSentence":"Electrons may just transfer themselves to the other side via a process called quantum tunneling.","segmentIndex":21},{"word":"superposition","definition":"a quantum state in which a particle exists in multiple states simultaneously until measured","meaningKo":"중첩 (양자역학에서 여러 상태가 동시에 존재하는 것)","etymology":"Latin ''super-'' (above, on top of) + ''positio'' (placing)","rootBreakdown":{"prefix":"super-","root":"posit (place)","suffix":"-ion"},"relatedWords":["position","superimpose","compose"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ˌsuːpərpəˈzɪʃən/","contextSentence":"This is called superposition.","segmentIndex":30},{"word":"entanglement","definition":"a quantum phenomenon where particles become interconnected so that the state of one instantly influences the other","meaningKo":"얽힘, 양자 얽힘 (입자들이 상호 연결되어 한쪽의 상태가 즉시 다른 쪽에 영향을 미치는 현상)","etymology":"Old French ''entangler'' meaning ''to tangle up, ensnare''","rootBreakdown":{"prefix":"en-","root":"tangle (twist together)","suffix":"-ment"},"relatedWords":["entangle","tangle","disentangle"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ɪnˈtæŋɡəlmənt/","contextSentence":"A really weird and unintuitive property qubits can have is entanglement.","segmentIndex":38},{"word":"polarization","definition":"the orientation of vibrations of a wave, especially light, in a particular direction","meaningKo":"편광 (빛 등의 파동이 특정 방향으로 진동하는 것)","etymology":"French ''polarisation'' from ''polaire'' (polar)","rootBreakdown":{"prefix":null,"root":"polar (of the pole)","suffix":"-ization"},"relatedWords":["polarize","polar","bipolar"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ˌpoʊlərɪˈzeɪʃən/","contextSentence":"Zero and one are this system''s possible states, like the photon''s horizontal or vertical polarization.","segmentIndex":28},{"word":"qubit","definition":"the basic unit of quantum information, capable of existing in superposition of states","meaningKo":"큐비트 (양자 컴퓨터의 기본 정보 단위)","etymology":"Portmanteau of ''quantum'' + ''bit''","rootBreakdown":{"prefix":"qu-","root":"bit (binary digit)","suffix":null},"relatedWords":["quantum","bit","byte"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ˈkjuːbɪt/","contextSentence":"Quantum computers use qubits, which can also be set to one of two values.","segmentIndex":26},{"word":"encryption","definition":"the process of converting information into a secret code to prevent unauthorized access","meaningKo":"암호화","etymology":"Greek ''en-'' (in) + ''kryptein'' (to hide)","rootBreakdown":{"prefix":"en-","root":"crypt (hide)","suffix":"-ion"},"relatedWords":["encrypt","decrypt","cryptography"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ɪnˈkrɪpʃən/","contextSentence":"Your data is being kept secure by an encryption system.","segmentIndex":52},{"word":"simulation","definition":"an imitation of a real-world process or system using a computer model","meaningKo":"시뮬레이션, 모의 실험","etymology":"Latin ''simulare'' meaning ''to imitate, represent''","rootBreakdown":{"prefix":null,"root":"simul (imitate)","suffix":"-ation"},"relatedWords":["simulate","similar","simultaneous"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ˌsɪmjʊˈleɪʃən/","contextSentence":"Another really exciting new use is simulations.","segmentIndex":57},{"word":"tunneling","definition":"a quantum mechanical phenomenon where a particle passes through a potential energy barrier","meaningKo":"터널링 (입자가 에너지 장벽을 통과하는 양자역학적 현상)","etymology":"Old French ''tonel'' (cask, barrel) — originally referring to a passage through something","rootBreakdown":{"prefix":null,"root":"tunnel (underground passage)","suffix":"-ing"},"relatedWords":["tunnel","channel","passage"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ˈtʌnəlɪŋ/","contextSentence":"Electrons may just transfer themselves to the other side via a process called quantum tunneling.","segmentIndex":21},{"word":"nanometer","definition":"a unit of length equal to one billionth of a meter","meaningKo":"나노미터 (10억분의 1미터)","etymology":"Greek ''nanos'' (dwarf) + ''metron'' (measure)","rootBreakdown":{"prefix":"nano-","root":"meter (measure)","suffix":null},"relatedWords":["nanotechnology","micrometer","kilometer"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ˈnænəˌmiːtər/","contextSentence":"A typical scale for transistors is 40 nanometers.","segmentIndex":20},{"word":"deduce","definition":"to arrive at a conclusion by reasoning from given information","meaningKo":"추론하다, 연역하다","etymology":"Latin ''deducere'' meaning ''to lead down, derive''","rootBreakdown":{"prefix":"de-","root":"duc (lead)","suffix":"-e"},"relatedWords":["deduction","deduce","induce","reduce"],"isEssential":true,"partOfSpeech":"verb","phonetic":"/dɪˈdjuːs/","contextSentence":"You can directly deduce properties of its partners without having to look.","segmentIndex":39},{"word":"unintuitive","definition":"not easy to understand or grasp by instinct; counterintuitive","meaningKo":"직관에 반하는, 직감적으로 이해하기 어려운","etymology":"Latin ''un-'' (not) + ''intueri'' (to look at, consider)","rootBreakdown":{"prefix":"un-","root":"intuit (to perceive directly)","suffix":"-ive"},"relatedWords":["intuitive","intuition","counterintuitive"],"isEssential":false,"partOfSpeech":"adjective","phonetic":"/ˌʌnɪnˈtjuːɪtɪv/","contextSentence":"A really weird and unintuitive property qubits can have is entanglement.","segmentIndex":38},{"word":"instantaneously","definition":"happening or done in an instant; immediately","meaningKo":"즉각적으로, 순간적으로","etymology":"Latin ''instantaneus'' from ''instare'' (to stand upon, be present)","rootBreakdown":{"prefix":"in-","root":"stant (stand)","suffix":"-aneously"},"relatedWords":["instant","instantaneous","instance"],"isEssential":true,"partOfSpeech":"adverb","phonetic":"/ˌɪnstənˈteɪniəsli/","contextSentence":"Each of the qubits react to a change in the other''s state instantaneously.","segmentIndex":38},{"word":"configuration","definition":"an arrangement of elements in a particular form or combination","meaningKo":"구성, 배치, 설정","etymology":"Latin ''configurare'' meaning ''to form, shape after''","rootBreakdown":{"prefix":"con-","root":"figur (shape, form)","suffix":"-ation"},"relatedWords":["configure","figure","figurative"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/kənˌfɪɡjʊˈreɪʃən/","contextSentence":"Four classical bits can be in one of two to the power of four different configurations at a time.","segmentIndex":33},{"word":"algorithm","definition":"a process or set of rules to be followed in calculations or problem-solving operations","meaningKo":"알고리즘 (문제 해결을 위한 절차나 규칙의 집합)","etymology":"Named after al-Khwarizmi, a 9th-century Persian mathematician","rootBreakdown":{"prefix":null,"root":"algorithm (from al-Khwarizmi)","suffix":null},"relatedWords":["algorithmic","logarithm","computation"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ˈælɡərɪðəm/","contextSentence":"Quantum algorithms need only the square root of that time.","segmentIndex":50},{"word":"molecule","definition":"a group of atoms bonded together, representing the smallest unit of a chemical compound","meaningKo":"분자","etymology":"French ''molécule'' from Latin ''moles'' (mass) + diminutive ''-cula''","rootBreakdown":{"prefix":null,"root":"mol (mass)","suffix":"-ecule (small)"},"relatedWords":["molecular","mole","atom"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ˈmɒlɪkjuːl/","contextSentence":"Even for bigger structures such as molecules, they often lack accuracy.","segmentIndex":59},{"word":"vastly","definition":"to a very great extent; immensely","meaningKo":"엄청나게, 대단히","etymology":"Latin ''vastus'' meaning ''immense, huge, empty''","rootBreakdown":{"prefix":null,"root":"vast (huge)","suffix":"-ly"},"relatedWords":["vast","vastness","immensely"],"isEssential":false,"partOfSpeech":"adverb","phonetic":"/ˈvɑːstli/","contextSentence":"In some areas they are vastly superior.","segmentIndex":48},{"word":"revolutionize","definition":"to change something radically or fundamentally","meaningKo":"혁명적으로 변화시키다","etymology":"Latin ''revolutio'' meaning ''a turn around'' from ''revolvere'' (to turn back)","rootBreakdown":{"prefix":"re-","root":"volut (turn)","suffix":"-ionize"},"relatedWords":["revolution","revolve","evolve"],"isEssential":true,"partOfSpeech":"verb","phonetic":"/ˌrɛvəˈluːʃənaɪz/","contextSentence":"Quantum simulations could provide new insights on proteins that might revolutionize medicine.","segmentIndex":61},{"word":"photon","definition":"a particle representing a quantum of light or other electromagnetic radiation","meaningKo":"광자 (빛이나 전자기 복사의 양자 단위)","etymology":"Greek ''phos/phot-'' meaning ''light''","rootBreakdown":{"prefix":null,"root":"phot (light)","suffix":"-on (particle)"},"relatedWords":["photograph","photosynthesis","electron"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ˈfoʊtɒn/","contextSentence":"A qubit can be any two-level quantum system, such as a spin in a magnetic field or a single photon.","segmentIndex":27}]'::jsonb, '[{"pattern":"Present perfect continuous: has/have + been + verb-ing","explanation":"Used to describe an action that started in the past and continues to the present with emphasis on duration. ''Has kept growing'' shows the ongoing nature of technological progress.","explanationKo":"현재완료 진행형은 과거에 시작된 행동이 현재까지 계속되고 있음을 강조할 때 사용해. ''has kept growing''은 기술 발전이 계속 진행 중임을 보여줘.","examples":["The power of our brain machines has kept growing exponentially."],"segmentIndex":2},{"pattern":"Be about to + verb (imminent future)","explanation":"Used to express that something is on the verge of happening. It creates a sense of urgency or immediacy about an upcoming event.","explanationKo":"''be about to + 동사''는 어떤 일이 곧 일어나려 한다는 것을 표현할 때 사용해. 긴박감이나 즉각성을 줘. ''막 ~하려 하다''라는 의미야.","examples":["But this process is about to meet its physical limits."],"segmentIndex":3},{"pattern":"Be made up of + noun (composition)","explanation":"Used to describe what something consists of or is composed of. It is a common way to explain the parts that form a whole.","explanationKo":"''be made up of''는 어떤 것이 무엇으로 구성되어 있는지 설명할 때 사용해. ''~로 이루어져 있다''라는 의미야.","examples":["A computer is made up of very simple components doing very simple things.","This information is made up of bits."],"segmentIndex":6},{"pattern":"Once + clause, clause (conditional sequence)","explanation":"Used to show that one event triggers or enables another. It implies that the first action is a prerequisite for the second.","explanationKo":"''Once + 절''은 한 가지 일이 다른 일을 가능하게 하거나 촉발함을 보여줘. 첫 번째 행동이 두 번째의 전제 조건임을 암시해. ''일단 ~하면''이라는 뜻이야.","examples":["Once you can add, you can also multiply, and once you can multiply, you can basically do anything."],"segmentIndex":14},{"pattern":"May/might + verb (possibility/speculation)","explanation":"Used to express that something is possible but not certain. In scientific contexts, it indicates theoretical possibility or uncertainty.","explanationKo":"''may/might + 동사''는 가능하지만 확실하지 않은 일을 표현할 때 사용해. 과학적 맥락에서는 이론적 가능성이나 불확실성을 나타내.","examples":["Electrons may just transfer themselves to the other side of a blocked passage.","Quantum simulations could provide new insights on proteins that might revolutionize medicine."],"segmentIndex":21},{"pattern":"As long as + clause (condition duration)","explanation":"Used to set a condition that must remain true for the main clause to be valid. It means ''during the entire time that'' or ''provided that.''","explanationKo":"''as long as + 절''은 주절이 유효하기 위해 유지되어야 하는 조건을 설정할 때 사용해. ''~하는 한'', ''~하는 동안''이라는 뜻이야.","examples":["So, as long as it''s unobserved, the qubit is in a superposition of probabilities for zero and one."],"segmentIndex":31},{"pattern":"What this means is that + clause (reformulation)","explanation":"Used to rephrase or clarify a complex idea in simpler terms. It signals an explanation of the practical implications of what was just described.","explanationKo":"''What this means is that''은 복잡한 아이디어를 더 쉽게 바꿔 설명할 때 사용해. 방금 설명한 것의 실질적인 의미를 풀어서 말하는 신호야.","examples":["What this means is that you get the entire lot of calculations that are possible with your setup all done at the same time."],"segmentIndex":45},{"pattern":"So while + clause, clause (concession)","explanation":"Used to acknowledge one point while introducing a contrasting conclusion. It balances two ideas, recognizing a limitation before stating a strength.","explanationKo":"''So while + 절''은 한 가지 점을 인정하면서 대조적인 결론을 소개할 때 사용해. ''~이긴 하지만, ~이다''라는 의미로 두 아이디어의 균형을 잡아.","examples":["So while quantum computers will probably not replace our home computers, in some areas they are vastly superior."],"segmentIndex":48},{"pattern":"By + verb-ing (means/method)","explanation":"Used to explain the method or means by which something is achieved. It answers the ''how'' of an action.","explanationKo":"''by + 동명사(-ing)''는 어떤 것을 달성하는 방법이나 수단을 설명할 때 사용해. 행동의 ''어떻게''에 답하는 표현이야.","examples":["But by cleverly exploiting superposition and entanglement, this can be exponentially more efficient.","Scientists are trying to use these unusual quantum properties to their advantage by building quantum computers."],"segmentIndex":47},{"pattern":"Why not + verb? (rhetorical suggestion)","explanation":"Used to propose an idea as if it is an obvious or natural solution. It is a rhetorical way to introduce an innovative approach.","explanationKo":"''Why not + 동사?''는 어떤 아이디어를 당연하거나 자연스러운 해결책으로 제안할 때 사용해. 혁신적인 접근 방식을 수사적으로 소개하는 방법이야.","examples":["So why not simulate quantum physics with actual quantum physics?"],"segmentIndex":60}]'::jsonb, '[{"type":"linking","originalText":"made up of","phonetic":"/meɪdʌpəv/","koreanPhonetic":"메이더퍼브","explanation":"The /d/ of ''made'' links to the vowel /ʌ/ of ''up,'' and the /p/ of ''up'' links to the reduced /əv/ of ''of.'' The three words flow as one unit in natural speech.","explanationKo":"''made''의 /d/가 ''up''의 모음 /ʌ/와 연결되고, ''up''의 /p/가 약화된 ''of'' /əv/와 이어져서 세 단어가 하나의 덩어리처럼 흘러가요.","practiceGuide":"''메이드 업 오브''라고 따로 끊지 말고, ''메이더퍼브''처럼 한 덩어리로 이어서 발음해 보세요.","segmentIndex":6},{"type":"reduction","originalText":"set to either","phonetic":"/sɛtə ˈiːðər/","koreanPhonetic":"세터 이더","explanation":"The word ''to'' is reduced to /tə/, and the /t/ of ''set'' links directly to it. ''Either'' also reduces its initial vowel. The phrase sounds much smoother than when each word is fully articulated.","explanationKo":"''to''가 /tə/로 약화되고, ''set''의 /t/와 바로 연결돼요. ''either''도 첫 모음이 약해져서 전체 구가 매끄럽게 들려요.","practiceGuide":"''셋 투 이더''가 아니라 ''세터 이더''처럼 ''to''를 약하게 /tə/로 발음하며 앞 단어와 연결해 보세요.","segmentIndex":9},{"type":"elision","originalText":"just stop","phonetic":"/dʒʌs stɒp/","koreanPhonetic":"저스 스탑","explanation":"The /t/ at the end of ''just'' is elided before the /s/ of ''stop.'' When a stop consonant is followed by another consonant, the first is often dropped in natural speech.","explanationKo":"''just''의 마지막 /t/가 ''stop''의 /s/ 앞에서 탈락해요. 파열음 뒤에 다른 자음이 오면 첫 번째 파열음이 생략되는 경우가 많아요.","practiceGuide":"''저스트 스탑''이라고 /t/를 분명히 발음하지 말고, ''저스 스탑''처럼 /t/를 생략해 보세요.","segmentIndex":22},{"type":"assimilation","originalText":"in parallel","phonetic":"/ɪm ˈpærəlɛl/","koreanPhonetic":"임 패럴렐","explanation":"The /n/ of ''in'' assimilates to /m/ before the bilabial /p/ of ''parallel.'' This is place assimilation, where the nasal sound adjusts to match the place of articulation of the following consonant.","explanationKo":"''in''의 /n/이 ''parallel''의 양순음 /p/ 앞에서 /m/으로 동화돼요. 비음이 다음 자음의 조음 위치에 맞춰 변하는 조음위치 동화 현상이에요.","practiceGuide":"''인 패럴렐''이 아니라 ''임 패럴렐''처럼 /n/을 /m/으로 바꿔서 발음해 보세요. 입술을 다물면서 자연스럽게 이어져요.","segmentIndex":37},{"type":"linking","originalText":"measure it","phonetic":"/ˈmɛʒərɪt/","koreanPhonetic":"메저릿","explanation":"The final /r/ of ''measure'' (in non-rhotic accents) or the schwa links smoothly to the /ɪ/ of ''it,'' and the whole phrase sounds like one word.","explanationKo":"''measure''의 마지막 소리가 ''it''의 /ɪ/와 자연스럽게 연결되어 전체 구가 한 단어처럼 들려요.","practiceGuide":"''메저 잇''이라고 끊지 말고, ''메저릿''처럼 /r/ 소리를 ''it''과 이어서 발음해 보세요.","segmentIndex":32},{"type":"reduction","originalText":"can be","phonetic":"/kənbi/","koreanPhonetic":"컨비","explanation":"The modal ''can'' is reduced to its weak form /kən/ in unstressed position. The vowel /æ/ becomes a schwa /ə/, making the phrase flow quickly.","explanationKo":"''can''이 강세를 받지 않는 위치에서 약형 /kən/으로 축약돼요. 모음 /æ/가 슈와 /ə/로 변해서 구가 빠르게 흘러가요.","practiceGuide":"''캔 비''라고 강하게 발음하지 말고, ''컨비''처럼 ''can''을 약하게 발음해 보세요. 부정문 ''can''t''와 구별하는 중요한 포인트예요.","segmentIndex":29},{"type":"elision","originalText":"most famous","phonetic":"/moʊs ˈfeɪməs/","koreanPhonetic":"모우스 페이머스","explanation":"The /t/ at the end of ''most'' is elided before the /f/ of ''famous.'' This is a common consonant cluster simplification in English.","explanationKo":"''most''의 마지막 /t/가 ''famous''의 /f/ 앞에서 탈락해요. 영어에서 흔히 일어나는 자음군 단순화 현상이에요.","practiceGuide":"''모우스트 페이머스''가 아니라 ''모우스 페이머스''처럼 /t/를 생략하면 더 자연스러워요.","segmentIndex":51},{"type":"linking","originalText":"do it in a","phonetic":"/duːɪtɪnə/","koreanPhonetic":"두이리너","explanation":"Multiple consonant-vowel links chain together: the /t/ of ''it'' links to the /ɪ/ of ''in,'' and the /n/ of ''in'' links to the /ə/ of ''a.'' The whole phrase flows as one continuous sound.","explanationKo":"여러 자음-모음 연결이 연쇄적으로 이어져요: ''it''의 /t/가 ''in''의 /ɪ/와, ''in''의 /n/이 ''a''의 /ə/와 연결되어 전체 구가 하나의 연속된 소리로 흘러가요.","practiceGuide":"''두 잇 인 어''라고 끊지 말고, ''두이리너''처럼 자음과 모음을 연결하면서 한 호흡으로 발음해 보세요.","segmentIndex":56}]'::jsonb, '{"sections":[{"section":"Computing''s Exponential Growth Hits Physical Limits","startSegment":0,"endSegment":5,"summary":"The narrator introduces the history of computing and how exponential growth in processing power is now hitting physical limits as components approach atomic scale.","summaryKo":"컴퓨팅의 역사를 소개하고, 처리 능력의 기하급수적 성장이 부품이 원자 크기에 접근하면서 물리적 한계에 부딪히고 있다고 설명해.","keyPoints":["Computer power has grown exponentially since the 1960s","Parts are approaching the size of an atom","This creates a fundamental problem for further progress"]},{"section":"How Traditional Computers Work","startSegment":6,"endSegment":16,"summary":"Explains the basic building blocks of traditional computers: transistors, logic gates, and modules. Uses the analogy of seven-year-olds doing simple math to show how simple operations combine into complex computing.","summaryKo":"기존 컴퓨터의 기본 구성 요소인 트랜지스터, 논리 게이트, 모듈을 설명해. 간단한 수학을 하는 7살짜리 아이들에 비유해서 단순한 연산이 어떻게 복잡한 컴퓨팅이 되는지 보여줘.","keyPoints":["Computers consist of transistors, logic gates, and modules","Transistors are simple on/off switches processing bits","Complex calculations emerge from combining simple operations"]},{"section":"The Quantum Problem: Tunneling at Atomic Scale","startSegment":17,"endSegment":24,"summary":"Explains why miniaturization causes problems at the quantum level. Quantum tunneling allows electrons to bypass barriers, breaking traditional computing. Scientists respond by developing quantum computers.","summaryKo":"소형화가 양자 수준에서 왜 문제를 일으키는지 설명해. 양자 터널링으로 전자가 장벽을 통과할 수 있어서 기존 컴퓨팅이 작동하지 않게 돼. 과학자들은 양자 컴퓨터를 개발해 대응하고 있어.","keyPoints":["At atomic scale, quantum tunneling lets electrons pass through barriers","Traditional computers stop working reliably at this scale","Scientists aim to harness quantum properties for quantum computers"]},{"section":"Qubits and Superposition","startSegment":25,"endSegment":37,"summary":"Introduces qubits and the concept of superposition. Unlike classical bits, qubits can exist in multiple states simultaneously, allowing exponential growth in parallel computation.","summaryKo":"큐비트와 중첩의 개념을 소개해. 고전적 비트와 달리 큐비트는 여러 상태에 동시에 존재할 수 있어서 병렬 계산이 기하급수적으로 증가할 수 있어.","keyPoints":["Qubits can be in superposition of both 0 and 1 simultaneously","Measurement collapses the superposition to a definite state","20 qubits can store a million values in parallel"]},{"section":"Entanglement and Quantum Gates","startSegment":38,"endSegment":47,"summary":"Covers entanglement, quantum gates, and how quantum computing works in practice. Entangled qubits react to each other instantaneously, and quantum gates manipulate superpositions to perform massive parallel calculations.","summaryKo":"얽힘, 양자 게이트, 양자 컴퓨팅의 실제 작동 방식을 다뤄. 얽힌 큐비트는 서로 즉각적으로 반응하고, 양자 게이트는 중첩을 조작해서 대규모 병렬 계산을 수행해.","keyPoints":["Entanglement links qubits so measuring one reveals the other''s state","Quantum gates manipulate superpositions and probabilities","Superposition and entanglement enable exponentially more efficient computation"]},{"section":"Applications: Databases, Encryption, and Drug Discovery","startSegment":48,"endSegment":61,"summary":"Presents practical applications of quantum computers: database searching with Grover''s algorithm, breaking encryption systems, and simulating quantum physics for drug discovery and materials science.","summaryKo":"양자 컴퓨터의 실용적 응용 분야를 소개해: 그로버 알고리즘을 이용한 데이터베이스 검색, 암호화 시스템 해독, 신약 개발과 재료 과학을 위한 양자 물리학 시뮬레이션.","keyPoints":["Database searching becomes vastly faster with quantum algorithms","Public-key encryption could be broken by quantum speed-up","Quantum simulations could revolutionize medicine through protein modeling"]},{"section":"The Uncertain but Exciting Future","startSegment":62,"endSegment":64,"summary":"The narrator concludes by acknowledging that the future of quantum computing is uncertain — it may be a specialized tool or a transformative revolution — and emphasizes the spirit of exploration.","summaryKo":"양자 컴퓨팅의 미래가 불확실하다는 점을 인정하며 마무리해. 전문적인 도구가 될 수도 있고 혁명이 될 수도 있으며, 탐구 정신을 강조해.","keyPoints":["The ultimate impact of quantum computers remains unknown","They could be specialized tools or a revolution for humanity","The only way to find out is to keep pushing forward"]}],"signalExpressions":[{"expression":"For most of our history","type":"transition","segmentIndex":0,"role":"역사적 맥락을 설정하며 이야기를 시작해요"},{"expression":"But this process is about to meet its physical limits","type":"emphasis","segmentIndex":3,"role":"핵심 문제를 예고하며 긴박감을 조성해요"},{"expression":"To understand why this is a problem, we have to clear up some basics","type":"transition","segmentIndex":5,"role":"기본 개념 설명으로 전환하며 청중을 안내해요"},{"expression":"However, with parts getting tinier and tinier","type":"transition","segmentIndex":17,"role":"양자 문제로의 전환을 알리는 역접 표현이에요"},{"expression":"In a nutshell","type":"summary","segmentIndex":18,"role":"복잡한 개념을 간결하게 요약하겠다는 신호예요"},{"expression":"To solve this problem, scientists are trying to","type":"transition","segmentIndex":24,"role":"문제에서 해결책으로 전환하며 양자 컴퓨터를 소개해요"},{"expression":"This is called superposition","type":"emphasis","segmentIndex":30,"role":"핵심 용어를 정의하며 개념을 명확하게 해요"},{"expression":"Superposition is a game-changer","type":"emphasis","segmentIndex":33,"role":"중첩의 중요성을 강조하며 실질적 의미를 설명하기 시작해요"},{"expression":"What this means is that","type":"summary","segmentIndex":45,"role":"복잡한 설명을 실질적인 의미로 바꿔 설명해요"},{"expression":"So while quantum computers will probably not replace our home computers","type":"transition","segmentIndex":48,"role":"이론에서 실제 응용 분야로 전환하며 기대를 조정해요"},{"expression":"Another really exciting new use is","type":"transition","segmentIndex":57,"role":"새로운 응용 분야로 자연스럽게 전환해요"},{"expression":"We have no idea where the limits of technology are","type":"summary","segmentIndex":64,"role":"전체 영상을 마무리하며 열린 결론으로 끝내요"}]}'::jsonb
)
