INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'en', 'LaLvVc1sS20', '{"videoId":"LaLvVc1sS20","youtubeId":"LaLvVc1sS20","title":"The history of tea - Shunan Teng","channel":"TED-Ed","categoryId":"culture","difficulty":"intermediate","duration":298,"thumbnail":"https://i.ytimg.com/vi_webp/LaLvVc1sS20/maxresdefault.webp","speechRateWpm":155,"addedAt":"2026-02-16","segmentCount":62,"vocabularyCount":20,"grammarPatternCount":10,"descriptionKo":"중국 황제부터 전 세계로, 차(茶)의 흥미로운 역사"}'::jsonb, '{"videoId":"LaLvVc1sS20","segments":[{"index":0,"start":6.68,"end":10.78,"textEn":"The End During a long day spent roaming the forest in search of edible grains and herbs,","words":[{"word":"The","start":6.68,"end":7.22},{"word":"End","start":7.22,"end":7.22},{"word":"During","start":7.22,"end":7.22},{"word":"a","start":7.22,"end":7.42},{"word":"long","start":7.42,"end":7.64},{"word":"day","start":7.64,"end":7.88},{"word":"spent","start":7.88,"end":8.14},{"word":"roaming","start":8.14,"end":8.44},{"word":"the","start":8.44,"end":8.64},{"word":"forest","start":8.64,"end":8.98},{"word":"in","start":8.98,"end":9.22},{"word":"search","start":9.22,"end":9.42},{"word":"of","start":9.42,"end":9.58},{"word":"edible","start":9.58,"end":9.84},{"word":"grains","start":9.84,"end":10.24},{"word":"and","start":10.24,"end":10.42},{"word":"herbs,","start":10.42,"end":10.78}],"textKo":"","listenDifficulty":5},{"index":1,"start":11.26,"end":16.2,"textEn":"The weary divine farmer Shen Nong accidentally poisoned himself 72 times.","words":[{"word":"the","start":11.26,"end":11.34},{"word":"weary","start":11.34,"end":11.62},{"word":"divine","start":11.62,"end":11.94},{"word":"farmer","start":11.94,"end":12.46},{"word":"Shen","start":12.46,"end":12.94},{"word":"Nong","start":12.94,"end":13.24},{"word":"accidentally","start":13.24,"end":14.06},{"word":"poisoned","start":14.06,"end":14.5},{"word":"himself","start":14.5,"end":14.92},{"word":"72","start":14.92,"end":15.68},{"word":"times.","start":15.68,"end":16.2}],"textKo":"지치고 힘든 신농씨가 실수로 72번이나 독에 중독되었어요.","listenDifficulty":3},{"index":2,"start":16.62,"end":20.62,"textEn":"But before the poisons could end his life, a leaf drifted into his mouth.","words":[{"word":"But","start":16.62,"end":17.12},{"word":"before","start":17.12,"end":17.44},{"word":"the","start":17.44,"end":17.62},{"word":"poisons","start":17.62,"end":17.98},{"word":"could","start":17.98,"end":18.16},{"word":"end","start":18.16,"end":18.34},{"word":"his","start":18.34,"end":18.52},{"word":"life,","start":18.52,"end":18.74},{"word":"a","start":18.94,"end":19.28},{"word":"leaf","start":19.28,"end":19.52},{"word":"drifted","start":19.52,"end":19.96},{"word":"into","start":19.96,"end":20.14},{"word":"his","start":20.14,"end":20.36},{"word":"mouth.","start":20.36,"end":20.62}],"textKo":"하지만 독이 그의 목숨을 앗아가기 전에, 나뭇잎 하나가 그의 입 안으로 날아들었어요.","listenDifficulty":3},{"index":3,"start":21.04,"end":23.24,"textEn":"He chewed on it, and it revived him.","words":[{"word":"He","start":21.04,"end":21.58},{"word":"chewed","start":21.58,"end":21.9},{"word":"on","start":21.9,"end":22.02},{"word":"it,","start":22.02,"end":22.14},{"word":"and","start":22.26,"end":22.54},{"word":"it","start":22.54,"end":22.64},{"word":"revived","start":22.64,"end":23.0},{"word":"him.","start":23.0,"end":23.24}],"textKo":"그는 그것을 씹었고, 덕분에 기운을 되찾았어요.","listenDifficulty":4},{"index":4,"start":23.56,"end":28.4,"textEn":"And that is how we discovered tea. Or so an ancient legend goes, at least.","words":[{"word":"And","start":23.56,"end":24.08},{"word":"that","start":24.08,"end":24.3},{"word":"is","start":24.3,"end":24.44},{"word":"how","start":24.44,"end":24.6},{"word":"we","start":24.6,"end":24.74},{"word":"discovered","start":24.74,"end":25.14},{"word":"tea.","start":25.14,"end":25.44},{"word":"Or","start":26.16,"end":26.7},{"word":"so","start":26.7,"end":26.98},{"word":"an","start":26.98,"end":27.18},{"word":"ancient","start":27.18,"end":27.48},{"word":"legend","start":27.48,"end":27.74},{"word":"goes,","start":27.74,"end":28.04},{"word":"at","start":28.16,"end":28.22},{"word":"least.","start":28.22,"end":28.4}],"textKo":"그렇게 우리는 차를 발견하게 되었어요. 적어도 오래된 전설에 따르면 그래요.","listenDifficulty":2},{"index":5,"start":28.4,"end":32.76,"textEn":"Tea doesn''t actually cure poisonings, but the story of Shen Nong,","words":[{"word":"Tea","start":28.4,"end":29.54},{"word":"doesn''t","start":29.54,"end":29.9},{"word":"actually","start":29.9,"end":30.2},{"word":"cure","start":30.2,"end":30.52},{"word":"poisonings,","start":30.52,"end":31.1},{"word":"but","start":31.24,"end":31.58},{"word":"the","start":31.58,"end":31.72},{"word":"story","start":31.72,"end":32.02},{"word":"of","start":32.02,"end":32.24},{"word":"Shen","start":32.24,"end":32.48},{"word":"Nong,","start":32.48,"end":32.76}],"textKo":"차가 실제로 중독을 치료하지는 못하지만, 신농씨의 이야기는,","listenDifficulty":1},{"index":6,"start":33.04,"end":37.56,"textEn":"The mythical Chinese inventor of agriculture, highlights tea''s importance to ancient China.","words":[{"word":"the","start":33.04,"end":33.14},{"word":"mythical","start":33.14,"end":33.48},{"word":"Chinese","start":33.48,"end":33.92},{"word":"inventor","start":33.92,"end":34.34},{"word":"of","start":34.34,"end":34.54},{"word":"agriculture,","start":34.54,"end":35.1},{"word":"highlights","start":35.46,"end":35.98},{"word":"tea''s","start":35.98,"end":36.34},{"word":"importance","start":36.34,"end":36.68},{"word":"to","start":36.68,"end":36.92},{"word":"ancient","start":36.92,"end":37.2},{"word":"China.","start":37.2,"end":37.56}],"textKo":"농업의 신화적인 중국 발명자로서, 고대 중국에서 차가 얼마나 중요했는지를 보여줘요.","listenDifficulty":2},{"index":7,"start":38.56,"end":43.52,"textEn":"Archaeological evidence suggests tea was first cultivated there as early as 6,000 years ago,","words":[{"word":"Archaeological","start":38.56,"end":39.16},{"word":"evidence","start":39.16,"end":39.6},{"word":"suggests","start":39.6,"end":40.08},{"word":"tea","start":40.08,"end":40.38},{"word":"was","start":40.38,"end":40.62},{"word":"first","start":40.62,"end":40.84},{"word":"cultivated","start":40.84,"end":41.34},{"word":"there","start":41.34,"end":41.62},{"word":"as","start":41.62,"end":42.04},{"word":"early","start":42.04,"end":42.34},{"word":"as","start":42.34,"end":42.54},{"word":"6","start":42.54,"end":42.78},{"word":",000","start":42.78,"end":43.08},{"word":"years","start":43.08,"end":43.24},{"word":"ago,","start":43.24,"end":43.52}],"textKo":"고고학적 증거에 따르면 차는 무려 6,000년 전에 처음 재배되었어요.","listenDifficulty":3},{"index":8,"start":43.66,"end":47.58,"textEn":"Or 1,500 years before the pharaohs built the Great Pyramids of Giza.","words":[{"word":"or","start":43.66,"end":44.26},{"word":"1","start":44.26,"end":44.54},{"word":",500","start":44.54,"end":44.9},{"word":"years","start":44.9,"end":45.24},{"word":"before","start":45.24,"end":45.62},{"word":"the","start":45.62,"end":45.82},{"word":"pharaohs","start":45.82,"end":46.22},{"word":"built","start":46.22,"end":46.38},{"word":"the","start":46.38,"end":46.52},{"word":"Great","start":46.52,"end":46.66},{"word":"Pyramids","start":46.66,"end":47.18},{"word":"of","start":47.18,"end":47.3},{"word":"Giza.","start":47.3,"end":47.58}],"textKo":"즉 파라오들이 기자의 대피라미드를 건설하기 1,500년 전이에요.","listenDifficulty":2},{"index":9,"start":47.9,"end":52.28,"textEn":"That original Chinese tea plant is the same type that''s grown around the world today,","words":[{"word":"That","start":47.9,"end":48.46},{"word":"original","start":48.46,"end":48.82},{"word":"Chinese","start":48.82,"end":49.22},{"word":"tea","start":49.22,"end":49.5},{"word":"plant","start":49.5,"end":49.82},{"word":"is","start":49.82,"end":50.28},{"word":"the","start":50.28,"end":50.42},{"word":"same","start":50.42,"end":50.7},{"word":"type","start":50.7,"end":50.98},{"word":"that''s","start":50.98,"end":51.26},{"word":"grown","start":51.26,"end":51.46},{"word":"around","start":51.46,"end":51.68},{"word":"the","start":51.68,"end":51.82},{"word":"world","start":51.82,"end":51.98},{"word":"today,","start":51.98,"end":52.28}],"textKo":"그 원래의 중국 차나무는 오늘날 전 세계에서 재배되는 것과 같은 품종이에요.","listenDifficulty":2},{"index":10,"start":52.58,"end":54.88,"textEn":"Yet it was originally consumed very differently.","words":[{"word":"yet","start":52.58,"end":52.84},{"word":"it","start":52.84,"end":53.0},{"word":"was","start":53.0,"end":53.12},{"word":"originally","start":53.12,"end":53.56},{"word":"consumed","start":53.56,"end":54.14},{"word":"very","start":54.14,"end":54.48},{"word":"differently.","start":54.48,"end":54.88}],"textKo":"하지만 원래는 지금과 매우 다르게 소비되었어요.","listenDifficulty":2},{"index":11,"start":54.88,"end":58.32,"textEn":"It was eaten as a vegetable or cooked with grain porridge.","words":[{"word":"It","start":54.88,"end":55.54},{"word":"was","start":55.54,"end":55.72},{"word":"eaten","start":55.72,"end":56.02},{"word":"as","start":56.02,"end":56.28},{"word":"a","start":56.28,"end":56.38},{"word":"vegetable","start":56.38,"end":56.76},{"word":"or","start":56.76,"end":57.16},{"word":"cooked","start":57.16,"end":57.48},{"word":"with","start":57.48,"end":57.68},{"word":"grain","start":57.68,"end":57.92},{"word":"porridge.","start":57.92,"end":58.32}],"textKo":"채소로 먹거나 곡물 죽과 함께 요리해서 먹었어요.","listenDifficulty":3},{"index":12,"start":58.66,"end":62.38,"textEn":"Tea only shifted from food to drink 1,500 years ago,","words":[{"word":"Tea","start":58.66,"end":59.26},{"word":"only","start":59.26,"end":59.6},{"word":"shifted","start":59.6,"end":59.98},{"word":"from","start":59.98,"end":60.22},{"word":"food","start":60.22,"end":60.5},{"word":"to","start":60.5,"end":60.66},{"word":"drink","start":60.66,"end":60.96},{"word":"1","start":60.96,"end":61.34},{"word":",500","start":61.34,"end":61.72},{"word":"years","start":61.72,"end":62.06},{"word":"ago,","start":62.06,"end":62.38}],"textKo":"차가 음식에서 음료로 바뀐 것은 불과 1,500년 전이에요.","listenDifficulty":1},{"index":13,"start":62.6,"end":66.0,"textEn":"When people realized that a combination of heat and moisture","words":[{"word":"when","start":62.6,"end":63.08},{"word":"people","start":63.08,"end":63.38},{"word":"realized","start":63.38,"end":63.88},{"word":"that","start":63.88,"end":64.2},{"word":"a","start":64.2,"end":64.3},{"word":"combination","start":64.3,"end":64.72},{"word":"of","start":64.72,"end":65.04},{"word":"heat","start":65.04,"end":65.34},{"word":"and","start":65.34,"end":65.58},{"word":"moisture","start":65.58,"end":66.0}],"textKo":"사람들이 열과 수분의 조합이","listenDifficulty":3},{"index":14,"start":66.0,"end":69.6,"textEn":"Could create a complex and varied taste out of the leafy green.","words":[{"word":"could","start":66.0,"end":66.56},{"word":"create","start":66.56,"end":66.9},{"word":"a","start":66.9,"end":67.08},{"word":"complex","start":67.08,"end":67.64},{"word":"and","start":67.64,"end":67.9},{"word":"varied","start":67.9,"end":68.2},{"word":"taste","start":68.2,"end":68.56},{"word":"out","start":68.56,"end":68.86},{"word":"of","start":68.86,"end":68.96},{"word":"the","start":68.96,"end":69.08},{"word":"leafy","start":69.08,"end":69.38},{"word":"green.","start":69.38,"end":69.6}],"textKo":"푸른 잎에서 복잡하고 다양한 맛을 만들어낼 수 있다는 것을 깨달았을 때예요.","listenDifficulty":2},{"index":15,"start":70.4,"end":73.64,"textEn":"After hundreds of years of variations to the preparation method,","words":[{"word":"After","start":70.4,"end":71.0},{"word":"hundreds","start":71.0,"end":71.32},{"word":"of","start":71.32,"end":71.54},{"word":"years","start":71.54,"end":71.72},{"word":"of","start":71.72,"end":71.9},{"word":"variations","start":71.9,"end":72.36},{"word":"to","start":72.36,"end":72.66},{"word":"the","start":72.66,"end":72.78},{"word":"preparation","start":72.78,"end":73.2},{"word":"method,","start":73.2,"end":73.64}],"textKo":"수백 년에 걸친 다양한 준비 방법의 변화 끝에,","listenDifficulty":2},{"index":16,"start":74.14,"end":79.16,"textEn":"The standard became to heat tea, pack it into portable cakes, grind it into powder,","words":[{"word":"the","start":74.14,"end":74.26},{"word":"standard","start":74.26,"end":74.62},{"word":"became","start":74.62,"end":74.96},{"word":"to","start":74.96,"end":75.14},{"word":"heat","start":75.14,"end":75.42},{"word":"tea,","start":75.42,"end":75.7},{"word":"pack","start":76.06,"end":76.52},{"word":"it","start":76.52,"end":76.62},{"word":"into","start":76.62,"end":76.84},{"word":"portable","start":76.84,"end":77.2},{"word":"cakes,","start":77.2,"end":77.6},{"word":"grind","start":78.2,"end":78.5},{"word":"it","start":78.5,"end":78.64},{"word":"into","start":78.64,"end":78.82},{"word":"powder,","start":78.82,"end":79.16}],"textKo":"차를 가열하고, 휴대용 떡 형태로 압축하고, 가루로 갈아서,","listenDifficulty":1},{"index":17,"start":79.74,"end":84.2,"textEn":"Mix with hot water, and create a beverage called mocha, or matcha.","words":[{"word":"mix","start":79.74,"end":80.02},{"word":"with","start":80.02,"end":80.16},{"word":"hot","start":80.16,"end":80.38},{"word":"water,","start":80.38,"end":80.72},{"word":"and","start":80.92,"end":81.14},{"word":"create","start":81.14,"end":81.4},{"word":"a","start":81.4,"end":81.54},{"word":"beverage","start":81.54,"end":81.84},{"word":"called","start":81.84,"end":82.14},{"word":"mocha,","start":82.14,"end":82.98},{"word":"or","start":83.2,"end":83.64},{"word":"matcha.","start":83.64,"end":84.2}],"textKo":"뜨거운 물과 섞어 말차라고 불리는 음료를 만드는 것이 표준이 되었어요.","listenDifficulty":1},{"index":18,"start":85.1,"end":88.6,"textEn":"Matcha became so popular that a distinct Chinese tea culture emerged.","words":[{"word":"Matcha","start":85.1,"end":85.7},{"word":"became","start":85.7,"end":85.96},{"word":"so","start":85.96,"end":86.26},{"word":"popular","start":86.26,"end":86.76},{"word":"that","start":86.76,"end":87.2},{"word":"a","start":87.2,"end":87.3},{"word":"distinct","start":87.3,"end":87.62},{"word":"Chinese","start":87.62,"end":88.02},{"word":"tea","start":88.02,"end":88.26},{"word":"culture","start":88.26,"end":88.56},{"word":"emerged.","start":88.56,"end":88.86}],"textKo":"말차가 매우 인기를 끌면서 독특한 중국 차 문화가 형성되었어요.","listenDifficulty":2},{"index":19,"start":89.56,"end":94.96,"textEn":"Tea was the subject of books and poetry, the favorite drink of emperors, and a medium for artists.","words":[{"word":"Tea","start":89.56,"end":90.08},{"word":"was","start":90.08,"end":90.32},{"word":"the","start":90.32,"end":90.46},{"word":"subject","start":90.46,"end":90.76},{"word":"of","start":90.76,"end":90.96},{"word":"books","start":90.96,"end":91.2},{"word":"and","start":91.2,"end":91.34},{"word":"poetry,","start":91.34,"end":91.76},{"word":"the","start":92.2,"end":92.42},{"word":"favorite","start":92.42,"end":92.74},{"word":"drink","start":92.74,"end":92.94},{"word":"of","start":92.94,"end":93.08},{"word":"emperors,","start":93.08,"end":93.5},{"word":"and","start":93.64,"end":93.96},{"word":"a","start":93.96,"end":94.08},{"word":"medium","start":94.08,"end":94.36},{"word":"for","start":94.36,"end":94.58},{"word":"artists.","start":94.58,"end":94.96}],"textKo":"차는 책과 시의 주제였고, 황제가 가장 좋아하는 음료였으며, 예술가들의 매체였어요.","listenDifficulty":2},{"index":20,"start":95.44,"end":98.26,"textEn":"They would draw extravagant pictures in the foam of the tea,","words":[{"word":"They","start":95.44,"end":95.84},{"word":"would","start":95.84,"end":95.98},{"word":"draw","start":95.98,"end":96.22},{"word":"extravagant","start":96.22,"end":96.98},{"word":"pictures","start":96.98,"end":97.3},{"word":"in","start":97.3,"end":97.48},{"word":"the","start":97.48,"end":97.58},{"word":"foam","start":97.58,"end":97.82},{"word":"of","start":97.82,"end":97.96},{"word":"the","start":97.96,"end":98.02},{"word":"tea,","start":98.02,"end":98.26}],"textKo":"그들은 차의 거품 위에 화려한 그림을 그리곤 했어요.","listenDifficulty":4},{"index":21,"start":98.56,"end":101.74,"textEn":"Very much like the espresso art you might see in coffee shops today.","words":[{"word":"very","start":98.56,"end":98.94},{"word":"much","start":98.94,"end":99.14},{"word":"like","start":99.14,"end":99.38},{"word":"the","start":99.38,"end":99.52},{"word":"espresso","start":99.52,"end":99.9},{"word":"art","start":99.9,"end":100.24},{"word":"you","start":100.24,"end":100.42},{"word":"might","start":100.42,"end":100.54},{"word":"see","start":100.54,"end":100.78},{"word":"in","start":100.78,"end":100.94},{"word":"coffee","start":100.94,"end":101.2},{"word":"shops","start":101.2,"end":101.46},{"word":"today.","start":101.46,"end":101.74}],"textKo":"오늘날 커피숍에서 볼 수 있는 에스프레소 아트와 매우 비슷해요.","listenDifficulty":3},{"index":22,"start":102.32,"end":108.22,"textEn":"In the 9th century, during the Tang Dynasty, a Japanese monk brought the first tea plant to Japan.","words":[{"word":"In","start":102.32,"end":102.84},{"word":"the","start":102.84,"end":102.94},{"word":"9th","start":102.94,"end":103.22},{"word":"century,","start":103.22,"end":103.56},{"word":"during","start":103.9,"end":104.04},{"word":"the","start":104.04,"end":104.2},{"word":"Tang","start":104.2,"end":104.48},{"word":"Dynasty,","start":104.48,"end":104.84},{"word":"a","start":105.44,"end":105.72},{"word":"Japanese","start":105.72,"end":106.16},{"word":"monk","start":106.16,"end":106.48},{"word":"brought","start":106.48,"end":106.74},{"word":"the","start":106.74,"end":106.92},{"word":"first","start":106.92,"end":107.2},{"word":"tea","start":107.2,"end":107.42},{"word":"plant","start":107.42,"end":107.7},{"word":"to","start":107.7,"end":107.86},{"word":"Japan.","start":107.86,"end":108.22}],"textKo":"9세기 당나라 시대에 일본 승려가 최초의 차나무를 일본에 가져왔어요.","listenDifficulty":2},{"index":23,"start":108.22,"end":112.4,"textEn":"The Japanese eventually developed their own unique rituals around tea,","words":[{"word":"The","start":108.22,"end":109.26},{"word":"Japanese","start":109.26,"end":109.7},{"word":"eventually","start":109.7,"end":110.26},{"word":"developed","start":110.26,"end":110.66},{"word":"their","start":110.66,"end":110.84},{"word":"own","start":110.84,"end":111.08},{"word":"unique","start":111.08,"end":111.44},{"word":"rituals","start":111.44,"end":111.8},{"word":"around","start":111.8,"end":112.08},{"word":"tea,","start":112.08,"end":112.4}],"textKo":"일본인들은 결국 차를 중심으로 자신들만의 독특한 의식을 발전시켰어요.","listenDifficulty":2},{"index":24,"start":112.64,"end":115.56,"textEn":"Leading to the creation of the Japanese tea ceremony.","words":[{"word":"leading","start":112.64,"end":113.26},{"word":"to","start":113.26,"end":113.46},{"word":"the","start":113.46,"end":113.58},{"word":"creation","start":113.58,"end":113.96},{"word":"of","start":113.96,"end":114.22},{"word":"the","start":114.22,"end":114.34},{"word":"Japanese","start":114.34,"end":114.78},{"word":"tea","start":114.78,"end":115.1},{"word":"ceremony.","start":115.1,"end":115.56}],"textKo":"이것이 일본 다도의 탄생으로 이어졌어요.","listenDifficulty":2},{"index":25,"start":115.88,"end":118.64,"textEn":"And in the 14th century, during the Ming Dynasty,","words":[{"word":"And","start":115.88,"end":116.38},{"word":"in","start":116.38,"end":116.5},{"word":"the","start":116.5,"end":116.6},{"word":"14th","start":116.6,"end":117.08},{"word":"century,","start":117.08,"end":117.4},{"word":"during","start":117.66,"end":117.86},{"word":"the","start":117.86,"end":118.02},{"word":"Ming","start":118.02,"end":118.22},{"word":"Dynasty,","start":118.22,"end":118.64}],"textKo":"그리고 14세기 명나라 시대에,","listenDifficulty":2},{"index":26,"start":119.22,"end":123.8,"textEn":"The Chinese emperor shifted the standard from tea pressed into cakes to loose leaf tea.","words":[{"word":"the","start":119.22,"end":119.3},{"word":"Chinese","start":119.3,"end":119.66},{"word":"emperor","start":119.66,"end":120.08},{"word":"shifted","start":120.08,"end":120.54},{"word":"the","start":120.54,"end":120.72},{"word":"standard","start":120.72,"end":121.14},{"word":"from","start":121.14,"end":121.48},{"word":"tea","start":121.48,"end":121.76},{"word":"pressed","start":121.76,"end":122.12},{"word":"into","start":122.12,"end":122.34},{"word":"cakes","start":122.34,"end":122.66},{"word":"to","start":122.66,"end":123.14},{"word":"loose","start":123.14,"end":123.38},{"word":"leaf","start":123.38,"end":123.56},{"word":"tea.","start":123.56,"end":123.8}],"textKo":"중국 황제가 떡 형태의 차에서 잎차로 기준을 바꾸었어요.","listenDifficulty":2},{"index":27,"start":124.34,"end":128.38,"textEn":"At that point, China still held a virtual monopoly on the world''s tea trees,","words":[{"word":"At","start":124.34,"end":124.8},{"word":"that","start":124.8,"end":124.96},{"word":"point,","start":124.96,"end":125.22},{"word":"China","start":125.44,"end":125.64},{"word":"still","start":125.64,"end":125.88},{"word":"held","start":125.88,"end":126.18},{"word":"a","start":126.18,"end":126.3},{"word":"virtual","start":126.3,"end":126.64},{"word":"monopoly","start":126.64,"end":127.12},{"word":"on","start":127.12,"end":127.42},{"word":"the","start":127.42,"end":127.52},{"word":"world''s","start":127.52,"end":127.82},{"word":"tea","start":127.82,"end":128.02},{"word":"trees,","start":128.02,"end":128.38}],"textKo":"그 시점에서 중국은 여전히 세계 차나무에 대한 사실상의 독점권을 가지고 있었어요.","listenDifficulty":3},{"index":28,"start":128.8,"end":133.72,"textEn":"Making tea one of three essential Chinese export goods, along with porcelain and silk.","words":[{"word":"making","start":128.8,"end":129.04},{"word":"tea","start":129.04,"end":129.38},{"word":"one","start":129.38,"end":129.7},{"word":"of","start":129.7,"end":129.84},{"word":"three","start":129.84,"end":130.12},{"word":"essential","start":130.12,"end":130.62},{"word":"Chinese","start":130.62,"end":130.94},{"word":"export","start":130.94,"end":131.44},{"word":"goods,","start":131.44,"end":131.8},{"word":"along","start":131.92,"end":132.4},{"word":"with","start":132.4,"end":132.6},{"word":"porcelain","start":132.6,"end":133.14},{"word":"and","start":133.14,"end":133.42},{"word":"silk.","start":133.42,"end":133.72}],"textKo":"차를 도자기, 비단과 함께 중국의 3대 필수 수출품 중 하나로 만들었어요.","listenDifficulty":2},{"index":29,"start":133.72,"end":137.62,"textEn":"This gave China a great deal of power and economic influence,","words":[{"word":"This","start":133.72,"end":134.74},{"word":"gave","start":134.74,"end":134.96},{"word":"China","start":134.96,"end":135.24},{"word":"a","start":135.24,"end":135.42},{"word":"great","start":135.42,"end":135.66},{"word":"deal","start":135.66,"end":135.86},{"word":"of","start":135.86,"end":136.02},{"word":"power","start":136.02,"end":136.32},{"word":"and","start":136.32,"end":136.58},{"word":"economic","start":136.58,"end":137.08},{"word":"influence,","start":137.08,"end":137.62}],"textKo":"이것은 중국에 큰 힘과 경제적 영향력을 주었어요.","listenDifficulty":1},{"index":30,"start":137.82,"end":142.72,"textEn":"As tea drinking spread around the world. That spread began in earnest around the early 1600s,","words":[{"word":"as","start":137.82,"end":138.18},{"word":"tea","start":138.18,"end":138.4},{"word":"drinking","start":138.4,"end":138.7},{"word":"spread","start":138.7,"end":139.04},{"word":"around","start":139.04,"end":139.26},{"word":"the","start":139.26,"end":139.38},{"word":"world.","start":139.38,"end":139.62},{"word":"That","start":140.04,"end":140.52},{"word":"spread","start":140.52,"end":140.78},{"word":"began","start":140.78,"end":141.08},{"word":"in","start":141.08,"end":141.28},{"word":"earnest","start":141.28,"end":141.6},{"word":"around","start":141.6,"end":141.9},{"word":"the","start":141.9,"end":142.06},{"word":"early","start":142.06,"end":142.34},{"word":"1600s,","start":142.34,"end":142.72}],"textKo":"차 문화가 전 세계로 퍼져나가면서요. 그 확산은 1600년대 초에 본격적으로 시작되었어요.","listenDifficulty":3},{"index":31,"start":143.34,"end":146.14,"textEn":"When Dutch traders brought tea to Europe in large quantities.","words":[{"word":"when","start":143.34,"end":143.58},{"word":"Dutch","start":143.58,"end":143.84},{"word":"traders","start":143.84,"end":144.2},{"word":"brought","start":144.2,"end":144.46},{"word":"tea","start":144.46,"end":144.7},{"word":"to","start":144.7,"end":144.88},{"word":"Europe","start":144.88,"end":145.16},{"word":"in","start":145.16,"end":145.44},{"word":"large","start":145.44,"end":145.68},{"word":"quantities.","start":145.68,"end":146.14}],"textKo":"네덜란드 상인들이 대량의 차를 유럽에 가져왔을 때예요.","listenDifficulty":3},{"index":32,"start":146.8,"end":150.54,"textEn":"Many credit Queen Catherine of Braganza, a Portuguese noblewoman,","words":[{"word":"Many","start":146.8,"end":147.18},{"word":"credit","start":147.18,"end":147.5},{"word":"Queen","start":147.5,"end":147.84},{"word":"Catherine","start":147.84,"end":148.26},{"word":"of","start":148.26,"end":148.46},{"word":"Braganza,","start":148.46,"end":148.98},{"word":"a","start":149.16,"end":149.38},{"word":"Portuguese","start":149.38,"end":149.88},{"word":"noblewoman,","start":149.88,"end":150.54}],"textKo":"많은 사람들이 포르투갈 귀족 여성인 카타리나 드 브라간사 왕비의 공을 인정해요.","listenDifficulty":1},{"index":33,"start":150.86,"end":156.7,"textEn":"For making tea popular with the English aristocracy when she married King Charles II in 1661.","words":[{"word":"for","start":150.86,"end":150.98},{"word":"making","start":150.98,"end":151.24},{"word":"tea","start":151.24,"end":151.52},{"word":"popular","start":151.52,"end":152.02},{"word":"with","start":152.02,"end":152.3},{"word":"the","start":152.3,"end":152.44},{"word":"English","start":152.44,"end":152.7},{"word":"aristocracy","start":152.7,"end":153.48},{"word":"when","start":153.48,"end":153.82},{"word":"she","start":153.82,"end":154.0},{"word":"married","start":154.0,"end":154.38},{"word":"King","start":154.38,"end":154.62},{"word":"Charles","start":154.62,"end":155.02},{"word":"II","start":155.02,"end":155.36},{"word":"in","start":155.36,"end":155.76},{"word":"1661.","start":155.76,"end":156.7}],"textKo":"그녀가 1661년 찰스 2세와 결혼했을 때 영국 귀족 사이에서 차를 유행시킨 것으로요.","listenDifficulty":2},{"index":34,"start":157.26,"end":161.5,"textEn":"At the time, Great Britain was in the midst of expanding its colonial influence","words":[{"word":"At","start":157.26,"end":157.82},{"word":"the","start":157.82,"end":157.94},{"word":"time,","start":157.94,"end":158.22},{"word":"Great","start":158.56,"end":158.72},{"word":"Britain","start":158.72,"end":159.0},{"word":"was","start":159.0,"end":159.22},{"word":"in","start":159.22,"end":159.36},{"word":"the","start":159.36,"end":159.44},{"word":"midst","start":159.44,"end":159.68},{"word":"of","start":159.68,"end":159.82},{"word":"expanding","start":159.82,"end":160.3},{"word":"its","start":160.3,"end":160.54},{"word":"colonial","start":160.54,"end":160.9},{"word":"influence","start":160.9,"end":161.5}],"textKo":"당시 영국은 식민지 영향력을 확대하는 한가운데에 있었고","listenDifficulty":3},{"index":35,"start":161.5,"end":163.72,"textEn":"And becoming the new dominant world power.","words":[{"word":"and","start":161.5,"end":161.88},{"word":"becoming","start":161.88,"end":162.28},{"word":"the","start":162.28,"end":162.5},{"word":"new","start":162.5,"end":162.7},{"word":"dominant","start":162.7,"end":163.1},{"word":"world","start":163.1,"end":163.34},{"word":"power.","start":163.34,"end":163.72}],"textKo":"새로운 세계 지배 강국이 되어가고 있었어요.","listenDifficulty":2},{"index":36,"start":164.12,"end":167.66,"textEn":"And as Great Britain grew, interest in tea spread around the world.","words":[{"word":"And","start":164.12,"end":164.68},{"word":"as","start":164.68,"end":164.84},{"word":"Great","start":164.84,"end":165.02},{"word":"Britain","start":165.02,"end":165.32},{"word":"grew,","start":165.32,"end":165.6},{"word":"interest","start":165.82,"end":166.36},{"word":"in","start":166.36,"end":166.52},{"word":"tea","start":166.52,"end":166.72},{"word":"spread","start":166.72,"end":167.08},{"word":"around","start":167.08,"end":167.3},{"word":"the","start":167.3,"end":167.42},{"word":"world.","start":167.42,"end":167.66}],"textKo":"그리고 영국이 성장하면서, 차에 대한 관심이 전 세계로 퍼져나갔어요.","listenDifficulty":3},{"index":37,"start":168.02,"end":172.48,"textEn":"By 1700, tea in Europe sold for 10 times the price of coffee,","words":[{"word":"By","start":168.02,"end":168.54},{"word":"1700,","start":168.54,"end":169.08},{"word":"tea","start":169.88,"end":170.04},{"word":"in","start":170.04,"end":170.2},{"word":"Europe","start":170.2,"end":170.4},{"word":"sold","start":170.4,"end":170.74},{"word":"for","start":170.74,"end":170.96},{"word":"10","start":170.96,"end":171.24},{"word":"times","start":171.24,"end":171.58},{"word":"the","start":171.58,"end":171.8},{"word":"price","start":171.8,"end":172.02},{"word":"of","start":172.02,"end":172.16},{"word":"coffee,","start":172.16,"end":172.48}],"textKo":"1700년까지 유럽에서 차는 커피의 10배 가격에 팔렸어요.","listenDifficulty":1},{"index":38,"start":172.64,"end":175.1,"textEn":"And the plant was still only grown in China.","words":[{"word":"and","start":172.64,"end":173.14},{"word":"the","start":173.14,"end":173.24},{"word":"plant","start":173.24,"end":173.5},{"word":"was","start":173.5,"end":173.7},{"word":"still","start":173.7,"end":173.96},{"word":"only","start":173.96,"end":174.32},{"word":"grown","start":174.32,"end":174.6},{"word":"in","start":174.6,"end":174.8},{"word":"China.","start":174.8,"end":175.1}],"textKo":"그리고 차나무는 여전히 중국에서만 재배되고 있었어요.","listenDifficulty":3},{"index":39,"start":175.66,"end":180.2,"textEn":"The tea trade was so lucrative that the world''s fastest sailboat, the Clipper Ship,","words":[{"word":"The","start":175.66,"end":176.22},{"word":"tea","start":176.22,"end":176.4},{"word":"trade","start":176.4,"end":176.64},{"word":"was","start":176.64,"end":176.8},{"word":"so","start":176.8,"end":177.04},{"word":"lucrative","start":177.04,"end":177.48},{"word":"that","start":177.48,"end":178.0},{"word":"the","start":178.0,"end":178.14},{"word":"world''s","start":178.14,"end":178.5},{"word":"fastest","start":178.5,"end":178.9},{"word":"sailboat,","start":178.9,"end":179.4},{"word":"the","start":179.54,"end":179.74},{"word":"Clipper","start":179.74,"end":180.04},{"word":"Ship,","start":180.04,"end":180.2}],"textKo":"차 무역이 너무 수익성이 좋아서 세계에서 가장 빠른 범선인 클리퍼선이","listenDifficulty":3},{"index":40,"start":180.54,"end":184.0,"textEn":"Was born out of intense competition between Western trading companies.","words":[{"word":"was","start":180.54,"end":180.82},{"word":"born","start":180.82,"end":181.12},{"word":"out","start":181.12,"end":181.34},{"word":"of","start":181.34,"end":181.46},{"word":"intense","start":181.46,"end":181.8},{"word":"competition","start":181.8,"end":182.36},{"word":"between","start":182.36,"end":182.8},{"word":"Western","start":182.8,"end":183.18},{"word":"trading","start":183.18,"end":183.5},{"word":"companies.","start":183.5,"end":184.0}],"textKo":"서양 무역 회사들 간의 치열한 경쟁에서 탄생했어요.","listenDifficulty":1},{"index":41,"start":184.32,"end":188.62,"textEn":"All were racing to bring their tea back to Europe first, to maximize their profits.","words":[{"word":"All","start":184.32,"end":184.84},{"word":"were","start":184.84,"end":185.02},{"word":"racing","start":185.02,"end":185.34},{"word":"to","start":185.34,"end":185.54},{"word":"bring","start":185.54,"end":185.78},{"word":"their","start":185.78,"end":185.94},{"word":"tea","start":185.94,"end":186.14},{"word":"back","start":186.14,"end":186.36},{"word":"to","start":186.36,"end":186.5},{"word":"Europe","start":186.5,"end":186.76},{"word":"first,","start":186.76,"end":187.14},{"word":"to","start":187.32,"end":187.54},{"word":"maximize","start":187.54,"end":187.96},{"word":"their","start":187.96,"end":188.22},{"word":"profits.","start":188.22,"end":188.62}],"textKo":"모두 이익을 극대화하기 위해 차를 유럽에 가장 먼저 가져오려고 경쟁했어요.","listenDifficulty":3},{"index":42,"start":188.62,"end":192.72,"textEn":"At first, Britain paid for all this Chinese tea with silver.","words":[{"word":"At","start":188.62,"end":189.7},{"word":"first,","start":189.7,"end":190.04},{"word":"Britain","start":190.42,"end":190.58},{"word":"paid","start":190.58,"end":190.84},{"word":"for","start":190.84,"end":191.0},{"word":"all","start":191.0,"end":191.2},{"word":"this","start":191.2,"end":191.4},{"word":"Chinese","start":191.4,"end":191.68},{"word":"tea","start":191.68,"end":191.98},{"word":"with","start":191.98,"end":192.36},{"word":"silver.","start":192.36,"end":192.72}],"textKo":"처음에 영국은 이 모든 중국 차를 은으로 지불했어요.","listenDifficulty":1},{"index":43,"start":193.1,"end":198.6,"textEn":"When that proved too expensive, they suggested trading tea for another substance, opium.","words":[{"word":"When","start":193.1,"end":193.64},{"word":"that","start":193.64,"end":193.8},{"word":"proved","start":193.8,"end":194.1},{"word":"too","start":194.1,"end":194.3},{"word":"expensive,","start":194.3,"end":194.78},{"word":"they","start":195.16,"end":195.34},{"word":"suggested","start":195.34,"end":195.8},{"word":"trading","start":195.8,"end":196.16},{"word":"tea","start":196.16,"end":196.48},{"word":"for","start":196.48,"end":196.88},{"word":"another","start":196.88,"end":197.16},{"word":"substance,","start":197.16,"end":197.68},{"word":"opium.","start":198.02,"end":198.6}],"textKo":"그것이 너무 비싸다는 것이 드러나자, 차를 다른 물질인 아편과 교환하자고 제안했어요.","listenDifficulty":2},{"index":44,"start":199.06,"end":203.66,"textEn":"This triggered a public health problem within China, as people became addicted to the drug.","words":[{"word":"This","start":199.06,"end":199.68},{"word":"triggered","start":199.68,"end":199.98},{"word":"a","start":199.98,"end":200.12},{"word":"public","start":200.12,"end":200.38},{"word":"health","start":200.38,"end":200.6},{"word":"problem","start":200.6,"end":200.96},{"word":"within","start":200.96,"end":201.18},{"word":"China,","start":201.18,"end":201.62},{"word":"as","start":201.8,"end":202.18},{"word":"people","start":202.18,"end":202.44},{"word":"became","start":202.44,"end":202.76},{"word":"addicted","start":202.76,"end":203.12},{"word":"to","start":203.12,"end":203.32},{"word":"the","start":203.32,"end":203.42},{"word":"drug.","start":203.42,"end":203.66}],"textKo":"이것은 사람들이 마약에 중독되면서 중국 내에 공중 보건 문제를 일으켰어요.","listenDifficulty":3},{"index":45,"start":204.46,"end":210.34,"textEn":"Then in 1839, a Chinese official ordered his men to destroy massive British shipments of opium","words":[{"word":"Then","start":204.46,"end":204.8},{"word":"in","start":204.8,"end":204.96},{"word":"1839,","start":204.96,"end":205.82},{"word":"a","start":206.1,"end":206.26},{"word":"Chinese","start":206.26,"end":206.56},{"word":"official","start":206.56,"end":207.04},{"word":"ordered","start":207.04,"end":207.4},{"word":"his","start":207.4,"end":207.62},{"word":"men","start":207.62,"end":207.88},{"word":"to","start":207.88,"end":208.08},{"word":"destroy","start":208.08,"end":208.42},{"word":"massive","start":208.42,"end":208.9},{"word":"British","start":208.9,"end":209.2},{"word":"shipments","start":209.2,"end":209.72},{"word":"of","start":209.72,"end":209.92},{"word":"opium","start":209.92,"end":210.34}],"textKo":"그러다 1839년, 한 중국 관리가 부하들에게 영국의 대규모 아편 화물을 파괴하라고 명령했어요.","listenDifficulty":1},{"index":46,"start":210.34,"end":212.96,"textEn":"As a statement against Britain''s influence over China.","words":[{"word":"as","start":210.34,"end":210.74},{"word":"a","start":210.74,"end":210.86},{"word":"statement","start":210.86,"end":211.18},{"word":"against","start":211.18,"end":211.52},{"word":"Britain''s","start":211.52,"end":211.98},{"word":"influence","start":211.98,"end":212.36},{"word":"over","start":212.36,"end":212.66},{"word":"China.","start":212.66,"end":212.96}],"textKo":"중국에 대한 영국의 영향력에 항의하는 의미로요.","listenDifficulty":2},{"index":47,"start":213.34,"end":216.64,"textEn":"This act triggered the first opium war between the two nations.","words":[{"word":"This","start":213.34,"end":213.9},{"word":"act","start":213.9,"end":214.06},{"word":"triggered","start":214.06,"end":214.36},{"word":"the","start":214.36,"end":214.54},{"word":"first","start":214.54,"end":214.8},{"word":"opium","start":214.8,"end":215.26},{"word":"war","start":215.26,"end":215.52},{"word":"between","start":215.52,"end":215.9},{"word":"the","start":215.9,"end":216.12},{"word":"two","start":216.12,"end":216.26},{"word":"nations.","start":216.26,"end":216.64}],"textKo":"이 행위가 두 나라 사이에 제1차 아편 전쟁을 촉발시켰어요.","listenDifficulty":3},{"index":48,"start":216.64,"end":220.7,"textEn":"Fighting raged up and down the Chinese coast until 1842,","words":[{"word":"Fighting","start":216.64,"end":217.7},{"word":"raged","start":217.7,"end":218.12},{"word":"up","start":218.12,"end":218.32},{"word":"and","start":218.32,"end":218.44},{"word":"down","start":218.44,"end":218.6},{"word":"the","start":218.6,"end":218.76},{"word":"Chinese","start":218.76,"end":219.04},{"word":"coast","start":219.04,"end":219.38},{"word":"until","start":219.38,"end":219.72},{"word":"1842,","start":219.72,"end":220.7}],"textKo":"1842년까지 중국 해안 전역에서 전투가 벌어졌어요.","listenDifficulty":1},{"index":49,"start":221.06,"end":224.82,"textEn":"When the defeated Qing Dynasty ceded the port of Hong Kong to the British","words":[{"word":"when","start":221.06,"end":221.4},{"word":"the","start":221.4,"end":221.52},{"word":"defeated","start":221.52,"end":221.9},{"word":"Qing","start":221.9,"end":222.26},{"word":"Dynasty","start":222.26,"end":222.72},{"word":"ceded","start":222.72,"end":223.34},{"word":"the","start":223.34,"end":223.5},{"word":"port","start":223.5,"end":223.68},{"word":"of","start":223.68,"end":223.82},{"word":"Hong","start":223.82,"end":224.04},{"word":"Kong","start":224.04,"end":224.22},{"word":"to","start":224.22,"end":224.46},{"word":"the","start":224.46,"end":224.56},{"word":"British","start":224.56,"end":224.82}],"textKo":"패배한 청나라가 홍콩 항구를 영국에 할양하고","listenDifficulty":3},{"index":50,"start":224.82,"end":227.22,"textEn":"And resumed trading on unfavorable terms.","words":[{"word":"and","start":224.82,"end":225.32},{"word":"resumed","start":225.32,"end":225.76},{"word":"trading","start":225.76,"end":226.04},{"word":"on","start":226.04,"end":226.24},{"word":"unfavorable","start":226.24,"end":226.9},{"word":"terms.","start":226.9,"end":227.22}],"textKo":"불리한 조건으로 무역을 재개했을 때예요.","listenDifficulty":1},{"index":51,"start":227.62,"end":230.7,"textEn":"The war weakened China''s global standing for over a century.","words":[{"word":"The","start":227.62,"end":228.06},{"word":"war","start":228.06,"end":228.28},{"word":"weakened","start":228.28,"end":228.64},{"word":"China''s","start":228.64,"end":229.06},{"word":"global","start":229.06,"end":229.28},{