INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'en', 'iB4MS1hsWXU', '{"videoId":"iB4MS1hsWXU","youtubeId":"iB4MS1hsWXU","title":"The lies our culture tells us about what matters --- and a better way to live | David Brooks","channel":"TED","categoryId":"culture","difficulty":"intermediate","duration":894,"thumbnail":"https://i.ytimg.com/vi_webp/iB4MS1hsWXU/maxresdefault.webp","speechRateWpm":188,"addedAt":"2026-02-16","segmentCount":231,"vocabularyCount":20,"grammarPatternCount":10,"descriptionKo":"우리 문화가 말하는 성공의 거짓말과 진짜 행복한 삶"}'::jsonb, '{"videoId":"iB4MS1hsWXU","segments":[{"index":0,"start":0.0,"end":14.4,"textEn":"Reviewer. So we all have bad seasons in life,","words":[{"word":"Reviewer.","start":0.0,"end":0.82},{"word":"So","start":12.26,"end":12.7},{"word":"we","start":12.7,"end":13.14},{"word":"all","start":13.14,"end":13.28},{"word":"have","start":13.28,"end":13.42},{"word":"bad","start":13.42,"end":13.6},{"word":"seasons","start":13.6,"end":13.88},{"word":"in","start":13.88,"end":14.1},{"word":"life,","start":14.1,"end":14.4}],"textKo":"","listenDifficulty":1},{"index":1,"start":15.48,"end":19.56,"textEn":"And I had one in 2013. My marriage had just ended,","words":[{"word":"and","start":15.48,"end":15.92},{"word":"I","start":15.92,"end":16.06},{"word":"had","start":16.06,"end":16.22},{"word":"one","start":16.22,"end":16.44},{"word":"in","start":16.44,"end":16.58},{"word":"2013.","start":16.58,"end":17.08},{"word":"My","start":18.16,"end":18.6},{"word":"marriage","start":18.6,"end":18.98},{"word":"had","start":18.98,"end":19.12},{"word":"just","start":19.12,"end":19.26},{"word":"ended,","start":19.26,"end":19.56}],"textKo":"그리고 2013년에 저에게도 그런 시기가 있었어요. 결혼 생활이 막 끝났거든요.","listenDifficulty":3},{"index":2,"start":19.72,"end":24.52,"textEn":"And I was humiliated by that failed commitment. My kids had left home for college or were leaving.","words":[{"word":"and","start":19.72,"end":19.78},{"word":"I","start":19.78,"end":19.88},{"word":"was","start":19.88,"end":20.06},{"word":"humiliated","start":20.06,"end":20.7},{"word":"by","start":20.7,"end":20.84},{"word":"that","start":20.84,"end":21.0},{"word":"failed","start":21.0,"end":21.26},{"word":"commitment.","start":21.26,"end":21.62},{"word":"My","start":22.14,"end":22.58},{"word":"kids","start":22.58,"end":22.82},{"word":"had","start":22.82,"end":23.02},{"word":"left","start":23.02,"end":23.2},{"word":"home","start":23.2,"end":23.48},{"word":"for","start":23.48,"end":23.66},{"word":"college","start":23.66,"end":24.04},{"word":"or","start":24.04,"end":24.2},{"word":"were","start":24.2,"end":24.34},{"word":"leaving.","start":24.34,"end":24.52}],"textKo":"그 실패한 약속에 창피했어요. 아이들은 대학에 가거나 떠나고 있었어요.","listenDifficulty":3},{"index":3,"start":25.78,"end":28.26,"textEn":"I grew up mostly in the conservative movement,","words":[{"word":"I","start":25.78,"end":26.22},{"word":"grew","start":26.22,"end":26.4},{"word":"up","start":26.4,"end":26.52},{"word":"mostly","start":26.52,"end":26.92},{"word":"in","start":26.92,"end":27.06},{"word":"the","start":27.06,"end":27.12},{"word":"conservative","start":27.12,"end":27.46},{"word":"movement,","start":27.46,"end":28.26}],"textKo":"저는 대부분 보수주의 운동 안에서 성장했어요.","listenDifficulty":1},{"index":4,"start":28.26,"end":31.5,"textEn":"But conservatism had changed, so I''d lost a lot of those friends, too.","words":[{"word":"but","start":28.26,"end":28.54},{"word":"conservatism","start":28.54,"end":29.22},{"word":"had","start":29.22,"end":29.4},{"word":"changed,","start":29.4,"end":29.76},{"word":"so","start":29.9,"end":30.1},{"word":"I''d","start":30.1,"end":30.32},{"word":"lost","start":30.32,"end":30.54},{"word":"a","start":30.54,"end":30.68},{"word":"lot","start":30.68,"end":30.74},{"word":"of","start":30.74,"end":30.84},{"word":"those","start":30.84,"end":30.98},{"word":"friends,","start":30.98,"end":31.22},{"word":"too.","start":31.32,"end":31.5}],"textKo":"하지만 보수주의가 변해서, 그 친구들도 많이 잃었어요.","listenDifficulty":4},{"index":5,"start":32.2,"end":34.24,"textEn":"And so what I did is I lived alone in an apartment,","words":[{"word":"And","start":32.2,"end":32.6},{"word":"so","start":32.6,"end":32.74},{"word":"what","start":32.74,"end":32.88},{"word":"I","start":32.88,"end":33.0},{"word":"did","start":33.0,"end":33.12},{"word":"is","start":33.12,"end":33.28},{"word":"I","start":33.28,"end":33.38},{"word":"lived","start":33.38,"end":33.54},{"word":"alone","start":33.54,"end":33.74},{"word":"in","start":33.74,"end":33.86},{"word":"an","start":33.86,"end":33.96},{"word":"apartment,","start":33.96,"end":34.24}],"textKo":"그래서 제가 한 일은 아파트에서 혼자 사는 거였어요.","listenDifficulty":3},{"index":6,"start":35.24,"end":40.06,"textEn":"And I just worked. If you open the kitchen drawers where there should have been utensils,","words":[{"word":"and","start":35.24,"end":35.64},{"word":"I","start":35.64,"end":35.76},{"word":"just","start":35.76,"end":35.94},{"word":"worked.","start":35.94,"end":36.22},{"word":"If","start":37.24,"end":37.64},{"word":"you","start":37.64,"end":37.74},{"word":"open","start":37.74,"end":38.04},{"word":"the","start":38.04,"end":38.22},{"word":"kitchen","start":38.22,"end":38.46},{"word":"drawers","start":38.46,"end":38.8},{"word":"where","start":38.8,"end":39.0},{"word":"there","start":39.0,"end":39.14},{"word":"should","start":39.14,"end":39.28},{"word":"have","start":39.28,"end":39.36},{"word":"been","start":39.36,"end":39.44},{"word":"utensils,","start":39.44,"end":40.06}],"textKo":"그리고 그냥 일만 했어요. 주방 서랍을 열면 식기가 있어야 할 자리에","listenDifficulty":3},{"index":7,"start":40.36,"end":44.8,"textEn":"There were Post-it notes. If you open the other drawers where there should have been plates,","words":[{"word":"there","start":40.36,"end":40.74},{"word":"were","start":40.74,"end":40.92},{"word":"Post","start":40.92,"end":41.2},{"word":"-it","start":41.2,"end":41.3},{"word":"notes.","start":41.3,"end":41.56},{"word":"If","start":42.68,"end":43.08},{"word":"you","start":43.08,"end":43.16},{"word":"open","start":43.16,"end":43.34},{"word":"the","start":43.34,"end":43.44},{"word":"other","start":43.44,"end":43.6},{"word":"drawers","start":43.6,"end":43.98},{"word":"where","start":43.98,"end":44.16},{"word":"there","start":44.16,"end":44.26},{"word":"should","start":44.26,"end":44.4},{"word":"have","start":44.4,"end":44.46},{"word":"been","start":44.46,"end":44.54},{"word":"plates,","start":44.54,"end":44.8}],"textKo":"포스트잇이 있었어요. 접시가 있어야 할 다른 서랍을 열면","listenDifficulty":2},{"index":8,"start":45.0,"end":49.5,"textEn":"I had envelopes. I had work friends, weekday friends,","words":[{"word":"I","start":45.0,"end":45.16},{"word":"had","start":45.16,"end":45.42},{"word":"envelopes.","start":45.42,"end":46.04},{"word":"I","start":47.64,"end":48.04},{"word":"had","start":48.04,"end":48.2},{"word":"work","start":48.2,"end":48.46},{"word":"friends,","start":48.46,"end":48.74},{"word":"weekday","start":48.92,"end":49.24},{"word":"friends,","start":49.24,"end":49.5}],"textKo":"봉투가 있었어요. 직장 친구, 주중 친구는 있었지만","listenDifficulty":1},{"index":9,"start":49.62,"end":55.02,"textEn":"But I didn''t have weekend friends. And so my weekends were these long, howling silences.","words":[{"word":"but","start":49.62,"end":49.68},{"word":"I","start":49.68,"end":49.78},{"word":"didn''t","start":49.78,"end":49.9},{"word":"have","start":49.9,"end":50.04},{"word":"weekend","start":50.04,"end":50.34},{"word":"friends.","start":50.34,"end":50.86},{"word":"And","start":51.7,"end":52.1},{"word":"so","start":52.1,"end":52.26},{"word":"my","start":52.26,"end":52.42},{"word":"weekends","start":52.42,"end":52.88},{"word":"were","start":52.88,"end":53.1},{"word":"these","start":53.1,"end":53.26},{"word":"long,","start":53.26,"end":53.74},{"word":"howling","start":53.86,"end":54.36},{"word":"silences.","start":54.36,"end":55.02}],"textKo":"주말 친구는 없었어요. 그래서 주말은 길고 텅 빈 적막이었어요.","listenDifficulty":2},{"index":10,"start":56.1,"end":61.78,"textEn":"And I was lonely. Loneliness unexpectedly came to me in the form of...","words":[{"word":"And","start":56.1,"end":56.5},{"word":"I","start":56.5,"end":56.76},{"word":"was","start":56.76,"end":56.92},{"word":"lonely.","start":56.92,"end":57.24},{"word":"Loneliness","start":58.44,"end":59.0},{"word":"unexpectedly","start":59.0,"end":59.56},{"word":"came","start":59.56,"end":59.9},{"word":"to","start":59.9,"end":60.04},{"word":"me","start":60.04,"end":60.2},{"word":"in","start":60.2,"end":60.44},{"word":"the","start":60.44,"end":60.58},{"word":"form","start":60.58,"end":61.02},{"word":"of","start":61.02,"end":61.5},{"word":"...","start":61.5,"end":61.78}],"textKo":"그리고 외로웠어요. 외로움은 예상치 못한 형태로 찾아왔어요...","listenDifficulty":1},{"index":11,"start":61.78,"end":64.44,"textEn":"It felt like fear, a burning in my stomach,","words":[{"word":"It","start":61.78,"end":62.52},{"word":"felt","start":62.52,"end":62.72},{"word":"like","start":62.72,"end":62.88},{"word":"fear,","start":62.88,"end":63.22},{"word":"a","start":63.34,"end":63.42},{"word":"burning","start":63.42,"end":63.68},{"word":"in","start":63.68,"end":63.94},{"word":"my","start":63.94,"end":64.1},{"word":"stomach,","start":64.1,"end":64.44}],"textKo":"두려움 같은 느낌이었어요, 속이 타는 듯한 느낌이요.","listenDifficulty":2},{"index":12,"start":64.82,"end":67.1,"textEn":"And it felt a little like drunkenness,","words":[{"word":"and","start":64.82,"end":65.4},{"word":"it","start":65.4,"end":65.48},{"word":"felt","start":65.48,"end":65.68},{"word":"a","start":65.68,"end":65.92},{"word":"little","start":65.92,"end":66.12},{"word":"like","start":66.12,"end":66.38},{"word":"drunkenness,","start":66.38,"end":67.1}],"textKo":"약간 취한 것 같은 느낌이기도 했어요.","listenDifficulty":1},{"index":13,"start":67.44,"end":70.76,"textEn":"Just making bad decisions or just fluidity,","words":[{"word":"just","start":67.44,"end":68.16},{"word":"making","start":68.16,"end":68.42},{"word":"bad","start":68.42,"end":68.76},{"word":"decisions","start":68.76,"end":69.2},{"word":"or","start":69.2,"end":69.46},{"word":"just","start":69.46,"end":69.64},{"word":"fluidity,","start":69.64,"end":70.76}],"textKo":"나쁜 결정을 내리거나 그냥 흐물흐물한 느낌이요.","listenDifficulty":1},{"index":14,"start":71.44,"end":75.66,"textEn":"A lack of solidity. And the painful part of that moment","words":[{"word":"a","start":71.44,"end":71.84},{"word":"lack","start":71.84,"end":71.98},{"word":"of","start":71.98,"end":72.12},{"word":"solidity.","start":72.12,"end":72.66},{"word":"And","start":73.52,"end":74.08},{"word":"the","start":74.08,"end":74.2},{"word":"painful","start":74.2,"end":74.54},{"word":"part","start":74.54,"end":74.88},{"word":"of","start":74.88,"end":75.14},{"word":"that","start":75.14,"end":75.32},{"word":"moment","start":75.32,"end":75.66}],"textKo":"단단함이 없는 느낌이요. 그 순간의 고통스러운 점은","listenDifficulty":1},{"index":15,"start":75.66,"end":78.94,"textEn":"Was the awareness that the emptiness in my apartment","words":[{"word":"was","start":75.66,"end":76.36},{"word":"the","start":76.36,"end":76.52},{"word":"awareness","start":76.52,"end":76.9},{"word":"that","start":76.9,"end":77.34},{"word":"the","start":77.34,"end":77.98},{"word":"emptiness","start":77.98,"end":78.34},{"word":"in","start":78.34,"end":78.56},{"word":"my","start":78.56,"end":78.66},{"word":"apartment","start":78.66,"end":78.94}],"textKo":"제 아파트의 공허함이","listenDifficulty":1},{"index":16,"start":78.94,"end":85.88,"textEn":"Was just reflective of the emptiness in myself, and that I''d fallen for some of the lies that our culture tells us.","words":[{"word":"was","start":78.94,"end":79.18},{"word":"just","start":79.18,"end":79.32},{"word":"reflective","start":79.32,"end":79.72},{"word":"of","start":79.72,"end":79.96},{"word":"the","start":79.96,"end":80.08},{"word":"emptiness","start":80.08,"end":80.38},{"word":"in","start":80.38,"end":80.58},{"word":"myself,","start":80.58,"end":80.92},{"word":"and","start":81.88,"end":82.44},{"word":"that","start":82.44,"end":82.64},{"word":"I''d","start":82.64,"end":82.84},{"word":"fallen","start":82.84,"end":83.24},{"word":"for","start":83.24,"end":83.68},{"word":"some","start":83.68,"end":83.88},{"word":"of","start":83.88,"end":83.98},{"word":"the","start":83.98,"end":84.04},{"word":"lies","start":84.04,"end":84.38},{"word":"that","start":84.38,"end":84.6},{"word":"our","start":84.6,"end":84.7},{"word":"culture","start":84.7,"end":85.06},{"word":"tells","start":85.06,"end":85.44},{"word":"us.","start":85.44,"end":85.88}],"textKo":"제 자신의 공허함을 반영한 것이었고, 우리 문화가 말하는 거짓말 몇 가지에 빠졌다는 자각이었어요.","listenDifficulty":1},{"index":17,"start":86.7,"end":89.72,"textEn":"The first lie is that career success is fulfilling.","words":[{"word":"The","start":86.7,"end":87.32},{"word":"first","start":87.32,"end":87.54},{"word":"lie","start":87.54,"end":87.82},{"word":"is","start":87.82,"end":88.16},{"word":"that","start":88.16,"end":88.34},{"word":"career","start":88.34,"end":88.62},{"word":"success","start":88.62,"end":89.02},{"word":"is","start":89.02,"end":89.28},{"word":"fulfilling.","start":89.28,"end":89.72}],"textKo":"첫 번째 거짓말은 직업적 성공이 만족을 준다는 거예요.","listenDifficulty":1},{"index":18,"start":90.48,"end":96.42,"textEn":"I''ve had a fair bit of career success, and I''ve found that it helps me avoid the shame I would feel if I felt myself a failure,","words":[{"word":"I''ve","start":90.48,"end":90.8},{"word":"had","start":90.8,"end":90.9},{"word":"a","start":90.9,"end":91.0},{"word":"fair","start":91.0,"end":91.14},{"word":"bit","start":91.14,"end":91.28},{"word":"of","start":91.28,"end":91.38},{"word":"career","start":91.38,"end":91.56},{"word":"success,","start":91.56,"end":92.08},{"word":"and","start":92.14,"end":92.52},{"word":"I''ve","start":92.52,"end":92.72},{"word":"found","start":92.72,"end":92.82},{"word":"that","start":92.82,"end":92.96},{"word":"it","start":92.96,"end":93.04},{"word":"helps","start":93.04,"end":93.18},{"word":"me","start":93.18,"end":93.34},{"word":"avoid","start":93.34,"end":93.62},{"word":"the","start":93.62,"end":93.8},{"word":"shame","start":93.8,"end":94.04},{"word":"I","start":94.04,"end":94.2},{"word":"would","start":94.2,"end":94.32},{"word":"feel","start":94.32,"end":94.68},{"word":"if","start":94.68,"end":95.4},{"word":"I","start":95.4,"end":95.48},{"word":"felt","start":95.48,"end":95.66},{"word":"myself","start":95.66,"end":95.98},{"word":"a","start":95.98,"end":96.14},{"word":"failure,","start":96.14,"end":96.42}],"textKo":"저는 꽤 많은 직업적 성공을 거뒀고, 실패자라고 느낄 때의 수치심을 피하는 데는 도움이 됐지만","listenDifficulty":3},{"index":19,"start":96.42,"end":98.92,"textEn":"But it hasn''t given me any positive good.","words":[{"word":"but","start":96.42,"end":97.14},{"word":"it","start":97.14,"end":97.24},{"word":"hasn''t","start":97.24,"end":97.5},{"word":"given","start":97.5,"end":97.68},{"word":"me","start":97.68,"end":97.86},{"word":"any","start":97.86,"end":98.1},{"word":"positive","start":98.1,"end":98.62},{"word":"good.","start":98.62,"end":98.92}],"textKo":"어떤 긍정적인 좋은 것도 주지는 못했어요.","listenDifficulty":1},{"index":20,"start":99.72,"end":103.52,"textEn":"The second lie is I can make myself happy.","words":[{"word":"The","start":99.72,"end":100.32},{"word":"second","start":100.32,"end":100.6},{"word":"lie","start":100.6,"end":100.98},{"word":"is","start":100.98,"end":102.04},{"word":"I","start":102.04,"end":102.28},{"word":"can","start":102.28,"end":102.46},{"word":"make","start":102.46,"end":102.68},{"word":"myself","start":102.68,"end":103.08},{"word":"happy.","start":103.08,"end":103.52}],"textKo":"두 번째 거짓말은 스스로를 행복하게 만들 수 있다는 거예요.","listenDifficulty":1},{"index":21,"start":103.52,"end":105.98,"textEn":"That if I just win one more victory,","words":[{"word":"That","start":103.52,"end":104.62},{"word":"if","start":104.62,"end":104.76},{"word":"I","start":104.76,"end":104.84},{"word":"just","start":104.84,"end":105.04},{"word":"win","start":105.04,"end":105.24},{"word":"one","start":105.24,"end":105.42},{"word":"more","start":105.42,"end":105.62},{"word":"victory,","start":105.62,"end":105.98}],"textKo":"한 번만 더 승리하면,","listenDifficulty":1},{"index":22,"start":106.6,"end":109.3,"textEn":"Lose 15 pounds, do a little more yoga,","words":[{"word":"lose","start":106.6,"end":106.84},{"word":"15","start":106.84,"end":107.2},{"word":"pounds,","start":107.2,"end":107.76},{"word":"do","start":108.28,"end":108.56},{"word":"a","start":108.56,"end":108.66},{"word":"little","start":108.66,"end":108.74},{"word":"more","start":108.74,"end":108.94},{"word":"yoga,","start":108.94,"end":109.3}],"textKo":"7킬로만 빼면, 요가를 조금 더 하면","listenDifficulty":1},{"index":23,"start":109.58,"end":113.42,"textEn":"I''ll get happy. And that''s the lie of self-sufficiency.","words":[{"word":"I''ll","start":109.58,"end":110.28},{"word":"get","start":110.28,"end":110.42},{"word":"happy.","start":110.42,"end":110.74},{"word":"And","start":111.42,"end":111.9},{"word":"that''s","start":111.9,"end":112.16},{"word":"the","start":112.16,"end":112.28},{"word":"lie","start":112.28,"end":112.48},{"word":"of","start":112.48,"end":112.64},{"word":"self","start":112.64,"end":112.86},{"word":"-sufficiency.","start":112.86,"end":113.42}],"textKo":"행복해질 거라는 거예요. 그것이 자급자족의 거짓말이에요.","listenDifficulty":2},{"index":24,"start":114.04,"end":116.18,"textEn":"But as anybody on their deathbed will tell you,","words":[{"word":"But","start":114.04,"end":114.52},{"word":"as","start":114.52,"end":114.64},{"word":"anybody","start":114.64,"end":114.88},{"word":"on","start":114.88,"end":115.08},{"word":"their","start":115.08,"end":115.18},{"word":"deathbed","start":115.18,"end":115.58},{"word":"will","start":115.58,"end":115.72},{"word":"tell","start":115.72,"end":115.92},{"word":"you,","start":115.92,"end":116.18}],"textKo":"하지만 임종을 앞둔 사람이라면 누구나 말해 줄 거예요.","listenDifficulty":2},{"index":25,"start":117.12,"end":120.12,"textEn":"The things that make people happy is the deep relationships of life,","words":[{"word":"the","start":117.12,"end":117.28},{"word":"things","start":117.28,"end":117.5},{"word":"that","start":117.5,"end":117.66},{"word":"make","start":117.66,"end":117.82},{"word":"people","start":117.82,"end":118.1},{"word":"happy","start":118.1,"end":118.38},{"word":"is","start":118.38,"end":118.68},{"word":"the","start":118.68,"end":118.84},{"word":"deep","start":118.84,"end":119.06},{"word":"relationships","start":119.06,"end":119.54},{"word":"of","start":119.54,"end":119.86},{"word":"life,","start":119.86,"end":120.12}],"textKo":"사람을 행복하게 만드는 것은 삶의 깊은 관계라고요.","listenDifficulty":2},{"index":26,"start":120.34,"end":125.96,"textEn":"The losing of self-sufficiency. The third lie is the lie of the meritocracy.","words":[{"word":"the","start":120.34,"end":120.54},{"word":"losing","start":120.54,"end":120.86},{"word":"of","start":120.86,"end":121.12},{"word":"self","start":121.12,"end":121.36},{"word":"-sufficiency.","start":121.36,"end":121.94},{"word":"The","start":123.5,"end":123.94},{"word":"third","start":123.94,"end":124.16},{"word":"lie","start":124.16,"end":124.48},{"word":"is","start":124.48,"end":124.74},{"word":"the","start":124.74,"end":124.88},{"word":"lie","start":124.88,"end":125.06},{"word":"of","start":125.06,"end":125.24},{"word":"the","start":125.24,"end":125.32},{"word":"meritocracy.","start":125.32,"end":125.96}],"textKo":"자급자족을 내려놓는 거예요. 세 번째 거짓말은 능력주의의 거짓말이에요.","listenDifficulty":2},{"index":27,"start":127.14,"end":130.08,"textEn":"The message of the meritocracy is you are what you accomplish.","words":[{"word":"The","start":127.14,"end":127.58},{"word":"message","start":127.58,"end":128.02},{"word":"of","start":128.02,"end":128.22},{"word":"the","start":128.22,"end":128.28},{"word":"meritocracy","start":128.28,"end":128.9},{"word":"is","start":128.9,"end":129.16},{"word":"you","start":129.16,"end":129.3},{"word":"are","start":129.3,"end":129.46},{"word":"what","start":129.46,"end":129.62},{"word":"you","start":129.62,"end":129.7},{"word":"accomplish.","start":129.7,"end":130.08}],"textKo":"능력주의의 메시지는 당신은 당신이 이룬 것이라는 거예요.","listenDifficulty":2},{"index":28,"start":130.82,"end":133.52,"textEn":"The myth of the meritocracy is you can earn dignity","words":[{"word":"The","start":130.82,"end":131.26},{"word":"myth","start":131.26,"end":131.5},{"word":"of","start":131.5,"end":131.66},{"word":"the","start":131.66,"end":131.76},{"word":"meritocracy","start":131.76,"end":132.34},{"word":"is","start":132.34,"end":132.54},{"word":"you","start":132.54,"end":132.64},{"word":"can","start":132.64,"end":132.78},{"word":"earn","start":132.78,"end":133.06},{"word":"dignity","start":133.06,"end":133.52}],"textKo":"능력주의의 신화는 존엄성을 벌 수 있다는 거예요.","listenDifficulty":2},{"index":29,"start":133.52,"end":139.0,"textEn":"By attaching yourself to prestigious brands. The emotion of the meritocracy is conditional love,","words":[{"word":"by","start":133.52,"end":133.74},{"word":"attaching","start":133.74,"end":134.12},{"word":"yourself","start":134.12,"end":134.38},{"word":"to","start":134.38,"end":134.58},{"word":"prestigious","start":134.58,"end":135.0},{"word":"brands.","start":135.0,"end":135.46},{"word":"The","start":136.04,"end":136.36},{"word":"emotion","start":136.36,"end":136.7},{"word":"of","start":136.7,"end":136.98},{"word":"the","start":136.98,"end":137.4},{"word":"meritocracy","start":137.4,"end":138.02},{"word":"is","start":138.02,"end":138.22},{"word":"conditional","start":138.22,"end":138.64},{"word":"love,","start":138.64,"end":139.0}],"textKo":"명문 브랜드에 자신을 붙여서요. 능력주의의 감정은 조건부 사랑이에요.","listenDifficulty":1},{"index":30,"start":139.08,"end":144.0,"textEn":"You can earn your way to love. The anthropology of the meritocracy is you''re not a soul to be purified,","words":[{"word":"you","start":139.08,"end":139.16},{"word":"can","start":139.16,"end":139.3},{"word":"earn","start":139.3,"end":139.48},{"word":"your","start":139.48,"end":139.62},{"word":"way","start":139.62,"end":139.74},{"word":"to","start":139.74,"end":139.84},{"word":"love.","start":139.84,"end":140.16},{"word":"The","start":140.62,"end":141.06},{"word":"anthropology","start":141.06,"end":141.48},{"word":"of","start":141.48,"end":141.82},{"word":"the","start":141.82,"end":141.88},{"word":"meritocracy","start":141.88,"end":142.44},{"word":"is","start":142.44,"end":142.64},{"word":"you''re","start":142.64,"end":142.78},{"word":"not","start":142.78,"end":142.86},{"word":"a","start":142.86,"end":143.02},{"word":"soul","start":143.02,"end":143.2},{"word":"to","start":143.2,"end":143.32},{"word":"be","start":143.32,"end":143.44},{"word":"purified,","start":143.44,"end":144.0}],"textKo":"사랑을 노력해서 얻을 수 있다는 거예요. 능력주의의 인간관은 당신은 정화해야 할 영혼이 아니라","listenDifficulty":3},{"index":31,"start":144.22,"end":149.92,"textEn":"You''re a set of skills to be maximized. And the evil of the meritocracy is that people who''ve achieved","words":[{"word":"you''re","start":144.22,"end":144.5},{"word":"a","start":144.5,"end":144.58},{"word":"set","start":144.58,"end":144.72},{"word":"of","start":144.72,"end":144.84},{"word":"skills","start":144.84,"end":145.1},{"word":"to","start":145.1,"end":145.3},{"word":"be","start":145.3,"end":145.4},{"word":"maximized.","start":145.4,"end":146.08},{"word":"And","start":146.66,"end":147.02},{"word":"the","start":147.02,"end":147.14},{"word":"evil","start":147.14,"end":147.46},{"word":"of","start":147.46,"end":147.64},{"word":"the","start":147.64,"end":147.72},{"word":"meritocracy","start":147.72,"end":148.34},{"word":"is","start":148.34,"end":148.96},{"word":"that","start":148.96,"end":149.1},{"word":"people","start":149.1,"end":149.38},{"word":"who''ve","start":149.38,"end":149.62},{"word":"achieved","start":149.62,"end":149.92}],"textKo":"극대화해야 할 기술의 집합이라는 거예요. 그리고 능력주의의 악은 조금 더 이룬 사람이","listenDifficulty":1},{"index":32,"start":149.92,"end":153.02,"textEn":"A little more than others are actually worth a little more than others.","words":[{"word":"a","start":149.92,"end":150.14},{"word":"little","start":150.14,"end":150.26},{"word":"more","start":150.26,"end":150.46},{"word":"than","start":150.46,"end":150.6},{"word":"others","start":150.6,"end":150.94},{"word":"are","start":150.94,"end":151.52},{"word":"actually","start":151.52,"end":151.86},{"word":"worth","start":151.86,"end":152.1},{"word":"a","start":152.1,"end":152.26},{"word":"little","start":152.26,"end":152.38},{"word":"more","start":152.38,"end":152.58},{"word":"than","start":152.58,"end":152.72},{"word":"others.","start":152.72,"end":153.02}],"textKo":"실제로 다른 사람보다 조금 더 가치 있다는 거예요.","listenDifficulty":2},{"index":33,"start":153.92,"end":158.3,"textEn":"And so the wages of sin are sin, and my sins were the sins of omission,","words":[{"word":"And","start":153.92,"end":154.28},{"word":"so","start":154.28,"end":154.4},{"word":"the","start":154.4,"end":154.5},{"word":"wages","start":154.5,"end":154.74},{"word":"of","start":154.74,"end":154.94},{"word":"sin","start":154.94,"end":155.14},{"word":"are","start":155.14,"end":155.28},{"word":"sin,","start":155.28,"end":155.54},{"word":"and","start":156.58,"end":156.94},{"word":"my","start":156.94,"end":157.12},{"word":"sins","start":157.12,"end":157.42},{"word":"were","start":157.42,"end":157.56},{"word":"the","start":157.56,"end":157.66},{"word":"sins","start":157.66,"end":157.86},{"word":"of","start":157.86,"end":157.98},{"word":"omission,","start":157.98,"end":158.3}],"textKo":"그래서 죄의 대가는 또 다른 죄이고, 제 죄는 빠뜨림의 죄였어요.","listenDifficulty":3},{"index":34,"start":158.44,"end":162.22,"textEn":"Not reaching out, failing to show up for my friends, evasion, avoiding conflict.","words":[{"word":"not","start":158.44,"end":158.56},{"word":"reaching","start":158.56,"end":158.8},{"word":"out,","start":158.8,"end":158.98},{"word":"failing","start":159.06,"end":159.26},{"word":"to","start":159.26,"end":159.38},{"word":"show","start":159.38,"end":159.5},{"word":"up","start":159.5,"end":159.6},{"word":"for","start":159.6,"end":159.68},{"word":"my","start":159.68,"end":159.8},{"word":"friends,","start":159.8,"end":160.18},{"word":"evasion,","start":160.86,"end":161.22},{"word":"avoiding","start":161.46,"end":161.78},{"word":"conflict.","start":161.78,"end":162.22}],"textKo":"손을 내밀지 않고, 친구들에게 나타나지 않고, 회피하고, 갈등을 피하는 것이었어요.","listenDifficulty":3},{"index":35,"start":163.3,"end":165.68,"textEn":"And the weird thing was that as I was falling in the valley,","words":[{"word":"And","start":163.3,"end":163.66},{"word":"the","start":163.66,"end":163.76},{"word":"weird","start":163.76,"end":163.88},{"word":"thing","start":163.88,"end":164.02},{"word":"was","start":164.02,"end":164.22},{"word":"that","start":164.22,"end":164.38},{"word":"as","start":164.38,"end":164.56},{"word":"I","start":164.56,"end":164.74},{"word":"was","start":164.74,"end":164.9},{"word":"falling","start":164.9,"end":165.18},{"word":"in","start":165.18,"end":165.28},{"word":"the","start":165.28,"end":165.36},{"word":"valley,","start":165.36,"end":165.68}],"textKo":"이상한 것은 제가 골짜기로 떨어지고 있을 때","listenDifficulty":3},{"index":36,"start":166.42,"end":169.34,"textEn":"It was a valley of disconnection. A lot of other people were doing that, too.","words":[{"word":"it","start":166.42,"end":166.78},{"word":"was","start":166.78,"end":166.88},{"word":"a","start":166.88,"end":167.0},{"word":"valley","start":167.0,"end":167.22},{"word":"of","start":167.22,"end":167.36},{"word":"disconnection.","start":167.36,"end":167.9},{"word":"A","start":167.98,"end":168.08},{"word":"lot","start":168.08,"end":168.18},{"word":"of","start":168.18,"end":168.3},{"word":"other","start":168.3,"end":168.48},{"word":"people","start":168.48,"end":168.72},{"word":"were","start":168.72,"end":168.88},{"word":"doing","start":168.88,"end":169.0},{"word":"that,","start":169.0,"end":169.16},{"word":"too.","start":169.24,"end":169.34}],"textKo":"그것은 단절의 골짜기였어요. 많은 다른 사람들도 그렇게 하고 있었어요.","listenDifficulty":3},{"index":37,"start":170.8,"end":173.66,"textEn":"And that''s sort of the secret to my career. A lot of the things that happen to me","words":[{"word":"And","start":170.8,"end":171.16},{"word":"that''s","start":171.16,"end":171.36},{"word":"sort","start":171.36,"end":171.48},{"word":"of","start":171.48,"end":171.56},{"word":"the","start":171.56,"end":171.68},{"word":"secret","start":171.68,"end":171.9},{"word":"to","start":171.9,"end":172.06},{"word":"my","start":172.06,"end":172.18},{"word":"career.","start":172.18,"end":172.4},{"word":"A","start":172.5,"end":172.58},{"word":"lot","start":172.58,"end":172.64},{"word":"of","start":172.64,"end":172.76},{"word":"the","start":172.76,"end":172.98},{"word":"things","start":172.98,"end":173.18},{"word":"that","start":173.18,"end":173.3},{"word":"happen","start":173.3,"end":173.5},{"word":"to","start":173.5,"end":173.58},{"word":"me","start":173.58,"end":173.66}],"textKo":"그게 제 경력의 비밀이에요. 저에게 일어나는 많은 일들이","listenDifficulty":4},{"index":38,"start":173.66,"end":179.1,"textEn":"Are always happening to a lot of other people. I''m a very average person with above-average communication skills.","words":[{"word":"are","start":173.66,"end":173.78},{"word":"always","start":173.78,"end":174.0},{"word":"happening","start":174.0,"end":174.24},{"word":"to","start":174.24,"end":174.36},{"word":"a","start":174.36,"end":174.5},{"word":"lot","start":174.5,"end":174.6},{"word":"of","start":174.6,"end":174.7},{"word":"other","start":174.7,"end":174.84},{"word":"people.","start":174.84,"end":175.12},{"word":"I''m","start":176.08,"end":176.36},{"word":"a","start":176.36,"end":176.48},{"word":"very","start":176.48,"end":176.74},{"word":"average","start":176.74,"end":177.1},{"word":"person","start":177.1,"end":177.46},{"word":"with","start":177.46,"end":177.62},{"word":"above","start":177.62,"end":177.88},{"word":"-average","start":177.88,"end":178.16},{"word":"communication","start":178.16,"end":178.6},{"word":"skills.","start":178.6,"end":179.1}],"textKo":"항상 다른 많은 사람들에게도 일어나요. 저는 평균 이상의 소통 능력을 가진 아주 평범한 사람이에요.","listenDifficulty":2},{"index":39,"start":181.0,"end":185.42,"textEn":"And so I was detached. And at the same time, a lot of other people were detached","words":[{"word":"And","start":181.0,"end":181.52},{"word":"so","start":181.52,"end":181.68},{"word":"I","start":181.68,"end":181.82},{"word":"was","start":181.82,"end":181.98},{"word":"detached.","start":181.98,"end":182.42},{"word":"And","start":182.84,"end":183.36},{"word":"at","start":183.36,"end":183.46},{"word":"the","start":183.46,"end":183.54},{"word":"same","start":183.54,"end":183.7},{"word":"time,","start":183.7,"end":183.94},{"word":"a","start":184.06,"end":184.12},{"word":"lot","start":184.12,"end":184.2},{"word":"of","start":184.2,"end":184.32},{"word":"other","start":184.32,"end":184.48},{"word":"people","start":184.48,"end":184.74},{"word":"were","start":184.74,"end":184.94},{"word":"detached","start":184.94,"end":185.42}],"textKo":"그래서 저는 고립되어 있었어요. 동시에 많은 다른 사람들도 고립되어 있었고","listenDifficulty":3},{"index":40,"start":186.26,"end":188.96,"textEn":"And isolated and fragmented from each other.","words":[{"word":"and","start":186.26,"end":186.78},{"word":"isolated","start":186.78,"end":187.3},{"word":"and","start":187.3,"end":187.84},{"word":"fragmented","start":187.84,"end":188.4},{"word":"from","start":188.4,"end":188.6},{"word":"each","start":188.6,"end":188.76},{"word":"other.","start":188.76,"end":188.96}],"textKo":"서로로부터 분리되고 단편화되어 있었어요.","listenDifficulty":2},{"index":41,"start":189.08,"end":191.72,"textEn":"Thirty-five percent of Americans over 45 are chronically lonely.","words":[{"word":"Thirty","start":189.08,"end":189.22},{"word":"-five","start":189.22,"end":189.44},{"word":"percent","start":189.44,"end":189.66},{"word":"of","start":189.66,"end":189.78},{"word":"Americans","start":189.78,"end":190.14},{"word":"over","start":190.14,"end":190.42},{"word":"45","start":190.42,"end":190.84},{"word":"are","start":190.84,"end":191.02},{"word":"chronically","start":191.02,"end":191.42},{"word":"lonely.","start":191.42,"end":191.72}],"textKo":"45세 이상 미국인의 35퍼센트가 만성적으로 외로워요.","listenDifficulty":3},{"index":42,"start":192.16,"end":194.2,"textEn":"Only eight percent of Americans report","words":[{"word":"Only","start":192.16,"end":192.42},{"word":"eight","start":192.42,"end":192.6},{"word":"percent","start":192.6,"end":192.88},{"word":"of","start":192.88,"end":193.0},{"word":"Americans","start":193.0,"end":193.46},{"word":"report","start":193.46,"end":194.2}],"textKo":"미국인의 8퍼센트만이","listenDifficulty":1},{"index":43,"start":194.2,"end":199.16,"textEn":"Having meaningful conversations with their neighbors. Only 32 percent of Americans say they trust their neighbors,","words":[{"word":"having","start":194.2,"end":194.5},{"word":"meaningful","start":194.5,"end":194.9},{"word":"conversations","start":194.9,"end":195.38},{"word":"with","start":195.38,"end":195.68},{"word":"their","start":195.68,"end":195.8},{"word":"neighbors.","start":195.8,"end":196.06},{"word":"Only","start":196.6,"end":196.82},{"word":"32","start":196.82,"end":197.2},{"word":"percent","start":197.2,"end":197.5},{"word":"of","start":197.5,"end":197.64},{"word":"Americans","start":197.64,"end":197.96},{"word":"say","start":197.96,"end":198.2},{"word":"they","start":198.2,"end":198.34},{"word":"trust","start":198.34,"end":198.66},{"word":"their","start":198.66,"end":198.84},{"word":"neighbors,","start":198.84,"end":199.16}],"textKo":"이웃과 의미 있는 대화를 한다고 보고해요. 미국인의 32퍼센트만 이웃을 신뢰한다고 말하고","listenDifficulty":1},{"index":44,"start":199.32,"end":203.68,"textEn":"And only 18 percent are millennials. The fastest-growing political party is unaffiliated,","words":[{"word":"and","start":199.32,"end":199.58},{"word":"only","start":199.58,"end":199.76},{"word":"18","start":199.76,"end":200.08},{"word":"percent","start":200.08,"end":200.34},{"word":"are","start":200.34,"end":200.48},{"word":"millennials.","start":200.48,"end":200.68},{"word":"The","start":201.44,"end":201.96},{"word":"fastest","start":201.96,"end":202.24},{"word":"-growing","start":202.24,"end":202.46},{"word":"political","start":202.46,"end":202.78},{"word":"party","start":202.78,"end":203.08},{"word":"is","start":203.08,"end":203.2},{"word":"unaffiliated,","start":203.2,"end":203.68}],"textKo":"밀레니얼 세대 중에서는 18퍼센트뿐이에요. 가장 빠르게 성장하는 정당은 무소속이고","listenDifficulty":2},{"index":45,"start":203.78,"end":205.88,"textEn":"The fastest-growing religious movement is unaffiliated,","words":[{"word":"the","start":203.78,"end":203.84},{"word":"fastest","start":203.84,"end":204.06},{"word":"-growing","start":204.06,"end":204.3},{"word":"religious","start":204.3,"end":204.8},{"word":"movement","start":204.8,"end":205.12},{"word":"is","start":205.12,"end":205.26},{"word":"unaffiliated,","start":205.26,"end":205.88}],"textKo":"가장 빠르게 성장하는 종교 운동도 무소속이에요.","listenDifficulty":1},{"index":46,"start":206.08,"end":209.1,"textEn":"Depression rates are rising, mental health problems are rising.","words":[{"word":"depression","start":206.08,"end":206.7},{"word":"rates","start":206.7,"end":207.04},{"word":"are","start":207.04,"end":207.22},{"word":"rising,","start":207.22,"end":207.6},{"word":"mental","start":207.78,"end":207.96},{"word":"health","start":207.96,"end":208.18},{"word":"problems","start":208.18,"end":208.52},{"word":"are","start":208.52,"end":208.68},{"word":"rising.","start":208.68,"end":209.1}],"textKo":"우울증 비율이 증가하고 있고, 정신 건강 문제가 늘어나고 있어요.","listenDifficulty":1},{"index":47,"start":209.68,"end":212.22,"textEn":"The suicide rate has risen 30 percent since 1999.","words":[{"word":"The","start":209.68,"end":209.8},{"word":"suicide","start":209.8,"end":210.1},{"word":"rate","start":210.1,"end":210.4},{"word":"has","start":210.4,"end":210.58},{"word":"risen","start":210.58,"end":210.88},{"word":"30","start":210.88,"end":211.14},{"word":"percent","start":211.14,"end":211.42},{"word":"since","start":211.42,"end":211.7},{"word":"1999.","start":211.7,"end":212.22}],"textKo":"자살률이 1999년 이후 30퍼센트 상승했어요.","listenDifficulty":2},{"index":48,"start":213.18,"end":217.78,"textEn":"For teen suicides over the last several years, the suicide rate has risen by 70 percent.","words":[{"word":"For","start":213.18,"end":213.36},{"word":"teen","start":213.36,"end":213.56},{"word":"suicides","start":213.56,"end":214.06},{"word":"over","start":214.06,"end":214.2},{"word":"the","start":214.2,"end":214.3},{"word":"last","start":214.3,"end":214.46},{"word":"several","start":214.46,"end":214.68},{"word":"years,","start":214.68,"end":215.0},{"word":"the","start":215.3,"end":215.38},{"word":"suicide","start":215.38,"end":215.7},{"word":"rate","start":215.7,"end":216.02},{"word":"has","start":216.02,"end":216.46},{"word":"risen","start":216.46,"end":216.76},{"word":"by","start":216.76,"end":216.94},{"word":"70","start":216.94,"end":217.4},{"word":"percent.","start":217.4,"end":217.78}],"textKo":"지난 몇 년간 10대 자살의 경우, 자살률이 70퍼센트 상승했어요.","listenDifficulty":2},{"index":49,"start":218.96,"end":221.52,"textEn":"Forty-five thousand Americans kill themselves every year.","words":[{"word":"Forty","start":218.96,"end":219.56},{"word":"-five","start":219.56,"end":219.68},{"word":"thousand","start":219.68,"end":219.94},{"word":"Americans","start":219.94,"end":220.32},{"word":"kill","start":220.32,"end":220.6},{"word":"themselves","start":220.6,"end":220.86},{"word":"every","start":220.86,"end":221.18},{"word":"year.","start":221.18,"end":221.52}],"textKo":"매년 4만 5천 명의 미국인이 스스로 목숨을 끊어요.","listenDifficulty":1},{"index":50,"start":221.94,"end":227.1,"textEn":"Seventy-two thousand die from opiate addictions. Life expectancy is falling, not rising.","words":[{"word":"Seventy","start":221.94,"end":222.26},{"word":"-two","start":222.26,"end":222.42},{"word":"thousand","start":222.42,"end":222.72},{"word":"die","start":222.72,"end":222.96},{"word":"from","start":222.96,"end":223.16},{"word":"opiate","start":223.16,"end":223.46},{"word":"addictions.","start":223.46,"end":223.9},{"word":"Life","start":224.16,"end":224.44},{"word":"expectancy","start":224.44,"end":224.92},{"word":"is","start":224.92,"end":225.62},{"word":"falling,","start":225.62,"end":226.08},{"word":"not","start":226.34,"end":226.64},{"word":"rising.","start":226.64,"end":227.1}],"textKo":"7만 2천 명이 아편류 중독으로 사망해요. 기대 수명이 늘지 않고 줄어들고 있어요.","listenDifficulty":1},{"index":51,"start":228.82,"end":232.66,"textEn":"So what do I mean to tell you? I came here, I flew out here to say that we have an economic crisis,","words":[{"word":"So","start":228.82,"end":229.14},{"word":"what","start":229.14,"end":229.28},{"word":"do","start":229.28,"end":229.4},{"word":"I","start":229.4,"end":229.42},{"word":"mean","start":229.42,"end":229.56},{"word":"to","start":229.56,"end":229.7},{"word":"tell","start":229.7,"end":229.86},{"word":"you?","start":229.86,"end":229.96},{"word":"I","start":230.04,"end":230.08},{"word":"came","start":230.08,"end":230.26},{"word":"here,","start":230.26,"end":230.42},{"word":"I","start":230.48,"end":230.52},{"word":"flew","start":230.52,"end":230.68},{"word":"out","start":230.68,"end":230.84},{"word":"here","start":230.84,"end":230.96},{"word":"to","start":230.96,"end":231.08},{"word":"say","start":231.08,"end":231.36},{"word":"that","start":231.36,"end":231.7},{"word":"we","start":231.7,"end":231.78},{"word":"have","start":231.78,"end":231.88},{"word":"an","start":231.88,"end":231.98},{"word":"economic","start":231.98,"end":232.3},{"word":"crisis,","start":232.3,"end":232.66}],"textKo":"그래서 제가 무슨 말을 하려는 거냐면요? 저는 여기에, 여기까지 날아와서 경제적 위기가 있다고 말하려고 왔어요.","listenDifficulty":3},{"index":52,"start":232.82,"end":237.62,"textEn":"We have an environmental crisis, we have a political crisis. We also have a social and relational crisis.","words":[{"word":"we","start":232.82,"end":232.84},{"word":"have","start":232.84,"end":232.9},{"word":"an","start":232.9,"end":232.96},{"word":"environmental","start":232.96,"end":233.22},{"word":"crisis,","start":233.22,"end":233.58},{"word":"we","start":233.74,"end":233.76},{"word":"have","start":233.76,"end":233.84},{"word":"a","start":233.84,"end":233.86},{"word":"political","start":233.86,"end":234.06},{"word":"crisis.","start":234.06,"end":234.6},{"word":"We","start":234.9,"end":235.22},{"word":"also","start":235.22,"end":235.4},{"word":"have","start":235.4,"end":235.54},{"word":"a","start":235.54,"end":235.64},{"word":"social","start":235.64,"end":236.0},{"word":"and","start":236.0,"end":236.58},{"word":"relational","start":236.58,"end":237.12},{"word":"crisis.","start":237.12,"end":237.62}],"textKo":"환경 위기가 있고, 정치적 위기가 있어요. 사회적, 관계적 위기도 있어요.","listenDifficulty":2},{"index":53,"start":237.64,"end":240.64,"textEn":"We''re in the valley. We''re fragmented from each other,","words":[{"word":"We''re","start":237.64,"end":237.9},{"word":"in","start":237.9,"end":238.06},{"word":"the","start":238.06,"end":238.18},{"word":"valley.","start":238.18,"end":238.5},{"word":"We''re","start":239.28,"end":239.64},{"word":"fragmented","start":239.64,"end":240.0},{"word":"from","start":240.0,"end":240.22},{"word":"each","start":240.22,"end":240.4},{"word":"other,","start":240.4,"end":240.64}],"textKo":"우리는 골짜기에 있어요. 서로로부터 분리되어 있고","listenDifficulty":1},{"index":54,"start":240.82,"end":243.14,"textEn":"We''ve got cascades of lies coming out of Washington,","words":[{"word":"we''ve","start":240.82,"end":241.16},{"word":"got","start":241.16,"end":241.28},{"word":"cascades","start":241.28,"end":241.86},{"word":"of","start":241.86,"end":241.98},{"word":"lies","start":241.98,"end":242.24},{"word":"coming","start":242.24,"end":242.52},{"word":"out","start":242.52,"end":242.66},{"word":"of","start":242.66,"end":242.74},{"word":"Washington,","start":242.74,"end":243.14}],"textKo":"워싱턴에서 거짓말의 연쇄가 쏟아지고 있어요.","listenDifficulty":3},{"index":55,"start":243.32,"end":246.84,"textEn":"We''re in the valley. And so I''ve spent the last five years,","words":[{"word":"we''re","start":243.32,"end":243.54},{"word":"in","start":243.54,"end":243.64},{"word":"the","start":243.64,"end":243.7},{"word":"valley.","start":243.7,"end":243.98},{"word":"And","start":245.24,"end":245.6},{"word":"so","start":245.6,"end":245.7},{"word":"I''ve","start":245.7,"end":245.86},{"word":"spent","start":245.86,"end":246.02},{"word":"the","start":246.02,"end":246.16},{"word":"last","start":246.16,"end":246.34},{"word":"five","start":246.34,"end":246.54},{"word":"years,","start":246.54,"end":246.84}],"textKo":"우리는 골짜기에 있어요. 그래서 저는 지난 5년간","listenDifficulty":2},{"index":56,"start":246.86,"end":250.26,"textEn":"How do you get out of a valley? And the Greeks used to say,","words":[{"word":"how","start":246.86,"end":247.32},{"word":"do","start":247.32,"end":247.44},{"word":"you","start":247.44,"end":247.48},{"word":"get","start":247.48,"end":247.58},{"word":"out","start":247.58,"end":247.68},{"word":"of","start":247.68,"end":247.78},{"word":"a","start":247.78,"end":247.88},{"word":"valley?","start":247.88,"end":248.2},{"word":"And","start":249.12,"end":249.48},{"word":"the","start":249.48,"end":249.58},{"word":"Greeks","start":249.58,"end":249.78},{"word":"used","start":249.78,"end":249.98},{"word":"to","start":249.98,"end":250.1},{"word":"say,","start":250.1,"end":250.26}],"textKo":"골짜기에서 어떻게 빠져나오는지를 고민했어요. 그리스인들은 이렇게 말하곤 했어요.","listenDifficulty":2},{"index":57,"start":250.36,"end":254.64,"textEn":"You suffer your way to wisdom. And from that dark period where I started,","words":[{"word":"you","start":250.36,"end":250.4},{"word":"suffer","start":250.4,"end":250.68},{"word":"your","start":250.68,"end":250.86},{"word":"way","start":250.86,"end":251.02},{"word":"to","start":251.02,"end":251.14},{"word":"wisdom.","start":251.14,"end":251.7},{"word":"And","start":252.66,"end":253.14},{"word":"from","start":253.14,"end":253.32},{"word":"that","start":253.32,"end":253.48},{"word":"dark","start":253.48,"end":253.72},{"word":"period","start":253.72,"end":254.1},{"word":"where","start":254.1,"end":254.28},{"word":"I","start":254.28,"end":254.36},{"word":"started,","start":254.36,"end":254.64}],"textKo":"고통을 통해 지혜에 이른다고요. 그리고 제가 시작한 그 어두운 시기로부터","listenDifficulty":1},{"index":58,"start":254.78,"end":259.78,"textEn":"I''ve had a few realizations. The first is, freedom sucks.","words":[{"word":"I''ve","start":254.78,"end":254.96},{"word":"had","start":254.96,"end":255.06},{"word":"a","start":255.06,"end":255.16},{"word":"few","start":255.16,"end":255.36},{"word":"realizations.","start":255.36,"end":256.04},{"word":"The","start":256.92,"end":257.4},{"word":"first","start":257.4,"end":257.74},{"word":"is,","start":257.74,"end":258.2},{"word":"freedom","start":258.42,"end":259.22},{"word":"sucks.","start":259.22,"end":259.78}],"textKo":"몇 가지 깨달음을 얻었어요. 첫 번째는, 자유는 별로예요.","listenDifficulty":1},{"index":59,"start":260.9,"end":263.24,"textEn":"Economic freedom is OK, political freedom is great,","words":[{"word":"Economic","start":260.9,"end":261.38},{"word":"freedom","start":261.38,"end":261.64},{"word":"is","start":261.64,"end":261.8},{"word":"OK,","start":261.8,"end":262.0},{"word":"political","start":262.24,"end":262.54},{"word":"freedom","start":262.54,"end":262.82},{"word":"is","start":262.82,"end":262.96},{"word":"great,","start":262.96,"end":263.24}],"textKo":"경제적 자유는 괜찮고, 정치적 자유는 훌륭하지만","listenDifficulty":2},{"index":60,"start":263.56,"end":268.04,"textEn":"Social freedom sucks. The unrooted man is the adrift man,","words":[{"word":"social","start":263.56,"end":264.04},{"word":"freedom","start":264.04,"end":264.46},{"word":"sucks.","start":264.46,"end":265.08},{"word":"The","start":265.74,"end":266.22},{"word":"unrooted","start":266.22,"end":266.62},{"word":"man","start":266.62,"end":266.92},{"word":"is","start":266.92,"end":267.18},{"word":"the","start":267.18,"end":267.32},{"word":"adrift","start":267.32,"end":267.66},{"word":"man,","start":267.66,"end":268.04}],"textKo":"사회적 자유는 별로예요. 뿌리 없는 사람은 떠도는 사람이에요.","listenDifficulty":1},{"index":61,"start":268.28,"end":270.4,"textEn":"The unrooted man is the unremembered man","words":[{"word":"the","start":268.28,"end":268.5},{"word":"unrooted","start":268.5,"end":268.88},{"word":"man","start":268.88,"end":269.12},{"word":"is","start":269.12,"end":269.3},{"word":"the","start":269.3,"end":269.44},{"word":"unremembered","start":269.44,"end":270.18},{"word":"man","start":270.18,"end":270.4}],"textKo":"뿌리 없는 사람은 기억되지 않는 사람이에요.","listenDifficulty":1},{"index":62,"start":270.4,"end":274.38,"textEn":"Because he''s uncommitted to things. Freedom is not a river,","words":[{"word":"because","start":270.4,"end":270.64},{"word":"he''s","start":270.64,"end":270.9},{"word":"uncommitted","start":270.9,"end":271.34},{"word":"to","start":271.34,"end":271.5},{"word":"things.","start":271.5,"end":271.88},{"word":"Freedom","start":272.78,"end":273.12},{"word":"is","start":273.12,"end":273.26},{"word":"not","start":273.26,"end":273.4},{"word":"a","start":273.4,"end":274.14},{"word":"river,","start":274.14,"end":274.38}],"textKo":"왜냐하면 아무것에도 헌신하지 않기 때문이에요. 자유는 강이 아니에요.","listenDifficulty":1},{"index":63,"start":274.6,"end":277.72,"textEn":"It''s not an ocean you want to swim in, it''s a river you want to get across,","words":[{"word":"it''s","start":274.6,"end":274.9},{"word":"not","start":274.9,"end":275.04},{"word":"an","start":275.04,"end":275.18},{"word":"ocean","start":275.18,"end":275.4},{"word":"you","start":275.4,"end":275.52},{"word":"want","start":275.52,"end":275.62},{"word":"to","start":275.62,"end":275.7},{"word":"swim","start":275.7,"end":275.9},{"word":"in,","start":275.9,"end":276.12},{"word":"it''s","start":276.28,"end":276.52},{"word":"a","start":276.52,"end":276.6},{"word":"river","start":276.6,"end":276.78},{"word":"you","start":276.78,"end":276.92},{"word":"want","start":276.92,"end":277.06},{"word":"to","start":277.06,"end":277.16},{"word":"get","start":277.16,"end":277.28},{"word":"across,","start":277.28,"end":277.72}],"textKo":"헤엄치고 싶은 바다가 아니에요. 건너고 싶은 강이에요.","listenDifficulty":3},{"index":64,"start":277.9,"end":280.16,"textEn":"So you can commit and plant yourself on the other side.","words":[{"word":"so","start":277.9,"end":278.18},{"word":"you","start":278.18,"end":278.28},{"word":"can","start":278.28,"end":278.4},{"word":"commit","start":278.4,"end":278.72},{"word":"and","start":278.72,"end":278.94},{"word":"plant","start":278.94,"end":279.18},{"word":"yourself","start":279.18,"end":279.46},{"word":"on","start":279.46,"end":279.64},{"word":"the","start":279.64,"end":279.72},{"word":"other","start":279.72,"end":279.84},{"word":"side.","start":279.84,"end":280.16}],"textKo":"건너서 반대편에 헌신하고 뿌리내리기 위해서요.","listenDifficulty":3},{"index":65,"start":280.94,"end":284.64,"textEn":"The second thing I learned is that when you have one of those bad moments in life,","words":[{"word":"The","start":280.94,"end":281.38},{"word":"second","start":281.38,"end":281.62},{"word":"thing","start":281.62,"end":281.86},{"word":"I","start":281.86,"end":282.02},{"word":"learned","start":282.02,"end":282.32},{"word":"is","start":282.32,"end":283.08},{"word":"that","start":283.08,"end":283.16},{"word":"when","start":283.16,"end":283.24},{"word":"you","start":283.24,"end":283.32},{"word":"have","start":283.32,"end":283.44},{"word":"one","start":283.44,"end":283.58},{"word":"of","start":283.58,"end":283.62},{"word":"those","start":283.62,"end":283.74},{"word":"bad","start":283.74,"end":283.94},{"word":"moments","start":283.94,"end":284.28},{"word":"in","start":284.28,"end":284.42},{"word":"life,","start":284.42,"end":284.64}],"textKo":"두 번째로 배운 것은, 삶에서 힘든 순간을 맞닥뜨릴 때","listenDifficulty":3},{"index":66,"start":284.94,"end":287.96,"textEn":"You can either be broken or you can be broken open.","words":[{"word":"you","start":284.94,"end":285.36},{"word":"can","start":285.36,"end":285.54},{"word":"either","start":285.54,"end":285.78},{"word":"be","start":285.78,"end":285.98},{"word":"broken","start":285.98,"end":286.38},{"word":"or","start":286.38,"end":286.98},{"word":"you","start":286.98,"end":287.1},{"word":"can","start":287.1,"end":287.24},{"word":"be","start":287.24,"end":287.36},{"word":"broken","start":287.36,"end":287.64},{"word":"open.","start":287.64,"end":287.96}],"textKo":"부서질 수도 있고 부서져서 열릴 수도 있다는 거예요.","listenDifficulty":3},{"index":67,"start":288.58,"end":291.62,"textEn":"And we all know people who are broken, they''ve endured some pain or grief,","words":[{"word":"And","start":288.58,"end":289.02},{"word":"we","start":289.02,"end":289.14},{"word":"all","start":289.14,"end":289.24},{"word":"know","start":289.24,"end":289.38},{"word":"people","start":289.38,"end":289.62},{"word":"who","start":289.62,"end":289.76},{"word":"are","start":289.76,"end":289.84},{"word":"broken,","start":289.84,"end":290.16},{"word":"they''ve","start":290.34,"end":290.58},{"word":"endured","start":290.58,"end":290.82},{"word":"some","start":290.82,"end":291.04},{"word":"pain","start":291.04,"end":291.24},{"word":"or","start":291.24,"end":291.36},{"word":"grief,","start":291.36,"end":291.62}],"textKo":"우리 모두 부서진 사람들을 알아요. 어떤 고통이나 슬픔을 겪고","listenDifficulty":3},{"index":68,"start":291.7,"end":294.22,"textEn":"They get smaller, they get angry or resentful,","words":[{"word":"they","start":291.7,"end":291.78},{"word":"get","start":291.78,"end":291.9},{"word":"smaller,","start":291.9,"end":292.36},{"word":"they","start":293.02,"end":293.06},{"word":"get","start":293.06,"end":293.24},{"word":"angry","start":293.24,"end":293.58},{"word":"or","start":293.58,"end":293.74},{"word":"resentful,","start":293.74,"end":294.22}],"textKo":"더 작아지고, 화내거나 원망하게 되는 사람들이요.","listenDifficulty":1},{"index":69,"start":294.3,"end":296.56,"textEn":"They lash out. As the saying is,","words":[{"word":"they","start":294.3,"end":294.4},{"word":"lash","start":294.4,"end":294.74},{"word":"out.","start":294.74,"end":295.06},{"word":"As","start":295.66,"end":295.88},{"word":"the","start":295.88,"end":295.98},{"word":"saying","start":295.98,"end":296.26},{"word":"is,","start":296.26,"end":296.56}],"textKo":"공격적으로 변하죠. 이런 말이 있어요.","listenDifficulty":2},{"index":70,"start":296.74,"end":298.9,"textEn":"Pain that is not transformed gets transmitted.","words":[{"word":"pain","start":296.74,"end":297.06},{"word":"that","start":297.06,"end":297.22},{"word":"is","start":297.22,"end":297.36},{"word":"not","start":297.36,"end":297.5},{"word":"transformed","start":297.5,"end":298.12},{"word":"gets","start":298.12,"end":298.36},{"word":"transmitted.","start":298.36,"end":298.9}],"textKo":"변환되지 않은 고통은 전달된다고요.","listenDifficulty":1},{"index":71,"start":299.6,"end":305.7,"textEn":"But other people are broken open. Suffering''s great power is that it''s an interruption of life.","words":[{"word":"But","start":299.6,"end":300.04},{"word":"other","start":300.04,"end":300.22},{"word":"people","start":300.22,"end":300.46},{"word":"are","start":300.46,"end":300.6},{"word":"broken","start":300.6,"end":300.88},{"word":"open.","start":300.88,"end":301.2},{"word":"Suffering''s","start":303.18,"end":303.62},{"word":"great","start":303.62,"end":303.78},{"word":"power","start":303.78,"end":304.16},{"word":"is","start":304.16,"end":304.4},{"word":"that","start":304.4,"end":304.52},{"word":"it''s","start":304.52,"end":304.68},{"word":"an","start":304.68,"end":304.76},{"word":"interruption","start":304.76,"end":305.24},{"word":"of","start":305.24,"end":305.44},{"word":"life.","start":305.44,"end":305.7}],"textKo":"하지만 다른 사람들은 부서져서 열려요. 고통의 위대한 힘은 삶의 중단이라는 거예요.","listenDifficulty":1},{"index":72,"start":306.08,"end":308.4,"textEn":"It reminds you you''re not the person you thought you were.","words":[{"word":"It","start":306.08,"end":306.42},{"word":"reminds","start":306.42,"end":306.74},{"word":"you","start":306.74,"end":306.94},{"word":"you''re","start":306.94,"end":307.14},{"word":"not","start":307.14,"end":307.28},{"word":"the","start":307.28,"end":307.44},{"word":"person","start":307.44,"end":307.68},{"word":"you","start":307.68,"end":307.84},{"word":"thought","start":307.84,"end":308.02},{"word":"you","start":308.02,"end":308.2},{"word":"were.","start":308.2,"end":308.4}],"textKo":"자신이 생각했던 그런 사람이 아니라는 걸 일깨워 줘요.","listenDifficulty":3},{"index":73,"start":308.4,"end":312.48,"textEn":"It''s an interruption of life. The theologian Paul Tillich said, what suffering does is it carves through","words":[{"word":"It''s","start":308.4,"end":309.14},{"word":"an","start":309.14,"end":309.14},{"word":"interruption","start":309.14,"end":309.14},{"word":"of","start":309.14,"end":309.14},{"word":"life.","start":309.14,"end":309.14},{"word":"The","start":309.14,"end":309.14},{"word":"theologian","start":309.14,"end":309.62},{"word":"Paul","start":309.62,"end":309.82},{"word":"Tillich","start":309.82,"end":310.14},{"word":"said,","start":310.14,"end":310.34},{"word":"what","start":310.48,"end":310.48},{"word":"suffering","start":310.48,"end":310.82},{"word":"does","start":310.82,"end":311.12},{"word":"is","start":311.12,"end":311.84},{"word":"it","start":311.84,"end":311.98},{"word":"carves","start":311.98,"end":312.3},{"word":"through","start":312.3,"end":312.48}],"textKo":"삶의 중단이에요. 신학자 폴 틸리히는 이렇게 말했어요. 고통이 하는 일은","listenDifficulty":2},{"index":74,"start":312.48,"end":315.16,"textEn":"What you thought was the floor of the basement of your soul,","words":[{"word":"what","start":312.48,"end":312.98},{"word":"you","start":312.98,"end":313.12},{"word":"thought","start":313.12,"end":313.34},{"word":"was","start":313.34,"end":313.52},{"word":"the","start":313.52,"end":313.66},{"word":"floor","start":313.66,"end":313.94},{"word":"of","start":313.94,"end":314.1},{"word":"the","start":314.1,"end":314.2},{"word":"basement","start":314.2,"end":314.52},{"word":"of","start":314.52,"end":314.7},{"word":"your","start":314.7,"end":314.82},{"word":"soul,","start":314.82,"end":315.16}],"textKo":"당신 영혼의 지하실 바닥이라고 생각했던 곳을 뚫고 파내려 가는 거예요.","listenDifficulty":3},{"index":75,"start":315.34,"end":317.5,"textEn":"And it carves through that, revealing a cavity below,","words":[{"word":"and","start":315.34,"end":315.54},{"word":"it","start":315.54,"end":315.64},{"word":"carves","start":315.64,"end":315.94},{"word":"through","start":315.94,"end":316.08},{"word":"that,","start":316.08,"end":316.3},{"word":"revealing","start":316.4,"end":316.7},{"word":"a","start":316.7,"end":316.88},{"word":"cavity","start":316.88,"end":317.18},{"word":"below,","start":317.18,"end":317.5}],"textKo":"그것을 뚫고 아래에 또 다른 공간을 드러내요.","listenDifficulty":2},{"index":76,"start":317.74,"end":319.74,"textEn":"And it carves through that, revealing a cavity below.","words":[{"word":"and","start":317.74,"end":317.96},{"word":"it","start":317.96,"end":318.06},{"word":"carves","start":318.06,"end":318.3},{"word":"through","start":318.3,"end":318.42},{"word":"that,","start":318.42,"end":318.6},{"word":"revealing","start":318.66,"end":318.94},{"word":"a","start":318.94,"end":319.12},{"word":"cavity","start":319.12,"end":319.44},{"word":"below.","start":319.44,"end":319.74}],"textKo":"그것을 뚫고 아래에 또 다른 공간을 드러내요.","listenDifficulty":3},{"index":77,"start":320.18,"end":322.88,"textEn":"You realize there are depths of yourself you never anticipated,","words":[{"word":"You","start":320.18,"end":320.52},{"word":"realize","start":320.52,"end":320.8},{"word":"there","start":320.8,"end":320.98},{"word":"are","start":320.98,"end":321.08},{"word":"depths","start":321.08,"end":321.32},{"word":"of","start":321.32,"end":321.54},{"word":"yourself","start":321.54,"end":321.84},{"word":"you","start":321.84,"end":322.04},{"word":"never","start":322.04,"end":322.28},{"word":"anticipated,","start":322.28,"end":322.88}],"textKo":"자신도 예상하지 못했던 깊이가 있다는 것을 깨닫게 돼요.","listenDifficulty":2},{"index":78,"start":323.18,"end":325.9,"textEn":"And only spiritual and relational food will fill those depths.","words":[{"word":"and","start":323.18,"end":323.4},{"word":"only","start":323.4,"end":323.68},{"word":"spiritual","start":323.68,"end":324.14},{"word":"and","start":324.14,"end":324.42},{"word":"relational","start":324.42,"end":324.78},{"word":"food","start":324.78,"end":325.06},{"word":"will","start":325.06,"end":325.26},{"word":"fill","start":325.26,"end":325.44},{"word":"those","start":325.44,"end":325.64},{"word":"depths.","start":325.64,"end":325.9}],"textKo":"그리고 영적이고 관계적인 양식만이 그 깊이를 채울 수 있어요.","listenDifficulty":2},{"index":79,"start":327.9,"end":330.16,"textEn":"And when you get down there, you get out of the head of the ego,","words":[{"word":"And","start":327.9,"end":328.3},{"word":"when","start":328.3,"end":328.4},{"word":"you","start":328.4,"end":328.48},{"word":"get","start":328.48,"end":328.6},{"word":"down","start":328.6,"end":328.78},{"word":"there,","start":328.78,"end":328.92},{"word":"you","start":329.02,"end":329.06},{"word":"get","start":329.06,"end":329.2},{"word":"out","start":329.2,"end":329.36},{"word":"of","start":329.36,"end":329.44},{"word":"the","start":329.44,"end":329.54},{"word":"head","start":329.54,"end":329.66},{"word":"of","start":329.66,"end":329.78},{"word":"the","start":329.78,"end":329.88},{"word":"ego,","start":329.88,"end":330.16}],"textKo":"거기까지 내려가면, 자아의 머리에서 벗어나","listenDifficulty":3},{"index":80,"start":330.36,"end":333.76,"textEn":"And you get into the heart, the desiring heart,","words":[{"word":"and","start":330.36,"end":330.7},{"word":"you","start":330.7,"end":330.78},{"word":"get","start":330.78,"end":330.92},{"word":"into","start":330.92,"end":331.12},{"word":"the","start":331.12,"end":331.24},{"word":"heart,","start":331.24,"end":331.46},{"word":"the","start":332.54,"end":332.98},{"word":"desiring","start":332.98,"end":333.42},{"word":"heart,","start":333.42,"end":333.76}],"textKo":"마음으로, 갈망하는 마음으로 들어가게 돼요.","listenDifficulty":1},{"index":81,"start":334.4,"end":337.94,"textEn":"The idea that what we really yearn for is longing and love for another,","words":[{"word":"the","start":334.4,"end":334.84},{"word":"idea","start":334.84,"end":335.2},{"word":"that","start":335.2,"end":335.4},{"word":"what","start":335.4,"end":335.58},{"word":"we","start":335.58,"end":335.74},{"word":"really","start":335.74,"end":336.06},{"word":"yearn","start":336.06,"end":336.3},{"word":"for","start":336.3,"end":336.44},{"word":"is","start":336.44,"end":336.62},{"word":"longing","start":336.62,"end":337.0},{"word":"and","start":337.0,"end":337.28},{"word":"love","start":337.28,"end":337.48},{"word":"for","start":337.48,"end":337.66},{"word":"another,","start":337.66,"end":337.94}],"textKo":"우리가 진정으로 갈망하는 것은 다른 사람에 대한 그리움과 사랑이라는 생각이에요.","listenDifficulty":2},{"index":82,"start":338.24,"end":341.16,"textEn":"The kind of thing that Louis de Bernier described in his book","words":[{"word":"the","start":338.24,"end":338.42},{"word":"kind","start":338.42,"end":338.6},{"word":"of","start":338.6,"end":338.74},{"word":"thing","start":338.74,"end":338.96},{"word":"that","start":338.96,"end":339.18},{"word":"Louis","start":339.18,"end":339.48},{"word":"de","start":339.48,"end":339.64},{"word":"Bernier","start":339.64,"end":340.0},{"word":"described","start":340.0,"end":340.4},{"word":"in","start":340.4,"end":340.78},{"word":"his","start":340.78,"end":340.96},{"word":"book","start":340.96,"end":341.16}],"textKo":"루이 드 베르니에르가 그의 책에서 묘사한 그런 종류의 것이요.","listenDifficulty":2},{"index":83,"start":341.16,"end":346.56,"textEn":"Captain Corelli''s Mandolin. He had an old guy talking to his daughter about his relationship with his late wife,","words":[{"word":"Captain","start":341.16,"end":341.46},{"word":"Corelli''s","start":341.46,"end":342.28},{"word":"Mandolin.","start":342.28,"end":342.7},{"word":"He","start":343.18,"end":343.4},{"word":"had","start":343.4,"end":343.48},{"word":"an","start":343.48,"end":343.56},{"word":"old","start":343.56,"end":343.66},{"word":"guy","start":343.66,"end":343.84},{"word":"talking","start":343.84,"end":344.14},{"word":"to","start":344.14,"end":344.36},{"word":"his","start":344.36,"end":344.58},{"word":"daughter","start":344.58,"end":344.8},{"word":"about","start":344.8,"end":345.02},{"word":"his","start":345.02,"end":345.16},{"word":"relationship","start":345.16,"end":345.62},{"word":"with","start":345.62,"end":345.82},{"word":"his","start":345.82,"end":345.96},{"word":"late","start":345.96,"end":346.18},{"word":"wife,","start":346.18,"end":346.56}],"textKo":"코렐리 대위의 만돌린이라는 책에서요. 한 노인이 딸에게 돌아가신 아내와의 관계에 대해 이야기해요.","listenDifficulty":2},{"index":84,"start":346.76,"end":351.74,"textEn":"And the old guy says, love itself is whatever is left over when being in love is burned away,","words":[{"word":"and","start":346.76,"end":347.3},{"word":"the","start":347.3,"end":347.4},{"word":"old","start":347.4,"end":347.54},{"word":"guy","start":347.54,"end":347.72},{"word":"says,","start":347.72,"end":348.18},{"word":"love","start":348.18,"end":348.92},{"word":"itself","start":348.92,"end":349.28},{"word":"is","start":349.28,"end":349.5},{"word":"whatever","start":349.5,"end":349.7},{"word":"is","start":349.7,"end":349.98},{"word":"left","start":349.98,"end":350.14},{"word":"over","start":350.14,"end":350.38},{"word":"when","start":350.38,"end":350.58},{"word":"being","start":350.58,"end":350.78},{"word":"in","start":350.78,"end":350.94},{"word":"love","start":350.94,"end":351.1},{"word":"is","start":351.1,"end":351.24},{"word":"burned","start":351.24,"end":351.44},{"word":"away,","start":351.44,"end":351.74}],"textKo":"노인은 말해요. 사랑 그 자체는 사랑에 빠진 감정이 다 타버린 후 남은 것이라고","listenDifficulty":2},{"index":85,"start":352.22,"end":354.98,"textEn":"And this book is both an art and a fortunate accident.","words":[{"word":"and","start":352.22,"end":352.62},{"word":"this","start":352.62,"end":352.78},{"word":"book","start":352.78,"end":353.0},{"word":"is","start":353.0,"end":353.26},{"word":"both","start":353.26,"end":353.44},{"word":"an","start":353.44,"end":353.62},{"word":"art","start":353.62,"end":353.84},{"word":"and","start":353.84,"end":354.0},{"word":"a","start":354.0,"end":354.1},{"word":"fortunate","start":354.1,"end":354.4},{"word":"accident.","start":354.4,"end":354.98}],"textKo":"이 책은 예술이자 행운의 우연이에요.","listenDifficulty":2},{"index":86,"start":355.46,"end":359.24,"textEn":"Your mother and I had it. We had roots that grew towards each other underground,","words":[{"word":"Your","start":355.46,"end":355.86},{"word":"mother","start":355.86,"end":356.04},{"word":"and","start":356.04,"end":356.2},{"word":"I","start":356.2,"end":356.3},{"word":"had","start":356.3,"end":356.54},{"word":"it.","start":356.54,"end":356.66},{"word":"We","start":357.14,"end":357.54},{"word":"had","start":357.54,"end":357.64},{"word":"roots","start":357.64,"end":357.88},{"word":"that","start":357.88,"end":358.04},{"word":"grew","start":358.04,"end":358.24},{"word":"towards","start":358.24,"end":358.5},{"word":"each","start":358.5,"end":358.66},{"word":"other","start":358.66,"end":358.82},{"word":"underground,","start":358.82,"end":359.24}],"textKo":"너희 어머니와 나는 그것을 가졌었단다. 우리는 땅 아래에서 서로를 향해 자라는 뿌리를 가졌어.","listenDifficulty":2},{"index":87,"start":359.7,"end":362.16,"textEn":"And when all the pretty blossoms had fallen from our branches,","words":[{"word":"and","start":359.7,"end":360.02},{"word":"when","start":360.02,"end":360.14},{"word":"all","start":360.14,"end":360.24},{"word":"the","start":360.24,"end":360.36},{"word":"pretty","start":360.36,"end":360.52},{"word":"blossoms","start":360.52,"end":360.96},{"word":"had","start":360.96,"end":361.18},{"word":"fallen","start":361.18,"end":361.42},{"word":"from","start":361.42,"end":361.62},{"word":"our","start":361.62,"end":361.76},{"word":"branches,","start":361.76,"end":362.16}],"textKo":"모든 예쁜 꽃잎이 가지에서 다 떨어졌을 때","listenDifficulty":3},{"index":88,"start":362.44,"end":364.78,"textEn":"We discovered that we are one tree and not two.","words":[{"word":"we","start":362.44,"end":362.76},{"word":"discovered","start":362.76,"end":363.14},{"word":"that","start":363.14,"end":363.34},{"word":"we","start":363.34,"end":363.48},{"word":"are","start":363.48,"end":363.56},{"word":"one","start":363.56,"end":363.78},{"word":"tree","start":363.78,"end":364.1},{"word":"and","start":364.1,"end":364.34},{"word":"not","start":364.34,"end":364.52},{"word":"two.","start":364.52,"end":364.78}],"textKo":"우리는 둘이 아니라 하나의 나무라는 것을 발견했단다.","listenDifficulty":2},{"index":89,"start":365.5,"end":369.82,"textEn":"That''s what the heart yearns for. The second thing you discover is your soul.","words":[{"word":"That''s","start":365.5,"end":365.9},{"word":"what","start":365.9,"end":366.0},{"word":"the","start":366.0,"end":366.1},{"word":"heart","start":366.1,"end":366.22},{"word":"yearns","start":366.22,"end":366.52},{"word":"for.","start":366.52,"end":366.72},{"word":"The","start":367.32,"end":367.72},{"word":"second","start":367.72,"end":367.94},{"word":"thing","start":367.94,"end":368.12},{"word":"you","start":368.12,"end":368.24},{"word":"discover","start":368.24,"end":368.64},{"word":"is","start":368.64,"end":369.38},{"word":"your","start":369.38,"end":369.54},{"word":"soul.","start":369.54,"end":369.82}],"textKo":"그것이 마음이 갈망하는 거예요. 두 번째로 발견하는 것은 영혼이에요.","listenDifficulty":1},{"index":90,"start":370.8,"end":372.86,"textEn":"Now, I don''t ask you to believe in God or not believe in God,","words":[{"word":"Now,","start":370.8,"end":371.02},{"word":"I","start":371.1,"end":371.12},{"word":"don''t","start":371.12,"end":371.24},{"word":"ask","start":371.24,"end":371.44},{"word":"you","start":371.44,"end":371.54},{"word":"to","start":371.54,"end":371.6},{"word":"believe","start":371.6,"end":371.74},{"word":"in","start":371.74,"end":371.84},{"word":"God","start":371.84,"end":371.98},{"word":"or","start":371.98,"end":372.1},{"word":"not","start":372.1,"end":372.24},{"word":"believe","start":372.24,"end":372.5},{"word":"in","start":372.5,"end":372.62},{"word":"God,","start":372.62,"end":372.86}],"textKo":"자, 신을 믿으라거나 믿지 말라고 부탁하는 게 아니에요.","listenDifficulty":3},{"index":91,"start":372.86,"end":377.14,"textEn":"But I do ask you to believe that there''s a piece of you that has no shape, size, color or weight,","words":[{"word":"but","start":372.86,"end":373.04},{"word":"I","start":373.04,"end":373.14},{"word":"do","start":373.14,"end":373.26},{"word":"ask","start":373.26,"end":373.46},{"word":"you","start":373.46,"end":373.58},{"word":"to","start":373.58,"end":373.66},{"word":"believe","start":373.66,"end":373.84},{"word":"that","start":373.84,"end":374.02},{"word":"there''s","start":374.02,"end":374.26},{"word":"a","start":374.26,"end":374.34},{"word":"piece","start":374.34,"end":374.58},{"word":"of","start":374.58,"end":374.7},{"word":"you","start":374.7,"end":374.82},{"word":"that","start":374.82,"end":374.98},{"word":"has","start":374.98,"end":375.12},{"word":"no","start":375.12,"end":375.28},{"word":"shape,","start":375.28,"end":375.6},{"word":"size,","start":375.78,"end":376.18},{"word":"color","start":376.36,"end":376.6},{"word":"or","start":376.6,"end":376.84},{"word":"weight,","start":376.84,"end":377.14}],"textKo":"하지만 당신 안에 모양도, 크기도, 색깔도, 무게도 없는 부분이 있다고 믿어 달라고 부탁해요.","listenDifficulty":3},{"index":92,"start":377.34,"end":380.72,"textEn":"But that gives you infinite dignity and value.","words":[{"word":"but","start":377.34,"end":377.72},{"word":"that","start":377.72,"end":377.88},{"word":"gives","start":377.88,"end":378.12},{"word":"you","start":378.12,"end":378.24},{"word":"infinite","start":378.24,"end":378.7},{"word":"dignity","start":378.7,"end":379.96},{"word":"and","start":379.96,"end":380.3},{"word":"value.","start":380.3,"end":380.72}],"textKo":"하지만 그것이 무한한 존엄성과 가치를 부여해 줘요.","listenDifficulty":1},{"index":93,"start":381.18,"end":384.28,"textEn":"Rich and successful people don''t have more of this than less successful people.","words":[{"word":"Rich","start":381.18,"end":381.58},{"word":"and","start":381.58,"end":381.7},{"word":"successful","start":381.7,"end":382.08},{"word":"people","start":382.08,"end":382.4},{"word":"don''t","start":382.4,"end":382.62},{"word":"have","start":382.62,"end":382.72},{"word":"more","start":382.72,"end":382.88},{"word":"of","start":382.88,"end":383.0},{"word":"this","start":383.0,"end":383.16},{"word":"than","start":383.16,"end":383.32},{"word":"less","start":383.32,"end":383.5},{"word":"successful","start":383.5,"end":383.92},{"word":"people.","start":383.92,"end":384.28}],"textKo":"부유하고 성공한 사람들이 덜 성공한 사람들보다 이것을 더 많이 가지고 있지는 않아요.","listenDifficulty":2},{"index":94,"start":385.96,"end":388.5,"textEn":"Slavery is wrong because it''s an obliteration of another soul.","words":[{"word":"Slavery","start":385.96,"end":386.4},{"word":"is","start":386.4,"end":386.58},{"word":"wrong","start":386.58,"end":386.82},{"word":"because","start":386.82,"end":387.1},{"word":"it''s","start":387.1,"end":387.32},{"word":"an","start":387.32,"end":387.4},{"word":"obliteration","start":387.4,"end":387.9},{"word":"of","start":387.9,"end":388.02},{"word":"another","start":388.02,"end":388.2},{"word":"soul.","start":388.2,"end":388.5}],"textKo":"노예제가 잘못된 것은 다른 사람의 영혼을 말살하는 것이기 때문이에요.","listenDifficulty":3},{"index":95,"start":389.06,"end":391.5,"textEn":"Rape is not just an attack on a bunch of physical molecules,","words":[{"word":"Rape","start":389.06,"end":389.4},{"word":"is","start":389.4,"end":389.54},{"word":"not","start":389.54,"end":389.66},{"word":"just","start":389.66,"end":389.84},{"word":"an","start":389.84,"end":389.98},{"word":"attack","start":389.98,"end":390.22},{"word":"on","start":390.22,"end":390.4},{"word":"a","start":390.4,"end":390.48},{"word":"bunch","start":390.48,"end":390.56},{"word":"of","start":390.56,"end":390.68},{"word":"physical","start":390.68,"end":390.98},{"word":"molecules,","start":390.98,"end":391.5}],"textKo":"강간은 단지 물리적 분자에 대한 공격이 아니에요.","listenDifficulty":3},{"index":96,"start":391.78,"end":394.08,"textEn":"It''s an attempt to insult another person''s soul.","words":[{"word":"it''s","start":391.78,"end":392.14},{"word":"an","start":392.14,"end":392.24},{"word":"attempt","start":392.24,"end":392.48},{"word":"to","start":392.48,"end":392.64},{"word":"insult","start":392.64,"end":393.0},{"word":"another","start":393.0,"end":393.34},{"word":"person''s","start":393.34,"end":393.82},{"word":"soul.","start":393.82,"end":394.08}],"textKo":"다른 사람의 영혼을 모욕하려는 시도예요.","listenDifficulty":2},{"index":97,"start":394.66,"end":397.24,"textEn":"And what the soul does is it yearns for righteousness.","words":[{"word":"And","start":394.66,"end":395.1},{"word":"what","start":395.1,"end":395.24},{"word":"the","start":395.24,"end":395.38},{"word":"soul","start":395.38,"end":395.6},{"word":"does","start":395.6,"end":395.86},{"word":"is","start":395.86,"end":396.04},{"word":"it","start":396.04,"end":396.2},{"word":"yearns","start":396.2,"end":396.6},{"word":"for","start":396.6,"end":396.78},{"word":"righteousness.","start":396.78,"end":397.24}],"textKo":"그리고 영혼이 하는 일은 올바름을 갈망하는 거예요.","listenDifficulty":3},{"index":98,"start":397.88,"end":400.76,"textEn":"The heart yearns for fusion with another, the soul yearns for righteousness.","words":[{"word":"The","start":397.88,"end":398.16},{"word":"heart","start":398.16,"end":398.34},{"word":"yearns","start":398.34,"end":398.66},{"word":"for","start":398.66,"end":398.78},{"word":"fusion","start":398.78,"end":399.06},{"word":"with","start":399.06,"end":399.26},{"word":"another,","start":399.26,"end":399.5},{"word":"the","start":399.62,"end":399.72},{"word":"soul","start":399.72,"end":399.94},{"word":"yearns","start":399.94,"end":400.22},{"word":"for","start":400.22,"end":400.36},{"word":"righteousness.","start":400.36,"end":400.76}],"textKo":"마음은 다른 사람과의 융합을 갈망하고, 영혼은 올바름을 갈망해요.","listenDifficulty":3},{"index":99,"start":401.36,"end":404.22,"textEn":"And that led to my third realization, which I borrowed from Einstein.","words":[{"word":"And","start":401.36,"end":401.76},{"word":"that","start":401.76,"end":401.92},{"word":"led","start":401.92,"end":402.12},{"word":"to","start":402.12,"end":402.24},{"word":"my","start":402.24,"end":402.4},{"word":"third","start":402.4,"end":402.6},{"word":"realization,","start":402.6,"end":403.08},{"word":"which","start":403.26,"end":403.36},{"word":"I","start":403.36,"end":403.46},{"word":"borrowed","start":403.46,"end":403.68},{"word":"from","start":403.68,"end":403.84},{"word":"Einstein.","start":403.84,"end":404.22}],"textKo":"그리고 그것이 아인슈타인에게서 빌려온 세 번째 깨달음으로 이끌었어요.","listenDifficulty":2},{"index":100,"start":405.4,"end":408.14,"textEn":"The problem you have is not going to be solved","words":[{"word":"The","start":405.4,"end":405.8},{"word":"problem","start":405.8,"end":406.12},{"word":"you","start":406.12,"end":406.28},{"word":"have","start":406.28,"end":407.32},{"word":"is","start":407.32,"end":407.48},{"word":"not","start":407.48,"end":407.62},{"word":"going","start":407.62,"end":407.76},{"word":"to","start":407.76,"end":407.82},{"word":"be","start":407.82,"end":407.9},{"word":"solved","start":407.9,"end":408.14}],"textKo":"당신이 가진 문제는 해결될 수 없어요.","listenDifficulty":2},{"index":101,"start":408.14,"end":410.14,"textEn":"At the level of consciousness on which you created it.","words":[{"word":"at","start":408.14,"end":408.28},{"word":"the","start":408.28,"end":408.36},{"word":"level","start":408.36,"end":408.56},{"word":"of","start":408.56,"end":408.68},{"word":"consciousness","start":408.68,"end":409.06},{"word":"on","start":409.06,"end":409.34},{"word":"which","start":409.34,"end":409.48},{"word":"you","start":409.48,"end":409.58},{"word":"created","start":409.58,"end":409.94},{"word":"it.","start":409.94,"end":410.14}],"textKo":"그 문제를 만든 의식 수준에서는요.","listenDifficulty":3},{"index":102,"start":410.68,"end":414.06,"textEn":"You have to expand to a different level of consciousness.","words":[{"word":"You","start":410.68,"end":411.02},{"word":"have","start":411.02,"end":411.42},{"word":"to","start":411.42,"end":411.56},{"word":"expand","start":411.56,"end":412.02},{"word":"to","start":412.02,"end":412.16},{"word":"a","start":412.16,"end":412.28},{"word":"different","start":412.28,"end":412.56},{"word":"level","start":412.56,"end":413.52},{"word":"of","start":413.52,"end":413.68},{"word":"consciousness.","start":413.68,"end":414.06}],"textKo":"다른 의식 수준으로 확장해야 해요.","listenDifficulty":1},{"index":103,"start":414.56,"end":416.74,"textEn":"So what do you do? Well, the first thing you do,","words":[{"word":"So","start":414.56,"end":414.96},{"word":"what","start":414.96,"end":415.06},{"word":"do","start":415.06,"end":415.12},{"word":"you","start":415.12,"end":415.2},{"word":"do?","start":415.2,"end":415.42},{"word":"Well,","start":415.84,"end":416.14},{"word":"the","start":416.16,"end":416.24},{"word":"first","start":416.24,"end":416.38},{"word":"thing","start":416.38,"end":416.52},{"word":"you","start":416.52,"end":416.62},{"word":"do,","start":416.62,"end":416.74}],"textKo":"그러면 어떻게 하느냐고요? 첫 번째로 하는 일은","listenDifficulty":3},{"index":104,"start":416.8,"end":420.06,"textEn":"You throw yourselves on your friends and you have deeper conversations than you ever had before.","words":[{"word":"you","start":416.8,"end":416.88},{"word":"throw","start":416.88,"end":417.42},{"word":"yourselves","start":417.42,"end":417.76},{"word":"on","start":417.76,"end":417.92},{"word":"your","start":417.92,"end":418.02},{"word":"friends","start":418.02,"end":418.26},{"word":"and","start":418.26,"end":418.38},{"word":"you","start":418.38,"end":418.44},{"word":"have","start":418.44,"end":418.52},{"word":"deeper","start":418.52,"end":418.76},{"word":"conversations","start":418.76,"end":419.26},{"word":"than","start":419.26,"end":419.46},{"word":"you","start":419.46,"end":419.54},{"word":"ever","start":419.54,"end":419.66},{"word":"had","start":419.66,"end":419.8},{"word":"before.","start":419.8,"end":420.06}],"textKo":"친구들에게 달려가서 이전보다 더 깊은 대화를 나누는 거예요.","listenDifficulty":3},{"index":105,"start":420.72,"end":423.64,"textEn":"But the second thing you do, you have to go out alone into the wilderness.","words":[{"word":"But","start":420.72,"end":421.04},{"word":"the","start":421.04,"end":421.16},{"word":"second","start":421.16,"end":421.4},{"word":"thing","start":421.4,"end":421.64},{"word":"you","start":421.64,"end":421.8},{"word":"do,","start":421.8,"end":421.96},{"word":"you","start":422.04,"end":422.14},{"word":"have","start":422.14,"end":422.28},{"word":"to","start":422.28,"end":422.4},{"word":"go","start":422.4,"end":422.54},{"word":"out","start":422.54,"end":422.74},{"word":"alone","start":422.74,"end":423.02},{"word":"into","start":423.02,"end":423.24},{"word":"the","start":423.24,"end":423.36},{"word":"wilderness.","start":423.36,"end":423.64}],"textKo":"하지만 두 번째로 하는 일은 혼자 광야로 나가야 해요.","listenDifficulty":3},{"index":106,"start":424.28,"end":427.06,"textEn":"You go out into that place where there''s nobody there to perform","words":[{"word":"You","start":424.28,"end":424.52},{"word":"go","start":424.52,"end":424.7},{"word":"out","start":424.7,"end":424.86},{"word":"into","start":424.86,"end":425.08},{"word":"that","start":425.08,"end":425.24},{"word":"place","start":425.24,"end":425.54},{"word":"where","start":425.54,"end":425.74},{"word":"there''s","start":425.74,"end":425.98},{"word":"nobody","start":425.98,"end":426.24},{"word":"there","start":426.24,"end":426.46},{"word":"to","start":426.46,"end":426.64},{"word":"perform","start":426.64,"end":427.06}],"textKo":"아무도 없어서 연기할 필요가 없는 곳으로 나가는 거예요.","listenDifficulty":2},{"index":107,"start":427.06,"end":429.82,"textEn":"And the ego has nothing to do and it crumbles,","words":[{"word":"and","start":427.06,"end":427.52},{"word":"the","start":427.52,"end":427.66},{"word":"ego","start":427.66,"end":427.94},{"word":"has","start":427.94,"end":428.16},{"word":"nothing","start":428.16,"end":428.42},{"word":"to","start":428.42,"end":428.6},{"word":"do","start":428.6,"end":428.9},{"word":"and","start":428.9,"end":429.22},{"word":"it","start":429.22,"end":429.36},{"word":"crumbles,","start":429.36,"end":429.82}],"textKo":"자아는 할 일이 없어서 무너지고","listenDifficulty":2},{"index":108,"start":429.82,"end":432.32,"textEn":"And only then are you capable of being loved.","words":[{"word":"and","start":429.82,"end":430.28},{"word":"only","start":430.28,"end":430.56},{"word":"then","start":430.56,"end":430.8},{"word":"are","start":430.8,"end":431.02},{"word":"you","start":431.02,"end":431.18},{"word":"capable","start":431.18,"end":431.54},{"word":"of","start":431.54,"end":431.8},{"word":"being","start":431.8,"end":432.0},{"word":"loved.","start":432.0,"end":432.32}],"textKo":"그래야만 사랑받을 수 있게 돼요.","listenDifficulty":2},{"index":109,"start":433.32,"end":436.88,"textEn":"I have a friend who said that when her daughter was born,","words":[{"word":"I","start":433.32,"end":433.8},{"word":"have","start":433.8,"end":433.88},{"word":"a","start":433.88,"end":434.0},{"word":"friend","start":434.0,"end":434.14},{"word":"who","start":434.14,"end":434.36},{"word":"said","start":434.36,"end":434.9},{"word":"that","start":434.9,"end":435.9},{"word":"when","start":435.9,"end":436.04},{"word":"her","start":436.04,"end":436.2},{"word":"daughter","start":436.2,"end":436.42},{"word":"was","start":436.42,"end":436.64},{"word":"born,","start":436.64,"end":436.88}],"textKo":"제 친구 한 명이 말했어요. 딸이 태어났을 때","listenDifficulty":1},{"index":110,"start":436.9,"end":440.2,"textEn":"She realized that she loved her more than evolution required.","words":[{"word":"she","start":436.9,"end":437.12},{"word":"realized","start":437.12,"end":437.56},{"word":"that","start":437.56,"end":438.3},{"word":"she","start":438.3,"end":438.48},{"word":"loved","start":438.48,"end":438.72},{"word":"her","start":438.72,"end":438.88},{"word":"more","start":438.88,"end":439.06},{"word":"than","start":439.06,"end":439.22},{"word":"evolution","start":439.22,"end":439.64},{"word":"required.","start":439.64,"end":440.2}],"textKo":"진화가 요구하는 것 이상으로 사랑한다는 걸 깨달았다고요.","listenDifficulty":1},{"index":111,"start":441.88,"end":447.4,"textEn":"And I''ve always loved that, because it talks about the peace that''s at the deep of ourself,","words":[{"word":"And","start":441.88,"end":442.36},{"word":"I''ve","start":442.36,"end":442.54},{"word":"always","start":442.54,"end":442.74},{"word":"loved","start":442.74,"end":443.02},{"word":"that,","start":443.02,"end":443.38},{"word":"because","start":444.52,"end":445.0},{"word":"it","start":445.0,"end":445.18},{"word":"talks","start":445.18,"end":445.48},{"word":"about","start":445.48,"end":445.74},{"word":"the","start":445.74,"end":445.96},{"word":"peace","start":445.96,"end":446.24},{"word":"that''s","start":446.24,"end":446.52},{"word":"at","start":446.52,"end":446.62},{"word":"the","start":446.62,"end":446.72},{"word":"deep","start":446.72,"end":446.88},{"word":"of","start":446.88,"end":447.04},{"word":"ourself,","start":447.04,"end":447.4}],"textKo":"저는 항상 그 말이 좋았어요. 왜냐하면 우리 깊은 곳에 있는 평화에 대해 말해 주니까요.","listenDifficulty":1},{"index":112,"start":447.72,"end":449.84,"textEn":"Our inexplicable care for one another.","words":[{"word":"our","start":447.72,"end":447.8},{"word":"inexplicable","start":447.8,"end":448.72},{"word":"care","start":448.72,"end":449.08},{"word":"for","start":449.08,"end":449.36},{"word":"one","start":449.36,"end":449.54},{"word":"another.","start":449.54,"end":449.84}],"textKo":"서로에 대한 설명할 수 없는 배려요.","listenDifficulty":1},{"index":113,"start":450.2,"end":452.96,"textEn":"And when you touch that spot, you''re ready to be rescued.","words":[{"word":"And","start":450.2,"end":450.68},{"word":"when","start":450.68,"end":450.82},{"word":"you","start":450.82,"end":450.92},{"word":"touch","start":450.92,"end":451.2},{"word":"that","start":451.2,"end":451.44},{"word":"spot,","start":451.44,"end":451.78},{"word":"you''re","start":451.94,"end":452.22},{"word":"ready","start":452.22,"end":452.38},{"word":"to","start":452.38,"end":452.48},{"word":"be","start":452.48,"end":452.6},{"word":"rescued.","start":452.6,"end":452.96}],"textKo":"그 지점에 닿으면, 구원받을 준비가 된 거예요.","listenDifficulty":2},{"index":114,"start":453.54,"end":458.48,"textEn":"The hard thing about when you''re in the valley is that you can''t climb out.","words":[{"word":"The","start":453.54,"end":453.9},{"word":"hard","start":453.9,"end":454.12},{"word":"thing","start":454.12,"end":454.36},{"word":"about","start":454.36,"end":454.54},{"word":"when","start":454.54,"end":454.7},{"word":"you''re","start":454.7,"end":454.88},{"word":"in","start":454.88,"end":454.98},{"word":"the","start":454.98,"end":455.06},{"word":"valley","start":455.06,"end":455.38},{"word":"is","start":457.1,"end":457.46},{"word":"that","start":457.46,"end":457.6},{"word":"you","start":457.6,"end":457.72},{"word":"can''t","start":457.72,"end":458.0},{"word":"climb","start":458.0,"end":458.26},{"word":"out.","start":458.26,"end":458.48}],"textKo":"골짜기에 있을 때 어려운 점은 스스로 기어올라 나올 수 없다는 거예요.","listenDifficulty":1},{"index":115,"start":458.6,"end":461.84,"textEn":"Somebody has to reach in and pull you out. It happened to me,","words":[{"word":"Somebody","start":458.6,"end":458.78},{"word":"has","start":458.78,"end":458.96},{"word":"to","start":458.96,"end":459.08},{"word":"reach","start":459.08,"end":459.3},{"word":"in","start":459.3,"end":459.46},{"word":"and","start":459.46,"end":459.58},{"word":"pull","start":459.58,"end":459.82},{"word":"you","start":459.82,"end":460.0},{"word":"out.","start":460.0,"end":460.24},{"word":"It","start":461.16,"end":461.44},{"word":"happened","start":461.44,"end":461.62},{"word":"to","start":461.62,"end":461.72},{"word":"me,","start":461.72,"end":461.84}],"textKo":"누군가가 손을 내밀어 끌어올려 줘야 해요. 저에게도 그런 일이 일어났어요.","listenDifficulty":3},{"index":116,"start":461.9,"end":465.36,"textEn":"I got luckily invited over to a house by a couple named Kathy and David,","words":[{"word":"I","start":461.9,"end":462.0},{"word":"got","start":462.0,"end":462.3},{"word":"luckily","start":462.3,"end":462.74},{"word":"invited","start":462.74,"end":463.06},{"word":"over","start":463.06,"end":463.26},{"word":"to","start":463.26,"end":463.36},{"word":"a","start":463.36,"end":463.44},{"word":"house","start":463.44,"end":463.68},{"word":"by","start":463.68,"end":463.94},{"word":"a","start":463.94,"end":464.3},{"word":"couple","start":464.3,"end":464.46},{"word":"named","start":464.46,"end":464.64},{"word":"Kathy","start":464.64,"end":464.94},{"word":"and","start":464.94,"end":465.08},{"word":"David,","start":465.08,"end":465.36}],"textKo":"캐시와 데이비드라는 부부의 집에 초대받은 거예요.","listenDifficulty":2},{"index":117,"start":465.84,"end":470.5,"textEn":"And they were... They had a kid in the D. C. public schools named Santi.","words":[{"word":"and","start":465.84,"end":466.2},{"word":"they","start":466.2,"end":466.36},{"word":"were","start":466.36,"end":466.54},{"word":"...","start":466.54,"end":467.16},{"word":"They","start":468.08,"end":468.44},{"word":"had","start":468.44,"end":468.64},{"word":"a","start":468.64,"end":468.78},{"word":"kid","start":468.78,"end":469.0},{"word":"in","start":469.0,"end":469.16},{"word":"the","start":469.16,"end":469.24},{"word":"D","start":469.24,"end":469.38},{"word":".C.","start":469.38,"end":469.48},{"word":"public","start":469.54,"end":469.72},{"word":"schools","start":469.72,"end":470.0},{"word":"named","start":470.0,"end":470.16},{"word":"Santi.","start":470.16,"end":470.5}],"textKo":"그들은... 산티라는 아이가 DC 공립학교에 다니고 있었어요.","listenDifficulty":2},{"index":118,"start":470.64,"end":473.74,"textEn":"Santi had a friend who needed a place to stay because his mom had some health issues.","words":[{"word":"Santi","start":470.64,"end":470.86},{"word":"had","start":470.86,"end":470.98},{"word":"a","start":470.98,"end":471.06},{"word":"friend","start":471.06,"end":471.28},{"word":"who","start":471.28,"end":471.72},{"word":"needed","start":471.72,"end":471.88},{"word":"a","start":471.88,"end":472.02},{"word":"place","start":472.02,"end":472.16},{"word":"to","start":472.16,"end":472.32},{"word":"stay","start":472.32,"end":472.48},{"word":"because","start":472.48,"end":472.66},{"word":"his","start":472.66,"end":472.8},{"word":"mom","start":472.8,"end":472.94},{"word":"had","start":472.94,"end":473.1},{"word":"some","start":473.1,"end":473.22},{"word":"health","start":473.22,"end":473.38},{"word":"issues.","start":473.38,"end":473.74}],"textKo":"산티에게는 엄마의 건강 문제로 머물 곳이 필요한 친구가 있었어요.","listenDifficulty":3},{"index":119,"start":473.74,"end":476.08,"textEn":"And then that kid had a friend and that kid had a friend","words":[{"word":"And","start":473.74,"end":474.36},{"word":"then","start":474.36,"end":474.48},{"word":"that","start":474.48,"end":474.64},{"word":"kid","start":474.64,"end":474.84},{"word":"had","start":474.84,"end":475.0},{"word":"a","start":475.0,"end":475.1},{"word":"friend","start":475.1,"end":475.22},{"word":"and","start":475.22,"end":475.34},{"word":"that","start":475.34,"end":475.46},{"word":"kid","start":475.46,"end":475.64},{"word":"had","start":475.64,"end":475.8},{"word":"a","start":475.8,"end":475.94},{"word":"friend","start":475.94,"end":476.08}],"textKo":"그 아이에게도 친구가 있었고 그 아이에게도 친구가 있었고","listenDifficulty":3},{"index":120,"start":476.08,"end":479.14,"textEn":"And that kid had a friend. When I went to their house six years ago,","words":[{"word":"and","start":476.08,"end":476.2},{"word":"that","start":476.2,"end":476.34},{"word":"kid","start":476.34,"end":476.54},{"word":"had","start":476.54,"end":476.66},{"word":"a","start":476.66,"end":476.8},{"word":"friend.","start":476.8,"end":477.02},{"word":"When","start":477.3,"end":477.58},{"word":"I","start":477.58,"end":477.64},{"word":"went","start":477.64,"end":477.76},{"word":"to","start":477.76,"end":477.88},{"word":"their","start":477.88,"end":478.0},{"word":"house","start":478.0,"end":478.24},{"word":"six","start":478.24,"end":478.6},{"word":"years","start":478.6,"end":478.8},{"word":"ago,","start":478.8,"end":479.14}],"textKo":"그 아이에게도 친구가 있었어요. 6년 전 그들의 집에 갔을 때","listenDifficulty":3},{"index":121,"start":479.44,"end":481.88,"textEn":"I walk in the door, there''s like 25 around the kitchen table,","words":[{"word":"I","start":479.44,"end":479.76},{"word":"walk","start":479.76,"end":479.98},{"word":"in","start":479.98,"end":480.08},{"word":"the","start":480.08,"end":480.16},{"word":"door,","start":480.16,"end":480.28},{"word":"there''s","start":480.36,"end":480.52},{"word":"like","start":480.52,"end":480.62},{"word":"25","start":480.62,"end":480.92},{"word":"around","start":480.92,"end":481.2},{"word":"the","start":481.2,"end":481.32},{"word":"kitchen","start":481.32,"end":481.52},{"word":"table,","start":481.52,"end":481.88}],"textKo":"문을 열고 들어가니 부엌 식탁 주위에 25명 정도가 있었어요.","listenDifficulty":3},{"index":122,"start":482.06,"end":484.18,"textEn":"A whole bunch sleeping downstairs in the basement.","words":[{"word":"a","start":482.06,"end":482.18},{"word":"whole","start":482.18,"end":482.32},{"word":"bunch","start":482.32,"end":482.54},{"word":"sleeping","start":482.54,"end":482.84},{"word":"downstairs","start":482.84,"end":483.5},{"word":"in","start":483.5,"end":483.8},{"word":"the","start":483.8,"end":483.86},{"word":"basement.","start":483.86,"end":484.18}],"textKo":"지하실에서 자고 있는 아이들도 한 무리가 있었고요.","listenDifficulty":2},{"index":123,"start":484.64,"end":486.66,"textEn":"I reach out to introduce myself to a kid,","words":[{"word":"I","start":484.64,"end":485.0},{"word":"reach","start":485.0,"end":485.22},{"word":"out","start":485.22,"end":485.4},{"word":"to","start":485.4,"end":485.56},{"word":"introduce","start":485.56,"end":485.8},{"word":"myself","start":485.8,"end":486.12},{"word":"to","start":486.12,"end":486.28},{"word":"a","start":486.28,"end":486.38},{"word":"kid,","start":486.38,"end":486.66}],"textKo":"한 아이에게 악수하려고 손을 내밀었더니","listenDifficulty":3},{"index":124,"start":486.78,"end":489.24,"textEn":"And he says, we don''t really shake hands here.","words":[{"word":"and","start":486.78,"end":487.18},{"word":"he","start":487.18,"end":487.34},{"word":"says,","start":487.34,"end":487.68},{"word":"we","start":487.78,"end":488.08},{"word":"don''t","start":488.08,"end":488.26},{"word":"really","start":488.26,"end":488.46},{"word":"shake","start":488.46,"end":488.7},{"word":"hands","start":488.7,"end":489.0},{"word":"here.","start":489.0,"end":489.24}],"textKo":"그 아이가 말했어요. 여기서는 악수를 안 해요.","listenDifficulty":2},{"index":125,"start":490.1,"end":494.18,"textEn":"We just hug here. And I''m not the huggiest guy on the face of the earth,","words":[{"word":"We","start":490.1,"end":490.5},{"word":"just","start":490.5,"end":490.72},{"word":"hug","start":490.72,"end":490.94},{"word":"here.","start":490.94,"end":491.18},{"word":"And","start":492.06,"end":492.46},{"word":"I''m","start":492.46,"end":492.64},{"word":"not","start":492.64,"end":492.72},{"word":"the","start":492.72,"end":492.86},{"word":"huggiest","start":492.86,"end":493.18},{"word":"guy","start":493.18,"end":493.4},{"word":"on","start":493.4,"end":493.54},{"word":"the","start":493.54,"end":493.62},{"word":"face","start":493.62,"end":493.82},{"word":"of","start":493.82,"end":493.92},{"word":"the","start":493.92,"end":494.0},{"word":"earth,","start":494.0,"end":494.18}],"textKo":"여기서는 그냥 포옹해요. 저는 세상에서 포옹을 가장 좋아하는 사람은 아니지만","listenDifficulty":2},{"index":126,"start":495.02,"end":497.84,"textEn":"But I''ve been going back to that home every Thursday night","words":[{"word":"but","start":495.02,"end":495.42},{"word":"I''ve","start":495.42,"end":495.6},{"word":"been","start":495.6,"end":495.68},{"word":"going","start":495.68,"end":495.94},{"word":"back","start":495.94,"end":496.24},{"word":"to","start":496.24,"end":496.44},{"word":"that","start":496.44,"end":496.6},{"word":"home","start":496.6,"end":496.96},{"word":"every","start":496.96,"end":497.26},{"word":"Thursday","start":497.26,"end":497.6},{"word":"night","start":497.6,"end":497.84}],"textKo":"제가 시내에 있을 때마다 매주 목요일 밤 그 집에 가서","listenDifficulty":2},{"index":127,"start":497.84,"end":499.98,"textEn":"When I''m in town and just hugging all those kids.","words":[{"word":"when","start":497.84,"end":498.0},{"word":"I''m","start":498.0,"end":498.16},{"word":"in","start":498.16,"end":498.3},{"word":"town","start":498.3,"end":498.58},{"word":"and","start":498.58,"end":498.96},{"word":"just","start":498.96,"end":499.12},{"word":"hugging","start":499.12,"end":499.38},{"word":"all","start":499.38,"end":499.54},{"word":"those","start":499.54,"end":499.74},{"word":"kids.","start":499.74,"end":499.98}],"textKo":"그 아이들 모두를 안아 주고 있어요.","listenDifficulty":3},{"index":128,"start":500.12,"end":504.08,"textEn":"And they demand intimacy. They demand that you behave in a way","words":[{"word":"And","start":500.12,"end":500.14},{"word":"they","start":500.14,"end":500.54},{"word":"demand","start":500.54,"end":501.18},{"word":"intimacy.","start":501.18,"end":501.7},{"word":"They","start":502.14,"end":502.54},{"word":"demand","start":502.54,"end":502.88},{"word":"that","start":502.88,"end":503.04},{"word":"you","start":503.04,"end":503.14},{"word":"behave","start":503.14,"end":503.46},{"word":"in","start":503.46,"end":503.86},{"word":"a","start":503.86,"end":503.94},{"word":"way","start":503.94,"end":504.08}],"textKo":"그 아이들은 친밀감을 요구해요. 온전히 모습을 드러내는 방식으로 행동하라고 요구해요.","listenDifficulty":2},{"index":129,"start":504.08,"end":507.94,"textEn":"Where you''re showing all the way up, and they teach you a new way to live,","words":[{"word":"where","start":504.08,"end":504.24},{"word":"you''re","start":504.24,"end":504.42},{"word":"showing","start":504.42,"end":504.74},{"word":"all","start":504.74,"end":504.94},{"word":"the","start":504.94,"end":505.04},{"word":"way","start":505.04,"end":505.14},{"word":"up,","start":505.14,"end":505.38},{"word":"and","start":506.2,"end":506.6},{"word":"they","start":506.6,"end":506.74},{"word":"teach","start":506.74,"end":507.04},{"word":"you","start":507.04,"end":507.18},{"word":"a","start":507.18,"end":507.32},{"word":"new","start":507.32,"end":507.46},{"word":"way","start":507.46,"end":507.64},{"word":"to","start":507.64,"end":507.76},{"word":"live,","start":507.76,"end":507.94}],"textKo":"그리고 새로운 삶의 방식을 가르쳐 줘요.","listenDifficulty":2},{"index":130,"start":508.0,"end":510.02,"textEn":"Which is the cure for all the ills of our culture,","words":[{"word":"which","start":508.0,"end":508.14},{"word":"is","start":508.14,"end":508.28},{"word":"the","start":508.28,"end":508.4},{"word":"cure","start":508.4,"end":508.66},{"word":"for","start":508.66,"end":508.84},{"word":"all","start":508.84,"end":509.08},{"word":"the","start":509.08,"end":509.22},{"word":"ills","start":509.22,"end":509.44},{"word":"of","start":509.44,"end":509.58},{"word":"our","start":509.58,"end":509.68},{"word":"culture,","start":509.68,"end":510.02}],"textKo":"그것이 우리 문화의 모든 병폐에 대한 치유법이에요.","listenDifficulty":3},{"index":131,"start":510.36,"end":513.26,"textEn":"Which is a way of direct, really putting relationship first,","words":[{"word":"which","start":510.36,"end":510.58},{"word":"is","start":510.58,"end":510.7},{"word":"a","start":510.7,"end":510.78},{"word":"way","start":510.78,"end":510.92},{"word":"of","start":510.92,"end":511.06},{"word":"direct,","start":511.06,"end":511.48},{"word":"really","start":511.74,"end":512.16},{"word":"putting","start":512.16,"end":512.4},{"word":"relationship","start":512.4,"end":512.9},{"word":"first,","start":512.9,"end":513.26}],"textKo":"관계를 진정으로 첫 번째에 놓는 방식이에요.","listenDifficulty":2},{"index":132,"start":513.4,"end":516.12,"textEn":"Not just as a word, but as a reality.","words":[{"word":"not","start":513.4,"end":513.6},{"word":"just","start":513.6,"end":514.6},{"word":"as","start":514.6,"end":514.8},{"word":"a","start":514.8,"end":514.88},{"word":"word,","start":514.88,"end":515.1},{"word":"but","start":515.24,"end":515.46},{"word":"as","start":515.46,"end":515.62},{"word":"a","start":515.62,"end":515.7},{"word":"reality.","start":515.7,"end":516.12}],"textKo":"단지 말로만이 아니라 현실로서요.","listenDifficulty":1},{"index":133,"start":517.3,"end":521.16,"textEn":"And the beautiful thing is, these communities are everywhere.","words":[{"word":"And","start":517.3,"end":517.7},{"word":"the","start":517.7,"end":517.8},{"word":"beautiful","start":517.8,"end":518.12},{"word":"thing","start":518.12,"end":518.4},{"word":"is,","start":518.4,"end":518.82},{"word":"these","start":519.84,"end":520.24},{"word":"communities","start":520.24,"end":520.64},{"word":"are","start":520.64,"end":520.9},{"word":"everywhere.","start":520.9,"end":521.16}],"textKo":"아름다운 것은 이런 공동체가 어디에나 있다는 거예요.","listenDifficulty":1},{"index":134,"start":521.18,"end":524.38,"textEn":"I started something called the Aspen Institute, called Weave, the social fabric.","words":[{"word":"I","start":521.18,"end":521.76},{"word":"started","start":521.76,"end":522.0},{"word":"something","start":522.0,"end":522.24},{"word":"called","start":522.24,"end":522.46},{"word":"the","start":522.46,"end":522.58},{"word":"Aspen","start":522.58,"end":522.88},{"word":"Institute,","start":522.88,"end":523.1},{"word":"called","start":523.28,"end":523.36},{"word":"Weave,","start":523.36,"end":523.68},{"word":"the","start":523.74,"end":523.8},{"word":"social","start":523.8,"end":524.02},{"word":"fabric.","start":524.02,"end":524.38}],"textKo":"저는 아스펜 연구소에서 위브라는 것을 시작했어요. 사회적 직물이라는 뜻이에요.","listenDifficulty":2},{"index":135,"start":524.5,"end":527.48,"textEn":"This is our logo here. And we plop into a place,","words":[{"word":"This","start":524.5,"end":524.62},{"word":"is","start":524.62,"end":524.72},{"word":"our","start":524.72,"end":524.84},{"word":"logo","start":524.84,"end":525.12},{"word":"here.","start":525.12,"end":525.4},{"word":"And","start":526.06,"end":526.42},{"word":"we","start":526.42,"end":526.52},{"word":"plop","start":526.52,"end":526.98},{"word":"into","start":526.98,"end":527.12},{"word":"a","start":527.12,"end":527.26},{"word":"place,","start":527.26,"end":527.48}],"textKo":"이것이 우리 로고예요. 우리가 어떤 곳에 가면","listenDifficulty":2},{"index":136,"start":527.54,"end":532.14,"textEn":"And we find weavers everywhere. We find people like Aisha Butler,","words":[{"word":"and","start":527.54,"end":527.62},{"word":"we","start":527.62,"end":527.76},{"word":"find","start":527.76,"end":528.02},{"word":"weavers","start":528.02,"end":528.48},{"word":"everywhere.","start":528.48,"end":529.28},{"word":"We","start":530.54,"end":530.9},{"word":"find","start":530.9,"end":531.16},{"word":"people","start":531.16,"end":531.4},{"word":"like","start":531.4,"end":531.58},{"word":"Aisha","start":531.58,"end":531.86},{"word":"Butler,","start":531.86,"end":532.14}],"textKo":"어디서나 위버들을 발견해요. 아이샤 버틀러 같은 사람들을 찾아요.","listenDifficulty":1},{"index":137,"start":532.34,"end":535.44,"textEn":"Who grew up in or lived in Chicago in Englewood,","words":[{"word":"who","start":532.34,"end":532.4},{"word":"grew","start":532.4,"end":532.56},{"word":"up","start":532.56,"end":532.74},{"word":"in","start":532.74,"end":532.9},{"word":"or","start":532.9,"end":534.12},{"word":"lived","start":534.12,"end":534.42},{"word":"in","start":534.42,"end":534.54},{"word":"Chicago","start":534.54,"end":534.9},{"word":"in","start":534.9,"end":535.08},{"word":"Englewood,","start":535.08,"end":535.44}],"textKo":"시카고의 잉글우드에서 자랐거나 살았던 분이에요.","listenDifficulty":1},{"index":138,"start":535.48,"end":538.72,"textEn":"In a tough neighborhood, and she was about to move because it was so dangerous.","words":[{"word":"in","start":535.48,"end":535.56},{"word":"a","start":535.56,"end":535.68},{"word":"tough","start":535.68,"end":535.86},{"word":"neighborhood,","start":535.86,"end":536.2},{"word":"and","start":536.6,"end":536.96},{"word":"she","start":536.96,"end":537.22},{"word":"was","start":537.22,"end":537.36},{"word":"about","start":537.36,"end":537.48},{"word":"to","start":537.48,"end":537.6},{"word":"move","start":537.6,"end":537.78},{"word":"because","start":537.78,"end":537.94},{"word":"it","start":537.94,"end":538.04},{"word":"was","start":538.04,"end":538.12},{"word":"so","start":538.12,"end":538.26},{"word":"dangerous.","start":538.26,"end":538.72}],"textKo":"힘든 동네에서요. 너무 위험해서 이사하려고 했어요.","listenDifficulty":3},{"index":139,"start":539.94,"end":545.1,"textEn":"And she looked across the street, and she saw two little girls playing in an empty lot with broken bottles,","words":[{"word":"And","start":539.94,"end":540.3},{"word":"she","start":540.3,"end":540.44},{"word":"looked","start":540.44,"end":540.64},{"word":"across","start":540.64,"end":540.94},{"word":"the","start":540.94,"end":541.12},{"word":"street,","start":541.12,"end":541.36},{"word":"and","start":541.46,"end":541.6},{"word":"she","start":541.6,"end":541.74},{"word":"saw","start":541.74,"end":542.08},{"word":"two","start":542.08,"end":542.42},{"word":"little","start":542.42,"end":542.6},{"word":"girls","start":542.6,"end":542.84},{"word":"playing","start":542.84,"end":543.08},{"word":"in","start":543.08,"end":543.2},{"word":"an","start":543.2,"end":543.26},{"word":"empty","start":543.26,"end":543.44},{"word":"lot","start":543.44,"end":543.74},{"word":"with","start":543.74,"end":544.48},{"word":"broken","start":544.48,"end":544.72},{"word":"bottles,","start":544.72,"end":545.1}],"textKo":"그런데 길 건너편을 보니 두 어린 소녀가 깨진 유리병이 있는 빈 터에서 놀고 있었어요.","listenDifficulty":2},{"index":140,"start":545.18,"end":547.86,"textEn":"And she turned to her husband, and she said, we''re not leaving.","words":[{"word":"and","start":545.18,"end":545.26},{"word":"she","start":545.26,"end":545.36},{"word":"turned","start":545.36,"end":545.54},{"word":"to","start":545.54,"end":545.68},{"word":"her","start":545.68,"end":545.74},{"word":"husband,","start":545.74,"end":546.04},{"word":"and","start":546.2,"end":546.5},{"word":"she","start":546.5,"end":546.62},{"word":"said,","start":546.62,"end":546.88},{"word":"we''re","start":546.98,"end":547.44},{"word":"not","start":547.44,"end":547.56},{"word":"leaving.","start":547.56,"end":547.86}],"textKo":"남편을 돌아보며 말했어요. 우리는 떠나지 않을 거야.","listenDifficulty":3},{"index":141,"start":548.26,"end":550.6,"textEn":"We''re not going to be just another family that abandoned that.","words":[{"word":"We''re","start":548.26,"end":548.5},{"word":"not","start":548.5,"end":548.66},{"word":"going","start":548.66,"end":548.78},{"word":"to","start":548.78,"end":548.84},{"word":"be","start":548.84,"end":548.92},{"word":"just","start":548.92,"end":549.1},{"word":"another","start":549.1,"end":549.34},{"word":"family","start":549.34,"end":549.74},{"word":"that","start":549.74,"end":549.9},{"word":"abandoned","start":549.9,"end":550.28},{"word":"that.","start":550.28,"end":550.6}],"textKo":"우리는 그곳을 버린 또 다른 가족이 되지 않을 거야.","listenDifficulty":3},{"index":142,"start":551.18,"end":554.0,"textEn":"And she Googled volunteer in Englewood, and now she runs RAGE,","words":[{"word":"And","start":551.18,"end":551.18},{"word":"she","start":551.18,"end":551.32},{"word":"Googled","start":551.32,"end":551.74},{"word":"volunteer","start":551.74,"end":552.22},{"word":"in","start":552.22,"end":552.42},{"word":"Englewood,","start":552.42,"end":552.98},{"word":"and","start":553.08,"end":553.12},{"word":"now","start":553.12,"end":553.24},{"word":"she","start":553.24,"end":553.4},{"word":"runs","start":553.4,"end":553.66},{"word":"RAGE,","start":553.66,"end":554.0}],"textKo":"그녀는 잉글우드 자원봉사를 검색했고, 지금은 RAGE를 운영해요.","listenDifficulty":2},{"index":143,"start":554.08,"end":558.46,"textEn":"The big community organization there. Some of these people have had tough valleys.","words":[{"word":"the","start":554.08,"end":554.18},{"word":"big","start":554.18,"end":554.3},{"word":"community","start":554.3,"end":554.58},{"word":"organization","start":554.58,"end":554.96},{"word":"there.","start":554.96,"end":555.36},{"word":"Some","start":555.82,"end":556.22},{"word":"of","start":556.22,"end":556.3},{"word":"these","start":556.3,"end":556.46},{"word":"people","start":556.46,"end":556.78},{"word":"have","start":556.78,"end":557.1},{"word":"had","start":557.1,"end":557.3},{"word":"tough","start":557.3,"end":557.64},{"word":"valleys.","start":557.64,"end":558.46}],"textKo":"그곳의 큰 지역 사회 조직이에요. 이런 사람들 중 일부는 힘든 골짜기를 겪었어요.","listenDifficulty":1},{"index":144,"start":559.22,"end":562.88,"textEn":"I met a woman named Sarah in Ohio, who came home from an antiquing trip","words":[{"word":"I","start":559.22,"end":559.52},{"word":"met","start":559.52,"end":559.62},{"word":"a","start":559.62,"end":559.72},{"word":"woman","start":559.72,"end":559.9},{"word":"named","start":559.9,"end":560.08},{"word":"Sarah","start":560.08,"end":560.4},{"word":"in","start":560.4,"end":560.62},{"word":"Ohio,","start":560.62,"end":561.0},{"word":"who","start":561.24,"end":561.52},{"word":"came","start":561.52,"end":561.74},{"word":"home","start":561.74,"end":561.9},{"word":"from","start":561.9,"end":562.06},{"word":"an","start":562.06,"end":562.2},{"word":"antiquing","start":562.2,"end":562.64},{"word":"trip","start":562.64,"end":562.88}],"textKo":"오하이오에서 세라라는 여성을 만났어요. 골동품 쇼핑을 다녀오니","listenDifficulty":2},{"index":145,"start":562.88,"end":566.5,"textEn":"And found that her husband had killed himself and their two kids.","words":[{"word":"and","start":562.88,"end":563.28},{"word":"found","start":563.28,"end":563.48},{"word":"that","start":563.48,"end":563.62},{"word":"her","start":563.62,"end":563.72},{"word":"husband","start":563.72,"end":564.02},{"word":"had","start":564.02,"end":564.28},{"word":"killed","start":564.28,"end":564.62},{"word":"himself","start":564.62,"end":565.28},{"word":"and","start":565.28,"end":565.58},{"word":"their","start":565.58,"end":566.0},{"word":"two","start":566.0,"end":566.18},{"word":"kids.","start":566.18,"end":566.5}],"textKo":"남편이 자신과 두 아이를 죽인 것을 발견했어요.","listenDifficulty":1},{"index":146,"start":567.58,"end":569.66,"textEn":"She now runs a free pharmacy.","words":[{"word":"She","start":567.58,"end":567.98},{"word":"now","start":567.98,"end":568.18},{"word":"runs","start":568.18,"end":568.54},{"word":"a","start":568.54,"end":568.7},{"word":"free","start":568.7,"end":569.24},{"word":"pharmacy.","start":569.24,"end":569.66}],"textKo":"그녀는 지금 무료 약국을 운영해요.","listenDifficulty":1},{"index":147,"start":569.96,"end":572.62,"textEn":"She volunteers in the community. She helps women cope with violence.","words":[{"word":"She","start":569.96,"end":570.24},{"word":"volunteers","start":570.24,"end":570.64},{"word":"in","start":570.64,"end":570.84},{"word":"the","start":570.84,"end":570.92},{"word":"community.","start":570.92,"end":571.16},{"word":"She","start":571.28,"end":571.36},{"word":"helps","start":571.36,"end":571.56},{"word":"women","start":571.56,"end":571.78},{"word":"cope","start":571.78,"end":572.08},{"word":"with","start":572.08,"end":572.22},{"word":"violence.","start":572.22,"end":572.62}],"textKo":"지역 사회에서 봉사해요. 여성들이 폭력에 대처하도록 도와요.","listenDifficulty":2},{"index":148,"start":572.76,"end":576.68,"textEn":"She teaches. She told me, I grew from this experience because I was angry.","words":[{"word":"She","start":572.76,"end":572.86},{"word":"teaches.","start":572.86,"end":573.18},{"word":"She","start":574.0,"end":574.4},{"word":"told","start":574.4,"end":574.56},{"word":"me,","start":574.56,"end":574.7},{"word":"I","start":574.8,"end":574.82},{"word":"grew","start":574.82,"end":575.04},{"word":"from","start":575.04,"end":575.22},{"word":"this","start":575.22,"end":575.38},{"word":"experience","start":575.38,"end":575.76},{"word":"because","start":575.76,"end":576.02},{"word":"I","start":576.02,"end":576.18},{"word":"was","start":576.18,"end":576.32},{"word":"angry.","start":576.32,"end":576.68}],"textKo":"가르쳐요. 그녀가 말했어요. 이 경험을 통해 성장했어요. 화가 났기 때문이에요.","listenDifficulty":2},{"index":149,"start":577.08,"end":579.72,"textEn":"I was going to fight back against what he tried to do to me","words":[{"word":"I","start":577.08,"end":577.42},{"word":"was","start":577.42,"end":577.56},{"word":"going","start":577.56,"end":577.64},{"word":"to","start":577.64,"end":577.72},{"word":"fight","start":577.72,"end":577.94},{"word":"back","start":577.94,"end":578.14},{"word":"against","start":578.14,"end":578.72},{"word":"what","start":578.72,"end":578.9},{"word":"he","start":578.9,"end":578.98},{"word":"tried","start":578.98,"end":579.2},{"word":"to","start":579.2,"end":579.34},{"word":"do","start":579.34,"end":579.46},{"word":"to","start":579.46,"end":579.58},{"word":"me","start":579.58,"end":579.72}],"textKo":"그가 저에게 하려 했던 일에 맞서 싸울 거였어요.","listenDifficulty":3},{"index":150,"start":579.72,"end":583.52,"textEn":"By making a difference in the world. See, he didn''t kill me.","words":[{"word":"by","start":579.72,"end":579.9},{"word":"making","start":579.9,"end":580.28},{"word":"a","start":580.28,"end":580.46},{"word":"difference","start":580.46,"end":580.74},{"word":"in","start":580.74,"end":580.94},{"word":"the","start":580.94,"end":581.02},{"word":"world.","start":581.02,"end":581.3},{"word":"See,","start":581.56,"end":581.96},{"word":"he","start":582.04,"end":582.1},{"word":"didn''t","start":582.1,"end":582.32},{"word":"kill","start":582.32,"end":582.58},{"word":"me.","start":582.58,"end":583.52}],"textKo":"세상에 변화를 만들어서요. 보세요, 그는 저를 죽이지 못했어요.","listenDifficulty":1},{"index":151,"start":583.52,"end":586.78,"textEn":"My response to him is, whatever you meant to do to me,","words":[{"word":"My","start":583.52,"end":584.1},{"word":"response","start":584.1,"end":584.46},{"word":"to","start":584.46,"end":584.7},{"word":"him","start":584.7,"end":584.84},{"word":"is,","start":584.84,"end":584.98},{"word":"whatever","start":585.06,"end":585.26},{"word":"you","start":585.26,"end":585.5},{"word":"meant","start":585.5,"end":585.66},{"word":"to","start":585.66,"end":585.82},{"word":"do","start":585.82,"end":585.98},{"word":"to","start":585.98,"end":586.12},{"word":"me,","start":586.12,"end":586.78}],"textKo":"그에 대한 제 응답은, 당신이 나에게 무엇을 하려 했든","listenDifficulty":2},{"index":152,"start":587.04,"end":593.18,"textEn":"Screw you, you''re not going to do it. These weavers are not living an individualistic life.","words":[{"word":"screw","start":587.04,"end":587.46},{"word":"you,","start":587.46,"end":587.76},{"word":"you''re","start":587.92,"end":588.12},{"word":"not","start":588.12,"end":588.28},{"word":"going","start":588.28,"end":588.44},{"word":"to","start":588.44,"end":588.54},{"word":"do","start":588.54,"end":588.68},{"word":"it.","start":588.68,"end":588.84},{"word":"These","start":589.86,"end":590.26},{"word":"weavers","start":590.26,"end":590.62},{"word":"are","start":590.62,"end":591.52},{"word":"not","start":591.52,"end":591.68},{"word":"living","start":591.68,"end":592.02},{"word":"an","start":592.02,"end":592.16},{"word":"individualistic","start":592.16,"end":592.9},{"word":"life.","start":592.9,"end":593.18}],"textKo":"꺼져요, 당신은 그렇게 할 수 없어요. 이 위버들은 개인주의적인 삶을 살지 않아요.","listenDifficulty":1},{"index":153,"start":593.36,"end":595.94,"textEn":"They''re living a relationist life. They have a different set of values.","words":[{"word":"They''re","start":593.36,"end":593.58},{"word":"living","start":593.58,"end":593.76},{"word":"a","start":593.76,"end":593.88},{"word":"relationist","start":593.88,"end":594.4},{"word":"life.","start":594.4,"end":594.62},{"word":"They","start":594.74,"end":594.84},{"word":"have","start":594.84,"end":594.94},{"word":"a","start":594.94,"end":595.1},{"word":"different","start":595.1,"end":595.26},{"word":"set","start":595.26,"end":595.48},{"word":"of","start":595.48,"end":595.58},{"word":"values.","start":595.58,"end":595.94}],"textKo":"관계주의적인 삶을 살아요. 그들은 다른 가치관을 가지고 있어요.","listenDifficulty":3},{"index":154,"start":596.26,"end":599.48,"textEn":"They have moral motivations. They have vocational certitude.","words":[{"word":"They","start":596.26,"end":596.5},{"word":"have","start":596.5,"end":596.64},{"word":"moral","start":596.64,"end":596.98},{"word":"motivations.","start":596.98,"end":597.58},{"word":"They","start":598.02,"end":598.38},{"word":"have","start":598.38,"end":598.48},{"word":"vocational","start":598.48,"end":598.98},{"word":"certitude.","start":598.98,"end":599.48}],"textKo":"도덕적 동기가 있어요. 소명에 대한 확신이 있어요.","listenDifficulty":1},{"index":155,"start":599.48,"end":602.32,"textEn":"They have planted themselves down. I met a guy in Youngstown, Ohio,","words":[{"word":"They","start":599.48,"end":599.86},{"word":"have","start":599.86,"end":600.06},{"word":"planted","start":600.06,"end":600.34},{"word":"themselves","start":600.34,"end":600.7},{"word":"down.","start":600.7,"end":601.06},{"word":"I","start":601.16,"end":601.2},{"word":"met","start":601.2,"end":601.32},{"word":"a","start":601.32,"end":601.44},{"word":"guy","start":601.44,"end":601.54},{"word":"in","start":601.54,"end":601.7},{"word":"Youngstown,","start":601.7,"end":602.04},{"word":"Ohio,","start":602.12,"end":602.32}],"textKo":"뿌리를 내렸어요. 영스타운, 오하이오에서 한 남자를 만났어요.","listenDifficulty":2},{"index":156,"start":602.44,"end":605.26,"textEn":"Who just held up a sign in the town square, defend Youngstown.","words":[{"word":"who","start":602.44,"end":602.52},{"word":"just","start":602.52,"end":602.62},{"word":"held","start":602.62,"end":602.84},{"word":"up","start":602.84,"end":602.94},{"word":"a","start":602.94,"end":603.1},{"word":"sign","start":603.1,"end":603.36},{"word":"in","start":603.36,"end":603.76},{"word":"the","start":603.76,"end":603.84},{"word":"town","start":603.84,"end":604.04},{"word":"square,","start":604.04,"end":604.28},{"word":"defend","start":604.42,"end":604.64},{"word":"Youngstown.","start":604.64,"end":605.26}],"textKo":"마을 광장에서 ''영스타운을 지켜라''라는 팻말을 들고 있었어요.","listenDifficulty":2},{"index":157,"start":605.8,"end":610.02,"textEn":"They have radical mutuality, and they are geniuses at relationship.","words":[{"word":"They","start":605.8,"end":606.2},{"word":"have","start":606.2,"end":606.4},{"word":"radical","start":606.4,"end":606.86},{"word":"mutuality,","start":606.86,"end":607.64},{"word":"and","start":607.78,"end":608.32},{"word":"they","start":608.32,"end":608.48},{"word":"are","start":608.48,"end":608.64},{"word":"geniuses","start":608.64,"end":609.42},{"word":"at","start":609.42,"end":609.56},{"word":"relationship.","start":609.56,"end":610.02}],"textKo":"그들은 급진적인 상호성을 가지고 있고, 관계의 천재들이에요.","listenDifficulty":1},{"index":158,"start":611.08,"end":614.12,"textEn":"There''s a woman named Mary Gordon who runs something called Roots of Empathy.","words":[{"word":"There''s","start":611.08,"end":611.44},{"word":"a","start":611.44,"end":611.52},{"word":"woman","start":611.52,"end":611.7},{"word":"named","start":611.7,"end":611.86},{"word":"Mary","start":611.86,"end":612.08},{"word":"Gordon","start":612.08,"end":612.44},{"word":"who","start":612.44,"end":612.86},{"word":"runs","start":612.86,"end":613.04},{"word":"something","start":613.04,"end":613.24},{"word":"called","start":613.24,"end":613.38},{"word":"Roots","start":613.38,"end":613.62},{"word":"of","start":613.62,"end":613.72},{"word":"Empathy.","start":613.72,"end":614.12}],"textKo":"메리 고든이라는 여성이 공감의 뿌리라는 프로그램을 운영해요.","listenDifficulty":3},{"index":159,"start":614.38,"end":617.92,"textEn":"And what they do is they take a bunch of kids in eighth grade class,","words":[{"word":"And","start":614.38,"end":614.72},{"word":"what","start":614.72,"end":614.82},{"word":"they","start":614.82,"end":614.96},{"word":"do","start":614.96,"end":615.12},{"word":"is","start":615.12,"end":615.26},{"word":"they","start":615.26,"end":615.4},{"word":"take","start":615.4,"end":615.64},{"word":"a","start":615.64,"end":615.78},{"word":"bunch","start":615.78,"end":615.9},{"word":"of","start":615.9,"end":616.14},{"word":"kids","start":616.14,"end":616.9},{"word":"in","start":616.9,"end":617.1},{"word":"eighth","start":617.1,"end":617.26},{"word":"grade","start":617.26,"end":617.46},{"word":"class,","start":617.46,"end":617.92}],"textKo":"그들이 하는 일은 8학년 학급의 아이들을 모으고","listenDifficulty":2},{"index":160,"start":618.1,"end":621.24,"textEn":"They put a mom and an infant, and then the kids, the students,","words":[{"word":"they","start":618.1,"end":618.32},{"word":"put","start":618.32,"end":618.52},{"word":"a","start":618.52,"end":618.62},{"word":"mom","start":618.62,"end":618.84},{"word":"and","start":618.84,"end":619.0},{"word":"an","start":619.0,"end":619.12},{"word":"infant,","start":619.12,"end":619.5},{"word":"and","start":619.88,"end":620.2},{"word":"then","start":620.2,"end":620.32},{"word":"the","start":620.32,"end":620.46},{"word":"kids,","start":620.46,"end":620.7},{"word":"the","start":620.9,"end":621.02},{"word":"students,","start":621.02,"end":621.24}],"textKo":"엄마와 아기를 데려와서, 학생들이","listenDifficulty":2},{"index":161,"start":621.38,"end":623.38,"textEn":"Have to guess what the infant is thinking to teach empathy.","words":[{"word":"have","start":621.38,"end":621.46},{"word":"to","start":621.46,"end":621.56},{"word":"guess","start":621.56,"end":621.76},{"word":"what","start":621.76,"end":621.92},{"word":"the","start":621.92,"end":622.02},{"word":"infant","start":622.02,"end":622.22},{"word":"is","start":622.22,"end":622.4},{"word":"thinking","start":622.4,"end":622.62},{"word":"to","start":622.62,"end":622.82},{"word":"teach","start":622.82,"end":623.04},{"word":"empathy.","start":623.04,"end":623.38}],"textKo":"아기가 무슨 생각을 하는지 추측하게 해서 공감을 가르쳐요.","listenDifficulty":3},{"index":162,"start":624.04,"end":627.4,"textEn":"There''s one kid in a class who was bigger than the rest","words":[{"word":"There''s","start":624.04,"end":624.44},{"word":"one","start":624.44,"end":624.62},{"word":"kid","start":624.62,"end":624.86},{"word":"in","start":624.86,"end":625.0},{"word":"a","start":625.0,"end":625.08},{"word":"class","start":625.08,"end":625.54},{"word":"who","start":625.54,"end":625.82},{"word":"was","start":625.82,"end":626.78},{"word":"bigger","start":626.78,"end":627.0},{"word":"than","start":627.0,"end":627.14},{"word":"the","start":627.14,"end":627.22},{"word":"rest","start":627.22,"end":627.4}],"textKo":"한 반에 다른 아이들보다 큰 아이가 있었어요.","listenDifficulty":2},{"index":163,"start":627.4,"end":630.5,"textEn":"Because he''d been held back, been through the foster care system,","words":[{"word":"because","start":627.4,"end":627.64},{"word":"he''d","start":627.64,"end":627.9},{"word":"been","start":627.9,"end":628.12},{"word":"held","start":628.12,"end":628.32},{"word":"back,","start":628.32,"end":628.68},{"word":"been","start":628.68,"end":629.26},{"word":"through","start":629.26,"end":629.4},{"word":"the","start":629.4,"end":629.52},{"word":"foster","start":629.52,"end":629.78},{"word":"care","start":629.78,"end":630.0},{"word":"system,","start":630.0,"end":630.5}],"textKo":"유급되었고, 위탁 가정 시스템을 거쳤고","listenDifficulty":2},{"index":164,"start":631.02,"end":633.7,"textEn":"Seen his mom get killed, and he wanted to hold the baby.","words":[{"word":"seen","start":631.02,"end":631.24},{"word":"his","start":631.24,"end":631.4},{"word":"mom","start":631.4,"end":631.56},{"word":"get","start":631.56,"end":631.72},{"word":"killed,","start":631.72,"end":632.1},{"word":"and","start":632.3,"end":632.78},{"word":"he","start":632.78,"end":632.88},{"word":"wanted","start":632.88,"end":633.02},{"word":"to","start":633.02,"end":633.12},{"word":"hold","start":633.12,"end":633.28},{"word":"the","start":633.28,"end":633.38},{"word":"baby.","start":633.38,"end":633.7}],"textKo":"엄마가 살해당하는 것을 봤고, 아기를 안고 싶어 했어요.","listenDifficulty":3},{"index":165,"start":634.34,"end":636.48,"textEn":"And the mom was nervous because he looked big and scary,","words":[{"word":"And","start":634.34,"end":634.74},{"word":"the","start":634.74,"end":634.84},{"word":"mom","start":634.84,"end":635.0},{"word":"was","start":635.0,"end":635.18},{"word":"nervous","start":635.18,"end":635.46},{"word":"because","start":635.46,"end":635.64},{"word":"he","start":635.64,"end":635.76},{"word":"looked","start":635.76,"end":635.9},{"word":"big","start":635.9,"end":636.04},{"word":"and","start":636.04,"end":636.16},{"word":"scary,","start":636.16,"end":636.48}],"textKo":"엄마는 걱정했어요. 그 아이가 크고 무서워 보였거든요.","listenDifficulty":3},{"index":166,"start":636.8,"end":639.18,"textEn":"But she let this kid, Darren, hold the baby.","words":[{"word":"but","start":636.8,"end":637.2},{"word":"she","start":637.2,"end":637.38},{"word":"let","start":637.38,"end":637.6},{"word":"this","start":637.6,"end":637.92},{"word":"kid,","start":637.92,"end":638.14},{"word":"Darren,","start":638.26,"end":638.46},{"word":"hold","start":638.6,"end":638.76},{"word":"the","start":638.76,"end":638.88},{"word":"baby.","start":638.88,"end":639.18}],"textKo":"하지만 대런이라는 그 아이가 아기를 안게 해 줬어요.","listenDifficulty":2},{"index":167,"start":639.6,"end":644.38,"textEn":"He held it and he was great with it. He gave the baby back","words":[{"word":"He","start":639.6,"end":640.0},{"word":"held","start":640.0,"end":640.22},{"word":"it","start":640.22,"end":640.32},{"word":"and","start":640.32,"end":640.42},{"word":"he","start":640.42,"end":640.5},{"word":"was","start":640.5,"end":640.62},{"word":"great","start":640.62,"end":640.84},{"word":"with","start":640.84,"end":641.0},{"word":"it.","start":641.0,"end":641.18},{"word":"He","start":642.7,"end":643.1},{"word":"gave","start":643.1,"end":643.3},{"word":"the","start":643.3,"end":643.44},{"word":"baby","start":643.44,"end":644.14},{"word":"back","start":644.14,"end":644.38}],"textKo":"아기를 안았고 정말 잘했어요. 아기를 돌려주고","listenDifficulty":1},{"index":168,"start":644.38,"end":648.22,"textEn":"And started asking questions about parenthood, and his final question was,","words":[{"word":"and","start":644.38,"end":644.56},{"word":"started","start":644.56,"end":644.76},{"word":"asking","start":644.76,"end":645.02},{"word":"questions","start":645.02,"end":645.38},{"word":"about","start":645.38,"end":645.62},{"word":"parenthood,","start":645.62,"end":645.82},{"word":"and","start":646.72,"end":647.12},{"word":"his","start":647.12,"end":647.28},{"word":"final","start":647.28,"end":647.52},{"word":"question","start":647.52,"end":647.88},{"word":"was,","start":647.88,"end":648.22}],"textKo":"부모 됨에 대해 질문하기 시작했어요. 마지막 질문은 이거였어요.","listenDifficulty":1},{"index":169,"start":648.7,"end":651.36,"textEn":"If nobody has ever loved you, do you think you can be a good father?","words":[{"word":"if","start":648.7,"end":649.1},{"word":"nobody","start":649.1,"end":649.4},{"word":"has","start":649.4,"end":649.54},{"word":"ever","start":649.54,"end":649.7},{"word":"loved","start":649.7,"end":649.92},{"word":"you,","start":649.92,"end":650.06},{"word":"do","start":650.14,"end":650.18},{"word":"you","start":650.18,"end":650.28},{"word":"think","start":650.28,"end":650.46},{"word":"you","start":650.46,"end":650.56},{"word":"can","start":650.56,"end":650.7},{"word":"be","start":650.7,"end":650.8},{"word":"a","start":650.8,"end":650.9},{"word":"good","start":650.9,"end":651.02},{"word":"father?","start":651.02,"end":651.36}],"textKo":"아무도 당신을 사랑해 준 적이 없다면, 좋은 아버지가 될 수 있을까요?","listenDifficulty":3},{"index":170,"start":652.4,"end":654.94,"textEn":"And so what Roots of Empathy does is they reach down","words":[{"word":"And","start":652.4,"end":652.8},{"word":"so","start":652.8,"end":652.96},{"word":"what","start":652.96,"end":653.1},{"word":"Roots","start":653.1,"end":653.32},{"word":"of","start":653.32,"end":653.42},{"word":"Empathy","start":653.42,"end":653.72},{"word":"does","start":653.72,"end":654.02},{"word":"is","start":654.02,"end":654.3},{"word":"they","start":654.3,"end":654.46},{"word":"reach","start":654.46,"end":654.72},{"word":"down","start":654.72,"end":654.94}],"textKo":"공감의 뿌리가 하는 일은 손을 내밀어","listenDifficulty":2},{"index":171,"start":654.94,"end":658.14,"textEn":"And they grab people out of the valley, and that''s what weavers are doing.","words":[{"word":"and","start":654.94,"end":655.1},{"word":"they","start":655.1,"end":655.18},{"word":"grab","start":655.18,"end":655.38},{"word":"people","start":655.38,"end":655.68},{"word":"out","start":655.68,"end":655.84},{"word":"of","start":655.84,"end":655.92},{"word":"the","start":655.92,"end":656.0},{"word":"valley,","start":656.0,"end":656.3},{"word":"and","start":656.3,"end":656.8},{"word":"that''s","start":656.8,"end":657.06},{"word":"what","start":657.06,"end":657.2},{"word":"weavers","start":657.2,"end":657.56},{"word":"are","start":657.56,"end":657.86},{"word":"doing.","start":657.86,"end":658.14}],"textKo":"사람들을 골짜기에서 끌어올리는 거예요. 위버들이 하는 일이 바로 그거예요.","listenDifficulty":2},{"index":172,"start":661.02,"end":666.02,"textEn":"Some of them switch jobs, some of them stay in their same jobs,","words":[{"word":"Some","start":661.02,"end":661.54},{"word":"of","start":661.54,"end":661.64},{"word":"them","start":661.64,"end":661.78},{"word":"switch","start":661.78,"end":662.44},{"word":"jobs,","start":662.44,"end":662.98},{"word":"some","start":663.94,"end":664.46},{"word":"of","start":664.46,"end":664.56},{"word":"them","start":664.56,"end":664.7},{"word":"stay","start":664.7,"end":665.0},{"word":"in","start":665.0,"end":665.16},{"word":"their","start":665.16,"end":665.28},{"word":"same","start":665.28,"end":665.5},{"word":"jobs,","start":665.5,"end":666.02}],"textKo":"일부는 직업을 바꾸고, 일부는 같은 직업을 유지하지만","listenDifficulty":1},{"index":173,"start":666.62,"end":668.84,"textEn":"But one of the things, they have an intensity to them.","words":[{"word":"but","start":666.62,"end":667.1},{"word":"one","start":667.1,"end":667.26},{"word":"of","start":667.26,"end":667.38},{"word":"the","start":667.38,"end":667.38},{"word":"things,","start":667.38,"end":667.54},{"word":"they","start":667.64,"end":667.72},{"word":"have","start":667.72,"end":667.86},{"word":"an","start":667.86,"end":667.96},{"word":"intensity","start":667.96,"end":668.38},{"word":"to","start":668.38,"end":668.66},{"word":"them.","start":668.66,"end":668.84}],"textKo":"한 가지는, 그들에게는 강렬함이 있어요.","listenDifficulty":3},{"index":174,"start":669.9,"end":673.78,"textEn":"I read this... E. O. Wilson wrote a great book called Naturalist","words":[{"word":"I","start":669.9,"end":670.08},{"word":"read","start":670.08,"end":670.22},{"word":"this","start":670.22,"end":670.46},{"word":"...","start":670.46,"end":671.08},{"word":"E","start":671.08,"end":671.48},{"word":".O.","start":671.48,"end":671.58},{"word":"Wilson","start":671.6,"end":671.86},{"word":"wrote","start":671.86,"end":672.06},{"word":"a","start":672.06,"end":672.18},{"word":"great","start":672.18,"end":672.36},{"word":"book","start":672.36,"end":672.7},{"word":"called","start":672.7,"end":673.2},{"word":"Naturalist","start":673.2,"end":673.78}],"textKo":"E. O. 윌슨이 자연주의자라는 훌륭한 책을 썼는데 읽었어요.","listenDifficulty":1},{"index":175,"start":673.78,"end":676.3,"textEn":"About his childhood.","words":[{"word":"about","start":673.78,"end":674.0},{"word":"his","start":674.0,"end":674.88},{"word":"childhood.","start":674.88,"end":676.3}],"textKo":"그의 어린 시절에 대한 이야기예요.","listenDifficulty":1},{"index":176,"start":677.36,"end":679.54,"textEn":"And when he was seven, his parents were divorcing.","words":[{"word":"And","start":677.36,"end":677.82},{"word":"when","start":677.82,"end":677.9},{"word":"he","start":677.9,"end":677.96},{"word":"was","start":677.96,"end":678.08},{"word":"seven,","start":678.08,"end":678.34},{"word":"his","start":678.42,"end":678.56},{"word":"parents","start":678.56,"end":678.82},{"word":"were","start":678.82,"end":679.0},{"word":"divorcing.","start":679.0,"end":679.54}],"textKo":"일곱 살 때, 부모님이 이혼하고 있었어요.","listenDifficulty":2},{"index":177,"start":681.02,"end":683.94,"textEn":"And they sent him to Paradise Beach in North Florida,","words":[{"word":"And","start":681.02,"end":681.52},{"word":"they","start":681.52,"end":681.88},{"word":"sent","start":681.88,"end":682.06},{"word":"him","start":682.06,"end":682.14},{"word":"to","start":682.14,"end":682.24},{"word":"Paradise","start":682.24,"end":682.56},{"word":"Beach","start":682.56,"end":683.04},{"word":"in","start":683.04,"end":683.38},{"word":"North","start":683.38,"end":683.58},{"word":"Florida,","start":683.58,"end":683.94}],"textKo":"그들은 그를 북플로리다의 파라다이스 비치로 보냈어요.","listenDifficulty":2},{"index":178,"start":684.18,"end":688.92,"textEn":"And he''d never seen the ocean before, and he''d never seen a jellyfish before.","words":[{"word":"and","start":684.18,"end":684.6},{"word":"he''d","start":684.6,"end":684.76},{"word":"never","start":684.76,"end":684.9},{"word":"seen","start":684.9,"end":685.06},{"word":"the","start":685.06,"end":685.16},{"word":"ocean","start":685.16,"end":685.38},{"word":"before,","start":685.38,"end":685.76},{"word":"and","start":686.44,"end":686.94},{"word":"he''d","start":686.94,"end":687.16},{"word":"never","start":687.16,"end":687.38},{"word":"seen","start":687.38,"end":687.78},{"word":"a","start":687.78,"end":688.12},{"word":"jellyfish","start":688.12,"end":688.58},{"word":"before.","start":688.58,"end":688.92}],"textKo":"그는 바다를 본 적이 없었고, 해파리를 본 적도 없었어요.","listenDifficulty":1},{"index":179,"start":689.08,"end":692.66,"textEn":"He wrote, the creature was astonishing, it existed beyond my imagination.","words":[{"word":"He","start":689.08,"end":689.18},{"word":"wrote,","start":689.18,"end":689.36},{"word":"the","start":689.48,"end":689.58},{"word":"creature","start":689.58,"end":689.86},{"word":"was","start":689.86,"end":690.04},{"word":"astonishing,","start":690.04,"end":690.56},{"word":"it","start":690.86,"end":691.1},{"word":"existed","start":691.1,"end":691.58},{"word":"beyond","start":691.58,"end":691.92},{"word":"my","start":691.92,"end":692.12},{"word":"imagination.","start":692.12,"end":692.66}],"textKo":"그는 썼어요. 그 생물체는 놀라웠다, 내 상상을 초월하여 존재했다고.","listenDifficulty":1},{"index":180,"start":693.2,"end":697.6,"textEn":"He was sitting on the dock one day, and he saw a stingray float beneath his feet.","words":[{"word":"He","start":693.2,"end":693.68},{"word":"was","start":693.68,"end":693.8},{"word":"sitting","start":693.8,"end":694.1},{"word":"on","start":694.1,"end":694.26},{"word":"the","start":694.26,"end":694.34},{"word":"dock","start":694.34,"end":694.58},{"word":"one","start":694.58,"end":694.76},{"word":"day,","start":694.76,"end":694.92},{"word":"and","start":694.98,"end":695.04},{"word":"he","start":695.04,"end":695.12},{"word":"saw","start":695.12,"end":695.4},{"word":"a","start":695.4,"end":695.9},{"word":"stingray","start":695.9,"end":696.38},{"word":"float","start":696.38,"end":696.72},{"word":"beneath","start":696.72,"end":697.0},{"word":"his","start":697.0,"end":697.28},{"word":"feet.","start":697.28,"end":697.6}],"textKo":"어느 날 부두에 앉아 있는데 발밑으로 가오리가 떠가는 것을 봤어요.","listenDifficulty":2},{"index":181,"start":697.6,"end":702.04,"textEn":"And at that moment, a naturalist was born in awe and wonder.","words":[{"word":"And","start":697.6,"end":698.5},{"word":"at","start":698.5,"end":699.02},{"word":"that","start":699.02,"end":699.18},{"word":"moment,","start":699.18,"end":699.4},{"word":"a","start":699.48,"end":699.58},{"word":"naturalist","start":699.58,"end":700.08},{"word":"was","start":700.08,"end":700.22},{"word":"born","start":700.22,"end":700.54},{"word":"in","start":700.54,"end":700.86},{"word":"awe","start":700.86,"end":701.36},{"word":"and","start":701.36,"end":701.68},{"word":"wonder.","start":701.68,"end":702.04}],"textKo":"그 순간, 경외와 경이 속에서 한 자연주의자가 태어났어요.","listenDifficulty":1},{"index":182,"start":702.28,"end":705.46,"textEn":"And he makes this observation that when you''re a child,","words":[{"word":"And","start":702.28,"end":702.56},{"word":"he","start":702.56,"end":702.66},{"word":"makes","start":702.66,"end":702.88},{"word":"this","start":702.88,"end":703.04},{"word":"observation","start":703.04,"end":703.58},{"word":"that","start":704.26,"end":704.78},{"word":"when","start":704.78,"end":704.9},{"word":"you''re","start":704.9,"end":705.02},{"word":"a","start":705.02,"end":705.14},{"word":"child,","start":705.14,"end":705.46}],"textKo":"그리고 그는 이런 관찰을 해요. 어린이일 때","listenDifficulty":1},{"index":183,"start":705.72,"end":708.66,"textEn":"You see animals at twice the size as you do as an adult.","words":[{"word":"you","start":705.72,"end":705.9},{"word":"see","start":705.9,"end":706.08},{"word":"animals","start":706.08,"end":706.44},{"word":"at","start":706.44,"end":706.6},{"word":"twice","start":706.6,"end":706.86},{"word":"the","start":706.86,"end":707.06},{"word":"size","start":707.06,"end":707.4},{"word":"as","start":707.4,"end":707.6},{"word":"you","start":707.6,"end":707.72},{"word":"do","start":707.72,"end":707.84},{"word":"as","start":707.84,"end":708.26},{"word":"an","start":708.26,"end":708.38},{"word":"adult.","start":708.38,"end":708.66}],"textKo":"어른이 되었을 때보다 동물을 두 배 크기로 본다고요.","listenDifficulty":2},{"index":184,"start":709.8,"end":715.6,"textEn":"And that has always impressed me, because what we want as kids is that moral intensity,","words":[{"word":"And","start":709.8,"end":710.32},{"word":"that","start":710.32,"end":710.52},{"word":"has","start":710.52,"end":710.74},{"word":"always","start":710.74,"end":710.92},{"word":"impressed","start":710.92,"end":711.3},{"word":"me,","start":711.3,"end":711.48},{"word":"because","start":711.58,"end":711.68},{"word":"what","start":711.68,"end":712.46},{"word":"we","start":712.46,"end":712.6},{"word":"want","start":712.6,"end":712.82},{"word":"as","start":712.82,"end":713.0},{"word":"kids","start":713.0,"end":713.42},{"word":"is","start":713.42,"end":714.58},{"word":"that","start":714.58,"end":714.94},{"word":"moral","start":714.94,"end":715.42},{"word":"intensity,","start":715.42,"end":715.68}],"textKo":"그 이야기에 항상 감명받았어요. 왜냐하면 우리가 아이로서 원하는 것은 그 도덕적 강렬함이니까요.","listenDifficulty":1},{"index":185,"start":716.36,"end":719.16,"textEn":"To be totally given ourselves over to something","words":[{"word":"to","start":716.36,"end":716.88},{"word":"be","start":716.88,"end":717.0},{"word":"totally","start":717.0,"end":717.36},{"word":"given","start":717.36,"end":717.84},{"word":"ourselves","start":717.84,"end":718.26},{"word":"over","start":718.26,"end":718.66},{"word":"to","start":718.66,"end":718.82},{"word":"something","start":718.82,"end":719.16}],"textKo":"무언가에 완전히 자신을 내맡기는 것","listenDifficulty":1},{"index":186,"start":719.16,"end":721.56,"textEn":"And to find that level of vocation.","words":[{"word":"and","start":719.16,"end":719.8},{"word":"to","start":719.8,"end":719.94},{"word":"find","start":719.94,"end":720.24},{"word":"that","start":720.24,"end":720.46},{"word":"level","start":720.46,"end":720.82},{"word":"of","start":720.82,"end":721.02},{"word":"vocation.","start":721.02,"end":721.56}],"textKo":"그리고 그 수준의 소명을 찾는 거예요.","listenDifficulty":2},{"index":187,"start":722.14,"end":727.04,"textEn":"And when you''re around these weavers, they see other people at twice the size as normal people.","words":[{"word":"And","start":722.14,"end":722.62},{"word":"when","start":722.62,"end":722.72},{"word":"you''re","start":722.72,"end":722.96},{"word":"around","start":722.96,"end":723.24},{"word":"these","start":723.24,"end":723.48},{"word":"weavers,","start":723.48,"end":723.9},{"word":"they","start":724.38,"end":724.6},{"word":"see","start":724.6,"end":724.88},{"word":"other","start":724.88,"end":725.12},{"word":"people","start":725.12,"end":725.42},{"word":"at","start":725.42,"end":725.6},{"word":"twice","start":725.6,"end":725.84},{"word":"the","start":725.84,"end":726.04},{"word":"size","start":726.04,"end":726.3},{"word":"as","start":726.3,"end":726.48},{"word":"normal","start":726.48,"end":726.72},{"word":"people.","start":726.72,"end":727.04}],"textKo":"이 위버들 곁에 있으면, 그들은 다른 사람을 보통 사람의 두 배 크기로 봐요.","listenDifficulty":2},{"index":188,"start":727.36,"end":731.16,"textEn":"They see deeper into them. And what they see is joy.","words":[{"word":"They","start":727.36,"end":727.6},{"word":"see","start":727.6,"end":727.84},{"word":"deeper","start":727.84,"end":728.2},{"word":"into","start":728.2,"end":728.5},{"word":"them.","start":728.5,"end":728.74},{"word":"And","start":729.64,"end":730.12},{"word":"what","start":730.12,"end":730.26},{"word":"they","start":730.26,"end":730.44},{"word":"see","start":730.44,"end":730.76},{"word":"is","start":730.76,"end":731.12},{"word":"joy.","start":731.12,"end":731.36}],"textKo":"더 깊이 들여다봐요. 그리고 그들이 보는 것은 기쁨이에요.","listenDifficulty":1},{"index":189,"start":732.98,"end":735.56,"textEn":"On the first mountain of our life, when we''re shooting for our career,","words":[{"word":"On","start":732.98,"end":733.46},{"word":"the","start":733.46,"end":733.54},{"word":"first","start":733.54,"end":733.74},{"word":"mountain","start":733.74,"end":733.98},{"word":"of","start":733.98,"end":734.08},{"word":"our","start":734.08,"end":734.16},{"word":"life,","start":734.16,"end":734.32},{"word":"when","start":734.36,"end":734.48},{"word":"we''re","start":734.48,"end":734.6},{"word":"shooting","start":734.6,"end":734.78},{"word":"for","start":734.78,"end":735.0},{"word":"our","start":735.0,"end":735.18},{"word":"career,","start":735.18,"end":735.56}],"textKo":"우리 삶의 첫 번째 산에서, 경력을 향해 달릴 때","listenDifficulty":3},{"index":190,"start":737.0,"end":740.58,"textEn":"We shoot for happiness. And happiness is good,","words":[{"word":"we","start":737.0,"end":737.48},{"word":"shoot","start":737.48,"end":737.96},{"word":"for","start":737.96,"end":738.1},{"word":"happiness.","start":738.1,"end":738.5},{"word":"And","start":739.32,"end":739.8},{"word":"happiness","start":739.8,"end":740.14},{"word":"is","start":740.14,"end":740.38},{"word":"good,","start":740.38,"end":740.58}],"textKo":"행복을 추구해요. 행복은 좋은 거예요.","listenDifficulty":1},{"index":191,"start":740.68,"end":743.34,"textEn":"It''s the expansion of self. You win a victory,","words":[{"word":"it''s","start":740.68,"end":741.08},{"word":"the","start":741.08,"end":741.26},{"word":"expansion","start":741.26,"end":741.72},{"word":"of","start":741.72,"end":741.9},{"word":"self.","start":741.9,"end":742.16},{"word":"You","start":742.6,"end":742.82},{"word":"win","start":742.82,"end":742.94},{"word":"a","start":742.94,"end":743.06},{"word":"victory,","start":743.06,"end":743.34}],"textKo":"자아의 확장이에요. 승리를 거두면","listenDifficulty":2},{"index":192,"start":745.24,"end":748.02,"textEn":"You get a promotion, your team wins the Super Bowl,","words":[{"word":"you","start":745.24,"end":745.72},{"word":"get","start":745.72,"end":746.2},{"word":"a","start":746.2,"end":746.3},{"word":"promotion,","start":746.3,"end":746.68},{"word":"your","start":747.0,"end":747.16},{"word":"team","start":747.16,"end":747.3},{"word":"wins","start":747.3,"end":747.48},{"word":"the","start":747.48,"end":747.58},{"word":"Super","start":747.58,"end":747.8},{"word":"Bowl,","start":747.8,"end":748.02}],"textKo":"승진하면, 당신 팀이 슈퍼볼에서 이기면","listenDifficulty":2},{"index":193,"start":748.02,"end":751.84,"textEn":"You''re happy. Joy is not the expansion of self,","words":[{"word":"you''re","start":748.02,"end":748.66},{"word":"happy.","start":748.66,"end":748.9},{"word":"Joy","start":749.88,"end":750.4},{"word":"is","start":750.4,"end":750.66},{"word":"not","start":750.66,"end":750.82},{"word":"the","start":750.82,"end":750.98},{"word":"expansion","start":750.98,"end":751.36},{"word":"of","start":751.36,"end":751.56},{"word":"self,","start":751.56,"end":751.84}],"textKo":"행복해요. 기쁨은 자아의 확장이 아니에요.","listenDifficulty":1},{"index":194,"start":752.12,"end":756.86,"textEn":"It''s the dissolving of self. It''s the moment when the skin barrier disappears","words":[{"word":"it''s","start":752.12,"end":752.42},{"word":"the","start":752.42,"end":752.56},{"word":"dissolving","start":752.56,"end":753.1},{"word":"of","start":753.1,"end":753.28},{"word":"self.","start":753.28,"end":753.56},{"word":"It''s","start":754.46,"end":754.98},{"word":"the","start":754.98,"end":755.1},{"word":"moment","start":755.1,"end":755.4},{"word":"when","start":755.4,"end":755.58},{"word":"the","start":755.58,"end":755.72},{"word":"skin","start":755.72,"end":755.94},{"word":"barrier","start":755.94,"end":756.3},{"word":"disappears","start":756.3,"end":756.86}],"textKo":"자아의 용해예요. 엄마와 아이 사이의 피부 장벽이 사라지는 순간이에요.","listenDifficulty":2},{"index":195,"start":756.86,"end":762.02,"textEn":"Between a mother and her child. It''s the moment when a naturalist feels just free in nature.","words":[{"word":"between","start":756.86,"end":757.14},{"word":"a","start":757.14,"end":757.32},{"word":"mother","start":757.32,"end":757.6},{"word":"and","start":757.6,"end":757.82},{"word":"her","start":757.82,"end":757.94},{"word":"child.","start":757.94,"end":758.36},{"word":"It''s","start":758.72,"end":759.24},{"word":"the","start":759.24,"end":759.34},{"word":"moment","start":759.34,"end":759.58},{"word":"when","start":759.58,"end":759.76},{"word":"a","start":759.76,"end":759.9},{"word":"naturalist","start":759.9,"end":760.4},{"word":"feels","start":760.4,"end":760.7},{"word":"just","start":760.7,"end":761.02},{"word":"free","start":761.02,"end":761.38},{"word":"in","start":761.38,"end":761.7},{"word":"nature.","start":761.7,"end":762.02}],"textKo":"자연주의자가 자연 속에서 자유로움을 느끼는 순간이에요.","listenDifficulty":1},{"index":196,"start":762.92,"end":765.22,"textEn":"It''s the moment when you''re so lost in your work","words":[{"word":"It''s","start":762.92,"end":763.44},{"word":"the","start":763.44,"end":763.54},{"word":"moment","start":763.54,"end":763.76},{"word":"when","start":763.76,"end":763.92},{"word":"you''re","start":763.92,"end":764.06},{"word":"so","start":764.06,"end":764.24},{"word":"lost","start":764.24,"end":764.56},{"word":"in","start":764.56,"end":764.76},{"word":"your","start":764.76,"end":764.9},{"word":"work","start":764.9,"end":765.22}],"textKo":"일이나 어떤 대의에 너무 빠져서","listenDifficulty":2},{"index":197,"start":765.22,"end":767.64,"textEn":"Or a cause you have totally self-forgotten.","words":[{"word":"or","start":765.22,"end":765.4},{"word":"a","start":765.4,"end":765.54},{"word":"cause","start":765.54,"end":765.94},{"word":"you","start":765.94,"end":766.32},{"word":"have","start":766.32,"end":766.44},{"word":"totally","start":766.44,"end":766.8},{"word":"self","start":766.8,"end":767.14},{"word":"-forgotten.","start":767.14,"end":767.64}],"textKo":"완전히 자신을 잊은 순간이에요.","listenDifficulty":1},{"index":198,"start":768.52,"end":770.8,"textEn":"And joy is a better thing to aim for than happiness.","words":[{"word":"And","start":768.52,"end":768.84},{"word":"joy","start":768.84,"end":769.1},{"word":"is","start":769.1,"end":769.4},{"word":"a","start":769.4,"end":769.5},{"word":"better","start":769.5,"end":769.66},{"word":"thing","start":769.66,"end":769.86},{"word":"to","start":769.86,"end":770.0},{"word":"aim","start":770.0,"end":770.08},{"word":"for","start":770.08,"end":770.26},{"word":"than","start":770.26,"end":770.42},{"word":"happiness.","start":770.42,"end":770.8}],"textKo":"기쁨은 행복보다 더 나은 목표예요.","listenDifficulty":3},{"index":199,"start":771.24,"end":774.32,"textEn":"I collect passages of joy, of people when they lose it.","words":[{"word":"I","start":771.24,"end":771.7},{"word":"collect","start":771.7,"end":772.0},{"word":"passages","start":772.0,"end":772.64},{"word":"of","start":772.64,"end":772.9},{"word":"joy,","start":772.9,"end":773.16},{"word":"of","start":773.32,"end":773.4},{"word":"people","start":773.4,"end":773.64},{"word":"when","start":773.64,"end":773.78},{"word":"they","start":773.78,"end":773.92},{"word":"lose","start":773.92,"end":774.16},{"word":"it.","start":774.16,"end":774.32}],"textKo":"저는 기쁨의 구절들을 수집해요. 사람들이 자아를 잃는 순간이요.","listenDifficulty":2},{"index":200,"start":774.58,"end":779.66,"textEn":"One of my favorites is from Zadie Smith. In 1999, she was in a London nightclub,","words":[{"word":"One","start":774.58,"end":774.74},{"word":"of","start":774.74,"end":774.8},{"word":"my","start":774.8,"end":774.9},{"word":"favorites","start":774.9,"end":775.14},{"word":"is","start":775.14,"end":775.32},{"word":"from","start":775.32,"end":775.44},{"word":"Zadie","start":775.44,"end":775.76},{"word":"Smith.","start":775.76,"end":776.06},{"word":"In","start":776.06,"end":777.0},{"word":"1999,","start":777.0,"end":777.48},{"word":"she","start":777.68,"end":777.86},{"word":"was","start":777.86,"end":777.96},{"word":"in","start":777.96,"end":778.1},{"word":"a","start":778.1,"end":778.42},{"word":"London","start":778.42,"end":779.08},{"word":"nightclub,","start":779.08,"end":779.66}],"textKo":"제가 가장 좋아하는 것 중 하나는 재디 스미스의 글이에요. 1999년, 그녀는 런던의 나이트클럽에 있었어요.","listenDifficulty":1},{"index":201,"start":779.92,"end":782.62,"textEn":"Looking for her friends, wondering where her handbag was.","words":[{"word":"looking","start":779.92,"end":780.48},{"word":"for","start":780.48,"end":780.66},{"word":"her","start":780.66,"end":780.8},{"word":"friends,","start":780.8,"end":781.1},{"word":"wondering","start":781.26,"end":781.48},{"word":"where","start":781.48,"end":781.68},{"word":"her","start":781.68,"end":781.8},{"word":"handbag","start":781.8,"end":782.24},{"word":"was.","start":782.24,"end":782.62}],"textKo":"친구들을 찾고, 핸드백이 어디 있는지 궁금해하고 있었어요.","listenDifficulty":1},{"index":202,"start":783.06,"end":789.48,"textEn":"And suddenly, as she writes, a rail-thin man with enormous eyes reached across a sea of bodies from my hand.","words":[{"word":"And","start":783.06,"end":783.54},{"word":"suddenly,","start":783.54,"end":783.92},{"word":"as","start":784.04,"end":784.14},{"word":"she","start":784.14,"end":784.26},{"word":"writes,","start":784.26,"end":784.54},{"word":"a","start":785.16,"end":785.6},{"word":"rail","start":785.6,"end":785.88},{"word":"-thin","start":785.88,"end":786.16},{"word":"man","start":786.16,"end":786.44},{"word":"with","start":786.44,"end":786.62},{"word":"enormous","start":786.62,"end":786.96},{"word":"eyes","start":786.96,"end":787.34},{"word":"reached","start":787.34,"end":787.64},{"word":"across","start":787.64,"end":787.98},{"word":"a","start":787.98,"end":788.18},{"word":"sea","start":788.18,"end":788.32},{"word":"of","start":788.32,"end":788.46},{"word":"bodies","start":788.46,"end":788.76},{"word":"from","start":788.76,"end":788.94},{"word":"my","start":788.94,"end":789.1},{"word":"hand.","start":789.1,"end":789.48}],"textKo":"그러다 갑자기, 그녀가 쓴 것처럼, 커다란 눈을 가진 아주 마른 남자가 사람들의 바다 너머로 제 손을 향해 손을 뻗었어요.","listenDifficulty":1},{"index":203,"start":789.8,"end":792.12,"textEn":"He kept asking me the same thing over and over,","words":[{"word":"He","start":789.8,"end":790.14},{"word":"kept","start":790.14,"end":790.36},{"word":"asking","start":790.36,"end":790.76},{"word":"me","start":790.76,"end":790.9},{"word":"the","start":790.9,"end":791.02},{"word":"same","start":791.02,"end":791.26},{"word":"thing","start":791.26,"end":791.48},{"word":"over","start":791.48,"end":791.78},{"word":"and","start":791.78,"end":791.92},{"word":"over,","start":791.92,"end":792.12}],"textKo":"그는 계속 같은 말을 반복해서 물었어요.","listenDifficulty":2},{"index":204,"start":792.22,"end":795.44,"textEn":"Are you feeling it? My ridiculous heels were killing me,","words":[{"word":"are","start":792.22,"end":792.34},{"word":"you","start":792.34,"end":792.46},{"word":"feeling","start":792.46,"end":792.82},{"word":"it?","start":792.82,"end":793.06},{"word":"My","start":793.56,"end":793.9},{"word":"ridiculous","start":793.9,"end":794.32},{"word":"heels","start":794.32,"end":794.68},{"word":"were","start":794.68,"end":794.88},{"word":"killing","start":794.88,"end":795.18},{"word":"me,","start":795.18,"end":795.44}],"textKo":"느끼고 있어요? 터무니없는 힐이 저를 죽이고 있었고","listenDifficulty":1},{"index":205,"start":795.68,"end":801.0,"textEn":"I was terrified I might die, yet I felt simultaneously overwhelmed with the light that can I kick it,","words":[{"word":"I","start":795.68,"end":795.9},{"word":"was","start":795.9,"end":796.04},{"word":"terrified","start":796.04,"end":796.48},{"word":"I","start":796.48,"end":796.72},{"word":"might","start":796.72,"end":796.9},{"word":"die,","start":796.9,"end":797.3},{"word":"yet","start":797.64,"end":797.8},{"word":"I","start":797.8,"end":797.92},{"word":"felt","start":797.92,"end":798.14},{"word":"simultaneously","start":798.14,"end":798.8},{"word":"overwhelmed","start":798.8,"end":799.52},{"word":"with","start":799.52,"end":799.76},{"word":"the","start":799.76,"end":799.86},{"word":"light","start":799.86,"end":800.06},{"word":"that","start":800.06,"end":800.24},{"word":"can","start":800.24,"end":800.42},{"word":"I","start":800.42,"end":800.58},{"word":"kick","start":800.58,"end":800.8},{"word":"it,","start":800.8,"end":801.0}],"textKo":"죽을 수도 있다는 공포를 느꼈지만, 동시에 ''Can I Kick It''이라는 노래의 빛에 압도되었어요.","listenDifficulty":3},{"index":206,"start":801.16,"end":803.96,"textEn":"Should happen to be playing on this precise moment in the history of the world,","words":[{"word":"should","start":801.16,"end":801.38},{"word":"happen","start":801.38,"end":801.68},{"word":"to","start":801.68,"end":801.8},{"word":"be","start":801.8,"end":801.84},{"word":"playing","start":801.84,"end":802.12},{"word":"on","start":802.12,"end":802.24},{"word":"this","start":802.24,"end":802.38},{"word":"precise","start":802.38,"end":802.72},{"word":"moment","start":802.72,"end":803.04},{"word":"in","start":803.04,"end":803.2},{"word":"the","start":803.2,"end":803.26},{"word":"history","start":803.26,"end":803.5},{"word":"of","start":803.5,"end":803.66},{"word":"the","start":803.66,"end":803.74},{"word":"world,","start":803.74,"end":803.96}],"textKo":"세계 역사의 바로 이 순간에 울려 퍼지다니","listenDifficulty":3},{"index":207,"start":804.14,"end":807.16,"textEn":"On the sound system, and it was now morphing into teen spirit.","words":[{"word":"on","start":804.14,"end":804.38},{"word":"the","start":804.38,"end":804.48},{"word":"sound","start":804.48,"end":804.7},{"word":"system,","start":804.7,"end":805.06},{"word":"and","start":805.06,"end":805.5},{"word":"it","start":805.5,"end":805.58},{"word":"was","start":805.58,"end":805.7},{"word":"now","start":805.7,"end":805.88},{"word":"morphing","start":805.88,"end":806.34},{"word":"into","start":806.34,"end":806.54},{"word":"teen","start":806.54,"end":806.78},{"word":"spirit.","start":806.78,"end":807.16}],"textKo":"음향 시스템에서, 그리고 그것이 이제 ''틴 스피릿''으로 변하고 있었어요.","listenDifficulty":2},{"index":208,"start":807.88,"end":810.96,"textEn":"I took the man''s hand, the top of my head blew away,","words":[{"word":"I","start":807.88,"end":808.32},{"word":"took","start":808.32,"end":808.54},{"word":"the","start":808.54,"end":808.68},{"word":"man''s","start":808.68,"end":809.02},{"word":"hand,","start":809.02,"end":809.34},{"word":"the","start":809.52,"end":809.66},{"word":"top","start":809.66,"end":809.9},{"word":"of","start":809.9,"end":810.04},{"word":"my","start":810.04,"end":810.16},{"word":"head","start":810.16,"end":810.34},{"word":"blew","start":810.34,"end":810.52},{"word":"away,","start":810.52,"end":810.96}],"textKo":"그 남자의 손을 잡았고, 머리 꼭대기가 날아갔어요.","listenDifficulty":2},{"index":209,"start":811.22,"end":814.26,"textEn":"We danced, we danced, we gave ourselves up to joy.","words":[{"word":"we","start":811.22,"end":811.5},{"word":"danced,","start":811.5,"end":811.92},{"word":"we","start":812.1,"end":812.24},{"word":"danced,","start":812.24,"end":812.58},{"word":"we","start":812.82,"end":813.06},{"word":"gave","start":813.06,"end":813.26},{"word":"ourselves","start":813.26,"end":813.56},{"word":"up","start":813.56,"end":813.8},{"word":"to","start":813.8,"end":813.96},{"word":"joy.","start":813.96,"end":814.26}],"textKo":"우리는 춤추었고, 춤추었고, 기쁨에 우리 자신을 내맡겼어요.","listenDifficulty":1},{"index":210,"start":815.38,"end":819.04,"textEn":"And so what I''m trying to describe is two different live mindsets.","words":[{"word":"And","start":815.38,"end":815.82},{"word":"so","start":815.82,"end":815.96},{"word":"what","start":815.96,"end":816.1},{"word":"I''m","start":816.1,"end":816.22},{"word":"trying","start":816.22,"end":816.44},{"word":"to","start":816.44,"end":816.6},{"word":"describe","start":816.6,"end":816.94},{"word":"is","start":816.94,"end":817.12},{"word":"two","start":817.12,"end":817.3},{"word":"different","start":817.3,"end":817.58},{"word":"live","start":817.58,"end":817.92},{"word":"mindsets.","start":817.92,"end":819.04}],"textKo":"그래서 제가 묘사하려는 것은 두 가지 다른 삶의 사고방식이에요.","listenDifficulty":1},{"index":211,"start":819.68,"end":824.4,"textEn":"A first mountain mindset, which is about individual happiness and career success.","words":[{"word":"A","start":819.68,"end":820.12},{"word":"first","start":820.12,"end":820.3},{"word":"mountain","start":820.3,"end":820.56},{"word":"mindset,","start":820.56,"end":821.02},{"word":"which","start":821.12,"end":821.32},{"word":"is","start":821.32,"end":821.44},{"word":"about","start":821.44,"end":821.64},{"word":"individual","start":821.64,"end":822.48},{"word":"happiness","start":822.48,"end":823.02},{"word":"and","start":823.02,"end":823.74},{"word":"career","start":823.74,"end":824.0},{"word":"success.","start":824.0,"end":824.4}],"textKo":"첫 번째 산 사고방식, 개인적 행복과 경력 성공에 대한 거예요.","listenDifficulty":1},{"index":212,"start":824.54,"end":828.98,"textEn":"And it''s a good mindset, I have nothing against it. But we''re in a national valley","words":[{"word":"And","start":824.54,"end":824.62},{"word":"it''s","start":824.62,"end":824.74},{"word":"a","start":824.74,"end":824.8},{"word":"good","start":824.8,"end":824.9},{"word":"mindset,","start":824.9,"end":825.2},{"word":"I","start":825.32,"end":825.36},{"word":"have","start":825.36,"end":825.38},{"word":"nothing","start":825.38,"end":825.56},{"word":"against","start":825.56,"end":825.86},{"word":"it.","start":825.86,"end":826.06},{"word":"But","start":826.7,"end":827.2},{"word":"we''re","start":827.2,"end":827.38},{"word":"in","start":827.38,"end":827.76},{"word":"a","start":827.76,"end":828.14},{"word":"national","start":828.14,"end":828.48},{"word":"valley","start":828.48,"end":828.98}],"textKo":"좋은 사고방식이에요, 반대하지 않아요. 하지만 우리는 국가적 골짜기에 있어요.","listenDifficulty":2},{"index":213,"start":828.98,"end":831.44,"textEn":"Because we don''t have the other mindset to balance it.","words":[{"word":"because","start":828.98,"end":829.58},{"word":"we","start":829.58,"end":829.78},{"word":"don''t","start":829.78,"end":829.94},{"word":"have","start":829.94,"end":830.1},{"word":"the","start":830.1,"end":830.24},{"word":"other","start":830.24,"end":830.38},{"word":"mindset","start":830.38,"end":830.68},{"word":"to","start":830.68,"end":830.92},{"word":"balance","start":830.92,"end":831.22},{"word":"it.","start":831.22,"end":831.44}],"textKo":"그것을 균형 잡을 다른 사고방식이 없기 때문이에요.","listenDifficulty":2},{"index":214,"start":831.88,"end":834.14,"textEn":"We no longer feel good about ourselves as a people,","words":[{"word":"We","start":831.88,"end":832.38},{"word":"no","start":832.38,"end":832.52},{"word":"longer","start":832.52,"end":832.72},{"word":"feel","start":832.72,"end":832.94},{"word":"good","start":832.94,"end":833.1},{"word":"about","start":833.1,"end":833.26},{"word":"ourselves","start":833.26,"end":833.54},{"word":"as","start":833.54,"end":833.78},{"word":"a","start":833.78,"end":833.88},{"word":"people,","start":833.88,"end":834.14}],"textKo":"더 이상 국민으로서 자신에 대해 좋게 느끼지 않아요.","listenDifficulty":3},{"index":215,"start":834.38,"end":836.86,"textEn":"We''ve lost our defining faith in our future,","words":[{"word":"we''ve","start":834.38,"end":835.04},{"word":"lost","start":835.04,"end":835.22},{"word":"our","start":835.22,"end":835.4},{"word":"defining","start":835.4,"end":835.78},{"word":"faith","start":835.78,"end":836.12},{"word":"in","start":836.12,"end":836.44},{"word":"our","start":836.44,"end":836.56},{"word":"future,","start":836.56,"end":836.86}],"textKo":"우리의 미래에 대한 확고한 믿음을 잃었어요.","listenDifficulty":1},{"index":216,"start":837.3,"end":840.42,"textEn":"We don''t see each other deeply, we don''t treat each others well.","words":[{"word":"we","start":837.3,"end":837.68},{"word":"don''t","start":837.68,"end":837.94},{"word":"see","start":837.94,"end":838.14},{"word":"each","start":838.14,"end":838.4},{"word":"other","start":838.4,"end":838.6},{"word":"deeply,","start":838.6,"end":838.98},{"word":"we","start":839.06,"end":839.2},{"word":"don''t","start":839.2,"end":839.42},{"word":"treat","start":839.42,"end":839.62},{"word":"each","start":839.62,"end":839.8},{"word":"others","start":839.8,"end":840.02},{"word":"well.","start":840.02,"end":840.42}],"textKo":"서로를 깊이 바라보지 않고, 서로를 잘 대하지 않아요.","listenDifficulty":2},{"index":217,"start":841.12,"end":845.7,"textEn":"And we need a lot of changes. We need economic change and environmental change,","words":[{"word":"And","start":841.12,"end":841.62},{"word":"we","start":841.62,"end":841.7},{"word":"need","start":841.7,"end":841.86},{"word":"a","start":841.86,"end":841.98},{"word":"lot","start":841.98,"end":842.06},{"word":"of","start":842.06,"end":842.22},{"word":"changes.","start":842.22,"end":842.62},{"word":"We","start":843.24,"end":843.66},{"word":"need","start":843.66,"end":843.8},{"word":"economic","start":843.8,"end":844.16},{"word":"change","start":844.16,"end":844.58},{"word":"and","start":844.58,"end":844.78},{"word":"environmental","start":844.78,"end":845.16},{"word":"change,","start":845.16,"end":845.7}],"textKo":"많은 변화가 필요해요. 경제적 변화와 환경적 변화가 필요해요.","listenDifficulty":1},{"index":218,"start":846.5,"end":849.16,"textEn":"But we also need a cultural and relational revolution.","words":[{"word":"but","start":846.5,"end":847.0},{"word":"we","start":847.0,"end":847.12},{"word":"also","start":847.12,"end":847.32},{"word":"need","start":847.32,"end":847.5},{"word":"a","start":847.5,"end":847.6},{"word":"cultural","start":847.6,"end":847.96},{"word":"and","start":847.96,"end":848.2},{"word":"relational","start":848.2,"end":848.64},{"word":"revolution.","start":848.64,"end":849.16}],"textKo":"하지만 문화적이고 관계적인 혁명도 필요해요.","listenDifficulty":2},{"index":219,"start":849.62,"end":853.84,"textEn":"We need to name the language of a recovered society.","words":[{"word":"We","start":849.62,"end":850.04},{"word":"need","start":850.04,"end":850.16},{"word":"to","start":850.16,"end":850.28},{"word":"name","start":850.28,"end":850.56},{"word":"the","start":850.56,"end":850.76},{"word":"language","start":850.76,"end":851.26},{"word":"of","start":851.26,"end":852.74},{"word":"a","start":852.74,"end":852.84},{"word":"recovered","start":852.84,"end":853.22},{"word":"society.","start":853.22,"end":853.84}],"textKo":"회복된 사회의 언어에 이름을 붙여야 해요.","listenDifficulty":1},{"index":220,"start":854.24,"end":856.8,"textEn":"And to me, the Weavers have found a way to make it. We''ve found that language.","words":[{"word":"And","start":854.24,"end":854.72},{"word":"to","start":854.72,"end":854.86},{"word":"me,","start":854.86,"end":855.0},{"word":"the","start":855.1,"end":855.16},{"word":"Weavers","start":855.16,"end":855.58},{"word":"have","start":855.58,"end":855.96},{"word":"found","start":855.96,"end":856.04},{"word":"a","start":856.04,"end":856.04},{"word":"way","start":856.04,"end":856.04},{"word":"to","start":856.04,"end":856.04},{"word":"make","start":856.04,"end":856.04},{"word":"it.","start":856.04,"end":856.04},{"word":"We''ve","start":856.06,"end":856.06},{"word":"found","start":856.06,"end":856.2},{"word":"that","start":856.2,"end":856.38},{"word":"language.","start":856.38,"end":856.8}],"textKo":"저에게 있어 위버들은 그 방법을 찾았어요. 우리는 그 언어를 찾았어요.","listenDifficulty":3},{"index":221,"start":857.34,"end":860.54,"textEn":"My theory of social change is that society changes","words":[{"word":"My","start":857.34,"end":857.76},{"word":"theory","start":857.76,"end":857.98},{"word":"of","start":857.98,"end":858.16},{"word":"social","start":858.16,"end":858.42},{"word":"change","start":858.42,"end":858.96},{"word":"is","start":858.96,"end":859.56},{"word":"that","start":859.56,"end":859.68},{"word":"society","start":859.68,"end":860.14},{"word":"changes","start":860.14,"end":860.54}],"textKo":"제 사회 변화 이론은 사회가 변한다는 거예요.","listenDifficulty":1},{"index":222,"start":860.54,"end":862.84,"textEn":"When a small group of people find a better way to live,","words":[{"word":"when","start":860.54,"end":860.76},{"word":"a","start":860.76,"end":860.88},{"word":"small","start":860.88,"end":861.1},{"word":"group","start":861.1,"end":861.3},{"word":"of","start":861.3,"end":861.44},{"word":"people","start":861.44,"end":861.68},{"word":"find","start":861.68,"end":861.94},{"word":"a","start":861.94,"end":862.06},{"word":"better","start":862.06,"end":862.22},{"word":"way","start":862.22,"end":862.4},{"word":"to","start":862.4,"end":862.52},{"word":"live,","start":862.52,"end":862.84}],"textKo":"소수의 사람들이 더 나은 삶의 방식을 찾으면 나머지가 따라 하는 거예요.","listenDifficulty":3},{"index":223,"start":863.06,"end":867.64,"textEn":"And the rest of us copy them. And these Weavers have found a better way to live.","words":[{"word":"and","start":863.06,"end":863.54},{"word":"the","start":863.54,"end":863.66},{"word":"rest","start":863.66,"end":863.84},{"word":"of","start":863.84,"end":863.98},{"word":"us","start":863.98,"end":864.1},{"word":"copy","start":864.1,"end":864.44},{"word":"them.","start":864.44,"end":864.66},{"word":"And","start":865.48,"end":865.9},{"word":"these","start":865.9,"end":866.1},{"word":"Weavers","start":866.1,"end":866.38},{"word":"have","start":866.38,"end":866.56},{"word":"found","start":866.56,"end":866.86},{"word":"a","start":866.86,"end":867.0},{"word":"better","start":867.0,"end":867.14},{"word":"way","start":867.14,"end":867.3},{"word":"to","start":867.3,"end":867.42},{"word":"live.","start":867.42,"end":867.64}],"textKo":"이 위버들은 더 나은 삶의 방식을 찾았어요.","listenDifficulty":2},{"index":224,"start":868.16,"end":873.2,"textEn":"And you don''t have to theorize about it, they''re out there as community builders all around the country.","words":[{"word":"And","start":868.16,"end":868.58},{"word":"you","start":868.58,"end":868.7},{"word":"don''t","start":868.7,"end":868.84},{"word":"have","start":868.84,"end":868.96},{"word":"to","start":868.96,"end":869.06},{"word":"theorize","start":869.06,"end":869.66},{"word":"about","start":869.66,"end":869.86},{"word":"it,","start":869.86,"end":870.06},{"word":"they''re","start":870.22,"end":870.58},{"word":"out","start":870.58,"end":870.76},{"word":"there","start":870.76,"end":870.98},{"word":"as","start":870.98,"end":871.24},{"word":"community","start":871.24,"end":871.58},{"word":"builders","start":871.58,"end":872.18},{"word":"all","start":872.18,"end":872.5},{"word":"around","start":872.5,"end":872.74},{"word":"the","start":872.74,"end":872.92},{"word":"country.","start":872.92,"end":873.2}],"textKo":"이론으로 따질 필요 없어요. 전국 곳곳에서 공동체 건설자로 활동하고 있어요.","listenDifficulty":2},{"index":225,"start":873.98,"end":876.1,"textEn":"We just have to shift our lives a little","words":[{"word":"We","start":873.98,"end":874.4},{"word":"just","start":874.4,"end":874.58},{"word":"have","start":874.58,"end":874.76},{"word":"to","start":874.76,"end":874.9},{"word":"shift","start":874.9,"end":875.18},{"word":"our","start":875.18,"end":875.42},{"word":"lives","start":875.42,"end":875.76},{"word":"a","start":875.76,"end":875.92},{"word":"little","start":875.92,"end":876.1}],"textKo":"우리 삶을 조금만 바꾸면 돼요.","listenDifficulty":2},{"index":226,"start":876.1,"end":878.96,"textEn":"So we can say, well, I''m a Weaver, we''re a Weaver.","words":[{"word":"so","start":876.1,"end":876.76},{"word":"we","start":876.76,"end":876.92},{"word":"can","start":876.92,"end":877.06},{"word":"say,","start":877.06,"end":877.26},{"word":"well,","start":877.32,"end":877.48},{"word":"I''m","start":877.56,"end":877.88},{"word":"a","start":877.88,"end":877.96},{"word":"Weaver,","start":877.96,"end":878.26},{"word":"we''re","start":878.36,"end":878.54},{"word":"a","start":878.54,"end":878.66},{"word":"Weaver.","start":878.66,"end":878.96}],"textKo":"나는 위버다, 우리는 위버다라고 말할 수 있도록요.","listenDifficulty":2},{"index":227,"start":879.7,"end":883.86,"textEn":"And if we do that, the hole inside ourselves gets filled,","words":[{"word":"And","start":879.7,"end":880.12},{"word":"if","start":880.12,"end":880.26},{"word":"we","start":880.26,"end":880.34},{"word":"do","start":880.34,"end":880.5},{"word":"that,","start":880.5,"end":880.88},{"word":"the","start":881.8,"end":882.22},{"word":"hole","start":882.22,"end":882.38},{"word":"inside","start":882.38,"end":882.66},{"word":"ourselves","start":882.66,"end":883.16},{"word":"gets","start":883.16,"end":883.5},{"word":"filled,","start":883.5,"end":883.86}],"textKo":"그렇게 하면 우리 안의 구멍이 채워지고","listenDifficulty":1},{"index":228,"start":883.86,"end":887.0,"textEn":"But more important, the social unity gets repaired.","words":[{"word":"but","start":883.86,"end":884.56},{"word":"more","start":884.56,"end":884.74},{"word":"important,","start":884.74,"end":885.16},{"word":"the","start":885.3,"end":885.38},{"word":"social","start":885.38,"end":885.66},{"word":"unity","start":885.66,"end":886.08},{"word":"gets","start":886.08,"end":886.64},{"word":"repaired.","start":886.64,"end":887.0}],"textKo":"더 중요한 것은 사회적 통합이 회복돼요.","listenDifficulty":1},{"index":229,"start":887.22,"end":893.26,"textEn":"Thank you very much. Thank you very much.","words":[{"word":"Thank","start":887.22,"end":887.42},{"word":"you","start":887.42,"end":887.52},{"word":"very","start":887.52,"end":887.64},{"word":"much.","start":887.64,"end":887.86},{"word":"Thank","start":887.86,"end":887.86},{"word":"you","start":887.86,"end":889.9},{"word":"very","start":889.9,"end":889.92},{"word":"much.","start":889.92,"end":893.26}],"textKo":"감사합니다. 정말 감사합니다.","listenDifficulty":1},{"index":230,"start":893.26,"end":894.06,"textEn":"Thank you. Thank you. Thank you. Thank you. Thank you. Thank you. Thank you.","words":[{"word":"Thank","start":893.26,"end":893.26},{"word":"you.","start":893.26,"end":893.52},{"word":"Thank","start":893.54,"end":893.54},{"word":"you.","start":893.54,"end":893.58},{"word":"Thank","start":893.66,"end":893.72},{"word":"you.","start":893.72,"end":893.84},{"word":"Thank","start":893.84,"end":893.86},{"word":"you.","start":893.86,"end":893.86},{"word":"Thank","start":893.86,"end":893.86},{"word":"you.","start":893.86,"end":893.88},{"word":"Thank","start":893.88,"end":893.9},{"word":"you.","start":893.9,"end":893.92},{"word":"Thank","start":893.98,"end":894.06},{"word":"you.","start":894.06,"end":894.06}],"textKo":"","listenDifficulty":3}]}'::jsonb, '[{"word":"humiliated","definition":"made to feel ashamed and foolish by injuring one''s dignity or pride","meaningKo":"굴욕감을 느끼는, 창피를 당한","etymology":"Latin ''humiliare'' meaning ''to make humble'' from ''humilis'' (low, humble)","rootBreakdown":{"prefix":null,"root":"humil (humble, low)","suffix":"-ated"},"relatedWords":["humble","humility","humiliation"],"isEssential":true,"partOfSpeech":"adjective","phonetic":"/hjuːˈmɪlieɪtɪd/","contextSentence":"And I was humiliated by that failed commitment.","segmentIndex":2},{"word":"conservatism","definition":"commitment to traditional values, ideas, and institutions; resistance to change","meaningKo":"보수주의, 전통적 가치와 제도를 지키려는 태도","etymology":"Latin ''conservare'' meaning ''to preserve, keep safe''","rootBreakdown":{"prefix":"con-","root":"serv (keep, save)","suffix":"-ism"},"relatedWords":["conservative","conserve","preserve"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/kənˈsɜːrvətɪzəm/","contextSentence":"But conservatism had changed, so I''d lost a lot of those friends, too.","segmentIndex":4},{"word":"meritocracy","definition":"a system in which advancement is based on individual ability or achievement","meaningKo":"능력주의, 실력에 따라 지위가 결정되는 체제","etymology":"Latin ''meritum'' (deserved) + Greek ''kratos'' (power, rule)","rootBreakdown":{"prefix":null,"root":"merit (deserve) + cracy (rule)","suffix":null},"relatedWords":["merit","meritorious","democracy"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ˌmerɪˈtɒkrəsi/","contextSentence":"The third lie is the lie of the meritocracy.","segmentIndex":26},{"word":"self-sufficiency","definition":"the quality of being able to provide for oneself without the help of others","meaningKo":"자급자족, 스스로 충족하는 능력","etymology":"Latin ''sui'' (of oneself) + ''sufficere'' (to be enough)","rootBreakdown":{"prefix":"self-","root":"suffic (be enough)","suffix":"-ency"},"relatedWords":["sufficient","suffice","self-reliant"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ˌsɛlf.səˈfɪʃənsi/","contextSentence":"And that''s the lie of self-sufficiency.","segmentIndex":23},{"word":"omission","definition":"the act of leaving something out or failing to do something","meaningKo":"빠뜨림, 생략, 태만","etymology":"Latin ''omittere'' meaning ''to let go, send away''","rootBreakdown":{"prefix":"o- (away)","root":"miss (send)","suffix":"-ion"},"relatedWords":["omit","mission","emission"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/əˈmɪʃən/","contextSentence":"And my sins were the sins of omission.","segmentIndex":33},{"word":"evasion","definition":"the act of avoiding or escaping something, especially a duty or responsibility","meaningKo":"회피, 도피","etymology":"Latin ''evadere'' meaning ''to escape, get away''","rootBreakdown":{"prefix":"e- (out)","root":"vas (go)","suffix":"-ion"},"relatedWords":["evade","evasive","invade"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ɪˈveɪʒən/","contextSentence":"Not reaching out, failing to show up for my friends, evasion, avoiding conflict.","segmentIndex":34},{"word":"detached","definition":"separate, disconnected; not involved or concerned emotionally","meaningKo":"분리된, 초연한, 무관심한","etymology":"Old French ''destachier'' meaning ''to unfasten''","rootBreakdown":{"prefix":"de- (away)","root":"tach (attach, fasten)","suffix":"-ed"},"relatedWords":["detach","attach","detachment"],"isEssential":true,"partOfSpeech":"adjective","phonetic":"/dɪˈtætʃt/","contextSentence":"And so I was detached.","segmentIndex":39},{"word":"chronically","definition":"in a way that continues for a long time or keeps recurring","meaningKo":"만성적으로, 오랫동안 지속적으로","etymology":"Greek ''chronos'' meaning ''time''","rootBreakdown":{"prefix":null,"root":"chron (time)","suffix":"-ically"},"relatedWords":["chronic","chronicle","chronological"],"isEssential":true,"partOfSpeech":"adverb","phonetic":"/ˈkrɒnɪkli/","contextSentence":"Thirty-five percent of Americans over 45 are chronically lonely.","segmentIndex":41},{"word":"fragmented","definition":"broken into separate parts; disjointed and incomplete","meaningKo":"단편화된, 조각난","etymology":"Latin ''fragmentum'' from ''frangere'' meaning ''to break''","rootBreakdown":{"prefix":null,"root":"frag (break)","suffix":"-mented"},"relatedWords":["fragment","fragile","fracture"],"isEssential":true,"partOfSpeech":"adjective","phonetic":"/ˈfræɡmentɪd/","contextSentence":"And isolated and fragmented from each other.","segmentIndex":40},{"word":"unaffiliated","definition":"not officially attached to or connected with an organization or group","meaningKo":"소속되지 않은, 무소속의","etymology":"Latin ''un-'' (not) + ''affiliare'' (to adopt as a son)","rootBreakdown":{"prefix":"un- (not)","root":"affili (adopt, connect)","suffix":"-ated"},"relatedWords":["affiliate","affiliated","affiliation"],"isEssential":false,"partOfSpeech":"adjective","phonetic":"/ˌʌnəˈfɪlieɪtɪd/","contextSentence":"The fastest-growing political party is unaffiliated.","segmentIndex":44},{"word":"righteousness","definition":"the quality of being morally right or justifiable; virtue","meaningKo":"올바름, 정의로움, 의로움","etymology":"Old English ''rihtwisnes'' from ''riht'' (right) + ''wis'' (manner)","rootBreakdown":{"prefix":null,"root":"right (correct, just)","suffix":"-eousness"},"relatedWords":["righteous","right","unrighteous"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ˈraɪtʃəsnəs/","contextSentence":"And what the soul does is it yearns for righteousness.","segmentIndex":97},{"word":"obliteration","definition":"the complete destruction or elimination of something","meaningKo":"말살, 완전한 파괴, 소멸","etymology":"Latin ''obliterare'' meaning ''to erase, cause to disappear''","rootBreakdown":{"prefix":"ob- (against)","root":"liter (letter, mark)","suffix":"-ation"},"relatedWords":["obliterate","literal","literate"],"isEssential":false,"partOfSpeech":"noun","phonetic":"/əˌblɪtəˈreɪʃən/","contextSentence":"Slavery is wrong because it''s an obliteration of another soul.","segmentIndex":94},{"word":"vocation","definition":"a strong feeling of suitability for a particular career or occupation; a calling","meaningKo":"소명, 천직, 직업적 사명감","etymology":"Latin ''vocare'' meaning ''to call''","rootBreakdown":{"prefix":null,"root":"voc (call)","suffix":"-ation"},"relatedWords":["vocal","invoke","advocate"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/voʊˈkeɪʃən/","contextSentence":"And to find that level of vocation.","segmentIndex":186},{"word":"intimacy","definition":"close familiarity or friendship; a warm, personal relationship","meaningKo":"친밀감, 가까운 관계, 내밀함","etymology":"Latin ''intimus'' meaning ''innermost, deepest''","rootBreakdown":{"prefix":null,"root":"intim (innermost)","suffix":"-acy"},"relatedWords":["intimate","intimately","intimation"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ˈɪntɪməsi/","contextSentence":"And they demand intimacy.","segmentIndex":128},{"word":"empathy","definition":"the ability to understand and share the feelings of another person","meaningKo":"공감, 감정 이입","etymology":"Greek ''empatheia'' from ''en'' (in) + ''pathos'' (feeling)","rootBreakdown":{"prefix":"em- (in)","root":"path (feeling)","suffix":"-y"},"relatedWords":["empathetic","sympathy","apathy"],"isEssential":true,"partOfSpeech":"noun","phonetic":"/ˈempəθi/","contextSentence":"There''s a woman named Mary Gordon who runs something called Roots of Empathy.","segmentIndex":158},{"word":"cascades","definition":"a series of things that happen rapidly one after another","meaningKo":"연쇄, 폭포처럼 쏟아지는 것들","etymology":"Italian ''cascata'' from ''cascare'' meaning ''to fall''","rootBreakdown":{"prefix":null,"root":"casc (fall)","suffix":"-ade"},"relatedWords":["cascade","case","occasion"],"isEssential":false,"partOfSpeech":"noun","phonetic":"/kæˈskeɪdz/","contextSentence":"We''ve got cascades of lies coming out of Washington.","segmentIndex":54},{"word":"dissolving","definition":"the process of breaking down or disappearing; ceasing to exist as a distinct entity","meaningKo":"용해, 녹아 없어짐, 해소","etymology":"Latin ''dissolvere'' from ''dis-'' (apart) + ''solvere'' (to loosen)","rootBreakdown":{"prefix":"dis- (apart)","root":"solv (loosen)","suffix":"-ing"},"relatedWords":["dissolve","solve","resolution"],"isEssential":true,"partOfSpeech":"noun/gerund","phonetic":"/dɪˈzɒlvɪŋ/","contextSentence":"It''s the dissolving of self.","segmentIndex":194},{"word":"simultaneously","definition":"at the same time; occurring or existing at the same moment","meaningKo":"동시에, 일제히","etymology":"Latin ''simul'' meaning ''at the same time''","rootBreakdown":{"prefix":null,"root":"simul (same time)","suffix":"-taneously"},"relatedWords":["simultaneous","similar","simulate"],"isEssential":true,"partOfSpeech":"adverb","phonetic":"/ˌsaɪməlˈteɪniəsli/","contextSentence":"Yet I felt simultaneously overwhelmed with the light.","segmentIndex":205},{"word":"relationist","definition":"a person who prioritizes relationships and community bonds over individual achievement","meaningKo":"관계주의자, 관계를 우선시하는 사람","etymology":"Latin ''relatio'' (a bringing back, relation) + ''-ist'' (one who practices)","rootBreakdown":{"prefix":null,"root":"relat (carry back, relate)","suffix":"-ionist"},"relatedWords":["relation","relationship","relational"],"isEssential":false,"partOfSpeech":"noun/adjective","phonetic":"/rɪˈleɪʃənɪst/","contextSentence":"They''re living a relationist life.","segmentIndex":153},{"word":"yearns","definition":"to have an intense feeling of longing for something or someone","meaningKo":"갈망하다, 그리워하다, 동경하다","etymology":"Old English ''giernan'' meaning ''to desire, long for''","rootBreakdown":{"prefix":null,"root":"yearn (desire)","suffix":"-s"},"relatedWords":["yearning","desire","long for"],"isEssential":true,"partOfSpeech":"verb","phonetic":"/jɜːrnz/","contextSentence":"The heart yearns for fusion with another, the soul yearns for righteousness.","segmentIndex":98}]'::jsonb, '[{"pattern":"Past perfect: had + past participle","explanation":"Used to describe an action completed before another past action. It establishes a timeline showing which event came first in the past.","explanationKo":"과거완료(had + 과거분사)는 과거의 어떤 시점보다 더 이전에 완료된 행동을 나타내요. ''이미 ~했었다''라는 의미로, 과거 속의 더 먼 과거를 표현해요.","examples":["My marriage had just ended.","My kids had left home for college or were leaving.","Conservatism had changed, so I''d lost a lot of those friends."],"segmentIndex":1},{"pattern":"Conditional: If + present simple (zero conditional)","explanation":"Used to express a general truth or habitual outcome. The ''if'' clause sets up a condition that always leads to the stated result.","explanationKo":"''If + 현재시제''는 일반적인 사실이나 항상 일어나는 결과를 표현할 때 사용해요. 조건이 충족되면 항상 같은 결과가 나온다는 의미예요.","examples":["If you open the kitchen drawers where there should have been utensils, there were Post-it notes.","If nobody has ever loved you, do you think you can be a good father?"],"segmentIndex":6},{"pattern":"The + comparative, the + comparative","explanation":"While not directly used in this pattern, David Brooks uses escalating parallel structures to show cause and effect chains. The repetition reinforces escalation.","explanationKo":"데이비드 브룩스는 병렬 구조의 반복을 통해 점점 강해지는 인과관계를 보여줘요. 반복이 상승 효과를 만들어요.","examples":["The message of the meritocracy is... The myth of the meritocracy is... The emotion of the meritocracy is... The anthropology of the meritocracy is... The evil of the meritocracy is..."],"segmentIndex":27},{"pattern":"Passive voice: was/were + past participle","explanation":"Used when the focus is on the experience or state rather than the agent. Common in personal narratives about emotions and situations.","explanationKo":"수동태(be동사 + 과거분사)는 행위자보다 경험이나 상태에 초점을 맞출 때 사용해요. 감정이나 상황에 대한 개인적 서술에서 자주 쓰여요.","examples":["I was humiliated by that failed commitment.","I was lonely.","He''d been held back, been through the foster care system."],"segmentIndex":2},{"pattern":"What + clause + is/was (cleft sentence for emphasis)","explanation":"A cleft sentence structure that emphasizes a specific piece of information by placing it in a ''what'' clause. It highlights the key point.","explanationKo":"''What + 절 + is/was'' 구조는 강조하고 싶은 정보를 ''what'' 절로 묶어서 특정 요점을 부각시키는 강조 구문이에요.","examples":["And so what I did is I lived alone in an apartment.","What we really yearn for is longing and love for another.","What they see is joy."],"segmentIndex":5},{"pattern":"Not A but B (contrast structure)","explanation":"Used to correct a potential assumption by negating one idea and presenting the true one. Creates a clear rhetorical contrast.","explanationKo":"''Not A but B'' 구조는 잘못된 가정을 부정하고 실제 사실을 제시할 때 사용해요. 명확한 수사적 대비를 만들어 내요.","examples":["You''re not a soul to be purified, you''re a set of skills to be maximized.","Joy is not the expansion of self, it''s the dissolving of self.","Not just as a word, but as a reality."],"segmentIndex":30},{"pattern":"Present participle phrase as modifier","explanation":"A participial phrase (verb-ing) used to add descriptive or explanatory information about the subject. Keeps sentences flowing and concise.","explanationKo":"현재분사구(-ing)를 사용하여 주어에 대한 설명을 간결하게 덧붙이는 구조예요. 문장을 자연스럽게 이어 줘요.","examples":["Just making bad decisions or just fluidity.","Not reaching out, failing to show up for my friends, evasion, avoiding conflict.","Looking for her friends, wondering where her handbag was."],"segmentIndex":34},{"pattern":"Modal should + have + past participle (past obligation/expectation)","explanation":"Used to express an expectation about the past that was not fulfilled. It implies something was expected but didn''t happen.","explanationKo":"''should have + 과거분사''는 과거에 기대했지만 실현되지 않은 일을 표현해요. ''~이 있었어야 했는데''라는 의미로, 기대와 현실의 차이를 나타내요.","examples":["Where there should have been utensils.","Where there should have been plates."],"segmentIndex":6},{"pattern":"Either A or B (presenting alternatives)","explanation":"Used to present two possibilities or choices. Often creates a dramatic contrast between outcomes.","explanationKo":"''Either A or B''는 두 가지 가능성이나 선택지를 제시할 때 사용해요. 결과 사이의 극적인 대비를 만들어 내요.","examples":["You can either be broken or you can be broken open."],"segmentIndex":66},{"pattern":"As + noun/saying + is/says (citing authority)","explanation":"Used to introduce a quote, proverb, or authoritative reference. It lends credibility to the speaker''s argument.","explanationKo":"''As + 명사/속담''은 인용문이나 권위 있는 참조를 소개할 때 사용해요. 화자의 주장에 신뢰성을 부여해요.","examples":["As the saying is, pain that is not transformed gets transmitted.","The Greeks used to say, you suffer your way to wisdom.","As she writes, a rail-thin man with enormous eyes reached across."],"segmentIndex":69}]'::jsonb, '[{"type":"linking","originalText":"had one in","phonetic":"/hædˈwʌnɪn/","koreanPhonetic":"해드워닌","explanation":"The /d/ at the end of ''had'' links to the /w/ of ''one,'' and the /n/ of ''one'' links directly to the /ɪ/ of ''in,'' creating a smooth three-word chain.","explanationKo":"''had''의 /d/가 ''one''의 /w/와 연결되고, ''one''의 /n/이 ''in''의 /ɪ/와 이어져 세 단어가 자연스러운 연쇄를 이뤄요.","practiceGuide":"''해드 원 인''이 아니라 ''해드워닌''처럼 세 단어를 끊김 없이 이어서 발음해 보세요.","segmentIndex":1},{"type":"reduction","originalText":"a lot of","phonetic":"/əˈlɒtə/","koreanPhonetic":"얼라러","explanation":"The word ''of'' is reduced to schwa /ə/, and the /t/ of ''lot'' flaps to a soft /ɾ/ between vowels. ''A lot of'' sounds like ''a lotta'' in natural speech.","explanationKo":"''of''가 /ə/로 축약되고, ''lot''의 /t/가 모음 사이에서 가벼운 탄설음 /ɾ/로 변해서 ''얼라러''처럼 들려요.","practiceGuide":"''어 랏 오브''라고 또박또박 발음하지 말고, ''얼라러''처럼 ''of''를 가볍게 /ə/로만 발음하고 /t/도 부드럽게 해 보세요.","segmentIndex":4},{"type":"elision","originalText":"just worked","phonetic":"/dʒʌs wɜːrkt/","koreanPhonetic":"저스 워크트 → 저스워크트","explanation":"The /t/ at the end of ''just'' is often elided before the /w/ of ''worked.'' When a stop consonant meets another consonant, the first is frequently dropped.","explanationKo":"''just''의 마지막 /t/가 ''worked''의 /w/ 앞에서 탈락해요. 파열음이 다른 자음을 만나면 첫 번째가 자주 생략돼요.","practiceGuide":"''저스트 워크트''에서 /t/ 소리를 생략하고 ''저스워크트''처럼 자연스럽게 이어 보세요.","segmentIndex":6},{"type":"assimilation","originalText":"don''t have","phonetic":"/doʊnt hæv/ → /doʊn(t) hæv/","koreanPhonetic":"돈 해브","explanation":"The /t/ in ''don''t'' becomes unreleased or silent before the /h/ of ''have.'' The nasal /n/ carries the rhythm while the /t/ is barely articulated.","explanationKo":"''don''t''의 /t/가 ''have''의 /h/ 앞에서 거의 발음되지 않아요. 비음 /n/이 리듬을 유지하면서 /t/는 약하게 처리돼요.","practiceGuide":"''돈트 해브''라고 강하게 발음하지 말고, ''돈 해브''처럼 /t/를 거의 발음하지 않고 넘어가 보세요.","segmentIndex":9},{"type":"linking","originalText":"broken open","phonetic":"/ˈbroʊkən ˈoʊpən/","koreanPhonetic":"브로우크노우픈","explanation":"The /n/ at the end of ''broken'' links smoothly to the /oʊ/ of ''open,'' creating a nasal-to-vowel connection that binds the phrase into one unit.","explanationKo":"''broken''의 /n/이 ''open''의 /oʊ/와 자연스럽게 연결되어 비음에서 모음으로의 매끄러운 연결이 이루어져요.","practiceGuide":"''브로우큰 오우픈''이 아니라 ''브로우크노우픈''처럼 /n/과 /oʊ/를 끊지 않고 이어 보세요.","segmentIndex":66},{"type":"reduction","originalText":"sort of","phonetic":"/ˈsɔːrtə/","koreanPhonetic":"소러","explanation":"The phrase ''sort of'' is commonly reduced in casual speech. ''Of'' becomes a schwa /ə/, and the /t/ flaps, making it sound like ''sorta.''","explanationKo":"''sort of''는 일상 대화에서 흔히 축약돼요. ''of''가 /ə/로 약화되고 /t/가 탄설음으로 변해서 ''소러''처럼 들려요.","practiceGuide":"''소트 오브''라고 정확히 발음하지 말고, ''소러''처럼 빠르고 가볍게 발음해 보세요.","segmentIndex":37},{"type":"linking","originalText":"reach in and","phonetic":"/riːtʃ ɪn ænd/","koreanPhonetic":"리치내느","explanation":"The /tʃ/ of ''reach'' links to the /ɪ/ of ''in,'' and the /n/ of ''in'' links to the /æ/ of ''and.'' The phrase flows as a single connected unit.","explanationKo":"''reach''의 /tʃ/가 ''in''의 /ɪ/와 연결되고, ''in''의 /n/이 ''and''의 /æ/와 이어져서 전체가 하나의 덩어리처럼 흘러가요.","practiceGuide":"''리치 인 앤드''가 아니라 ''리치내느''처럼 자음과 모음을 이어 붙여서 발음해 보세요.","segmentIndex":115},{"type":"elision","originalText":"lost a lot","phonetic":"/lɒs ə lɒt/","koreanPhonetic":"로서랏","explanation":"The /t/ at the end of ''lost'' is elided before the schwa /ə/ of ''a,'' and then ''a lot'' connects with the flapped /t/ sounding like /ɾ/. The whole phrase simplifies.","explanationKo":"''lost''의 마지막 /t/가 ''a''의 /ə/ 앞에서 약해지고, ''a lot''이 연결되면서 전체 구절이 단순화돼요.","practiceGuide":"''로스트 어 랏''이라고 각각 끊어 말하지 말고, ''로서랏''처럼 자연스럽게 이어서 발음해 보세요.","segmentIndex":4}]'::jsonb, '{"sections":[{"section":"Personal Crisis: Loneliness and Cultural Lies","startSegment":0,"endSegment":16,"summary":"David Brooks shares his personal crisis in 2013 — his marriage ended, his children left home, and he lost friends. Living alone, consumed by work, he experienced profound loneliness and realized the emptiness in his life reflected the lies our culture tells us.","summaryKo":"데이비드 브룩스가 2013년의 개인적 위기를 나눠요. 결혼 생활이 끝나고, 아이들이 떠나고, 친구들을 잃었어요. 혼자 살면서 일에만 매달렸고, 깊은 외로움을 경험하며 삶의 공허함이 문화가 말하는 거짓말을 반영한다는 것을 깨달았어요.","keyPoints":["Personal crisis: divorce, children leaving, loss of friends","Loneliness manifested as fear and lack of solidity","The emptiness outside reflected emptiness within"]},{"section":"Three Cultural Lies About Success","startSegment":17,"endSegment":32,"summary":"Brooks identifies three cultural lies: (1) career success is fulfilling, (2) you can make yourself happy through self-sufficiency, and (3) the meritocracy — the belief that your worth equals your accomplishments. He argues that deep relationships, not achievements, create true happiness.","summaryKo":"브룩스는 세 가지 문화적 거짓말을 지적해요. (1) 직업적 성공이 만족을 준다, (2) 자급자족으로 행복해질 수 있다, (3) 능력주의 — 당신의 가치가 성취와 같다는 믿음이에요. 성취가 아니라 깊은 관계가 진정한 행복을 만든다고 주장해요.","keyPoints":["Career success only avoids shame, doesn''t bring positive good","Self-sufficiency is a lie; deep relationships make people happy","Meritocracy teaches conditional love and dehumanizing rankings"]},{"section":"A National Crisis of Disconnection","startSegment":33,"endSegment":55,"summary":"Brooks describes how his personal valley of disconnection mirrors a national crisis. He presents alarming statistics about loneliness, isolation, depression, and suicide in America, arguing that we face not just economic and environmental crises but a social and relational one.","summaryKo":"브룩스는 자신의 단절의 골짜기가 국가적 위기를 반영한다고 설명해요. 미국의 외로움, 고립, 우울증, 자살에 관한 충격적인 통계를 제시하며, 경제적 환경적 위기뿐 아니라 사회적이고 관계적인 위기에 직면해 있다고 주장해요.","keyPoints":["35% of Americans over 45 are chronically lonely","Suicide rate has risen 30% since 1999","Life expectancy is falling — a social and relational crisis exists"]},{"section":"Three Realizations from the Valley","startSegment":56,"endSegment":88,"summary":"Brooks shares three realizations from his valley: (1) social freedom without roots leads to drift, (2) suffering can break you or break you open to deeper self-knowledge, and (3) the heart yearns for love and fusion with others. He illustrates with the theologian Paul Tillich and a passage from Captain Corelli''s Mandolin.","summaryKo":"브룩스는 골짜기에서 얻은 세 가지 깨달음을 나눠요. (1) 뿌리 없는 사회적 자유는 방황으로 이끈다, (2) 고통은 부서지게도, 열리게도 할 수 있다, (3) 마음은 사랑과 타인과의 융합을 갈망한다는 거예요. 신학자 폴 틸리히와 코렐리 대위의 만돌린을 인용해요.","keyPoints":["Freedom is a river to cross, not an ocean to swim in","Suffering carves deeper into the soul, revealing unknown depths","True love is what remains after being in love burns away"]},{"section":"The Soul and Infinite Dignity","startSegment":89,"endSegment":113,"summary":"Brooks explores the soul and consciousness. He argues that everyone has a soul of infinite dignity regardless of status. The soul yearns for righteousness while the heart yearns for connection. Borrowing from Einstein, he says problems can''t be solved at the level of consciousness that created them.","summaryKo":"브룩스는 영혼과 의식을 탐구해요. 지위에 관계없이 모든 사람에게 무한한 존엄성의 영혼이 있다고 주장해요. 영혼은 올바름을 갈망하고 마음은 연결을 갈망해요. 아인슈타인을 인용하여 문제를 만든 의식 수준에서는 문제를 해결할 수 없다고 말해요.","keyPoints":["Every person has a soul with infinite dignity and value","The soul yearns for righteousness, the heart for fusion","You must expand to a different level of consciousness to solve problems"]},{"section":"Stories of Weavers: Community Builders","startSegment":114,"endSegment":171,"summary":"Brooks shares stories of ''weavers'' — community builders who pull others out of valleys. He describes Kathy and David''s home that welcomed 25 kids, Aisha Butler who chose to stay and rebuild her neighborhood, Sarah who turned tragedy into service, and the Roots of Empathy program that teaches children through caring for an infant.","summaryKo":"브룩스는 ''위버'' — 다른 사람을 골짜기에서 끌어올리는 공동체 건설자들의 이야기를 나눠요. 25명의 아이를 환영한 캐시와 데이비드의 집, 동네를 재건하기로 한 아이샤 버틀러, 비극을 봉사로 바꾼 세라, 아기 돌봄을 통해 아이들에게 공감을 가르치는 공감의 뿌리 프로그램을 소개해요.","keyPoints":["You can''t climb out of a valley alone — someone must reach in","Weavers live relationist lives with moral motivation and vocational certitude","Stories of Kathy & David, Aisha Butler, Sarah, and Roots of Empathy"]},{"section":"Happiness vs. Joy: Dissolving the Self","startSegment":172,"endSegment":209,"summary":"Brooks distinguishes between happiness (expansion of self) and joy (dissolving of self). He uses E.O. Wilson''s childhood awe at nature and Zadie Smith''s ecstatic night at a London club to illustrate joy — moments when self-consciousness disappears and one is fully given over to the experience.","summaryKo":"브룩스는 행복(자아의 확장)과 기쁨(자아의 용해)을 구분해요. E.O. 윌슨의 자연에 대한 어린 시절의 경외와 재디 스미스의 런던 클럽에서의 황홀한 밤을 통해 기쁨을 설명해요 — 자의식이 사라지고 경험에 완전히 빠지는 순간이에요.","keyPoints":["Happiness is expansion of self; joy is dissolving of self","E.O. Wilson''s childhood encounter with nature illustrates awe and vocation","Zadie Smith''s nightclub experience captures the surrender to joy"]},{"section":"Two Mindsets: Individual Success vs. Relational Living","startSegment":210,"endSegment":230,"summary":"Brooks contrasts two mindsets: the ''first mountain'' mindset of individual success and the relational mindset needed to heal our national valley. He calls for a cultural and relational revolution, arguing that weavers have found a better way to live, and if we follow their example, both personal emptiness and social fragmentation can be repaired.","summaryKo":"브룩스는 두 가지 사고방식을 대비해요: 개인적 성공의 ''첫 번째 산'' 사고방식과 국가적 골짜기를 치유하는 데 필요한 관계적 사고방식이에요. 문화적이고 관계적인 혁명을 촉구하며, 위버들이 더 나은 삶의 방식을 찾았고 그 본보기를 따르면 개인의 공허함과 사회적 분열 모두 회복될 수 있다고 주장해요.","keyPoints":["Two mindsets: first mountain (individual success) vs. relational living","We need a cultural and relational revolution, not just economic fixes","Weavers show a better way — we just need to shift our lives a little"]}],"signalExpressions":[{"expression":"So we all have bad seasons in life","type":"emphasis","segmentIndex":0,"role":"청중의 공감을 유도하는 도입부 — 보편적인 경험으로 시작하여 주의를 끌어요"},{"expression":"And I had one in 2013","type":"transition","segmentIndex":1,"role":"일반적인 이야기에서 개인적 경험으로 전환하며 구체적인 서사를 시작해요"},{"expression":"The first lie is that career success is fulfilling","type":"transition","segmentIndex":17,"role":"핵심 주장의 첫 번째 항목을 소개하며 논리적 구조를 세워요"},{"expression":"The second lie is I can make myself happy","type":"transition","segmentIndex":20,"role":"두 번째 거짓말로 전환하며 병렬 구조를 유지해요"},{"expression":"The third lie is the lie of the meritocracy","type":"transition","segmentIndex":26,"role":"세 번째 거짓말을 소개하며 가장 깊은 분석으로 들어가요"},{"expression":"So what do I mean to tell you?","type":"transition","segmentIndex":51,"role":"개인 이야기에서 사회적 메시지로 전환하며 강연의 핵심 목적을 밝혀요"},{"expression":"How do you get out of a valley?","type":"transition","segmentIndex":56,"role":"문제 제기에서 해결책으로 전환하는 수사적 질문이에요"},{"expression":"The first is, freedom sucks","type":"emphasis","segmentIndex":58,"role":"충격적인 표현으로 주의를 집중시키며 첫 번째 깨달음을 소개해요"},{"expression":"The second thing I learned is that","type":"transition","segmentIndex":65,"role":"두 번째 깨달음으로 자연스럽게 전환해요"},{"expression":"The hard thing about when you''re in the valley is","type":"transition","segmentIndex":114,"role":"이론에서 실천적 이야기로 전환하며 위버들의 등장을 준비해요"},{"expression":"And so what I''m trying to describe is two different live mindsets","type":"summary","segmentIndex":210,"role":"전체 강연의 핵심을 요약하며 결론부로 진입해요"},{"expression":"My theory of social change is that society changes","type":"summary","segmentIndex":221,"role":"최종 메시지를 전달하며 행동을 촉구하는 마무리를 시작해요"}]}'::jsonb
)
