) VALUES (
  'en', 'BHY0FxzoKZE', '{"videoId":"BHY0FxzoKZE","youtubeId":"BHY0FxzoKZE","title":"The Brain-Changing Benefits of Exercise | Wendy Suzuki | TED","channel":"TED","categoryId":"academic","difficulty":"intermediate","duration":783,"thumbnail":"https://i.ytimg.com/vi_webp/BHY0FxzoKZE/maxresdefault.webp","speechRateWpm":147,"addedAt":"2026-02-16","segmentCount":204,"vocabularyCount":25,"grammarPatternCount":12,"descriptionKo":"운동이 뇌를 바꾼다 — 신경과학자가 밝히는 운동의 놀라운 효과"}'::jsonb, '{"videoId":"BHY0FxzoKZE","segments":[{"index":0,"start":0.0,"end":16.58,"textEn":"Reviewer. What if I told you there was something that you can do right now","textKo":"지금 바로 할 수 있는 무언가가 있다고 말씀드리면 어떨까요?","words":[{"word":"Reviewer.","start":0.0,"end":0.8},{"word":"What","start":12.64,"end":13.0},{"word":"if","start":13.0,"end":13.3},{"word":"I","start":13.3,"end":13.42},{"word":"told","start":13.42,"end":13.72},{"word":"you","start":13.72,"end":14.04},{"word":"there","start":14.04,"end":14.46},{"word":"was","start":14.46,"end":14.58},{"word":"something","start":14.58,"end":14.9},{"word":"that","start":14.9,"end":15.14},{"word":"you","start":15.14,"end":15.28},{"word":"can","start":15.28,"end":15.44},{"word":"do","start":15.44,"end":15.72},{"word":"right","start":15.72,"end":16.08},{"word":"now","start":16.08,"end":16.58}],"listenDifficulty":3},{"index":1,"start":17.18,"end":20.6,"textEn":"That would have an immediate positive benefit for your brain,","textKo":"여러분의 뇌에 즉각적이고 긍정적인 효과를 가져다줄","words":[{"word":"that","start":16.96,"end":17.32},{"word":"would","start":17.32,"end":17.46},{"word":"have","start":17.46,"end":17.7},{"word":"an","start":17.7,"end":17.92},{"word":"immediate","start":17.92,"end":18.44},{"word":"positive","start":18.44,"end":19.08},{"word":"benefit","start":19.08,"end":19.68},{"word":"for","start":19.68,"end":20.04},{"word":"your","start":20.04,"end":20.22},{"word":"brain,","start":20.22,"end":20.6}],"listenDifficulty":2},{"index":2,"start":20.74,"end":23.3,"textEn":"Including your mood and your focus?","textKo":"기분과 집중력을 포함해서요.","words":[{"word":"including","start":20.74,"end":21.32},{"word":"your","start":21.32,"end":21.74},{"word":"mood","start":21.74,"end":22.16},{"word":"and","start":22.16,"end":22.68},{"word":"your","start":22.68,"end":22.84},{"word":"focus?","start":22.84,"end":23.3}],"listenDifficulty":1},{"index":3,"start":23.74,"end":26.1,"textEn":"And what if I told you that same thing","textKo":"그리고 그 같은 것이","words":[{"word":"And","start":23.74,"end":24.38},{"word":"what","start":24.38,"end":24.56},{"word":"if","start":24.56,"end":24.68},{"word":"I","start":24.68,"end":24.78},{"word":"told","start":24.78,"end":24.98},{"word":"you","start":24.98,"end":25.1},{"word":"that","start":25.1,"end":25.26},{"word":"same","start":25.26,"end":25.62},{"word":"thing","start":25.62,"end":26.1}],"listenDifficulty":3},{"index":4,"start":26.1,"end":29.38,"textEn":"Could actually last a long time","textKo":"실제로 오랫동안 지속될 수 있고","words":[{"word":"could","start":26.1,"end":26.76},{"word":"actually","start":26.76,"end":27.26},{"word":"last","start":27.26,"end":27.94},{"word":"a","start":27.94,"end":28.36},{"word":"long","start":28.36,"end":28.68},{"word":"time","start":28.68,"end":29.38}],"listenDifficulty":2},{"index":5,"start":29.38,"end":32.22,"textEn":"And protect your brain from different conditions","textKo":"다양한 질환으로부터 여러분의 뇌를 보호해 줄 수 있다면요.","words":[{"word":"and","start":29.38,"end":29.82},{"word":"protect","start":29.82,"end":30.26},{"word":"your","start":30.26,"end":30.5},{"word":"brain","start":30.5,"end":30.86},{"word":"from","start":30.86,"end":31.48},{"word":"different","start":31.48,"end":31.8},{"word":"conditions","start":31.8,"end":32.22}],"listenDifficulty":2},{"index":6,"start":32.22,"end":35.66,"textEn":"Like depression, Alzheimer''s disease or dementia?","textKo":"우울증이나 알츠하이머병, 또는 치매 같은 것들 말이에요.","words":[{"word":"like","start":32.22,"end":32.54},{"word":"depression,","start":32.54,"end":33.54},{"word":"Alzheimer''s","start":34.0,"end":34.68},{"word":"disease","start":34.68,"end":34.98},{"word":"or","start":34.98,"end":35.24},{"word":"dementia?","start":35.24,"end":35.66}],"listenDifficulty":2},{"index":7,"start":36.0,"end":38.26,"textEn":"Would you do it? Yes.","textKo":"하시겠어요? 네!","words":[{"word":"Would","start":36.0,"end":36.46},{"word":"you","start":36.46,"end":36.56},{"word":"do","start":36.56,"end":36.72},{"word":"it?","start":36.72,"end":36.96},{"word":"Yes.","start":37.6,"end":38.26}],"listenDifficulty":1},{"index":8,"start":38.68,"end":43.62,"textEn":"I am talking about the powerful effects of physical activity","textKo":"저는 신체 활동의 강력한 효과에 대해 이야기하고 있습니다.","words":[{"word":"I","start":38.68,"end":39.22},{"word":"am","start":39.22,"end":39.4},{"word":"talking","start":39.4,"end":39.88},{"word":"about","start":39.88,"end":40.4},{"word":"the","start":40.4,"end":40.68},{"word":"powerful","start":40.68,"end":41.26},{"word":"effects","start":41.26,"end":41.86},{"word":"of","start":41.86,"end":42.5},{"word":"physical","start":42.5,"end":42.98},{"word":"activity","start":42.98,"end":43.62}],"listenDifficulty":1},{"index":9,"start":43.62,"end":45.66,"textEn":"That is simply moving your body,","textKo":"단순히 몸을 움직이는 것,","words":[{"word":"that","start":43.62,"end":43.86},{"word":"is","start":43.86,"end":44.02},{"word":"simply","start":44.02,"end":44.44},{"word":"moving","start":44.44,"end":44.98},{"word":"your","start":44.98,"end":45.22},{"word":"body,","start":45.22,"end":45.66}],"listenDifficulty":2},{"index":10,"start":45.82,"end":51.28,"textEn":"Has immediate, long-lasting and protective benefits for your brain,","textKo":"그것이 여러분의 뇌에 즉각적이고 오래 지속되며 보호적인 효과를 줍니다.","words":[{"word":"has","start":45.82,"end":46.48},{"word":"immediate,","start":46.48,"end":47.26},{"word":"long","start":47.54,"end":48.06},{"word":"-lasting","start":48.06,"end":48.62},{"word":"and","start":48.62,"end":49.14},{"word":"protective","start":49.14,"end":49.72},{"word":"benefits","start":49.72,"end":50.32},{"word":"for","start":50.32,"end":50.62},{"word":"your","start":50.62,"end":50.84},{"word":"brain,","start":50.84,"end":51.28}],"listenDifficulty":2},{"index":11,"start":51.44,"end":53.68,"textEn":"And that can last for the rest of your life.","textKo":"그리고 그것은 여러분의 남은 인생 동안 지속될 수 있습니다.","words":[{"word":"and","start":51.44,"end":52.1},{"word":"that","start":52.1,"end":52.22},{"word":"can","start":52.22,"end":52.34},{"word":"last","start":52.34,"end":52.64},{"word":"for","start":52.64,"end":52.82},{"word":"the","start":52.82,"end":52.9},{"word":"rest","start":52.9,"end":53.1},{"word":"of","start":53.1,"end":53.22},{"word":"your","start":53.22,"end":53.34},{"word":"life.","start":53.34,"end":53.68}],"listenDifficulty":3},{"index":12,"start":53.92,"end":56.28,"textEn":"So what I want to do today is tell you a story","textKo":"그래서 오늘 제가 하고 싶은 것은 여러분에게 이야기를 하나 들려드리는 것입니다.","words":[{"word":"So","start":53.92,"end":54.34},{"word":"what","start":54.34,"end":54.54},{"word":"I","start":54.54,"end":54.66},{"word":"want","start":54.66,"end":54.76},{"word":"to","start":54.76,"end":54.86},{"word":"do","start":54.86,"end":55.0},{"word":"today","start":55.0,"end":55.24},{"word":"is","start":55.24,"end":55.38},{"word":"tell","start":55.38,"end":55.62},{"word":"you","start":55.62,"end":55.76},{"word":"a","start":55.76,"end":55.88},{"word":"story","start":55.88,"end":56.28}],"listenDifficulty":4},{"index":13,"start":56.28,"end":60.86,"textEn":"About how I used my deep understanding of neuroscience,","textKo":"신경과학에 대한 저의 깊은 이해를 어떻게 활용했는지에 대해서요.","words":[{"word":"about","start":56.28,"end":56.74},{"word":"how","start":56.74,"end":57.26},{"word":"I","start":57.26,"end":57.64},{"word":"used","start":57.64,"end":57.96},{"word":"my","start":57.96,"end":58.16},{"word":"deep","start":58.16,"end":58.54},{"word":"understanding","start":58.54,"end":59.34},{"word":"of","start":59.34,"end":60.12},{"word":"neuroscience,","start":60.12,"end":60.86}],"listenDifficulty":2},{"index":14,"start":61.12,"end":65.2,"textEn":"As a professor of neuroscience, to essentially do an experiment on myself,","textKo":"신경과학 교수로서, 본질적으로 저 자신에게 실험을 했습니다.","words":[{"word":"as","start":61.12,"end":61.36},{"word":"a","start":61.36,"end":61.44},{"word":"professor","start":61.44,"end":61.78},{"word":"of","start":61.78,"end":61.94},{"word":"neuroscience,","start":61.94,"end":62.46},{"word":"to","start":62.72,"end":63.14},{"word":"essentially","start":63.14,"end":63.48},{"word":"do","start":63.48,"end":63.78},{"word":"an","start":63.78,"end":63.92},{"word":"experiment","start":63.92,"end":64.36},{"word":"on","start":64.36,"end":64.7},{"word":"myself,","start":64.7,"end":65.2}],"listenDifficulty":3},{"index":15,"start":65.6,"end":69.78,"textEn":"In which I discovered the science underlying why exercise","textKo":"그 실험을 통해 왜 운동이","words":[{"word":"in","start":65.6,"end":65.94},{"word":"which","start":65.94,"end":66.14},{"word":"I","start":66.14,"end":66.38},{"word":"discovered","start":66.38,"end":66.9},{"word":"the","start":66.9,"end":67.14},{"word":"science","start":67.14,"end":67.72},{"word":"underlying","start":67.72,"end":68.48},{"word":"why","start":68.48,"end":69.14},{"word":"exercise","start":69.14,"end":69.78}],"listenDifficulty":1},{"index":16,"start":69.78,"end":74.52,"textEn":"Is the most transformative thing that you can do for your brain today.","textKo":"오늘날 여러분의 뇌를 위해 할 수 있는 가장 혁신적인 것인지 그 과학을 발견했습니다.","words":[{"word":"is","start":69.78,"end":70.48},{"word":"the","start":70.48,"end":70.78},{"word":"most","start":70.78,"end":71.22},{"word":"transformative","start":71.22,"end":71.94},{"word":"thing","start":71.94,"end":72.4},{"word":"that","start":72.4,"end":72.9},{"word":"you","start":72.9,"end":73.0},{"word":"can","start":73.0,"end":73.18},{"word":"do","start":73.18,"end":73.48},{"word":"for","start":73.48,"end":73.78},{"word":"your","start":73.78,"end":73.92},{"word":"brain","start":73.92,"end":74.2},{"word":"today.","start":74.2,"end":74.52}],"listenDifficulty":3},{"index":17,"start":74.52,"end":78.98,"textEn":"Now, as a neuroscientist, I know that our brains,","textKo":"자, 신경과학자로서 저는 우리의 뇌가,","words":[{"word":"Now,","start":74.52,"end":75.48},{"word":"as","start":75.62,"end":75.68},{"word":"a","start":75.68,"end":75.78},{"word":"neuroscientist,","start":75.78,"end":77.54},{"word":"I","start":77.64,"end":77.76},{"word":"know","start":77.76,"end":78.1},{"word":"that","start":78.1,"end":78.48},{"word":"our","start":78.48,"end":78.6},{"word":"brains,","start":78.6,"end":78.98}],"listenDifficulty":1},{"index":18,"start":79.04,"end":81.54,"textEn":"That is the thing in our head right now,","textKo":"바로 지금 우리 머릿속에 있는 이것이,","words":[{"word":"that","start":79.04,"end":79.2},{"word":"is","start":79.2,"end":79.36},{"word":"the","start":79.36,"end":79.92},{"word":"thing","start":79.92,"end":80.18},{"word":"in","start":80.18,"end":80.44},{"word":"our","start":80.44,"end":80.58},{"word":"head","start":80.58,"end":80.86},{"word":"right","start":80.86,"end":81.18},{"word":"now,","start":81.18,"end":81.54}],"listenDifficulty":3},{"index":19,"start":82.1,"end":86.68,"textEn":"That is the most complex structure known to humankind.","textKo":"인류에게 알려진 가장 복잡한 구조라는 것을 알고 있습니다.","words":[{"word":"that","start":82.1,"end":82.48},{"word":"is","start":82.48,"end":83.04},{"word":"the","start":83.04,"end":83.4},{"word":"most","start":83.4,"end":83.9},{"word":"complex","start":83.9,"end":84.46},{"word":"structure","start":84.46,"end":84.96},{"word":"known","start":84.96,"end":85.38},{"word":"to","start":85.38,"end":86.0},{"word":"humankind.","start":86.0,"end":86.68}],"listenDifficulty":1},{"index":20,"start":87.04,"end":89.7,"textEn":"But it''s one thing to talk about the brain,","textKo":"하지만 뇌에 대해 이야기하는 것과","words":[{"word":"But","start":87.04,"end":87.42},{"word":"it''s","start":87.42,"end":87.62},{"word":"one","start":87.62,"end":87.8},{"word":"thing","start":87.8,"end":88.12},{"word":"to","start":88.12,"end":88.54},{"word":"talk","start":88.54,"end":89.04},{"word":