INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'en', '8S0FDjFBj8o', '{"videoId":"8S0FDjFBj8o","youtubeId":"8S0FDjFBj8o","title":"How to sound smart in your TEDx Talk | Will Stephen | TEDxNewYork","channel":"TEDx Talks","categoryId":"daily","difficulty":"intermediate","duration":356,"thumbnail":"https://i.ytimg.com/vi_webp/8S0FDjFBj8o/maxresdefault.webp","speechRateWpm":177,"addedAt":"2026-02-16","segmentCount":71,"vocabularyCount":25,"grammarPatternCount":12,"descriptionKo":"아무 내용 없이 TED 강연처럼 보이는 법 — 유쾌한 패러디"}'::jsonb, '{"videoId":"8S0FDjFBj8o","segments":[{"index":0,"start":0.0,"end":4.54,"textEn":"Leonardo Silva Reviewer Reviewer","textKo":"레오나르도 실바 리뷰어 리뷰어","words":[{"word":"Leonardo","start":0.0,"end":0.62},{"word":"Silva","start":0.62,"end":0.62},{"word":"Reviewer","start":0.62,"end":1.36},{"word":"Reviewer","start":3.78,"end":4.54}],"listenDifficulty":1},{"index":1,"start":18.84,"end":23.26,"textEn":"Hear that? That''s nothing.","textKo":"들리시죠? 아무것도 아닙니다.","words":[{"word":"Hear","start":18.84,"end":19.6},{"word":"that?","start":19.6,"end":19.96},{"word":"That''s","start":21.74,"end":22.5},{"word":"nothing.","start":22.5,"end":23.26}],"listenDifficulty":2},{"index":2,"start":24.28,"end":27.72,"textEn":"Which is what I, as a speaker at today''s conference,","textKo":"이것이 바로 저, 오늘 컨퍼런스의 연사로서,","words":[{"word":"Which","start":24.28,"end":25.04},{"word":"is","start":25.04,"end":25.22},{"word":"what","start":25.22,"end":25.44},{"word":"I,","start":25.44,"end":25.84},{"word":"as","start":26.02,"end":26.54},{"word":"a","start":26.54,"end":26.62},{"word":"speaker","start":26.62,"end":26.9},{"word":"at","start":26.9,"end":27.06},{"word":"today''s","start":27.06,"end":27.34},{"word":"conference,","start":27.34,"end":27.72}],"listenDifficulty":2},{"index":3,"start":27.72,"end":31.32,"textEn":"Have for you all. I have nothing.","textKo":"여러분 모두에게 가지고 온 것입니다. 저는 아무것도 없습니다.","words":[{"word":"have","start":27.72,"end":28.66},{"word":"for","start":28.66,"end":28.82},{"word":"you","start":28.82,"end":28.94},{"word":"all.","start":28.94,"end":29.14},{"word":"I","start":29.88,"end":30.56},{"word":"have","start":30.56,"end":30.96},{"word":"nothing.","start":30.96,"end":31.32}],"listenDifficulty":1},{"index":4,"start":32.04,"end":34.1,"textEn":"Nada. Zip.","textKo":"나다. 집.","words":[{"word":"Nada.","start":32.04,"end":32.72},{"word":"Zip.","start":33.46,"end":34.1}],"listenDifficulty":1},{"index":5,"start":34.72,"end":36.74,"textEn":"Zilch. Zippo.","textKo":"질치. 지포.","words":[{"word":"Zilch.","start":34.72,"end":35.4},{"word":"Zippo.","start":36.06,"end":36.74}],"listenDifficulty":1},{"index":6,"start":37.58,"end":40.34,"textEn":"Nothing smart. Nothing inspirational.","textKo":"똑똑한 것도 없습니다. 영감을 주는 것도 없습니다.","words":[{"word":"Nothing","start":37.58,"end":38.26},{"word":"smart.","start":38.26,"end":38.68},{"word":"Nothing","start":39.04,"end":39.72},{"word":"inspirational.","start":39.72,"end":40.34}],"listenDifficulty":2},{"index":7,"start":40.6,"end":45.9,"textEn":"Nothing even remotely researched at all. I have absolutely nothing to say whatsoever.","textKo":"조금이라도 조사한 것조차 없습니다. 저는 정말 할 말이 전혀 없습니다.","words":[{"word":"Nothing","start":40.6,"end":40.74},{"word":"even","start":40.74,"end":40.94},{"word":"remotely","start":40.94,"end":41.32},{"word":"researched","start":41.32,"end":41.88},{"word":"at","start":41.88,"end":42.22},{"word":"all.","start":42.22,"end":42.5},{"word":"I","start":43.16,"end":43.84},{"word":"have","start":43.84,"end":44.02},{"word":"absolutely","start":44.02,"end":44.56},{"word":"nothing","start":44.56,"end":44.9},{"word":"to","start":44.9,"end":45.12},{"word":"say","start":45.12,"end":45.36},{"word":"whatsoever.","start":45.36,"end":45.9}],"listenDifficulty":2},{"index":8,"start":46.7,"end":49.26,"textEn":"And yet, through my manner of speaking,","textKo":"그럼에도 불구하고, 제 말하는 방식을 통해,","words":[{"word":"And","start":46.7,"end":47.38},{"word":"yet,","start":47.38,"end":47.64},{"word":"through","start":47.78,"end":48.1},{"word":"my","start":48.1,"end":48.38},{"word":"manner","start":48.38,"end":48.64},{"word":"of","start":48.64,"end":48.84},{"word":"speaking,","start":48.84,"end":49.26}],"listenDifficulty":3},{"index":9,"start":49.3,"end":55.14,"textEn":"I will make it seem like I do. Like what I am saying is brilliant.","textKo":"마치 뭔가 있는 것처럼 보이게 할 것입니다. 제가 하는 말이 훌륭한 것처럼요.","words":[{"word":"I","start":49.3,"end":49.54},{"word":"will","start":49.54,"end":49.7},{"word":"make","start":49.7,"end":49.88},{"word":"it","start":49.88,"end":50.02},{"word":"seem","start":50.02,"end":50.26},{"word":"like","start":50.26,"end":50.5},{"word":"I","start":50.5,"end":50.64},{"word":"do.","start":50.64,"end":50.9},{"word":"Like","start":52.76,"end":53.44},{"word":"what","start":53.44,"end":53.62},{"word":"I","start":53.62,"end":53.74},{"word":"am","start":53.74,"end":53.86},{"word":"saying","start":53.86,"end":54.16},{"word":"is","start":54.16,"end":54.54},{"word":"brilliant.","start":54.54,"end":55.14}],"listenDifficulty":4},{"index":10,"start":55.98,"end":60.76,"textEn":"And maybe, just maybe, you will feel like you''ve learned something.","textKo":"그리고 아마도, 정말 아마도, 여러분은 무언가를 배운 것 같은 느낌이 들 것입니다.","words":[{"word":"And","start":55.98,"end":56.28},{"word":"maybe,","start":56.28,"end":56.58},{"word":"just","start":56.82,"end":57.22},{"word":"maybe,","start":57.22,"end":57.6},{"word":"you","start":57.84,"end":58.36},{"word":"will","start":58.36,"end":58.5},{"word":"feel","start":58.5,"end":58.9},{"word":"like","start":58.9,"end":59.92},{"word":"you''ve","start":59.92,"end":60.14},{"word":"learned","start":60.14,"end":60.36},{"word":"something.","start":60.36,"end":60.76}],"listenDifficulty":3},{"index":11,"start":63.32,"end":66.56,"textEn":"Now, I''m going to get started with the opening. I''m going to make a lot of hand gestures.","textKo":"자, 오프닝부터 시작하겠습니다. 손동작을 많이 할 겁니다.","words":[{"word":"Now,","start":63.32,"end":63.62},{"word":"I''m","start":63.62,"end":63.92},{"word":"going","start":63.92,"end":63.98},{"word":"to","start":63.98,"end":64.0},{"word":"get","start":64.0,"end":64.1},{"word":"started","start":64.1,"end":64.42},{"word":"with","start":64.42,"end":64.54},{"word":"the","start":64.54,"end":64.66},{"word":"opening.","start":64.66,"end":64.94},{"word":"I''m","start":65.18,"end":65.48},{"word":"going","start":65.48,"end":65.52},{"word":"to","start":65.52,"end":65.56},{"word":"make","start":65.56,"end":65.66},{"word":"a","start":65.66,"end":65.76},{"word":"lot","start":65.76,"end":65.82},{"word":"of","start":65.82,"end":65.92},{"word":"hand","start":65.92,"end":66.14},{"word":"gestures.","start":66.14,"end":66.56}],"listenDifficulty":5},{"index":12,"start":67.0,"end":69.46,"textEn":"I''m going to do this with my right hand. I''m going to do this with my left.","textKo":"오른손으로 이렇게 할 겁니다. 왼손으로 이렇게 할 겁니다.","words":[{"word":"I''m","start":67.0,"end":67.3},{"word":"going","start":67.3,"end":67.34},{"word":"to","start":67.34,"end":67.4},{"word":"do","start":67.4,"end":67.5},{"word":"this","start":67.5,"end":67.66},{"word":"with","start":67.66,"end":67.78},{"word":"my","start":67.78,"end":67.9},{"word":"right","start":67.9,"end":68.1},{"word":"hand.","start":68.1,"end":68.32},{"word":"I''m","start":68.44,"end":68.52},{"word":"going","start":68.52,"end":68.6},{"word":"to","start":68.6,"end":68.68},{"word":"do","start":68.68,"end":68.78},{"word":"this","start":68.78,"end":68.92},{"word":"with","start":68.92,"end":69.02},{"word":"my","start":69.02,"end":69.18},{"word":"left.","start":69.18,"end":69.46}],"listenDifficulty":3},{"index":13,"start":69.66,"end":73.52,"textEn":"I''m going to adjust my glasses. And then I''m going to ask you all a question.","textKo":"안경을 고쳐 쓸 겁니다. 그리고 나서 여러분 모두에게 질문을 하나 하겠습니다.","words":[{"word":"I''m","start":69.66,"end":69.96},{"word":"going","start":69.96,"end":70.04},{"word":"to","start":70.04,"end":70.12},{"word":"adjust","start":70.12,"end":70.34},{"word":"my","start":70.34,"end":70.52},{"word":"glasses.","start":70.52,"end":70.96},{"word":"And","start":71.8,"end":72.1},{"wor