INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'en', 'TFbv757kup4', '{"videoId":"TFbv757kup4","youtubeId":"TFbv757kup4","title":"The Secret of Becoming Mentally Strong | Amy Morin | TEDxOcala","channel":"TEDx Talks","categoryId":"motivation","difficulty":"intermediate","duration":901,"thumbnail":"https://i.ytimg.com/vi/TFbv757kup4/hqdefault.jpg","speechRateWpm":162,"addedAt":"2026-02-16","segmentCount":180,"vocabularyCount":25,"grammarPatternCount":12,"descriptionKo":"정신적으로 강해지는 비밀 — 나쁜 습관 3가지를 버려라"}'::jsonb, '{"videoId":"TFbv757kup4","segments":[{"index":0,"start":0.0,"end":8.14,"textEn":"Reviewer Gisela C. Reviewer. So I have a Facebook friend whose life seems perfect.","textKo":"리뷰어 지젤라 C. 리뷰어. 저에게는 완벽한 삶을 사는 것처럼 보이는 페이스북 친구가 있어요.","words":[{"word":"Reviewer","start":0.0,"end":0.64},{"word":"Gisela","start":0.64,"end":0.64},{"word":"C.","start":0.64,"end":0.64},{"word":"Reviewer.","start":0.64,"end":0.64},{"word":"So","start":4.32,"end":4.76},{"word":"I","start":4.76,"end":4.96},{"word":"have","start":4.96,"end":5.14},{"word":"a","start":5.14,"end":5.26},{"word":"Facebook","start":5.26,"end":5.62},{"word":"friend","start":5.62,"end":6.06},{"word":"whose","start":6.06,"end":6.92},{"word":"life","start":6.92,"end":7.18},{"word":"seems","start":7.18,"end":7.54},{"word":"perfect.","start":7.54,"end":8.14}],"listenDifficulty":3},{"index":1,"start":9.32,"end":13.6,"textEn":"She lives in a gorgeous house, and she has a really rewarding career.","textKo":"그녀는 멋진 집에 살고, 정말 보람 있는 직업을 가지고 있어요.","words":[{"word":"She","start":9.32,"end":9.76},{"word":"lives","start":9.76,"end":9.96},{"word":"in","start":9.96,"end":10.08},{"word":"a","start":10.08,"end":10.18},{"word":"gorgeous","start":10.18,"end":10.48},{"word":"house,","start":10.48,"end":11.06},{"word":"and","start":11.56,"end":12.0},{"word":"she","start":12.0,"end":12.1},{"word":"has","start":12.1,"end":12.18},{"word":"a","start":12.18,"end":12.28},{"word":"really","start":12.28,"end":12.5},{"word":"rewarding","start":12.5,"end":13.02},{"word":"career.","start":13.02,"end":13.6}],"listenDifficulty":2},{"index":2,"start":14.46,"end":17.66,"textEn":"And she and her family go on all these exciting adventures together","textKo":"그리고 그녀와 가족은 함께 이 모든 신나는 모험을 떠나요","words":[{"word":"And","start":14.46,"end":14.9},{"word":"she","start":14.9,"end":15.06},{"word":"and","start":15.06,"end":15.2},{"word":"her","start":15.2,"end":15.3},{"word":"family","start":15.3,"end":15.62},{"word":"go","start":15.62,"end":15.8},{"word":"on","start":15.8,"end":16.0},{"word":"all","start":16.0,"end":16.22},{"word":"these","start":16.22,"end":16.4},{"word":"exciting","start":16.4,"end":16.84},{"word":"adventures","start":16.84,"end":17.3},{"word":"together","start":17.3,"end":17.66}],"listenDifficulty":2},{"index":3,"start":17.66,"end":23.06,"textEn":"On the weekends, and I swear that they must take a professional photographer along with them,","textKo":"주말마다, 그리고 저는 그들이 전문 사진작가를 함께 데리고 다니는 것 같다고 확신해요,","words":[{"word":"on","start":17.66,"end":17.92},{"word":"the","start":17.92,"end":18.0},{"word":"weekends,","start":18.0,"end":18.44},{"word":"and","start":19.2,"end":19.64},{"word":"I","start":19.64,"end":19.74},{"word":"swear","start":19.74,"end":20.1},{"word":"that","start":20.1,"end":20.3},{"word":"they","start":20.3,"end":20.42},{"word":"must","start":20.42,"end":20.64},{"word":"take","start":20.64,"end":20.84},{"word":"a","start":20.84,"end":20.96},{"word":"professional","start":20.96,"end":21.52},{"word":"photographer","start":21.52,"end":22.14},{"word":"along","start":22.14,"end":22.54},{"word":"with","start":22.54,"end":22.76},{"word":"them,","start":22.76,"end":23.06}],"listenDifficulty":2},{"index":4,"start":24.06,"end":26.3,"textEn":"Because no matter where they go or what they do,","textKo":"왜냐하면 어디를 가든 무엇을 하든,","words":[{"word":"because","start":24.06,"end":24.5},{"word":"no","start":24.5,"end":24.66},{"word":"matter","start":24.66,"end":24.82},{"word":"where","start":24.82,"end":25.0},{"word":"they","start":25.0,"end":25.22},{"word":"go","start":25.22,"end":25.44},{"word":"or","start":25.44,"end":25.66},{"word":"what","start":25.66,"end":25.84},{"word":"they","start":25.84,"end":26.02},{"word":"do,","start":26.02,"end":26.3}],"listenDifficulty":3},{"index":5,"start":26.48,"end":32.88,"textEn":"The whole family just looks beautiful. And she''s always posting about how blessed she is","textKo":"온 가족이 정말 아름답게 보여요. 그리고 그녀는 항상 자신이 얼마나 축복받았는지 게시하고 있어요","words":[{"word":"the","start":26.48,"end":26.86},{"word":"whole","start":26.86,"end":27.04},{"word":"family","start":27.04,"end":27.42},{"word":"just","start":27.42,"end":27.64},{"word":"looks","start":27.64,"end":27.86},{"word":"beautiful.","start":27.86,"end":28.36},{"word":"And","start":29.4,"end":29.92},{"word":"she''s","start":29.92,"end":30.4},{"word":"always","start":30.4,"end":30.72},{"word":"posting","start":30.72,"end":31.26},{"word":"about","start":31.26,"end":31.5},{"word":"how","start":31.5,"end":31.76},{"word":"blessed","start":31.76,"end":32.2},{"word":"she","start":32.2,"end":32.5},{"word":"is","start":32.5,"end":32.88}],"listenDifficulty":3},{"index":6,"start":32.88,"end":35.78,"textEn":"And how grateful she is for the life that she has.","textKo":"그리고 자신이 가진 삶에 얼마나 감사한지도요.","words":[{"word":"and","start":32.88,"end":33.6},{"word":"how","start":33.6,"end":33.76},{"word":"grateful","start":33.76,"end":34.16},{"word":"she","start":34.16,"end":34.4},{"word":"is","start":34.4,"end":34.58},{"word":"for","start":34.58,"end":34.74},{"word":"the","start":34.74,"end":34.84},{"word":"life","start":34.84,"end":35.08},{"word":"that","start":35.08,"end":35.3},{"word":"she","start":35.3,"end":35.48},{"word":"has.","start":35.48,"end":35.78}],"listenDifficulty":2},{"index":7,"start":36.42,"end":38.96,"textEn":"And I get the feeling she''s not just saying those things","textKo":"그리고 저는 그녀가 그런 말을 그냥 하는 게 아니라는 느낌이 들어요","words":[{"word":"And","start":36.42,"end":36.94},{"word":"I","start":36.94,"end":37.02},{"word":"get","start":37.02,"end":37.12},{"word":"the","start":37.12,"end":37.22},{"word":"feeling","start":37.22,"end":37.44},{"word":"she''s","start":37.44,"end":37.86},{"word":"not","start":37.86,"end":38.0},{"word":"just","start":38.0,"end":38.22},{"word":"saying","start":38.22,"end":38.48},{"word":"those","start":38.48,"end":38.68},{"word":"things","start":38.68,"end":38.96}],"listenDifficulty":3},{"index":8,"start":38.96,"end":42.22,"textEn":"For the sake of Facebook, but she truly means it.","textKo":"페이스북을 위해서가 아니라, 진심으로 그렇게 느끼는 거예요.","words":[{"word":"for","start":38.96,"end":39.18},{"word":"the","start":39.18,"end":39.3},{"word":"sake","start":39.3,"end":39.5},{"word":"of","start":39.5,"end":39.64},{"word":"Facebook,","start":39.64,"end":40.06},{"word":"but","start":40.48,"end":41.0},{"word":"she","start":41.0,"end":41.18},{"word":"truly","start":41.18,"end":41.54},{"word":"means","start":41.54,"end":41.92},{"word":"it.","start":41.92,"end":42.22}],"listenDifficulty":1},{"index":9,"start":43.22,"end":45.92,"textEn":"How many of you have a friend kind of like that?","textKo":"여러분 중에 그런 친구가 있는 분 얼마나 되세요?","words":[{"word":"How","start":43.22,"end":43.74},{"word":"many","start":43.74,"end":43.9},{"word":"of","start":43.9,"end":44.06},{"word":"you","start":44.06,"end":44.16},{"word":"have","start":44.16,"end":44.34},{"word":"a","start":44.34,"end":44.46},{"word":"friend","start":44.46,"end":44.74},{"word":"kind","start":44.74,"end":45.26},{"word":"of","start":45.26,"end":45.42},{"word":"like","start":45.42,"end":45.64},{"word":"that?","start":45.64,"end":45.92}],"listenDifficulty":4},{"index":10,"start":48.36,"end":52.46,"textEn":"And how many of you kind of don''t like that person sometimes?","textKo":"그리고 여러분 중에 가끔 그 사람이 좀 싫은 분은 얼마나 되세요?","words":[{"word":"And","start":48.36,"end":48.88},{"word":"how","start":48.88,"end":49.26},{"word":"many","start":49.26,"end":49.5},{"word":"of","start":49.5,"end":49.68},{"word":"you","start":49.68,"end":49.9},{"word":"kind","start":49.9,"end":50.8},{"word":"of","start":50.8,"end":50.96},{"word":"don''t","start":50.96,"end":51.16},{"word":"like","start":51.16,"end":51.4},{"word":"that","start":51.4,"end":51.62},{"word":"person","start":51.62,"end":52.02},{"word":"sometimes?","start":52.02,"end":52.46}],"listenDifficulty":3},{"index":11,"start":56.02,"end":58.02,"textEn":"We all do this, right?","textKo":"우리 모두 이러잖아요, 그렇죠?","words":[{"word":"We","start":56.02,"end":56.54},{"word":"all","start":56.54,"end":56.96},{"word":"do","start":56.96,"end":57.26},{"word":"this,","start":57.26,"end":57.7},{"word":"right?","start":57.8,"end":58.02}],"listenDifficulty":1},{"index":12,"start":58.52,"end":64.04,"textEn":"It''s hard not to do. But that way of thinking costs us something.","textKo":"안 그러기가 어려워요. 하지만 그런 사고방식에는 대가가 있어요.","words":[{"word":"It''s","start":58.52,"end":59.0},{"word":"hard","start":59.0,"end":59.24},{"word":"not","start":59.24,"end":59.54},{"word":"to","start":59.54,"end":59.8},{"word":"do.","start":59.8,"end":60.08},{"word":"But","start":60.7,"end":61.18},{"word":"that","start":61.18,"end":61.42},{"word":"way","start":61.42,"end":61.62},{"word":"of","start":61.62,"end":61.8},{"word":"thinking","start":61.8,"end":62.16},{"word":"costs","start":62.16,"end":63.3},{"word":"us","start":63.3,"end":63.6},{"word":"something.","start":63.6,"end":64.04}],"listenDifficulty":2},{"index":13,"start":64.46,"end":66.46,"textEn":"And that''s what I want to talk to you about today,","textKo":"그리고 오늘 여러분께 이야기하고 싶은 것이 바로 그거예요,","words":[{"word":"And","start":64.46,"end":64.94},{"word":"that''s","start":64.94,"end":65.1},{"word":"what","start":65.1,"end":65.2},{"word":"I","start":65.2,"end":65.28},{"word":"want","start":65.28,"end":65.4},{"word":"to","start":65.4,"end":65.48},{"word":"talk","start":65.48,"end":65.68},{"word":"to","start":65.68,"end":65.8},{"word":"you","start":65.8,"end":65.9},{"word":"about","start":65.9,"end":66.08},{"word":"today,","start":66.08,"end":66.46}],"listenDifficulty":4},{"index":14,"start":66.7,"end":69.58,"textEn":"Is what our bad habits cost us.","textKo":"우리의 나쁜 습관이 우리에게 어떤 대가를 치르게 하는지요.","words":[{"word":"is","start":66.7,"end":66.96},{"word":"what","start":66.96,"end":67.1},{"word":"our","start":67.1,"end":67.22},{"word":"bad","start":67.22,"end":67.5},{"word":"habits","start":67.5,"end":68.12},{"word":"cost","start":68.12,"end":69.2},{"word":"us.","start":69.2,"end":69.58}],"listenDifficulty":1},{"index":15,"start":70.82,"end":73.3,"textEn":"Maybe you scroll through your Facebook feed and you think,","textKo":"아마 여러분은 페이스북 피드를 스크롤하면서 이렇게 생각할 거예요,","words":[{"word":"Maybe","start":70.82,"end":71.3},{"word":"you","start":71.3,"end":71.44},{"word":"scroll","start":71.44,"end":71.74},{"word":"through","start":71.74,"end":71.94},{"word":"your","start":71.94,"end":72.1},{"word":"Facebook","start":72.1,"end":72.48},{"word":"feed","start":72.48,"end":72.84},{"word":"and","start":72.84,"end":72.98},{"word":"you","start":72.98,"end":73.08},{"word":"think,","start":73.08,"end":73.3}],"listenDifficulty":2},{"index":16,"start":73.54,"end":77.76,"textEn":"So what if I roll my eyes? It''s just five seconds of my time.","textKo":"눈 좀 굴리면 어때? 겨우 5초밖에 안 걸리잖아.","words":[{"word":"so","start":73.54,"end":73.66},{"word":"what","start":73.66,"end":74.0},{"word":"if","start":74.0,"end":74.12},{"word":"I","start":74.12,"end":74.32},{"word":"roll","start":74.32,"end":74.52},{"word":"my","start":74.52,"end":74.72},{"word":"eyes?","start":74.72,"end":75.22},{"word":"It''s","start":75.5,"end":75.98},{"word":"just","start":75.98,"end":76.18},{"word":"five","start":76.18,"end":76.56},{"word":"seconds","start":76.56,"end":76.98},{"word":"of","start":76.98,"end":77.2},{"word":"my","start":77.2,"end":77.36},{"word":"time.","start":77.36,"end":77.76}],"listenDifficulty":2},{"index":17,"start":78.04,"end":84.36,"textEn":"How could it be hurting me? Well, researchers have found that envying your friends on Facebook","textKo":"그게 나한테 뭐가 해롭겠어? 그런데 연구자들이 발견한 바에 따르면 페이스북에서 친구를 부러워하는 것이","words":[{"word":"How","start":78.04,"end":78.46},{"word":"could","start":78.46,"end":78.66},{"word":"it","start":78.66,"end":78.74},{"word":"be","start":78.74,"end":78.86},{"word":"hurting","start":78.86,"end":79.16},{"word":"me?","start":79.16,"end":79.44},{"word":"Well,","start":80.3,"end":80.82},{"word":"researchers","start":81.1,"end":81.3},{"word":"have","start":81.3,"end":81.66},{"word":"found","start":81.66,"end":82.06},{"word":"that","start":82.06,"end":82.6},{"word":"envying","start":82.6,"end":83.1},{"word":"your","start":83.1,"end":83.3},{"word":"friends","start":83.3,"end":83.64},{"word":"on","start":83.64,"end":83.88},{"word":"Facebook","start":83.88,"end":84.36}],"listenDifficulty":1},{"index":18,"start":85.08,"end":91.1,"textEn":"Actually leads to depression. That''s just one of the traps that our minds can set for us.","textKo":"실제로 우울증으로 이어진다고 합니다. 그것은 우리 마음이 우리에게 설 수 있는 함정 중 하나일 뿐이에요.","words":[{"word":"actually","start":85.08,"end":85.6},{"word":"leads","start":85.6,"end":86.0},{"word":"to","start":86.0,"end":86.18},{"word":"depression.","start":86.18,"end":86.66},{"word":"That''s","start":87.9,"end":88.42},{"word":"just","start":88.42,"end":88.58},{"word":"one","start":88.58,"end":88.86},{"word":"of","start":88.86,"end":88.98},{"word":"the","start":88.98,"end":89.08},{"word":"traps","start":89.08,"end":89.42},{"word":"that","start":89.42,"end":89.66},{"word":"our","start":89.66,"end":89.8},{"word":"minds","start":89.8,"end":90.06},{"word":"can","start":90.06,"end":90.3},{"word":"set","start":90.3,"end":90.56},{"word":"for","start":90.56,"end":90.74},{"word":"us.","start":90.74,"end":91.1}],"listenDifficulty":1},{"index":19,"start":91.98,"end":94.22,"textEn":"Have you ever complained about your boss?","textKo":"여러분은 상사에 대해 불평한 적이 있나요?","words":[{"word":"Have","start":91.98,"end":92.5},{"word":"you","start":92.5,"end":92.56},{"word":"ever","start":92.56,"end":92.74},{"word":"complained","start":92.74,"end":93.3},{"word":"about","start":93.3,"end":93.54},{"word":"your","start":93.54,"end":93.72},{"word":"boss?","start":93.72,"end":94.22}],"listenDifficulty":1},{"index":20,"start":95.2,"end":99.34,"textEn":"Or looked at your friends'' lives and thought, why do they have all the luck?","textKo":"또는 친구들의 삶을 보면서, 왜 저 사람들만 운이 좋지? 라고 생각한 적이 있나요?","words":[{"word":"Or","start":95.2,"end":95.72},{"word":"looked","start":95.72,"end":95.94},{"word":"at","start":95.94,"end":96.06},{"word":"your","start":96.06,"end":96.18},{"word":"friends''","start":96.18,"end":96.4},{"word":"lives","start":96.56,"end":96.72},{"word":"and","start":96.72,"end":96.9},{"word":"thought,","start":96.9,"end":97.16},{"word":"why","start":97.46,"end":98.1},{"word":"do","start":98.1,"end":98.24},{"word":"they","start":98.24,"end":98.44},{"word":"have","start":98.44,"end":98.74},{"word":"all","start":98.74,"end":98.9},{"word":"the","start":98.9,"end":99.02},{"word":"luck?","start":99.02,"end":99.34}],"listenDifficulty":2},{"index":21,"start":100.5,"end":105.48,"textEn":"Can''t help thinking that way, right? That way of thinking seems small in the moment.","textKo":"그렇게 생각하지 않을 수 없죠, 그렇죠? 그런 사고방식은 그 순간에는 사소해 보여요.","words":[{"word":"Can''t","start":100.5,"end":101.02},{"word":"help","start":101.02,"end":101.2},{"word":"thinking","start":101.2,"end":101.48},{"word":"that","start":101.48,"end":101.76},{"word":"way,","start":101.76,"end":101.96},{"word":"right?","start":102.04,"end":102.22},{"word":"That","start":102.22,"end":103.28},{"word":"way","start":103.28,"end":103.42},{"word":"of","start":103.42,"end":103.54},{"word":"thinking","start":103.54,"end":103.72},{"word":"seems","start":103.72,"end":104.28},{"word":"small","start":104.28,"end":104.78},{"word":"in","start":104.78,"end":105.0},{"word":"the","start":105.0,"end":105.1},{"word":"moment.","start":105.1,"end":105.48}],"listenDifficulty":1},{"index":22,"start":105.82,"end":108.54,"textEn":"In fact, it might even make you feel better in the moment.","textKo":"사실 그 순간에는 기분이 더 나아질 수도 있어요.","words":[{"word":"In","start":105.82,"end":106.24},{"word":"fact,","start":106.24,"end":106.38},{"word":"it","start":106.5,"end":106.58},{"word":"might","start":106.58,"end":106.72},{"word":"even","start":106.72,"end":106.94},{"word":"make","start":106.94,"end":107.16},{"word":"you","start":107.16,"end":107.3},{"word":"feel","start":107.3,"end":107.6},{"word":"better","start":107.6,"end":107.9},{"word":"in","start":107.9,"end":108.1},{"word":"the","start":108.1,"end":108.2},{"word":"moment.","start":108.2,"end":108.54}],"listenDifficulty":3},{"index":23,"start":109.42,"end":112.8,"textEn":"But that way of thinking is eating away at your mental strength.","textKo":"하지만 그런 사고방식이 여러분의 정신적 강인함을 서서히 갉아먹고 있어요.","words":[{"word":"But","start":109.42,"end":109.96},{"word":"that","start":109.96,"end":110.12},{"word":"way","start":110.12,"end":110.26},{"word":"of","start":110.26,"end":110.42},{"word":"thinking","start":110.42,"end":110.68},{"word":"is","start":110.68,"end":111.12},{"word":"eating","start":111.12,"end":111.44},{"word":"away","start":111.44,"end":111.72},{"word":"at","start":111.72,"end":111.94},{"word":"your","start":111.94,"end":112.06},{"word":"mental","start":112.06,"end":112.34},{"word":"strength.","start":112.34,"end":112.8}],"listenDifficulty":2},{"index":24,"start":114.86,"end":117.3,"textEn":"There''s three kinds of destructive beliefs","textKo":"세 가지 종류의 파괴적인 믿음이 있어요","words":[{"word":"There''s","start":114.86,"end":115.4},{"word":"three","start":115.4,"end":115.64},{"word":"kinds","start":115.64,"end":116.1},{"word":"of","start":116.1,"end":116.28},{"word":"destructive","start":116.28,"end":116.78},{"word":"beliefs","start":116.78,"end":117.3}],"listenDifficulty":2},{"index":25,"start":117.3,"end":121.84,"textEn":"That make us less effective and rob us of our mental strength.","textKo":"그것이 우리를 덜 효과적으로 만들고 정신적 강인함을 빼앗아 가요.","words":[{"word":"that","start":117.3,"end":118.26},{"word":"make","start":118.26,"end":118.48},{"word":"us","start":118.48,"end":118.7},{"word":"less","start":118.7,"end":118.9},{"word":"effective","start":118.9,"end":119.44},{"word":"and","start":119.44,"end":120.06},{"word":"rob","start":120.06,"end":120.46},{"word":"us","start":120.46,"end":120.78},{"word":"of","start":120.78,"end":120.98},{"word":"our","start":120.98,"end":121.1},{"word":"mental","start":121.1,"end":121.36},{"word":"strength.","start":121.36,"end":121.84}],"listenDifficulty":2},{"index":26,"start":122.86,"end":126.56,"textEn":"And that''s what we''re talking about. The first one is unhealthy beliefs about ourselves.","textKo":"그것이 우리가 이야기할 내용이에요. 첫 번째는 자기 자신에 대한 건강하지 못한 믿음이에요.","words":[{"word":"And","start":122.86,"end":123.38},{"word":"that''s","start":123.38,"end":123.38},{"word":"what","start":123.38,"end":123.38},{"word":"we''re","start":123.38,"end":123.38},{"word":"talking","start":123.38,"end":123.38},{"word":"about.","start":123.38,"end":123.38},{"word":"The","start":123.38,"end":123.38},{"word":"first","start":123.38,"end":123.66},{"word":"one","start":123.66,"end":123.98},{"word":"is","start":123.98,"end":124.88},{"word":"unhealthy","start":124.88,"end":125.34},{"word":"beliefs","start":125.34,"end":125.74},{"word":"about","start":125.74,"end":126.0},{"word":"ourselves.","start":126.0,"end":126.56}],"listenDifficulty":2},{"index":27,"start":127.56,"end":129.86,"textEn":"We tend to feel sorry for ourselves.","textKo":"우리는 자기 자신을 불쌍히 여기는 경향이 있어요.","words":[{"word":"We","start":127.56,"end":128.08},{"word":"tend","start":128.08,"end":128.26},{"word":"to","start":128.26,"end":128.44},{"word":"feel","start":128.44,"end":128.64},{"word":"sorry","start":128.64,"end":129.06},{"word":"for","start":129.06,"end":129.3},{"word":"ourselves.","start":129.3,"end":129.86}],"listenDifficulty":1},{"index":28,"start":130.52,"end":133.74,"textEn":"And while it''s okay to be sad when something bad happens,","textKo":"나쁜 일이 일어났을 때 슬퍼하는 것은 괜찮지만,","words":[{"word":"And","start":130.52,"end":130.98},{"word":"while","start":130.98,"end":131.12},{"word":"it''s","start":131.12,"end":131.28},{"word":"okay","start":131.28,"end":131.44},{"word":"to","start":131.44,"end":131.58},{"word":"be","start":131.58,"end":131.7},{"word":"sad","start":131.7,"end":132.24},{"word":"when","start":132.24,"end":132.68},{"word":"something","start":132.68,"end":132.98},{"word":"bad","start":132.98,"end":133.26},{"word":"happens,","start":133.26,"end":133.74}],"listenDifficulty":2},{"index":29,"start":134.52,"end":138.62,"textEn":"Self-pity goes beyond that. It''s when you start to magnify your misfortune.","textKo":"자기연민은 그 이상이에요. 자신의 불행을 과장하기 시작하는 것이죠.","words":[{"word":"self","start":134.52,"end":134.84},{"word":"-pity","start":134.84,"end":135.1},{"word":"goes","start":135.1,"end":135.36},{"word":"beyond","start":135.36,"end":135.76},{"word":"that.","start":135.76,"end":136.12},{"word":"It''s","start":136.24,"end":136.38},{"word":"when","start":136.38,"end":136.48},{"word":"you","start":136.48,"end":136.58},{"word":"start","start":136.58,"end":136.76},{"word":"to","start":136.76,"end":136.94},{"word":"magnify","start":136.94,"end":137.66},{"word":"your","start":137.66,"end":137.88},{"word":"misfortune.","start":137.88,"end":138.62}],"listenDifficulty":3},{"index":30,"start":138.88,"end":142.92,"textEn":"When you think things like, why do these things always have to happen to me?","textKo":"왜 이런 일이 항상 나한테만 일어나야 하지? 같은 생각을 할 때요.","words":[{"word":"When","start":138.88,"end":139.34},{"word":"you","start":139.34,"end":139.44},{"word":"think","start":139.44,"end":139.66},{"word":"things","start":139.66,"end":139.96},{"word":"like,","start":139.96,"end":140.24},{"word":"why","start":140.44,"end":140.98},{"word":"do","start":140.98,"end":141.12},{"word":"these","start":141.12,"end":141.3},{"word":"things","start":141.3,"end":141.48},{"word":"always","start":141.48,"end":141.76},{"word":"have","start":141.76,"end":142.0},{"word":"to","start":142.0,"end":142.16},{"word":"happen","start":142.16,"end":142.46},{"word":"to","start":142.46,"end":142.66},{"word":"me?","start":142.66,"end":142.92}],"listenDifficulty":3},{"index":31,"start":143.06,"end":147.54,"textEn":"I shouldn''t have to deal with it. That way of thinking keeps you stuck,","textKo":"이런 건 겪을 필요가 없는데. 그런 사고방식은 여러분을 막다른 곳에 가둬요,","words":[{"word":"I","start":143.06,"end":143.32},{"word":"shouldn''t","start":143.32,"end":143.68},{"word":"have","start":143.68,"end":143.96},{"word":"to","start":143.96,"end":144.18},{"word":"deal","start":144.18,"end":144.38},{"word":"with","start":144.38,"end":144.58},{"word":"it.","start":144.58,"end":144.82},{"word":"That","start":145.52,"end":146.04},{"word":"way","start":146.04,"end":146.16},{"word":"of","start":146.16,"end":146.28},{"word":"thinking","start":146.28,"end":146.5},{"word":"keeps","start":146.5,"end":146.82},{"word":"you","start":146.82,"end":146.98},{"word":"stuck,","start":146.98,"end":147.54}],"listenDifficulty":1},{"index":32,"start":147.78,"end":152.22,"textEn":"Keeps you focused on the problem, keeps you from finding a solution.","textKo":"문제에만 집중하게 하고, 해결책을 찾지 못하게 해요.","words":[{"word":"keeps","start":147.78,"end":148.14},{"word":"you","start":148.14,"end":148.3},{"word":"focused","start":148.3,"end":148.7},{"word":"on","start":148.7,"end":148.92},{"word":"the","start":148.92,"end":149.04},{"word":"problem,","start":149.04,"end":149.52},{"word":"keeps","start":149.52,"end":150.16},{"word":"you","start":150.16,"end":150.3},{"word":"from","start":150.3,"end":150.48},{"word":"finding","start":150.48,"end":151.54},{"word":"a","start":151.54,"end":151.76},{"word":"solution.","start":151.76,"end":152.22}],"listenDifficulty":1},{"index":33,"start":152.96,"end":155.1,"textEn":"And even when you can''t create a solution,","textKo":"그리고 해결책을 만들 수 없을 때조차도,","words":[{"word":"And","start":152.96,"end":153.48},{"word":"even","start":153.48,"end":153.74},{"word":"when","start":153.74,"end":153.9},{"word":"you","start":153.9,"end":154.04},{"word":"can''t","start":154.04,"end":154.32},{"word":"create","start":154.32,"end":154.56},{"word":"a","start":154.56,"end":154.74},{"word":"solution,","start":154.74,"end":155.1}],"listenDifficulty":2},{"index":34,"start":155.2,"end":157.3,"textEn":"You can always take steps to make your life","textKo":"여러분의 삶을 더 나아지게 할 수 있는 조치를 항상 취할 수 있어요","words":[{"word":"you","start":155.2,"end":155.38},{"word":"can","start":155.38,"end":155.5},{"word":"always","start":155.5,"end":155.82},{"word":"take","start":155.82,"end":156.1},{"word":"steps","start":156.1,"end":156.42},{"word":"to","start":156.42,"end":156.58},{"word":"make","start":156.58,"end":156.76},{"word":"your","start":156.76,"end":156.96},{"word":"life","start":156.96,"end":157.3}],"listenDifficulty":3},{"index":35,"start":157.3,"end":163.0,"textEn":"Or somebody else''s life better. But you can''t do that when you''re busy hosting your own pity party.","textKo":"아니면 다른 사람의 삶을 더 낫게요. 하지만 자기만의 연민 파티를 열고 있을 때는 그렇게 할 수 없어요.","words":[{"word":"or","start":157.3,"end":157.5},{"word":"somebody","start":157.5,"end":157.82},{"word":"else''s","start":157.82,"end":158.24},{"word":"life","start":158.24,"end":158.44},{"word":"better.","start":158.44,"end":158.82},{"word":"But","start":159.26,"end":159.78},{"word":"you","start":159.78,"end":159.88},{"word":"can''t","start":159.88,"end":160.26},{"word":"do","start":160.26,"end":160.44},{"word":"that","start":160.44,"end":160.66},{"word":"when","start":160.66,"end":160.84},{"word":"you''re","start":160.84,"end":161.0},{"word":"busy","start":161.0,"end":161.32},{"word":"hosting","start":161.32,"end":162.02},{"word":"your","start":162.02,"end":162.24},{"word":"own","start":162.24,"end":162.36},{"word":"pity","start":162.36,"end":162.62},{"word":"party.","start":162.62,"end":163.0}],"listenDifficulty":2},{"index":36,"start":164.84,"end":168.02,"textEn":"The second type of destructive belief that holds us back","textKo":"우리를 막는 두 번째 유형의 파괴적인 믿음은","words":[{"word":"The","start":164.84,"end":165.36},{"word":"second","start":165.36,"end":165.7},{"word":"type","start":165.7,"end":165.94},{"word":"of","start":165.94,"end":166.12},{"word":"destructive","start":166.12,"end":166.54},{"word":"belief","start":166.54,"end":166.96},{"word":"that","start":166.96,"end":167.18},{"word":"holds","start":167.18,"end":167.44},{"word":"us","start":167.44,"end":167.64},{"word":"back","start":167.64,"end":168.02}],"listenDifficulty":2},{"index":37,"start":168.8,"end":174.3,"textEn":"Is unhealthy beliefs about others. We think that other people can control us,","textKo":"다른 사람들에 대한 건강하지 못한 믿음이에요. 다른 사람들이 우리를 통제할 수 있다고 생각하고,","words":[{"word":"is","start":168.8,"end":169.06},{"word":"unhealthy","start":169.06,"end":169.5},{"word":"beliefs","start":169.5,"end":169.88},{"word":"about","start":169.88,"end":170.14},{"word":"others.","start":170.14,"end":170.58},{"word":"We","start":171.78,"end":172.3},{"word":"think","start":172.3,"end":172.5},{"word":"that","start":172.5,"end":172.68},{"word":"other","start":172.68,"end":172.92},{"word":"people","start":172.92,"end":173.2},{"word":"can","start":173.2,"end":173.46},{"word":"control","start":173.46,"end":173.88},{"word":"us,","start":173.88,"end":174.3}],"listenDifficulty":1},{"index":38,"start":174.44,"end":179.96,"textEn":"And we give away our power. And we think that we''re going to be able to do our power. But as adults who live in a free country,","textKo":"우리는 권한을 내어줘요. 하지만 자유로운 나라에 사는 성인으로서,","words":[{"word":"and","start":174.44,"end":174.88},{"word":"we","start":174.88,"end":175.02},{"word":"give","start":175.02,"end":175.28},{"word":"away","start":175.28,"end":175.52},{"word":"our","start":175.52,"end":175.72},{"word":"power.","start":175.72,"end":176.22},{"word":"And","start":176.22,"end":176.26},{"word":"we","start":176.26,"end":176.26},{"word":"think","start":176.26,"end":176.26},{"word":"that","start":176.26,"end":176.26},{"word":"we''re","start":176.26,"end":176.26},{"word":"going","start":176.26,"end":176.26},{"word":"to","start":176.26,"end":176.26},{"word":"be","start":176.26,"end":176.26},{"word":"able","start":176.26,"end":176.26},{"word":"to","start":176.26,"end":176.26},{"word":"do","start":176.26,"end":176.26},{"word":"our","start":176.26,"end":176.26},{"word":"power.","start":176.26,"end":176.26},{"word":"But","start":177.62,"end":178.1},{"word":"as","start":178.1,"end":178.28},{"word":"adults","start":178.28,"end":178.68},{"word":"who","start":178.68,"end":178.94},{"word":"live","start":178.94,"end":179.12},{"word":"in","start":179.12,"end":179.22},{"word":"a","start":179.22,"end":179.34},{"word":"free","start":179.34,"end":179.52},{"word":"country,","start":179.52,"end":179.96}],"listenDifficulty":3},{"index":39,"start":180.48,"end":183.62,"textEn":"There''s very few things in life that you have to do.","textKo":"인생에서 반드시 해야 하는 일은 거의 없어요.","words":[{"word":"there''s","start":180.48,"end":180.96},{"word":"very","start":180.96,"end":181.26},{"word":"few","start":181.26,"end":181.5},{"word":"things","start":181.5,"end":181.82},{"word":"in","start":181.82,"end":181.98},{"word":"life","start":181.98,"end":182.16},{"word":"that","start":182.16,"end":182.36},{"word":"you","start":182.36,"end":182.56},{"word":"have","start":182.56,"end":183.06},{"word":"to","start":183.06,"end":183.38},{"word":"do.","start":183.38,"end":183.62}],"listenDifficulty":2},{"index":40,"start":184.18,"end":188.54,"textEn":"So when you say, I have to work late, you give away your power.","textKo":"그래서 ''야근해야 해''라고 말할 때, 여러분은 자신의 권한을 내어주는 거예요.","words":[{"word":"So","start":184.18,"end":184.66},{"word":"when","start":184.66,"end":184.78},{"word":"you","start":184.78,"end":184.9},{"word":"say,","start":184.9,"end":185.2},{"word":"I","start":185.4,"end":185.5},{"word":"have","start":185.5,"end":185.9},{"word":"to","start":185.9,"end":186.12},{"word":"work","start":186.12,"end":186.4},{"word":"late,","start":186.4,"end":186.64},{"word":"you","start":187.0,"end":187.56},{"word":"give","start":187.56,"end":187.76},{"word":"away","start":187.76,"end":187.96},{"word":"your","start":187.96,"end":188.12},{"word":"power.","start":188.12,"end":188.54}],"listenDifficulty":2},{"index":41,"start":189.6,"end":192.3,"textEn":"Yeah, maybe there''ll be consequences if you don''t work late,","textKo":"네, 야근하지 않으면 결과가 있을 수도 있어요,","words":[{"word":"Yeah,","start":189.6,"end":189.84},{"word":"maybe","start":189.9,"end":190.08},{"word":"there''ll","start":190.08,"end":190.28},{"word":"be","start":190.28,"end":190.36},{"word":"consequences","start":190.36,"end":191.16},{"word":"if","start":191.16,"end":191.44},{"word":"you","start":191.44,"end":191.56},{"word":"don''t","start":191.56,"end":191.82},{"word":"work","start":191.82,"end":192.04},{"word":"late,","start":192.04,"end":192.3}],"listenDifficulty":3},{"index":42,"start":192.42,"end":196.56,"textEn":"But it''s still a choice. Or when you say,","textKo":"하지만 그것은 여전히 선택이에요. 또는 이렇게 말할 때,","words":[{"word":"but","start":192.42,"end":192.64},{"word":"it''s","start":192.64,"end":193.44},{"word":"still","start":193.44,"end":193.6},{"word":"a","start":193.6,"end":193.74},{"word":"choice.","start":193.74,"end":194.16},{"word":"Or","start":195.48,"end":195.96},{"word":"when","start":195.96,"end":196.14},{"word":"you","start":196.14,"end":196.24},{"word":"say,","start":196.24,"end":196.56}],"listenDifficulty":1},{"index":43,"start":196.8,"end":198.92,"textEn":"My mother-in-law drives me crazy,","textKo":"시어머니가 나를 미치게 만들어,","words":[{"word":"my","start":196.8,"end":197.26},{"word":"mother","start":197.26,"end":197.54},{"word":"-in","start":197.54,"end":197.68},{"word":"-law","start":197.68,"end":197.8},{"word":"drives","start":197.8,"end":198.14},{"word":"me","start":198.14,"end":198.48},{"word":"crazy,","start":198.48,"end":198.92}],"listenDifficulty":2},{"index":44,"start":199.58,"end":204.58,"textEn":"You give away your power. Maybe she''s not the nicest person on earth,","textKo":"여러분은 자신의 권한을 내어주는 거예요. 아마 그녀가 세상에서 가장 친절한 사람은 아닐 수 있어요,","words":[{"word":"you","start":199.58,"end":200.06},{"word":"give","start":200.06,"end":200.24},{"word":"away","start":200.24,"end":200.44},{"word":"your","start":200.44,"end":200.62},{"word":"power.","start":200.62,"end":201.02},{"word":"Maybe","start":202.16,"end":202.68},{"word":"she''s","start":202.68,"end":202.98},{"word":"not","start":202.98,"end":203.1},{"word":"the","start":203.1,"end":203.28},{"word":"nicest","start":203.28,"end":203.58},{"word":"person","start":203.58,"end":204.06},{"word":"on","start":204.06,"end":204.28},{"word":"earth,","start":204.28,"end":204.58}],"listenDifficulty":1},{"index":45,"start":204.92,"end":207.18,"textEn":"But it''s up to you how you respond to her,","textKo":"하지만 그녀에게 어떻게 반응할지는 여러분에게 달려 있어요,","words":[{"word":"but","start":204.92,"end":205.46},{"word":"it''s","start":205.46,"end":205.6},{"word":"up","start":205.6,"end":205.7},{"word":"to","start":205.7,"end":205.82},{"word":"you","start":205.82,"end":206.0},{"word":"how","start":206.0,"end":206.16},{"word":"you","start":206.16,"end":206.34},{"word":"respond","start":206.34,"end":206.78},{"word":"to","start":206.78,"end":207.0},{"word":"her,","start":207.0,"end":207.18}],"listenDifficulty":3},{"index":46,"start":207.28,"end":214.26,"textEn":"Because you''re in control. The third type of unhealthy belief that holds us back","textKo":"왜냐하면 여러분이 통제권을 가지고 있으니까요. 세 번째 유형의 건강하지 못한 믿음은","words":[{"word":"because","start":207.28,"end":207.56},{"word":"you''re","start":207.56,"end":208.34},{"word":"in","start":208.34,"end":208.5},{"word":"control.","start":208.5,"end":208.98},{"word":"The","start":211.24,"end":211.76},{"word":"third","start":211.76,"end":212.04},{"word":"type","start":212.04,"end":212.28},{"word":"of","start":212.28,"end":212.48},{"word":"unhealthy","start":212.48,"end":212.86},{"word":"belief","start":212.86,"end":213.26},{"word":"that","start":213.26,"end":213.48},{"word":"holds","start":213.48,"end":213.74},{"word":"us","start":213.74,"end":213.92},{"word":"back","start":213.92,"end":214.26}],"listenDifficulty":1},{"index":47,"start":214.78,"end":216.86,"textEn":"Is unhealthy beliefs about the world.","textKo":"세상에 대한 건강하지 못한 믿음이에요.","words":[{"word":"is","start":214.78,"end":215.3},{"word":"unhealthy","start":215.3,"end":215.7},{"word":"beliefs","start":215.7,"end":216.12},{"word":"about","start":216.12,"end":216.3},{"word":"the","start":216.3,"end":216.5},{"word":"world.","start":216.5,"end":216.86}],"listenDifficulty":1},{"index":48,"start":218.38,"end":221.08,"textEn":"We tend to think that the world owes us something.","textKo":"우리는 세상이 우리에게 빚진 것이 있다고 생각하는 경향이 있어요.","words":[{"word":"We","start":218.38,"end":218.9},{"word":"tend","start":218.9,"end":219.06},{"word":"to","start":219.06,"end":219.2},{"word":"think","start":219.2,"end":219.38},{"word":"that","start":219.38,"end":219.62},{"word":"the","start":219.62,"end":219.86},{"word":"world","start":219.86,"end":220.06},{"word":"owes","start":220.06,"end":220.44},{"word":"us","start":220.44,"end":220.66},{"word":"something.","start":220.66,"end":221.08}],"listenDifficulty":2},{"index":49,"start":221.38,"end":223.78,"textEn":"We think, if I put in enough hard work,","textKo":"충분히 열심히 일하면,","words":[{"word":"We","start":221.38,"end":221.46},{"word":"think,","start":221.46,"end":221.7},{"word":"if","start":221.88,"end":222.24},{"word":"I","start":222.24,"end":222.38},{"word":"put","start":222.38,"end":222.64},{"word":"in","start":222.64,"end":222.78},{"word":"enough","start":222.78,"end":223.06},{"word":"hard","start":223.06,"end":223.36},{"word":"work,","start":223.36,"end":223.78}],"listenDifficulty":2},{"index":50,"start":224.0,"end":231.7,"textEn":"Then I deserve success. But expecting success to fall into your lap like some sort of cosmic reward","textKo":"성공할 자격이 있다고 생각해요. 하지만 어떤 우주적 보상처럼 성공이 저절로 따라오길 기대하는 것은","words":[{"word":"then","start":224.0,"end":224.36},{"word":"I","start":224.36,"end":224.5},{"word":"deserve","start":224.5,"end":224.86},{"word":"success.","start":224.86,"end":225.62},{"word":"But","start":226.76,"end":227.2},{"word":"expecting","start":227.2,"end":227.64},{"word":"success","start":227.64,"end":228.2},{"word":"to","start":228.2,"end":228.5},{"word":"fall","start":228.5,"end":228.76},{"word":"into","start":228.76,"end":228.98},{"word":"your","start":228.98,"end":229.16},{"word":"lap","start":229.16,"end":229.46},{"word":"like","start":229.46,"end":229.68},{"word":"some","start":229.68,"end":229.86},{"word":"sort","start":229.86,"end":230.08},{"word":"of","start":230.08,"end":230.22},{"word":"cosmic","start":230.22,"end":231.12},{"word":"reward","start":231.12,"end":231.7}],"listenDifficulty":2},{"index":51,"start":232.22,"end":239.0,"textEn":"Will only lead to disappointment. But I know it''s hard to give up our bad mental habits.","textKo":"실망만 가져다줄 뿐이에요. 하지만 나쁜 정신적 습관을 버리는 것이 어렵다는 걸 알아요.","words":[{"word":"will","start":232.22,"end":232.66},{"word":"only","start":232.66,"end":233.0},{"word":"lead","start":233.0,"end":233.22},{"word":"to","start":233.22,"end":233.36},{"word":"disappointment.","start":233.36,"end":233.96},{"word":"But","start":236.16,"end":236.6},{"word":"I","start":236.6,"end":236.68},{"word":"know","start":236.68,"end":236.88},{"word":"it''s","start":236.88,"end":237.2},{"word":"hard","start":237.2,"end":237.36},{"word":"to","start":237.36,"end":237.5},{"word":"give","start":237.5,"end":237.64},{"word":"up","start":237.64,"end":237.78},{"word":"our","start":237.78,"end":237.92},{"word":"bad","start":237.92,"end":238.16},{"word":"mental","start":238.16,"end":238.48},{"word":"habits.","start":238.48,"end":239.0}],"listenDifficulty":2},{"index":52,"start":239.32,"end":243.5,"textEn":"It''s hard to get rid of those unhealthy beliefs that we''ve carried around with us for so long.","textKo":"오랫동안 가지고 다녔던 건강하지 못한 믿음을 없애는 것은 어려워요.","words":[{"word":"It''s","start":239.32,"end":239.74},{"word":"hard","start":239.74,"end":239.82},{"word":"to","start":239.82,"end":239.94},{"word":"get","start":239.94,"end":240.08},{"word":"rid","start":240.08,"end":240.2},{"word":"of","start":240.2,"end":240.3},{"word":"those","start":240.3,"end":240.48},{"word":"unhealthy","start":240.48,"end":241.0},{"word":"beliefs","start":241.0,"end":241.44},{"word":"that","start":241.44,"end":241.64},{"word":"we''ve","start":241.64,"end":241.82},{"word":"carried","start":241.82,"end":242.08},{"word":"around","start":242.08,"end":242.36},{"word":"with","start":242.36,"end":242.54},{"word":"us","start":242.54,"end":242.76},{"word":"for","start":242.76,"end":242.94},{"word":"so","start":242.94,"end":243.14},{"word":"long.","start":243.14,"end":243.5}],"listenDifficulty":3},{"index":53,"start":244.56,"end":246.76,"textEn":"But you can''t afford not to give them up.","textKo":"하지만 그것들을 버리지 않을 여유가 없어요.","words":[{"word":"But","start":244.56,"end":245.0},{"word":"you","start":245.0,"end":245.1},{"word":"can''t","start":245.1,"end":245.42},{"word":"afford","start":245.42,"end":245.64},{"word":"not","start":245.64,"end":245.9},{"word":"to","start":245.9,"end":246.12},{"word":"give","start":246.12,"end":246.26},{"word":"them","start":246.26,"end":246.42},{"word":"up.","start":246.42,"end":246.76}],"listenDifficulty":3},{"index":54,"start":247.7,"end":251.06,"textEn":"Because sooner or later, you''re going to hit a time in your life","textKo":"왜냐하면 조만간 인생에서 그런 시기를 맞이하게 될 테니까요","words":[{"word":"Because","start":247.7,"end":248.14},{"word":"sooner","start":248.14,"end":248.42},{"word":"or","start":248.42,"end":248.6},{"word":"later,","start":248.6,"end":248.92},{"word":"you''re","start":249.34,"end":249.78},{"word":"going","start":249.78,"end":249.86},{"word":"to","start":249.86,"end":249.94},{"word":"hit","start":249.94,"end":250.08},{"word":"a","start":250.08,"end":250.22},{"word":"time","start":250.22,"end":250.46},{"word":"in","start":250.46,"end":250.6},{"word":"your","start":250.6,"end":250.7},{"word":"life","start":250.7,"end":251.06}],"listenDifficulty":3},{"index":55,"start":251.06,"end":254.32,"textEn":"Where you need all the mental strength that you can muster.","textKo":"모든 정신적 강인함을 끌어모아야 하는 때가요.","words":[{"word":"where","start":251.06,"end":251.82},{"word":"you","start":251.82,"end":251.98},{"word":"need","start":251.98,"end":252.24},{"word":"all","start":252.24,"end":252.5},{"word":"the","start":252.5,"end":252.66},{"word":"mental","start":252.66,"end":252.9},{"word":"strength","start":252.9,"end":253.28},{"word":"that","start":253.28,"end":253.52},{"word":"you","start":253.52,"end":253.64},{"word":"can","start":253.64,"end":253.84},{"word":"muster.","start":253.84,"end":254.32}],"listenDifficulty":3},{"index":56,"start":256.54,"end":260.84,"textEn":"When I was 23 years old, I thought I had life all figured out.","textKo":"23살 때, 저는 인생을 다 알아냈다고 생각했어요.","words":[{"word":"When","start":256.54,"end":257.06},{"word":"I","start":257.06,"end":257.16},{"word":"was","start":257.16,"end":257.32},{"word":"23","start":257.32,"end":257.7},{"word":"years","start":257.7,"end":258.06},{"word":"old,","start":258.06,"end":258.46},{"word":"I","start":258.66,"end":259.18},{"word":"thought","start":259.18,"end":259.36},{"word":"I","start":259.36,"end":259.52},{"word":"had","start":259.52,"end":259.66},{"word":"life","start":259.66,"end":259.96},{"word":"all","start":259.96,"end":260.24},{"word":"figured","start":260.24,"end":260.54},{"word":"out.","start":260.54,"end":260.84}],"listenDifficulty":3},{"index":57,"start":262.46,"end":267.28,"textEn":"I graduated from grad school. I landed my first big job as a therapist.","textKo":"대학원을 졸업하고, 치료사로서 첫 번째 큰 직장을 얻었어요.","words":[{"word":"I","start":262.46,"end":262.98},{"word":"graduated","start":262.98,"end":263.46},{"word":"from","start":263.46,"end":263.76},{"word":"grad","start":263.76,"end":264.04},{"word":"school.","start":264.04,"end":264.44},{"word":"I","start":264.76,"end":265.28},{"word":"landed","start":265.28,"end":265.6},{"word":"my","start":265.6,"end":265.8},{"word":"first","start":265.8,"end":266.08},{"word":"big","start":266.08,"end":266.3},{"word":"job","start":266.3,"end":266.56},{"word":"as","start":266.56,"end":266.76},{"word":"a","start":266.76,"end":266.86},{"word":"therapist.","start":266.86,"end":267.28}],"listenDifficulty":2},{"index":58,"start":268.18,"end":271.14,"textEn":"I got married. And I even bought a house.","textKo":"결혼도 했어요. 집도 샀어요.","words":[{"word":"I","start":268.18,"end":268.7},{"word":"got","start":268.7,"end":268.84},{"word":"married.","start":268.84,"end":269.26},{"word":"And","start":269.54,"end":270.0},{"word":"I","start":270.0,"end":270.1},{"word":"even","start":270.1,"end":270.32},{"word":"bought","start":270.32,"end":270.54},{"word":"a","start":270.54,"end":270.68},{"word":"house.","start":270.68,"end":271.14}],"listenDifficulty":1},{"index":59,"start":271.42,"end":275.56,"textEn":"And I thought, this is going to be great. I''ve got this incredible jump start on success.","textKo":"그리고 생각했어요, 이건 정말 좋겠다. 성공을 향한 놀라운 도약을 했구나.","words":[{"word":"And","start":271.42,"end":271.86},{"word":"I","start":271.86,"end":271.96},{"word":"thought,","start":271.96,"end":272.1},{"word":"this","start":272.16,"end":272.3},{"word":"is","start":272.3,"end":272.44},{"word":"going","start":272.44,"end":272.56},{"word":"to","start":272.56,"end":272.62},{"word":"be","start":272.62,"end":272.74},{"word":"great.","start":272.74,"end":273.06},{"word":"I''ve","start":273.18,"end":273.3},{"word":"got","start":273.3,"end":273.36},{"word":"this","start":273.36,"end":273.52},{"word":"incredible","start":273.52,"end":274.06},{"word":"jump","start":274.06,"end":274.68},{"word":"start","start":274.68,"end":274.9},{"word":"on","start":274.9,"end":275.1},{"word":"success.","start":275.1,"end":275.56}],"listenDifficulty":3},{"index":60,"start":276.18,"end":279.72,"textEn":"What could go wrong? I was like, I''m sorry.","textKo":"뭐가 잘못될 수 있겠어? 죄송해요.","words":[{"word":"What","start":276.18,"end":276.7},{"word":"could","start":276.7,"end":276.8},{"word":"go","start":276.8,"end":276.94},{"word":"wrong?","start":276.94,"end":277.28},{"word":"I","start":279.26,"end":279.72},{"word":"was","start":279.72,"end":279.72},{"word":"like,","start":279.72,"end":279.72},{"word":"I''m","start":279.72,"end":279.72},{"word":"sorry.","start":279.72,"end":279.72}],"listenDifficulty":1},{"index":61,"start":279.72,"end":283.0,"textEn":"That all changed for me one day, when I got a phone call from my sister.","textKo":"어느 날 언니한테서 전화가 오면서 모든 것이 바뀌었어요.","words":[{"word":"That","start":279.72,"end":279.72},{"word":"all","start":279.72,"end":279.88},{"word":"changed","start":279.88,"end":280.18},{"word":"for","start":280.18,"end":280.38},{"word":"me","start":280.38,"end":280.52},{"word":"one","start":280.52,"end":280.68},{"word":"day,","start":280.68,"end":280.94},{"word":"when","start":281.16,"end":281.64},{"word":"I","start":281.64,"end":281.7},{"word":"got","start":281.7,"end":281.78},{"word":"a","start":281.78,"end":281.88},{"word":"phone","start":281.88,"end":282.06},{"word":"call","start":282.06,"end":282.24},{"word":"from","start":282.24,"end":282.4},{"word":"my","start":282.4,"end":282.6},{"word":"sister.","start":282.6,"end":283.0}],"listenDifficulty":3},{"index":62,"start":284.34,"end":287.42,"textEn":"She said that our mother was found unresponsive,","textKo":"언니가 말하기를 어머니가 의식이 없는 채로 발견되었다고,","words":[{"word":"She","start":284.34,"end":284.8},{"word":"said","start":284.8,"end":284.98},{"word":"that","start":284.98,"end":285.08},{"word":"our","start":285.08,"end":285.2},{"word":"mother","start":285.2,"end":285.46},{"word":"was","start":285.46,"end":285.66},{"word":"found","start":285.66,"end":286.0},{"word":"unresponsive,","start":286.0,"end":287.42}],"listenDifficulty":2},{"index":63,"start":287.68,"end":294.36,"textEn":"And she''d been taken to the hospital. My husband Lincoln and I jumped in the car and rushed to the hospital.","textKo":"그리고 병원으로 이송되었다고 했어요. 남편 링컨과 저는 차에 뛰어타고 병원으로 달려갔어요.","words":[{"word":"and","start":287.68,"end":288.04},{"word":"she''d","start":288.04,"end":288.2},{"word":"been","start":288.2,"end":288.28},{"word":"taken","start":288.28,"end":288.52},{"word":"to","start":288.52,"end":288.7},{"word":"the","start":288.7,"end":288.82},{"word":"hospital.","start":288.82,"end":289.3},{"word":"My","start":290.44,"end":290.9},{"word":"husband","start":290.9,"end":291.18},{"word":"Lincoln","start":291.18,"end":291.5},{"word":"and","start":291.5,"end":291.7},{"word":"I","start":291.7,"end":291.88},{"word":"jumped","start":291.88,"end":292.18},{"word":"in","start":292.18,"end":292.32},{"word":"the","start":292.32,"end":292.4},{"word":"car","start":292.4,"end":292.7},{"word":"and","start":292.7,"end":293.3},{"word":"rushed","start":293.3,"end":293.6},{"word":"to","start":293.6,"end":293.76},{"word":"the","start":293.76,"end":293.88},{"word":"hospital.","start":293.88,"end":294.36}],"listenDifficulty":3},{"index":64,"start":294.7,"end":298.78,"textEn":"We couldn''t imagine what could be wrong. My mother was only 51.","textKo":"무엇이 잘못되었을지 상상할 수 없었어요. 어머니는 겨우 51세였어요.","words":[{"word":"We","start":294.7,"end":295.16},{"word":"couldn''t","start":295.16,"end":295.4},{"word":"imagine","start":295.4,"end":295.72},{"word":"what","start":295.72,"end":295.9},{"word":"could","start":295.9,"end":296.04},{"word":"be","start":296.04,"end":296.16},{"word":"wrong.","start":296.16,"end":296.54},{"word":"My","start":297.3,"end":297.76},{"word":"mother","start":297.76,"end":297.94},{"word":"was","start":297.94,"end":298.1},{"word":"only","start":298.1,"end":298.28},{"word":"51.","start":298.28,"end":298.78}],"listenDifficulty":1},{"index":65,"start":299.24,"end":302.26,"textEn":"She didn''t have any history of any kind of health problems.","textKo":"어머니에게는 어떤 종류의 건강 문제 이력도 없었어요.","words":[{"word":"She","start":299.24,"end":299.64},{"word":"didn''t","start":299.64,"end":299.76},{"word":"have","start":299.76,"end":299.9},{"word":"any","start":299.9,"end":300.08},{"word":"history","start":300.08,"end":300.34},{"word":"of","start":300.34,"end":300.5},{"word":"any","start":300.5,"end":301.16},{"word":"kind","start":301.16,"end":301.34},{"word":"of","start":301.34,"end":301.5},{"word":"health","start":301.5,"end":301.82},{"word":"problems.","start":301.82,"end":302.26}],"listenDifficulty":3},{"index":66,"start":304.26,"end":308.9,"textEn":"When we got to the hospital, doctors explained she''d had a brain aneurysm.","textKo":"병원에 도착했을 때, 의사들이 뇌동맥류가 있었다고 설명했어요.","words":[{"word":"When","start":304.26,"end":304.74},{"word":"we","start":304.74,"end":304.84},{"word":"got","start":304.84,"end":304.96},{"word":"to","start":304.96,"end":305.08},{"word":"the","start":305.08,"end":305.2},{"word":"hospital,","start":305.2,"end":305.68},{"word":"doctors","start":305.94,"end":306.28},{"word":"explained","start":306.28,"end":306.78},{"word":"she''d","start":306.78,"end":307.68},{"word":"had","start":307.68,"end":307.78},{"word":"a","start":307.78,"end":307.88},{"word":"brain","start":307.88,"end":308.16},{"word":"aneurysm.","start":308.16,"end":308.9}],"listenDifficulty":2},{"index":67,"start":309.84,"end":314.66,"textEn":"And within 24 hours, my mother, who used to wake up in the morning saying,","textKo":"그리고 24시간 이내에, 아침마다 일어나면서 이렇게 말하곤 했던 어머니가,","words":[{"word":"And","start":309.84,"end":310.32},{"word":"within","start":310.32,"end":310.54},{"word":"24","start":310.54,"end":311.02},{"word":"hours,","start":311.02,"end":311.5},{"word":"my","start":311.92,"end":312.5},{"word":"mother,","start":312.5,"end":312.78},{"word":"who","start":312.96,"end":313.2},{"word":"used","start":313.2,"end":313.38},{"word":"to","start":313.38,"end":313.5},{"word":"wake","start":313.5,"end":313.68},{"word":"up","start":313.68,"end":313.84},{"word":"in","start":313.84,"end":313.96},{"word":"the","start":313.96,"end":314.04},{"word":"morning","start":314.04,"end":314.28},{"word":"saying,","start":314.28,"end":314.66}],"listenDifficulty":3},{"index":68,"start":314.9,"end":318.12,"textEn":"It''s a great day to be alive, passed away.","textKo":"살아 있다는 건 정말 좋은 날이야, 돌아가셨어요.","words":[{"word":"it''s","start":314.9,"end":315.22},{"word":"a","start":315.22,"end":315.26},{"word":"great","start":315.26,"end":315.46},{"word":"day","start":315.46,"end":315.62},{"word":"to","start":315.62,"end":315.74},{"word":"be","start":315.74,"end":315.88},{"word":"alive,","start":315.88,"end":316.36},{"word":"passed","start":317.14,"end":317.76},{"word":"away.","start":317.76,"end":318.12}],"listenDifficulty":1},{"index":69,"start":319.18,"end":322.88,"textEn":"That news was devastating to me. My mother and I had been very close.","textKo":"그 소식은 저에게 충격적이었어요. 어머니와 저는 매우 가까웠어요.","words":[{"word":"That","start":319.18,"end":319.66},{"word":"news","start":319.66,"end":319.82},{"word":"was","start":319.82,"end":319.96},{"word":"devastating","start":319.96,"end":320.64},{"word":"to","start":320.64,"end":320.94},{"word":"me.","start":320.94,"end":321.14},{"word":"My","start":321.32,"end":321.48},{"word":"mother","start":321.48,"end":321.68},{"word":"and","start":321.68,"end":321.82},{"word":"I","start":321.82,"end":321.9},{"word":"had","start":321.9,"end":322.02},{"word":"been","start":322.02,"end":322.14},{"word":"very","start":322.14,"end":322.4},{"word":"close.","start":322.4,"end":322.88}],"listenDifficulty":3},{"index":70,"start":323.62,"end":327.48,"textEn":"As a therapist, I knew on an intellectual level how to go through grief.","textKo":"치료사로서 저는 지적인 수준에서 슬픔을 어떻게 겪어야 하는지 알고 있었어요.","words":[{"word":"As","start":323.62,"end":324.1},{"word":"a","start":324.1,"end":324.2},{"word":"therapist,","start":324.2,"end":324.62},{"word":"I","start":325.0,"end":325.14},{"word":"knew","start":325.14,"end":325.26},{"word":"on","start":325.26,"end":325.38},{"word":"an","start":325.38,"end":325.46},{"word":"intellectual","start":325.46,"end":325.88},{"word":"level","start":325.88,"end":326.3},{"word":"how","start":326.3,"end":326.64},{"word":"to","start":326.64,"end":326.74},{"word":"go","start":326.74,"end":326.86},{"word":"through","start":326.86,"end":327.06},{"word":"grief.","start":327.06,"end":327.48}],"listenDifficulty":3},{"index":71,"start":328.28,"end":331.86,"textEn":"But knowing it and doing it can be two very different things.","textKo":"하지만 아는 것과 실천하는 것은 매우 다른 일이 될 수 있어요.","words":[{"word":"But","start":328.26,"end":328.52},{"word":"knowing","start":328.52,"end":328.88},{"word":"it","start":328.88,"end":329.1},{"word":"and","start":329.1,"end":329.28},{"word":"doing","start":329.28,"end":329.5},{"word":"it","start":329.5,"end":329.78},{"word":"can","start":329.78,"end":330.6},{"word":"be","start":330.6,"end":330.72},{"word":"two","start":330.72,"end":330.88},{"word":"very","start":330.88,"end":331.14},{"word":"different","start":331.14,"end":331.38},{"word":"things.","start":331.38,"end":331.86}],"listenDifficulty":2},{"index":72,"start":332.76,"end":336.12,"textEn":"It took a long time before I felt like I was really healing.","textKo":"정말로 치유되고 있다고 느끼기까지 오랜 시간이 걸렸어요.","words":[{"word":"It","start":332.76,"end":333.28},{"word":"took","start":333.28,"end":333.42},{"word":"a","start":333.42,"end":333.54},{"word":"long","start":333.54,"end":333.68},{"word":"time","start":333.68,"end":333.92},{"word":"before","start":333.92,"end":334.24},{"word":"I","start":334.24,"end":334.9},{"word":"felt","start":334.9,"end":335.08},{"word":"like","start":335.08,"end":335.26},{"word":"I","start":335.26,"end":335.36},{"word":"was","start":335.36,"end":335.5},{"word":"really","start":335.5,"end":335.72},{"word":"healing.","start":335.72,"end":336.12}],"listenDifficulty":2},{"index":73,"start":337.98,"end":341.88,"textEn":"And then on the three-year anniversary of my mother''s death,","textKo":"그리고 어머니 사망 3주년이 되었을 때,","words":[{"word":"And","start":337.98,"end":338.5},{"word":"then","start":338.5,"end":338.68},{"word":"on","start":338.68,"end":338.94},{"word":"the","start":338.94,"end":339.06},{"word":"three","start":339.06,"end":339.32},{"word":"-year","start":339.32,"end":339.52},{"word":"anniversary","start":339.52,"end":340.06},{"word":"of","start":340.06,"end":341.04},{"word":"my","start":341.04,"end":341.2},{"word":"mother''s","start":341.2,"end":341.6},{"word":"death,","start":341.6,"end":341.88}],"listenDifficulty":1},{"index":74,"start":342.5,"end":347.18,"textEn":"Some friends called and invited Lincoln and me to a basketball game.","textKo":"친구들이 전화해서 링컨과 저를 농구 경기에 초대했어요.","words":[{"word":"some","start":342.5,"end":343.02},{"word":"friends","start":343.02,"end":343.36},{"word":"called","start":343.36,"end":343.72},{"word":"and","start":343.72,"end":344.6},{"word":"invited","start":344.6,"end":344.96},{"word":"Lincoln","start":344.96,"end":345.28},{"word":"and","start":345.28,"end":345.44},{"word":"me","start":345.44,"end":345.64},{"word":"to","start":345.64,"end":346.22},{"word":"a","start":346.22,"end":346.32},{"word":"basketball","start":346.32,"end":346.78},{"word":"game.","start":346.78,"end":347.18}],"listenDifficulty":1},{"index":75,"start":348.9,"end":353.92,"textEn":"Coincidentally, it was being played at the same auditorium where I had last seen my mother,","textKo":"우연히도 그 경기는 제가 마지막으로 어머니를 봤던 같은 강당에서 열리고 있었어요,","words":[{"word":"Coincidentally,","start":348.9,"end":349.42},{"word":"it","start":349.86,"end":350.3},{"word":"was","start":350.3,"end":350.4},{"word":"being","start":350.4,"end":350.54},{"word":"played","start":350.54,"end":350.78},{"word":"at","start":350.78,"end":350.9},{"word":"the","start":350.9,"end":351.04},{"word":"same","start":351.04,"end":351.32},{"word":"auditorium","start":351.32,"end":352.22},{"word":"where","start":352.22,"end":352.9},{"word":"I","start":352.9,"end":352.98},{"word":"had","start":352.98,"end":353.02},{"word":"last","start":353.02,"end":353.24},{"word":"seen","start":353.24,"end":353.46},{"word":"my","start":353.46,"end":353.64},{"word":"mother,","start":353.64,"end":353.92}],"listenDifficulty":3},{"index":76,"start":353.92,"end":355.94,"textEn":"And I had a great time before she passed away.","textKo":"그리고 어머니가 돌아가시기 전에 좋은 시간을 보냈던 곳이었어요.","words":[{"word":"and","start":353.92,"end":354.44},{"word":"I","start":354.44,"end":354.72},{"word":"had","start":354.72,"end":354.72},{"word":"a","start":354.72,"end":354.72},{"word":"great","start":354.72,"end":354.82},{"word":"time","start":354.82,"end":354.94},{"word":"before","start":354.94,"end":354.98},{"word":"she","start":354.98,"end":355.28},{"word":"passed","start":355.28,"end":355.58},{"word":"away.","start":355.58,"end":355.94}],"listenDifficulty":3},{"index":77,"start":357.3,"end":361.14,"textEn":"I hadn''t been back there since. I wasn''t even sure I wanted to go back.","textKo":"그 이후로 거기에 가본 적이 없었어요. 다시 가고 싶은지조차 확신이 없었어요.","words":[{"word":"I","start":357.3,"end":357.7},{"word":"hadn''t","start":357.7,"end":357.96},{"word":"been","start":357.96,"end":358.08},{"word":"back","start":358.08,"end":358.32},{"word":"there","start":358.32,"end":358.5},{"word":"since.","start":358.5,"end":358.98},{"word":"I","start":359.34,"end":359.66},{"word":"wasn''t","start":359.66,"end":359.82},{"word":"even","start":359.82,"end":359.96},{"word":"sure","start":359.96,"end":360.1},{"word":"I","start":360.1,"end":360.22},{"word":"wanted","start":360.22,"end":360.52},{"word":"to","start":360.52,"end":360.68},{"word":"go","start":360.68,"end":360.78},{"word":"back.","start":360.78,"end":361.14}],"listenDifficulty":2},{"index":78,"start":361.9,"end":367.52,"textEn":"But Lincoln and I talked about it. And ultimately, we said, maybe that''ll be a good way to honor her memory.","textKo":"하지만 링컨과 저는 그것에 대해 이야기했어요. 그리고 결국, 그것이 어머니를 기리는 좋은 방법이 될 수 있겠다고 말했어요.","words":[{"word":"But","start":361.9,"end":362.3},{"word":"Lincoln","start":362.3,"end":362.54},{"word":"and","start":362.54,"end":362.7},{"word":"I","start":362.7,"end":362.8},{"word":"talked","start":362.8,"end":363.08},{"word":"about","start":363.08,"end":363.34},{"word":"it.","start":363.34,"end":363.6},{"word":"And","start":364.32,"end":364.38},{"word":"ultimately,","start":364.38,"end":364.76},{"word":"we","start":364.82,"end":364.98},{"word":"said,","start":364.98,"end":365.22},{"word":"maybe","start":365.66,"end":365.9},{"word":"that''ll","start":365.9,"end":366.12},{"word":"be","start":366.12,"end":366.2},{"word":"a","start":366.2,"end":366.3},{"word":"good","start":366.3,"end":366.42},{"word":"way","start":366.42,"end":366.56},{"word":"to","start":366.56,"end":366.72},{"word":"honor","start":366.72,"end":366.94},{"word":"her","start":366.94,"end":367.14},{"word":"memory.","start":367.14,"end":367.52}],"listenDifficulty":2},{"index":79,"start":368.36,"end":372.18,"textEn":"So we went to the game. And we actually had a really good time with our friends.","textKo":"그래서 경기에 갔어요. 그리고 실제로 친구들과 정말 즐거운 시간을 보냈어요.","words":[{"word":"So","start":368.36,"end":368.76},{"word":"we","start":368.76,"end":368.88},{"word":"went","start":368.88,"end":369.04},{"word":"to","start":369.04,"end":369.16},{"word":"the","start":369.16,"end":369.28},{"word":"game.","start":369.28,"end":369.58},{"word":"And","start":370.08,"end":370.48},{"word":"we","start":370.48,"end":370.52},{"word":"actually","start":370.52,"end":370.74},{"word":"had","start":370.74,"end":370.86},{"word":"a","start":370.86,"end":370.96},{"word":"really","start":370.96,"end":371.14},{"word":"good","start":371.14,"end":371.3},{"word":"time","start":371.3,"end":371.56},{"word":"with","start":371.56,"end":371.7},{"word":"our","start":371.7,"end":371.82},{"word":"friends.","start":371.82,"end":372.18}],"listenDifficulty":3},{"index":80,"start":373.46,"end":378.02,"textEn":"On the drive home that night, we talked about how great it was to finally be able to go back to that","textKo":"그날 밤 집으로 가는 길에, 드디어 그곳에 다시 가서","words":[{"word":"On","start":373.46,"end":373.86},{"word":"the","start":373.86,"end":373.94},{"word":"drive","start":373.94,"end":374.14},{"word":"home","start":374.14,"end":374.38},{"word":"that","start":374.38,"end":374.56},{"word":"night,","start":374.56,"end":374.82},{"word":"we","start":375.02,"end":375.42},{"word":"talked","sta