INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'en', 'BShvYeyMm_Y', '{"videoId":"BShvYeyMm_Y","youtubeId":"BShvYeyMm_Y","title":"How America became a superpower","channel":"Vox","categoryId":"current","difficulty":"advanced","duration":535,"thumbnail":"https://i.ytimg.com/vi_webp/BShvYeyMm_Y/maxresdefault.webp","speechRateWpm":173,"addedAt":"2026-02-16","segmentCount":74,"vocabularyCount":25,"grammarPatternCount":12,"descriptionKo":"미국은 어떻게 초강대국이 되었는가 — 고립주의에서 세계 패권까지"}'::jsonb, '{"videoId":"BShvYeyMm_Y","segments":[{"index":0,"start":0.84,"end":8.84,"textEn":"The modern United States is the most powerful country in human history, with over 800 military bases and 37% of global military spending.","textKo":"현대 미국은 인류 역사상 가장 강력한 국가로, 800개 이상의 군사 기지와 전 세계 군사비의 37%를 차지하고 있습니다.","words":[{"word":"The","start":0.84,"end":1.28},{"word":"modern","start":1.28,"end":1.52},{"word":"United","start":1.52,"end":1.8},{"word":"States","start":1.8,"end":2.12},{"word":"is","start":2.12,"end":2.32},{"word":"the","start":2.32,"end":2.42},{"word":"most","start":2.42,"end":2.56},{"word":"powerful","start":2.56,"end":2.94},{"word":"country","start":2.94,"end":3.28},{"word":"in","start":3.28,"end":3.44},{"word":"human","start":3.44,"end":3.64},{"word":"history,","start":3.64,"end":4.0},{"word":"with","start":4.28,"end":4.56},{"word":"over","start":4.56,"end":4.74},{"word":"800","start":4.74,"end":5.14},{"word":"military","start":5.14,"end":5.54},{"word":"bases","start":5.54,"end":6.06},{"word":"and","start":6.06,"end":6.44},{"word":"37","start":6.44,"end":6.98},{"word":"%","start":6.98,"end":7.6},{"word":"of","start":7.6,"end":7.88},{"word":"global","start":7.88,"end":8.1},{"word":"military","start":8.1,"end":8.48},{"word":"spending.","start":8.48,"end":8.84}],"listenDifficulty":3},{"index":1,"start":9.5,"end":17.4,"textEn":"The U. S. has become the leader of a vast interconnected global system that has helped usher in an era of unprecedented prosperity and low levels of conflict.","textKo":"미국은 전례 없는 번영과 낮은 수준의 분쟁 시대를 여는 데 기여한 거대한 상호 연결된 글로벌 시스템의 리더가 되었습니다.","words":[{"word":"The","start":9.5,"end":9.94},{"word":"U","start":9.94,"end":10.08},{"word":".S.","start":10.08,"end":10.2},{"word":"has","start":10.34,"end":10.34},{"word":"become","start":10.34,"end":10.58},{"word":"the","start":10.58,"end":10.74},{"word":"leader","start":10.74,"end":10.96},{"word":"of","start":10.96,"end":11.18},{"word":"a","start":11.18,"end":11.28},{"word":"vast","start":11.28,"end":11.7},{"word":"interconnected","start":11.7,"end":12.18},{"word":"global","start":12.18,"end":12.6},{"word":"system","start":12.6,"end":13.0},{"word":"that","start":13.0,"end":13.22},{"word":"has","start":13.22,"end":13.34},{"word":"helped","start":13.34,"end":13.56},{"word":"usher","start":13.56,"end":13.9},{"word":"in","start":13.9,"end":14.02},{"word":"an","start":14.02,"end":14.14},{"word":"era","start":14.14,"end":14.34},{"word":"of","start":14.34,"end":14.5},{"word":"unprecedented","start":14.5,"end":15.24},{"word":"prosperity","start":15.24,"end":16.04},{"word":"and","start":16.04,"end":16.46},{"word":"low","start":16.46,"end":16.62},{"word":"levels","start":16.62,"end":16.86},{"word":"of","start":16.86,"end":17.0},{"word":"conflict.","start":17.0,"end":17.4}],"listenDifficulty":5},{"index":2,"start":18.56,"end":28.16,"textEn":"To understand America''s position in the world, and why it''s so pivotal for world politics as we know it, you have to go back to the country''s founding, back to when America wasn''t a global power in any sense of the word.","textKo":"세계에서 미국의 위치와, 그것이 왜 우리가 아는 세계 정치에 그토록 중요한지 이해하려면, 미국이 어떤 의미에서도 세계 강국이 아니었던 건국 시절로 돌아가야 합니다.","words":[{"word":"To","start":18.56,"end":19.0},{"word":"understand","start":19.0,"end":19.38},{"word":"America''s","start":19.38,"end":19.82},{"word":"position","start":19.82,"end":20.1},{"word":"in","start":20.1,"end":20.26},{"word":"the","start":20.26,"end":20.32},{"word":"world,","start":20.32,"end":20.6},{"word":"and","start":20.66,"end":20.98},{"word":"why","start":20.98,"end":21.22},{"word":"it''s","start":21.22,"end":21.58},{"word":"so","start":21.58,"end":21.74},{"word":"pivotal","start":21.74,"end":22.14},{"word":"for","start":22.14,"end":22.34},{"word":"world","start":22.34,"end":22.56},{"word":"politics","start":22.56,"end":22.94},{"word":"as","start":22.94,"end":23.1},{"word":"we","start":23.1,"end":23.22},{"word":"know","start":23.22,"end":23.36},{"word":"it,","start":23.36,"end":23.56},{"word":"you","start":23.7,"end":23.84},{"word":"have","start":23.84,"end":23.92},{"word":"to","start":23.92,"end":24.0},{"word":"go","start":24.0,"end":24.1},{"word":"back","start":24.1,"end":24.28},{"word":"to","start":24.28,"end":24.4},{"word":"the","start":24.4,"end":24.5},{"word":"country''s","start":24.5,"end":24.82},{"word":"founding,","start":24.82,"end":25.14},{"word":"back","start":25.38,"end":25.56},{"word":"to","start":25.56,"end":25.68},{"word":"when","start":25.68,"end":25.8},{"word":"America","start":25.8,"end":26.12},{"word":"wasn''t","start":26.12,"end":26.46},{"word":"a","start":26.46,"end":26.52},{"word":"global","start":26.52,"end":26.74},{"word":"power","start":26.74,"end":27.08},{"word":"in","start":27.08,"end":27.24},{"word":"any","start":27.24,"end":27.46},{"word":"sense","start":27.46,"end":27.72},{"word":"of","start":27.72,"end":27.84},{"word":"the","start":27.84,"end":27.94},{"word":"word.","start":27.94,"end":28.16}],"listenDifficulty":4},{"index":3,"start":28.78,"end":41.74,"textEn":"During the first 70 years of its existence, the United States expanded in both territory and influence in North America, eventually reaching the Pacific Ocean, in a wave of expansionism that resulted in the wholesale slaughter of the indigenous people who populated the continent.","textKo":"존재의 첫 70년 동안, 미국은 북미에서 영토와 영향력 모두를 확장하여 결국 태평양에 도달했으며, 이 팽창주의의 물결은 대륙에 살던 원주민들의 대량 학살을 초래했습니다.","words":[{"word":"During","start":28.78,"end":29.3},{"word":"the","start":29.3,"end":29.44},{"word":"first","start":29.44,"end":29.64},{"word":"70","start":29.64,"end":29.92},{"word":"years","start":29.92,"end":30.12},{"word":"of","start":30.12,"end":30.24},{"word":"its","start":30.24,"end":30.34},{"word":"existence,","start":30.34,"end":30.8},{"word":"the","start":31.3,"end":31.34},{"word":"United","start":31.34,"end":31.48},{"word":"States","start":31.48,"end":31.74},{"word":"expanded","start":31.74,"end":32.2},{"word":"in","start":32.2,"end":32.38},{"word":"both","start":32.38,"end":32.54},{"word":"territory","start":32.54,"end":32.98},{"word":"and","start":32.98,"end":33.24},{"word":"influence","start":33.24,"end":33.74},{"word":"in","start":33.74,"end":33.94},{"word":"North","start":33.94,"end":34.1},{"word":"America,","start":34.1,"end":34.52},{"word":"eventually","start":34.84,"end":35.12},{"word":"reaching","start":35.12,"end":35.4},{"word":"the","start":35.4,"end":35.52},{"word":"Pacific","start":35.52,"end":35.8},{"word":"Ocean,","start":35.8,"end":36.16},{"word":"in","start":36.3,"end":36.66},{"word":"a","start":36.66,"end":36.74},{"word":"wave","start":36.74,"end":36.92},{"word":"of","start":36.92,"end":37.04},{"word":"expansionism","start":37.04,"end":37.68},{"word":"that","start":37.68,"end":37.88},{"word":"resulted","start":37.88,"end":38.22},{"word":"in","start":38.22,"end":38.4},{"word":"the","start":38.4,"end":38.48},{"word":"wholesale","start":38.48,"end":38.9},{"word":"slaughter","start":38.9,"end":39.46},{"word":"of","start":39.46,"end":39.9},{"word":"the","start":39.9,"end":40.0},{"word":"indigenous","start":40.0,"end":40.3},{"word":"people","start":40.3,"end":40.68},{"word":"who","start":40.68,"end":40.84},{"word":"populated","start":40.84,"end":41.28},{"word":"the","start":41.28,"end":41.44},{"word":"continent.","start":41.44,"end":41.74}],"listenDifficulty":4},{"index":4,"start":42.48,"end":47.56,"textEn":"But early Americans were deeply divided as to whether the country should expand beyond the Pacific and Atlantic oceans.","textKo":"그러나 초기 미국인들은 국가가 태평양과 대서양 너머로 확장해야 하는지에 대해 깊이 분열되어 있었습니다.","words":[{"word":"But","start":42.48,"end":42.9},{"word":"early","start":42.9,"end":43.12},{"word":"Americans","start":43.12,"end":43.5},{"word":"were","start":43.5,"end":43.68},{"word":"deeply","start":43.68,"end":43.98},{"word":"divided","start":43.98,"end":44.34},{"word":"as","start":44.34,"end":44.52},{"word":"to","start":44.52,"end":44.6},{"word":"whether","start":44.6,"end":44.76},{"word":"the","start":44.76,"end":44.92},{"word":"country","start":44.92,"end":45.16},{"word":"should","start":45.16,"end":45.34},{"word":"expand","start":45.34,"end":45.7},{"word":"beyond","start":45.7,"end":46.06},{"word":"the","start":46.06,"end":46.24},{"word":"Pacific","start":46.24,"end":46.6},{"word":"and","start":46.6,"end":46.8},{"word":"Atlantic","start":46.8,"end":47.14},{"word":"oceans.","start":47.14,"end":47.56}],"listenDifficulty":3},{"index":5,"start":47.88,"end":56.1,"textEn":"This became a major debate after the Civil War, when some leaders, like post-war Secretary of State Seward, argued that America should push to become a global power.","textKo":"이것은 남북전쟁 이후 주요 논쟁이 되었는데, 전후 국무장관 수어드 같은 일부 지도자들이 미국이 세계 강국이 되어야 한다고 주장했기 때문입니다.","words":[{"word":"This","start":47.88,"end":48.26},{"word":"became","start":48.26,"end":48.48},{"word":"a","start":48.48,"end":48.64},{"word":"major","start":48.64,"end":48.9},{"word":"debate","start":48.9,"end":49.22},{"word":"after","start":49.22,"end":49.5},{"word":"the","start":49.5,"end":49.64},{"word":"Civil","start":49.64,"end":49.86},{"word":"War,","start":49.86,"end":50.18},{"word":"when","start":50.3,"end":50.5},{"word":"some","start":50.5,"end":50.7},{"word":"leaders,","start":50.7,"end":51.0},{"word":"like","start":51.2,"end":51.38},{"word":"post","start":51.38,"end":51.66},{"word":"-war","start":51.66,"end":51.84},{"word":"Secretary","start":51.84,"end":52.2},{"word":"of","start":52.2,"end":52.54},{"word":"State","start":52.54,"end":52.76},{"word":"Seward,","start":52.76,"end":53.12},{"word":"argued","start":53.38,"end":53.9},{"word":"that","start":53.9,"end":54.04},{"word":"America","start":54.04,"end":54.4},{"word":"should","start":54.4,"end":54.64},{"word":"push","start":54.64,"end":54.94},{"word":"to","start":54.94,"end":55.12},{"word":"become","start":55.12,"end":55.36},{"word":"a","start":55.36,"end":55.48},{"word":"global","start":55.48,"end":55.72},{"word":"power.","start":55.72,"end":56.1}],"listenDifficulty":3},{"index":6,"start":56.64,"end":65.3,"textEn":"Seward succeeded in pushing a plan to purchase Alaska from Russia, but his attempts to buy Greenland and Iceland, as well as annexed territory in the Caribbean, were all blocked by Congress.","textKo":"수어드는 러시아로부터 알래스카를 매입하는 계획을 추진하는 데 성공했지만, 그린란드와 아이슬란드를 사려는 시도와 카리브해의 영토를 병합하려는 시도는 모두 의회에 의해 저지되었습니다.","words":[{"word":"Seward","start":56.64,"end":57.14},{"word":"succeeded","start":57.14,"end":57.64},{"word":"in","start":57.64,"end":57.88},{"word":"pushing","start":57.88,"end":58.08},{"word":"a","start":58.08,"end":58.24},{"word":"plan","start":58.24,"end":58.42},{"word":"to","start":58.42,"end":58.54},{"word":"purchase","start":58.54,"end":58.82},{"word":"Alaska","start":58.82,"end":59.22},{"word":"from","start":59.22,"end":59.46},{"word":"Russia,","start":59.46,"end":59.76},{"word":"but","start":59.96,"end":60.36},{"word":"his","start":60.36,"end":60.46},{"word":"attempts","start":60.46,"end":60.7},{"word":"to","start":60.7,"end":60.84},{"word":"buy","start":60.84,"end":60.98},{"word":"Greenland","start":60.98,"end":61.42},{"word":"and","start":61.42,"end":61.54},{"word":"Iceland,","start":61.54,"end":61.88},{"word":"as","start":62.08,"end":62.38},{"word":"well","start":62.38,"end":62.5},{"word":"as","start":62.5,"end":62.62},{"word":"annexed","start":62.62,"end":63.02},{"word":"territory","start":63.02,"end":63.32},{"word":"in","start":63.32,"end":63.48},{"word":"the","start":63.48,"end":63.54},{"word":"Caribbean,","start":63.54,"end":63.86},{"word":"were","start":64.2,"end":64.42},{"word":"all","start":64.42,"end":64.52},{"word":"blocked","start":64.52,"end":64.76},{"word":"by","start":64.76,"end":64.92},{"word":"Congress.","start":64.92,"end":65.3}],"listenDifficulty":2},{"index":7,"start":66.8,"end":71.76,"textEn":"That''s because some Americans, including many on Capitol Hill, had a strong anti-imperialist bent.","textKo":"그것은 캐피톨 힐의 많은 사람들을 포함한 일부 미국인들이 강한 반제국주의적 성향을 가지고 있었기 때문입니다.","words":[{"word":"That''s","start":66.8,"end":67.3},{"word":"because","start":67.3,"end":67.48},{"word":"some","start":67.48,"end":67.68},{"word":"Americans,","start":67.68,"end":68.12},{"word":"including","start":68.32,"end":68.58},{"word":"many","start":68.58,"end":68.86},{"word":"on","start":68.86,"end":69.04},{"word":"Capitol","start":69.04,"end":69.32},{"word":"Hill,","start":69.32,"end":69.64},{"word":"had","start":69.96,"end":70.14},{"word":"a","start":70.14,"end":70.22},{"word":"strong","start":70.22,"end":70.54},{"word":"anti","start":70.54,"end":70.88},{"word":"-imperialist","start":70.88,"end":71.5},{"word":"bent.","start":71.5,"end":71.76}],"listenDifficulty":2},{"index":8,"start":71.76,"end":79.46,"textEn":"These people worried about America getting more involved in global politics, as well as having to integrate populations from quote-unquote inferior races.","textKo":"이 사람들은 미국이 세계 정치에 더 관여하는 것과, 소위 열등한 인종의 인구를 통합해야 하는 것에 대해 우려했습니다.","words":[{"word":"These","start":71.76,"end":72.48},{"word":"people","start":72.48,"end":72.72},{"word":"worried","start":72.72,"end":73.02},{"word":"about","start":73.02,"end":73.18},{"word":"America","start":73.18,"end":73.58},{"word":"getting","start":73.58,"end":73.82},{"word":"more","start":73.82,"end":74.1},{"word":"involved","start":74.1,"end":74.56},{"word":"in","start":74.56,"end":74.74},{"word":"global","start":74.74,"end":74.98},{"word":"politics,","start":74.98,"end":75.52},{"word":"as","start":75.74,"end":75.94},{"word":"well","start":75.94,"end":76.06},{"word":"as","start":76.06,"end":76.16},{"word":"having","start":76.16,"end":76.32},{"word":"to","start":76.32,"end":76.44},{"word":"integrate","start":76.44,"end":76.76},{"word":"populations","start":76.76,"end":77.34},{"word":"from","start":77.34,"end":77.68},{"word":"quote","start":77.68,"end":77.92},{"word":"-unquote","start":77.92,"end":78.24},{"word":"inferior","start":78.24,"end":78.86},{"word":"races.","start":78.86,"end":79.46}],"listenDifficulty":1},{"index":9,"start":79.8,"end":83.28,"textEn":"And this opposition applied major checks on the imperialist urge to expand.","textKo":"그리고 이 반대는 확장하려는 제국주의적 충동에 대해 주요한 견제를 가했습니다.","words":[{"word":"And","start":79.8,"end":80.14},{"word":"this","start":80.14,"end":80.28},{"word":"opposition","start":80.28,"end":80.66},{"word":"applied","start":80.66,"end":81.04},{"word":"major","start":81.04,"end":81.48},{"word":"checks","start":81.48,"end":81.82},{"word":"on","start":81.82,"end":82.0},{"word":"the","start":82.0,"end":82.08},{"word":"imperialist","start":82.08,"end":82.62},{"word":"urge","start":82.62,"end":82.8},{"word":"to","start":82.8,"end":82.96},{"word":"expand.","start":82.96,"end":83.28}],"listenDifficulty":2},{"index":10,"start":83.54,"end":88.26,"textEn":"But something was happening in the late 1800s that would change the debate about American expansionism.","textKo":"그러나 1800년대 후반에 미국 팽창주의에 대한 논쟁을 바꿀 무언가가 일어나고 있었습니다.","words":[{"word":"But","start":83.54,"end":84.04},{"word":"something","start":84.04,"end":84.26},{"word":"was","start":84.26,"end":84.42},{"word":"happening","start":84.42,"end":84.76},{"word":"in","start":84.76,"end":84.98},{"word":"the","start":84.98,"end":85.06},{"word":"late","start":85.06,"end":85.24},{"word":"1800s","start":85.24,"end":85.94},{"word":"that","start":85.94,"end":86.06},{"word":"would","start":86.06,"end":86.16},{"word":"change","start":86.16,"end":86.48},{"word":"the","start":86.48,"end":86.66},{"word":"debate","start":86.66,"end":86.94},{"word":"about","start":86.94,"end":87.2},{"word":"American","start":87.2,"end":87.56},{"word":"expansionism.","start":87.56,"end":88.26}],"listenDifficulty":2},{"index":11,"start":88.26,"end":96.42,"textEn":"The Industrial Revolution produced explosive economic growth, and the bigger U. S. economy required a more centralized state and bureaucracy to manage the growing economy.","textKo":"산업혁명은 폭발적인 경제 성장을 가져왔고, 더 커진 미국 경제는 성장하는 경제를 관리하기 위해 더 중앙집권화된 국가와 관료제를 필요로 했습니다.","words":[{"word":"The","start":88.26,"end":88.84},{"word":"Industrial","start":88.84,"end":89.1},{"word":"Revolution","start":89.1,"end":89.58},{"word":"produced","start":89.58,"end":89.96},{"word":"explosive","start":89.96,"end":90.54},{"word":"economic","start":90.54,"end":91.04},{"word":"growth,","start":91.04,"end":91.4},{"word":"and","start":91.48,"end":91.7},{"word":"the","start":91.7,"end":91.8},{"word":"bigger","start":91.8,"end":92.02},{"word":"U","start":92.02,"end":92.22},{"word":".S.","start":92.22,"end":92.32},{"word":"economy","start":92.4,"end":92.7},{"word":"required","start":92.7,"end":93.04},{"word":"a","start":93.04,"end":93.18},{"word":"more","start":93.18,"end":93.32},{"word":"centralized","start":93.32,"end":93.82},{"word":"state","start":93.82,"end":94.24},{"word":"and","start":94.24,"end":94.52},{"word":"bureaucracy","start":94.52,"end":94.94},{"word":"to","start":94.94,"end":95.34},{"word":"manage","start":95.34,"end":95.6},{"word":"the","start":95.6,"end":95.76},{"word":"growing","start":95.76,"end":95.98},{"word":"economy.","start":95.98,"end":96.42}],"listenDifficulty":2},{"index":12,"start":96.6,"end":104.6,"textEn":"Power became concentrated in the federal government, making it easier for expansionist presidents, like William McKinley, to unilaterally push American influence abroad.","textKo":"권력은 연방 정부에 집중되었고, 윌리엄 매킨리 같은 팽창주의적 대통령들이 일방적으로 미국의 영향력을 해외로 확장하는 것이 더 쉬워졌습니다.","words":[{"word":"Power","start":96.6,"end":97.16},{"word":"became","start":97.16,"end":97.42},{"word":"concentrated","start":97.42,"end":97.94},{"word":"in","start":97.94,"end":98.16},{"word":"the","start":98.16,"end":98.24},{"word":"federal","start":98.24,"end":98.44},{"word":"government,","start":98.44,"end":98.88},{"word":"making","start":99.16,"end":99.32},{"word":"it","start":99.32,"end":99.48},{"word":"easier","start":99.48,"end":99.78},{"word":"for","start":99.78,"end":100.0},{"word":"expansionist","start":100.0,"end":100.62},{"word":"presidents,","start":100.62,"end":100.98},{"word":"like","start":101.2,"end":101.44},{"word":"William","start":101.44,"end":101.66},{"word":"McKinley,","start":101.66,"end":102.1},{"word":"to","start":102.26,"end":102.62},{"word":"unilaterally","start":102.62,"end":103.2},{"word":"push","start":103.2,"end":103.52},{"word":"American","start":103.52,"end":103.84},{"word":"influence","start":103.84,"end":104.26},{"word":"abroad.","start":104.26,"end":104.6}],"listenDifficulty":2},{"index":13,"start":104.98,"end":112.8,"textEn":"The key turning point came in 1898, when President McKinley dragged the country into war with Spain over Cuba, despite some intense domestic opposition.","textKo":"핵심 전환점은 1898년에 왔는데, 매킨리 대통령이 강한 국내 반대에도 불구하고 쿠바를 둘러싼 스페인과의 전쟁으로 나라를 끌어들였을 때입니다.","words":[{"word":"The","start":104.98,"end":105.2},{"word":"key","start":105.2,"end":105.36},{"word":"turning","start":105.36,"end":105.6},{"word":"point","start":105.6,"end":105.84},{"word":"came","start":105.84,"end":106.04},{"word":"in","start":106.04,"end":106.16},{"word":"1898,","start":106.16,"end":106.84},{"word":"when","start":106.84,"end":107.34},{"word":"President","start":107.34,"end":107.66},{"word":"McKinley","start":107.66,"end":108.16},{"word":"dragged","start":108.16,"end":108.44},{"word":"the","start":108.44,"end":108.58},{"word":"country","start":108.58,"end":108.86},{"word":"into","start":108.86,"end":109.08},{"word":"war","start":109.08,"end":109.3},{"word":"with","start":109.3,"end":109.48},{"word":"Spain","start":109.48,"end":109.9},{"word":"over","start":109.9,"end":110.24},{"word":"Cuba,","start":110.24,"end":110.64},{"word":"despite","start":110.96,"end":111.32},{"word":"some","start":111.32,"end":111.6},{"word":"intense","start":111.6,"end":111.94},{"word":"domestic","start":111.94,"end":112.32},{"word":"opposition.","start":112.32,"end":112.8}],"listenDifficulty":2},{"index":14,"start":112.8,"end":119.92,"textEn":"The rising United States easily defeated the Moribund Spanish Empire, acquiring Puerto Rico, Guam, and the Philippines in the process.","textKo":"부상하는 미국은 쇠퇴하는 스페인 제국을 쉽게 물리쳤고, 그 과정에서 푸에르토리코, 괌, 필리핀을 획득했습니다.","words":[{"word":"The","start":112.8,"end":113.6},{"word":"rising","start":113.6,"end":113.88},{"word":"United","start":113.88,"end":114.2},{"word":"States","start":114.2,"end":114.58},{"word":"easily","start":114.58,"end":115.04},{"word":"defeated","start":115.04,"end":115.42},{"word":"the","start":115.42,"end":115.6},{"word":"Moribund","start":115.6,"end":115.98},{"word":"Spanish","start":115.98,"end":116.24},{"word":"Empire,","start":116.24,"end":116.66},{"word":"acquiring","start":116.98,"end":117.36},{"word":"Puerto","start":117.36,"end":117.64},{"word":"Rico,","start":117.64,"end":118.0},{"word":"Guam,","start":118.28,"end":118.68},{"word":"and","start":118.8,"end":118.84},{"word":"the","start":118.84,"end":118.96},{"word":"Philippines","start":118.96,"end":119.36},{"word":"in","start":119.36,"end":119.54},{"word":"the","start":119.54,"end":119.6},{"word":"process.","start":119.6,"end":119.92}],"listenDifficulty":2},{"index":15,"start":120.6,"end":125.5,"textEn":"Over the next two years, the U. S. would annex the Kingdom of Hawaii, Wake Island, and American Samoa.","textKo":"이후 2년에 걸쳐, 미국은 하와이 왕국, 웨이크 섬, 미국령 사모아를 병합했습니다.","words":[{"word":"Over","start":120.6,"end":121.08},{"word":"the","start":121.08,"end":121.18},{"word":"next","start":121.18,"end":121.36},{"word":"two","start":121.36,"end":121.52},{"word":"years,","start":121.52,"end":121.78},{"word":"the","start":121.98,"end":122.02},{"word":"U","start":122.02,"end":122.14},{"word":".S.","start":122.14,"end":122.24},{"word":"would","start":122.38,"end":122.38},{"word":"annex","start":122.38,"end":122.68},{"word":"the","start":122.68,"end":122.84},{"word":"Kingdom","start":122.84,"end":123.06},{"word":"of","start":123.06,"end":123.24},{"word":"Hawaii,","start":123.24,"end":123.58},{"word":"Wake","start":123.8,"end":124.04},{"word":"Island,","start":124.04,"end":124.36},{"word":"and","start":124.5,"end":124.72},{"word":"American","start":124.72,"end":125.06},{"word":"Samoa.","start":125.06,"end":125.5}],"listenDifficulty":4},{"index":16,"start":125.74,"end":130.86,"textEn":"A few years later, the U. S. took control of the Panama Canal Zone and sent troops to occupy the Dominican Republic.","textKo":"몇 년 후, 미국은 파나마 운하 지대의 통제권을 장악하고 도미니카 공화국을 점령하기 위해 군대를 보냈습니다.","words":[{"word":"A","start":125.74,"end":126.0},{"word":"few","start":126.0,"end":126.16},{"word":"years","start":126.16,"end":126.38},{"word":"later,","start":126.38,"end":126.64},{"word":"the","start":126.8,"end":126.82},{"word":"U","start":126.82,"end":126.96},{"word":".S.","start":126.96,"end":127.06},{"word":"took","start":127.08,"end":127.16},{"word":"control","start":127.16,"end":127.48},{"word":"of","start":127.48,"end":127.6},{"word":"the","start":127.6,"end":127.66},{"word":"Panama","start":127.66,"end":127.92},{"word":"Canal","start":127.92,"end":128.24},{"word":"Zone","start":128.24,"end":128.58},{"word":"and","start":128.58,"end":129.0},{"word":"sent","start":129.0,"end":129.18},{"word":"troops","start":129.18,"end":129.42},{"word":"to","start":129.42,"end":129.56},{"word":"occupy","start":129.56,"end":129.88},{"word":"the","start":129.88,"end":130.06},{"word":"Dominican","start":130.06,"end":130.34},{"word":"Republic.","start":130.34,"end":130.86}],"listenDifficulty":3},{"index":17,"start":131.04,"end":138.7,"textEn":"It also purchased the American Virgin Islands. This period of rapid acquisition of far-flung territories put the U. S. on the map as a truly global power.","textKo":"또한 미국령 버진 아일랜드를 매입했습니다. 이 먼 곳의 영토를 급속히 획득한 시기는 미국을 진정한 세계 강국으로 지도에 올려놓았습니다.","words":[{"word":"It","start":131.04,"end":131.3},{"word":"also","start":131.3,"end":131.5},{"word":"purchased","start":131.5,"end":131.86},{"word":"the","start":131.86,"end":132.0},{"word":"American","start":132.0,"end":132.28},{"word":"Virgin","start":132.28,"end":132.54},{"word":"Islands.","start":132.54,"end":132.92},{"word":"This","start":133.46,"end":133.94},{"word":"period","start":133.94,"end":134.24},{"word":"of","start":134.24,"end":134.4},{"word":"rapid","start":134.4,"end":134.68},{"word":"acquisition","start":134.68,"end":135.16},{"word":"of","start":135.16,"end":135.34},{"word":"far","start":135.34,"end":135.56},{"word":"-flung","start":135.56,"end":135.8},{"word":"territories","start":135.8,"end":136.22},{"word":"put","start":136.22,"end":136.48},{"word":"the","start":136.48,"end":136.6},{"word":"U","start":136.6,"end":136.76},{"word":".S.","start":136.76,"end":136.86},{"word":"on","start":136.94,"end":137.0},{"word":"the","start":137.0,"end":137.1},{"word":"map","start":137.1,"end":137.3},{"word":"as","start":137.3,"end":137.48},{"word":"a","start":137.48,"end":137.56},{"word":"truly","start":137.56,"end":137.9},{"word":"global","start":137.9,"end":138.32},{"word":"power.","start":138.32,"end":138.7}],"listenDifficulty":4},{"index":18,"start":139.36,"end":148.14,"textEn":"During this time, America also began using its influence to protect its growing commercial and military interests abroad, installing pro-American regimes in places like Nicaragua,","textKo":"이 시기에 미국은 또한 니카라과 같은 곳에 친미 정권을 세우는 등 해외에서 성장하는 상업적, 군사적 이익을 보호하기 위해 영향력을 사용하기 시작했으며,","words":[{"word":"During","start":139.36,"end":139.88},{"word":"this","start":139.88,"end":140.1},{"word":"time,","start":140.1,"end":140.36},{"word":"America","start":140.56,"end":140.86},{"word":"also","start":140.86,"end":141.2},{"word":"began","start":141.2,"end":141.5},{"word":"using","start":141.5,"end":141.76},{"word":"its","start":141.76,"end":141.98},{"word":"influence","start":141.98,"end":142.3},{"word":"to","start":142.3,"end":142.48},{"word":"protect","start":142.48,"end":142.74},{"word":"its","start":142.74,"end":142.96},{"word":"growing","start":142.96,"end":143.24},{"word":"commercial","start":143.24,"end":143.7},{"word":"and","start":143.7,"end":143.94},{"word":"military","start":143.94,"end":144.28},{"word":"interests","start":144.28,"end":144.64},{"word":"abroad,","start":144.64,"end":144.98},{"word":"installing","start":145.22,"end":145.9},{"word":"pro","start":145.9,"end":146.18},{"word":"-American","start":146.18,"end":146.48},{"word":"regimes","start":146.48,"end":146.94},{"word":"in","start":146.94,"end":147.14},{"word":"places","start":147.14,"end":147.38},{"word":"like","start":147.38,"end":147.58},{"word":"Nicaragua,","start":147.58,"end":148.14}],"listenDifficulty":1},{"index":19,"start":148.22,"end":152.14,"textEn":"And playing a major role in international diplomacy regarding the Western presence in China.","textKo":"중국 내 서방의 존재에 관한 국제 외교에서도 주요한 역할을 했습니다.","words":[{"word":"and","start":148.22,"end":148.46},{"word":"playing","start":148.46,"end":148.7},{"word":"a","start":148.7,"end":148.86},{"word":"major","start":148.86,"end":149.12},{"word":"role","start":149.12,"end":149.4},{"word":"in","start":149.4,"end":149.54},{"word":"international","start":149.54,"end":149.94},{"word":"diplomacy","start":149.94,"end":150.5},{"word":"regarding","start":150.5,"end":150.84},{"word":"the","start":150.84,"end":151.0},{"word":"Western","start":151.0,"end":151.26},{"word":"presence","start":151.26,"end":151.66},{"word":"in","start":151.66,"end":151.84},{"word":"China.","start":151.84,"end":152.14}],"listenDifficulty":2},{"index":20,"start":153.64,"end":156.7,"textEn":"World War I showed just how much America''s influence had grown.","textKo":"제1차 세계대전은 미국의 영향력이 얼마나 성장했는지를 보여주었습니다.","words":[{"word":"World","start":153.64,"end":154.16},{"word":"War","start":154.16,"end":154.34},{"word":"I","start":154.34,"end":154.52},{"word":"showed","start":154.52,"end":154.82},{"word":"just","start":154.82,"end":155.1},{"word":"how","start":155.1,"end":155.28},{"word":"much","start":155.28,"end":155.46},{"word":"America''s","start":155.46,"end":155.92},{"word":"influence","start":155.92,"end":156.24},{"word":"had","start":156.24,"end":156.44},{"word":"grown.","start":156.44,"end":156.7}],"listenDifficulty":2},{"index":21,"start":157.14,"end":166.02,"textEn":"Not only was American intervention a decisive factor in the war''s end, but President Wilson attended the Paris Peace Conference, which ended the war, and attempted to set the terms of the peace.","textKo":"미국의 개입이 전쟁 종결에 결정적인 요인이었을 뿐만 아니라, 윌슨 대통령은 전쟁을 종결시킨 파리 강화 회의에 참석하여 평화의 조건을 정하려고 시도했습니다.","words":[{"word":"Not","start":157.14,"end":157.32},{"word":"only","start":157.32,"end":157.64},{"word":"was","start":157.64,"end":157.92},{"word":"American","start":157.92,"end":158.26},{"word":"intervention","start":158.26,"end":158.68},{"word":"a","start":158.68,"end":158.92},{"word":"decisive","start":158.92,"end":159.4},{"word":"factor","start":159.4,"end":159.86},{"word":"in","start":159.86,"end":160.04},{"word":"the","start":160.04,"end":160.1},{"word":"war''s","start":160.1,"end":160.4},{"word":"end,","start":160.4,"end":160.7},{"word":"but","start":160.9,"end":161.24},{"word":"President","start":161.24,"end":161.58},{"word":"Wilson","start":161.58,"end":161.9},{"word":"attended","start":161.9,"end":162.28},{"word":"the","start":162.28,"end":162.44},{"word":"Paris","start":162.44,"end":162.74},{"word":"Peace","start":162.74,"end":162.98},{"word":"Conference,","start":162.98,"end":163.34},{"word":"which","start":163.4,"end":163.54},{"word":"ended","start":163.54,"end":163.72},{"word":"the","start":163.72,"end":163.86},{"word":"war,","start":163.86,"end":164.1},{"word":"and","start":164.3,"end":164.58},{"word":"attempted","start":164.58,"end":164.88},{"word":"to","start":164.88,"end":165.04},{"word":"set","start":165.04,"end":165.2},{"word":"the","start":165.2,"end":165.32},{"word":"terms","start":165.32,"end":165.54},{"word":"of","start":165.54,"end":165.68},{"word":"the","start":165.68,"end":165.76},{"word":"peace.","start":165.76,"end":166.02}],"listenDifficulty":3},{"index":22,"start":166.02,"end":175.68,"textEn":"He spearheaded America''s most ambitious foreign policy initiative yet, an international organization called the League of Nations, designed to promote peace and cooperation globally.","textKo":"그는 미국의 가장 야심 찬 외교 정책 이니셔티브를 주도했는데, 전 세계적으로 평화와 협력을 증진하기 위해 설계된 국제연맹이라는 국제기구였습니다.","words":[{"word":"He","start":166.02,"end":167.04},{"word":"spearheaded","start":167.04,"end":167.44},{"word":"America''s","start":167.44,"end":167.94},{"word":"most","start":167.94,"end":168.2},{"word":"ambitious","start":168.2,"end":168.74},{"word":"foreign","start":168.74,"end":169.08},{"word":"policy","start":169.08,"end":169.44},{"word":"initiative","start":169.44,"end":169.8},{"word":"yet,","start":169.8,"end":170.1},{"word":"an","start":170.4,"end":170.78},{"word":"international","start":170.78,"end":171.22},{"word":"organization","start":171.22,"end":171.76},{"word":"called","start":171.76,"end":172.02},{"word":"the","start":172.02,"end":172.14},{"word":"League","start":172.14,"end":172.3},{"word":"of","start":172.3,"end":172.4},{"word":"Nations,","start":172.4,"end":172.76},{"word":"designed","start":172.98,"end":173.44},{"word":"to","start":173.44,"end":173.6},{"word":"promote","start":173.6,"end":173.86},{"word":"peace","start":173.86,"end":174.24},{"word":"and","start":174.24,"end":174.7},{"word":"cooperation","start":174.7,"end":175.22},{"word":"globally.","start":175.22,"end":175.68}],"listenDifficulty":2},{"index":23,"start":176.9,"end":183.22,"textEn":"The League, a wholesale effort to remake global politics, showed just how ambitious American foreign policy had become.","textKo":"세계 정치를 재편하려는 전면적인 노력인 국제연맹은 미국 외교 정책이 얼마나 야심 차게 변했는지를 보여주었습니다.","words":[{"word":"The","start":176.9,"end":177.56},{"word":"League,","start":177.56,"end":177.78},{"word":"a","start":177.96,"end":178.18},{"word":"wholesale","start":178.18,"end":178.5},{"word":"effort","start":178.5,"end":178.92},{"word":"to","start":178.92,"end":179.12},{"word":"remake","start":179.12,"end":179.54},{"word":"global","start":179.54,"end":179.84},{"word":"politics,","start":179.84,"end":180.4},{"word":"showed","start":180.76,"end":180.96},{"word":"just","start":180.96,"end":181.2},{"word":"how","start":181.2,"end":181.38},{"word":"ambitious","start":181.38,"end":181.72},{"word":"American","start":181.72,"end":182.1},{"word":"foreign","start":182.1,"end":182.38},{"word":"policy","start":182.38,"end":182.78},{"word":"had","start":182.78,"end":182.92},{"word":"become.","start":182.92,"end":183.22}],"listenDifficulty":1},{"index":24,"start":184.5,"end":187.84,"textEn":"Yet isolationism was still a major force in the United States.","textKo":"그러나 고립주의는 여전히 미국에서 주요한 세력이었습니다.","words":[{"word":"Yet","start":184.5,"end":185.0},{"word":"isolationism","start":185.0,"end":185.7},{"word":"was","start":185.7,"end":185.88},{"word":"still","start":185.88,"end":186.0},{"word":"a","start":186.0,"end":186.18},{"word":"major","start":186.18,"end":186.44},{"word":"force","start":186.44,"end":186.86},{"word":"in","start":186.86,"end":187.1},{"word":"the","start":187.1,"end":187.18},{"word":"United","start":187.18,"end":187.38},{"word":"States.","start":187.38,"end":187.84}],"listenDifficulty":2},{"index":25,"start":189.1,"end":193.24,"textEn":"Congress blocked the United States from joining the League of Nations, dooming Wilson''s project.","textKo":"의회는 미국이 국제연맹에 가입하는 것을 막았고, 윌슨의 프로젝트를 좌절시켰습니다.","words":[{"word":"Congress","start":189.1,"end":189.58},{"word":"blocked","start":189.58,"end":189.96},{"word":"the","start":189.96,"end":190.08},{"word":"United","start":190.08,"end":190.26},{"word":"States","start":190.26,"end":190.56},{"word":"from","start":190.56,"end":190.7},{"word":"joining","start":190.7,"end":190.92},{"word":"the","start":190.92,"end":191.06},{"word":"League","start":191.06,"end":191.2},{"word":"of","start":191.2,"end":191.32},{"word":"Nations,","start":191.32,"end":191.66},{"word":"dooming","start":191.98,"end":192.46},{"word":"Wilson''s","start":192.46,"end":192.88},{"word":"project.","start":192.88,"end":193.24}],"listenDifficulty":2},{"index":26,"start":194.76,"end":200.2,"textEn":"During the Great Depression and the rise of Hitler, the U. S. was much more focused on its own region than on European affairs.","textKo":"대공황과 히틀러의 부상 동안, 미국은 유럽 문제보다 자국 지역에 훨씬 더 집중했습니다.","words":[{"word":"During","start":194.76,"end":195.24},{"word":"the","start":195.24,"end":195.34},{"word":"Great","start":195.34,"end":195.46},{"word":"Depression","start":195.46,"end":195.84},{"word":"and","start":195.84,"end":196.04},{"word":"the","start":196.04,"end":196.1},{"word":"rise","start":196.1,"end":196.28},{"word":"of","start":196.28,"end":196.38},{"word":"Hitler,","start":196.38,"end":196.62},{"word":"the","start":197.08,"end":197.14},{"word":"U","start":197.14,"end":197.28},{"word":".S.","start":197.28,"end":197.38},{"word":"was","start":197.5,"end":197.5},{"word":"much","start":197.5,"end":197.76},{"word":"more","start":197.76,"end":197.94},{"word":"focused","start":197.94,"end":198.3},{"word":"on","start":198.3,"end":198.54},{"word":"its","start":198.54,"end":198.7},{"word":"own","start":198.7,"end":198.94},{"word":"region","start":198.94,"end":199.24},{"word":"than","start":199.24,"end":199.42},{"word":"on","start":199.42,"end":199.54},{"word":"European","start":199.54,"end":199.84},{"word":"affairs.","start":199.84,"end":200.2}],"listenDifficulty":3},{"index":27,"start":201.22,"end":206.76,"textEn":"Ultimately, America''s ever-growing entanglements abroad made it impossible for it to stay out of global affairs entirely.","textKo":"궁극적으로, 해외에서 점점 커지는 미국의 얽힘은 글로벌 문제에서 완전히 빠져나가는 것을 불가능하게 만들었습니다.","words":[{"word":"Ultimately,","start":201.22,"end":201.7},{"word":"America''s","start":202.12,"end":202.5},{"word":"ever","start":202.5,"end":202.72},{"word":"-growing","start":202.72,"end":203.06},{"word":"entanglements","start":203.06,"end":203.64},{"word":"abroad","start":203.64,"end":203.92},{"word":"made","start":203.92,"end":204.24},{"word":"it","start":204.24,"end":204.36},{"word":"impossible","start":204.36,"end":204.8},{"word":"for","start":204.8,"end":205.16},{"word":"it","start":205.16,"end":205.26},{"word":"to","start":205.26,"end":205.36},{"word":"stay","start":205.36,"end":205.54},{"word":"out","start":205.54,"end":205.7},{"word":"of","start":205.7,"end":205.76},{"word":"global","start":205.76,"end":206.0},{"word":"affairs","start":206.0,"end":206.36},{"word":"entirely.","start":206.36,"end":206.76}],"listenDifficulty":3},{"index":28,"start":206.76,"end":214.98,"textEn":"In East Asia, the growing Japanese empire posed a direct threat to American possessions and troops, bringing the United States and Japan into conflict.","textKo":"동아시아에서, 성장하는 일본 제국은 미국의 소유지와 군대에 직접적인 위협을 가했고, 미국과 일본을 갈등으로 이끌었습니다.","words":[{"word":"In","start":206.76,"end":207.62},{"word":"East","start":207.62,"end":207.84},{"word":"Asia,","start":207.84,"end":208.18},{"word":"the","start":208.38,"end":208.48},{"word":"growing","start":208.48,"end":208.76},{"word":"Japanese","start":208.76,"end":209.18},{"word":"empire","start":209.18,"end":209.56},{"word":"posed","start":209.56,"end":209.96},{"word":"a","start":209.96,"end":210.12},{"word":"direct","start":210.12,"end":210.48},{"word":"threat","start":210.48,"end":210.88},{"word":"to","start":210.88,"end":211.1},{"word":"American","start":211.1,"end":211.42},{"word":"possessions","start":211.42,"end":211.88},{"word":"and","start":211.88,"end":212.16},{"word":"troops,","start":212.16,"end":212.54},{"word":"bringing","start":212.82,"end":213.48},{"word":"the","start":213.48,"end":213.62},{"word":"United","start":213.62,"end":213.8},{"word":"States","start":213.8,"end":214.08},{"word":"and","start":214.08,"end":214.18},{"word":"Japan","start":214.18,"end":214.42},{"word":"into","start":214.42,"end":214.58},{"word":"conflict.","start":214.58,"end":214.98}],"listenDifficulty":1},{"index":29,"start":215.26,"end":219.3,"textEn":"This culminated in the Pearl Harbor attack, bringing the United States into World War II.","textKo":"이것은 진주만 공격으로 절정에 달했고, 미국을 제2차 세계대전으로 끌어들였습니다.","words":[{"word":"This","start":215.26,"end":215.58},{"word":"culminated","start":215.58,"end":216.14},{"word":"in","start":216.14,"end":216.32},{"word":"the","start":216.32,"end":216.42},{"word":"Pearl","start":216.42,"end":216.58},{"word":"Harbor","start":216.58,"end":216.88},{"word":"attack,","start":216.88,"end":217.2},{"word":"bringing","start":217.2,"end":217.9},{"word":"the","start":217.9,"end":218.04},{"word":"United","start":218.04,"end":218.26},{"word":"States","start":218.26,"end":218.56},{"word":"into","start":218.56,"end":218.74},{"word":"World","start":218.74,"end":218.92},{"word":"War","start":218.92,"end":219.08},{"word":"II.","start":219.08,"end":219.3}],"listenDifficulty":3},{"index":30,"start":219.72,"end":222.44,"textEn":"World War II would transform America''s global presence forever.","textKo":"제2차 세계대전은 미국의 세계적 존재를 영원히 변화시킬 것이었습니다.","words":[{"word":"World","start":219.72,"end":220.02},{"word":"War","start":220.02,"end":220.2},{"word":"II","start":220.2,"end":220.36},{"word":"would","start":220.36,"end":220.5},{"word":"transform","start":220.5,"end":220.9},{"word":"America''s","start":220.9,"end":221.38},{"word":"global","start":221.38,"end":221.62},{"word":"presence","start":221.62,"end":222.04},{"word":"forever.","start":222.04,"end":222.44}],"listenDifficulty":2},{"index":31,"start":223.54,"end":230.62,"textEn":"The United States was the only major power to avoid economic ruin during the war, and it was the sole country equipped with atomic weapons.","textKo":"미국은 전쟁 중 경제적 파탄을 면한 유일한 주요 강국이었고, 핵무기를 보유한 유일한 나라였습니다.","words":[{"word":"The","start":223.54,"end":223.8},{"word":"United","start":223.8,"end":223.96},{"word":"States","start":223.96,"end":224.26},{"word":"was","start":224.26,"end":224.4},{"word":"the","start":224.4,"end":224.54},{"word":"only","start":224.54,"end":224.88},{"word":"major","start":224.88,"end":225.16},{"word":"power","start":225.16,"end":225.44},{"word":"to","start":225.44,"end":225.66},{"word":"avoid","start":225.66,"end":225.94},{"word":"economic","start":225.94,"end":226.36},{"word":"ruin","start":226.36,"end":226.7},{"word":"during","start":226.7,"end":226.9},{"word":"the","start":226.9,"end":227.06},{"word":"war,","start":227.06,"end":227.28},{"word":"and","start":227.32,"end":228.6},{"word":"it","start":228.6,"end":228.68},{"word":"was","start":228.68,"end":228.78},{"word":"the","start":228.78,"end":228.9},{"word":"sole","start":228.9,"end":229.14},{"word":"country","start":229.14,"end":229.46},{"word":"equipped","start":229.46,"end":229.74},{"word":"with","start":229.74,"end":229.88},{"word":"atomic","start":229.88,"end":230.16},{"word":"weapons.","start":230.16,"end":230.62}],"listenDifficulty":3},{"index":32,"start":230.62,"end":237.96,"textEn":"As such, it was in a unique position to set the terms of the peace, and, with the aim of preventing another war in mind, it took advantage.","textKo":"그래서 미국은 평화의 조건을 정할 독특한 위치에 있었으며, 또 다른 전쟁을 방지하려는 목적으로 그 이점을 활용했습니다.","words":[{"word":"As","start":230.62,"end":231.48},{"word":"such,","start":231.48,"end":231.74},{"word":"it","start":231.94,"end":232.0},{"word":"was","start":232.0,"end":232.1},{"word":"in","start":232.1,"end":232.2},{"word":"a","start":232.2,"end":232.28},{"word":"unique","start":232.28,"end":232.6},{"word":"position","start":232.6,"end":233.0},{"word":"to","start":233.0,"end":233.16},{"word":"set","start":233.16,"end":233.3},{"word":"the","start":233.3,"end":233.42},{"word":"terms","start":233.42,"end":233.6},{"word":"of","start":233.6,"end":233.72},{"word":"the","start":233.72,"end":233.8},{"word":"peace,","start":233.8,"end":234.12},{"word":"and,","start":234.26,"end":234.9},{"word":"with","start":235.0,"end":235.34},{"word":"the","start":235.34,"end":235.46},{"word":"aim","start":235.46,"end":235.66},{"word":"of","start":235.66,"end":235.78},{"word":"preventing","start":235.78,"end":236.14},{"word":"another","start":236.14,"end":236.44},{"word":"war","start":236.44,"end":236.68},{"word":"in","start":236.68,"end":236.82},{"word":"mind,","start":236.82,"end":237.08},{"word":"it","start":237.32,"end":237.5},{"word":"took","start":237.5,"end":237.64},{"word":"advantage.","start":237.64,"end":237.96}],"listenDifficulty":3},{"index":33,"start":238.26,"end":241.52,"textEn":"The most famous example of this is the creation of the United Nations.","textKo":"이것의 가장 유명한 예가 유엔의 창설입니다.","words":[{"word":"The","start":238.26,"end":238.68},{"word":"most","start":238.68,"end":238.86},{"word":"famous","start":238.86,"end":239.16},{"word":"example","start":239.16,"end":239.54},{"word":"of","start":239.54,"end":239.7},{"word":"this","start":239.7,"end":239.84},{"word":"is","start":239.84,"end":239.98},{"word":"the","start":239.98,"end":240.1},{"word":"creation","start":240.1,"end":240.46},{"word":"of","start":240.46,"end":240.76},{"word":"the","start":240.76,"end":240.86},{"word":"United","start":240.86,"end":241.1},{"word":"Nations.","start":241.1,"end":241.52}],"listenDifficulty":3},{"index":34,"start":241.92,"end":247.94,"textEn":"The UN Charter set up a system of international law prohibiting wars of conquest, like the ones waged by the Nazis and the Japanese.","textKo":"유엔 헌장은 나치와 일본이 벌인 것과 같은 정복 전쟁을 금지하는 국제법 체계를 수립했습니다.","words":[{"word":"The","start":241.92,"end":242.36},{"word":"UN","start":242.36,"end":242.56},{"word":"Charter","start":242.56,"end":242.88},{"word":"set","start":242.88,"end":243.12},{"word":"up","start":243.12,"end":243.24},{"word":"a","start":243.24,"end":243.38},{"word":"system","start":243.38,"end":243.68},{"word":"of","start":243.68,"end":243.86},{"word":"international","start":243.86,"end":244.22},{"word":"law","start":244.22,"end":244.62},{"word":"prohibiting","start":244.62,"end":245.08},{"word":"wars","start":245.08,"end":245.3},{"word":"of","start":245.3,"end":245.44},{"word":"conquest,","start":245.44,"end":245.88},{"word":"like","start":246.06,"end":246.24},{"word":"the","start":246.24,"end":246.36},{"word":"ones","start":246.36,"end":246.5},{"word":"waged","start":246.5,"end":246.84},{"word":"by","start":246.84,"end":247.0},{"word":"the","start":247.0,"end":247.08},{"word":"Nazis","start":247.08,"end":247.36},{"word":"and","start":247.36,"end":247.5},{"word":"the","start":247.5,"end":247.58},{"word":"Japanese.","start":247.58,"end":247.94}],"listenDifficulty":3},{"index":35,"start":248.44,"end":253.64,"textEn":"It also served as a forum in which the international community could weigh in on disputes and help resolve them.","textKo":"또한 국제 사회가 분쟁에 대해 의견을 표명하고 해결을 도울 수 있는 포럼의 역할도 했습니다.","words":[{"word":"It","start":248.44,"end":248.88},{"word":"also","start":248.88,"end":249.14},{"word":"served","start":249.14,"end":249.44},{"word":"as","start":249.44,"end":249.56},{"word":"a","start":249.56,"end":249.64},{"word":"forum","start":249.64,"end":249.96},{"word":"in","start":249.96,"end":250.16},{"word":"which","start":250.16,"end":250.28},{"word":"the","start":250.28,"end":250.42},{"word":"international","start":250.42,"end":250.82},{"word":"community","start":250.82,"end":251.26},{"word":"could","start":251.26,"end":251.52},{"word":"weigh","start":251.52,"end":251.74},{"word":"in","start":251.74,"end":251.96},{"word":"on","start":251.96,"end":252.08},{"word":"disputes","start":252.08,"end":252.54},{"word":"and","start":252.54,"end":253.0},{"word":"help","start":253.0,"end":253.14},{"word":"resolve","start":253.14,"end":253.44},{"word":"them.","start":253.44,"end":253.64}],"listenDifficulty":4},{"index":36,"start":253.64,"end":260.04,"textEn":"This way, the Americans hoped, great powers could resolve their differences through compromise and law rather than war.","textKo":"이러한 방식으로, 미국인들은 강대국들이 전쟁이 아닌 타협과 법을 통해 차이를 해결할 수 있기를 희망했습니다.","words":[{"word":"This","start":253.64,"end":254.44},{"word":"way,","start":254.44,"end":254.64},{"word":"the","start":254.7,"end":254.8},{"word":"Americans","start":254.8,"end":255.14},{"word":"hoped,","start":255.14,"end":255.48},{"word":"great","start":255.8,"end":256.24},{"word":"powers","start":256.24,"end":256.64},{"word":"could","start":256.64,"end":256.86},{"word":"resolve","start":256.86,"end":257.18},{"word":"their","start":257.18,"end":257.34},{"word":"differences","start":257.34,"end":257.72},{"word":"through","start":257.72,"end":257.94},{"word":"compromise","start":257.94,"end":258.42},{"word":"and","start":258.42,"end":258.76},{"word":"law","start":258.76,"end":259.1},{"word":"rather","start":259.1,"end":259.58},{"word":"than","start":259.58,"end":259.82},{"word":"war.","start":259.82,"end":260.04}],"listenDifficulty":1},{"index":37,"start":261.56,"end":265.78,"textEn":"But while the UN is the most famous of the post-war institutions, it isn''t the only one.","textKo":"그러나 유엔이 전후 기관 중 가장 유명하지만, 유일한 것은 아닙니다.","words":[{"word":"But","start":261.56,"end":262.12},{"word":"while","start":262.12,"end":262.26},{"word":"the","start":262.26,"end":262.4},{"word":"UN","start":262.4,"end":262.62},{"word":"is","start":262.62,"end":262.84},{"word":"the","start":262.84,"end":262.94},{"word":"most","start":262.94,"end":263.1},{"word":"famous","start":263.1,"end":263.46},{"word":"of","start":263.46,"end":263.6},{"word":"the","start":263.6,"end":263.68},{"word":"post","start":263.68,"end":263.9},{"word":"-war","start":263.9,"end":264.04},{"word":"institutions,","start":264.04,"end":264.54},{"word":"it","start":264.84,"end":264.96},{"word":"isn''t","start":264.96,"end":265.18},{"word":"the","start":265.18,"end":265.3},{"word":"only","start":265.3,"end":265.52},{"word":"one.","start":265.52,"end":265.78}],"listenDifficulty":3},{"index":38,"start":266.9,"end":272.44,"textEn":"730 delegates from all 44 allied nations came together in a small vacation haven in New Hampshire.","textKo":"44개 연합국 모두에서 730명의 대표가 뉴햄프셔의 작은 휴양지에 모였습니다.","words":[{"word":"730","start":266.9,"end":267.46},{"word":"delegates","start":267.46,"end":267.86},{"word":"from","start":267.86,"end":268.22},{"word":"all","start":268.22,"end":268.54},{"word":"44","start":268.54,"end":269.04},{"word":"allied","start":269.04,"end":269.44},{"word":"nations","start":269.44,"end":269.92},{"word":"came","start":269.92,"end":270.2},{"word":"together","start":270.2,"end":270.56},{"word":"in","start":270.56,"end":270.74},{"word":"a","start":270.74,"end":270.84},{"word":"small","start":270.84,"end":271.12},{"word":"vacation","start":271.12,"end":271.56},{"word":"haven","start":271.56,"end":271.82},{"word":"in","start":271.82,"end":271.98},{"word":"New","start":271.98,"end":272.1},{"word":"Hampshire.","start":272.1,"end":272.44}],"listenDifficulty":1},{"index":39,"start":272.74,"end":278.0,"textEn":"Their goal? To establish a global financial system that would prevent another Great Depression and World War.","textKo":"그들의 목표는? 또 다른 대공황과 세계대전을 방지할 글로벌 금융 시스템을 수립하는 것이었습니다.","words":[{"word":"Their","start":272.74,"end":273.16},{"word":"goal?","start":273.16,"end":273.4},{"word":"To","start":273.54,"end":273.94},{"word":"establish","start":273.94,"end":274.32},{"word":"a","start":274.32,"end":274.5},{"word":"global","start":274.5,"end":274.78},{"word":"financial","start":274.78,"end":275.16},{"word":"system","start":275.16,"end":275.56},{"word":"that","start":275.56,"end":275.74},{"word":"would","start":275.74,"end":275.86},{"word":"prevent","start":275.86,"end":276.14},{"word":"another","start":276.14,"end":276.58},{"word":"Great","start":276.58,"end":276.8},{"word":"Depression","start":276.8,"end":277.24},{"word":"and","start":277.24,"end":277.5},{"word":"World","start":277.5,"end":277.72},{"word":"War.","start":277.72,"end":278.0}],"listenDifficulty":2},{"index":40,"start":279.94,"end":288.48,"textEn":"The resulting agreement, called the Bretton Woods 