INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'en', 'n4NVPg2kHv4', '{"videoId":"n4NVPg2kHv4","youtubeId":"n4NVPg2kHv4","title":"English Pronunciation Training | Improve Your Accent & Speak Clearly","channel":"mmmEnglish","categoryId":"pronunciation","difficulty":"beginner","duration":466,"thumbnail":"https://i.ytimg.com/vi_webp/n4NVPg2kHv4/maxresdefault.webp","speechRateWpm":97,"addedAt":"2026-02-16","segmentCount":82,"vocabularyCount":20,"grammarPatternCount":12,"descriptionKo":"영어 발음 훈련 — 악센트 개선과 명확한 발음 연습"}'::jsonb, '{"videoId":"n4NVPg2kHv4","segments":[{"index":0,"start":0.0,"end":13.66,"textEn":"Music Hey guys! I know you''re super keen to improve your English pronunciation","textKo":"음악 안녕하세요 여러분! 영어 발음을 향상시키고 싶어하시는 거 알아요","words":[{"word":"Music","start":0.0,"end":0.46},{"word":"Hey","start":8.82,"end":9.26},{"word":"guys!","start":9.26,"end":9.6},{"word":"I","start":9.8,"end":10.22},{"word":"know","start":10.22,"end":10.48},{"word":"you''re","start":10.48,"end":10.82},{"word":"super","start":10.82,"end":11.32},{"word":"keen","start":11.32,"end":11.6},{"word":"to","start":11.6,"end":11.82},{"word":"improve","start":11.82,"end":12.18},{"word":"your","start":12.18,"end":12.46},{"word":"English","start":12.46,"end":12.9},{"word":"pronunciation","start":12.9,"end":13.66}],"listenDifficulty":3},{"index":1,"start":13.66,"end":16.76,"textEn":"And to do that you need two things.","textKo":"그리고 그렇게 하려면 두 가지가 필요해요.","words":[{"word":"and","start":13.66,"end":14.54},{"word":"to","start":14.54,"end":14.7},{"word":"do","start":14.7,"end":14.84},{"word":"that","start":14.84,"end":15.1},{"word":"you","start":15.1,"end":15.48},{"word":"need","start":15.48,"end":15.8},{"word":"two","start":15.8,"end":16.32},{"word":"things.","start":16.32,"end":16.76}],"listenDifficulty":3},{"index":2,"start":17.22,"end":26.72,"textEn":"A native English speaker and a super amazing tool called the IPA,","textKo":"원어민 영어 화자와 IPA라고 불리는 아주 놀라운 도구가요,","words":[{"word":"A","start":17.22,"end":17.82},{"word":"native","start":17.82,"end":18.2}