INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'zh', '3K0D2hHYi04', '{"videoId":"3K0D2hHYi04","youtubeId":"3K0D2hHYi04","title":"HSK 1-2 | 中文对话：聊聊你的上个周末 | Talk About Your Weekend in Chinese","channel":"Chinese Daily Podcast","categoryId":"daily","difficulty":"elementary","duration":783,"thumbnail":"https://i.ytimg.com/vi/3K0D2hHYi04/maxresdefault.jpg","speechRateWpm":0,"addedAt":"2026-02-18","segmentCount":239,"vocabularyCount":23,"grammarPatternCount":12,"speechRateCpm":323}'::jsonb, '{"videoId":"3K0D2hHYi04","segments":[{"index":0,"start":7.96,"end":11.28,"textZh":"李明 早上好 早上好 王宇","pinyin":"Lǐ Míng, zǎoshang hǎo. Zǎoshang hǎo, Wáng Yǔ.","textKo":"리밍, 좋은 아침. 좋은 아침, 왕위.","words":[{"word":"李","start":7.96,"end":8.48},{"word":"明","start":8.48,"end":8.7},{"word":"早","start":8.98,"end":9.3},{"word":"上","start":9.3,"end":9.48},{"word":"好","start":9.48,"end":9.84},{"word":"早","start":9.84,"end":10.7},{"word":"上","start":10.7,"end":10.84},{"word":"好","start":10.84,"end":10.96},{"word":"王","start":11.04,"end":11.12},{"word":"宇","start":11.12,"end":11.28}]},{"index":1,"start":12.96,"end":16.34,"textZh":"你怎么了 今天看起来没什么精神","pinyin":"Nǐ zěnme le? Jīntiān kàn qǐlái méi shénme jīngshén.","textKo":"너 왜 그래? 오늘 기운이 없어 보여.","words":[{"word":"你","start":12.96,"end":13.48},{"word":"怎么了","start":13.48,"end":13.86},{"word":"今天","start":13.86,"end":14.72},{"word":"看","start":14.72,"end":14.98},{"word":"起","start":14.98,"end":15.14},{"word":"来","start":15.14,"end":15.4},{"word":"没","start":15.4,"end":15.7},{"word":"什么","start":15.7,"end":15.92},{"word":"精","start":15.92,"end":16.12},{"word":"神","start":16.12,"end":16.34}]},{"index":2,"start":16.34,"end":19.66,"textZh":"有点累的样子 别提了","pinyin":"Yǒudiǎn lèi de yàngzi. Bié tí le.","textKo":"좀 피곤해 보이네. 말도 마.","words":[{"word":"有","start":16.34,"end":17.1},{"word":"点","start":17.1,"end":17.2},{"word":"累","start":17.2,"end":17.4},{"word":"的","start":17.4,"end":17.54},{"word":"样","start":17.54,"end":17.68},{"word":"子","start":17.68,"end":17.9},{"word":"别","start":18.64,"end":19.16},{"word":"提","start":19.16,"end":19.42},{"word":"了","start":19.42,"end":19.66}]},{"index":3,"start":19.66,"end":23.26,"textZh":"我感觉我的周末好像被偷走了","pinyin":"Wǒ gǎnjué wǒ de zhōumò hǎoxiàng bèi tōu zǒu le.","textKo":"내 주말이 도둑맞은 것 같아.","words":[{"word":"我","start":19.66,"end":20.4},{"word":"感","start":20.4,"end":20.56},{"word":"觉","start":20.56,"end":20.8},{"word":"我的","start":20.8,"end":21.16},{"word":"周","start":21.16,"end":21.34},{"word":"末","start":21.34,"end":21.64},{"word":"好像","start":21.64,"end":22.22},{"word":"被","start":22.22,"end":22.44},{"word":"偷","start":22.44,"end":22.78},{"word":"走了","start":22.78,"end":23.26}]},{"index":4,"start":23.26,"end":26.24,"textZh":"被偷走了 这么严重","pinyin":"Bèi tōu zǒu le? Zhème yánzhòng?","textKo":"도둑맞았다고? 그렇게 심해?","words":[{"word":"被","start":23.26,"end":24.02},{"word":"偷","start":24.02,"end":24.44},{"word":"走了","start":24.44,"end":24.92},{"word":"这么","start":24.92,"end":25.8},{"word":"严","start":25.8,"end":26.04},{"word":"重","start":26.04,"end":26.24}]},{"index":5,"start":26.8,"end":31.82,"textZh":"你的周末做什么了 是不是去参加什么很累的活动了","pinyin":"Nǐ de zhōumò zuò shénme le? Shì bú shì qù cānjiā shénme hěn lèi de huódòng le?","textKo":"주말에 뭐 했어? 뭔가 힘든 활동에 참가한 거야?","words":[{"word":"你的","start":26.8,"end":27.32},{"word":"周","start":27.32,"end":27.48},{"word":"末","start":27.48,"end":27.74},{"word":"做","start":27.74,"end":28.02},{"word":"什么","start":28.02,"end":28.32},{"word":"了","start":28.32,"end":28.48},{"word":"是不是","start":28.48,"end":29.4},{"word":"去","start":29.4,"end":29.88},{"word":"参","start":29.88,"end":30.12},{"word":"加","start":30.12,"end":30.36},{"word":"什么","start":30.36,"end":30.7},{"word":"很","start":30.7,"end":30.96},{"word":"累","start":30.96,"end":31.12},{"word":"的","start":31.12,"end":31.26},{"word":"活","start":31.26,"end":31.48},{"word":"动","start":31.48,"end":31.64},{"word":"了","start":31.64,"end":31.82}]},{"index":6,"start":34.4,"end":38.86,"textZh":"没有 我哪儿都没去 我整个周末都在家","pinyin":"Méiyǒu, wǒ nǎr dōu méi qù. Wǒ zhěnggè zhōumò dōu zài jiā.","textKo":"아니, 나 아무 데도 안 갔어. 주말 내내 집에 있었어.","words":[{"word":"没有","start":34.4,"end":34.88},{"word":"我","start":34.88,"end":35.36},{"word":"哪","start":35.36,"end":35.6},{"word":"儿","start":35.6,"end":35.78},{"word":"都","start":35.78,"end":35.88},{"word":"没","start":35.88,"end":36.08},{"word":"去","start":36.08,"end":36.38},{"word":"我","start":36.38,"end":37.1},{"word":"整","start":37.1,"end":37.32},{"word":"个","start":37.32,"end":37.5},{"word":"周","start":37.5,"end":37.7},{"word":"末","start":37.7,"end":37.98},{"word":"都","start":37.98,"end":38.28},{"word":"在","start":38.28,"end":38.54},{"word":"家","start":38.54,"end":38.86}]},{"index":7,"start":40.06,"end":42.68,"textZh":"哈 在家待着还会这么累","pinyin":"Hā, zài jiā dāizhe hái huì zhème lèi?","textKo":"하, 집에 있으면서 이렇게 피곤해?","words":[{"word":"哈","start":40.06,"end":40.54},{"word":"在","start":40.54,"end":41.02},{"word":"家","start":41.02,"end":41.24},{"word":"待","start":41.24,"end":41.46},{"word":"着","start":41.46,"end":41.76},{"word":"还","start":41.76,"end":42.1},{"word":"会","start":42.1,"end":42.26},{"word":"这么","start":42.26,"end":42.46},{"word":"累","start":42.46,"end":42.68}]},{"index":8,"start":43.3,"end":47.92,"textZh":"这我就不明白了 你不是最喜欢在家的吗","pinyin":"Zhè wǒ jiù bù míngbai le. Nǐ bú shì zuì xǐhuān zài jiā de ma?","textKo":"그건 이해가 안 되네. 너 집에 있는 거 제일 좋아하잖아?","words":[{"word":"这","start":43.3,"end":43.78},{"word":"我就","start":43.78,"end":44.06},{"word":"不","start":44.06,"end":44.26},{"word":"明白","start":44.26,"end":44.52},{"word":"了","start":44.52,"end":44.8},{"word":"你","start":45.5,"end":45.98},{"word":"不是","start":45.98,"end":46.26},{"word":"最","start":46.26,"end":46.82},{"word":"喜欢","start":46.82,"end":47.2},{"word":"在","start":47.2,"end":47.38},{"word":"家","start":47.38,"end":47.58},{"word":"的","start":47.58,"end":47.72},{"word":"吗","start":47.72,"end":47.92}]},{"index":9,"start":48.94,"end":51.32,"textZh":"是啊 我本来计划得很好","pinyin":"Shì a, wǒ běnlái jìhuà de hěn hǎo.","textKo":"그래, 원래 계획은 잘 세웠어.","words":[{"word":"是啊","start":48.94,"end":49.42},{"word":"我","start":49.42,"end":49.9},{"word":"本","start":49.9,"end":50.1},{"word":"来","start":50.1,"end":50.28},{"word":"计","start":50.28,"end":50.52},{"word":"划","start":50.52,"end":50.68},{"word":"得","start":50.68,"end":50.8},{"word":"很好","start":50.8,"end":51.32}]},{"index":10,"start":51.84,"end":53.9,"textZh":"我想星期六睡到中午","pinyin":"Wǒ xiǎng xīngqīliù shuì dào zhōngwǔ.","textKo":"토요일에 점심때까지 자려고 했어.","words":[{"word":"我想","start":51.84,"end":52.32},{"word":"星","start":52.32,"end":52.54},{"word":"期","start":52.54,"end":52.7},{"word":"六","start":52.7,"end":52.92},{"word":"睡","start":52.92,"end":53.18},{"word":"到","start":53.18,"end":53.36},{"word":"中","start":53.36,"end":53.58},{"word":"午","start":53.58,"end":53.9}]},{"index":11,"start":53.9,"end":57.5,"textZh":"下午看一部电影 晚上早点睡觉","pinyin":"Xiàwǔ kàn yī bù diànyǐng, wǎnshàng zǎo diǎn shuìjiào.","textKo":"오후에 영화 한 편 보고, 밤에 일찍 자려고 했어.","words":[{"word":"下","start":53.9,"end":54.46},{"word":"午","start":54.46,"end":54.7},{"word":"看","start":54.7,"end":55.0},{"word":"一","start":55.0,"end":55.14},{"word":"部","start":55.14,"end":55.24},{"word":"电","start":55.24,"end":55.44},{"word":"影","start":55.44,"end":55.72},{"word":"晚上","start":55.72,"end":56.5},{"word":"早","start":56.5,"end":56.94},{"word":"点","start":56.94,"end":57.1},{"word":"睡","start":57.1,"end":57.28},{"word":"觉","start":57.28,"end":57.5}]},{"index":12,"start":57.5,"end":61.18,"textZh":"星期天呢 就看看书 听听音乐","pinyin":"Xīngqītiān ne, jiù kànkan shū, tīngting yīnyuè.","textKo":"일요일에는 책 좀 보고, 음악 좀 듣고.","words":[{"word":"星","start":57.5,"end":58.42},{"word":"期","start":58.42,"end":58.56},{"word":"天","start":58.56,"end":58.82},{"word":"呢","start":58.82,"end":59.06},{"word":"就","start":59.06,"end":59.5},{"word":"看看","start":59.5,"end":59.9},{"word":"书","start":59.9,"end":60.32},{"word":"听","start":60.58,"end":60.68},{"word":"听","start":60.68,"end":60.84},{"word":"音","start":60.84,"end":60.98},{"word":"乐","start":60.98,"end":61.18}]},{"index":13,"start":61.18,"end":66.02,"textZh":"非常放松 这个计划听起来确实很不错","pinyin":"Fēicháng fàngsōng. Zhège jìhuà tīng qǐlái quèshí hěn búcuò.","textKo":"아주 편하게. 이 계획 정말 괜찮게 들리네.","words":[{"word":"非常","start":61.18,"end":62.02},{"word":"放","start":62.02,"end":62.32},{"word":"松","start":62.32,"end":62.64},{"word":"这个","start":63.32,"end":63.76},{"word":"计","start":63.76,"end":63.98},{"word":"划","start":63.98,"end":64.22},{"word":"听","start":64.22,"end":64.58},{"word":"起","start":64.58,"end":64.72},{"word":"来","start":64.72,"end":64.94},{"word":"确","start":64.94,"end":65.34},{"word":"实","start":65.34,"end":65.5},{"word":"很","start":65.5,"end":65.68},{"word":"不","start":65.68,"end":65.86},{"word":"错","start":65.86,"end":66.02}]},{"index":14,"start":66.02,"end":69.12,"textZh":"很舒服 那后来呢","pinyin":"Hěn shūfu. Nà hòulái ne?","textKo":"아주 편하지. 그런데 그다음엔?","words":[{"word":"很","start":66.02,"end":66.52},{"word":"舒","start":66.52,"end":66.74},{"word":"服","start":66.74,"end":66.94},{"word":"那","start":66.94,"end":67.88},{"word":"后","start":67.88,"end":68.76},{"word":"来","start":68.76,"end":68.96},{"word":"呢","start":68.96,"end":69.12}]},{"index":15,"start":69.7,"end":75.52,"textZh":"后来 后来我朋友给我推荐了一个新的电视剧","pinyin":"Hòulái, hòulái wǒ péngyǒu gěi wǒ tuījiàn le yī gè xīn de diànshìjù.","textKo":"그다음에, 친구가 새 드라마를 추천해줬어.","words":[{"word":"后","start":69.7,"end":69.98},{"word":"来","start":69.98,"end":70.6},{"word":"后","start":71.68,"end":72.16},{"word":"来","start":72.16,"end":72.52},{"word":"我","start":72.52,"end":72.96},{"word":"朋友","start":72.96,"end":73.32},{"word":"给我","start":73.32,"end":73.6},{"word":"推","start":73.6,"end":73.86},{"word":"荐","start":73.86,"end":74.06},{"word":"了","start":74.06,"end":74.18},{"word":"一个","start":74.18,"end":74.4},{"word":"新","start":74.4,"end":74.7},{"word":"的","start":74.7,"end":74.88},{"word":"电","start":74.88,"end":75.04},{"word":"视","start":75.04,"end":75.28},{"word":"剧","start":75.28,"end":75.52}]},{"index":16,"start":75.52,"end":79.76,"textZh":"他说特别好看 星期六晚上我想","pinyin":"Tā shuō tèbié hǎokàn. Xīngqīliù wǎnshàng wǒ xiǎng,","textKo":"엄청 재밌다고 했어. 토요일 밤에 생각했지,","words":[{"word":"他","start":75.52,"end":76.22},{"word":"说","start":76.22,"end":76.4},{"word":"特","start":76.4,"end":76.68},{"word":"别","start":76.68,"end":76.96},{"word":"好","start":76.96,"end":77.22},{"word":"看","start":77.22,"end":77.5},{"word":"星","start":77.5,"end":78.34},{"word":"期","start":78.34,"end":78.48},{"word":"六","start":78.48,"end":78.64},{"word":"晚上","start":78.64,"end":78.96},{"word":"我想","start":78.96,"end":79.76}]},{"index":17,"start":79.76,"end":82.4,"textZh":"那我就看一集吧 就一集","pinyin":"nà wǒ jiù kàn yī jí ba, jiù yī jí.","textKo":"그럼 한 편만 보자, 딱 한 편만.","words":[{"word":"那","start":79.76,"end":80.4},{"word":"我就","start":80.4,"end":80.7},{"word":"看","start":80.7,"end":80.94},{"word":"一","start":80.94,"end":81.12},{"word":"集","start":81.12,"end":81.26},{"word":"吧","start":81.26,"end":81.48},{"word":"就","start":81.48,"end":82.02},{"word":"一","start":82.02,"end":82.24},{"word":"集","start":82.24,"end":82.4}]},{"index":18,"start":83.7,"end":87.34,"textZh":"我猜到结果了 你肯定不止看了一集","pinyin":"Wǒ cāi dào jiéguǒ le. Nǐ kěndìng bù zhǐ kàn le yī jí.","textKo":"결과를 맞혀볼게. 분명 한 편만 본 게 아니지?","words":[{"word":"我","start":83.7,"end":84.18},{"word":"猜","start":84.18,"end":84.44},{"word":"到","start":84.44,"end":84.58},{"word":"结","start":84.58,"end":84.72},{"word":"果","start":84.72,"end":84.9},{"word":"了","start":84.9,"end":85.06},{"word":"你","start":85.06,"end":85.9},{"word":"肯","start":85.9,"end":86.12},{"word":"定","start":86.12,"end":86.26},{"word":"不","start":86.26,"end":86.48},{"word":"止","start":86.48,"end":86.68},{"word":"看","start":86.68,"end":86.9},{"word":"了","start":86.9,"end":87.04},{"word":"一","start":87.04,"end":87.16},{"word":"集","start":87.16,"end":87.34}]},{"index":19,"start":87.88,"end":91.1,"textZh":"是啊 那个电视剧太有意思了","pinyin":"Shì a, nàge diànshìjù tài yǒu yìsi le.","textKo":"맞아, 그 드라마가 너무 재밌었어.","words":[{"word":"是啊","start":87.88,"end":88.36},{"word":"那个","start":88.36,"end":89.28},{"word":"电","start":89.28,"end":89.5},{"word":"视","start":89.5,"end":89.68},{"word":"剧","start":89.68,"end":89.88},{"word":"太","start":89.88,"end":90.18},{"word":"有","start":90.18,"end":90.52},{"word":"意思","start":90.52,"end":90.88},{"word":"了","start":90.88,"end":91.1}]},{"index":20,"start":91.1,"end":93.5,"textZh":"我看了一集 又想看一集","pinyin":"Wǒ kàn le yī jí, yòu xiǎng kàn yī jí.","textKo":"한 편 보고 나니 또 한 편 보고 싶어지더라고.","words":[{"word":"我","start":91.1,"end":91.54},{"word":"看","start":91.54,"end":91.72},{"word":"了","start":91.72,"end":91.84},{"word":"一","start":91.84,"end":92.08},{"word":"集","start":92.08,"end":92.3},{"word":"又","start":92.3,"end":92.76},{"word":"想","start":92.76,"end":92.92},{"word":"看","start":92.92,"end":93.12},{"word":"一","start":93.12,"end":93.3},{"word":"集","start":93.3,"end":93.5}]},{"index":21,"start":94.86,"end":97.54,"textZh":"然后我就看到了星期天早上","pinyin":"Ránhòu wǒ jiù kàn dào le xīngqītiān zǎoshang.","textKo":"그래서 일요일 아침까지 봤어.","words":[{"word":"然后","start":94.86,"end":95.34},{"word":"我就","start":95.34,"end":95.82},{"word":"看到","start":95.82,"end":96.14},{"word":"了","start":96.14,"end":96.32},{"word":"星","start":96.32,"end":96.46},{"word":"期","start":96.46,"end":96.62},{"word":"天","start":96.62,"end":96.8},{"word":"早","start":96.8,"end":97.04},{"word":"上","start":97.04,"end":97.54}]},{"index":22,"start":97.54,"end":102.56,"textZh":"天呐 那你星期天不就一整天都在睡觉","pinyin":"Tiān na! Nà nǐ xīngqītiān bù jiù yī zhěng tiān dōu zài shuìjiào?","textKo":"세상에! 그러면 일요일에 하루 종일 잤겠네?","words":[{"word":"天","start":97.54,"end":98.0},{"word":"呐","start":98.0,"end":98.38},{"word":"那","start":99.02,"end":99.5},{"word":"你","start":99.5,"end":99.68},{"word":"星","start":99.68,"end":99.88},{"word":"期","start":99.88,"end":100.04},{"word":"天","start":100.04,"end":100.34},{"word":"不","start":100.34,"end":100.7},{"word":"就","start":100.7,"end":100.9},{"word":"一","start":100.9,"end":101.24},{"word":"整","start":101.24,"end":101.44},{"word":"天","start":101.44,"end":101.74},{"word":"