) VALUES (
  'ja', '7WAHPmY-B70', '{"videoId":"7WAHPmY-B70","youtubeId":"7WAHPmY-B70","title":"一瞬 で 惹き つける 声 を 出す方法 | Shigemitsu Hayashi | TEDxShinshuUniversity","channel":"TEDx Talks","categoryId":"daily","difficulty":"intermediate","duration":757,"thumbnail":"https://i.ytimg.com/vi_webp/7WAHPmY-B70/maxresdefault.webp","speechRateMpm":108,"speechRateWpm":0,"addedAt":"2026-02-19","segmentCount":61,"vocabularyCount":20,"grammarPatternCount":14}'::jsonb, '{"videoId":"7WAHPmY-B70","segments":[{"index":0,"start":0.0,"end":5.18,"textJa":"字幕作成者 初音ミク 字幕作成者 初音ミク","reading":"じまくさくせいしゃ はつねみく じまくさくせいしゃ はつねみく","textKo":"자막 제작자: 하츠네 미쿠 자막 제작자: 하츠네 미쿠","words":[{"word":"字","start":0.0,"end":0.58},{"word":"幕","start":0.58,"end":1.82},{"word":"作","start":1.82,"end":1.82},{"word":"成","start":1.82,"end":1.82},{"word":"者","start":1.82,"end":1.82},{"word":"初","start":1.82,"end":1.82},{"word":"音","start":1.82,"end":1.82},{"word":"ミ","start":1.82,"end":1.82},{"word":"ク","start":1.82,"end":1.82}]},{"index":1,"start":12.88,"end":20.78,"textJa":"拍手 皆様こんにちは 林茂光と申します よろしくお願いいたします","reading":"はくしゅ みなさまこんにちは はやししげみつともうします よろしくおねがいいたします","textKo":"박수 여러분 안녕하세요. 하야시 시게미츠라고 합니다. 잘 부탁드립니다.","words":[{"word":"拍","start":12.88,"end":13.32},{"word":"手","start":13.32,"end":13.76},{"word":"皆","start":16.36,"end":16.8},{"word":"様","start":16.8,"end":16.94},{"word":"こんにちは","start":16.94,"end":17.32},{"word":"林","start":18.24,"end":18.64},{"word":"茂","start":18.64,"end":18.94},{"word":"光","start":18.94,"end":19.06},{"word":"と","start":19.06,"end":19.18},{"word":"申","start":19.18,"end":19.3},{"word":"します","start":19.3,"end":19.62},{"word":"よろしく","start":19.84,"end":20.06},{"word":"お","start":20.06,"end":20.24},{"word":"願","start":20.24,"end":20.24},{"word":"いい","start":20.24,"end":20.38},{"word":"た","start":20.38,"end":20.46},{"word":"します","start":20.46,"end":20.78}]},{"index":2,"start":22.08,"end":26.42,"textJa":"皆様は手の形で声が変わることをご存知でしょうか","reading":"みなさまはてのかたちでこえがかわることをごぞんじでしょうか","textKo":"여러분은 손 모양에 따라 목소리가 바뀐다는 것을 알