INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'ja', 'ttMyF8d-o7E', '{"videoId":"ttMyF8d-o7E","youtubeId":"ttMyF8d-o7E","title":"【初登場】自己紹介も面接も一発OK！「声」で差がつく３つの秘策（元NHK／滑舌／声量／呼吸法／アナウンサー／あなたの話が「伝わらない」のは声のせい／墨屋那津子）","channel":"NewsPicks /ニューズピックス","categoryId":"business","difficulty":"intermediate","duration":819,"thumbnail":"https://i.ytimg.com/vi_webp/ttMyF8d-o7E/maxresdefault.webp","speechRateMpm":131,"speechRateWpm":0,"addedAt":"2026-02-19","segmentCount":84,"vocabularyCount":0,"grammarPatternCount":0}'::jsonb, '{"videoId":"ttMyF8d-o7E","segments":[{"index":0,"start":0.0,"end":2.16,"textJa":"編集部の日賀太一です","reading":"へんしゅうぶのひがたいちです","textKo":"편집부의 히가 타이치입니다","words":[{"word":"編集部","start":0.0,"end":1.06},{"word":"の","start":1.06,"end":1.24},{"word":"日賀太一","start":1.24,"end":1.84},{"word":"です","start":1.84,"end":2.16}]},{"index":1,"start":4.22,"end":9.22,"textJa":"たった一つしかない魔法の型があるので一生楽になりますので","reading":"たったひとつしかないまほうのかたがあるのでいっしょうらくになりますので","textKo":"단 하나밖에 없는 마법의 형태가 있어서 평생 편해지실 겁니다","words":[{"word":"たった","start":4.22,"end":4.78},{"word":"一つ","start":4.78,"end":5.12},{"word":"しかない","start":5.12,"end":5.72},{"word":"魔法の型","start":5.72,"end":6.88},{"word":"が","start":6.88,"end":7.06},{"word":"ある","start":7.06,"end":7.18},{"word":"ので","start":7.18,"end":7.42},{"word":"一生","start":7.42,"end":8.06},{"word":"楽になります","start":8.06,"end":8.88},{"word":"ので","start":8.88,"end":9.22}]},{"index":2,"start":12.58,"end":16.62,"textJa":"ミュースピックス編集部の日賀です","reading":"みゅーすぴっくすへんしゅうぶのひがです","textKo":"뮤스픽스 편집부의 히가입니다","words":[{"word":"ミュースピックス","start":12.58,"end":15.56},{"word":"編集部","start":15.56,"end":15.92},{"word":"の","start":15.92,"end":16.06},{"word":"日賀","start":16.06,"end":16.38},{"word":"です","start":16.38,"end":16.62}]},{"index":3,"start":16.62,"end":21.04,"textJa":"初めまして今日はよろしくお願いします はい初めましてスミヤと申します","reading":"はじめましてきょうはよろしくおねがいします はいはじめましてすみやともうします","textKo":"처음 뵙겠습니다, 오늘 잘 부탁드립니다. 네, 처음 뵙겠습니다, 스미야라고 합니다","words":[{"word":"初めまして","start":16.62,"end":17.52},{"word":"今日は","start":17.52,"end":17.7},{"word":"よろしく","start":17.