INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'ja', 'g8TEUFSiRPA', '{"videoId":"g8TEUFSiRPA","youtubeId":"g8TEUFSiRPA","title":"「伝統を途絶えさせないために革新を」伝統工芸の町・京都で覆す『職人像』 新たな挑戦が生む未来とは【かんさい情報ネット ten.特集/カラフル】","channel":"YOMIURI TELECASTING CORPORATION NEWS CHANNEL","categoryId":"culture","difficulty":"intermediate","duration":809,"thumbnail":"https://i.ytimg.com/vi_webp/g8TEUFSiRPA/maxresdefault.webp","speechRateMpm":135,"speechRateWpm":0,"addedAt":"2026-02-19","segmentCount":104,"vocabularyCount":0,"grammarPatternCount":0}'::jsonb, '{"videoId":"g8TEUFSiRPA","segments":[{"index":0,"start":5.12,"end":7.62,"textJa":"響き渡る鉄を叩く音","reading":"ひびきわたるてつをたたくおと","textKo":"울려 퍼지는 쇠를 두드리는 소리","words":[{"word":"響き渡る","start":5.12,"end":5.88},{"word":"鉄","start":6.08,"end":6.74},{"word":"を","start":6.74,"end":7.04},{"word":"叩く","start":7.04,"end":7.38},{"word":"音","start":7.38,"end":7.62}]},{"index":1,"start":13.96,"end":22.86,"textJa":"暗闇に揺れる炎 千年の歴史を持つ鉄の工芸品","reading":"くらやみにゆれるほのお せんねんのれきしをもつてつのこうげいひん","textKo":"어둠 속에 흔들리는 불꽃, 천 년의 역사를 가진 철의 공예품","words":[{"word":"暗闇","start":13.96,"end":14.64},{"word":"に","start":14.64,"end":14.86},{"word":"揺れる","start":14.86,"end":15.22},{"word":"炎","start":15.22,"end":15.58},{"word":"千年","start":19.76,"end":20.46},{"word":"の","start":20.46,"end":20.64},{"word":"歴史","start":20.64,"end":20.98},{"word":"を","start":20.98,"end":21.14},{"word":"持つ","start":21.14,"end":21.46},{"word":"鉄","start":21.46,"end":21.88},{"word":"の","start":21.88,"end":22.16},{"word":"工芸品","start":22.16,"end":22.86}]},{"index":2,"start":23.9,"end":26.66,"textJa":"日本刀を生み出す刀鍛冶","reading":"にほんとうをうみだすかたなかじ","textKo":"일본도를 만들어 내는 도검 제조 장인","words":[{"word":"日本刀","start":23.9,"end":24.64},{"word":"を","start":24.64,"end":24.78},{"word":"生み出す","start":24.78,"end":25.38},{"word":"刀鍛冶","start":25.38,"end":26.66}]},{"index":3,"start":27.98,"end":32.42,"textJa":"日本刀自体が残っても刀鍛冶自体が残らないかもしれないですね","reading":"にほんとうじたいがのこってもかたなかじじたいがのこらないかもしれないですね","textKo":"일본도 자체가 남아 있어도, 도검 장인 자체가 남지 않을지도 모르겠네요","words":[{"word":"日本刀","start":27.98,"end":28