INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'ja', 'j9fJmTYdEyU', '{"videoId":"j9fJmTYdEyU","youtubeId":"j9fJmTYdEyU","title":"「プレステ5」大幅値下げの舞台裏を独自解説【経済記者インサイト】","channel":"テレ東BIZ ダイジェスト","categoryId":"news","difficulty":"intermediate","duration":524,"thumbnail":"https://i.ytimg.com/vi/j9fJmTYdEyU/maxresdefault.jpg","speechRateMpm":352,"speechRateWpm":0,"addedAt":"2026-02-19","segmentCount":142,"vocabularyCount":0,"grammarPatternCount":0}'::jsonb, '{"videoId":"j9fJmTYdEyU","segments":[{"index":0,"start":1.28,"end":6.42,"textJa":"経済記者による経済の裏側を独自に解説する経済記者インサイトです","reading":"けいざいきしゃによるけいざいのうらがわをどくじにかいせつするけいざいきしゃインサイトです","textKo":"경제 기자가 경제의 이면을 독자적으로 해설하는 경제 기자 인사이트입니다.","words":[{"word":"経済記者","reading":"けいざいきしゃ","meaning":"경제 기자"},{"word":"による","reading":"による","meaning":"~에 의한"},{"word":"裏側","reading":"うらがわ","meaning":"이면, 뒷면"},{"word":"独自に","reading":"どくじに","meaning":"독자적으로"},{"word":"解説する","reading":"かいせつする","meaning":"해설하다"},{"word":"インサイト","reading":"インサイト","meaning":"인사이트(통찰)"}]},{"index":1,"start":7.1,"end":12.18,"textJa":"今日は経済企画キャップの安倍記者とテレトービズの編集長の菅野さんとお送りします","reading":"きょうはけいざいきかくキャップのあべきしゃとテレトービズのへんしゅうちょうのすがのさんとおおくりします","textKo":"오늘은 경제기획 캡인 아베 기자와 텔레토비즈 편집장 스가노 씨와 함께 전해드립니다.","words":[{"word":"経済企画","reading":"けいざいきかく","meaning":"경제기획"},{"word":"キャップ","reading":"キャップ","meaning":"캡(부서 책임자)"},{"word":"編集長","reading":"へんしゅうちょう","meaning":"편집장"},{"word":"お送りします","reading":"おおくりします","meaning":"전해드립니다"}]},{"index":2,"start":12.18,"end":16.54,"textJa":"よろしくお願いします さて今回のテーマは何でしょうか","reading":"よろしくおねがいします さてこんかいのテーマはなんでしょうか","textKo":"잘 부탁드립니다. 자, 이번 테마는 무엇인가요?","words":[{"word":"よろしくお願いします","reading":"よろしくおねがいします","meaning":"잘 부탁드립니다"},{"word":"さて","reading":"さて","meaning":"자, 그런데"},{"word":"今回","reading":"こんかい","meaning":"이번"},{"word":"テーマ","reading":"テーマ","meaning":"테마, 주제"}]},{"index":3,"start":17.82,"end":25.54,"textJa":"昨日ですね12日発表がありましたソニーのゲーム機プレイセッション5の実質値下げのニュースです","reading":"きのうですねじゅうにちはっぴょうがありましたソニーのゲームきプレイセッション5のじっしつねさげのニュースです","textKo":"어제죠, 12일에 발표가 있었습니다. 소니 게임기 플레이스테이션5의 실질 가격 인하 뉴스입니다.","words":[{"word":"昨日","reading":"きのう","meaning":"어제"},{"word":"発表","reading":"はっぴょう","meaning":"발표"},{"word":"ゲーム機","reading":"ゲームき","meaning":"게임기"},{"word":"実質値下げ","reading":"じっしつねさげ","meaning":"실질 가격 인하"}]},{"index":4,"start":25.54,"end":28.32,"textJa":"これWBSで竹崎さん読んでいただきましたね","reading":"これWBSでたけざきさんよんでいただきましたね","textKo":"이건 WBS에서 다케자키 씨가 읽어주셨죠.","words":[{"word":"読んでいただく","reading":"よんでいただく","meaning":"읽어주시다(받는 표현)"}]},{"index":5,"start":28.32,"end":32.54,"textJa":"昨日お伝えしました 内容はニュースでもお伝えしましたけれども","reading":"きのうおつたえしました ないようはニュースでもおつたえしましたけれども","textKo":"어제 전달해드렸습니다. 내용은 뉴스에서도 전달해드렸습니다만,","words":[{"word":"お伝えしました","reading":"おつたえしました","meaning":"전달했습니다(경어)"},{"word":"内容","reading":"ないよう","meaning":"내용"}]},{"index":6,"start":32.54,"end":37.56,"textJa":"7万円以上する現行のモデルから1万8000円ほど実質値引きして","reading":"ななまんえんいじょうするげんこうのモデルからいちまんはっせんえんほどじっしつねびきして","textKo":"7만 엔 이상 하는 현행 모델에서 약 1만 8천 엔 실질 할인하여","words":[{"word":"現行","reading":"げんこう","meaning":"현행, 현재"},{"word":"実質値引き","reading":"じっしつねびき","meaning":"실질 할인"},{"word":"以上","reading":"いじょう","meaning":"이상"}]},{"index":7,"start":37.56,"end":40.06,"textJa":"税込み5万5000円で投入します","reading":"ぜいこみごまんごせんえんでとうにゅうします","textKo":"세금 포함 5만 5천 엔으로 투입합니다.","words":[{"word":"税込み","reading":"ぜいこみ","meaning":"세금 포함"},{"word":"投入します","reading":"とうにゅうします","meaning":"투입합니다, 출시합니다"}]},{"index":8,"start":40.78,"end":43.56,"textJa":"これライバルの任天堂スイッチ2がですね","reading":"これライバルのにんてんどうスイッチ2がですね","textKo":"이게 라이벌인 닌텐도 스위치2가 있는데요,","words":[{"word":"ライバル","reading":"ライバル","meaning":"라이벌"},{"word":"任天堂","reading":"にんてんどう","meaning":"닌텐도"}]},{"index":9,"start":43.56,"end":46.02,"textJa":"4万9880円","reading":"よんまんきゅうせんはっぴゃくはちじゅうえん","textKo":"4만 9,880엔","words":[{"word":"4万9880円","reading":"よんまんきゅうせんはっぴゃくはちじゅうえん","meaning":"49,880엔"}]},{"index":10,"start":46.02,"end":50.74,"textJa":"およそ5万円でやってますからそこの価格帯に合わせてきたという狙いですね","reading":"およそごまんえんでやってますからそこのかかくたいにあわせてきたというねらいですね","textKo":"약 5만 엔에 판매되고 있으니, 그 가격대에 맞춰온 것이 노림수네요.","words":[{"word":"価格帯","reading":"かかくたい","meaning":"가격대"},{"word":"合わせてきた","reading":"あわせてきた","meaning":"맞춰왔다"},{"word":"狙い","reading":"ねらい","meaning":"노림수, 목표"}]},{"index":11,"start":50.74,"end":54.6,"textJa":"もう一つ中身が変わってます これこの日本語専用モデルと","reading":"もうひとつなかみがかわってます これこのにほんごせんようモデルと","textKo":"또 한 가지 내용이 바뀌었습니다. 이 일본어 전용 모델과","words":[{"word":"中身","reading":"なかみ","meaning":"내용, 내부"},{"word":"日本語専用","reading":"にほんごせんよう","meaning":"일본어 전용"}]},{"index":12,"start":54.6,"end":58.46,"textJa":"日本での利用を想定したモデルにチェンジします","reading":"にほんでのりようをそうていしたモデルにチェンジします","textKo":"일본에서의 이용을 상정한 모델로 변경합니다.","words":[{"word":"利用","reading":"りよう","meaning":"이용"},{"word":"想定した","reading":"そうていした","meaning":"상정한, 가정한"},{"word":"チェンジ","reading":"チェンジ","meaning":"변경"}]},{"index":13,"start":58.46,"end":60.6,"textJa":"これ狙いは後でお伝えします","reading":"これねらいはあとでおつたえします","textKo":"이 노림수는 나중에 전달해드리겠습니다.","words":[{"word":"後で","reading":"あとで","meaning":"나중에"}]},{"index":14,"start":61.54,"end":65.62,"textJa":"11月21日から発売という内容になっていますが","reading":"じゅういちがつにじゅういちにちからはつばいというないようになっていますが","textKo":"11월 21일부터 발매라는 내용이 되어 있습니다만,","words":[{"word":"発売","reading":"はつばい","meaning":"발매, 출시"}]},{"index":15,"start":66.18,"end":68.56,"textJa":"菅野さんってプレスでしたか?","reading":"すがのさんってプレスでしたか","textKo":"스가노 씨는 플스 쓰셨나요?","words":[{"word":"プレス","reading":"プレス","meaning":"플스(플레이스테이션 약칭)"}]},{"index":16,"start":69.6,"end":73.0,"textJa":"そうですね 自分で買ったのは3ですけど","reading":"そうですね じぶんでかったのは3ですけど","textKo":"그렇네요. 직접 산 건 3이지만,","words":[{"word":"自分で","reading":"じぶんで","meaning":"직접, 스스로"}]},{"index":17,"start":73.54,"end":78.8,"textJa":"当時で確かギガス容量別で5万円と6万円だったんですよ","reading":"とうじでたしかギガスようりょうべつでごまんえんとろくまんえんだったんですよ","textKo":"당시에 아마 용량별로 5만 엔과 6만 엔이었거든요.","words":[{"word":"当時","reading":"とうじ","meaning":"당시"},{"word":"確か","reading":"たしか","meaning":"분명히, 아마"},{"word":"容量別","reading":"ようりょうべつ","meaning":"용량별"}]},{"index":18,"start":78.8,"end":83.34,"textJa":"大体およそ すでに当時でも結構高いなと思ってやってましたけど","reading":"だいたいおよそ すでにとうじでもけっこうたかいなとおもってやってましたけど","textKo":"대체로 이미 당시에도 꽤 비싸다고 생각하며 했었지만,","words":[{"word":"大体","reading":"だいたい","meaning":"대체로"},{"word":"結構","reading":"けっこう","meaning":"꽤, 상당히"}]},{"index":19,"start":83.34,"end":85.8,"textJa":"でも高性能なやっぱりゲームマシンですよね","reading":"でもこうせいのうなやっぱりゲームマシンですよね","textKo":"하지만 역시 고성능 게임머신이죠.","words":[{"word":"高性能","reading":"こうせいのう","meaning":"고성능"},{"word":"やっぱり","reading":"やっぱり","meaning":"역시"}]},{"index":20,"start":85.8,"end":91.18,"textJa":"竹崎さんとかいかがですか? 私は1992年生まれで生まれてすぐに発売されて","reading":"たけざきさんとかいかがですか わたしは1992ねんうまれでうまれてすぐにはつばいされて","textKo":"다케자키 씨는 어떠신가요? 저는 1992년생인데 태어나자마자 발매되어서","words":[{"word":"いかがですか","reading":"いかがですか","meaning":"어떠신가요(경어)"},{"word":"生まれてすぐ","reading":"うまれてすぐ","meaning":"태어나자마자"}]},{"index":21,"start":91.52,"end":94.38,"textJa":"小学生の時にプレイしてた記憶はあるんですけど","reading":"しょうがくせいのときにプレイしてたきおくはあるんですけど","textKo":"초등학생 때 플레이했던 기억은 있는데요,","words":[{"word":"小学生","reading":"しょうがくせい","meaning":"초등학생"},{"word":"記憶","reading":"きおく","meaning":"기억"}]},{"index":22,"start":94.92,"end":97.04,"textJa":"今はこう… いや違います違います","reading":"いまはこう… いやちがいますちがいます","textKo":"지금은 이렇게… 아, 아니에요, 아니에요.","words":[{"word":"違います","reading":"ちがいます","meaning":"아닙니다, 다릅니다"}]},{"index":23,"start":97.04,"end":99.66,"textJa":"でも自分で買うことはあまりなかったので","reading":"でもじぶんでかうことはあまりなかったので","textKo":"하지만 직접 살 일은 별로 없었으므로","words":[{"word":"あまりなかった","reading":"あまりなかった","meaning":"별로 없었다"}]},{"index":24,"start":99.66,"end":101.92,"textJa":"金額意識したことなかったんですが","reading":"きんがくいしきしたことなかったんですが","textKo":"금액을 의식한 적이 없었는데요,","words":[{"word":"金額","reading":"きんがく","meaning":"금액"},{"word":"意識する","reading":"いしきする","meaning":"의식하다"}]},{"index":25,"start":102.28,"end":105.92,"textJa":"当時5万円親は頑張ってくれたなというふうに思いますね","reading":"とうじごまんえんおやはがんばってくれたなというふうにおもいますね","textKo":"당시 5만 엔, 부모님이 고생해 주셨구나 하고 생각하네요.","words":[{"word":"頑張ってくれた","reading":"がんばってくれた","meaning":"노력해 주셨다"},{"word":"というふうに","reading":"というふうに","meaning":"~라고, ~처럼"}]},{"index":26,"start":105.92,"end":108.28,"textJa":"結構高いなという印象です","reading":"けっこうたかいなという印象です","textKo":"꽤 비싸다는 인상입니다.","words":[{"word":"印象","reading":"いんしょう","meani