INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'ja', 'lYbMTvAejOw', '{"videoId":"lYbMTvAejOw","youtubeId":"lYbMTvAejOw","title":"【「春節」異変】中国人観光客が激減、日本の観光地は…","channel":"日テレNEWS","categoryId":"news","difficulty":"intermediate","duration":419,"thumbnail":"https://i.ytimg.com/vi/lYbMTvAejOw/maxresdefault.jpg","speechRateMpm":184,"speechRateWpm":0,"addedAt":"2026-02-19","segmentCount":71,"vocabularyCount":0,"grammarPatternCount":0}'::jsonb, '{"videoId":"lYbMTvAejOw","segments":[{"index":0,"start":4.78,"end":8.44,"textJa":"おとといから始まった中国の旧正月","reading":"おとといからはじまったちゅうごくのきゅうしょうがつ","textKo":"그저께부터 시작된 중국의 구정(음력 설)","words":[{"word":"おととい","reading":"おととい","meaning":"그저께"},{"word":"から","reading":"から","meaning":"부터"},{"word":"始まった","reading":"はじまった","meaning":"시작된"},{"word":"中国","reading":"ちゅうごく","meaning":"중국"},{"word":"の","reading":"の","meaning":"의"},{"word":"旧正月","reading":"きゅうしょうがつ","meaning":"구정, 음력 설"}]},{"index":1,"start":8.94,"end":11.54,"textJa":"春節に伴う大型連休","reading":"しゅんせつにともなうおおがたれんきゅう","textKo":"춘절에 따른 대형 연휴","words":[{"word":"春節","reading":"しゅんせつ","meaning":"춘절, 중국 설"},{"word":"に伴う","reading":"にともなう","meaning":"에 따른"},{"word":"大型","reading":"おおがた","meaning":"대형"},{"word":"連休","reading":"れんきゅう","meaning":"연휴"}]},{"index":2,"start":15.06,"end":18.16,"textJa":"今年は史上最長の旧連休","reading":"ことしはしじょうさいちょうのきゅうれんきゅう","textKo":"올해는 역사상 가장 긴 구정 연휴","words":[{"word":"今年","reading":"ことし","meaning":"올해"},{"word":"は","reading":"は","meaning":"은/는"},{"word":"史上","reading":"しじょう","meaning":"역사상"},{"word":"最長","reading":"さいちょう","meaning":"최장"},{"word":"の","reading":"の","meaning":"의"},{"word":"旧連休","reading":"きゅうれんきゅう","meaning":"구정 연휴"}]},{"index":3,"start":19.04,"end":24.1,"textJa":"過去最多延べ95億人の大移動が見込まれています","reading":"かこさいたのべきゅうじゅうごおくにんのだいいどうがみこまれています","textKo":"과거 최다인 연 95억 명의 대이동이 예상되고 있습니다","words":[{"word":"過去最多","reading":"かこさいた","meaning":"과거 최다"},{"word":"延べ","reading":"のべ","meaning":"연 (延), 누계"},{"word":"95億人","reading":"きゅうじゅうごおくにん","meaning":"95억 명"},{"word":"の","reading":"の","meaning":"의"},{"word":"大移動","reading":"だいいどう","meaning":"대이동"},{"word":"が","reading":"が","meaning":"이/가"},{"word":"見込まれています","reading":"みこまれています","meaning":"예상되고 있습니다"}]},{"index":4,"start":25.64,"end":28.52,"textJa":"連休の始まった上海の駅構内ですが","reading":"れんきゅうのはじまったしゃんはいのえきこうないですが","textKo":"연휴가 시작된 상하이역 구내입니다만","words":[{"word":"連休","reading":"れんきゅう","meaning":"연휴"},{"word":"の","reading":"の","meaning":"의"},{"word":"始まった","reading":"はじまった","meaning":"시작된"},{"word":"上海","reading":"しゃんはい","meaning":"상하이"},{"word":"の","reading":"の","meaning":"의"},{"word":"駅構内","reading":"えきこうない","meaning":"역 구내"},{"word":"ですが","reading":"ですが","meaning":"입니다만"}]},{"index":5,"start":28.52,"end":32.06,"textJa":"前に進むのも難しいほど大変混雑しています","reading":"まえにすすむのもむずかしいほどたいへんこんざつしています","textKo":"앞으로 나아가기도 어려울 정도로 매우 혼잡합니다","words":[{"word":"前に進む","reading":"まえにすすむ","meaning":"앞으로 나아가다"},{"word":"のも","reading":"のも","meaning":"것도"},{"word":"難しい","reading":"むずかしい","meaning":"어렵다"},{"word":"ほど","reading":"ほど","meaning":"정도"},{"word":"大変","reading":"たいへん","meaning":"매우"},{"word":"混雑しています","reading":"こんざつしています","meaning":"혼잡합니다"}]},{"index":6,"start":35.6,"end":38.8,"textJa":"ただ日中関係の緊張が続く中","reading":"ただにっちゅうかんけいのきんちょうがつづくなか","textKo":"그런데 일중 관계의 긴장이 이어지는 가운데","words":[{"word":"ただ","reading":"ただ","meaning":"그런데, 다만"},{"word":"日中関係","reading":"にっちゅうかんけい","meaning":"일중 관계"},{"word":"の","reading":"の","meaning":"의"},{"word":"緊張","reading":"きんちょう","meaning":"긴장"},{"word":"が続く","reading":"がつづく","meaning":"가 이어지다"},{"word":"中","reading":"なか","meaning":"가운데"}]},{"index":7,"start":39.94,"end":44.22,"textJa":"中国政府は日本への渡航自粛を呼びかけていて","reading":"ちゅうごくせいふはにほんへのとこうじしゅくをよびかけていて","textKo":"중국 정부는 일본으로의 여행 자제를 촉구하고 있어","words":[{"word":"中国政府","reading":"ちゅうごくせいふ","meaning":"중국 정부"},{"word":"は","reading":"は","meaning":"은/는"},{"word":"日本","reading":"にほん","meaning":"일본"},{"word":"への","reading":"への","meaning":"으로의"},{"word":"渡航","reading":"とこう","meaning":"도항, 여행"},{"word":"自粛","reading":"じしゅく","meaning":"자제, 자숙"},{"word":"を呼びかけていて","reading":"をよびかけていて","meaning":"를 촉구하고 있어"}]},{"index":8,"start":46.92,"end":51.0,"textJa":"日中関係があまり良くないから安全を心配しています","reading":"にっちゅうかんけいがあまりよくないからあんぜんをしんぱいしています","textKo":"일중 관계가 그다지 좋지 않아서 안전을 걱정하고 있습니다","words":[{"word":"日中関係","reading":"にっちゅうかんけい","meaning":"일중 관계"},{"word":"が","reading":"が","meaning":"이/가"},{"word":"あまり","reading":"あまり","meaning":"그다지"},{"word":"良くない","reading":"よくない","meaning":"좋지 않다"},{"word":"から","reading":"から","meaning":"때문에"},{"word":"安全","reading":"あんぜん","meaning":"안전"},{"word":"を心配しています","reading":"をしんぱいしています","meaning":"을 걱정하고 있습니다"}]},{"index":9,"start":52.68,"end":56.74,"textJa":"進めていないのもあってできるだけ国家の呼びかけに応えないと","reading":"すすめていないのもあってできるだけこっかのよびかけにこたえないと","textKo":"진전이 없는 것도 있어서 되도록 국가의 호소에 응하지 않으면","words":[{"word":"進めていない","reading":"すすめていない","meaning":"진전이 없다"},{"word":"のもあって","reading":"のもあって","meaning":"것도 있어서"},{"word":"できるだけ","reading":"できるだけ","meaning":"되도록, 최대한"},{"word":"国家","reading":"こっか","meaning":"국가"},{"word":"の呼びかけ","reading":"のよびかけ","meaning":"의 호소"},{"word":"に応えないと","reading":"にこたえないと","meaning":"에 응하지 않으면"}]},{"index":10,"start":60.36,"end":64.16,"textJa":"東京浅草のこちらの抹茶専門店では","reading":"とうきょうあさくさのこちらのまっちゃせんもんてんでは","textKo":"도쿄 아사쿠사에 있는 이 말차 전문점에서는","words":[{"word":"東京浅草","reading":"とうきょうあさくさ","meaning":"도쿄 아사쿠사"},{"word":"の","reading":"の","meaning":"의"},{"word":"こちら","reading":"こちら","meaning":"이쪽, 여기"},{"word":"の","reading":"の","meaning":"의"},{"word":"抹茶専門店","reading":"まっちゃせんもんてん","meaning":"말차 전문점"},{"word":"では","reading":"では","meaning":"에서는"}]},{"index":11,"start":68.54,"end":72.06,"textJa":"今日の抹茶作り体験の予約はゼロ","reading":"きょうのまっちゃづくりたいけんのよやくはぜろ","textKo":"오늘 말차 만들기 체험 예약은 제로","words":[{"word":"今日","reading":"きょう","meaning":"오늘"},{"word":"の","reading":"の","meaning":"의"},{"word":"抹茶作り体験","reading":"まっちゃづくりたいけん","meaning":"말차 만들기 체험"},{"word":"の","reading":"の","meaning":"의"},{"word":"予約","reading":"よやく","meaning":"예약"},{"word":"は","reading":"は","meaning":"은/는"},{"word":"ゼロ","reading":"ぜろ","meaning":"제로, 0"}]},{"index":12,"start":73.12,"end":76.22,"textJa":"予約が入っているのは珍しいことですか","reading":"よやくがはいっているのはめずらしいことですか","textKo":"예약이 들어와 있는 것은 드문 일인가요?","words":[{"word":"予約","reading":"よやく","meaning":"예약"},{"word":"が入っている","reading":"がはいっている","meaning":"이 들어와 있다"},{"word":"のは","reading":"のは","meaning":"것은"},{"word":"珍しい","reading":"めずらしい","meaning":"드문, 희귀한"},{"word":"こと","reading":"こと","meaning":"일, 것"},{"word":"ですか","reading":"ですか","meaning":"입니까?"}]},{"index":13,"start":77.08,"end":81.02,"textJa":"例年ですとこの旧正月春節の時期に関しては","reading":"れいねんですとこのきゅうしょうがつしゅんせつのじきにかんしては","textKo":"평년 같으면 이 구정 춘절 시기에 관해서는","words":[{"word":"例年","reading":"れいねん","meaning":"평년, 보통 해"},{"word":"ですと","reading":"ですと","meaning":"라면 (정중체)"},{"word":"この","reading":"この","meaning":"이"},{"word":"旧正月","reading":"きゅうしょうがつ","meaning":"구정"},{"word":"春節","reading":"しゅんせつ","meaning":"춘절"},{"word":"の時期","reading":"のじき","meaning":"의 시기"},{"word":"に関しては","reading":"にかんしては","meaning":"에 관해서는"}]},{"index":14,"start":81.02,"end":83.74,"textJa":"中国の団体のお客様でしたり","reading":"ちゅうごくのだんたいのおきゃくさまでしたり","textKo":"중국 단체 고객님이시거나","words":[{"word":"中国","reading":"ちゅうごく","meaning":"중국"},{"word":"の","reading":"の","meaning":"의"},{"word":"団体","reading":"だんたい","meaning":"단체"},{"word":"の","reading":"の","meaning":"의"},{"word":"お客様","reading":"おきゃくさま","meaning":"고객님 (경어)"},{"word":"でしたり","reading":"でしたり","meaning":"이시거나"}]},{"index":15,"start":83.74,"end":88.32,"textJa":"またご家族でなどのお客様が多くいらっしゃるんですけれども","reading":"またごかぞくでなどのおきゃくさまがおおくいらっしゃるんですけれども","textKo":"또한 가족 단위 등의 고객님이 많이 오시는데요","words":[{"word":"また","reading":"また","meaning":"또한"},{"word":"ご家族","reading":"ごかぞく","meaning":"가족 (경어)"},{"word":"で","reading":"で","meaning":"으로, 단위"},{"word":"などの","reading":"などの","meaning":"등의"},{"word":"お客様","reading":"おきゃくさま","meaning":"고객님 (경어)"},{"word":"が多く","reading":"がおおく","meaning":"이 많이"},{"word":"いらっしゃる","reading":"いらっしゃる","meaning":"오시다 (경어)"},{"word":"んですけれども","reading":"んですけれども","meaning":"데요 (설명·완화)"}]},{"index":16,"start":88.32,"end":91.9,"textJa":"2月に入ってからは一見も入っていないのが現状です","reading":"にがつにはいってからはいちけんもはいっていないのがげんじょうです","textKo":"2월에 들어서부터는 단 한 건도 들어오지 않은 것이 현 상황입니다","words":[{"word":"2月に入ってから","reading":"にがつにはいってから","meaning":"2월에 들어서부터"},{"word":"は","reading":"は","meaning":"는"},{"word":"一見も","reading":"いちけんも","meaning":"한 건도"},{"word":"入っていない","reading":"はいっていない","meaning":"들어오지 않다"},{"word":"のが","reading":"のが","meaning":"것이"},{"word":"現状","reading":"げんじょう","meaning":"현 상황"},{"word":"です","reading":"です","meaning":"입니다"}]},{"index":17,"start":92.88,"end":96.08,"textJa":"店内のゆっくりと楽しめるというお声を","reading":"てんないのゆっくりとたのしめるというおこえを","textKo":"가게 안에서 천천히 즐길 수 있다는 목소리를","words":[{"word":"店内","reading":"てんない","meaning":"가게 안"},{"word":"の","reading":"の","meaning":"에서의"},{"word":"ゆっくりと","reading":"ゆっくりと","meaning":"천천히"},{"word":"楽しめる","reading":"たのしめる","meaning":"즐길 수 있다"},{"word":"という","reading":"という","meaning":"라는"},{"word":"お声","reading":"おこえ","meaning":"목소리 (경어)"},{"word":"を","reading":"を","meaning":"을/를"}]},{"index":18,"start":96.08,"end":99.04,"textJa":"かなり日本のお客様から多くいただけるので","reading":"かなりにほんのおきゃくさまからおおくいただけるので","textKo":"상당히 일본 고객님들로부터 많이 받을 수 있기 때문에","words":[{"word":"かなり","reading":"かなり","meaning":"상당히"},{"word":"日本","reading":"にほん","meaning":"일본"},{"word":"の","reading":"の","meaning":"의"},{"word":"お客様","reading":"おきゃくさま","meaning":"고객님 (경어)"},{"word":"から","reading":"から","meaning":"로부터"},{"word":"多く","reading":"おおく","meaning":"많이"},{"word":"いただける","reading":"いただける","meaning":"받을 수 있다 (겸양)"},{"word":"ので","reading":"ので","meaning":"때문에"}]},{"index":19,"start":99.04,"end":102.16,"textJa":"私たちとしては来ていただけるお客様に","reading":"わたしたちとしてはきていただけるおきゃくさまに","textKo":"저희로서는 와 주시는 고객님께","words":[{"word":"私たち","reading":"わたしたち","meaning":"저희"},{"word":"としては","reading":"としては","meaning":"로서는"},{"word":"来ていただける","reading":"きていただける","meaning":"와 주실 수 있는 (겸양)"},{"word":"お客様","reading":"おきゃくさま","meaning":"고객님 (경어)"},{"word":"に","reading":"に","meaning":"께, 에게"}]},{"index":20,"start":102.16,"end":108.22,"textJa":"より楽しい時間を あとは美味しい商品をゆっくりと楽しめる時間を","reading":"よりたのしいじかんを あとはおいしいしょうひんをゆっくりとたのしめるじかんを","textKo":"더욱