INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'ja', 'r8bMLcCxxAA', '{"videoId":"r8bMLcCxxAA","youtubeId":"r8bMLcCxxAA","title":"Inside Japan’s Chicano Subculture | NYT","channel":"The New York Times","categoryId":"culture","difficulty":"intermediate","duration":406,"thumbnail":"https://i.ytimg.com/vi_webp/r8bMLcCxxAA/maxresdefault.webp","speechRateMpm":152,"speechRateWpm":0,"addedAt":"2026-02-19","segmentCount":56,"vocabularyCount":0,"grammarPatternCount":0}'::jsonb, '{"videoId":"r8bMLcCxxAA","segments":[{"index":0,"start":0.0,"end":4.9,"textJa":"BGM","reading":"","textKo":"(배경음악)","words":[]},{"index":1,"start":12.34,"end":43.56,"textJa":"BGM","reading":"","textKo":"(배경음악)","words":[]},{"index":2,"start":43.56,"end":46.56,"textJa":"まずは、ローライダーの場所にある","reading":"まずは、ローライダーのばしょにある","textKo":"우선, 로우라이더가 있는 장소에는","words":[{"word":"まずは","reading":"まずは","meaning":"우선은"},{"word":"ローライダー","reading":"ローライダー","meaning":"로우라이더"},{"word":"の","reading":"の","meaning":"~의"},{"word":"場所","reading":"ばしょ","meaning":"장소"},{"word":"に","reading":"に","meaning":"~에"},{"word":"ある","reading":"ある","meaning":"있다"}]},{"index":3,"start":50.72,"end":55.04,"textJa":"ローライダーはチカノコミュニティの中でのイコンとして","reading":"ローライダーはチカノコミュニティのなかでのイコンとして","textKo":"로우라이더는 치카노 커뮤니티 안에서의 아이콘으로서","words":[{"word":"ローライダー","reading":"ローライダー","meaning":"로우라이더"},{"word":"は","reading":"は","meaning":"~은/는 (주제)"},{"word":"チカノ","reading":"チカノ","meaning":"치카노 (멕시코계 미국인)"},{"word":"コミュニティ","reading":"コミュニティ","meaning":"커뮤니티"},{"word":"の中で","reading":"のなかで","meaning":"~안에서"},{"word":"の","reading":"の","meaning":"~의"},{"word":"イコン","reading":"イコン","meaning":"아이콘"},{"word":"として","reading":"として","meaning":"~으로서"}]},{"index":4,"start":55.04,"end":57.58,"textJa":"1940年代の中での作品を作り始めました","reading":"1940ねんだいのなかでのさくひんをつくりはじめました","textKo":"1940년대 안에서 작품을 만들기 시작했습니다","words":[{"word":"1940年代","reading":"1940ねんだい","meaning":"1940년대"},{"word":"の中で","reading":"のなかで","meaning":"~안에서"},{"word":"の","reading":"の","meaning":"~의"},{"word":"作品","reading":"さくひん","meaning":"작품"},{"word":"を","reading":"を","meaning":"~을/를 (목적격)"},{"word":"作り始めました","reading":"つくりはじめました","meaning":"만들기 시작했습니다"}]},{"index":5,"start":57.58,"end":60.22,"textJa":"戦い、継続、美容を表現するために","reading":"たたかい、けいぞく、びようをひょうげんするために","textKo":"투쟁, 지속, 아름다움을 표현하기 위해","words":[{"word":"戦い","reading":"たたかい","meaning":"투쟁, 싸움"},{"word":"継続","reading":"けいぞく","meaning":"지속, 계속"},{"word":"美容","reading":"びよう","meaning":"미용, 아름다움"},{"word":"を","reading":"を","meaning":"~을/를 (목적격)"},{"word":"表現する","reading":"ひょうげんする","meaning":"표현하다"},{"word":"ために","reading":"ために","meaning":"~하기 위해"}]},{"index":6,"start":61.06,"end":69.82,"textJa":"このカードがここに来ているのが興味がある","reading":"このカードがここにきているのがきょうみがある","textKo":"이 차가 여기에 와 있다는 것이 흥미롭다","words":[{"word":"この","reading":"この","meaning":"이"},{"word":"カード","reading":"カード","meaning":"카드 (여기서는 ''차''를 의미)"},{"word":"が","reading":"が","meaning":"~이/가 (주어)"},{"word":"ここに","reading":"ここに","meaning":"여기에"},{"word":"来ている","reading":"きている","meaning":"와 있다"},{"word":"のが","reading":"のが","meaning":"~것이"},{"word":"興味がある","reading":"きょうみがある","meaning":"흥미가 있다"}]},{"index":7,"start":69.82,"end":72.34,"textJa":"それが、ジュニチ。日本のローライダーの場所によって","reading":"それが、ジュニチ。にほんのローライダーのばしょによって","textKo":"그것이 준이치. 일본의 로우라이더 장소에 의해","words":[{"word":"それが","reading":"それが","meaning":"그것이"},{"word":"ジュニチ","reading":"ジュニチ","meaning":"준이치 (인명)"},{"word":"日本の","reading":"にほんの","meaning":"일본의"},{"word":"ローライダー","reading":"ローライダー","meaning":"로우라이더"},{"word":"の","reading":"の","meaning":"~의"},{"word":"場所","reading":"ばしょ","meaning":"장소"},{"word":"によって","reading":"によって","meaning":"~에 의해"}]},{"index":8,"start":72.34,"end":76.6,"textJa":"日本のローライダーの場所によって 一番古いカードのカードを建てた","reading":"にほんのローライダーのばしょによって いちばんふるいカードのカードをたてた","textKo":"일본의 로우라이더 장소에서 가장 오래된 차를 세웠다","words":[{"word":"日本の","reading":"にほんの","meaning":"일본의"},{"word":"ローライダー","reading":"ローライダー","meaning":"로우라이더"},{"word":"場所","reading":"ばしょ","meaning":"장소"},{"word":"によって","reading":"によって","meaning":"~에 의해"},{"word":"一番古い","reading":"いちばんふるい","meaning":"가장 오래된"},{"word":"カード","