INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'ja', 'iFzqCIEsTsA', '{"videoId":"iFzqCIEsTsA","youtubeId":"iFzqCIEsTsA","title":"匿名さんの声の具現化: エディ 宇賀田 at TEDxTokyo","channel":"TEDx Talks","categoryId":"culture","difficulty":"intermediate","duration":348,"thumbnail":"https://i.ytimg.com/vi/iFzqCIEsTsA/maxresdefault.jpg","speechRateMpm":308,"speechRateWpm":0,"addedAt":"2026-02-19","segmentCount":78,"vocabularyCount":0,"grammarPatternCount":0}'::jsonb, '{"videoId":"iFzqCIEsTsA","segments":[{"index":0,"start":3.38,"end":18.32,"textJa":"作詞・作曲・編曲 初音ミク 皆さんこんにちは","reading":"さくし・さっきょく・へんきょく はつねミク みなさんこんにちは","textKo":"작사·작곡·편곡 하츠네 미쿠. 여러분 안녕하세요.","words":[{"word":"作詞","reading":"さくし","meaning":"작사"},{"word":"作曲","reading":"さっきょく","meaning":"작곡"},{"word":"編曲","reading":"へんきょく","meaning":"편곡"},{"word":"初音ミク","reading":"はつねミク","meaning":"하츠네 미쿠 (버추얼 가수)"},{"word":"皆さん","reading":"みなさん","meaning":"여러분"}]},{"index":1,"start":18.96,"end":23.0,"textJa":"今日は特命産の声の具現化についてお話ししたいと思います","reading":"きょうはとくめいさんのこえのぐげんかについておはなししたいとおもいます","textKo":"오늘은 익명씨의 목소리의 구현화에 대해 이야기하고 싶습니다.","words":[{"word":"今日は","reading":"きょうは","meaning":"오늘은"},{"word":"特命産","reading":"とくめいさん","meaning":"익명씨 (화자가 사용하는 특수 표현)"},{"word":"声","reading":"こえ","meaning":"목소리"},{"word":"具現化","reading":"ぐげんか","meaning":"구현화"},{"word":"お話しする","reading":"おはなしする","meaning":"이야기하다 (겸양어)"}]},{"index":2,"start":23.44,"end":28.46,"textJa":"ここに立っている私 私自身も普段はネットの妖精さんです","reading":"ここにたっているわたし わたしじしんもふだんはネットのようせいさんです","textKo":"여기 서 있는 저 자신도 평소에는 인터넷의 요정입니다.","words":[{"word":"立っている","reading":"たっている","meaning":"서 있는"},{"word":"私自身","reading":"わたしじしん","meaning":"저 자신"},{"word":"普段","reading":"ふだん","meaning":"평소"},{"word":"ネット","reading":"ネット","meaning":"인터넷"},{"word":"妖精","reading":"ようせい","meaning":"요정 (익명 인터넷 유저를 가리킴)"}]},{"index":3,"start":29.44,"end":31.48,"textJa":"そしてちょっとこういう見た感じ","reading":"そしてちょっとこういうみたかんじ","textKo":"그리고 좀 이런 외모 느낌","words":[{"word":"そして","reading":"そして","meaning":"그리고"},{"word":"ちょっと","reading":"ちょっと","meaning":"좀"},{"word":"こういう","reading":"こういう","meaning":"이런"},{"word":"見た感じ","reading":"みたかんじ","meaning":"보이는 느낌, 외모"}]},{"index":4,"start":31.48,"end":34.72,"textJa":"うさんくさい感じで ちょっと今日は登壇してみました","reading":"うさんくさいかんじで ちょっときょうはとうだんしてみました","textKo":"수상한 느낌으로 오늘은 잠깐 등단해 보았습니다.","words":[{"word":"うさんくさい","reading":"うさんくさい","meaning":"수상한, 의심스러운"},{"word":"感じ","reading":"かんじ","meaning":"느낌"},{"word":"登壇する","reading":"とうだんする","meaning":"등단하다, 무대에 오르다"}]},{"index":5,"start":35.6,"end":39.88,"textJa":"スピーカーの紹介でも エディ・ウガタという名前で紹介されていますが","reading":"スピーカーのしょうかいでも エディ・ウガタというなまえでしょうかいされていますが","textKo":"스피커 소개에서도 에디 우가타라는 이름으로 소개되고 있습니다만,","words":[{"word":"スピーカー","reading":"スピーカー","meaning":"스피커, 발표자"},{"word":"紹介","reading":"しょうかい","meaning":"소개"},{"word":"名前","reading":"なまえ","meaning":"이름"},{"word":"紹介される","reading":"しょうかいされる","meaning":"소개되다 (수동형)"}]},{"index":6,"start":39.88,"end":42.06,"textJa":"Googleで検索していただいても","reading":"グーグルでけんさくしていただいても","textKo":"Google에서 검색해 주셔도","words":[{"word":"検索する","reading":"けんさくする","meaning":"검색하다"},{"word":"していただいても","reading":"していただいても","meaning":"해 주셔도 (겸양 표현)"}]},{"index":7,"start":42.06,"end":45.92,"textJa":"私の名前でヒットするものというのはあまりないです","reading":"わたしのなまえでヒットするものというのはあまりないです","textKo":"제 이름으로 히트하는 것은 별로 없습니다.","words":[{"word":"ヒットする","reading":"ヒットする","meaning":"히트하다, 검색에 걸리다"},{"word":"あまりない","reading":"あまりない","meaning":"별로 없다"}]},{"index":8,"start":46.96,"end":49.86,"textJa":"でもこれが他の名前で検索すると","reading":"でもこれがほかのなまえでけんさくすると","textKo":"하지만 이것이 다른 이름으로 검색하면","words":[{"word":"でも","reading":"でも","meaning":"하지만"},{"word":"他の","reading":"ほかの","meaning":"다른"},{"word":"検索する","reading":"けんさくする","meaning":"검색하다"}]},{"index":9,"start":49.86,"end":52.78,"textJa":"実は私の顔写真というのがコラージュされたり","reading":"じつはわたしのかおしゃしんというのがコラージュされたり","textKo":"사실 제 얼굴 사진이 콜라주되거나","words":[{"word":"実は","reading":"じつは","meaning":"사실은"},{"word":"顔写真","reading":"かおしゃしん","meaning":"얼굴 사진"},{"word":"コラージュされる","reading":"コラージュされる","meaning":"콜라주되다"}]},{"index":10,"start":52.78,"end":56.84,"textJa":"おもちゃにされたりして ネット中にばらまかれていると","reading":"おもちゃにされたりして ネットじゅうにばらまかれていると","textKo":"장난감 취급을 당하거나 해서 인터넷 곳곳에 뿌려져 있다고","words":[{"word":"おもちゃにされる","reading":"おもちゃにされる","meaning":"장난감 취급당하다"},{"word":"ネット中","reading":"ネットじゅう","meaning":"인터넷 전체, 곳곳"},{"word":"ばらまかれる","reading":"ばらまかれる","meaning":"뿌려지다, 퍼지다"}]},{"index":11,"start":57.44,"end":59.72,"textJa":"そういうような世界に","reading":"そういうようなせかいに","textKo":"그런 세계에","words":[{"word":"そういうような","reading":"そういうような","meaning":"그런"},{"word":"世界","reading":"せかい","meaning":"세계"}]},{"index":12,"start":59.72,"end":63.12,"textJa":"世界というかインターネットのお話をさせていただきたいと思います","reading":"せかいというかインターネットのおはなしをさせていただきたいとおもいます","textKo":"세계라고 할까요, 인터넷에 대한 이야기를 하고 싶습니다.","words":[{"word":"インターネット","reading":"インターネット","meaning":"인터넷"},{"word":"お話をさせていただく","reading":"おはなしをさせていただく","meaning":"이야기를 하다 (최고 겸양 표현)"}]},{"index":13,"start":63.8,"end":68.5,"textJa":"インターネット上で Twitterや掲示板、SNSを通じて","reading":"インターネットじょうで ツイッターやけいじばん、エスエヌエスをつうじて","textKo":"인터넷상에서 트위터나 게시판, SNS를 통해","words":[{"word":"インターネット上","reading":"インターネットじょう","meaning":"인터넷상"},{"word":"掲示板","reading":"けいじばん","meaning":"게시판"},{"word":"SNS","reading":"エスエヌエス","meaning":"SNS (소셜 네트워크 서비스)"},{"word":"通じて","reading":"つうじて","meaning":"통해서"}]},{"index":14,"start":68.5,"end":71.58,"textJa":"特に日本の匿名コミュニティの中では","reading":"とくににほんのとくめいコミュニティのなかでは","textKo":"특히 일본의 익명 커뮤니티 안에서는","words":[{"word":"特に","reading":"とくに","meaning":"특히"},{"word":"匿名","reading":"とくめい","meaning":"익명"},{"word":"コミュニティ","reading":"コミュニティ","meaning":"커뮤니티"}]},{"index":15,"start":71.58,"end":75.58,"textJa":"非常に面白いコンテンツが日々紹介されています","reading":"ひじょうにおもしろいコンテンツがひびしょうかいされています","textKo":"매우 재미있는 콘텐츠가 날마다 소개되고 있습니다.","words":[{"word":"非常に","reading":"ひじょうに","meaning":"매우, 굉장히"},{"word":"面白い","reading":"おもしろい","meaning":"재미있는"},{"word":"コンテンツ","reading":"コンテンツ","meaning":"콘텐츠"},{"word":"日々","reading":"ひび","meaning":"날마다, 매일"}]},{"index":16,"start":76.08,"end":79.54,"textJa":"ここに見ていただいたら分かるものなどもそうなんですけれども","reading":"ここにみていただいたらわかるものなどもそうなんですけれども","textKo":"여기서 봐 주시면 알 수 있는 것들도 그렇습니다만,","words":[{"word":"見ていただく","reading":"みていただく","meaning":"봐 주다 (겸양 표현)"},{"word":"分かる","reading":"わかる","meaning":"알다, 이해하다"},{"word":"けれども","reading":"けれども","meaning":"~하지만, ~이긴 한데"}]},{"index":17,"start":80.4,"end":86.18,"textJa":"匿名であるがゆえにですね 非常に自由活発な発想で","reading":"とくめいであるがゆえにですね ひじょうにじゆうかっぱつなはっそうで","textKo":"익명이기 때문에 매우 자유롭고 활발한 발상으로","words":[{"word":"であるがゆえに","reading":"であるがゆえに","meaning":"~이기 때문에 (문어체·강조)"},{"word":"自由活発","reading":"じゆうかっぱつ","meaning":"자유롭고 활발한"},{"word":"発想","reading":"はっそう","meaning":"발상, 아이디어"}]},{"index":18,"start":86.68,"end":90.94,"textJa":"その商品の商品というかアイデアやコンテンツのデザインができる","reading":"そのしょうひんのしょうひんというかアイデアやコンテンツのデザインができる","textKo":"그 상품, 상품이라기보다 아이디어나 콘텐츠의 디자인을 할 수 있다","words":[{"word":"商品","reading":"しょうひん","meaning":"상품"},{"word":"アイデア","reading":"アイデア","meaning":"아이디어"},{"word":"デザイン","reading":"デザイン","meaning":"디자인"}]},{"index":19,"start":90.94,"end":93.48,"textJa":"そういうことがありますので","reading":"そういうことがありますので","textKo":"그런 것들이 있기 때문에","words":[{"word":"そういうこと","reading":"そういうこと","meaning":"그런 것"},{"word":"ありますので","reading":"ありますので","meaning":"있기 때문에"}]},{"index":20,"start":93.48,"end":99.36,"textJa":"これは割と日本独特のコミュニティなのかなというふうに考えたりします","reading":"これはわりとにほんどくとくのコミュニティなのかなというふうにかんがえたりします","textKo":"이것은 꽤 일본 독특한 커뮤니티가 아닐까 하고 생각하기도 합니다.","words":[{"word":"割と","reading":"わりと","meaning":"꽤, 상당히"},{"word":"独特","reading":"どくとく","meaning":"독특한"},{"word":"というふうに","reading":"というふうに","meaning":"~라고, ~이런 식으로"},{"word":"考えたりする","reading":"かんがえたりする","meaning":"생각하기도 하다"}]},{"index":21,"start":99.9,"end":105.48,"textJa":"その匿名コミュニティの中でこうやっていろいろなものが日々作られていくのですが","reading":"そのとくめいコミュニティのなかでこうやっていろいろなものがひびつくられていくのですが","textKo":"그 익명 커뮤니티 안에서 이렇게 여러 가지 것들이 날마다 만들어져 가고 있습니다만,","words":[{"word":"こうやって","reading":"こうやって","meaning":"이렇게 해서"},{"word":"いろいろな","reading":"いろいろな","meaning":"여러 가지"},{"word":"作られていく","reading":"つくられていく","meaning":"만들어져 가다"}]},{"index":22,"start":106.94,"end":112.28,"textJa":"これは匿名コミュニティというのは ギブアンドテイクの精神というのが非常に強くてですね","reading":"これはとくめいコミュニティというのは ギブアンドテイクのせいしんというのがひじょうにつよくてですね","textKo":"익명 커뮤니티라는 것은 기브 앤 테이크의 정신이 매우 강한데요,","words":[{"word":"ギブアンドテイク","reading":"ギブアンドテイク","meaning":"기브 앤 테이크 (주고받기)"},{"word":"精神","reading":"せいしん","meaning":"정신"},{"word":"強い","reading":"つよい","meaning":"강하다"}]},{"index":23,"start":112.28,"end":117.16,"textJa":"いわゆるハイコンテクストなカルチャーとも言うべきですけれども","reading":"いわゆるハイコンテクストなカルチャーともいうべきですけれども","textKo":"이른바 하이 컨텍스트 문화라고도 할 수 있겠지만,","words":[{"word":"いわゆる","reading":"いわゆる","meaning":"이른바, 소위"},{"word":"ハイコンテクスト","reading":"ハイコンテクスト","meaning":"하이 컨텍스트 (고맥락 문화)"},{"word":"カルチャー","reading":"カルチャー","meaning":"문화"},{"word":"言うべき","reading":"いうべき","meaning":"라고 해야 할"}]},{"index":24,"start":121.44,"end":126.7,"textJa":"そこへ外からですね 企業がやってきたり外からアーティストがやってきて","reading":"そこへそとからですね きぎょうがやってきたりそとからアーティストがやってきて","textKo":"거기에 외부에서 기업이 찾아오거나 외부에서 아티스트가 찾아와서","words":[{"word":"外から","reading":"そとから","meaning":"외부에서"},{"word":"企業","reading":"きぎょう","meaning":"기업"},{"word":"アーティスト","reading":"アーティスト","meaning":"아티스트"},{"word":"やってくる","reading":"やってくる","meaning":"찾아오다"}]},{"index":25,"start":126.7,"end":129.1,"textJa":"勝手に商標登録をしてしまったり","reading":"かってにしょうひょうとうろくをしてしまったり","textKo":"멋대로 상표 등록을 해 버리거나","words":[{"word":"勝手に","reading":"かってに","meaning":"멋대로, 마음대로"},{"word":"商標登録","reading":"しょうひょうとうろく","meaning":"상표 등록"},{"word":"してしまう","reading":"してしまう","meaning":"해 버리다 (완료·후회 뉘앙스)"}]},{"index":26,"start":129.1,"end":131.36,"textJa":"勝手に自分の作品だといって","reading":"かってにじぶんのさくひんだといって","textKo":"멋대로 자신의 작품이라고 하면서","words":[{"word":"自分の","reading":"じぶんの","meaning":"자신의"},{"word":"作品","reading":"さくひん","meaning":"작품"}]},{"index":27,"start":131.36,"end":134.02,"textJa":"匿名さんの声を圧殺してですね","reading":"とくめいさんのこえをあっさつしてですね","textKo":"익명씨의 목소리를 억압하면서요,","words":[{"word":"圧殺する","reading":"あっさつする","meaning":"억압하다, 묵살하다"}]},{"index":28,"start":134.62,"end":140.76,"textJa":"自分のものにしてしまう そういったことでネットが炎上してしまうなんてことがたびたびあってですね","reading":"じぶんのものにしてしまう そういったことでネットがえんじょうしてしまうなんてことがたびたびあってですね","textKo":"자신의 것으로 만들어 버린다. 그런 일로 인터넷이 불타오르는 일이 종종 있었습니다.","words":[{"word":"自分のものにする","reading":"じぶんのものにする","meaning":"자신의 것으로 삼다"},{"word":"炎上する","reading":"えんじょうしてしまう","meaning":"인터넷에서 불타오르다, 집중 비판받다"},{"word":"たびたび","reading":"たびたび","meaning":"종종, 자주"}]},{"index":29,"start":141.26,"end":143.32,"textJa":"私なんかもそれを見ておりますと","reading":"わたしなんかもそれをみておりますと","textKo":"저 같은 사람도 그것을 보고 있으면","words":[{"word":"私なんか","reading":"わたしなんか","meaning":"저 같은 사람 (겸손 표현)"},{"word":"見ております","reading":"みております","meaning":"보고 있습니다 (겸양어)"}]},{"index":30,"start":143.72,"end":147.12,"textJa":"これリスクマネジメントどのようにみんなやってるんだと","reading":"これリスクマネジメントどのようにみんなやってるんだと","textKo":"이 리스크 매니지먼트를 다들 어떻게 하고 있는 건지","words":[{"word":"リスクマネジメント","reading":"リスクマネジメント","meaning":"리스크 매니지먼트, 위험 관리"},{"word":"どのように","reading":"どのように","meaning":"어떻게"},{"word":"みんな","reading":"みんな","meaning":"모두"}]},{"index":31,"start":147.12,"end":149.96,"textJa":"一部上場企業ですらそういったことを起こして","reading":"いちぶじょうじょうきぎょうですらそういったことをおこして","textKo":"일부 상장 기업조차 그런 일을 일으켜서","words":[{"word":"一部上場企業","reading":"いちぶじょうじょうきぎょう","meaning":"1부 상장 기업 (도쿄 증권거래소 1부)"},{"word":"ですら","reading":"ですら","meaning":"조차도"},{"word":"起こす","reading":"おこす","meaning":"일으키다"}]},{"index":32,"start":150.64,"end":153.94,"textJa":"ネットが大炎上してしまう じゃあこれをですね","reading":"ネットがだいえんじょうしてしまう じゃあこれをですね","textKo":"인터넷이 크게 불타오르게 된다. 그러면 이것을","words":[{"word":"大炎上","reading":"だいえんじょう","meaning":"대규모 인터넷 비난 폭주"},{"word":"じゃあ","reading":"じゃあ","meaning":"그러면, 자"}]},{"index":33,"start":153.94,"end":157.52,"textJa":"どうやってこういう形で具現化していくのか","reading":"どうやってこういうかたちでぐげんかしていくのか","textKo":"어떻게 이런 형태로 구현해 나갈 것인가","words":[{"word":"どうやって","reading":"どうやって","meaning":"어떻게 해서"},{"word":"形","reading":"かたち","meaning":"형태, 모습"},{"word":"具現化していく","reading":"ぐげんかしていく","meaning":"구현해 나가다"}]},{"index":34,"start":158.16,"end":162.42,"textJa":"それは匿名さんの作ったですね","reading":"それはとくめいさんのつくったですね","textKo":"그것은 익명씨가 만든","words":[{"word":"それは","reading":"それは","meaning":"그것은"},{"word":"作った","reading":"つくった","meaning":"만든"}]},{"index":35,"start":163.6,"end":167.