INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'ja', '0gvHwBXuwQ0', '{"videoId":"0gvHwBXuwQ0","youtubeId":"0gvHwBXuwQ0","title":"杉田智和、相棒・釘宮理恵に“照れ感謝”！？長年タッグが明かす“息を合わせすぎない”芝居論　『ナイト・オブ・ザ・セブン・キングダムズ』吹替声優・直撃インタビュー","channel":"oricon -Japanese entertainment news","categoryId":"anime","difficulty":"intermediate","duration":794,"thumbnail":"https://i.ytimg.com/vi_webp/0gvHwBXuwQ0/maxresdefault.webp","speechRateMpm":196,"speechRateWpm":0,"addedAt":"2026-02-19","segmentCount":118,"vocabularyCount":20,"grammarPatternCount":11}'::jsonb, '{"videoId":"0gvHwBXuwQ0","segments":[{"index":0,"start":0.0,"end":2.98,"textJa":"オリコンニュースをご覧の皆さん、こんにちは!","reading":"おりこんにゅーすをごらんのみなさん、こんにちは！","textKo":"오리콘 뉴스를 시청해주시는 여러분, 안녕하세요!","words":[{"word":"オリコンニュース","start":0.0,"end":0.0},{"word":"ご覧の","start":0.0,"end":0.0},{"word":"皆さん","start":0.0,"end":0.0},{"word":"こんにちは","start":0.0,"end":0.0}],"listenDifficulty":5},{"index":1,"start":3.84,"end":5.92,"textJa":"ダンク役の杉田智和です","reading":"だんくやくのすぎたともかずです","textKo":"덩크 역의 스기타 토모카즈입니다.","words":[{"word":"ダンク役","start":3.84,"end":3.84},{"word":"杉田智和","start":3.84,"end":3.84},{"word":"です","start":3.84,"end":3.84}],"listenDifficulty":4},{"index":2,"start":6.9,"end":10.68,"textJa":"エッグ役の久木宮理恵です ありがとうございます","reading":"えっぐやくのひきみやりえです ありがとうございます","textKo":"에그 역의 히키미야 리에입니다. 감사합니다.","words":[{"word":"エッグ役","start":6.9,"end":6.9},{"word":"久木宮理恵","start":6.9,"end":6.9},{"word":"ありがとうございます","start":6.9,"end":6.9}],"listenDifficulty":4},{"index":3,"start":13.2,"end":19.34,"textJa":"面白いなと思って 原音からして久木宮さんと近いと思うんですよね","reading":"おもしろいなとおもって げんおんからしてひきみやさんとちかいとおもうんですよね","textKo":"재미있다고 생각해서요. 원음부터가 히키미야 씨와 가깝다고 생각하거든요.","words":[{"word":"面白い","start":13.2,"end":13.2},{"word":"原音","start":13.2,"end":13.2},{"word":"近い","start":13.2,"end":13.2}],"listenDifficulty":4},{"index":4,"start":19.34,"end":22.18,"textJa":"なんか似てるというか 今、現代社会","reading":"なんかにてるというか いま、げんだいしゃかい","textKo":"뭔가 닮았다고 할까요. 지금 현대 사회에서","words":[{"word":"似てる","start":19.34,"end":19.34},{"word":"現代社会","start":19.34,"end":19.34}],"listenDifficulty":4},{"index":5,"start":22.18,"end":25.4,"textJa":"どうしたんですか? 現代社会の闇みたいな","reading":"どうしたんですか？ げんだいしゃかいのやみみたいな","textKo":"어떻게 된 건가요? 현대 사회의 어두운 면 같은","words":[{"word":"どうしたんですか","start":22.18,"end":22.18},{"word":"闇","start":22.18,"end":22.18},{"word":"みたいな","start":22.18,"end":22.18}],"listenDifficulty":5},{"index":6,"start":25.9,"end":35.5,"textJa":"読みちゃみたい ダンクのキャラクターの立ち位置と同じく","reading":"よみちゃみたい だんくのきゃらくたーのたちいちとおなじく","textKo":"읽은 것 같은 느낌이에요. 덩크 캐릭터의 포지션과 마찬가지로","words":[{"word":"読みちゃみたい","start":25.9,"end":25.9},{"word":"キャラクター","start":25.9,"end":25.9},{"word":"立ち位置","start":25.9,"end":25.9}],"listenDifficulty":3},{"index":7,"start":36.12,"end":41.62,"textJa":"作品から大きく浮いているような印象になればよいなと捉えたので","reading":"さくひんからおおきくういているようなinshょうになればよいなととらえたので","textKo":"작품에서 크게 튀는 듯한 인상이 되면 좋겠다고 파악했기 때문에","words":[{"word":"作品","start":36.12,"end":36.12},{"word":"浮いている","start":36.12,"end":36.12},{"word":"印象","start":36.12,"end":36.12},{"word":"捉えた","start":36.12,"end":36.12}],"listenDifficulty":4},{"index":8,"start":42.38,"end":45.28,"textJa":"ゲームオブスローンズの本編を調べたり見たり","reading":"げーむおぶすろーんずのほんへんをしらべたりみたり","textKo":"왕좌의 게임 본편을 조사하거나 보거나","words":[{"word":"ゲームオブスローンズ","start":42.38,"end":42.38},{"word":"本編","start":42.38,"end":42.38},{"word":"調べたり","start":42.38,"end":42.38}],"listenDifficulty":5},{"index":9,"start":45.66,"end":51.32,"textJa":"ということをあえてしていません 最初は視聴者がどうしてこの人なんだろう","reading":"ということをあえてしていません さいしょはしちょうしゃがどうしてこのひとなんだろう","textKo":"그런 것을 일부러 하지 않고 있습니다. 처음에는 시청자들이 왜 이 사람인가 하고","words":[{"word":"あえて","start":45.66,"end":45.66},{"word":"視聴者","start":45.66,"end":45.66}],"listenDifficulty":3},{"index":10,"start":51.84,"end":55.92,"textJa":"どうしてこんな奴が吹き替えてるんだろう 印象としてあった方がむしろいいかな","reading":"どうしてこんなやつがふきかえてるんだろう いんしょうとしてあったほうがむしろいいかな","textKo":"왜 이런 녀석이 더빙을 하고 있나 하는 인상이 있는 편이 오히려 좋지 않을까","words":[{"word":"奴","start":51.84,"end":51.84},{"word":"吹き替える","start":51.84,"end":51.84},{"word":"むしろ","start":51.84,"end":51.84}],"listenDifficulty":4},{"index":11,"start":56.78,"end":62.28,"textJa":"ダンクもまた なぜこんな奴が騎士なんか志すんだって言われてるところから始まるので","reading":"だんくもまた なぜこんなやつがきしなんかこころざすんだっていわれてるところからはじまるので","textKo":"덩크도 또한 왜 이런 녀석이 기사 따위를 지망하냐는 말을 듣는 데서 시작하기 때문에","words":[{"word":"騎士","start":56.78,"end":56.78},{"word":"志す","start":56.78,"end":56.78},{"word":"始まる","start":56.78,"end":56.78}],"listenDifficulty":4},{"index":12,"start":62.74,"end":65.44,"textJa":"最終的に騎士という概念が","reading":"さいしゅうてきにきしというがいねんが","textKo":"최종적으로 기사라는 개념이","words":[{"word":"最終的に","start":62.74,"end":62.74},{"word":"概念","start":62.74,"end":62.74}],"listenDifficulty":3},{"index":13,"start":66.08,"end":69.74,"textJa":"自分から名乗るものではなく 道として残るものだっていうのが","reading":"じぶんからなのるものではなく みちとしてのこるものだっていうのが","textKo":"스스로 자칭하는 것이 아니라 길로서 남는 것이라는 게","words":[{"word":"名乗る","start":66.08,"end":66.08},{"word":"道","start":66.08,"end":66.08},{"word":"残る","start":66.08,"end":66.08}],"listenDifficulty":4},{"index":14,"start":70.14,"end":72.46,"textJa":"最終的にはそこに到達するのかなって","reading":"さいしゅうてきにはそこにとうたつするのかなって","textKo":"최종적으로는 거기에 도달하는 건가 하고","words":[{"word":"到達する","start":70.14,"end":70.14}],"listenDifficulty":3},{"index":15,"start":72.46,"end":76.02,"textJa":"自分で予測を立てて 作品への姿勢をまず定めました","reading":"じぶんでよそくをたてて さくひんへのしせいをまずさだめました","textKo":"스스로 예측을 세우고 작품에 대한 자세를 먼저 정했습니다.","words":[{"word":"予測を立てる","start":72.46,"end":72.46},{"word":"姿勢","start":72.46,"end":72.46},{"word":"定める","start":72.46,"end":72.46}],"listenDifficulty":5},{"index":16,"start":78.3,"end":83.66,"textJa":"はいあの私は作品のタイトルを聞く前に","reading":"はいあのわたしはさくひんのたいとるをきくまえに","textKo":"네, 저는 작품 제목을 듣기 전에","words":[{"word":"あの","start":78.3,"end":78.3},{"word":"タイトル","start":78.3,"end":78.3},{"word":"聞く前に","start":78.3,"end":78.3}],"listenDifficulty":2},{"index":17,"start":83.66,"end":91.06,"textJa":"先に杉田さんが主演で同じ旅をする役ですっていう風に役所を伺って","reading":"さきにすぎたさんがしゅえんでおなじたびをするやくですっていうふうにやくしょをうかがって","textKo":"먼저 스기타 씨가 주연으로 같은 여행을 하는 역이라는 식으로 배역을 전달받고","words":[{"word":"主演","start":83.66,"end":83.66},{"word":"旅","start":83.66,"end":83.66},{"word":"役所を伺う","start":83.66,"end":83.66}],"listenDifficulty":1},{"index":18,"start":91.8,"end":94.6,"textJa":"作品のことはちょっとまだわからないけど","reading":"さくひんのことはちょっとまだわからないけど","textKo":"작품에 대해서는 아직 잘 모르지만","words":[{"word":"ちょっと","start":91.8,"end":91.8},{"word":"わからない","start":91.8,"end":91.8}],"listenDifficulty":3},{"index":19,"start":94.6,"end":102.73,"textJa":"楽しんだなぁと思って 後にこのタイトルがゲームオブスローズのシリーズに連なる作品だというのを知って","reading":"たのしんだなぁとおもって のちにこのたいとるがげーむおぶすろーずのしりーずにつらなるさくひんだというのをしって","textKo":"즐거웠다고 생각했는데, 나중에 이 제목이 왕좌의 게임 시리즈와 연결되는 작품이라는 걸 알고","words":[{"word":"楽しんだ","start":94.6,"end":94.6},{"word":"後に","start":94.6,"end":94.6},{"word":"連なる","start":94.6,"end":94.6},{"word":"シリーズ","start":94.6,"end":94.6}],"listenDifficulty":1},{"index":20,"start":103.35,"end":107.35,"textJa":"今までちょっと見たかったけどなかなか機会がなくて","reading":"いままでちょっとみたかったけどなかなかきかいがなくて","textKo":"지금까지 조금 보고 싶었는데 좀처럼 기회가 없어서","words":[{"word":"今まで","start":103.35,"end":103.35},{"word":"なかなか","start":103.35,"end":103.35},{"word":"機会","start":103.35,"end":103.35}],"listenDifficulty":2},{"index":21,"start":107.35,"end":110.39,"textJa":"見てなかった作品だなぁというのを思って","reading":"みてなかったさくひんだなぁというのをおもって","textKo":"보지 않았던 작품이었구나 하고 생각하면서","words":[{"word":"見てなかった","start":107.35,"end":107.35}],"listenDifficulty":1},{"index":22,"start":110.39,"end":112.61,"textJa":"一から見ています","reading":"いちからみています","textKo":"처음부터 보고 있습니다.","words":[{"word":"一から","start":110.39,"end":110.39},{"word":"見ています","start":110.39,"end":110.39}],"listenDifficulty":3},{"index":23,"start":117.63,"end":120.75,"textJa":"はい そんなに差はないと思いますけど","reading":"はい そんなにさはないとおもいますけど","textKo":"네. 그렇게 차이는 없다고 생각합니다만","words":[{"word":"差","start":117.63,"end":117.63},{"word":"そんなに","start":117.63,"end":117.63}],"listenDifficulty":3},{"index":24,"start":120.75,"end":124.29,"textJa":"はい 選ばれる理由みたいなものっていうのがあって","reading":"はい えらばれるりゆうみたいなものっていうのがあって","textKo":"네. 선택받는 이유 같은 것이 있어서","words":[{"word":"選ばれる","start":120.75,"end":120.75},{"word":"理由","start":120.75,"end":120.75}],"listenDifficulty":2},{"index":25,"start":124.29,"end":128.21,"textJa