INSERT INTO public.video_artifacts (
  language, video_id, meta, segments, vocabulary, grammar, connected_speech, structure
) VALUES (
  'ja', 'iXcQhnYR2kA', '{"videoId":"iXcQhnYR2kA","youtubeId":"iXcQhnYR2kA","title":"幸せを探す旅 | 喜多 桜子 | TEDxNagoyaU","channel":"TEDx Talks","categoryId":"travel","difficulty":"intermediate","duration":858,"thumbnail":"https://i.ytimg.com/vi_webp/iXcQhnYR2kA/maxresdefault.webp","speechRateMpm":174,"speechRateWpm":0,"addedAt":"2026-02-19","segmentCount":105,"vocabularyCount":20,"grammarPatternCount":12}'::jsonb, '{"videoId":"iXcQhnYR2kA","segments":[{"index":0,"start":16.08,"end":19.68,"textJa":"もし今日が人生最後の日だとしたら","reading":"もしきょうがじんせいさいごのひだとしたら","textKo":"만약 오늘이 인생 마지막 날이라면","words":[],"listenDifficulty":1},{"index":1,"start":20.98,"end":25.1,"textJa":"あなたはどんなことを後悔しますか","reading":"あなたはどんなことをこうかいしますか","textKo":"당신은 어떤 것을 후회하겠습니까","words":[],"listenDifficulty":2},{"index":2,"start":27.7,"end":30.68,"textJa":"ああ もっと毎日飲み歩いとけよかったな","reading":"ああ もっとまいにちのみあるいとけよかったな","textKo":"아, 더 매일 술집 돌아다닐걸 그랬다","words":[],"listenDifficulty":1},{"index":3,"start":33.08,"end":35.54,"textJa":"ああ もっと可愛いねんちゃんと","reading":"ああ もっとかわいいねんちゃんと","textKo":"아, 더 귀여운 애들이랑 제대로","words":[],"listenDifficulty":1},{"index":4,"start":36.02,"end":38.18,"textJa":"いっぱい遊んどくべきだったな","reading":"いっぱいあそんどくべきだったな","textKo":"많이 놀아둬야 했는데","words":[],"listenDifficulty":1},{"index":5,"start":41.28,"end":44.1,"textJa":"そんなことを一番に後悔する人は","reading":"そんなことをいちばんにこうかいするひとは","textKo":"그런 것을 가장 먼저 후회하는 사람은","words":[],"listenDifficulty":1},{"index":6,"start":45.04,"end":50.94,"textJa":"まずいないと思います じゃあ 何を思うのか","reading":"まずいないとおもいます じゃあ なにをおもうのか","textKo":"거의 없다고 생각합니다. 그럼 무엇을 생각하는 걸까요","words":[],"listenDifficulty":2},{"index":7,"start":53.76,"end":61.98,"textJa":"死を間近にしたとき 大半の人はこんな後悔の言葉を口にするそうです","reading":"しをまぢかにしたとき たいはんのひとはこんなこうかいのことばをくちにするそうです","textKo":"죽음을 눈앞에 두었을 때, 대부분의 사람은 이런 후회의 말을 한다고 합니다","words":[],"listenDifficulty":1},{"index":8,"start":63.24,"end":70.02,"textJa":"もっと家族と一緒に過ごせよかった もっと自分の夢を追えよかった","reading":"もっとかぞくといっしょにすごせよかった もっとじぶんのゆめをおえよかった","textKo":"더 가족과 함께 시간을 보낼걸. 더 내 꿈을 쫓을걸","words":[],"listenDifficulty":1},{"index":9,"start":72.78,"end":76.92,"textJa":"自分に正直に生きればよかった","reading":"じぶんにしょうじきにいきればよかった","textKo":"자신에게 솔직하게 살았더라면 좋았을 텐데","words":[],"listenDifficulty":1},{"index":10,"start":78.0,"end":82.8,"textJa":"私はこれが本当なんかどうかを確認したくて","reading":"わたしはこれがほんとうなんかどうかをかくにんしたくて","textKo":"저는 이것이 정말인지 아닌지를 확인하고 싶어서","words":[],"listenDifficulty":1},{"index":11,"start":83.5,"end":87.96,"textJa":"かつて看護師をしていたことがあります","reading":"かつてかんごしをしていたことがあります","textKo":"예전에 간호사를 한 적이 있습니다","words":[],"listenDifficulty":1},{"index":12,"start":89.4,"end":95.7,"textJa":"ある日 末期がんのおじいちゃんを担当することになりました","reading":"あるひ まっきがんのおじいちゃんをたんとうすることになりました","textKo":"어느 날, 말기 암 할아버지를 담당하게 되었습니다","words":[],"listenDifficulty":2},{"index":13,"start":97.34,"end":103.24,"textJa":"余命宣告を受けたおじいちゃんは毎日毎日泣いていました","reading":"よめいせんこくをうけたおじいちゃんはまいにちまいにちないていました","textKo":"시한부 선고를 받은 할아버지는 매일 매일 울고 있었습니다","words":[],"listenDifficulty":2},{"index":14,"start":104.72,"end":110.0,"textJa":"なんで泣いてるんですかと聞くと","reading":"なんでないてるんですかときくと","textKo":"왜 울고 계시냐고 물으면","words":[],"listenDifficulty":1},{"index":15,"start":111.14,"end":116.36,"textJa":"おじいちゃんはこうおっしゃっていました","reading":"おじいちゃんはこうおっしゃっていました","textKo":"할아버지는 이렇게 말씀하셨습니다","words":[],"listenDifficulty":3},{"index":16,"start":118.54,"end":122.64,"textJa":"わしはなあ ずっとお金のために働いてきた","reading":"わしはなあ ずっとおかねのためにはたらいてきた","textKo":"나는 말이야, 줄곧 돈을 위해 일해왔어","words":[],"listenDifficulty":2},{"index":17,"start":124.46,"end":129.94,"textJa":"でも もっと家族と一緒に過ごせばよかったなあ","reading":"でも もっとかぞくといっしょにすごせばよかったなあ","textKo":"하지만 더 가족과 함께 시간을 보냈으면 좋았을 텐데","words":[],"listenDifficulty":1},{"index":18,"start":131.46,"end":137.08,"textJa":"お金よりも幸せのために生きればよかったなあ","reading":"おかねよりもしあわせのためにいきればよかったなあ","textKo":"돈보다 행복을 위해 살았으면 좋았을 텐데","words":[],"listenDifficulty":2},{"index":19,"start":138.32,"end":143.1,"textJa":"そうおっしゃいながら 涙を流されていました","reading":"そうおっしゃいながら なみだをながされていました","textKo":"그렇게 말씀하시면서 눈물을 흘리고 계셨습니다","words":[],"listenDifficulty":3},{"index":20,"start":145.56,"end":152.52,"textJa":"そのおじいちゃんは最後にこんな言葉を私に残してくれました","reading":"そのおじいちゃんはさいごにこんなことばをわたしにのこしてくれました","textKo":"그 할아버지는 마지막에 이런 말을 저에게 남겨주셨습니다","words":[],"listenDifficulty":1},{"index":21,"start":154.5,"end":159.58,"textJa":"後悔のない人生を歩みなさい","reading":"こうかいのないじんせいをあゆみなさい","textKo":"후회 없는 인생을 걸어가거라","words":[],"listenDifficulty":1},{"index":22,"start":162.58,"end":170.44,"textJa":"私はこの言葉がずっと心に残り 本当にこの後悔のない人生を歩んでいる人がいるのだろうかと思い始めました","reading":"わたしはこのことばがずっとこころにのこり ほんとうにこのこうかいのないじんせいをあゆんでいるひとがいるのだろうかとおもいはじめました","textKo":"저는 이 말이 계속 마음에 남아, 정말로 이 후회 없는 인생을 살고 있는 사람이 있는 걸까 생각하기 시작했습니다","words":[],"listenDifficulty":1},{"index":23,"start":172.32,"end":180.94,"textJa":"幸せって一体なんだろう そう思い始めてから 私は幸せを調べ始めました","reading":"しあわせっていったいなんだろう そうおもいはじめてから わたしはしあわせをしらべはじめました","textKo":"행복이란 대체 무엇일까. 그렇게 생각하기 시작하고 나서, 저는 행복을 연구하기 시작했습니다","words":[],"listenDifficulty":1},{"index":24,"start":182.22,"end":186.98,"textJa":"そんなとき あるテレビ番組を見ました","reading":"そんなとき あるてれびばんぐみをみました","textKo":"그럴 때 어떤 TV 프로그램을 봤습니다","words":[],"listenDifficulty":1},{"index":25,"start":188.3,"end":196.4,"textJa":"世界の幸福度ランキングという番組で 日本は何位だったと思いますか","reading":"せかいのこうふくどらんきんぐというばんぐみで にほんはなんいだったとおもいますか","textKo":"세계 행복도 랭킹이라는 프로그램인데, 일본은 몇 위였다고 생각하십니까","words":[],"listenDifficulty":2},{"index":26,"start":198.5,"end":204.34,"textJa":"5位? 10位? 30位?","reading":"ごい？ じゅうい？ さんじゅうい？","textKo":"5위? 10위? 30위?","words":[],"listenDifficulty":1},{"index":27,"start":205.48,"end":209.98,"textJa":"まさかの90位","reading":"まさかのきゅうじゅうい","textKo":"놀랍게도 90위","words":[],"listenDifficulty":1},{"index":28,"start":213.14,"end":219.6,"textJa":"世界第三位の経済大国でありながら 幸福度は90位","reading":"せかいだいさんいのけいざいたいこくでありながら こうふくどはきゅうじゅうい","textKo":"세계 3위의 경제 대국이면서 행복도는 90위","words":[],"listenDifficulty":2},{"index":29,"start":221.0,"end":224.66,"textJa":"これはおかしいと思いました","reading":"これはおかしいとおもいました","textKo":"이건 이상하다고 생각했습니다","words":[],"listenDifficulty":1},{"index":30,"start":226.5,"end":232.86,"textJa":"お金があれば 幸せになれるんじゃないの?","reading":"おかねがあれば しあわせになれるんじゃないの","textKo":"돈이 있으면 행복해질 수 있는 거 아닌가요?","words":[],"listenDifficulty":2},{"index":31,"start":234.32,"end":241.32,"textJa":"なんで日本人は幸せじゃないんだろうって すごく疑問に思いました","reading":"なんでにほんじんはしあわせじゃないんだろうって すごくぎもんにおもいました","textKo":"왜 일본인은 행복하지 않을까 하고 굉장히 의문스러웠습니다","words":[],"listenDifficulty":1},{"index":32,"start":244.28,"end":250.62,"textJa":"それを確かめるために私は世界を旅して幸せを探すことにしました","reading":"それをたしかめるためにわたしはせかいをたびしてしあわせをさがすことにしました","textKo":"그것을 확인하기 위해 저는 세계를 여행하며 행복을 찾기로 했습니다","words":[],"listenDifficulty":1},{"index":33,"start":252.88,"end":260.98,"textJa":"最初の旅先はカンボジア そこでとても貧しい村 ルサイ村を訪れました","reading":"さいしょのたびさきはかんぼじあ そこでとてもまずしいむら るさいむらをおとずれました","textKo":"첫 번째 여행지는 캄보디아. 거기서 아주 가난한 마을, 루사이 마을을 방문했습니다","words":[],"listenDifficulty":2},{"index":34,"start":262.08,"end":267.86,"textJa":"1000人ほどの村で 電気もガスも水道もありません","reading":"せんにんほどのむらで でんきもがすもすいどうもありません","textKo":"약 1000명의 마을로, 전기도 가스도 수도도 없습니다","words":[],"listenDifficulty":1},{"index":35,"start":269.38,"end":274.26,"textJa":"でも子供達の目はキラキラと輝いていました","reading":"でもこどもたちのめはきらきらとかがやいていました","textKo":"하지만 아이들의 눈은 반짝반짝 빛나고 있었습니다","words":[],"listenDifficulty":2},{"index":36,"start":276.74,"end":280.88,"textJa":"みんな最高の笑顔で笑っていました","reading":"みんなさいこうのえがおでわらっていました","textKo":"모두 최고의 미소로 웃고 있었습니다","words":[],"listenDifficulty":1},{"index":37,"start":283.18,"end":287.94,"textJa":"なんで電気もガスも水道もないのに","reading":"なんででんきもがすもすいどうもないのに","textKo":"왜 전기도 가스도 수도도 없는데","words":[],"listenDifficulty":1},{"index":38,"start":289.58,"end":293.42,"textJa":"この子達はこんなに笑顔なんだろうと思いました","reading":"このこたちはこんなにえがおなんだろうとおもいました","textKo":"이 아이들은 왜 이렇게 웃고 있는 걸까 생각했습니다","words":[],"listenDifficulty":1},{"index":39,"start":295.98,"end":303.08,"textJa":"村の人たちとご飯を食べたり お話ししたりしていたら 村の人があることをやってくれました","reading":"むらのひとたちとごはんをたべたり おはなししたりしていたら むらのひとがあることをやってくれました","textKo":"마을 사람들과 밥을 먹거나 이야기를 나누고 있었더니, 마을 사람이 어떤 것을 해주었습니다","words":[],"listenDifficulty":2},{"index":40,"start":304.58,"end":309.32,"textJa":"私に向けて 歌を歌ってくれたんです","reading":"わたしにむけて うたをうたってくれたんです","textKo":"저를 위해 노래를 불러주었습니다","words":[],"listenDifficulty":1},{"index":41,"start":311.48,"end":318.14,"textJa":"私はその歌を聴いて 大粒の涙が出てきました","reading":"わたしはそのうたをきいて おおつぶのなみだがでてきました","textKo":"저는 그 노래를 듣고 굵은 눈물이 흘러나왔습니다","words":[],"listenDifficulty":1},{"index":42,"start":320.38,"end":327.02,"textJa":"こんなに貧しいのに こんなに豊かな心を持っているんだと感じました","reading":"こんなにまずしいのに こんなにゆたかなこころをもっているんだとかんじました","textKo":"이렇게 가난한데, 이렇게 풍요로운 마음을 가지고 있구나 하고 느꼈습니다","words":[],"listenDifficulty":2},{"index":43,"start":329.34,"end":333.76,"textJa":"そこで私が気づいたことがあります","reading":"そこでわたしがきづいたことがあります","textKo":"거기서 제가 깨달은 것이 있습니다","words":[],"listenDifficulty":1},{"index":44,"start":334.78,"end":342.62,"textJa":"幸せはお金や物で測れるものではない お金がないから不幸だということはないと気づきました","reading":"しあわせはおかねやものではかれるものではない おかねがないからふこうだということはないときづきました","textKo":"행복은 돈이나 물건으로 측정할 수 있는 것이 아니다. 돈이 없다고 불행한 것은 아니라고 깨달았습니다","words":[],"listenDifficulty":1},{"index":45,"start":343.72,"end":350.86,"textJa":"じゃあ 幸せはどこにあるんだろうって 私は次の旅先へと向かいました","reading":"じゃあ しあわせはどこにあるんだろうって わたしはつぎのたびさきへとむかいました","textKo":"그럼 행복은 어디에 있는 걸까 하며 저는 다음 여행지로 향했습니다","words":[],"listenDifficulty":1},{"index":46,"start":353.72,"end":362.64,"textJa":"ある日 サムという名のカンボジア人が日本にやってきました","reading":"あるひ さむというなのかんぼじあじんがにほんにやってきました","textKo":"어느 날, 삼이라는 이름의 캄보디아인이 일본에 왔습니다","words":[],"listenDifficulty":1},{"index":47,"start":364.28,"end":369.4,"textJa":"サムは日本に来てこう言いました","reading":"さむはにほんにきてこういいました","textKo":"삼은 일본에 와서 이렇게 말했습니다","words":[],"listenDifficulty":1},{"index":48,"start":371.84,"end":378.52,"textJa":"日本は物はたくさんあるのに 心が癒される場所がない","reading":"にほんはものはたくさんあるのに こころがいやされるばしょがない","textKo":"일본은 물건은 많이 있는데, 마음이 치유되는 장소가 없다","words":[],"listenDifficulty":2},{"index":49,"start":380.5,"end":386.62,"textJa":"カンボジアには物はないけれど 心が癒される場所がある","reading":"かんぼじあにはものはないけれど こころがいやされるばしょがある","textKo":"캄보디아에는 물건은 없지만, 마음이 치유되는 장소가 있다","words":[],"listenDifficulty":1},{"index":50,"start":388.36,"end":393.08,"textJa":"だから日本はカンボジアよりも幸せじゃないと思う","reading":"だからにほんはかんぼじあよりもしあわせじゃないとおもう","textKo":"그러니까 일본은 캄보디아보다 행복하지 않다고 생각해","words":[],"listenDifficulty":1},{"index":51,"start":395.06,"end":401.8,"textJa":"私はサムの言葉を聞いてハッとしました","reading":"わたしはさむのことばをきいてはっとしました","textKo":"저는 삼의 말을 듣고 번뜩 깨달았습니다","words":[],"listenDifficulty":1},{"index":52,"start":403.54,"end":409.52,"textJa":"お金があっても 心が豊かでなければ 幸せにはなれないんだと","reading":"おかねがあっても こころがゆたかでなければ しあわせにはなれないんだと","textKo":"돈이 있어도, 마음이 풍요롭지 않으면 행복해질 수 없다고","words":[],"listenDifficulty":1},{"index":53,"start":411.94,"end":418.7,"textJa":"日本に帰ってきた私は 社会からたくさんのメッセージを受けとりました","reading":"にほんにかえってきたわたしは しゃかいからたくさんのめっせーじをうけとりました","textKo":"일본에 돌아온 저는 사회로부터 많은 메시지를 받았습니다","words":[],"listenDifficulty":1},{"index":54,"start":420.5,"end":424.9,"textJa":"有名大学を出ないと幸せになれないよ","reading":"ゆうめいだいがくをでないとしあわせになれないよ","textKo":"유명 대학을 나오지 않으면 행복해질 수 없어","words":[],"listenDifficulty":1},{"index":55,"start":426.52,"end":430.94,"textJa":"大企業に就職しないと幸せになれないよ","reading":"だいきぎょうにしゅうしょくしないとしあわせになれないよ","textKo":"대기업에 취직하지 않으면 행복해질 수 없어","words":[],"listenDifficulty":1},{"index":56,"start":432.58,"end":437.12,"textJa":"いい人と結婚しないと幸せになれないよ","reading":"いいひととけっこんしないとしあわせになれないよ","textKo":"좋은 사람과 결혼하지 않으면 행복해질 수 없어","words":[],"listenDifficulty":1},{"index":57,"start":438.56,"end":443.78,"textJa":"マイホームを建てないと幸せになれないよ","reading":"まいほーむをたてないとしあわせになれないよ","textKo":"내 집을 짓지 않으면 행복해질 수 없어","words":[],"listenDifficulty":1},{"index":58,"start":444.7,"end":449.28,"textJa":"子供を産まないと幸せになれないよ","reading":"こどもをうまないとしあわせになれないよ","textKo":"아이를 낳지 않으면 행복해질 수 없어","words":[],"listenDifficulty":1},{"index":59,"start":451.78,"end":458.9,"textJa":"私はこのメッセージを聞くたびに 何かが違う気がするなあと思っていました","reading":"わたしはこのめっせーじをきくたびに なにかがちがうきがするなあとおもっていました","textKo":"저는 이 메시지를 들을 때마다 뭔가 다른 것 같다는 생각을 하고 있었습니다","words":[],"listenDifficulty":1},{"index":60,"start":461.14,"end":465.52,"textJa":"でも周りの目も気になって","reading":"でもまわりのめもきになって","textKo":"하지만 주변의 시선도 신경 쓰여","words":[],"listenDifficulty":1},{"index":61,"start":467.04,"end":473.0,"textJa":"なんとなく社会の言う通りに生きてきていました","reading":"なんとなくしゃかいのいうとおりにいきてきていました","textKo":"왠지 사회가 말하는 대로 살아왔습니다","words":[],"listenDifficulty":1},{"index":62,"start":475.88,"end":481.98,"textJa":"でも 自分の幸せってなんだろう